-- Arrosto di tacchino alle erbe
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd8e4ac12-403d-4d06-97cf-022682d08894'::uuid, null, 'Arrosto di tacchino alle erbe', 'seed', 'https://blog.giallozafferano.it/ricettechepassione/arrosto-di-tacchino/', 'GialloZafferano', '/recipe-photos/arrosto-di-tacchino-alle-erbe.webp', 'https://blog.giallozafferano.it/ricettechepassione/wp-content/uploads/2018/04/arrosto-di-tacchino-perfettoo-oo.jpg',
    2, 4, 140, 15, 110, '["Legare il petto di tacchino con lo spago da cucina.","Massaggiarlo con rosmarino, salvia, origano, curry, sale e pepe.","Scaldare l''olio in un tegame con carota, cipolla, sedano e aglio a pezzi grossi e rosolare la carne su tutti i lati.","Sfumare con il vino bianco.","Cuocere coperto a fuoco basso per circa 45 minuti, oppure in forno a 180 °C coperto con alluminio per circa un''ora.","Lasciar riposare la carne prima di tagliarla a fette.","Frullare le verdure di cottura con un po'' di fondo, scaldare la salsa e servirla con l''arrosto."]'::jsonb,
    array['italian', 'mediterranean', 'oven', 'comfort', 'high protein']::text[], 'italian', 359, 48.5,
    true, 'it', 'medium', '{"pots":1,"oven":false,"special":["blender"]}'::jsonb, false,
    '{"en":{"title":"Herb roast turkey","steps":["Tie the turkey breast with kitchen string.","Rub it with rosemary, sage, oregano, curry powder, salt and pepper.","Heat the oil in a pan with the carrot, onion, celery and garlic cut into large chunks, and brown the meat on all sides.","Deglaze with the white wine.","Cook covered over low heat for about 45 minutes, or in the oven at 180 °C covered with foil for about an hour.","Let the meat rest before slicing it.","Blend the cooked vegetables with a little of the pan juices, heat the sauce and serve it with the roast."]},"fr":{"title":"Rôti de dinde aux herbes","steps":["Ficeler le blanc de dinde avec de la ficelle de cuisine.","Le masser avec le romarin, la sauge, l''origan, le curry, le sel et le poivre.","Faire chauffer l''huile dans une sauteuse avec la carotte, l''oignon, le céleri et l''ail coupés en gros morceaux, puis faire revenir la viande sur toutes ses faces.","Déglacer au vin blanc.","Cuire à couvert à feu doux pendant environ 45 minutes, ou au four à 180 °C, couvert de papier aluminium, pendant environ une heure.","Laisser reposer la viande avant de la couper en tranches.","Mixer les légumes de cuisson avec un peu de jus de cuisson, réchauffer la sauce et la servir avec le rôti."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd8e4ac12-403d-4d06-97cf-022682d08894')
  returning id
)
