-- Coniglio alla ligure con olive taggiasche
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7cb87b97-df20-4ea6-8837-a97aa96c651f'::uuid, null, 'Coniglio alla ligure con olive taggiasche', 'seed', 'https://www.dissapore.com/ricette/coniglio-alla-ligure-la-ricetta-originale-con-olive-taggiasche/', 'Dissapore', '/recipe-photos/coniglio-alla-ligure-con-olive-taggiasche.webp', 'https://images.dissapore.com/wp-content/uploads/2023/02/coniglio-alla-ligure-ricetta.jpg?width=1280&height=720&quality=75',
    2, 4, 110, 20, 90, '["Tagliare il coniglio a pezzi, eliminare grasso, fegato e reni, sciacquarlo e asciugarlo.","Tritare finemente la cipolla e tritare l''aglio senza anima insieme agli aghi di rosmarino.","Scaldare l''olio con il trito e il coniglio e rosolare la carne su tutti i lati a fuoco basso senza bruciare il soffritto.","Sfumare con il vino rosso alzando la fiamma finché l''alcol è evaporato.","Aggiungere alloro, timo, olive e un mestolo di brodo caldo, coprire e cuocere piano, unendo altro brodo solo se serve.","Dopo circa un''ora, quando la carne si stacca dall''osso, scoprire e far restringere il sugo in eccesso."]'::jsonb,
    array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 757, 77.1,
    true, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Ligurian rabbit with Taggiasca olives","steps":["Cut the rabbit into pieces, remove the fat, liver and kidneys, rinse it and pat it dry.","Finely chop the onion, and chop the garlic, germ removed, together with the rosemary needles.","Heat the oil with the chopped aromatics and the rabbit, and brown the meat on all sides over low heat without letting the aromatics burn.","Deglaze with the red wine, raising the heat until the alcohol has evaporated.","Add the bay leaf, thyme, olives and a ladle of hot stock, cover and cook gently, adding more stock only if needed.","After about an hour, when the meat comes away from the bone, uncover and reduce any excess sauce."]},"fr":{"title":"Lapin à la ligure aux olives taggiasche","steps":["Découper le lapin en morceaux, retirer le gras, le foie et les rognons, le rincer et le sécher.","Hacher finement l''oignon, et hacher l''ail dégermé avec les aiguilles de romarin.","Faire chauffer l''huile avec le hachis et le lapin, et faire revenir la viande sur toutes ses faces à feu doux sans brûler les aromates.","Déglacer au vin rouge en augmentant le feu jusqu''à ce que l''alcool soit évaporé.","Ajouter le laurier, le thym, les olives et une louche de bouillon chaud, couvrir et laisser mijoter doucement, en ajoutant du bouillon seulement si nécessaire.","Au bout d''environ une heure, lorsque la viande se détache de l''os, découvrir et faire réduire l''excédent de sauce."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7cb87b97-df20-4ea6-8837-a97aa96c651f')
  returning id
)
