-- Cozze alla tarantina
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '17c37e4b-5dc1-4114-8e36-27664bd290ca'::uuid, null, 'Cozze alla tarantina', 'seed', 'https://www.dissapore.com/ricette/cozze-alla-tarantina-al-sugo', 'Dissapore', '/recipe-photos/cozze-alla-tarantina.webp', 'https://images.dissapore.com/wp-content/uploads/2023/03/cozze-alla-tarantina-ricetta.jpg?width=1280&height=720&quality=75',
    2, 4, 100, 15, 25, '["Tieni le cozze in acqua salata per almeno un''ora, poi strofina i gusci ed elimina il bisso.","In una padella rosola uno spicchio d''aglio schiacciato in metà dell''olio, senza farlo scurire.","Aggiungi le cozze e un rametto di prezzemolo, sfuma con il vino e copri finché si aprono.","Filtra il liquido di cottura con un colino fine e tieni da parte le cozze.","In una padella pulita scalda l''olio rimasto con l''aglio a fettine e il peperoncino spezzettato.","Unisci i pelati schiacciandoli con una forchetta, aggiungi il liquido delle cozze e fai restringere a fuoco basso per circa 10 minuti.","Rimetti le cozze nel sugo con il prezzemolo tritato, lascia insaporire qualche minuto e servi con pane abbrustolito."]'::jsonb,
    array['italian', 'mediterranean', 'stew', 'comfort']::text[], 'italian', 459, 13.4,
    true, 'it', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Taranto-style mussels","steps":["Soak the mussels in salted water for at least an hour, then scrub the shells and pull off the beards.","In a frying pan, gently fry one crushed garlic clove in half the oil without letting it brown.","Add the mussels and a sprig of parsley, deglaze with the wine and cover until they open.","Strain the cooking liquid through a fine sieve and set the mussels aside.","In a clean frying pan, heat the remaining oil with the sliced garlic and the crumbled chilli.","Add the peeled tomatoes, crushing them with a fork, add the mussel liquid and reduce over low heat for about 10 minutes.","Return the mussels to the sauce with the chopped parsley, leave to take on flavour for a few minutes and serve with toasted bread."]},"fr":{"title":"Moules à la mode de Tarente","steps":["Laisser tremper les moules dans de l''eau salée pendant au moins une heure, puis brosser les coquilles et retirer le byssus.","Dans une poêle, faire revenir une gousse d''ail écrasée dans la moitié de l''huile, sans la laisser colorer.","Ajouter les moules et un brin de persil, déglacer au vin et couvrir jusqu''à ce qu''elles s''ouvrent.","Filtrer le jus de cuisson à travers une passoire fine et réserver les moules.","Dans une poêle propre, faire chauffer le reste de l''huile avec l''ail émincé et le piment émietté.","Ajouter les tomates pelées en les écrasant à la fourchette, ajouter le jus des moules et laisser réduire à feu doux pendant environ 10 minutes.","Remettre les moules dans la sauce avec le persil haché, laisser s''imprégner quelques minutes et servir avec du pain grillé."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '17c37e4b-5dc1-4114-8e36-27664bd290ca')
  returning id
)
