-- Frittata di zucchine e ricotta al forno
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bacd2ed3-0463-40f3-bb43-f496642a30b8'::uuid, null, 'Frittata di zucchine e ricotta al forno', 'seed', 'https://blog.giallozafferano.it/cottoinunclick/ricetta-frittata-zucchine-e-ricotta-al-forno/', 'GialloZafferano', '/recipe-photos/frittata-di-zucchine-e-ricotta-al-forno.webp', 'https://blog.giallozafferano.it/cottoinunclick/wp-content/uploads/2025/05/phonto-frittata-zucchine-e-ricotta-al-forno.jpg',
    2, 4, 45, 15, 30, '["Preriscalda il forno a 180 °C statico.","Lava e asciuga le zucchine, spuntale e tagliale a rondelle sottili.","Sbatti le uova in una ciotola, incorpora ricotta e parmigiano, regola di sale e pepe e unisci le zucchine.","Fodera una piccola tortiera con carta forno (leggermente unta o inumidita), versa il composto e livellalo.","Cuoci 30 minuti in modalità statica, poi altri 5 minuti ventilato finché la superficie è dorata.","Sforna, taglia a fette e servi tiepida o fredda."]'::jsonb,
    array['italian', 'oven', 'light', 'vegetarian']::text[], 'italian', 208, 17.1,
    false, 'it', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Baked courgette and ricotta frittata","steps":["Preheat the oven to 180 °C (conventional, no fan).","Wash and dry the courgettes, trim the ends and cut them into thin rounds.","Beat the eggs in a bowl, stir in the ricotta and parmesan, season with salt and pepper and add the courgettes.","Line a small cake tin with baking paper (lightly greased or dampened), pour in the mixture and level it.","Bake for 30 minutes on the conventional setting, then another 5 minutes with the fan until the top is golden.","Remove from the oven, cut into slices and serve warm or cold."]},"fr":{"title":"Frittata courgettes et ricotta au four","steps":["Préchauffer le four à 180 °C en chaleur statique.","Laver et sécher les courgettes, les équeuter et les couper en fines rondelles.","Battre les œufs dans un saladier, incorporer la ricotta et le parmesan, saler, poivrer et ajouter les courgettes.","Chemiser un petit moule à manqué de papier cuisson (légèrement huilé ou humidifié), verser la préparation et la lisser.","Cuire 30 minutes en chaleur statique, puis encore 5 minutes en chaleur tournante jusqu''à ce que le dessus soit doré.","Sortir du four, couper en parts et servir tiède ou froide."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bacd2ed3-0463-40f3-bb43-f496642a30b8')
  returning id
)
