-- Insalata di farro con tonno e ceci
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '27b821b2-edb6-4621-9429-c3073510739c'::uuid, null, 'Insalata di farro con tonno e ceci', 'seed', 'https://blog.giallozafferano.it/studentiaifornelli/insalata-di-farro-tonno-e-ceci/', 'GialloZafferano', '/recipe-photos/insalata-di-farro-con-tonno-e-ceci.webp', 'https://blog.giallozafferano.it/studentiaifornelli/wp-content/uploads/2020/08/ANT-FB-insalata-di-farro-tonno-e-ceci-ricetta-scaled.jpg',
    2, 2, 30, 10, 20, '["Lessa il farro in abbondante acqua salata secondo i tempi della confezione, scolalo e lascialo raffreddare.","Scola e sciacqua i ceci; sgocciola bene il tonno.","Unisci al farro i ceci e il tonno sbriciolato, condisci con olio e un pizzico di sale e mescola.","Taglia in quattro i pomodorini, lava e asciuga la rucola.","Aggiungi pomodorini e rucola al farro, mescola, regola il condimento e servi subito o tieni in frigo fino al momento."]'::jsonb,
    array['italian', 'mediterranean', 'salad', 'light']::text[], 'italian', 531, 31.5,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Farro salad with tuna and chickpeas","steps":["Boil the farro in plenty of salted water for the time given on the packet, drain and leave to cool.","Drain and rinse the chickpeas; drain the tuna well.","Add the chickpeas and flaked tuna to the farro, dress with oil and a pinch of salt and stir.","Quarter the cherry tomatoes; wash and dry the rocket.","Add the cherry tomatoes and rocket to the farro, stir, adjust the seasoning and serve straight away or keep in the fridge until needed."]},"fr":{"title":"Salade d''épeautre au thon et aux pois chiches","steps":["Cuire l''épeautre dans un grand volume d''eau salée selon le temps indiqué sur l''emballage, l''égoutter et le laisser refroidir.","Égoutter et rincer les pois chiches ; bien égoutter le thon.","Ajouter à l''épeautre les pois chiches et le thon émietté, assaisonner avec l''huile et une pincée de sel et mélanger.","Couper les tomates cerises en quatre, laver et sécher la roquette.","Ajouter les tomates cerises et la roquette à l''épeautre, mélanger, rectifier l''assaisonnement et servir aussitôt ou conserver au réfrigérateur jusqu''au moment de servir."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '27b821b2-edb6-4621-9429-c3073510739c')
  returning id
)
