-- Involtini di pollo al forno
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '78ed85bf-8d00-444e-b619-63a462d21934'::uuid, null, 'Involtini di pollo al forno', 'seed', 'https://www.dissapore.com/ricette/involtini-di-pollo-al-forno/', 'Dissapore', '/recipe-photos/involtini-di-pollo-al-forno.webp', 'https://images.dissapore.com/wp-content/uploads/2022/04/shutterstock_1930525085.jpg?width=1280&height=720&quality=50',
    2, 4, 35, 10, 20, '["Stendere le fette di pollo su un tagliere.","Coprire ciascuna con una fettina di fontina e una di prosciutto cotto.","Arrotolarle strette su se stesse.","Sbattere leggermente l''uovo con sale e pepe e passarvi gli involtini.","Rotolarli nel pangrattato e sistemarli su carta forno in una teglia, con un filo d''olio.","Cuocere in forno a 180 °C per 25 minuti."]'::jsonb,
    array['italian', 'oven', 'comfort', 'high protein']::text[], 'italian', 484, 51.5,
    true, 'it', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Baked chicken rolls","steps":["Lay the chicken slices out on a chopping board.","Top each one with a thin slice of fontina and a slice of cooked ham.","Roll them up tightly.","Lightly beat the egg with salt and pepper and dip the rolls in it.","Roll them in the breadcrumbs and arrange them in a baking tray lined with baking paper, with a drizzle of oil.","Bake at 180 °C for 25 minutes."]},"fr":{"title":"Roulés de poulet au four","steps":["Étaler les tranches de poulet sur une planche à découper.","Recouvrir chacune d''une fine tranche de fontina et d''une tranche de jambon blanc.","Les rouler bien serré sur elles-mêmes.","Battre légèrement l''œuf avec du sel et du poivre et y passer les roulés.","Les rouler dans la chapelure et les disposer dans un plat recouvert de papier cuisson, avec un filet d''huile.","Cuire au four à 180 °C pendant 25 minutes."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '78ed85bf-8d00-444e-b619-63a462d21934')
  returning id
)
