-- Medaglioni di filetto di maiale ai funghi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e895582c-375e-49f7-95de-d738448185c2'::uuid, null, 'Medaglioni di filetto di maiale ai funghi', 'seed', 'https://www.dissapore.com/ricette/medaglioni-di-filetto-di-maiale/', 'Dissapore', '/recipe-photos/medaglioni-di-filetto-di-maiale-ai-funghi.webp', 'https://images.dissapore.com/wp-content/uploads/2024/01/Medaglioni-di-filetto-di-maiale-ricetta.jpg?width=1280&height=720&quality=75',
    2, 4, 30, 5, 10, '["Rifilare il filetto da grasso e pellicine, tagliarlo a medaglioni spessi almeno 3 cm e tamponarli con carta da cucina.","Sciogliere il burro chiarificato con la salvia in una padella antiaderente e scottare i medaglioni a fuoco alto circa 2 minuti per lato, salando e pepando leggermente.","Sfumare con il vino bianco e far evaporare l''alcol, poi tenere da parte la carne al caldo.","Nella stessa padella cuocere i funghi affettati sottili con la panna, a fuoco basso e coperto.","Regolare di sale, addensare la salsa con l''amido di mais, rimettere i medaglioni a scaldare e servire."]'::jsonb,
    array['italian', 'fancy', 'comfort', 'high protein']::text[], 'italian', 450, 44,
    true, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pork tenderloin medallions with mushrooms","steps":["Trim the fat and silverskin from the tenderloin, cut it into medallions at least 3 cm thick and pat them dry with kitchen paper.","Melt the clarified butter with the sage in a non-stick frying pan and sear the medallions over high heat for about 2 minutes per side, seasoning lightly with salt and pepper.","Deglaze with the white wine and let the alcohol evaporate, then set the meat aside and keep it warm.","In the same pan, cook the thinly sliced mushrooms with the cream, covered, over low heat.","Season with salt, thicken the sauce with the cornflour, return the medallions to the pan to heat through and serve."]},"fr":{"title":"Médaillons de filet mignon aux champignons","steps":["Parer le filet mignon en retirant le gras et les membranes, le couper en médaillons d''au moins 3 cm d''épaisseur et les éponger avec du papier absorbant.","Faire fondre le beurre clarifié avec la sauge dans une poêle antiadhésive et saisir les médaillons à feu vif environ 2 minutes de chaque côté, en salant et poivrant légèrement.","Déglacer au vin blanc et laisser évaporer l''alcool, puis réserver la viande au chaud.","Dans la même poêle, cuire les champignons finement émincés avec la crème, à couvert et à feu doux.","Saler, épaissir la sauce avec la fécule de maïs, remettre les médaillons à réchauffer et servir."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e895582c-375e-49f7-95de-d738448185c2')
  returning id
)
