-- Merluzzo alla livornese
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5bdecccd-5a1b-46a8-8887-5bdebc040da6'::uuid, null, 'Merluzzo alla livornese', 'seed', 'https://www.dissapore.com/ricette/merluzzo-alla-livornese/', 'Dissapore', '/recipe-photos/merluzzo-alla-livornese.webp', 'https://images.dissapore.com/wp-content/uploads/2022/05/shutterstock_620172806.jpg?width=1280&height=720&quality=75',
    2, 4, 25, 5, 15, '["Sbuccia l''aglio ed elimina l''anima interna.","Fai dorare l''aglio nell''olio senza bruciarlo, poi toglilo dalla padella.","Adagia i filetti di merluzzo e rosolali circa 5 minuti per lato.","Bagna con il vino bianco e lascia evaporare a fiamma alta.","Aggiungi la passata, i capperi sciacquati e le olive, e cuoci finché il sugo si restringe.","Poco prima di spegnere unisci il prezzemolo tritato fine e una macinata di pepe."]'::jsonb,
    array['italian', 'mediterranean', 'stew', 'light', 'quick', 'high protein']::text[], 'italian', 350, 36.9,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Livorno-style cod","steps":["Peel the garlic and remove the green germ.","Fry the garlic in the oil until golden without burning it, then remove it from the pan.","Lay the cod fillets in the pan and brown them for about 5 minutes per side.","Pour in the white wine and let it evaporate over high heat.","Add the passata, the rinsed capers and the olives, and cook until the sauce thickens.","Just before turning off the heat, add the finely chopped parsley and a grind of pepper."]},"fr":{"title":"Cabillaud à la livournaise","steps":["Éplucher l''ail et retirer le germe.","Faire dorer l''ail dans l''huile sans le brûler, puis le retirer de la poêle.","Déposer les filets de cabillaud et les faire dorer environ 5 minutes de chaque côté.","Mouiller avec le vin blanc et laisser évaporer à feu vif.","Ajouter le coulis de tomate, les câpres rincées et les olives, et cuire jusqu''à ce que la sauce réduise.","Juste avant d''éteindre le feu, ajouter le persil finement haché et un tour de moulin à poivre."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5bdecccd-5a1b-46a8-8887-5bdebc040da6')
  returning id
)
