-- Orata al cartoccio
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '686a6848-a856-4bbe-b6f3-f2f4dae462d8'::uuid, null, 'Orata al cartoccio', 'seed', 'https://www.dissapore.com/ricette/orata-al-cartoccio/', 'Dissapore', '/recipe-photos/orata-al-cartoccio.webp', 'https://images.dissapore.com/wp-content/uploads/2021/12/shutterstock_226434073.jpg?width=1280&height=720&quality=75',
    2, 4, 55, 15, 40, '["Preriscalda il forno a 180 °C.","Pulisci l''orata incidendo la pancia, eviscerala, squamala raschiando contro il verso delle squame, poi lavala e asciugala.","Affetta l''aglio, la cipolla, le carote e il limone.","Farcisci la pancia del pesce con alloro, aglio, rosmarino, timo e un pizzico di sale.","Adagia l''orata su un foglio di alluminio con carote, cipolla e limone, condisci con olio, sale e pepe e chiudi bene il cartoccio.","Cuoci in forno per circa 40 minuti.","Apri il cartoccio, elimina erbe e verdure aromatiche e servi con un filo d''olio crudo."]'::jsonb,
    array['italian', 'mediterranean', 'oven', 'light', 'high protein']::text[], 'italian', 321, 45.4,
    true, 'it', 'medium', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Sea bream baked in foil","steps":["Preheat the oven to 180 °C.","Clean the sea bream by slitting open the belly, gut it, scale it by scraping against the direction of the scales, then wash and dry it.","Slice the garlic, onion, carrots and lemon.","Stuff the belly of the fish with the bay leaf, garlic, rosemary, thyme and a pinch of salt.","Lay the sea bream on a sheet of foil with the carrots, onion and lemon, season with oil, salt and pepper and seal the parcel tightly.","Bake for about 40 minutes.","Open the parcel, discard the herbs and aromatic vegetables and serve with a drizzle of fresh olive oil."]},"fr":{"title":"Dorade en papillote","steps":["Préchauffer le four à 180 °C.","Nettoyer la dorade en incisant le ventre, la vider, l''écailler en grattant à rebrousse-écailles, puis la laver et la sécher.","Émincer l''ail, l''oignon, les carottes et le citron.","Farcir le ventre du poisson avec le laurier, l''ail, le romarin, le thym et une pincée de sel.","Déposer la dorade sur une feuille de papier aluminium avec les carottes, l''oignon et le citron, arroser d''huile, saler, poivrer et bien fermer la papillote.","Cuire au four pendant environ 40 minutes.","Ouvrir la papillote, retirer les herbes et les légumes aromatiques et servir avec un filet d''huile d''olive crue."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '686a6848-a856-4bbe-b6f3-f2f4dae462d8')
  returning id
)
