-- Pasta e lenticchie
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5d1e5db1-40e3-4f53-9d61-d92916584684'::uuid, null, 'Pasta e lenticchie', 'seed', 'https://blog.giallozafferano.it/allacciateilgrembiule/pasta-e-lenticchie/', 'GialloZafferano', '/recipe-photos/pasta-e-lenticchie.webp', 'https://blog.giallozafferano.it/allacciateilgrembiule/wp-content/uploads/2017/10/PASTA-E-LENTICCHIEFB.jpg',
    2, 4, 65, 20, 45, '["Se usi lenticchie secche, mettile in ammollo circa 2 ore (accorcia la cottura); se in scatola, sciacquale e basta.","Trita finemente sedano, carota e cipolla.","Scalda l''olio in una pentola e fai soffriggere le verdure con rosmarino e aglio per qualche minuto.","Aggiungi la pancetta e le lenticchie, copri con il brodo caldo e cuoci a fuoco basso: circa 25 minuti se ammollate, 50 se secche non ammollate.","Quando le lenticchie sono tenere, unisci la pasta con altro brodo quanto basta a coprirla e cuoci circa 10 minuti mescolando.","Regola di sale e pepe e servi caldo con un filo d''olio a crudo."]'::jsonb,
    array['italian', 'mediterranean', 'soup', 'comfort', 'one-pot']::text[], 'italian', 663, 26,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pasta with lentils","steps":["If using dried lentils, soak them for about 2 hours (this shortens the cooking time); if using canned, just rinse them.","Finely chop the celery, carrot and onion.","Heat the oil in a pot and gently fry the vegetables with the rosemary and garlic for a few minutes.","Add the pancetta and lentils, cover with the hot stock and cook over low heat: about 25 minutes if soaked, 50 if dried and unsoaked.","When the lentils are tender, add the pasta with just enough extra stock to cover it and cook for about 10 minutes, stirring.","Season with salt and pepper and serve hot with a drizzle of fresh olive oil."]},"fr":{"title":"Pâtes aux lentilles","steps":["Pour des lentilles sèches, les faire tremper environ 2 heures (cela raccourcit la cuisson) ; pour des lentilles en conserve, simplement les rincer.","Hacher finement le céleri, la carotte et l''oignon.","Faire chauffer l''huile dans une casserole et faire revenir les légumes avec le romarin et l''ail pendant quelques minutes.","Ajouter les lardons et les lentilles, couvrir de bouillon chaud et cuire à feu doux : environ 25 minutes si elles ont trempé, 50 si elles sont sèches sans trempage.","Lorsque les lentilles sont tendres, ajouter les pâtes avec juste assez de bouillon pour les couvrir et cuire environ 10 minutes en remuant.","Saler, poivrer et servir chaud avec un filet d''huile d''olive crue."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5d1e5db1-40e3-4f53-9d61-d92916584684')
  returning id
)
