-- Pasta tonno e ceci cremosa
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '17aad271-1907-4d68-b566-8d66d014c39e'::uuid, null, 'Pasta tonno e ceci cremosa', 'seed', 'https://blog.giallozafferano.it/adryincucina/pasta-tonno-e-ceci/', 'GialloZafferano', '/recipe-photos/pasta-tonno-e-ceci-cremosa.webp', 'https://blog.giallozafferano.it/adryincucina/wp-content/uploads/2019/05/pasta-tonno-e-ceci.jpg',
    2, 4, 20, 5, 15, '["Metti a bollire l''acqua salata per la pasta.","In una padella scalda l''olio del tonno insieme all''olio extravergine.","Trita finemente la cipolla e falla appassire nell''olio a fuoco medio.","Unisci i ceci scolati e il tonno sbriciolato; per una salsa più cremosa frulla metà dei ceci con un po'' di acqua.","Cuoci la pasta al dente e scolala tenendo da parte un mestolo di acqua di cottura.","Versa la pasta in padella, aggiungi l''acqua di cottura e manteca qualche istante.","Servi con erba cipollina tritata."]'::jsonb,
    array['italian', 'mediterranean', 'quick', 'comfort']::text[], 'italian', 499, 27,
    true, 'it', 'easy', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, false,
    '{"en":{"title":"Creamy tuna and chickpea pasta","steps":["Bring a pot of salted water to the boil for the pasta.","In a frying pan, heat the oil from the tuna together with the extra virgin olive oil.","Finely chop the onion and soften it in the oil over medium heat.","Add the drained chickpeas and flaked tuna; for a creamier sauce, blend half the chickpeas with a little water.","Cook the pasta al dente and drain it, reserving a ladle of the cooking water.","Tip the pasta into the frying pan, add the cooking water and toss for a few moments until creamy.","Serve with chopped chives."]},"fr":{"title":"Pâtes crémeuses au thon et aux pois chiches","steps":["Porter à ébullition l''eau salée pour les pâtes.","Dans une poêle, faire chauffer l''huile du thon avec l''huile d''olive vierge extra.","Hacher finement l''oignon et le faire suer dans l''huile à feu moyen.","Ajouter les pois chiches égouttés et le thon émietté ; pour une sauce plus crémeuse, mixer la moitié des pois chiches avec un peu d''eau.","Cuire les pâtes al dente et les égoutter en réservant une louche d''eau de cuisson.","Verser les pâtes dans la poêle, ajouter l''eau de cuisson et remuer quelques instants pour lier la sauce.","Servir avec la ciboulette ciselée."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '17aad271-1907-4d68-b566-8d66d014c39e')
  returning id
)
