-- Pesce spada alla siciliana
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '99a3f1c7-6d4d-4439-a8b2-a3e06f9c8a07'::uuid, null, 'Pesce spada alla siciliana', 'seed', 'https://blog.giallozafferano.it/chezbibia/ricetta-pesce-spada-alla-siciliana/', 'GialloZafferano', '/recipe-photos/pesce-spada-alla-siciliana.webp', 'https://blog.giallozafferano.it/chezbibia/wp-content/uploads/2024/08/pesce-spada-alla-siciliana.jpg',
    2, 4, 30, 5, 25, '["Lava e taglia a metà i pomodorini; sbuccia l''aglio e trita il peperoncino se lo usi.","In una padella larga scalda un filo d''olio con aglio, peperoncino, capperi e olive per un paio di minuti.","Unisci i pomodorini con origano, basilico e un pizzico di sale; copri e cuoci 10 minuti.","Adagia le fette di pesce spada sul fondo in un solo strato, copri e cuoci altri 10 minuti.","Scopri, gira il pesce e lascia andare 5 minuti perché il sugo si restringa un po''; servi subito."]'::jsonb,
    array['italian', 'mediterranean', 'light', 'high protein']::text[], 'italian', 351, 36.3,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Sicilian-style swordfish","steps":["Wash and halve the cherry tomatoes; peel the garlic and chop the chilli if using.","In a large frying pan, heat a drizzle of oil with the garlic, chilli, capers and olives for a couple of minutes.","Add the cherry tomatoes with oregano, basil and a pinch of salt; cover and cook for 10 minutes.","Lay the swordfish slices in the pan in a single layer, cover and cook for another 10 minutes.","Uncover, turn the fish and cook for 5 minutes so the sauce reduces a little; serve straight away."]},"fr":{"title":"Espadon à la sicilienne","steps":["Laver les tomates cerises et les couper en deux ; éplucher l''ail et hacher le piment, le cas échéant.","Dans une grande poêle, faire chauffer un filet d''huile avec l''ail, le piment, les câpres et les olives pendant deux minutes environ.","Ajouter les tomates cerises avec l''origan, le basilic et une pincée de sel ; couvrir et cuire 10 minutes.","Déposer les tranches d''espadon au fond de la poêle en une seule couche, couvrir et cuire encore 10 minutes.","Découvrir, retourner le poisson et laisser cuire 5 minutes pour que la sauce réduise un peu ; servir aussitôt."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '99a3f1c7-6d4d-4439-a8b2-a3e06f9c8a07')
  returning id
)
