-- Petto di pollo alla cacciatora
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '61e1e664-8f21-4039-82b4-008367e27c96'::uuid, null, 'Petto di pollo alla cacciatora', 'seed', 'https://www.dissapore.com/ricette/petto-di-pollo-alla-cacciatora/', 'Dissapore', '/recipe-photos/petto-di-pollo-alla-cacciatora.webp', 'https://images.dissapore.com/wp-content/uploads/2022/09/petto-di-pollo-alla-cacciatora.jpg?width=1280&height=720&quality=75',
    2, 4, 45, 15, 30, '["Pulire i funghi e tagliarli a pezzi.","Tagliare il petto di pollo a bocconi piuttosto grandi.","Sbucciare l''aglio togliendo l''anima e affettare lo scalogno.","Scaldare l''olio con aglio e funghi a fuoco basso per circa 10 minuti.","Aggiungere scalogno e pollo, sfumare con il vino e rosolare finché la carne è colorita in modo uniforme.","Unire i pelati schiacciati e le olive, salare e pepare.","Cuocere dolcemente per circa 10 minuti e servire con basilico fresco."]'::jsonb,
    array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 456, 36,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Chicken breast cacciatore","steps":["Clean the mushrooms and cut them into pieces.","Cut the chicken breast into fairly large chunks.","Peel the garlic, removing the germ, and slice the shallot.","Heat the oil with the garlic and mushrooms over low heat for about 10 minutes.","Add the shallot and chicken, deglaze with the wine and brown until the meat is evenly coloured.","Add the crushed peeled tomatoes and the olives, and season with salt and pepper.","Cook gently for about 10 minutes and serve with fresh basil."]},"fr":{"title":"Blanc de poulet à la chasseur","steps":["Nettoyer les champignons et les couper en morceaux.","Couper le blanc de poulet en morceaux assez gros.","Éplucher l''ail en retirant le germe et émincer l''échalote.","Faire chauffer l''huile avec l''ail et les champignons à feu doux pendant environ 10 minutes.","Ajouter l''échalote et le poulet, déglacer au vin et faire revenir jusqu''à ce que la viande soit uniformément dorée.","Ajouter les tomates pelées écrasées et les olives, saler et poivrer.","Laisser mijoter doucement environ 10 minutes et servir avec du basilic frais."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '61e1e664-8f21-4039-82b4-008367e27c96')
  returning id
)
