-- Petto di pollo alla pizzaiola light
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '567369ff-11d7-4696-a56a-38bcb709f826'::uuid, null, 'Petto di pollo alla pizzaiola light', 'seed', 'https://blog.giallozafferano.it/lacucinasottosopra/petto-di-pollo-alla-pizzaiola-light/', 'GialloZafferano', '/recipe-photos/petto-di-pollo-alla-pizzaiola-light.webp', 'https://blog.giallozafferano.it/lacucinasottosopra/wp-content/uploads/2018/09/IMG_5671jpg.jpg',
    2, 2, 30, 10, 20, '["In una padella larga cuocere la polpa di pomodoro con l''aglio schiacciato, sale, pepe e origano a fuoco basso per 10-15 minuti.","Regolare di sale, allungare con mezzo bicchiere d''acqua e cuocere ancora un paio di minuti.","Adagiare le fettine di pollo nel sugo, coprirle di salsa e spolverare con altro origano.","Cuocere a fuoco medio con il coperchio socchiuso per circa 10 minuti, girando la carne a metà cottura.","A fuoco spento aggiungere, se si vuole, un filo d''olio a crudo e servire con il sugo."]'::jsonb,
    array['italian', 'mediterranean', 'one-pot', 'light', 'high protein']::text[], 'italian', 335, 48.6,
    false, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Light chicken pizzaiola","steps":["In a large frying pan, cook the tomato pulp with the crushed garlic, salt, pepper and oregano over low heat for 10-15 minutes.","Adjust the salt, thin with half a glass of water and cook for another couple of minutes.","Lay the chicken slices in the sauce, cover them with sauce and sprinkle with more oregano.","Cook over medium heat with the lid ajar for about 10 minutes, turning the meat halfway through.","Off the heat, add a drizzle of fresh olive oil if you like and serve with the sauce."]},"fr":{"title":"Blanc de poulet à la pizzaiola allégé","steps":["Dans une grande poêle, cuire la pulpe de tomate avec l''ail écrasé, le sel, le poivre et l''origan à feu doux pendant 10-15 minutes.","Rectifier le sel, allonger avec un demi-verre d''eau et cuire encore deux minutes environ.","Déposer les escalopes de poulet dans la sauce, les napper de sauce et saupoudrer d''un peu plus d''origan.","Cuire à feu moyen avec le couvercle entrouvert pendant environ 10 minutes, en retournant la viande à mi-cuisson.","Hors du feu, ajouter si on le souhaite un filet d''huile d''olive crue et servir avec la sauce."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '567369ff-11d7-4696-a56a-38bcb709f826')
  returning id
)
