-- Risotto ai gamberi e arancia
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '99e6987f-43cf-4bb6-a6d2-33eca8e6d6c9'::uuid, null, 'Risotto ai gamberi e arancia', 'seed', 'https://www.ricettedalmondo.it/risotto-ai-gamberi.html', 'Ricette dal Mondo', '/recipe-photos/risotto-ai-gamberi-e-arancia.webp', 'https://www.ricettedalmondo.it/images/foto-ricette/r/30332-risotto-ai-gamberi.jpg',
    2, 4, 30, 10, 20, '["Sguscia i gamberi eliminando testa e carapace.","Rosolali in padella con l''olio e l''aglio finché cambiano colore, poi tienili da parte.","In una casseruola fai appassire lo scalogno tritato nel burro, aggiungi il riso e tostalo 2-3 minuti.","Sfuma con il vino bianco e lascia evaporare.","Porta a cottura aggiungendo il brodo bollente un mestolo alla volta, mescolando spesso (circa 16-18 minuti).","Pochi minuti prima della fine unisci i gamberi e la scorza d''arancia; regola di sale.","Spegni, manteca con il burro freddo, lascia riposare un paio di minuti e servi."]'::jsonb,
    array['italian', 'risotto', 'fancy', 'comfort', 'high protein']::text[], 'italian', 670, 37.7,
    true, 'it', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Prawn and orange risotto","steps":["Peel the prawns, removing the heads and shells.","Fry them in a frying pan with the oil and garlic until they change colour, then set them aside.","In a saucepan, soften the chopped shallot in the butter, add the rice and toast it for 2-3 minutes.","Deglaze with the white wine and let it evaporate.","Cook the rice through, adding the boiling stock one ladle at a time and stirring often (about 16-18 minutes).","A few minutes before the end, add the prawns and orange zest; season with salt.","Turn off the heat, stir in the cold butter until creamy, leave to rest for a couple of minutes and serve."]},"fr":{"title":"Risotto aux crevettes et à l''orange","steps":["Décortiquer les crevettes en retirant la tête et la carapace.","Les faire revenir à la poêle avec l''huile et l''ail jusqu''à ce qu''elles changent de couleur, puis les réserver.","Dans une casserole, faire suer l''échalote hachée dans le beurre, ajouter le riz et le faire nacrer 2-3 minutes.","Déglacer au vin blanc et laisser évaporer.","Poursuivre la cuisson en ajoutant le bouillon bouillant louche par louche, en remuant souvent (environ 16-18 minutes).","Quelques minutes avant la fin, ajouter les crevettes et le zeste d''orange ; saler.","Éteindre le feu, incorporer le beurre froid pour lier le risotto, laisser reposer deux minutes environ et servir."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '99e6987f-43cf-4bb6-a6d2-33eca8e6d6c9')
  returning id
)
