-- Salmone in crosta di pistacchi e mandorle
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '48ebc83a-a38f-414e-9c34-86c41a6e7c2c'::uuid, null, 'Salmone in crosta di pistacchi e mandorle', 'seed', 'https://www.dissapore.com/ricette/ricetta-salmone-in-crosta-di-pistacchi-e-mandorle/', 'Dissapore', '/recipe-photos/salmone-in-crosta-di-pistacchi-e-mandorle.webp', 'https://images.dissapore.com/wp-content/uploads/2020/10/salmone-in-crosta-di-pistacchi-e-mandorle.jpg?width=1280&height=720&quality=50',
    2, 2, 25, 10, 15, '["Preriscalda il forno a 200 °C.","Trita pistacchi e mandorle e mescolali con pangrattato, un pizzico di sale e l''olio fino a ottenere un composto compatto.","Ungi leggermente una pirofila e sistema i tranci di salmone.","Distribuisci la crosta sulla superficie dei tranci premendo bene.","Cuoci in forno per circa 15 minuti, finché la crosta è dorata, e servi."]'::jsonb,
    array['italian', 'oven', 'quick', 'fancy', 'high protein']::text[], 'italian', 572, 36.1,
    false, 'it', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pistachio and almond crusted salmon","steps":["Preheat the oven to 200 °C.","Chop the pistachios and almonds and mix them with the breadcrumbs, a pinch of salt and the oil until you have a firm mixture.","Lightly grease an ovenproof dish and arrange the salmon fillets in it.","Spread the crust over the top of the fillets, pressing down well.","Bake for about 15 minutes, until the crust is golden, and serve."]},"fr":{"title":"Saumon en croûte de pistaches et d''amandes","steps":["Préchauffer le four à 200 °C.","Hacher les pistaches et les amandes et les mélanger avec la chapelure, une pincée de sel et l''huile jusqu''à obtenir une préparation compacte.","Huiler légèrement un plat allant au four et y disposer les pavés de saumon.","Répartir la croûte sur le dessus des pavés en pressant bien.","Cuire au four pendant environ 15 minutes, jusqu''à ce que la croûte soit dorée, et servir."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '48ebc83a-a38f-414e-9c34-86c41a6e7c2c')
  returning id
)
