-- Saltimbocca alla romana
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '620775f7-df12-48a6-acee-5a00dcdfeba6'::uuid, null, 'Saltimbocca alla romana', 'seed', 'https://blog.giallozafferano.it/valeriaciccotti/saltimbocca-alla-romana/', 'GialloZafferano', '/recipe-photos/saltimbocca-alla-romana.webp', 'https://blog.giallozafferano.it/valeriaciccotti/wp-content/uploads/2022/02/SALTIMBOCCA-ALLA-ROMANA.jpg',
    2, 4, 20, 10, 10, '["Togliere grasso e nervetti dalle fettine di vitello e salarle appena, il prosciutto è già sapido.","Passare le fettine nella farina in modo uniforme.","Appoggiare su ognuna una fetta di prosciutto e una foglia di salvia, fermando con uno stuzzicadenti.","Sciogliere il burro in padella e dorare le fettine.","Bagnare con il vino bianco e lasciarlo evaporare del tutto.","Coprire e proseguire la cottura per circa 2 minuti, poi servire subito ben caldi."]'::jsonb,
    array['italian', 'mediterranean', 'quick', 'fancy']::text[], 'italian', 310, 25.2,
    false, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Saltimbocca alla romana","steps":["Trim the fat and sinew from the veal slices and salt them very lightly, as the prosciutto is already salty.","Coat the slices evenly in flour.","Place a slice of prosciutto and a sage leaf on each one, securing them with a cocktail stick.","Melt the butter in a frying pan and brown the slices.","Pour in the white wine and let it evaporate completely.","Cover and continue cooking for about 2 minutes, then serve immediately, piping hot."]},"fr":{"title":"Saltimbocca alla romana","steps":["Retirer le gras et les nerfs des escalopes de veau et les saler à peine, le jambon cru étant déjà salé.","Fariner les escalopes de manière uniforme.","Déposer sur chacune une tranche de jambon cru et une feuille de sauge, et les fixer avec un cure-dent.","Faire fondre le beurre dans une poêle et faire dorer les escalopes.","Mouiller avec le vin blanc et le laisser s''évaporer complètement.","Couvrir et poursuivre la cuisson environ 2 minutes, puis servir aussitôt bien chaud."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '620775f7-df12-48a6-acee-5a00dcdfeba6')
  returning id
)
