-- Scaloppine di pollo al limone
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '015f5e6a-260f-4598-bd56-b3e794d5a80f'::uuid, null, 'Scaloppine di pollo al limone', 'seed', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/scaloppine-di-pollo-al-limone-facili-e-veloci/', 'GialloZafferano', '/recipe-photos/scaloppine-di-pollo-al-limone.webp', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/wp-content/uploads/2019/05/IMG_7363-scaled-e1647363898939.jpg',
    2, 2, 20, 3, 15, '["Infarinare le fettine di pollo su entrambi i lati, scuotendo l''eccesso.","Scaldare un filo d''olio con il pizzico d''aglio in una padella antiaderente.","Rosolare le scaloppine da entrambi i lati finché sono dorate, poi salarle.","Versare il succo di limone e un bicchiere d''acqua e lasciare restringere finché si forma una salsina cremosa.","Incorporare il miele per smorzare l''acidità e girare di nuovo le fettine nel fondo.","Completare con scorza di limone grattugiata e pepe macinato, far riposare un attimo e servire con prezzemolo e il sughetto."]'::jsonb,
    array['italian', 'mediterranean', 'quick', 'light', 'high protein']::text[], 'italian', 433, 57.8,
    true, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Lemon chicken escalopes","steps":["Dust the chicken slices with flour on both sides, shaking off the excess.","Heat a drizzle of oil with the pinch of garlic powder in a non-stick frying pan.","Brown the escalopes on both sides until golden, then season with salt.","Pour in the lemon juice and a glass of water and let it reduce until a creamy sauce forms.","Stir in the honey to soften the acidity and turn the slices again in the pan juices.","Finish with grated lemon zest and ground pepper, leave to rest for a moment and serve with parsley and the sauce."]},"fr":{"title":"Escalopes de poulet au citron","steps":["Fariner les escalopes de poulet des deux côtés en secouant l''excédent.","Faire chauffer un filet d''huile avec la pincée d''ail en poudre dans une poêle antiadhésive.","Faire dorer les escalopes des deux côtés, puis les saler.","Verser le jus de citron et un verre d''eau et laisser réduire jusqu''à obtenir une petite sauce onctueuse.","Incorporer le miel pour adoucir l''acidité et retourner de nouveau les escalopes dans le jus.","Terminer avec le zeste de citron râpé et du poivre moulu, laisser reposer un instant et servir avec le persil et la sauce."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '015f5e6a-260f-4598-bd56-b3e794d5a80f')
  returning id
)
