-- Sovracoscia di tacchino al limone in padella
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '60fe0e85-846c-4255-941b-f36927ddbfb8'::uuid, null, 'Sovracoscia di tacchino al limone in padella', 'seed', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/sovracoscia-di-tacchino-in-padella/', 'GialloZafferano', '/recipe-photos/sovracoscia-di-tacchino-al-limone-in-padella.webp', 'https://blog.giallozafferano.it/ilcaldosaporedelsud/wp-content/uploads/2025/03/IMG_0822.jpg',
    2, 4, 75, 5, 60, '["Eliminare eventuali penne residue e, se si vuole, disossare la sovracoscia con un coltello.","Scaldare l''olio in padella e adagiare la carne con fette e succo di limone, sale, pepe, rosmarino e alloro.","Rosolare a fiamma vivace finché è dorata, poi girarla e dorare l''altro lato.","Sfumare con il vino bianco e far evaporare l''alcol.","Coprire, abbassare al minimo e cuocere circa un''ora, senza aggiungere acqua.","Alzare la fiamma per ridurre i liquidi e caramellare la carne nel suo fondo, girandola.","Lasciar riposare coperto 5-10 minuti prima di servire."]'::jsonb,
    array['italian', 'mediterranean', 'one-pot', 'comfort', 'high protein']::text[], 'italian', 390, 44.2,
    false, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pan-cooked lemon turkey thigh","steps":["Remove any remaining feathers and, if you like, bone the thigh with a knife.","Heat the oil in a frying pan and add the meat with the lemon slices and juice, salt, pepper, rosemary and bay leaves.","Brown over high heat until golden, then turn it and brown the other side.","Deglaze with the white wine and let the alcohol evaporate.","Cover, turn the heat down to the minimum and cook for about an hour, without adding water.","Raise the heat to reduce the liquid and caramelise the meat in its juices, turning it.","Leave to rest, covered, for 5-10 minutes before serving."]},"fr":{"title":"Haut de cuisse de dinde au citron à la poêle","steps":["Retirer les éventuelles plumes restantes et, si on le souhaite, désosser le haut de cuisse au couteau.","Faire chauffer l''huile dans une poêle et y déposer la viande avec les tranches et le jus de citron, le sel, le poivre, le romarin et le laurier.","Faire dorer à feu vif, puis la retourner et faire dorer l''autre face.","Déglacer au vin blanc et laisser évaporer l''alcool.","Couvrir, baisser le feu au minimum et cuire environ une heure, sans ajouter d''eau.","Monter le feu pour faire réduire les liquides et caraméliser la viande dans son jus, en la retournant.","Laisser reposer à couvert 5-10 minutes avant de servir."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '60fe0e85-846c-4255-941b-f36927ddbfb8')
  returning id
)
