-- Spezzatino di vitello con patate
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '10e1f9f4-df57-4d78-9f93-c707704a3740'::uuid, null, 'Spezzatino di vitello con patate', 'seed', 'https://www.dissapore.com/ricette/spezzatino-di-vitello-con-patate/', 'Dissapore', '/recipe-photos/spezzatino-di-vitello-con-patate.webp', 'https://images.dissapore.com/wp-content/uploads/2021/11/spezzatino-di-vitello-con-patate-ricetta-1.jpg?width=1280&height=720&quality=50',
    2, 5, 125, 15, 80, '["Pelare carota e cipolla, pulire il sedano e tagliare tutto a pezzi grossolani.","Scaldare l''olio e far appassire le verdure con le erbe aromatiche a fiamma bassa per 20-25 minuti, senza acqua.","Tagliare il vitello a cubi di 3-5 cm, eliminando grasso e cartilagini.","Unire la carne al soffritto e mescolare finché cambia colore su tutti i lati.","Sfumare con il vino rosso a fiamma alta finché evapora del tutto.","Versare il brodo caldo e cuocere a fiamma bassissima per circa un''ora, coprendo se il liquido cala troppo.","Pelare le patate, tagliarle a pezzi di almeno 4 cm e aggiungerle allo spezzatino.","Cuocere ancora circa 20 minuti, finché le patate sono tenere e il sugo è denso."]'::jsonb,
    array['italian', 'mediterranean', 'stew', 'comfort', 'high protein']::text[], 'italian', 624, 48.3,
    true, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Veal stew with potatoes","steps":["Peel the carrot and onion, trim the celery and cut everything into rough chunks.","Heat the oil and gently soften the vegetables with the herbs over low heat for 20-25 minutes, without water.","Cut the veal into 3-5 cm cubes, removing fat and gristle.","Add the meat to the softened vegetables and stir until it changes colour on all sides.","Deglaze with the red wine over high heat until it has completely evaporated.","Pour in the hot stock and cook over very low heat for about an hour, covering if the liquid reduces too much.","Peel the potatoes, cut them into pieces of at least 4 cm and add them to the stew.","Cook for about 20 more minutes, until the potatoes are tender and the sauce is thick."]},"fr":{"title":"Sauté de veau aux pommes de terre","steps":["Éplucher la carotte et l''oignon, nettoyer le céleri et couper le tout en gros morceaux.","Faire chauffer l''huile et faire suer les légumes avec les herbes aromatiques à feu doux pendant 20-25 minutes, sans eau.","Couper le veau en cubes de 3-5 cm, en retirant le gras et les cartilages.","Ajouter la viande aux légumes et remuer jusqu''à ce qu''elle change de couleur sur toutes les faces.","Déglacer au vin rouge à feu vif jusqu''à complète évaporation.","Verser le bouillon chaud et cuire à feu très doux pendant environ une heure, en couvrant si le liquide réduit trop.","Éplucher les pommes de terre, les couper en morceaux d''au moins 4 cm et les ajouter au sauté.","Poursuivre la cuisson environ 20 minutes, jusqu''à ce que les pommes de terre soient tendres et la sauce épaisse."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '10e1f9f4-df57-4d78-9f93-c707704a3740')
  returning id
)
insert into public.recipe_ingredients (id, recipe_id, position, name, quantity, unit, aisle, is_staple, guessed, raw_text, original_text, optional)
