-- Straccetti di manzo con rucola e pomodorini
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e602a672-019f-4399-a580-26a8268d9a62'::uuid, null, 'Straccetti di manzo con rucola e pomodorini', 'seed', 'https://blog.giallozafferano.it/renatabriano/ricetta-straccetti-di-manzo-con-rucola-pomodorini-e-aceto-balsamico/', 'GialloZafferano', '/recipe-photos/straccetti-di-manzo-con-rucola-e-pomodorini.webp', 'https://blog.giallozafferano.it/renatabriano/wp-content/uploads/2022/08/straccetti-di-manzo-rucola-scaled.jpg',
    2, 4, 20, 10, 7, '["Lavare e asciugare la rucola; lavare i pomodorini e tagliarli a metà.","Battere le fettine di manzo per assottigliarle, ridurle a strisce e passarle velocemente nella farina setacciata.","Scaldare l''olio con l''aglio in una padella antiaderente e far dorare gli straccetti a fuoco vivo per 2-3 minuti.","Salare e pepare, unire i pomodorini e saltare per circa un minuto.","Aggiungere metà della rucola, mescolare ancora un minuto e spegnere.","Impiattare su un letto di rucola e pomodorini crudi, adagiare la carne sopra e finire con un filo d''olio e aceto balsamico."]'::jsonb,
    array['italian', 'mediterranean', 'stir-fry', 'light', 'quick']::text[], 'italian', 396, 33.8,
    true, 'it', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Beef strips with rocket and cherry tomatoes","steps":["Wash and dry the rocket; wash the cherry tomatoes and halve them.","Pound the beef slices to thin them, cut them into strips and quickly dredge them in the sifted flour.","Heat the oil with the garlic in a non-stick frying pan and brown the beef strips over high heat for 2-3 minutes.","Season with salt and pepper, add the cherry tomatoes and toss for about a minute.","Add half the rocket, stir for one more minute and turn off the heat.","Plate on a bed of raw rocket and cherry tomatoes, lay the meat on top and finish with a drizzle of oil and balsamic vinegar."]},"fr":{"title":"Émincé de bœuf à la roquette et aux tomates cerises","steps":["Laver et sécher la roquette ; laver les tomates cerises et les couper en deux.","Aplatir les tranches de bœuf pour les affiner, les tailler en lanières et les passer rapidement dans la farine tamisée.","Faire chauffer l''huile avec l''ail dans une poêle antiadhésive et faire dorer les lanières de bœuf à feu vif pendant 2-3 minutes.","Saler et poivrer, ajouter les tomates cerises et faire sauter environ une minute.","Ajouter la moitié de la roquette, mélanger encore une minute et éteindre le feu.","Dresser sur un lit de roquette et de tomates cerises crues, déposer la viande dessus et terminer par un filet d''huile et de vinaigre balsamique."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e602a672-019f-4399-a580-26a8268d9a62')
  returning id
)
