-- Straccetti di manzo con verdure
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4147d3f8-71f3-493a-987d-035d634235c5'::uuid, null, 'Straccetti di manzo con verdure', 'seed', 'https://blog.giallozafferano.it/pelledipollo/ricetta-straccetti-di-manzo-con-verdure/', 'GialloZafferano', '/recipe-photos/straccetti-di-manzo-con-verdure.webp', 'https://blog.giallozafferano.it/pelledipollo/wp-content/uploads/2026/04/stracc_manzo_verdure1.jpg',
    2, 2, 40, 15, 15, '["Tagliare la carne a striscioline e marinarla circa 15 minuti con salsa di soia, un filo d''olio, zenzero, aglio schiacciato e amido di mais.","Ridurre carota e zucchine a bastoncini e il cipollotto a rondelle.","Saltare le verdure in padella con poco olio e un pizzico di sale a fuoco vivace per pochi minuti, lasciandole croccanti.","In un''altra padella con un filo d''olio rosolare gli straccetti per un paio di minuti, mescolando sempre.","Riunire carne e verdure, aggiungere i semi di sesamo e saltare a fuoco alto per 1-2 minuti; servire subito."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'light']::text[], 'chinese', 388, 32.4,
    true, 'it', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Beef strips with vegetables","steps":["Cut the meat into thin strips and marinate for about 15 minutes with the soy sauce, a drizzle of oil, the ginger, crushed garlic and cornflour.","Cut the carrot and courgettes into sticks and the spring onion into rounds.","Stir-fry the vegetables in a frying pan with a little oil and a pinch of salt over high heat for a few minutes, keeping them crunchy.","In another frying pan with a drizzle of oil, brown the beef strips for a couple of minutes, stirring constantly.","Combine the meat and vegetables, add the sesame seeds and stir-fry over high heat for 1-2 minutes; serve immediately."]},"fr":{"title":"Émincé de bœuf aux légumes","steps":["Tailler la viande en fines lanières et la faire mariner environ 15 minutes avec la sauce soja, un filet d''huile, le gingembre, l''ail écrasé et la fécule de maïs.","Tailler la carotte et les courgettes en bâtonnets et l''oignon nouveau en rondelles.","Faire sauter les légumes à la poêle avec un peu d''huile et une pincée de sel à feu vif pendant quelques minutes, en les gardant croquants.","Dans une autre poêle avec un filet d''huile, faire revenir les lanières de bœuf pendant deux minutes environ, en remuant sans cesse.","Réunir la viande et les légumes, ajouter les graines de sésame et faire sauter à feu vif 1-2 minutes ; servir aussitôt."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4147d3f8-71f3-493a-987d-035d634235c5')
  returning id
)
