-- Tagliata di manzo con rucola e parmigiano
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6293ce0d-a630-48c6-b558-37f7a09ff101'::uuid, null, 'Tagliata di manzo con rucola e parmigiano', 'seed', 'https://www.dissapore.com/ricette/tagliata-di-manzo/', 'Dissapore', '/recipe-photos/tagliata-di-manzo-con-rucola-e-parmigiano.webp', 'https://images.dissapore.com/wp-content/uploads/2022/10/tagliata-di-manzo.jpg?width=1280&height=720&quality=50',
    2, 4, 75, 10, 10, '["Tirare fuori la carne dal frigo un''ora prima per portarla a temperatura ambiente.","Scaldare bene la griglia e cospargerla di sale grosso.","Cuocere il controfiletto 3 minuti per lato.","Lasciarlo riposare un minuto su un tagliere, poi affettarlo a circa mezzo centimetro e pepare.","Lavare e asciugare la rucola, togliendo i gambi lunghi.","Disporre rucola e fette di carne nel piatto, completare con scaglie di parmigiano e un filo d''olio."]'::jsonb,
    array['italian', 'mediterranean', 'grill', 'light', 'fancy', 'high protein']::text[], 'italian', 512, 47.4,
    false, 'it', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Beef tagliata with rocket and Parmesan","steps":["Take the meat out of the fridge an hour beforehand to bring it to room temperature.","Heat the grill pan well and sprinkle it with coarse salt.","Cook the sirloin for 3 minutes per side.","Let it rest for a minute on a chopping board, then slice it about half a centimetre thick and season with pepper.","Wash and dry the rocket, removing the long stems.","Arrange the rocket and beef slices on the plate, finish with Parmesan shavings and a drizzle of oil."]},"fr":{"title":"Tagliata de bœuf, roquette et parmesan","steps":["Sortir la viande du réfrigérateur une heure avant pour la mettre à température ambiante.","Bien faire chauffer le gril et le parsemer de gros sel.","Cuire le faux-filet 3 minutes de chaque côté.","Le laisser reposer une minute sur une planche, puis le trancher à environ un demi-centimètre d''épaisseur et poivrer.","Laver et sécher la roquette en retirant les longues tiges.","Disposer la roquette et les tranches de viande dans l''assiette, terminer avec des copeaux de parmesan et un filet d''huile."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6293ce0d-a630-48c6-b558-37f7a09ff101')
  returning id
)
