-- Blanc de poulet à la basquaise
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'eed99dab-45c0-4360-afbb-73c4b4ebc594'::uuid, null, 'Blanc de poulet à la basquaise', 'seed', 'https://www.evous.fr/recettes-de-cuisine/Recettes-Plat/Recette-Blanc-de-poulet-a-la,1116941/', 'Evous', null, 'https://www.evous.fr/IMG/jpg/poulet_basquaise-675ed.jpg',
    2, 4, 45, 15, 30, '["Ouvrir chaque blanc de poulet en deux dans l''épaisseur pour obtenir de fines escalopes.","Émincer l''oignon et l''ail, épépiner le poivron et le tailler en fines lanières.","Monder la tomate 30 s dans l''eau bouillante, la peler et la concasser ; couper le jambon en lanières.","Saisir oignon, ail et poivron dans l''huile à feu vif environ 8 min, puis les réserver.","Dans la même poêle, dorer les escalopes quelques minutes de chaque côté.","Remettre les légumes, ajouter jambon, tomate et piment d''Espelette, saler, poivrer et mélanger délicatement.","Verser le vin blanc et le faire réduire à gros bouillons 3 min.","Baisser le feu et laisser mijoter environ 15 min en remuant souvent."]'::jsonb,
    array['french', 'stew', 'light', 'high protein']::text[], 'french', 412, 37.1,
    false, 'fr', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Basque-style chicken breast","steps":["Slice each chicken breast in half horizontally to make thin escalopes.","Thinly slice the onion and garlic, deseed the pepper and cut it into thin strips.","Blanch the tomato in boiling water for 30 s, peel it and chop it roughly; cut the ham into strips.","Sear the onion, garlic and pepper in the oil over high heat for about 8 min, then set aside.","In the same frying pan, brown the escalopes for a few minutes on each side.","Return the vegetables, add the ham, tomato and Espelette pepper, season with salt and pepper and stir gently.","Pour in the white wine and reduce at a rolling boil for 3 min.","Lower the heat and simmer for about 15 min, stirring often."]},"it":{"title":"Petto di pollo alla basca","steps":["Aprire ogni petto di pollo a metà nello spessore per ottenere delle fettine sottili.","Affettare la cipolla e l''aglio, eliminare i semi dal peperone e tagliarlo a listarelle sottili.","Sbollentare il pomodoro 30 s in acqua bollente, pelarlo e tagliarlo a pezzetti; tagliare il prosciutto a listarelle.","Saltare cipolla, aglio e peperone nell''olio a fuoco vivo per circa 8 min, poi tenerli da parte.","Nella stessa padella, dorare le fettine per qualche minuto per lato.","Rimettere le verdure, aggiungere prosciutto, pomodoro e peperoncino di Espelette, salare, pepare e mescolare delicatamente.","Versare il vino bianco e farlo ridurre a fuoco vivace per 3 min.","Abbassare la fiamma e cuocere a fuoco lento per circa 15 min, mescolando spesso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'eed99dab-45c0-4360-afbb-73c4b4ebc594')
  returning id
)
