-- Blanquette de veau légère
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f57e24d7-670a-41d7-89de-13783e359454'::uuid, null, 'Blanquette de veau légère', 'seed', 'https://www.750g.com/blanquette-de-veau-version-light-r32377.htm', '750g', '/recipe-photos/blanquette-de-veau-legere.webp', 'https://static.750g.com/images/1200-630/6efbcb2a37e754e7afaddb1888ac0799/blanquette-de-veau-version-light.png',
    2, 2, 55, 15, 40, '["Porter une cocotte d''eau à ébullition ; pendant ce temps, éplucher et émincer oignon, échalote et carottes.","Plonger la viande et les légumes dans l''eau bouillante avec le thym, saler, poivrer, couvrir et cuire 30 min.","Égoutter le tout, le remettre dans la cocotte avec les champignons égouttés et faire revenir brièvement.","Incorporer la crème et le jus de citron en mélangeant bien jusqu''à ce que la sauce nappe.","Servir aussitôt, par exemple avec des haricots verts."]'::jsonb,
    array['french', 'stew', 'light', 'comfort', 'high protein']::text[], 'french', 448, 55.8,
    true, 'fr', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Light veal blanquette","steps":["Bring a casserole of water to the boil; meanwhile, peel and slice the onion, shallot and carrots.","Add the meat and vegetables to the boiling water with the thyme, season with salt and pepper, cover and cook for 30 min.","Drain everything, return it to the casserole with the drained mushrooms and sauté briefly.","Stir in the cream and lemon juice, mixing well until the sauce is thick enough to coat.","Serve immediately, for example with green beans."]},"it":{"title":"Blanquette di vitello leggera","steps":["Portare a ebollizione una casseruola d''acqua; nel frattempo, pelare e affettare cipolla, scalogno e carote.","Immergere la carne e le verdure nell''acqua bollente con il timo, salare, pepare, coprire e cuocere per 30 min.","Scolare il tutto, rimetterlo nella casseruola con i funghi sgocciolati e farlo saltare brevemente.","Incorporare la panna e il succo di limone mescolando bene, finché la salsa risulta abbastanza densa da velare.","Servire subito, per esempio con fagiolini."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f57e24d7-670a-41d7-89de-13783e359454')
  returning id
)
