-- Blanquette de veau one pot
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '449a378d-34ee-45e9-b50d-4fd3ee78ab88'::uuid, null, 'Blanquette de veau one pot', 'seed', 'https://www.croq-kilos.com/actus/recette-de-one-pot-blanquette', 'Croq''Kilos', '/recipe-photos/blanquette-de-veau-one-pot.webp', 'https://www.croq-kilos.com/sites/default/files/styles/1920px/public/2026-01/40698-one-pot-facon-blanquettejpg.jpg',
    2, 4, 110, 20, 90, '["Couper le veau en gros morceaux, les carottes en rondelles, les champignons en quartiers ; hacher oignon et ail, et éplucher puis couper la pomme de terre en dés.","Dans une grande cocotte, saisir rapidement le veau dans l''huile sans trop le colorer.","Ajouter oignon et ail, saupoudrer de farine et remuer 1 min.","Ajouter carottes, champignons, pomme de terre, thym et laurier, verser le bouillon chaud, saler légèrement, poivrer et mélanger.","Couvrir et cuire à feu doux 1 h 15 à 1 h 30 en remuant de temps en temps, jusqu''à ce que la viande soit fondante.","Hors du feu, fouetter la crème avec le jaune d''œuf et le jus de citron, puis l''incorporer doucement sans refaire bouillir.","Parsemer de persil et servir."]'::jsonb,
    array['french', 'one-pot', 'stew', 'comfort', 'high protein']::text[], 'french', 637, 51.7,
    true, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"One-pot veal blanquette","steps":["Cut the veal into large pieces, the carrots into rounds and the mushrooms into quarters; chop the onion and garlic, and peel and dice the potato.","In a large casserole, quickly sear the veal in the oil without browning it too much.","Add the onion and garlic, sprinkle with the flour and stir for 1 min.","Add the carrots, mushrooms, potato, thyme and bay leaf, pour in the hot stock, season lightly with salt, add pepper and stir.","Cover and cook over low heat for 1 h 15 to 1 h 30, stirring from time to time, until the meat is meltingly tender.","Off the heat, whisk the cream with the egg yolk and lemon juice, then stir it in gently without letting it boil again.","Sprinkle with parsley and serve."]},"it":{"title":"Blanquette di vitello one pot","steps":["Tagliare il vitello a pezzi grossi, le carote a rondelle e i funghi in quarti; tritare cipolla e aglio, pelare la patata e tagliarla a dadini.","In una casseruola capiente, rosolare velocemente il vitello nell''olio senza farlo colorire troppo.","Aggiungere cipolla e aglio, spolverizzare con la farina e mescolare per 1 min.","Aggiungere carote, funghi, patata, timo e alloro, versare il brodo caldo, salare leggermente, pepare e mescolare.","Coprire e cuocere a fuoco basso da 1 h 15 a 1 h 30, mescolando di tanto in tanto, finché la carne è tenerissima.","Fuori dal fuoco, sbattere la panna con il tuorlo e il succo di limone, poi incorporarla delicatamente senza far riprendere il bollore.","Cospargere di prezzemolo e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '449a378d-34ee-45e9-b50d-4fd3ee78ab88')
  returning id
)
