-- Brandade de morue légère
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '50ecea78-6439-45fa-8702-4656b35e676d'::uuid, null, 'Brandade de morue légère', 'seed', 'https://www.croq-kilos.com/actus/recette-de-brandade-de-morue-leger', 'Croq''Kilos', '/recipe-photos/brandade-de-morue-legere.webp', 'https://www.croq-kilos.com/sites/default/files/styles/1920px/public/2025-03/23708-2937-comment-faire-une-brandade-de-morue-legere.jpg',
    2, 4, 1485, 20, 40, '["La veille, rincer la morue et la laisser dessaler 24 h au réfrigérateur dans de l''eau froide, en renouvelant l''eau 3 à 4 fois.","Éplucher et couper les pommes de terre, puis les cuire à l''eau bouillante jusqu''à ce qu''elles soient tendres.","Mettre la morue et l''ail écrasé dans de l''eau froide et pocher 8 à 10 minutes à petits frémissements, sans bouillir.","Égoutter la morue, ôter peau et arêtes, puis l''effilocher finement.","Écraser les pommes de terre en ajoutant le lait tiède petit à petit, puis incorporer le yaourt ou le skyr.","Mélanger la morue à la purée en versant l''huile d''olive en filet, puis poivrer et ajouter un peu de muscade.","Réchauffer à feu doux ou 10 minutes au four à 180 °C, puis servir parsemé de persil."]'::jsonb,
    array['french', 'oven', 'comfort', 'make ahead', 'high protein']::text[], 'french', 364, 39.8,
    true, 'fr', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Light salt cod brandade","steps":["The day before, rinse the salt cod and leave it to desalt for 24 h in the fridge in cold water, changing the water 3 to 4 times.","Peel and cut the potatoes, then cook them in boiling water until tender.","Put the cod and crushed garlic in cold water and poach for 8 to 10 minutes at a gentle simmer, without boiling.","Drain the cod, remove the skin and bones, then flake it finely.","Mash the potatoes, adding the warm milk little by little, then stir in the yoghurt or skyr.","Mix the cod into the mash while drizzling in the olive oil, then season with pepper and add a little nutmeg.","Reheat over low heat or for 10 minutes in the oven at 180 °C, then serve sprinkled with parsley."]},"it":{"title":"Brandade di baccalà leggera","steps":["Il giorno prima, sciacquare il baccalà e lasciarlo dissalare 24 h in frigorifero in acqua fredda, cambiando l''acqua 3 o 4 volte.","Pelare e tagliare le patate, poi lessarle in acqua bollente finché sono tenere.","Mettere il baccalà e l''aglio schiacciato in acqua fredda e cuocerlo da 8 a 10 minuti a fuoco dolcissimo, appena sobbollente, senza farlo bollire.","Scolare il baccalà, eliminare pelle e spine, poi sfilacciarlo finemente.","Schiacciare le patate aggiungendo poco alla volta il latte tiepido, poi incorporare lo yogurt o lo skyr.","Mescolare il baccalà al purè versando l''olio d''oliva a filo, poi pepare e aggiungere un po'' di noce moscata.","Scaldare a fuoco basso o per 10 minuti in forno a 180 °C, poi servire cosparso di prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '50ecea78-6439-45fa-8702-4656b35e676d')
  returning id
)
