-- Cabillaud épicé au four et ses légumes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '589fb2e8-d8cb-4568-93b3-16cca96d832b'::uuid, null, 'Cabillaud épicé au four et ses légumes', 'seed', 'https://www.demotivateur.fr/food/cabillaud-epice-au-four-43138', 'Demotivateur Food', '/recipe-photos/cabillaud-epice-au-four-et-ses-legumes.webp', 'https://www.demotivateur.fr/images-buzz/cover/181198235267d06a38b7603_cabillaud-epices-au-four.jpg',
    2, 6, 55, 15, 40, '["Préchauffer le four à 200 °C.","Couper pommes de terre et courgettes en rondelles, l''oignon en dés et le poivron en lanières.","Mélanger ces légumes avec les tomates cerises, l''huile d''olive, le jus de citron, les gousses d''ail pelées et un peu de sel.","Étaler le tout dans un grand plat et rôtir 25 minutes.","Pendant ce temps, mélanger l''huile, le jus de citron, le paprika, le curcuma et le piment d''Espelette, puis en badigeonner les morceaux de cabillaud.","Poser le poisson sur les légumes et prolonger la cuisson de 15 minutes.","Servir parsemé de persil haché, avec des quartiers de citron."]'::jsonb,
    array['french', 'oven']::text[], 'french', 448, 29.2,
    true, 'fr', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Spiced baked cod with vegetables","steps":["Preheat the oven to 200 °C.","Slice the potatoes and courgettes into rounds, dice the onion and cut the pepper into strips.","Mix these vegetables with the cherry tomatoes, olive oil, lemon juice, peeled garlic cloves and a little salt.","Spread everything out in a large dish and roast for 25 minutes.","Meanwhile, mix the oil, lemon juice, paprika, turmeric and Espelette pepper, then brush it over the cod pieces.","Place the fish on the vegetables and cook for a further 15 minutes.","Serve sprinkled with chopped parsley, with lemon wedges."]},"it":{"title":"Merluzzo speziato al forno con verdure","steps":["Preriscaldare il forno a 200 °C.","Tagliare patate e zucchine a rondelle, la cipolla a dadini e il peperone a listarelle.","Mescolare queste verdure con i pomodorini, l''olio d''oliva, il succo di limone, gli spicchi d''aglio pelati e un po'' di sale.","Distribuire il tutto in una teglia grande e arrostire in forno per 25 minuti.","Nel frattempo, mescolare l''olio, il succo di limone, la paprika, la curcuma e il peperoncino di Espelette, poi spennellarne i pezzi di merluzzo.","Adagiare il pesce sulle verdure e proseguire la cottura per 15 minuti.","Servire cosparso di prezzemolo tritato, con spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '589fb2e8-d8cb-4568-93b3-16cca96d832b')
  returning id
)
