-- Dos de cabillaud à la basquaise
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c4df5fda-28c9-43a2-96e7-7e5561d1ce17'::uuid, null, 'Dos de cabillaud à la basquaise', 'seed', 'https://www.weightwatchers.com/fr/recette/dos-de-cabillaud-a-la-basquaise/5625ac93b7878c0b34e6abdf', 'WW', '/recipe-photos/dos-de-cabillaud-a-la-basquaise.webp', 'https://v.cdn.ww.com/media/system/wine/57f2fa60dce32ff313afe3be/9dbfa72d-7d8b-447f-9afe-61d84ce8da59/srhiwo05o7yvqnwkidit.jpg?fit=crop&height=800&width=800&enable=upscale&quality=80',
    2, 4, 35, 15, 20, '["Préchauffer le four à 210 °C. Plonger les tomates 30 secondes dans l''eau bouillante pour les peler facilement.","Épépiner les tomates et les couper en dés ; couper le poivron en cubes, émincer l''oignon et hacher l''ail.","Mettre les légumes dans une sauteuse avec un petit verre d''eau, le piment et le bouquet garni, couvrir et laisser compoter à feu doux.","Saler, poivrer, puis retirer le piment et le bouquet garni.","Cuire le riz environ 20 minutes à l''eau bouillante salée, l''égoutter et le garder au chaud.","Étaler la compotée de légumes dans un plat à gratin, poser les morceaux de cabillaud dessus, saler, poivrer et enfourner 10 minutes.","Servir le poisson et sa basquaise avec le riz."]'::jsonb,
    array['french', 'oven', 'light']::text[], 'french', 260, 26,
    false, 'fr', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Basque-style cod loin","steps":["Preheat the oven to 210 °C. Plunge the tomatoes into boiling water for 30 seconds so they peel easily.","Deseed the tomatoes and dice them; cut the pepper into cubes, thinly slice the onion and chop the garlic.","Put the vegetables in a sauté pan with a small glass of water, the chilli and the bouquet garni, cover and leave to stew gently over low heat.","Season with salt and pepper, then remove the chilli and the bouquet garni.","Cook the rice for about 20 minutes in boiling salted water, drain it and keep it warm.","Spread the stewed vegetables in a gratin dish, place the cod pieces on top, season with salt and pepper and bake for 10 minutes.","Serve the fish and its Basque-style vegetables with the rice."]},"it":{"title":"Trancio di merluzzo alla basca","steps":["Preriscaldare il forno a 210 °C. Immergere i pomodori per 30 secondi in acqua bollente per pelarli facilmente.","Eliminare i semi dai pomodori e tagliarli a dadini; tagliare il peperone a cubetti, affettare la cipolla e tritare l''aglio.","Mettere le verdure in una padella dai bordi alti con un bicchierino d''acqua, il peperoncino e il mazzetto aromatico, coprire e lasciar stufare a fuoco basso.","Salare, pepare, poi togliere il peperoncino e il mazzetto aromatico.","Cuocere il riso per circa 20 minuti in acqua bollente salata, scolarlo e tenerlo in caldo.","Distribuire le verdure stufate in una pirofila, adagiarvi sopra i tranci di merluzzo, salare, pepare e infornare per 10 minuti.","Servire il pesce e le sue verdure alla basca con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c4df5fda-28c9-43a2-96e7-7e5561d1ce17')
  returning id
)
