-- Filet mignon de porc à la moutarde
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '484ced08-5bb5-47ec-ac0a-be7990951eef'::uuid, null, 'Filet mignon de porc à la moutarde', 'seed', 'https://www.750g.com/filet-mignon-de-porc-a-la-moutarde-r74670.htm', '750g', '/recipe-photos/filet-mignon-de-porc-a-la-moutarde.webp', 'https://static.750g.com/images/1200-630/1891f1b9d47a53796fe6d9de441cc8b6/filet-mignon-de-porc-a-la-moutarde-r74670.png',
    2, 4, 40, 5, 35, '["Émincer finement l''oignon.","Chauffer beurre et huile dans une sauteuse et saisir le filet mignon sur toutes ses faces.","Faire fondre l''oignon 5 min dans la matière grasse, déglacer au vin blanc et remettre la viande.","Couvrir et cuire 20 min à feu moyen, puis réserver la viande sur une assiette.","Verser la crème dans la sauteuse en raclant les sucs, saler, poivrer et délayer les deux moutardes.","Couper le filet en tranches épaisses, les remettre dans la sauce, napper et laisser mijoter doucement 10 min."]'::jsonb,
    array['french', 'comfort']::text[], 'french', 418, 28.6,
    false, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pork tenderloin with mustard","steps":["Thinly slice the onion.","Heat the butter and oil in a sauté pan and sear the pork tenderloin on all sides.","Soften the onion in the fat for 5 min, deglaze with the white wine and return the meat.","Cover and cook for 20 min over medium heat, then set the meat aside on a plate.","Pour the cream into the pan, scraping up the browned bits, season with salt and pepper and stir in both mustards.","Cut the tenderloin into thick slices, return them to the sauce, spoon it over and simmer gently for 10 min."]},"it":{"title":"Filetto di maiale alla senape","steps":["Affettare finemente la cipolla.","Scaldare burro e olio in una padella dai bordi alti e rosolare il filetto su tutti i lati.","Far appassire la cipolla nel grasso di cottura per 5 min, sfumare con il vino bianco e rimettere la carne.","Coprire e cuocere 20 min a fuoco medio, poi tenere da parte la carne su un piatto.","Versare la panna nella padella raschiando il fondo, salare, pepare e stemperarvi le due senapi.","Tagliare il filetto a fette spesse, rimetterle nella salsa, ricoprirle di salsa e cuocere a fuoco lento per 10 min."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '484ced08-5bb5-47ec-ac0a-be7990951eef')
  returning id
)
