-- Filet mignon moutarde, pommes de terre et brocoli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '77447388-35a3-4563-83f0-2ca7a120c528'::uuid, null, 'Filet mignon moutarde, pommes de terre et brocoli', 'seed', 'https://jow.com/fr/recipes/filet-mignon-a-la-moutarde-pommes-de-terre-et-brocoli-8v4x3uwufp5c03fx11wy/print', 'Jow', '/recipe-photos/filet-mignon-moutarde-pommes-de-terre-et-brocoli.webp', 'https://static.jow.fr/550x550/patterns/kale-04-202309.png_merge_recipes/Y3e0SkaQQVJSww.png.jpg',
    2, 1, 80, 10, 40, '["Fouetter moutarde, sirop d''érable, sauce soja et un peu d''huile, enrober le filet mignon et le laisser mariner au frais au moins 30 min.","Préchauffer le four à 190 °C et trancher finement les pommes de terre.","Étaler les pommes de terre dans un plat, assaisonner de sel, poivre, thym et huile, puis enfourner 15 min.","Détailler le brocoli en fleurettes.","Ajouter le filet et le brocoli à côté des pommes de terre, assaisonner et rôtir 25 à 30 min, jusqu''à 63 °C à cœur.","Laisser reposer la viande quelques minutes, la trancher et servir avec les légumes."]'::jsonb,
    array['french', 'oven', 'light', 'high protein']::text[], 'french', 640, 54.3,
    true, 'fr', 'medium', '{"pots":1,"oven":true,"special":["thermometer"]}'::jsonb, false,
    '{"en":{"title":"Mustard pork tenderloin with potatoes and broccoli","steps":["Whisk the mustard, maple syrup, soy sauce and a little oil, coat the pork tenderloin and leave it to marinate in the fridge for at least 30 min.","Preheat the oven to 190 °C and thinly slice the potatoes.","Spread the potatoes in a dish, season with salt, pepper, thyme and oil, then bake for 15 min.","Cut the broccoli into florets.","Add the tenderloin and broccoli alongside the potatoes, season and roast for 25 to 30 min, until the core temperature reaches 63 °C.","Let the meat rest for a few minutes, slice it and serve with the vegetables."]},"it":{"title":"Filetto di maiale alla senape con patate e broccoli","steps":["Sbattere senape, sciroppo d''acero, salsa di soia e un po'' d''olio, ricoprire il filetto e lasciarlo marinare in frigorifero per almeno 30 min.","Preriscaldare il forno a 190 °C e affettare sottilmente le patate.","Distribuire le patate in una teglia, condire con sale, pepe, timo e olio, poi infornare per 15 min.","Dividere il broccolo in cimette.","Aggiungere il filetto e il broccolo accanto alle patate, condire e arrostire da 25 a 30 min, finché la carne raggiunge 63 °C al cuore.","Lasciar riposare la carne qualche minuto, affettarla e servire con le verdure."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '77447388-35a3-4563-83f0-2ca7a120c528')
  returning id
)
