-- Moules marinières
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '9b3c2f12-57fa-470a-81df-b5393ed78c87'::uuid, null, 'Moules marinières', 'seed', 'https://www.750g.com/la-meilleure-facon-de-faire-des-moules-marinieres-r207667.htm', '750g', '/recipe-photos/moules-marinieres.webp', 'https://static.750g.com/images/1200-630/51b65ce9ef864989f3d27004babc49c2/w6a9050.jpg',
    2, 4, 20, 10, 10, '["Rincer soigneusement les moules et jeter celles qui sont cassées ou qui restent ouvertes quand on les tapote.","Couper le céleri en petits dés, hacher les échalotes et le persil.","Faire fondre le beurre dans une cocotte et y faire suer doucement échalotes et céleri, sans coloration.","Ajouter les moules, le vin blanc, une bonne dose de poivre, le bouquet garni et le persil.","Couvrir et cuire à feu vif 3 à 4 minutes en mélangeant à mi-cuisson, jusqu''à ce que toutes les moules soient ouvertes.","Remuer une dernière fois pour enrober les moules de jus, retirer le bouquet garni et servir aussitôt."]'::jsonb,
    array['french', 'one-pot', 'quick', 'light']::text[], 'french', 281, 22.6,
    true, 'fr', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Moules marinières","steps":["Rinse the mussels thoroughly and discard any that are broken or stay open when tapped.","Cut the celery into small dice, and chop the shallots and parsley.","Melt the butter in a casserole and gently sweat the shallots and celery without letting them colour.","Add the mussels, white wine, a generous amount of pepper, the bouquet garni and the parsley.","Cover and cook over high heat for 3 to 4 minutes, stirring halfway through, until all the mussels have opened.","Stir one last time to coat the mussels in the juices, remove the bouquet garni and serve immediately."]},"it":{"title":"Moules marinières","steps":["Sciacquare accuratamente le cozze ed eliminare quelle rotte o che restano aperte quando si picchiettano.","Tagliare il sedano a dadini, tritare gli scalogni e il prezzemolo.","Far sciogliere il burro in una casseruola e farvi appassire dolcemente scalogni e sedano, senza farli colorire.","Aggiungere le cozze, il vino bianco, una generosa macinata di pepe, il mazzetto aromatico e il prezzemolo.","Coprire e cuocere a fuoco vivo da 3 a 4 minuti mescolando a metà cottura, finché tutte le cozze si sono aperte.","Mescolare un''ultima volta per avvolgere le cozze nel loro sugo, togliere il mazzetto aromatico e servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '9b3c2f12-57fa-470a-81df-b5393ed78c87')
  returning id
)
