-- Navarin d'agneau léger
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3716d87e-51ea-489d-9fc2-2d1322423904'::uuid, null, 'Navarin d''agneau léger', 'seed', 'https://www.croq-kilos.com/actus/recette-du-navarin-d-agneau-leger', 'Croq''Kilos', '/recipe-photos/navarin-d-agneau-leger.webp', 'https://www.croq-kilos.com/sites/default/files/styles/1920px/public/2025-03/23468-1633-recette-du-navarin-dagneau-leger.jpg',
    2, 4, 95, 20, 75, '["Éplucher et couper carotte, navet et pommes de terre ; émincer poireau et oignon, concasser la tomate et équeuter les haricots. Dégraisser l''agneau.","Saisir l''agneau 5 à 7 min dans l''huile chaude, puis le réserver.","Faire suer l''oignon et l''ail dans la cocotte et, si souhaité, les saupoudrer de farine.","Remettre l''agneau, ajouter bouillon, tomate, carotte, navet, poireau et bouquet garni ; couvrir et laisser frémir 45 min.","Ajouter pommes de terre et haricots verts et cuire encore 15 à 20 min jusqu''à ce qu''ils soient tendres.","Rectifier l''assaisonnement, retirer le bouquet garni et servir en assiettes creuses parsemées de persil."]'::jsonb,
    array['french', 'stew', 'light', 'one-pot']::text[], 'french', 535, 33,
    true, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Light lamb navarin","steps":["Peel and cut the carrot, turnip and potatoes; slice the leek and onion, chop the tomato and top and tail the beans. Trim the fat from the lamb.","Sear the lamb in the hot oil for 5 to 7 min, then set aside.","Sweat the onion and garlic in the casserole and, if desired, sprinkle them with flour.","Return the lamb, add the stock, tomato, carrot, turnip, leek and bouquet garni; cover and simmer gently for 45 min.","Add the potatoes and green beans and cook for another 15 to 20 min until tender.","Adjust the seasoning, remove the bouquet garni and serve in shallow bowls sprinkled with parsley."]},"it":{"title":"Navarin di agnello leggero","steps":["Pelare e tagliare carota, rapa e patate; affettare porro e cipolla, tagliare a pezzetti il pomodoro e spuntare i fagiolini. Sgrassare l''agnello.","Rosolare l''agnello da 5 a 7 min nell''olio caldo, poi tenerlo da parte.","Far appassire la cipolla e l''aglio nella casseruola e, se si desidera, spolverizzarli con la farina.","Rimettere l''agnello, aggiungere brodo, pomodoro, carota, rapa, porro e mazzetto aromatico; coprire e lasciar sobbollire per 45 min.","Aggiungere patate e fagiolini e cuocere ancora da 15 a 20 min, finché sono teneri.","Regolare di sale e pepe, togliere il mazzetto aromatico e servire in piatti fondi cosparsi di prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3716d87e-51ea-489d-9fc2-2d1322423904')
  returning id
)
