-- Papillote de cabillaud au fromage et aux poivrons
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f2fd383a-9f87-4d59-8b6f-1bcb8af6b4ba'::uuid, null, 'Papillote de cabillaud au fromage et aux poivrons', 'seed', 'https://www.quiveutdufromage.com/r-papillote-de-cabillaud-au-fromage-et-aux-poivrons', 'Qui veut du fromage', '/recipe-photos/papillote-de-cabillaud-au-fromage-et-aux-poivrons.webp', 'https://www.quiveutdufromage.com/api/dam/schema-image/fix635d9eidk98dkmqgfthhiidnzepkdhxmzjze.webp',
    2, 5, 35, 20, 10, '["Préchauffer le four à 180 °C (th. 6).","Laver, épépiner et peler les poivrons, puis les tailler en fines lanières.","Ciseler finement l''estragon et couper le fromage en tranches de 3 mm.","Faire fondre les lanières de poivron dans une poêle chaude avec un peu d''huile d''olive, ajouter l''estragon en fin de cuisson, assaisonner et réserver.","Retirer la peau du cabillaud et couvrir chaque filet de tranches de fromage.","Sur des feuilles de papier cuisson, disposer les poivrons puis un filet de poisson, arroser d''un filet d''huile, assaisonner et fermer hermétiquement les papillotes.","Cuire 10 minutes au four, puis servir les papillotes ouvertes à table."]'::jsonb,
    array['french', 'oven', 'light']::text[], 'french', 229, 32.1,
    true, 'fr', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Cod en papillote with cheese and peppers","steps":["Preheat the oven to 180 °C.","Wash, deseed and peel the peppers, then cut them into thin strips.","Finely chop the tarragon and cut the cheese into 3 mm slices.","Soften the pepper strips in a hot frying pan with a little olive oil, add the tarragon at the end of cooking, season and set aside.","Remove the skin from the cod and cover each fillet with slices of cheese.","On sheets of baking paper, lay the peppers then a fish fillet, drizzle with oil, season and seal the parcels tightly.","Bake for 10 minutes, then serve the parcels and open them at the table."]},"it":{"title":"Merluzzo al cartoccio con formaggio e peperoni","steps":["Preriscaldare il forno a 180 °C.","Lavare, privare dei semi e pelare i peperoni, poi tagliarli a listarelle sottili.","Tritare finemente il dragoncello e tagliare il formaggio a fette di 3 mm.","Far appassire le listarelle di peperone in una padella calda con un po'' d''olio d''oliva, aggiungere il dragoncello a fine cottura, condire e tenere da parte.","Togliere la pelle al merluzzo e coprire ogni filetto con fette di formaggio.","Su fogli di carta forno, disporre i peperoni e poi un filetto di pesce, irrorare con un filo d''olio, condire e chiudere ermeticamente i cartocci.","Cuocere in forno per 10 minuti, poi servire i cartocci aprendoli a tavola."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f2fd383a-9f87-4d59-8b6f-1bcb8af6b4ba')
  returning id
)
