-- Papillote de cabillaud au gingembre et citron vert
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6fd24020-984a-437d-8c7e-66f378f054a4'::uuid, null, 'Papillote de cabillaud au gingembre et citron vert', 'seed', 'https://www.weightwatchers.com/be/fr/recipe/papillote-cabillaud-au-gingembre-citron-vert/5d67b72532f27600dc549bec', 'WW', '/recipe-photos/papillote-de-cabillaud-au-gingembre-et-citron-vert.webp', 'https://v.cdn.ww.com/media/system/wine/5d67b71bb602ed002b6210f9/6a82d9ce-876f-4f9b-ae06-3aa8c51eaaf2/ukzjopwzxn39llpabaao.jpg?fit=crop&height=800&width=800&enable=upscale&quality=80',
    2, 4, 117, 25, 32, '["Préparer la marinade : mélanger l''ail haché, le zeste et le jus du citron vert, le gingembre râpé, le miel, l''huile d''olive et la sauce soja.","Enrober les pavés de cabillaud de marinade, couvrir et réserver 1 heure au réfrigérateur.","Préchauffer le four à 210 °C. Tailler les carottes en bâtonnets et émincer la courgette et les mange-tout.","Précuire les carottes 10 minutes à l''eau bouillante, puis les mange-tout et la courgette 2 minutes ; égoutter.","Répartir les légumes sur de grandes feuilles de papier cuisson, poser le cabillaud dessus, arroser du reste de marinade et parsemer de coriandre ciselée.","Fermer les papillotes et cuire 20 minutes au four."]'::jsonb,
    array['french', 'oven', 'light', 'make ahead']::text[], 'french', 295, 30.6,
    true, 'fr', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Cod en papillote with ginger and lime","steps":["Make the marinade: mix the chopped garlic, the lime zest and juice, the grated ginger, honey, olive oil and soy sauce.","Coat the cod fillets in the marinade, cover and refrigerate for 1 hour.","Preheat the oven to 210 °C. Cut the carrots into sticks and slice the courgette and mangetout.","Par-cook the carrots in boiling water for 10 minutes, then the mangetout and courgette for 2 minutes; drain.","Divide the vegetables among large sheets of baking paper, place the cod on top, drizzle with the remaining marinade and sprinkle with chopped coriander.","Seal the parcels and bake for 20 minutes."]},"it":{"title":"Merluzzo al cartoccio con zenzero e lime","steps":["Preparare la marinata: mescolare l''aglio tritato, la scorza e il succo del lime, lo zenzero grattugiato, il miele, l''olio d''oliva e la salsa di soia.","Ricoprire i tranci di merluzzo con la marinata, coprire e lasciar riposare 1 ora in frigorifero.","Preriscaldare il forno a 210 °C. Tagliare le carote a bastoncini e affettare la zucchina e le taccole.","Precuocere le carote per 10 minuti in acqua bollente, poi le taccole e la zucchina per 2 minuti; scolare.","Distribuire le verdure su grandi fogli di carta forno, adagiarvi sopra il merluzzo, irrorare con la marinata rimasta e cospargere di coriandolo tritato.","Chiudere i cartocci e cuocere in forno per 20 minuti."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6fd24020-984a-437d-8c7e-66f378f054a4')
  returning id
)
