-- Pavés de saumon sur lit de lentilles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7e1759e4-48d3-4b1a-9b65-d3c31e93172d'::uuid, null, 'Pavés de saumon sur lit de lentilles', 'seed', 'https://www.ricardocuisine.com/recettes/551-paves-de-saumon-sur-lit-de-lentilles', 'Ricardo', '/recipe-photos/paves-de-saumon-sur-lit-de-lentilles.webp', 'https://images.ricardocuisine.com/services/recipes/551.jpg',
    2, 4, 45, 15, 30, '["Piquer l''oignon avec les clous de girofle, puis le mettre dans une casserole d''eau avec les lentilles, le laurier, 1 c. à soupe d''huile, du sel et du poivre.","Laisser frémir environ 25 minutes jusqu''à ce que les lentilles soient tendres, puis égoutter et retirer l''oignon et le laurier.","Dans une poêle, faire suer les échalotes dans le reste de l''huile.","Verser le vin blanc, ajouter le zeste de citron et laisser réduire de moitié.","Ajouter les lentilles, réchauffer 2 minutes, incorporer le basilic, rectifier l''assaisonnement et garder au chaud.","Allumer le gril du four. Déposer le saumon dans un plat, le badigeonner de miel et le parsemer de chapelure.","Passer sous le gril, sur la grille du haut, 5 à 7 minutes selon l''épaisseur.","Découper le saumon en pavés et les servir sur les lentilles."]'::jsonb,
    array['french', 'oven', 'comfort', 'high protein']::text[], 'french', 1012, 67.9,
    false, 'fr', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Salmon fillets on a bed of lentils","steps":["Stud the onion with the cloves, then put it in a saucepan of water with the lentils, bay leaf, 1 tbsp of oil, salt and pepper.","Simmer for about 25 minutes until the lentils are tender, then drain and remove the onion and bay leaf.","In a frying pan, sweat the shallots in the remaining oil.","Pour in the white wine, add the lemon zest and reduce by half.","Add the lentils, heat through for 2 minutes, stir in the basil, adjust the seasoning and keep warm.","Turn on the oven grill. Place the salmon in a dish, brush it with honey and sprinkle with breadcrumbs.","Place under the grill, on the top shelf, for 5 to 7 minutes depending on thickness.","Cut the salmon into portions and serve them on the lentils."]},"it":{"title":"Tranci di salmone su letto di lenticchie","steps":["Steccare la cipolla con i chiodi di garofano, poi metterla in una pentola d''acqua con le lenticchie, l''alloro, 1 cucchiaio d''olio, sale e pepe.","Lasciar sobbollire per circa 25 minuti finché le lenticchie sono tenere, poi scolarle ed eliminare la cipolla e l''alloro.","In una padella, far appassire gli scalogni nell''olio rimasto.","Versare il vino bianco, aggiungere la scorza di limone e far ridurre della metà.","Aggiungere le lenticchie, scaldare per 2 minuti, incorporare il basilico, regolare di sale e pepe e tenere in caldo.","Accendere il grill del forno. Mettere il salmone in una pirofila, spennellarlo di miele e cospargerlo di pangrattato.","Passare sotto il grill, sul ripiano più alto, da 5 a 7 minuti a seconda dello spessore.","Tagliare il salmone a tranci e servirli sulle lenticchie."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7e1759e4-48d3-4b1a-9b65-d3c31e93172d')
  returning id
)
