-- Petit salé aux lentilles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0987bb18-6284-465e-9872-55a3a4917212'::uuid, null, 'Petit salé aux lentilles', 'seed', 'https://www.demotivateur.fr/food/petit-sale-aux-lentilles-38097', 'Demotivateur Food', '/recipe-photos/petit-sale-aux-lentilles.webp', 'https://www.demotivateur.fr/images-buzz/cover/34189379565d5d97f27cb6_petit-sale-lentilles.jpg',
    2, 4, 75, 15, 60, '["Rincer les lentilles à l''eau froide et les égoutter.","Dans une cocotte, faire revenir l''oignon en dés dans l''huile d''olive.","Ajouter les carottes en dés et l''ail, puis les lentilles, et remuer environ 1 minute.","Déposer le petit salé et la saucisse, verser le bouillon, puis ajouter le laurier, le thym et du poivre.","Couvrir et laisser mijoter 45 minutes à 1 heure, jusqu''à ce que les lentilles soient fondantes et la viande cuite ; ajouter un peu d''eau chaude si nécessaire.","Retirer le laurier et le thym, trancher la saucisse et parsemer de persil.","Servir bien chaud avec la moutarde à l''ancienne."]'::jsonb,
    array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 730, 42.4,
    true, 'fr', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Petit salé (salt pork with lentils)","steps":["Rinse the lentils in cold water and drain them.","In a casserole dish, sauté the diced onion in the olive oil.","Add the diced carrots and the garlic, then the lentils, and stir for about 1 minute.","Lay the salt pork and the sausage on top, pour in the stock, then add the bay leaf, thyme and some pepper.","Cover and simmer for 45 minutes to 1 hour, until the lentils are tender and the meat is cooked; add a little hot water if needed.","Remove the bay leaf and thyme, slice the sausage and sprinkle with parsley.","Serve piping hot with the wholegrain mustard."]},"it":{"title":"Petit salé con lenticchie","steps":["Sciacquare le lenticchie in acqua fredda e scolarle.","In una casseruola, soffriggere la cipolla a dadini nell''olio d''oliva.","Aggiungere le carote a dadini e l''aglio, poi le lenticchie, e mescolare per circa 1 minuto.","Adagiare il petit salé e la salsiccia, versare il brodo, poi aggiungere l''alloro, il timo e il pepe.","Coprire e cuocere a fuoco lento da 45 minuti a 1 ora, finché le lenticchie sono tenere e la carne è cotta; aggiungere un po'' d''acqua calda se necessario.","Togliere l''alloro e il timo, affettare la salsiccia e cospargere di prezzemolo.","Servire ben caldo con la senape in grani."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0987bb18-6284-465e-9872-55a3a4917212')
  returning id
)
