-- Poulet au vin blanc et à l'estragon, carottes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e28bf347-b869-4708-97e6-b7edec18d66e'::uuid, null, 'Poulet au vin blanc et à l''estragon, carottes', 'seed', 'https://www.weightwatchers.com/ch/fr/recette/poulet-sauce-au-vin-et-lestragon/659fabb3ce8846a01bc40d10', 'WW', '/recipe-photos/poulet-au-vin-blanc-et-a-l-estragon-carottes.webp', 'https://v.cdn.ww.com/media/system/wine/659fabab75cab8006305628f/60271476-5e04-4358-b839-0668f944e2c1/mlfnxi62hm0o3jeceqg9.jpg?fit=crop&height=800&width=800&enable=upscale&quality=80',
    2, 4, 70, 15, 55, '["Préchauffer le four à 190 °C (170 °C chaleur tournante).","Disposer les blancs de poulet dans un plat à gratin et les saler.","Faire dorer les échalotes émincées dans l''huile, puis les répartir sur le poulet.","Mélanger la majeure partie du bouillon avec le vin et le fromage frais, ajouter l''estragon haché et poivrer.","Verser sur le poulet, couvrir et enfourner 30 à 35 min jusqu''à cuisson complète.","Pendant ce temps, faire revenir les carottes dans le beurre fondu, mouiller avec le reste du bouillon et cuire environ 15 min.","Ajouter le persil aux carottes, assaisonner et servir avec le poulet, décoré d''estragon."]'::jsonb,
    array['french', 'oven', 'light', 'high protein']::text[], 'french', 445, 40.9,
    true, 'fr', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"White wine and tarragon chicken with carrots","steps":["Preheat the oven to 190 °C (170 °C fan).","Arrange the chicken breasts in a baking dish and season them with salt.","Brown the sliced shallots in the oil, then spread them over the chicken.","Mix most of the stock with the wine and the fromage frais, add the chopped tarragon and season with pepper.","Pour over the chicken, cover and bake for 30 to 35 min until cooked through.","Meanwhile, sauté the carrots in the melted butter, add the rest of the stock and cook for about 15 min.","Add the parsley to the carrots, season and serve with the chicken, garnished with tarragon."]},"it":{"title":"Pollo al vino bianco e dragoncello con carote","steps":["Preriscaldare il forno a 190 °C (170 °C ventilato).","Disporre i petti di pollo in una pirofila e salarli.","Far dorare gli scalogni affettati nell''olio, poi distribuirli sul pollo.","Mescolare la maggior parte del brodo con il vino e il formaggio fresco, aggiungere il dragoncello tritato e pepare.","Versare sul pollo, coprire e infornare per 30-35 min, fino a cottura completa.","Nel frattempo, rosolare le carote nel burro fuso, bagnare con il resto del brodo e cuocere per circa 15 min.","Aggiungere il prezzemolo alle carote, aggiustare di sale e pepe e servire con il pollo, guarnendo con il dragoncello."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e28bf347-b869-4708-97e6-b7edec18d66e')
  returning id
)
