-- Poulet mijoté aux olives
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c342d26f-6184-4e3a-898e-bf58347b4ac2'::uuid, null, 'Poulet mijoté aux olives', 'seed', 'https://www.demotivateur.fr/food/recette/poulet-mijote-aux-olives-1947', 'Demotivateur Food', '/recipe-photos/poulet-mijote-aux-olives.webp', 'https://www.demotivateur.fr/images/cover_recette/1689240958-poulet_mijote_olives.jpg',
    2, 6, 60, 10, 50, '["Saler et poivrer les morceaux de poulet, puis les dorer environ 10 min dans une cocotte avec un filet d''huile d''olive.","Retirer le poulet et faire fondre l''oignon et l''ail émincés dans la cocotte.","Remettre le poulet, mouiller avec le vin blanc et un petit verre d''eau, puis ajouter les olives égouttées.","Assaisonner avec les herbes de Provence, sel et poivre, couvrir et laisser mijoter 40 min à feu doux.","Goûter, rectifier l''assaisonnement, prolonger de quelques minutes si besoin et servir."]'::jsonb,
    array['french', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'french', 607, 60.8,
    true, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Braised chicken with olives","steps":["Season the chicken pieces with salt and pepper, then brown them for about 10 min in a casserole dish with a drizzle of olive oil.","Remove the chicken and soften the sliced onion and garlic in the casserole dish.","Return the chicken, pour in the white wine and a small glass of water, then add the drained olives.","Season with the herbes de Provence, salt and pepper, cover and simmer for 40 min over low heat.","Taste, adjust the seasoning, cook a few minutes longer if needed and serve."]},"it":{"title":"Pollo in umido alle olive","steps":["Salare e pepare i pezzi di pollo, poi rosolarli per circa 10 min in una casseruola con un filo d''olio d''oliva.","Togliere il pollo e far appassire la cipolla e l''aglio affettati nella casseruola.","Rimettere il pollo, bagnare con il vino bianco e un bicchierino d''acqua, poi aggiungere le olive sgocciolate.","Insaporire con le erbe di Provenza, sale e pepe, coprire e cuocere a fuoco lento per 40 min.","Assaggiare, regolare di sale e pepe, prolungare la cottura di qualche minuto se necessario e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c342d26f-6184-4e3a-898e-bf58347b4ac2')
  returning id
)
