    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a317f775-694d-4e3d-80c1-cdd2f0e6368a'::uuid, null, 'Poulet à l''estragon', 'seed', 'https://ileauxepices.com/blog/2014/09/25/recette-poulet-a-lestragon/wpid5861/', 'Île aux épices', '/recipe-photos/poulet-a-l-estragon.webp', 'https://ileauxepices.com/blog/wp-content/uploads/2014/09/poulet-à-lestragon.jpg',
    2, 4, 40, 10, 30, '["Hacher finement l''ail et les échalotes et couper chaque cuisse en deux.","Chauffer l''huile dans une sauteuse, y faire fondre le beurre et dorer le poulet à feu moyen sur toutes les faces.","Ajouter ail, échalotes et estragon, puis déglacer avec le vin blanc.","Saler, poivrer, couvrir et laisser mijoter environ 20 min en remuant de temps en temps.","Retirer le poulet, incorporer la crème à la sauce et chauffer doucement jusqu''aux premiers frémissements.","Remettre le poulet dans la sauce à l''estragon et servir."]'::jsonb,
    array['french', 'stew', 'comfort']::text[], 'french', 540, 24.3,
    false, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Tarragon chicken","steps":["Finely chop the garlic and shallots and cut each chicken leg in half.","Heat the oil in a sauté pan, melt the butter in it and brown the chicken on all sides over medium heat.","Add the garlic, shallots and tarragon, then deglaze with the white wine.","Season with salt and pepper, cover and simmer for about 20 min, stirring from time to time.","Remove the chicken, stir the crème fraîche into the sauce and heat gently until it just starts to simmer.","Return the chicken to the tarragon sauce and serve."]},"it":{"title":"Pollo al dragoncello","steps":["Tritare finemente l''aglio e gli scalogni e tagliare ogni coscia a metà.","Scaldare l''olio in una padella dai bordi alti, farvi sciogliere il burro e rosolare il pollo a fuoco medio su tutti i lati.","Aggiungere aglio, scalogni e dragoncello, poi sfumare con il vino bianco.","Salare, pepare, coprire e cuocere a fuoco lento per circa 20 min, mescolando di tanto in tanto.","Togliere il pollo, incorporare la panna alla salsa e scaldare dolcemente fino al primo bollore.","Rimettere il pollo nella salsa al dragoncello e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a317f775-694d-4e3d-80c1-cdd2f0e6368a')
  returning id
)
