-- Rôti de porc au lait et à la moutarde
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'c0a07491-dc99-4dc0-8895-b6358173175c'::uuid, null, 'Rôti de porc au lait et à la moutarde', 'seed', 'https://www.demotivateur.fr/food/recette/roti-de-porc-a-la-moutarde-1256', 'Demotivateur Food', '/recipe-photos/roti-de-porc-au-lait-et-a-la-moutarde.webp', 'https://www.demotivateur.fr/images/cover_recette/1641317473-roti_porc_lait_moutarde.jpg',
    2, 6, 115, 10, 105, '["Préchauffer le four à 150 °C.","Peler et dégermer l''ail, puis le mettre dans une casserole avec le lait, le laurier, la moutarde et le bouillon ; saler, poivrer et mélanger.","Porter à ébullition puis laisser frémir très doucement environ 15 min.","Saisir le rôti à feu vif sur toutes ses faces dans l''huile, dans une cocotte allant au four, puis jeter la graisse.","Verser le lait infusé sur la viande, couvrir et enfourner 1 h 30.","Trancher le rôti et le servir nappé de sauce."]'::jsonb,
    array['french', 'oven', 'comfort', 'high protein']::text[], 'french', 418, 48.5,
    true, 'fr', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Pork roast with milk and mustard","steps":["Preheat the oven to 150 °C.","Peel the garlic and remove the green germ, then put it in a saucepan with the milk, bay leaf, mustard and stock; season with salt and pepper and stir.","Bring to the boil, then simmer very gently for about 15 min.","Sear the roast over high heat on all sides in the oil, in an ovenproof casserole dish, then discard the fat.","Pour the infused milk over the meat, cover and bake for 1 hr 30 min.","Slice the roast and serve it with the sauce spooned over."]},"it":{"title":"Arrosto di maiale al latte e senape","steps":["Preriscaldare il forno a 150 °C.","Sbucciare l''aglio ed eliminare l''anima, poi metterlo in una casseruola con il latte, l''alloro, la senape e il brodo; salare, pepare e mescolare.","Portare a ebollizione, poi lasciar sobbollire molto dolcemente per circa 15 min.","Rosolare l''arrosto a fuoco vivace su tutti i lati nell''olio, in una casseruola adatta al forno, poi eliminare il grasso.","Versare il latte aromatizzato sulla carne, coprire e infornare per 1 ora e 30 min.","Affettare l''arrosto e servirlo irrorato con la salsa."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'c0a07491-dc99-4dc0-8895-b6358173175c')
  returning id
)
