-- Saumon rôti aux lentilles vertes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8e07faeb-77dd-4637-ac75-c74706aeb411'::uuid, null, 'Saumon rôti aux lentilles vertes', 'seed', 'https://lacuisinedejulie.fr/recette/saumon-roti-aux-lentilles-vertes/', 'La Cuisine de Julie', '/recipe-photos/saumon-roti-aux-lentilles-vertes.webp', 'https://lacuisinedejulie.fr/wp-content/uploads/2022/10/Saumon-roti-aux-lentilles-vertes.jpg',
    2, 4, 60, 15, 45, '["Éplucher les carottes et les couper en dés ; peler l''ail et l''oignon, puis piquer l''oignon du clou de girofle.","Ficeler les herbes du bouquet garni.","Mettre les lentilles rincées dans une casserole d''eau froide avec les carottes, l''oignon, l''ail, le morceau de lard et le bouquet garni.","Porter à ébullition puis laisser frémir 30 minutes à demi-couvert, en salant à mi-cuisson.","Environ 10 minutes avant la fin, passer les pavés de saumon sous le gril du four, côté peau vers la chaleur.","Égoutter les lentilles en retirant l''oignon et le bouquet garni ; couper le lard en dés et le faire dorer dans la moitié de l''huile.","Ajouter les lentilles au lard, mélanger et garder au chaud.","Retirer la peau du saumon, saler, poivrer, arroser du reste d''huile et servir sur les lentilles."]'::jsonb,
    array['french', 'stew', 'comfort', 'high protein']::text[], 'french', 935, 58.2,
    false, 'fr', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Roast salmon with green lentils","steps":["Peel the carrots and dice them; peel the garlic and onion, then stud the onion with the clove.","Tie the bouquet garni herbs together with string.","Put the rinsed lentils in a saucepan of cold water with the carrots, onion, garlic, the piece of bacon and the bouquet garni.","Bring to the boil, then simmer for 30 minutes half-covered, adding salt halfway through cooking.","About 10 minutes before the end, put the salmon fillets under the oven grill, skin side towards the heat.","Drain the lentils, removing the onion and the bouquet garni; dice the bacon and brown it in half the oil.","Add the lentils to the bacon, mix and keep warm.","Remove the skin from the salmon, season with salt and pepper, drizzle with the remaining oil and serve on the lentils."]},"it":{"title":"Salmone arrosto con lenticchie verdi","steps":["Pelare le carote e tagliarle a dadini; sbucciare l''aglio e la cipolla, poi steccare la cipolla con il chiodo di garofano.","Legare con lo spago le erbe del bouquet garni.","Mettere le lenticchie sciacquate in una casseruola di acqua fredda con le carote, la cipolla, l''aglio, il pezzo di pancetta e il bouquet garni.","Portare a ebollizione, poi lasciar sobbollire per 30 minuti con il coperchio socchiuso, salando a metà cottura.","Circa 10 minuti prima della fine, passare i tranci di salmone sotto il grill del forno, con la pelle rivolta verso il calore.","Scolare le lenticchie eliminando la cipolla e il bouquet garni; tagliare la pancetta a dadini e farla dorare in metà dell''olio.","Aggiungere le lenticchie alla pancetta, mescolare e tenere in caldo.","Togliere la pelle al salmone, salare, pepare, irrorare con l''olio rimasto e servire sulle lenticchie."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8e07faeb-77dd-4637-ac75-c74706aeb411')
  returning id
)
