-- Saumon à l'oseille des frères Troisgros
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '419c8ae2-41ee-4db8-afd8-c6f6ff0e11be'::uuid, null, 'Saumon à l''oseille des frères Troisgros', 'seed', 'https://www.gillespudlowski.com/257271/recettes/recette-de-confinement-le-saumon-a-loseille-des-freres-troisgros', 'Gilles Pudlowski', '/recipe-photos/saumon-a-l-oseille-des-freres-troisgros.webp', 'https://www.gillespudlowski.com/wp-content/uploads/2020/04/saumon-a-loseille-1.jpg',
    2, 4, 35, 20, 15, '["Ôter les arêtes du saumon à la pince, puis le détailler en fines escalopes d''environ 140 g.","Aplatir légèrement les escalopes entre deux feuilles de papier cuisson huilées pour obtenir une épaisseur régulière.","Effeuiller l''oseille en retirant les tiges et les nervures, la rincer et déchirer les grandes feuilles.","Dans une sauteuse, réunir l''échalote finement hachée, le fumet, le vin et le vermouth, puis réduire jusqu''à obtenir un liquide sirupeux.","Ajouter la crème et laisser frémir jusqu''à ce que la sauce nappe légèrement.","Plonger l''oseille 10 secondes en remuant la sauteuse sans fouetter, puis assaisonner de quelques gouttes de citron et de sel.","Saisir les escalopes salées dans une poêle antiadhésive très chaude, environ 10 secondes par face, en les laissant à peine cuites.","Napper des assiettes chaudes de sauce, poser le saumon dessus et servir immédiatement."]'::jsonb,
    array['french', 'fancy', 'high protein']::text[], 'french', 813, 49.7,
    false, 'fr', 'hard', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Troisgros brothers'' salmon with sorrel","steps":["Remove the pin bones from the salmon with tweezers, then cut it into thin escalopes of about 140 g.","Lightly flatten the escalopes between two sheets of oiled baking paper to get an even thickness.","Strip the sorrel, removing the stems and ribs, rinse it and tear the large leaves.","In a sauté pan, combine the finely chopped shallot, the fish stock, the wine and the vermouth, then reduce until syrupy.","Add the cream and simmer until the sauce lightly coats a spoon.","Plunge the sorrel in for 10 seconds, swirling the pan without whisking, then season with a few drops of lemon and some salt.","Sear the salted escalopes in a very hot non-stick frying pan, about 10 seconds per side, leaving them barely cooked.","Spoon the sauce onto warm plates, lay the salmon on top and serve immediately."]},"it":{"title":"Salmone all''acetosa dei fratelli Troisgros","steps":["Eliminare le spine del salmone con una pinzetta, poi tagliarlo in sottili scaloppe di circa 140 g.","Appiattire leggermente le scaloppe tra due fogli di carta forno unti d''olio per ottenere uno spessore uniforme.","Sfogliare l''acetosa eliminando gambi e nervature, sciacquarla e spezzettare le foglie grandi.","In una padella dai bordi alti, riunire lo scalogno tritato finemente, il fumetto, il vino e il vermouth, poi far ridurre fino a ottenere un liquido sciropposo.","Aggiungere la panna e lasciar sobbollire finché la salsa vela leggermente il cucchiaio.","Immergere l''acetosa per 10 secondi muovendo la padella senza sbattere, poi condire con qualche goccia di limone e il sale.","Scottare le scaloppe salate in una padella antiaderente molto calda, circa 10 secondi per lato, lasciandole appena cotte.","Velare di salsa dei piatti caldi, adagiarvi sopra il salmone e servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '419c8ae2-41ee-4db8-afd8-c6f6ff0e11be')
  returning id
)
