  select 'df8c039d-295f-4d5a-b25a-7f45780c4209'::uuid, null, 'Turbot sauce vierge', 'seed', 'https://www.noovomoi.ca/cuisiner/recettes/recette.turbot-sauce-vierge.1.1423555.html', 'Noovo Moi', '/recipe-photos/turbot-sauce-vierge.webp', 'https://www.noovomoi.ca/resizer/v2/QLP6DNZDNS7CBGY25ZADPA7FCY.jpg?smart=true&auth=efb274cad985b370ed3e8f21089e9d8632fa71a131069e1f05f3912ec1c478e6&width=1200&height=630',
    2, 4, 25, 10, 15, '["Préchauffer le four à 175 °C (350 °F).","Saler et poivrer le poisson et le déposer dans un plat ou sur une plaque couverte de papier cuisson.","Enfourner 10 à 15 minutes selon l''épaisseur des filets.","Pendant ce temps, mélanger les dés de tomate, l''huile d''olive, les câpres, le vinaigre et les herbes, puis saler et poivrer ; ajouter un peu de sucre si les tomates manquent de goût.","Sortir le poisson et le servir aussitôt nappé de sauce vierge, avec du riz ou une purée et un légume."]'::jsonb,
    array['french', 'oven', 'quick', 'light']::text[], 'french', 280, 28,
    true, 'fr', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Turbot with sauce vierge","steps":["Preheat the oven to 175 °C (350 °F).","Season the fish with salt and pepper and place it in a dish or on a baking tray lined with baking paper.","Bake for 10 to 15 minutes depending on the thickness of the fillets.","Meanwhile, mix the diced tomato, olive oil, capers, vinegar and herbs, then season with salt and pepper; add a little sugar if the tomatoes lack flavour.","Take the fish out and serve it straight away topped with the sauce vierge, with rice or mash and a vegetable."]},"it":{"title":"Rombo con salsa vierge","steps":["Preriscaldare il forno a 175 °C (350 °F).","Salare e pepare il pesce e disporlo in una pirofila o su una teglia rivestita di carta forno.","Infornare per 10-15 minuti a seconda dello spessore dei filetti.","Nel frattempo, mescolare i dadini di pomodoro, l''olio d''oliva, i capperi, l''aceto e le erbe, poi salare e pepare; aggiungere un po'' di zucchero se i pomodori sono poco saporiti.","Sfornare il pesce e servirlo subito coperto di salsa vierge, con riso o purè e una verdura."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'df8c039d-295f-4d5a-b25a-7f45780c4209')
  returning id
)
