-- Œufs pochés, épinards et lentilles
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'caa6c099-644e-4533-b07e-55ea51423d4c'::uuid, null, 'Œufs pochés, épinards et lentilles', 'seed', 'https://www.ricardocuisine.com/recettes/8946-oeufs-poches-epinards-et-lentilles', 'Ricardo', '/recipe-photos/oeufs-poches-epinards-et-lentilles.webp', 'https://images.ricardocuisine.com/services/recipes/8946.jpg',
    2, 4, 30, 15, 15, '["Dans une grande poêle, faire revenir l''oignon, l''ail et le gingembre dans l''huile environ 3 minutes.","Ajouter le garam masala et le curcuma et remuer 30 secondes.","Ajouter la tomate râpée, les lentilles et la moitié des épinards, couvrir et cuire environ 5 minutes jusqu''à ce que les épinards tombent.","Retirer le couvercle, ajouter le reste des épinards, les laisser tomber puis saler et poivrer.","Former des creux dans la préparation et y casser les œufs.","Couvrir et laisser mijoter 5 à 6 minutes, jusqu''à ce que les blancs soient pris.","Parsemer de feta, ajouter un trait de sriracha et servir."]'::jsonb,
    array['french', 'one-pot', 'vegetarian', 'light']::text[], 'french', 308, 17.2,
    true, 'fr', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Poached eggs with spinach and lentils","steps":["In a large frying pan, sauté the onion, garlic and ginger in the oil for about 3 minutes.","Add the garam masala and turmeric and stir for 30 seconds.","Add the grated tomato, the lentils and half the spinach, cover and cook for about 5 minutes until the spinach wilts.","Uncover, add the rest of the spinach, let it wilt, then season with salt and pepper.","Make hollows in the mixture and crack the eggs into them.","Cover and simmer for 5 to 6 minutes, until the whites are set.","Sprinkle with feta, add a dash of sriracha and serve."]},"it":{"title":"Uova in camicia con spinaci e lenticchie","steps":["In una padella grande, soffriggere la cipolla, l''aglio e lo zenzero nell''olio per circa 3 minuti.","Aggiungere il garam masala e la curcuma e mescolare per 30 secondi.","Aggiungere il pomodoro grattugiato, le lenticchie e metà degli spinaci, coprire e cuocere per circa 5 minuti, finché gli spinaci appassiscono.","Togliere il coperchio, aggiungere il resto degli spinaci, lasciarli appassire, poi salare e pepare.","Formare delle conche nel composto e rompervi dentro le uova.","Coprire e cuocere a fuoco lento per 5-6 minuti, finché gli albumi sono rappresi.","Cospargere di feta, aggiungere un goccio di sriracha e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'caa6c099-644e-4533-b07e-55ea51423d4c')
  returning id
)
