-- Beef rendang
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '39fd3a34-7eb2-497f-8ff1-3d247f845ea0'::uuid, null, 'Beef rendang', 'seed', 'https://recipetineats.com/beef-rendang', 'RecipeTin Eats', '/recipe-photos/beef-rendang.webp', 'https://www.recipetineats.com/tachyon/2014/11/Beef-Rendang-13.jpg',
    2, 6, 200, 20, 180, '["Blitz the chilies, onion, garlic, sliced lemongrass, galangal, ginger and paste oil in a food processor until very fine.","Heat the browning oil in a heavy pot over high heat and sear the beef in batches; set aside.","Lower the heat to medium-low and fry the spice paste for 2–3 minutes until it darkens.","Return the beef with all the remaining curry ingredients, bring to a simmer and turn down to a very gentle bubble.","Cover and cook for 1 hour 15 minutes, then check the beef.","Uncover, raise the heat to medium and cook for 30–40 minutes, stirring often, until the oil separates and the sauce reduces to a dark paste clinging to the beef (add a splash of water and keep going if the meat isn''t tender yet).","Serve with steamed rice."]'::jsonb,
    array['asian', 'indonesian', 'curry', 'comfort', 'fancy', 'high protein']::text[], 'indonesian', 860, 40.5,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":["food processor"]}'::jsonb, false,
    '{"fr":{"title":"Rendang de bœuf","steps":["Mixer au robot les piments, l''oignon, l''ail, la citronnelle émincée, le galanga, le gingembre et l''huile de la pâte jusqu''à obtenir une pâte très fine.","Faire chauffer l''huile de saisie dans une cocotte à fond épais à feu vif et saisir le bœuf en plusieurs fois ; réserver.","Baisser à feu moyen-doux et faire revenir la pâte d''épices 2 à 3 minutes jusqu''à ce qu''elle fonce.","Remettre le bœuf avec tous les autres ingrédients du curry, porter à frémissement puis baisser le feu pour obtenir un très léger bouillonnement.","Couvrir et cuire 1 heure 15 minutes, puis vérifier le bœuf.","Découvrir, monter à feu moyen et cuire 30 à 40 minutes en remuant souvent, jusqu''à ce que l''huile se sépare et que la sauce réduise en une pâte sombre qui enrobe le bœuf (ajouter un peu d''eau et poursuivre si la viande n''est pas encore tendre).","Servir avec du riz vapeur."]},"it":{"title":"Rendang di manzo","steps":["Frullare nel mixer i peperoncini, la cipolla, l''aglio, la citronella affettata, il galanga, lo zenzero e l''olio per la pasta fino a ottenere un composto finissimo.","Scaldare l''olio per rosolare in una pentola dal fondo spesso a fuoco vivace e rosolare il manzo poco alla volta; tenere da parte.","Abbassare a fuoco medio-basso e soffriggere la pasta di spezie per 2–3 minuti, finché si scurisce.","Rimettere il manzo con tutti gli altri ingredienti del curry, portare a leggero bollore e abbassare la fiamma fino a un bollore leggerissimo.","Coprire e cuocere per 1 ora e 15 minuti, poi controllare il manzo.","Scoprire, alzare a fuoco medio e cuocere per 30–40 minuti mescolando spesso, finché l''olio si separa e la salsa si riduce a una pasta scura che avvolge la carne (aggiungere un goccio d''acqua e continuare se la carne non è ancora tenera).","Servire con riso al vapore."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '39fd3a34-7eb2-497f-8ff1-3d247f845ea0')
  returning id
)
