-- Cantonese steamed fish with ginger and scallion
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'df078eb0-325b-4dde-897e-a5fdefb5ec92'::uuid, null, 'Cantonese steamed fish with ginger and scallion', 'seed', 'https://thewoksoflife.com/cantonese-steamed-fish/', 'The Woks of Life', '/recipe-photos/cantonese-steamed-fish-with-ginger-and-scallion.webp', 'https://thewoksoflife.com/wp-content/uploads/2020/12/cantonese-steamed-fish-17.jpg',
    2, 2, 20, 5, 15, '["Julienne the spring onions and ginger and roughly chop the coriander; keep about a third aside for topping.","Stir the soy sauce, salt and sugar into 2 tbsp hot water until dissolved.","Bring 2–5 cm of water to a boil in a steamer setup (a wok with a rack and lid works).","Put the rinsed fillet on a heatproof plate, set it in the steamer, cover and steam over medium heat 7–10 minutes (4–5 for thin fillets), until a knife slides easily through the thickest part.","Pour off the liquid on the plate and scatter the reserved aromatics over the fish.","Heat the oil in a small pan, fry the remaining ginger about 1 minute, add the white spring onion for 30 seconds, then the green parts and coriander.","Add the soy mixture, let it bubble about 30 seconds until the greens just wilt, then pour it over the fish and serve with steamed rice."]'::jsonb,
    array['chinese', 'asian', 'light', 'quick']::text[], 'chinese', 273, 27.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":["steamer"]}'::jsonb, false,
    '{"fr":{"title":"Poisson vapeur cantonais au gingembre et à l''oignon nouveau","steps":["Tailler les oignons nouveaux et le gingembre en julienne et hacher grossièrement la coriandre ; en réserver environ un tiers pour la garniture.","Mélanger la sauce soja, le sel et le sucre dans 2 c. à soupe d''eau chaude jusqu''à dissolution.","Porter à ébullition 2 à 5 cm d''eau dans un cuit-vapeur (un wok avec une grille et un couvercle fait l''affaire).","Déposer le filet rincé sur une assiette résistant à la chaleur, la placer dans le cuit-vapeur, couvrir et cuire à la vapeur à feu moyen 7 à 10 minutes (4 à 5 pour des filets fins), jusqu''à ce qu''un couteau traverse facilement la partie la plus épaisse.","Jeter le liquide de l''assiette et parsemer le poisson des aromates réservés.","Faire chauffer l''huile dans une petite poêle, faire revenir le reste du gingembre environ 1 minute, ajouter le blanc des oignons nouveaux 30 secondes, puis le vert et la coriandre.","Ajouter le mélange à la sauce soja, laisser bouillonner environ 30 secondes jusqu''à ce que les herbes commencent tout juste à flétrir, puis verser sur le poisson et servir avec du riz vapeur."]},"it":{"title":"Pesce al vapore alla cantonese con zenzero e cipollotto","steps":["Tagliare a julienne i cipollotti e lo zenzero e tritare grossolanamente il coriandolo; tenerne da parte circa un terzo per guarnire.","Sciogliere la salsa di soia, il sale e lo zucchero in 2 cucchiai di acqua calda.","Portare a ebollizione 2–5 cm d''acqua in una vaporiera (va bene anche un wok con griglia e coperchio).","Mettere il filetto sciacquato su un piatto resistente al calore, sistemarlo nella vaporiera, coprire e cuocere a vapore a fuoco medio per 7–10 minuti (4–5 per filetti sottili), finché un coltello affonda facilmente nella parte più spessa.","Eliminare il liquido nel piatto e distribuire sul pesce gli aromi tenuti da parte.","Scaldare l''olio in un padellino, friggere lo zenzero rimasto per circa 1 minuto, aggiungere la parte bianca dei cipollotti per 30 secondi, poi la parte verde e il coriandolo.","Aggiungere il composto di soia, lasciar bollire per circa 30 secondi finché le erbe appassiscono appena, poi versarlo sul pesce e servire con riso al vapore."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'df078eb0-325b-4dde-897e-a5fdefb5ec92')
  returning id
)
