-- Chicken larb in lettuce cups
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a7ed4529-c101-447e-8900-f9b038ec9bf2'::uuid, null, 'Chicken larb in lettuce cups', 'seed', 'https://thewoksoflife.com/chicken-larb/', 'The Woks of Life', '/recipe-photos/chicken-larb-in-lettuce-cups.webp', 'https://thewoksoflife.com/wp-content/uploads/2019/08/chicken-larb-13.jpg',
    2, 4, 30, 15, 15, '["Toast the raw rice in a dry wok over low heat for about 10 minutes until golden and fragrant, then grind it to a coarse powder.","Heat the oil in the wok over high heat and fry half the shallots until crisp; lift them out and keep the oil in the wok.","Get the wok smoking hot again, add the minced chicken and stir-fry until browned and slightly crispy.","Season with the sugar, fish sauce and lime juice.","Stir in the toasted rice powder, chili, the remaining raw shallots, spring onion, coriander and mint and toss for about a minute.","Taste and balance with salt, chili, fish sauce or lime as needed.","Spoon into lettuce leaves and scatter the crispy shallots on top."]'::jsonb,
    array['asian', 'thai', 'salad', 'light', 'high protein']::text[], 'thai', 330, 35.2,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":["mortar and pestle"]}'::jsonb, false,
    '{"fr":{"title":"Larb de poulet en feuilles de laitue","steps":["Faire griller le riz cru dans un wok à sec à feu doux environ 10 minutes jusqu''à ce qu''il soit doré et parfumé, puis le moudre en poudre grossière.","Faire chauffer l''huile dans le wok à feu vif et faire frire la moitié des échalotes jusqu''à ce qu''elles soient croustillantes ; les retirer en gardant l''huile dans le wok.","Faire chauffer de nouveau le wok jusqu''à ce qu''il fume, ajouter le poulet haché et le faire sauter jusqu''à ce qu''il soit doré et légèrement croustillant.","Assaisonner avec le sucre, la sauce poisson et le jus de citron vert.","Incorporer la poudre de riz grillé, le piment, le reste des échalotes crues, l''oignon nouveau, la coriandre et la menthe, et faire sauter environ une minute.","Goûter et équilibrer avec du sel, du piment, de la sauce poisson ou du citron vert selon les besoins.","Répartir à la cuillère dans les feuilles de laitue et parsemer d''échalotes croustillantes."]},"it":{"title":"Larb di pollo in coppette di lattuga","steps":["Tostare il riso crudo in un wok asciutto a fuoco basso per circa 10 minuti, finché è dorato e profumato, poi macinarlo in una polvere grossolana.","Scaldare l''olio nel wok a fuoco vivace e friggere metà degli scalogni finché sono croccanti; toglierli e lasciare l''olio nel wok.","Riscaldare il wok finché fuma, aggiungere il pollo macinato e saltarlo finché è rosolato e leggermente croccante.","Condire con lo zucchero, la salsa di pesce e il succo di lime.","Incorporare la polvere di riso tostato, il peperoncino, gli scalogni crudi rimasti, il cipollotto, il coriandolo e la menta e saltare per circa un minuto.","Assaggiare e bilanciare con sale, peperoncino, salsa di pesce o lime secondo necessità.","Distribuire con un cucchiaio nelle foglie di lattuga e cospargere con gli scalogni croccanti."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a7ed4529-c101-447e-8900-f9b038ec9bf2')
  returning id
)
