-- Chinese beef and broccoli
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '79682a8a-d507-4826-91a4-133add95113d'::uuid, null, 'Chinese beef and broccoli', 'seed', 'https://www.recipetineats.com/chinese-beef-and-broccoli/', 'RecipeTin Eats', '/recipe-photos/chinese-beef-and-broccoli.webp', 'https://www.recipetineats.com/tachyon/2015/03/Chinese-Beef-and-Broccoli_3.jpg',
    2, 3, 20, 10, 10, '["Stir the cornstarch into a little water until smooth, then mix in the sugar, both soy sauces, rice wine, five-spice, sesame oil and pepper.","Slice the beef thinly and toss it with about 1.5 tbsp of the sauce.","Heat the oil in a skillet or wok over high heat, spread the beef out and let it brown undisturbed for about 1 minute.","Toss the beef, add the garlic and ginger and stir-fry until the meat is no longer pink.","Pour in the rest of the sauce plus about 170 ml water and stir quickly.","Once bubbling, add the cooked broccoli, coat it in the sauce and simmer about 1 minute until glossy and thick.","Take off the heat and serve over rice, scattered with sesame seeds."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'quick']::text[], 'chinese', 425, 30.6,
    true, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Bœuf aux brocolis à la chinoise","steps":["Délayer la fécule de maïs dans un peu d''eau jusqu''à ce qu''elle soit lisse, puis incorporer le sucre, les deux sauces soja, le vin de riz, le cinq-épices, l''huile de sésame et le poivre.","Émincer finement le bœuf et le mélanger avec environ 1,5 c. à soupe de sauce.","Faire chauffer l''huile dans une poêle ou un wok à feu vif, étaler le bœuf et le laisser dorer sans y toucher environ 1 minute.","Remuer le bœuf, ajouter l''ail et le gingembre et faire sauter jusqu''à ce que la viande ne soit plus rosée.","Verser le reste de la sauce et environ 170 ml d''eau, et remuer rapidement.","Dès que ça bouillonne, ajouter les brocolis cuits, bien les enrober de sauce et laisser mijoter environ 1 minute jusqu''à ce que la sauce soit brillante et épaisse.","Retirer du feu et servir sur du riz, parsemé de graines de sésame."]},"it":{"title":"Manzo e broccoli alla cinese","steps":["Stemperare l''amido di mais in poca acqua fino a renderlo liscio, poi unire lo zucchero, le due salse di soia, il vino di riso, le cinque spezie, l''olio di sesamo e il pepe.","Affettare sottilmente il manzo e mescolarlo con circa 1,5 cucchiai di salsa.","Scaldare l''olio in una padella o nel wok a fuoco vivace, distribuire il manzo e lasciarlo rosolare senza toccarlo per circa 1 minuto.","Mescolare il manzo, aggiungere l''aglio e lo zenzero e saltare finché la carne non è più rosa.","Versare il resto della salsa e circa 170 ml d''acqua e mescolare rapidamente.","Quando bolle, aggiungere i broccoli cotti, ricoprirli di salsa e cuocere a fuoco lento per circa 1 minuto, finché la salsa è lucida e densa.","Togliere dal fuoco e servire sul riso, cospargendo di semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '79682a8a-d507-4826-91a4-133add95113d')
  returning id
)
