-- Chinese cashew chicken
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '28d94d63-942b-407b-b0b5-b31c5de37faa'::uuid, null, 'Chinese cashew chicken', 'seed', 'https://www.recipetineats.com/chinese-cashew-chicken/comment-page-24/', 'RecipeTin Eats', '/recipe-photos/chinese-cashew-chicken.webp', 'https://www.recipetineats.com/tachyon/2015/10/Cashew-Chicken_6.jpg',
    2, 4, 21, 15, 6, '["Whisk the cornstarch into the soy sauce until smooth, then add the rice wine, oyster sauce, sesame oil and white pepper.","Toss the chicken with about 1 tbsp of the sauce and leave at least 10 minutes.","Heat the oil in a wok over high heat and stir-fry the garlic and onion for about 1 minute.","Add the chicken and cook about 2 minutes, then add the bell pepper for another minute.","Pour in the remaining sauce with about 3 tbsp water and stir about 1 minute until it simmers and thickens.","Toss in the cashews, take off the heat and serve right away with rice."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'quick']::text[], 'chinese', 508, 28.9,
    true, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poulet aux noix de cajou à la chinoise","steps":["Délayer au fouet la fécule de maïs dans la sauce soja jusqu''à ce qu''elle soit lisse, puis ajouter le vin de riz, la sauce d''huître, l''huile de sésame et le poivre blanc.","Mélanger le poulet avec environ 1 c. à soupe de sauce et laisser reposer au moins 10 minutes.","Faire chauffer l''huile dans un wok à feu vif et faire sauter l''ail et l''oignon environ 1 minute.","Ajouter le poulet et cuire environ 2 minutes, puis ajouter le poivron et cuire encore une minute.","Verser le reste de la sauce avec environ 3 c. à soupe d''eau et remuer environ 1 minute jusqu''à ce qu''elle frémisse et épaississe.","Ajouter les noix de cajou, mélanger, retirer du feu et servir aussitôt avec du riz."]},"it":{"title":"Pollo agli anacardi alla cinese","steps":["Sbattere con una frusta l''amido di mais nella salsa di soia fino a renderlo liscio, poi aggiungere il vino di riso, la salsa di ostriche, l''olio di sesamo e il pepe bianco.","Mescolare il pollo con circa 1 cucchiaio di salsa e lasciar riposare almeno 10 minuti.","Scaldare l''olio nel wok a fuoco vivace e saltare l''aglio e la cipolla per circa 1 minuto.","Aggiungere il pollo e cuocere per circa 2 minuti, poi aggiungere il peperone per un altro minuto.","Versare la salsa rimasta con circa 3 cucchiai d''acqua e mescolare per circa 1 minuto, finché sobbolle e si addensa.","Unire gli anacardi, mescolare, togliere dal fuoco e servire subito con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '28d94d63-942b-407b-b0b5-b31c5de37faa')
  returning id
)
