-- Cá kho (Vietnamese caramelised braised mackerel)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '2d025e3c-c006-4ef1-873b-677587924532'::uuid, null, 'Cá kho (Vietnamese caramelised braised mackerel)', 'seed', 'https://delightfulplate.com/?p=84242', 'Delightful Plate', '/recipe-photos/ca-kho-vietnamese-caramelised-braised-mackerel.webp', 'https://delightfulplate.com/wp-content/uploads/2024/11/Ca-Kho-Recipe-Traditional-Vietnamese-Caramelized-Fish.jpg',
    2, 4, 135, 15, 120, '["Cut the mackerel into thick steaks of about 4 cm, discarding the heads; rub with salt, rinse and pat dry.","Melt the sugar with a splash of water in a small pan and let it bubble, then lower the heat and cook until it turns a dark caramel colour.","Take the caramel off the heat and carefully stir in about 140 ml water to make a dark amber braising liquid.","Line a heavy pot with galangal, shallot and most of the tomato, lay the fish on top in one layer and scatter over the rest of the aromatics, tomato and chili.","Add the fish sauce, soy sauce, caramel liquid and black pepper; top up with a little water so the fish is just covered.","Bring to a boil, add the lime juice, then cover and simmer gently for about 1½ hours, basting the fish from time to time (add hot water if it dries out).","Uncover, taste, and keep braising with the lid ajar until only a thin layer of glossy sauce coats the bottom of the pot.","Serve with steamed rice."]'::jsonb,
    array['asian', 'vietnamese', 'stew', 'comfort', 'high protein']::text[], 'vietnamese', 855, 54,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Cá kho (maquereau braisé au caramel à la vietnamienne)","steps":["Couper le maquereau en tranches épaisses d''environ 4 cm en jetant les têtes ; frotter de sel, rincer et sécher en tamponnant.","Faire fondre le sucre avec un peu d''eau dans une petite casserole et laisser bouillonner, puis baisser le feu et cuire jusqu''à obtenir un caramel foncé.","Retirer le caramel du feu et y incorporer prudemment environ 140 ml d''eau pour obtenir un liquide de braisage ambré foncé.","Tapisser le fond d''une cocotte à fond épais de galanga, d''échalote et de la majeure partie de la tomate, poser le poisson dessus en une seule couche et répartir le reste des aromates, de la tomate et le piment.","Ajouter la sauce poisson, la sauce soja, le caramel et le poivre noir ; compléter avec un peu d''eau pour que le poisson soit tout juste couvert.","Porter à ébullition, ajouter le jus de citron vert, puis couvrir et laisser mijoter doucement environ 1 heure et demie, en arrosant le poisson de temps en temps (ajouter de l''eau chaude si ça accroche).","Découvrir, goûter et poursuivre le braisage couvercle entrouvert jusqu''à ce qu''il ne reste qu''une fine couche de sauce brillante au fond de la cocotte.","Servir avec du riz vapeur."]},"it":{"title":"Cá kho (sgombro brasato al caramello alla vietnamita)","steps":["Tagliare lo sgombro in tranci spessi circa 4 cm, eliminando le teste; strofinarli con il sale, sciacquarli e tamponarli.","Sciogliere lo zucchero con un goccio d''acqua in un pentolino e lasciarlo bollire, poi abbassare la fiamma e cuocere finché diventa un caramello scuro.","Togliere il caramello dal fuoco e incorporare con cautela circa 140 ml d''acqua per ottenere un liquido di cottura ambrato scuro.","Foderare il fondo di una pentola dal fondo spesso con galanga, scalogno e gran parte del pomodoro, adagiarvi sopra il pesce in un solo strato e distribuire il resto degli aromi, del pomodoro e il peperoncino.","Aggiungere la salsa di pesce, la salsa di soia, il caramello e il pepe nero; aggiungere un po'' d''acqua in modo che il pesce sia appena coperto.","Portare a ebollizione, aggiungere il succo di lime, poi coprire e cuocere a fuoco lento per circa 1 ora e mezza, bagnando il pesce di tanto in tanto (aggiungere acqua calda se si asciuga).","Scoprire, assaggiare e continuare la cottura con il coperchio socchiuso finché resta solo un velo di salsa lucida sul fondo della pentola.","Servire con riso al vapore."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '2d025e3c-c006-4ef1-873b-677587924532')
  returning id
)
