-- Filipino chicken adobo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7604daa9-9518-4943-8ab8-875c445fe5b9'::uuid, null, 'Filipino chicken adobo', 'seed', 'https://panlasangpinoy.com/filipino-chicken-adobo-recipe', 'Panlasang Pinoy', '/recipe-photos/filipino-chicken-adobo.webp', 'https://panlasangpinoy.com/wp-content/uploads/2026/05/Chicken-Adobo-in-a-Bowl.jpg',
    2, 4, 120, 10, 50, '["Crush the garlic in a mortar, then combine with the chicken and soy sauce and marinate for at least 1 hour.","Lift the chicken out, keeping the marinade and garlic separately.","Heat most of the oil in a pot and sear the chicken for about 2 minutes per side; set aside.","Add the rest of the oil and the marinated garlic and fry until it just starts to colour.","Return the chicken with the leftover marinade, peppercorns, bay leaves and about 180 ml water; bring to a boil, cover and simmer for about 30 minutes until tender.","Pour in the vinegar and let it boil for 1 minute without stirring, then stir and simmer uncovered for 15 minutes to reduce.","Season with sugar and salt and serve hot with rice."]'::jsonb,
    array['asian', 'filipino', 'stew', 'comfort', 'high protein']::text[], 'filipino', 839, 47.9,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Adobo de poulet philippin","steps":["Écraser l''ail au mortier, puis le mélanger avec le poulet et la sauce soja et laisser mariner au moins 1 heure.","Retirer le poulet en réservant séparément la marinade et l''ail.","Faire chauffer la majeure partie de l''huile dans une cocotte et saisir le poulet environ 2 minutes par face ; réserver.","Ajouter le reste de l''huile et l''ail mariné et le faire revenir jusqu''à ce qu''il commence tout juste à colorer.","Remettre le poulet avec le reste de la marinade, les grains de poivre, les feuilles de laurier et environ 180 ml d''eau ; porter à ébullition, couvrir et laisser mijoter environ 30 minutes jusqu''à ce qu''il soit tendre.","Verser le vinaigre et laisser bouillir 1 minute sans remuer, puis remuer et laisser mijoter 15 minutes à découvert pour réduire.","Assaisonner avec le sucre et le sel et servir chaud avec du riz."]},"it":{"title":"Adobo di pollo alla filippina","steps":["Schiacciare l''aglio nel mortaio, poi unirlo al pollo e alla salsa di soia e lasciar marinare per almeno 1 ora.","Togliere il pollo, tenendo da parte separatamente la marinata e l''aglio.","Scaldare la maggior parte dell''olio in una pentola e rosolare il pollo per circa 2 minuti per lato; tenere da parte.","Aggiungere il resto dell''olio e l''aglio marinato e soffriggere finché inizia appena a colorirsi.","Rimettere il pollo con la marinata rimasta, i grani di pepe, le foglie di alloro e circa 180 ml d''acqua; portare a ebollizione, coprire e cuocere a fuoco lento per circa 30 minuti, finché è tenero.","Versare l''aceto e lasciar bollire per 1 minuto senza mescolare, poi mescolare e cuocere a fuoco lento senza coperchio per 15 minuti per far ridurre.","Insaporire con zucchero e sale e servire caldo con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7604daa9-9518-4943-8ab8-875c445fe5b9')
  returning id
)
