-- Gyudon (beef and onion rice bowl)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '25a49043-ae42-4755-8b99-fe6b204a5964'::uuid, null, 'Gyudon (beef and onion rice bowl)', 'seed', 'https://thewoksoflife.com/gyudon-recipe-beef-rice/', 'The Woks of Life', '/recipe-photos/gyudon-beef-and-onion-rice-bowl.webp', 'https://thewoksoflife.com/wp-content/uploads/2023/07/gyudon-7.jpg',
    2, 4, 40, 10, 30, '["Cook the rice.","Heat half the oil in a pan over medium-high heat and cook the onions about 10 minutes, stirring often, until soft.","Add the beef and sugar and stir until the beef is lightly browned.","Pour in the mirin, soy sauce and dashi and simmer 10–15 minutes until reduced to a thin sauce; taste and adjust.","Meanwhile fry the eggs sunny-side up in another pan with the remaining oil, keeping the yolks runny.","Spoon rice into bowls, pile on the beef and onions with some sauce, top each with an egg and finish with spring onion and sesame seeds."]'::jsonb,
    array['japanese', 'asian', 'bowl', 'comfort', 'high protein']::text[], 'japanese', 703, 38.1,
    true, 'en', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Gyudon (bol de riz au bœuf et aux oignons)","steps":["Faire cuire le riz.","Faire chauffer la moitié de l''huile dans une poêle à feu moyen-vif et faire cuire les oignons environ 10 minutes en remuant souvent, jusqu''à ce qu''ils soient tendres.","Ajouter le bœuf et le sucre et remuer jusqu''à ce que le bœuf soit légèrement doré.","Verser le mirin, la sauce soja et le dashi et laisser mijoter 10–15 minutes jusqu''à obtenir une sauce légère ; goûter et rectifier.","Pendant ce temps, faire cuire les œufs au plat dans une autre poêle avec le reste de l''huile, en gardant les jaunes coulants.","Répartir le riz dans des bols, y disposer le bœuf et les oignons avec un peu de sauce, déposer un œuf sur chaque bol et parsemer d''oignon nouveau et de graines de sésame."]},"it":{"title":"Gyudon (ciotola di riso con manzo e cipolle)","steps":["Cuocere il riso.","Scaldare metà dell''olio in una padella a fuoco medio-alto e cuocere le cipolle per circa 10 minuti, mescolando spesso, finché non sono morbide.","Aggiungere il manzo e lo zucchero e mescolare finché la carne non è leggermente rosolata.","Versare il mirin, la salsa di soia e il dashi e cuocere a fuoco lento per 10–15 minuti finché non si riduce a una salsa leggera; assaggiare e regolare.","Nel frattempo cuocere le uova all''occhio di bue in un''altra padella con l''olio rimasto, lasciando i tuorli morbidi.","Distribuire il riso nelle ciotole, adagiarvi sopra il manzo e le cipolle con un po'' di salsa, completare ciascuna con un uovo e finire con cipollotto e semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '25a49043-ae42-4755-8b99-fe6b204a5964')
  returning id
)
