-- Gà nướng sả (Vietnamese lemongrass grilled chicken)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '63ace58e-5c2b-45c1-9b70-599b42c3908e'::uuid, null, 'Gà nướng sả (Vietnamese lemongrass grilled chicken)', 'seed', 'https://www.vietnamesefoodrecipes.com/vietnamese-grilled-chicken-with-lemongrass-ga-nuong-sa/', 'Vietnamese Food Recipes', '/recipe-photos/ga-nuong-sa-vietnamese-lemongrass-grilled-chicken.webp', 'https://www.vietnamesefoodrecipes.com/wp-content/uploads/2025/06/IMG_1293.jpg',
    2, 4, 240, 195, 45, '["Whisk all the marinade ingredients together in a bowl.","Coat the chicken well and refrigerate for at least 3 hours, ideally overnight.","Heat the grill (or a grill pan) to about 200°C.","Grill the chicken, turning now and then, until charred on both sides and 74°C in the thickest part.","Rest for 5 minutes, then slice.","Serve hot with rice or rice vermicelli."]'::jsonb,
    array['asian', 'vietnamese', 'grill', 'make ahead', 'high protein']::text[], 'vietnamese', 742, 51.9,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":["thermometer","barbecue"]}'::jsonb, false,
    '{"fr":{"title":"Gà nướng sả (poulet grillé vietnamien à la citronnelle)","steps":["Fouetter ensemble tous les ingrédients de la marinade dans un bol.","Bien enrober le poulet et le laisser au réfrigérateur au moins 3 heures, idéalement toute une nuit.","Faire chauffer le barbecue (ou une poêle-gril) à environ 200 °C.","Faire griller le poulet en le retournant de temps en temps, jusqu''à ce qu''il soit bien grillé des deux côtés et atteigne 74 °C dans la partie la plus épaisse.","Laisser reposer 5 minutes, puis trancher.","Servir chaud avec du riz ou des vermicelles de riz."]},"it":{"title":"Gà nướng sả (pollo vietnamita alla griglia con citronella)","steps":["Sbattere insieme in una ciotola tutti gli ingredienti della marinata.","Ricoprire bene il pollo e metterlo in frigorifero per almeno 3 ore, meglio ancora per tutta la notte.","Scaldare la griglia (o una bistecchiera) a circa 200 °C.","Grigliare il pollo, girandolo di tanto in tanto, finché non è abbrustolito su entrambi i lati e raggiunge 74 °C nella parte più spessa.","Lasciare riposare per 5 minuti, poi affettare.","Servire caldo con riso o vermicelli di riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '63ace58e-5c2b-45c1-9b70-599b42c3908e')
  returning id
)
