-- Healthy chicken tikka masala with spinach
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '60542698-8098-4b4a-9ff6-37e012332afc'::uuid, null, 'Healthy chicken tikka masala with spinach', 'seed', 'https://bbcgoodfoodme.com/recipes/healthy-tikka-masala', 'BBC Good Food', '/recipe-photos/healthy-chicken-tikka-masala-with-spinach.webp', 'https://www.bbcgoodfoodme.com/assets/legacy/recipe/recipe-image/2019/10/healthy-tikka-masala.jpg',
    2, 4, 65, 15, 45, '["Blend the onion, garlic and ginger into a smooth paste.","Fry the paste in half the oil over medium heat for about 15 minutes until golden and sweet; scrape it out and wipe the pan.","Brown the chicken in the rest of the oil, then stir in the tikka spice and cayenne.","Add back the onion paste with the tomatoes and about 200 ml water and simmer uncovered for 15 minutes.","Stir in the ground almonds and spinach and cook 10 minutes more.","Season, take off the heat, stir through the yogurt and coriander and serve with brown basmati rice."]'::jsonb,
    array['asian', 'indian', 'curry', 'light', 'high protein']::text[], 'indian', 689, 47.4,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":["blender"]}'::jsonb, false,
    '{"fr":{"title":"Poulet tikka masala léger aux épinards","steps":["Mixer l''oignon, l''ail et le gingembre jusqu''à obtenir une pâte lisse.","Faire revenir la pâte dans la moitié de l''huile à feu moyen pendant environ 15 minutes jusqu''à ce qu''elle soit dorée et sucrée ; la retirer en raclant la poêle, puis essuyer celle-ci.","Faire dorer le poulet dans le reste de l''huile, puis incorporer les épices tikka et le piment de Cayenne.","Remettre la pâte d''oignon avec les tomates et environ 200 ml d''eau et laisser mijoter 15 minutes à découvert.","Incorporer la poudre d''amandes et les épinards et poursuivre la cuisson 10 minutes.","Saler, retirer du feu, incorporer le yaourt et la coriandre et servir avec du riz basmati complet."]},"it":{"title":"Pollo tikka masala leggero con spinaci","steps":["Frullare la cipolla, l''aglio e lo zenzero fino a ottenere una pasta liscia.","Soffriggere la pasta in metà dell''olio a fuoco medio per circa 15 minuti finché non è dorata e dolce; raccoglierla raschiando la padella e pulire la padella.","Rosolare il pollo nell''olio rimasto, poi unire le spezie tikka e il pepe di Caienna.","Rimettere la pasta di cipolla con i pomodori e circa 200 ml d''acqua e cuocere a fuoco lento senza coperchio per 15 minuti.","Unire le mandorle tritate e gli spinaci e cuocere per altri 10 minuti.","Regolare di sale, togliere dal fuoco, incorporare lo yogurt e il coriandolo e servire con riso basmati integrale."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '60542698-8098-4b4a-9ff6-37e012332afc')
  returning id
)
