-- Oven tandoori chicken
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '52ce91db-4179-47c8-8c68-268c31a607be'::uuid, null, 'Oven tandoori chicken', 'seed', 'https://www.indianhealthyrecipes.com/tandoori-chicken/', 'Swasthi''s Recipes', '/recipe-photos/oven-tandoori-chicken.webp', 'https://www.indianhealthyrecipes.com/wp-content/uploads/2025/09/tandoori-chicken-recipe-new.jpg',
    2, 4, 415, 15, 40, '["Mix the yogurt, ginger-garlic paste, ground spices, salt, fenugreek leaves, oil and lemon juice; taste and adjust salt and heat.","Cut 2–3 deep slits into each piece of chicken, coat thoroughly in the marinade and refrigerate for 6 hours or overnight.","Take the chicken out of the fridge 20 minutes before cooking and heat the oven to 240°C.","Stir together the chili powder and oil for the chili oil.","Set an oiled rack over a foil-lined tray, space the chicken out on it and roast for 15 minutes; baste with leftover marinade or chili oil.","Turn the pieces and roast another 12–15 minutes, then brush with chili oil.","Move to the top shelf under the grill for 3–4 minutes until lightly charred; the thickest part should reach 75°C.","Garnish with coriander and serve with onion, cucumber and lemon wedges."]'::jsonb,
    array['asian', 'indian', 'oven', 'grill', 'make ahead', 'high protein']::text[], 'indian', 493, 37.9,
    true, 'en', 'medium', '{"pots":1,"oven":true,"special":["thermometer"]}'::jsonb, false,
    '{"fr":{"title":"Poulet tandoori au four","steps":["Mélanger le yaourt, la pâte gingembre-ail, les épices moulues, le sel, les feuilles de fenugrec, l''huile et le jus de citron ; goûter et rectifier le sel et le piquant.","Faire 2–3 entailles profondes dans chaque morceau de poulet, bien l''enrober de marinade et réserver au réfrigérateur 6 heures ou toute une nuit.","Sortir le poulet du réfrigérateur 20 minutes avant la cuisson et préchauffer le four à 240 °C.","Mélanger le piment en poudre et l''huile pour l''huile pimentée.","Poser une grille huilée sur une plaque tapissée de papier aluminium, y disposer le poulet en espaçant les morceaux et enfourner 15 minutes ; badigeonner avec le reste de marinade ou d''huile pimentée.","Retourner les morceaux et poursuivre la cuisson 12–15 minutes, puis badigeonner d''huile pimentée.","Placer en haut du four sous le gril pendant 3–4 minutes jusqu''à ce que le poulet soit légèrement grillé ; la partie la plus épaisse doit atteindre 75 °C.","Parsemer de coriandre et servir avec de l''oignon, du concombre et des quartiers de citron."]},"it":{"title":"Pollo tandoori al forno","steps":["Mescolare lo yogurt, la pasta di zenzero e aglio, le spezie macinate, il sale, le foglie di fieno greco, l''olio e il succo di limone; assaggiare e regolare di sale e piccantezza.","Praticare 2–3 tagli profondi in ogni pezzo di pollo, ricoprirlo bene con la marinata e lasciarlo in frigorifero per 6 ore o per tutta la notte.","Togliere il pollo dal frigorifero 20 minuti prima della cottura e preriscaldare il forno a 240 °C.","Mescolare il peperoncino in polvere e l''olio per l''olio piccante.","Sistemare una griglia unta su una teglia rivestita di carta stagnola, disporvi il pollo ben distanziato e cuocere in forno per 15 minuti; spennellare con la marinata avanzata o con l''olio piccante.","Girare i pezzi e cuocere per altri 12–15 minuti, poi spennellare con l''olio piccante.","Spostare sul ripiano più alto sotto il grill per 3–4 minuti finché non è leggermente abbrustolito; la parte più spessa deve raggiungere 75 °C.","Guarnire con il coriandolo e servire con cipolla, cetriolo e spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '52ce91db-4179-47c8-8c68-268c31a607be')
  returning id
)
