-- Pad krapow gai (Thai basil chicken with fried egg)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b47b1a25-61a8-4ea7-8e06-77330e0d02d0'::uuid, null, 'Pad krapow gai (Thai basil chicken with fried egg)', 'seed', 'https://eatingthaifood.com/thai-basil-chicken-recipe', 'Eating Thai Food', '/recipe-photos/pad-krapow-gai-thai-basil-chicken-with-fried-egg.webp', 'https://www.eatingthaifood.com/wp-content/uploads/2014/01/thai-chicken-basil-recipe.jpg',
    2, 1, 20, 10, 10, '["Fry the eggs in a wok in the frying oil, basting the tops with hot oil instead of flipping, until the edges are crisp; drain and keep aside.","Cut the chicken into bite-sized pieces; roughly pound the garlic and chilies in a mortar (or mince them) and pick the basil leaves.","Heat the wok over high heat with the stir-fry oil and toss the garlic and chili for about 20 seconds until fragrant, without letting them burn.","Add the chicken and stir-fry until almost cooked through, adding a tiny splash of water if the pan gets dry.","Season with oyster sauce, light and dark soy sauce and sugar, and keep tossing for about 30 seconds.","Throw in the holy basil, fold it through and take the wok off the heat as soon as it wilts.","Serve over steamed jasmine rice with the fried egg on top."]'::jsonb,
    array['asian', 'thai', 'stir-fry', 'quick', 'high protein']::text[], 'thai', 1055, 60.2,
    true, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Pad krapow gai (poulet thaï au basilic et œuf frit)","steps":["Faire frire les œufs au wok dans l''huile de friture, en arrosant le dessus d''huile chaude au lieu de les retourner, jusqu''à ce que les bords soient croustillants ; égoutter et réserver.","Couper le poulet en bouchées ; piler grossièrement l''ail et les piments au mortier (ou les hacher) et effeuiller le basilic.","Faire chauffer le wok à feu vif avec l''huile de cuisson et faire sauter l''ail et le piment environ 20 secondes jusqu''à ce qu''ils embaument, sans les laisser brûler.","Ajouter le poulet et le faire sauter jusqu''à ce qu''il soit presque cuit, en ajoutant une goutte d''eau si le wok devient trop sec.","Assaisonner avec la sauce d''huître, les sauces soja claire et foncée et le sucre, et continuer à faire sauter environ 30 secondes.","Ajouter le basilic sacré, l''incorporer et retirer le wok du feu dès qu''il flétrit.","Servir sur du riz jasmin cuit à la vapeur, avec l''œuf frit par-dessus."]},"it":{"title":"Pad krapow gai (pollo thai al basilico con uovo fritto)","steps":["Friggere le uova nel wok con l''olio per friggere, irrorando la superficie con l''olio caldo invece di girarle, finché i bordi non sono croccanti; scolarle e tenerle da parte.","Tagliare il pollo a bocconcini; pestare grossolanamente l''aglio e i peperoncini nel mortaio (o tritarli) e staccare le foglie di basilico.","Scaldare il wok a fuoco vivo con l''olio per saltare e far saltare l''aglio e il peperoncino per circa 20 secondi finché non sprigionano il loro aroma, senza farli bruciare.","Aggiungere il pollo e saltarlo finché non è quasi cotto, aggiungendo un goccio d''acqua se il wok si asciuga troppo.","Condire con la salsa di ostriche, la salsa di soia chiara e quella scura e lo zucchero, e continuare a saltare per circa 30 secondi.","Unire il basilico sacro, mescolarlo e togliere il wok dal fuoco appena appassisce.","Servire su riso jasmine cotto al vapore con l''uovo fritto sopra."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b47b1a25-61a8-4ea7-8e06-77330e0d02d0')
  returning id
)
