-- Satay chicken drumsticks with peanut sauce
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7b6d0406-a5ed-4bfa-839a-a993a3868f64'::uuid, null, 'Satay chicken drumsticks with peanut sauce', 'seed', 'https://www.recipetineats.com/satay-chicken-legs-with-peanut-sauce/', 'RecipeTin Eats', '/recipe-photos/satay-chicken-drumsticks-with-peanut-sauce.webp', 'https://www.recipetineats.com/tachyon/2026/08/Satay-chicken-legs-with-peanut-sauce-v2-3.jpg',
    2, 4, 235, 10, 45, '["Cut three shallow slashes (about 5 mm deep) into the meaty side of each drumstick.","Stir together the marinade ingredients, coat the drumsticks and work the mixture into the cuts; marinate 3 hours or overnight in the fridge (optional but best).","Heat the oven to 200°C (180°C fan) and set a rack over a foil-lined tray.","Lay the drumsticks on the rack and dab any remaining marinade on top.","Bake for 35 minutes, then switch to the grill on high for 3–5 minutes to char the skin.","Meanwhile whisk all the sauce ingredients in a small pan and simmer on medium-low for about 5 minutes, stirring, until it is pourable but coats a spoon; keep warm.","Serve the drumsticks with jasmine rice and the peanut sauce for dipping."]'::jsonb,
    array['asian', 'thai', 'oven', 'make ahead', 'high protein']::text[], 'thai', 1249, 80.5,
    true, 'en', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Pilons de poulet satay, sauce cacahuète","steps":["Pratiquer trois entailles peu profondes (environ 5 mm) sur le côté charnu de chaque pilon.","Mélanger les ingrédients de la marinade, en enrober les pilons et faire pénétrer le mélange dans les entailles ; laisser mariner 3 heures ou toute une nuit au réfrigérateur (facultatif, mais c''est meilleur).","Préchauffer le four à 200 °C (180 °C chaleur tournante) et poser une grille sur une plaque tapissée de papier aluminium.","Disposer les pilons sur la grille et répartir le reste de marinade sur le dessus en tapotant.","Enfourner 35 minutes, puis passer en position gril, puissance maximale, pendant 3–5 minutes pour faire griller la peau.","Pendant ce temps, fouetter tous les ingrédients de la sauce dans une petite casserole et laisser mijoter à feu moyen-doux environ 5 minutes en remuant, jusqu''à ce qu''elle soit fluide mais nappe la cuillère ; garder au chaud.","Servir les pilons avec du riz jasmin et la sauce cacahuète pour les tremper."]},"it":{"title":"Fusi di pollo satay con salsa di arachidi","steps":["Praticare tre tagli poco profondi (circa 5 mm) sul lato più carnoso di ogni fuso.","Mescolare gli ingredienti della marinata, ricoprire i fusi e far penetrare il composto nei tagli; marinare per 3 ore o per tutta la notte in frigorifero (facoltativo ma consigliato).","Preriscaldare il forno a 200 °C (180 °C ventilato) e sistemare una griglia su una teglia rivestita di carta stagnola.","Disporre i fusi sulla griglia e distribuire sopra la marinata rimasta.","Cuocere in forno per 35 minuti, poi passare alla funzione grill al massimo per 3–5 minuti per abbrustolire la pelle.","Nel frattempo sbattere tutti gli ingredienti della salsa in un pentolino e cuocere a fuoco medio-basso per circa 5 minuti, mescolando, finché non è fluida ma vela il cucchiaio; tenere in caldo.","Servire i fusi con riso jasmine e la salsa di arachidi per intingerli."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7b6d0406-a5ed-4bfa-839a-a993a3868f64')
  returning id
)
