-- Taiwanese three cup chicken
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '57abb0a5-0fc5-4e5e-b5e7-7130b2e204ed'::uuid, null, 'Taiwanese three cup chicken', 'seed', 'https://www.recipetineats.com/taiwanese-three-cup-chicken/', 'RecipeTin Eats', '/recipe-photos/taiwanese-three-cup-chicken.webp', 'https://www.recipetineats.com/tachyon/2026/07/Taiwanese-Three-Cup-Chicken-9a.jpg',
    2, 4, 20, 8, 10, '["Mix the light and dark soy, sugar and rice wine in a small bowl.","Warm the oil in a non-stick pan over medium-low and sizzle the ginger and chili for about 30 seconds.","Turn the heat to high, add the chicken and cook until the outside turns white though still raw inside; add the garlic and stir 30 seconds.","Pour in the sauce, bring to a bubble, then lower to medium/medium-high for a steady simmer.","Simmer about 5 minutes, stirring, until the chicken is coloured and the sauce has reduced to a thin syrup (add a splash of water if it reduces too fast).","Stir in the sesame oil and basil until the leaves wilt, then serve on rice with all the pan syrup."]'::jsonb,
    array['taiwanese', 'asian', 'stir-fry', 'quick']::text[], 'taiwanese', 448, 28.8,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poulet trois tasses taïwanais","steps":["Mélanger les sauces soja claire et foncée, le sucre et le vin de riz dans un petit bol.","Faire chauffer l''huile dans une poêle antiadhésive à feu moyen-doux et faire grésiller le gingembre et le piment environ 30 secondes.","Monter à feu vif, ajouter le poulet et le faire cuire jusqu''à ce que l''extérieur blanchisse tout en restant cru à l''intérieur ; ajouter l''ail et remuer 30 secondes.","Verser la sauce, porter à frémissement, puis baisser à feu moyen/moyen-vif pour un frémissement régulier.","Laisser mijoter environ 5 minutes en remuant, jusqu''à ce que le poulet soit coloré et que la sauce ait réduit en un sirop léger (ajouter un peu d''eau si elle réduit trop vite).","Incorporer l''huile de sésame et le basilic jusqu''à ce que les feuilles flétrissent, puis servir sur du riz avec tout le sirop de la poêle."]},"it":{"title":"Pollo tre tazze taiwanese","steps":["Mescolare in una ciotolina la salsa di soia chiara e quella scura, lo zucchero e il vino di riso.","Scaldare l''olio in una padella antiaderente a fuoco medio-basso e far sfrigolare lo zenzero e il peperoncino per circa 30 secondi.","Alzare la fiamma al massimo, aggiungere il pollo e cuocerlo finché l''esterno non diventa bianco pur restando crudo all''interno; aggiungere l''aglio e mescolare per 30 secondi.","Versare la salsa, portare a bollore, poi abbassare a fuoco medio/medio-alto per mantenere un sobbollire costante.","Cuocere a fuoco lento per circa 5 minuti, mescolando, finché il pollo non ha preso colore e la salsa non si è ridotta a uno sciroppo leggero (aggiungere un goccio d''acqua se si riduce troppo in fretta).","Unire l''olio di sesamo e il basilico finché le foglie non appassiscono, poi servire sul riso con tutto lo sciroppo della padella."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '57abb0a5-0fc5-4e5e-b5e7-7130b2e204ed')
  returning id
)
