-- Thai green curry with chicken
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '133f9e39-76f2-420d-954d-e311510897f2'::uuid, null, 'Thai green curry with chicken', 'seed', 'https://www.recipetineats.com/thai-green-curry/', 'RecipeTin Eats', '/recipe-photos/thai-green-curry-with-chicken.webp', 'https://www.recipetineats.com/tachyon/2019/02/Thai-Green-Curry_5.jpg',
    2, 4, 35, 15, 20, '["Heat the oil in a heavy pan over medium-high heat.","Fry the green curry paste with the garlic, ginger and lemongrass for 2–3 minutes until most of the moisture has cooked off (keep your face away from the fumes).","Pour in the stock and coconut milk and stir until the paste dissolves.","Season with the fish sauce and sugar, add the lime leaves and bring to a simmer.","Add the chicken, turn the heat down to a gentle bubble and cook for 7 minutes.","Add the eggplant and simmer about 5 minutes until soft; taste and adjust salt and sweetness.","Add the snow peas for 2 minutes, then stir in the basil and lime juice and take off the heat straight away.","Serve over jasmine rice."]'::jsonb,
    array['asian', 'thai', 'curry', 'comfort']::text[], 'thai', 787, 27.4,
    true, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Curry vert thaï au poulet","steps":["Faire chauffer l''huile dans une casserole à fond épais à feu moyen-vif.","Faire revenir la pâte de curry vert avec l''ail, le gingembre et la citronnelle pendant 2–3 minutes jusqu''à ce que la majeure partie de l''humidité se soit évaporée (garder le visage à l''écart des vapeurs).","Verser le bouillon et le lait de coco et remuer jusqu''à ce que la pâte soit dissoute.","Assaisonner avec la sauce poisson et le sucre, ajouter les feuilles de citron kaffir et porter à frémissement.","Ajouter le poulet, baisser le feu pour obtenir un léger frémissement et cuire 7 minutes.","Ajouter l''aubergine et laisser mijoter environ 5 minutes jusqu''à ce qu''elle soit tendre ; goûter et rectifier le sel et le sucre.","Ajouter les pois gourmands pendant 2 minutes, puis incorporer le basilic et le jus de citron vert et retirer aussitôt du feu.","Servir sur du riz jasmin."]},"it":{"title":"Curry verde thai con pollo","steps":["Scaldare l''olio in una pentola dal fondo spesso a fuoco medio-alto.","Soffriggere la pasta di curry verde con l''aglio, lo zenzero e la citronella per 2–3 minuti finché gran parte dell''umidità non è evaporata (tenere il viso lontano dai vapori).","Versare il brodo e il latte di cocco e mescolare finché la pasta non si scioglie.","Condire con la salsa di pesce e lo zucchero, aggiungere le foglie di lime kaffir e portare a bollore leggero.","Aggiungere il pollo, abbassare la fiamma per un sobbollire delicato e cuocere per 7 minuti.","Aggiungere la melanzana e cuocere a fuoco lento per circa 5 minuti finché non è morbida; assaggiare e regolare di sale e dolcezza.","Aggiungere le taccole per 2 minuti, poi unire il basilico e il succo di lime e togliere subito dal fuoco.","Servire su riso jasmine."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '133f9e39-76f2-420d-954d-e311510897f2')
  returning id
)
