-- Cajun salmon and sweet potato chowder
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '259ada42-4c9b-4936-88ec-79c0ba6bb82b'::uuid, null, 'Cajun salmon and sweet potato chowder', 'seed', 'https://www.weightwatchers.com/us/recipe/cajun-salmon-sweet-potato-chowder/56d82afd0ac646df0ee3e08f', 'WW', null, null,
    2, 4, 35, 15, 20, '["Heat the oil in a saucepan over medium-high heat, add the carrot, onion and celery, cover and cook about 5 minutes until softened.","Add the bell pepper and Cajun seasoning and cook 2 minutes more.","Add the sweet potato, stock and about 120 ml water, bring to a boil, then cover and simmer about 10 minutes until the potato is tender.","Add the salmon and corn and simmer about 3 minutes until the fish is just opaque in the centre.","Turn the heat to low, stir in the half-and-half, basil and salt and warm through for 1 minute.","Take off the heat, stir in the lemon juice and serve."]'::jsonb,
    array['american', 'soup', 'light']::text[], 'american', 433, 29.8,
    true, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Chaudrée de saumon cajun et patate douce","steps":["Faire chauffer l''huile dans une casserole à feu moyen-vif, ajouter la carotte, l''oignon et le céleri, couvrir et cuire environ 5 minutes jusqu''à ce qu''ils soient tendres.","Ajouter le poivron et l''assaisonnement cajun et poursuivre la cuisson 2 minutes.","Ajouter la patate douce, le bouillon et environ 120 ml d''eau, porter à ébullition, puis couvrir et laisser mijoter environ 10 minutes jusqu''à ce que la patate douce soit tendre.","Ajouter le saumon et le maïs et laisser mijoter environ 3 minutes jusqu''à ce que le poisson soit tout juste opaque à cœur.","Baisser à feu doux, incorporer le mélange lait-crème, le basilic et le sel et réchauffer 1 minute.","Retirer du feu, incorporer le jus de citron et servir."]},"it":{"title":"Zuppa cremosa di salmone cajun e patate dolci","steps":["Scaldare l''olio in una casseruola a fuoco medio-alto, aggiungere la carota, la cipolla e il sedano, coprire e cuocere per circa 5 minuti finché non si ammorbidiscono.","Aggiungere il peperone e il condimento cajun e cuocere per altri 2 minuti.","Aggiungere la patata dolce, il brodo e circa 120 ml d''acqua, portare a bollore, poi coprire e cuocere a fuoco lento per circa 10 minuti finché la patata non è tenera.","Aggiungere il salmone e il mais e cuocere a fuoco lento per circa 3 minuti finché il pesce non è appena opaco al centro.","Abbassare la fiamma al minimo, unire la miscela di latte e panna, il basilico e il sale e scaldare per 1 minuto.","Togliere dal fuoco, unire il succo di limone e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '259ada42-4c9b-4936-88ec-79c0ba6bb82b')
  returning id
)
