-- Cajun salmon with sweet potato wedges
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd939ecdf-9a41-49f5-87f1-33289d9daeea'::uuid, null, 'Cajun salmon with sweet potato wedges', 'seed', 'https://www.olivemagazine.com/recipes/fish-and-seafood/cajun-salmon-with-rosemary-sweet-potato-wedges/', 'Olive Magazine', '/recipe-photos/cajun-salmon-with-sweet-potato-wedges.webp', 'https://images.immediate.co.uk/production/volatile/sites/2/2018/08/Cajun-salmon-f26325e.jpg?resize=1200%2C630',
    2, 2, 40, 10, 30, '["Heat the oven to 200C (180C fan).","Toss the wedges on a non-stick tray with half the oil, the rosemary and some salt and roast 25-30 minutes until crisp outside and soft inside.","Rub the salmon with a little oil and coat it in the Cajun seasoning.","For the last 10 minutes of the wedges, roast the salmon on a small tray alongside.","Dress the rocket with the remaining oil and the vinegar and serve with the salmon and wedges."]'::jsonb,
    array['american', 'oven']::text[], 'american', 742, 30.5,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Saumon cajun et quartiers de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger les quartiers sur une plaque antiadhésive avec la moitié de l''huile, le romarin et un peu de sel et enfourner 25-30 minutes jusqu''à ce qu''ils soient croustillants à l''extérieur et fondants à l''intérieur.","Frotter le saumon avec un peu d''huile et l''enrober d''assaisonnement cajun.","Pendant les 10 dernières minutes de cuisson des quartiers, faire rôtir le saumon à côté sur une petite plaque.","Assaisonner la roquette avec le reste de l''huile et le vinaigre et servir avec le saumon et les quartiers."]},"it":{"title":"Salmone cajun con spicchi di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Mescolare gli spicchi su una teglia antiaderente con metà dell''olio, il rosmarino e un po'' di sale e cuocere in forno per 25-30 minuti finché non sono croccanti fuori e morbidi dentro.","Strofinare il salmone con un filo d''olio e ricoprirlo con il condimento cajun.","Negli ultimi 10 minuti di cottura degli spicchi, cuocere in forno il salmone accanto, su una teglia piccola.","Condire la rucola con l''olio rimasto e l''aceto e servire con il salmone e gli spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd939ecdf-9a41-49f5-87f1-33289d9daeea')
  returning id
)
