-- Carne asada bowls with chipotle crema
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '376e8ca0-3d31-4b62-852c-ac2fdc9e9648'::uuid, null, 'Carne asada bowls with chipotle crema', 'seed', 'https://whitneybond.com/carne-asada-bowl/', 'Whitney Bond', '/recipe-photos/carne-asada-bowls-with-chipotle-crema.webp', 'https://whitneybond.com/wp-content/uploads/2021/03/Carne-Asada-Bowl-8.jpg',
    2, 4, 70, 30, 10, '["Combine oil, soy sauce, lime juice, cumin, chipotle powder, coriander and garlic in a zip bag.","Add the steak and marinate in the fridge at least 30 minutes (up to 8 hours).","Heat a grill to high, take the steak out of the marinade, salt both sides and grill about 5 minutes per side.","Rest the steak loosely covered for 5-10 minutes, then slice across the grain and dice.","Toss the cooked rice with coriander and lime juice.","Blend the crema, chipotle, garlic, lime and salt until smooth.","Fill bowls with rice, steak, pico de gallo, avocado, jalapeño, radish and cheese, then drizzle with the chipotle crema."]'::jsonb,
    array['mexican', 'bowl', 'grill', 'high protein']::text[], 'mexican', 1061, 59.9,
    true, 'en', 'medium', '{"pots":0,"oven":false,"special":["blender","barbecue"]}'::jsonb, false,
    '{"fr":{"title":"Bols de carne asada, crème au chipotle","steps":["Mélanger l''huile, la sauce soja, le jus de citron vert, le cumin, le chipotle en poudre, la coriandre et l''ail dans un sac de congélation zippé.","Ajouter le steak et laisser mariner au réfrigérateur au moins 30 minutes (jusqu''à 8 heures).","Faire chauffer un barbecue à feu vif, sortir le steak de la marinade, le saler des deux côtés et le faire griller environ 5 minutes de chaque côté.","Laisser reposer le steak 5-10 minutes, couvert sans serrer, puis le trancher perpendiculairement aux fibres et le couper en dés.","Mélanger le riz cuit avec la coriandre et le jus de citron vert.","Mixer la crème, le chipotle, l''ail, le citron vert et le sel jusqu''à obtenir une crème lisse.","Garnir les bols de riz, de steak, de pico de gallo, d''avocat, de jalapeño, de radis et de fromage, puis arroser de crème au chipotle."]},"it":{"title":"Ciotole di carne asada con crema al chipotle","steps":["Mescolare in un sacchetto con chiusura zip l''olio, la salsa di soia, il succo di lime, il cumino, il chipotle in polvere, il coriandolo e l''aglio.","Aggiungere la bistecca e lasciarla marinare in frigorifero per almeno 30 minuti (fino a 8 ore).","Scaldare la griglia al massimo, togliere la bistecca dalla marinata, salarla su entrambi i lati e grigliarla per circa 5 minuti per lato.","Lasciare riposare la bistecca coperta senza stringere per 5-10 minuti, poi tagliarla contro fibra e ridurla a cubetti.","Mescolare il riso cotto con il coriandolo e il succo di lime.","Frullare la crema, il chipotle, l''aglio, il lime e il sale fino a ottenere un composto liscio.","Riempire le ciotole con riso, bistecca, pico de gallo, avocado, jalapeño, ravanelli e formaggio, poi condire con un filo di crema al chipotle."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '376e8ca0-3d31-4b62-852c-ac2fdc9e9648')
  returning id
)
