-- Chicken souvlaki with tzatziki
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '27e46b96-2742-476c-bc1f-e5c23aa41f11'::uuid, null, 'Chicken souvlaki with tzatziki', 'seed', 'https://www.sbs.com.au/food/recipe/chicken-souvlaki/j847ixvsa', 'SBS Food', '/recipe-photos/chicken-souvlaki-with-tzatziki.webp', 'https://assets.sbs.com.au/dims4/default/da1f801/2147483647/strip/true/crop/3000x1688+0+225/resize/1280x720!/quality/90/?url=https%3A%2F%2Fsbs-au-brightspot.s3.ap-southeast-2.amazonaws.com%2Fdrupal%2Ffood%2Fpublic%2Fowk_3076_chicken_souvlaki_and_tzatziki_horizontal_2.jpg',
    2, 4, 200, 5, 15, '["Whisk the oil, lemon juice, garlic, oregano, salt and pepper into a marinade.","Coat the chicken cubes in it and leave in the fridge for 3-4 hours.","Soak wooden skewers in water, then thread on the chicken and brush with the leftover marinade.","Grill for 10-15 minutes, turning now and then, until cooked through.","Warm the pitas on the grill.","Serve the skewers on the pitas with tomato slices and tzatziki."]'::jsonb,
    array['greek', 'mediterranean', 'grill', 'wrap', 'make ahead', 'high protein']::text[], 'greek', 488, 47.4,
    true, 'en', 'medium', '{"pots":0,"oven":false,"special":["barbecue"]}'::jsonb, false,
    '{"fr":{"title":"Souvlaki de poulet au tzatziki","steps":["Fouetter l''huile, le jus de citron, l''ail, l''origan, le sel et le poivre pour obtenir une marinade.","Y enrober les cubes de poulet et laisser au réfrigérateur 3-4 heures.","Faire tremper des brochettes en bois dans l''eau, puis y enfiler le poulet et le badigeonner du reste de marinade.","Faire griller 10-15 minutes en retournant de temps en temps, jusqu''à ce que le poulet soit bien cuit.","Réchauffer les pitas sur le gril.","Servir les brochettes sur les pitas avec des rondelles de tomate et du tzatziki."]},"it":{"title":"Souvlaki di pollo con tzatziki","steps":["Sbattere l''olio, il succo di limone, l''aglio, l''origano, il sale e il pepe per preparare una marinata.","Ricoprire i cubetti di pollo con la marinata e lasciarli in frigorifero per 3-4 ore.","Mettere a bagno in acqua gli spiedini di legno, poi infilzarvi il pollo e spennellarlo con la marinata avanzata.","Grigliare per 10-15 minuti, girando di tanto in tanto, finché non è ben cotto.","Scaldare le pita sulla griglia.","Servire gli spiedini sulle pita con fette di pomodoro e tzatziki."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '27e46b96-2742-476c-bc1f-e5c23aa41f11')
  returning id
)
