-- Chicken tinga
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7fa7da2a-36aa-4a38-95f7-b0269eae6257'::uuid, null, 'Chicken tinga', 'seed', 'https://www.mexicoinmykitchen.com/chicken-tinga-recipe/', 'Mexico in My Kitchen', '/recipe-photos/chicken-tinga.webp', 'https://www.mexicoinmykitchen.com/wp-content/uploads/2020/12/Chicken-Tinga-recipe-3-ing.jpg',
    2, 6, 30, 10, 20, '["Heat the oil over medium heat and fry the sliced onion about 3 minutes.","Add the garlic and cook 2 more minutes until fragrant.","Stir in the tomatoes and parsley, reduce the heat and cook 6-7 minutes until the tomatoes break down (add a splash of water if dry).","Add the shredded chicken and chopped chipotle and simmer about 8 minutes so the flavours meld.","Season with salt and pepper, garnish with parsley and serve with rice and salad or on tostadas."]'::jsonb,
    array['mexican', 'stew', 'light']::text[], 'mexican', 155, 17.3,
    true, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Tinga de poulet","steps":["Faire chauffer l''huile à feu moyen et faire revenir l''oignon émincé environ 3 minutes.","Ajouter l''ail et cuire encore 2 minutes, jusqu''à ce qu''il soit parfumé.","Incorporer les tomates et le persil, baisser le feu et cuire 6-7 minutes jusqu''à ce que les tomates se défassent (ajouter un trait d''eau si c''est trop sec).","Ajouter le poulet effiloché et le chipotle haché et laisser mijoter environ 8 minutes pour que les saveurs se mêlent.","Saler, poivrer, parsemer de persil et servir avec du riz et de la salade ou sur des tostadas."]},"it":{"title":"Tinga di pollo","steps":["Scaldare l''olio a fuoco medio e soffriggere la cipolla affettata per circa 3 minuti.","Aggiungere l''aglio e cuocere ancora 2 minuti, finché non diventa profumato.","Unire i pomodori e il prezzemolo, abbassare la fiamma e cuocere 6-7 minuti finché i pomodori non si disfano (aggiungere un goccio d''acqua se si asciuga troppo).","Aggiungere il pollo sfilacciato e il chipotle tritato e cuocere a fuoco lento per circa 8 minuti, così che i sapori si amalgamino.","Regolare di sale e pepe, guarnire con prezzemolo e servire con riso e insalata oppure sulle tostadas."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7fa7da2a-36aa-4a38-95f7-b0269eae6257')
  returning id
)
