-- Greek baked fish (psari plaki)
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'eab5838e-660b-4b5f-9444-00603cb201fa'::uuid, null, 'Greek baked fish (psari plaki)', 'seed', 'https://www.themediterraneandish.com/baked-greek-fish-psari-plaki', 'The Mediterranean Dish', null, null,
    2, 6, 40, 10, 30, '["Heat the oven to 200°C (400°F) with a rack in the middle.","In an oven-safe pan, cook the onion in the olive oil with a pinch of salt until soft and lightly golden.","Stir in the garlic, then the tomatoes, oregano and pepper; crush the tomatoes, bring to a boil and simmer 10-15 minutes.","Dry the fish and season both sides with salt, oregano, paprika and cumin; squeeze half the lemon over it.","Settle the fish into the sauce and spoon some sauce on top.","Bake 15-25 minutes until the fish is opaque and flakes easily; check so it doesn''t overcook.","Scatter with parsley and serve with the remaining lemon in wedges, plus bread or rice."]'::jsonb,
    array['greek', 'mediterranean', 'oven', 'light']::text[], 'greek', 241, 30.7,
    true, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poisson au four à la grecque (psari plaki)","steps":["Préchauffer le four à 200 °C (400 °F), avec une grille au milieu.","Dans une poêle allant au four, faire revenir l''oignon dans l''huile d''olive avec une pincée de sel jusqu''à ce qu''il soit tendre et légèrement doré.","Incorporer l''ail, puis les tomates, l''origan et le poivre ; écraser les tomates, porter à ébullition et laisser mijoter 10-15 minutes.","Sécher le poisson et l''assaisonner des deux côtés de sel, d''origan, de paprika et de cumin ; presser la moitié du citron par-dessus.","Déposer le poisson dans la sauce et le napper d''un peu de sauce.","Enfourner 15-25 minutes, jusqu''à ce que le poisson soit opaque et s''effeuille facilement ; surveiller pour qu''il ne soit pas trop cuit.","Parsemer de persil et servir avec le reste du citron en quartiers, ainsi que du pain ou du riz."]},"it":{"title":"Pesce al forno alla greca (psari plaki)","steps":["Preriscaldare il forno a 200 °C (400 °F) con una griglia al centro.","In una padella adatta al forno, far appassire la cipolla nell''olio d''oliva con un pizzico di sale finché non è morbida e leggermente dorata.","Unire l''aglio, poi i pomodori, l''origano e il pepe; schiacciare i pomodori, portare a bollore e cuocere a fuoco lento per 10-15 minuti.","Asciugare il pesce e condirlo su entrambi i lati con sale, origano, paprika e cumino; spremerci sopra metà del limone.","Adagiare il pesce nel sugo e coprirlo con un po'' di sugo.","Cuocere in forno 15-25 minuti, finché il pesce non è opaco e si sfalda facilmente; controllare che non cuocia troppo.","Cospargere di prezzemolo e servire con il limone rimasto a spicchi, accompagnando con pane o riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'eab5838e-660b-4b5f-9444-00603cb201fa')
  returning id
)
