-- Harissa roast salmon with herby grains
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '88cbc523-853f-41c7-b63a-f0f761e56e3b'::uuid, null, 'Harissa roast salmon with herby grains', 'seed', 'https://olivemagazine.com/recipes/fish-and-seafood/harissa-roast-salmon-with-warm-herby-grains-and-yogurt-dressing', 'Olive Magazine', '/recipe-photos/harissa-roast-salmon-with-herby-grains.webp', 'https://images.immediate.co.uk/production/volatile/sites/2/2024/10/HarissaRoastedSalmonGrainSalad004preview-9e2cc18.jpg?resize=1200%2C630',
    2, 2, 35, 10, 20, '["Simmer the grains in salted water for 20-25 minutes until just tender.","Heat the oven to 180°C (160°C fan); mix harissa, oil, honey and the juice of half the lemon.","Toss the salmon and tomatoes in the harissa mix in a baking dish and roast 15 minutes.","In a large bowl combine the spring onions, most of the herbs, the rest of the lemon juice and a little oil.","Drop the peas into the grains for the last minute, then drain thoroughly.","Stir the leftover herbs into the yogurt with salt and a splash of water to loosen.","Toss the grains and peas with the spring onion mix, plate, top with salmon and tomatoes and add the yogurt dressing."]'::jsonb,
    array['north african', 'mediterranean', 'oven', 'bowl', 'light', 'high protein']::text[], 'north african', 647, 39.4,
    true, 'en', 'medium', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Saumon rôti à la harissa et céréales aux herbes","steps":["Faire cuire les céréales à petit bouillon dans de l''eau salée 20-25 minutes, jusqu''à ce qu''elles soient juste tendres.","Préchauffer le four à 180 °C (160 °C chaleur tournante) ; mélanger la harissa, l''huile, le miel et le jus d''un demi-citron.","Enrober le saumon et les tomates du mélange à la harissa dans un plat à four et rôtir 15 minutes.","Dans un grand saladier, mélanger les oignons nouveaux, la majeure partie des herbes, le reste du jus de citron et un filet d''huile.","Ajouter les petits pois aux céréales pendant la dernière minute, puis bien égoutter.","Mélanger le reste des herbes au yaourt avec du sel et un trait d''eau pour le détendre.","Mélanger les céréales et les petits pois avec les oignons nouveaux, dresser dans les assiettes, garnir de saumon et de tomates et ajouter la sauce au yaourt."]},"it":{"title":"Salmone al forno all''harissa con cereali alle erbe","steps":["Cuocere i cereali in acqua salata a fuoco lento per 20-25 minuti, finché non sono appena teneri.","Preriscaldare il forno a 180 °C (160 °C ventilato); mescolare harissa, olio, miele e il succo di mezzo limone.","In una pirofila, condire il salmone e i pomodorini con il mix all''harissa e cuocere in forno 15 minuti.","In una ciotola capiente unire i cipollotti, la maggior parte delle erbe, il resto del succo di limone e un filo d''olio.","Aggiungere i piselli ai cereali nell''ultimo minuto di cottura, poi scolare bene.","Mescolare le erbe rimaste allo yogurt con sale e un goccio d''acqua per renderlo più fluido.","Condire cereali e piselli con il mix di cipollotti, impiattare, aggiungere sopra salmone e pomodorini e completare con la salsa allo yogurt."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '88cbc523-853f-41c7-b63a-f0f761e56e3b')
  returning id
)
