-- Healthy turkey chili
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b0816cc0-d7b8-4649-88e0-b13c37a64404'::uuid, null, 'Healthy turkey chili', 'seed', 'https://ambitiouskitchen.com/seriously-the-best-healthy-turkey-chili', 'Ambitious Kitchen', '/recipe-photos/healthy-turkey-chili.webp', 'https://www.ambitiouskitchen.com/wp-content/uploads/2015/11/The-Best-Turkey-Chili-3long.jpg',
    2, 6, 55, 10, 45, '["Heat the oil in a large pot over medium-high heat and cook the onion, garlic and pepper for 5-7 minutes, stirring often.","Add the turkey and break it up with a spoon until it is no longer pink.","Stir in the chili powder, cumin, oregano, cayenne and salt and toast for about 20 seconds.","Add the tomatoes, stock, kidney beans and corn and bring to a boil.","Lower the heat and simmer 30-45 minutes until thick, then adjust the seasoning.","Serve topped with a little cheese, avocado or coriander if you like."]'::jsonb,
    array['american', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'american', 444, 32.8,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Chili de dinde allégé","steps":["Faire chauffer l''huile dans une grande marmite à feu moyen-vif et faire revenir l''oignon, l''ail et le poivron 5-7 minutes en remuant souvent.","Ajouter la dinde et l''émietter à la cuillère jusqu''à ce qu''elle ne soit plus rose.","Incorporer le piment en poudre, le cumin, l''origan, le piment de Cayenne et le sel et faire griller environ 20 secondes.","Ajouter les tomates, le bouillon, les haricots rouges et le maïs et porter à ébullition.","Baisser le feu et laisser mijoter 30-45 minutes jusqu''à ce que ce soit épais, puis rectifier l''assaisonnement.","Servir garni d''un peu de fromage, d''avocat ou de coriandre, selon les envies."]},"it":{"title":"Chili di tacchino light","steps":["Scaldare l''olio in una pentola capiente a fuoco medio-alto e soffriggere cipolla, aglio e peperone per 5-7 minuti, mescolando spesso.","Aggiungere il tacchino e sgranarlo con un cucchiaio finché non è più rosa.","Unire il chili in polvere, il cumino, l''origano, il pepe di Cayenna e il sale e tostare per circa 20 secondi.","Aggiungere i pomodori, il brodo, i fagioli rossi e il mais e portare a bollore.","Abbassare la fiamma e cuocere a fuoco lento per 30-45 minuti finché non si addensa, poi aggiustare di sapore.","Servire con un po'' di formaggio, avocado o coriandolo, a piacere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b0816cc0-d7b8-4649-88e0-b13c37a64404')
  returning id
)
