-- Jerk chicken curry with beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8415659c-0fbe-4c0f-879f-6902ec41c28b'::uuid, null, 'Jerk chicken curry with beans', 'seed', 'https://www.bbcgoodfoodme.com/recipes/jerk-chicken-curry-with-beans', 'BBC Good Food', '/recipe-photos/jerk-chicken-curry-with-beans.webp', 'https://www.bbcgoodfoodme.com/assets/legacy/recipe_images/recipe-image-legacy-id--19058_11.jpg',
    2, 4, 45, 5, 40, '["Rub the drumsticks with a little of the jerk seasoning plus salt and pepper.","Brown them in half the oil, then lift out onto a plate.","Add the rest of the oil and soften the onion and coriander stalks for about 5 minutes, stirring in the remaining jerk seasoning for the last minute.","Put the chicken back, add the tomatoes, bring to a simmer, cover and cook 20 minutes; start the rice meanwhile.","Uncover, add the beans and simmer 10 minutes more until the chicken is cooked through.","Scatter with coriander leaves and serve with the rice."]'::jsonb,
    array['caribbean', 'curry', 'comfort', 'high protein']::text[], 'caribbean', 902, 56.4,
    true, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Curry de poulet jerk aux haricots","steps":["Frotter les pilons avec un peu d''assaisonnement jerk, du sel et du poivre.","Les faire dorer dans la moitié de l''huile, puis les réserver sur une assiette.","Ajouter le reste de l''huile et faire suer l''oignon et les tiges de coriandre environ 5 minutes, en incorporant le reste de l''assaisonnement jerk pendant la dernière minute.","Remettre le poulet, ajouter les tomates, porter à frémissement, couvrir et cuire 20 minutes ; lancer la cuisson du riz pendant ce temps.","Découvrir, ajouter les haricots et laisser mijoter encore 10 minutes, jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de feuilles de coriandre et servir avec le riz."]},"it":{"title":"Curry di pollo jerk con fagioli","steps":["Massaggiare i fusi di pollo con un po'' di condimento jerk, sale e pepe.","Rosolarli in metà dell''olio, poi toglierli e metterli su un piatto.","Aggiungere il resto dell''olio e far appassire la cipolla e i gambi di coriandolo per circa 5 minuti, unendo il condimento jerk rimasto nell''ultimo minuto.","Rimettere il pollo, aggiungere i pomodori, portare a sobbollire, coprire e cuocere 20 minuti; nel frattempo mettere a cuocere il riso.","Scoprire, aggiungere i fagioli e cuocere a fuoco lento per altri 10 minuti, finché il pollo non è cotto.","Cospargere di foglie di coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8415659c-0fbe-4c0f-879f-6902ec41c28b')
  returning id
)
