-- Jerk chicken with sweet potato fries
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ff2f10ad-8161-4b4b-aba7-4d79a27d86cb'::uuid, null, 'Jerk chicken with sweet potato fries', 'seed', 'https://www.abelandcole.co.uk/box-recipes/jerked-chicken-with-sweet-potato-fries-tomato-salad', 'Abel & Cole', '/recipe-photos/jerk-chicken-with-sweet-potato-fries.webp', 'https://www.abelandcole.co.uk/media/3676_18875_z.jpg',
    2, 2, 55, 15, 40, '["Heat the oven to 200C (180C fan) and line two baking trays.","Cut the sweet potatoes into finger-thick chips, toss with most of the oil and a pinch of salt and spread on one tray.","Rub the jerk seasoning into the chicken and lay it on the second tray.","Roast 20 minutes with the chicken on the top shelf and the chips below, then swap the trays and roast 15-20 minutes more until the chips are tender and charred and the chicken is cooked.","Meanwhile mix the tomatoes, onion and chilli with the lime zest, half the lime juice, a drizzle of oil and a pinch of salt.","Serve the chicken and chips with the tomato salad, lamb''s lettuce and the rest of the lime in wedges."]'::jsonb,
    array['caribbean', 'oven', 'light', 'high protein']::text[], 'caribbean', 513, 35.1,
    true, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poulet jerk et frites de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante) et chemiser deux plaques de cuisson.","Couper les patates douces en frites de l''épaisseur d''un doigt, les mélanger avec la majeure partie de l''huile et une pincée de sel et les étaler sur une plaque.","Frotter le poulet avec l''assaisonnement jerk et le disposer sur la seconde plaque.","Rôtir 20 minutes, le poulet sur la grille du haut et les frites en dessous, puis intervertir les plaques et rôtir encore 15-20 minutes, jusqu''à ce que les frites soient tendres et grillées et que le poulet soit cuit.","Pendant ce temps, mélanger les tomates, l''oignon et le piment avec le zeste du citron vert, la moitié de son jus, un filet d''huile et une pincée de sel.","Servir le poulet et les frites avec la salade de tomates, la mâche et le reste du citron vert en quartiers."]},"it":{"title":"Pollo jerk con patatine di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato) e foderare due teglie.","Tagliare le patate dolci a bastoncini spessi un dito, condirle con la maggior parte dell''olio e un pizzico di sale e distribuirle su una teglia.","Massaggiare il pollo con il condimento jerk e disporlo sulla seconda teglia.","Cuocere in forno 20 minuti con il pollo sul ripiano alto e le patate sotto, poi invertire le teglie e cuocere altri 15-20 minuti, finché le patate non sono tenere e abbrustolite e il pollo è cotto.","Nel frattempo mescolare i pomodorini, la cipolla e il peperoncino con la scorza del lime, metà del succo, un filo d''olio e un pizzico di sale.","Servire il pollo e le patate con l''insalata di pomodorini, la valeriana e il lime rimasto a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ff2f10ad-8161-4b4b-aba7-4d79a27d86cb')
  returning id
)
