-- Lebanese chicken shawarma wraps
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '1e932845-59bf-429a-9ef5-73ddfd24e7ee'::uuid, null, 'Lebanese chicken shawarma wraps', 'seed', 'https://www.munatycooking.com/chicken-shawarma/', 'Munaty Cooking', '/recipe-photos/lebanese-chicken-shawarma-wraps.webp', 'https://www.munatycooking.com/wp-content/uploads/2023/12/chicken-shawarma-image-1-2023.jpg',
    2, 4, 210, 10, 20, '["Mix the garlic, lemon juice, yogurt, salt, spices and olive oil into a marinade.","Coat the chicken in it and refrigerate 3 hours or overnight (at least 1 hour if pressed).","Heat the frying oil in a wide pan until very hot.","Cook the chicken in a single uncrowded layer, about 2 minutes per side for thin breast slices, until browned and cooked through.","Cut the cooked chicken into strips.","Spread toum down the centre of each pita, add the chicken, pickles and fries if using.","Roll up tightly and halve to serve."]'::jsonb,
    array['lebanese', 'mediterranean', 'wrap', 'make ahead']::text[], 'lebanese', 572, 34.1,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Wraps shawarma au poulet à la libanaise","steps":["Mélanger l''ail, le jus de citron, le yaourt, le sel, les épices et l''huile d''olive pour préparer une marinade.","Y enrober le poulet et réfrigérer 3 heures ou toute une nuit (au moins 1 heure si on est pressé).","Faire chauffer l''huile de cuisson dans une grande poêle jusqu''à ce qu''elle soit très chaude.","Cuire le poulet en une seule couche sans surcharger la poêle, environ 2 minutes de chaque côté pour de fines tranches de blanc, jusqu''à ce qu''il soit doré et cuit à cœur.","Couper le poulet cuit en lanières.","Étaler de la toum au centre de chaque pita, ajouter le poulet, les cornichons et les frites si on en utilise.","Rouler bien serré et couper en deux pour servir."]},"it":{"title":"Wrap di shawarma di pollo alla libanese","steps":["Mescolare aglio, succo di limone, yogurt, sale, spezie e olio d''oliva per preparare la marinata.","Ricoprire il pollo con la marinata e lasciarlo in frigo 3 ore o tutta la notte (almeno 1 ora se si ha fretta).","Scaldare l''olio per friggere in una padella ampia finché non è molto caldo.","Cuocere il pollo in un solo strato senza affollare la padella, circa 2 minuti per lato per fettine sottili di petto, finché non è dorato e cotto.","Tagliare il pollo cotto a striscioline.","Spalmare la toum al centro di ogni pita, aggiungere il pollo, i cetriolini sottaceto e, se si usano, le patatine.","Arrotolare stretto e tagliare a metà per servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '1e932845-59bf-429a-9ef5-73ddfd24e7ee')
  returning id
)
