-- Lighter chicken paprikash
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'fc33d4ff-b75f-430a-b4e4-bff6fcb450a4'::uuid, null, 'Lighter chicken paprikash', 'seed', 'https://reciperunner.com/easy-smokey-chicken-paprikash/', 'Recipe Runner', '/recipe-photos/lighter-chicken-paprikash.webp', 'https://reciperunner.com/wp-content/uploads/2018/02/Easy-Smokey-Chicken-Paprikash-Photo.jpg',
    2, 4, 25, 10, 15, '["Put a pan of salted water on to boil and cook the egg noodles while you make the sauce.","Heat the oil in a large skillet over medium-high heat and cook the chicken until no longer pink; lift it out.","Soften the onion in the same pan, then add the garlic for about a minute.","Return the chicken with both paprikas, the stock, tomatoes, salt and pepper; bring to a boil and cook about 2 minutes until a little thicker.","Take the pan off the heat and stir in the yogurt (off the heat so it doesn''t split); adjust the seasoning.","Spoon over the noodles and finish with parsley."]'::jsonb,
    array['hungarian', 'stew', 'quick', 'comfort', 'high protein']::text[], 'hungarian', 589, 43.3,
    true, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poulet paprikash allégé","steps":["Mettre à bouillir une casserole d''eau salée et y cuire les nouilles aux œufs pendant la préparation de la sauce.","Faire chauffer l''huile dans une grande sauteuse à feu moyen-vif et cuire le poulet jusqu''à ce qu''il ne soit plus rose ; le retirer.","Faire suer l''oignon dans la même sauteuse, puis ajouter l''ail environ une minute.","Remettre le poulet avec les deux paprikas, le bouillon, les tomates, le sel et le poivre ; porter à ébullition et cuire environ 2 minutes jusqu''à ce que la sauce épaississe un peu.","Retirer la sauteuse du feu et incorporer le yaourt (hors du feu pour qu''il ne tranche pas) ; rectifier l''assaisonnement.","Napper les nouilles de la préparation et parsemer de persil."]},"it":{"title":"Pollo paprikash light","steps":["Mettere sul fuoco una pentola di acqua salata e cuocere le tagliatelle all''uovo mentre si prepara il sugo.","Scaldare l''olio in una padella capiente a fuoco medio-alto e cuocere il pollo finché non è più rosa; toglierlo dalla padella.","Far appassire la cipolla nella stessa padella, poi aggiungere l''aglio per circa un minuto.","Rimettere il pollo con entrambe le paprike, il brodo, i pomodori, sale e pepe; portare a bollore e cuocere circa 2 minuti finché il sugo non si addensa un po''.","Togliere la padella dal fuoco e incorporare lo yogurt (a fuoco spento, così non impazzisce); regolare di sale e pepe.","Versare sulle tagliatelle e completare con il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'fc33d4ff-b75f-430a-b4e4-bff6fcb450a4')
  returning id
)
