-- Moroccan chicken tagine with olives and lemon
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5bfdb175-f3b8-4a0a-a4ac-d972e6504617'::uuid, null, 'Moroccan chicken tagine with olives and lemon', 'seed', 'https://www.americastestkitchen.com/recipes/5189-moroccan-chicken-tagine-with-olives-and-lemon-djej-emshmel', 'America''s Test Kitchen', '/recipe-photos/moroccan-chicken-tagine-with-olives-and-lemon.webp', 'https://res.cloudinary.com/hksqkdlah/image/upload/c_fill,dpr_2.0,f_auto,fl_lossy.progressive.strip_profile,g_faces:auto,q_auto:low/8112_sfs-chicken-tangine-with-olives-and-lemon-article',
    2, 4, 90, 15, 75, '["Mix most of the garlic with all the ground spices; finely chop one zest strip and mix it with the remaining garlic.","Pat the chicken dry, season, and brown it well in hot oil in a heavy pot, in batches; set aside.","Pour off most of the fat, then soften the onion with the remaining zest strips.","Stir in the spice paste for about 30 seconds, then add carrots, stock and honey, scraping the pot.","Return the chicken and juices, cover and simmer gently until tender, about 1 hour for thighs (add breast pieces only for the last 20 minutes).","Lift out the chicken and keep warm; skim the sauce, add the olives and simmer until slightly thickened and the carrots are soft.","Put the chicken back, stir in the garlic-zest mix, coriander and lemon juice, adjust seasoning and serve."]'::jsonb,
    array['moroccan', 'north african', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'moroccan', 992, 84.6,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Tajine de poulet aux olives et au citron","steps":["Mélanger la majeure partie de l''ail avec toutes les épices moulues ; hacher finement un ruban de zeste et le mélanger avec le reste de l''ail.","Sécher le poulet en le tamponnant, l''assaisonner et le faire bien dorer dans l''huile chaude dans une cocotte en fonte, en plusieurs fois ; réserver.","Retirer la majeure partie de la graisse, puis faire suer l''oignon avec les rubans de zeste restants.","Incorporer la pâte d''épices environ 30 secondes, puis ajouter les carottes, le bouillon et le miel en grattant le fond de la cocotte.","Remettre le poulet et son jus, couvrir et laisser mijoter doucement jusqu''à ce qu''il soit tendre, environ 1 heure pour des cuisses (n''ajouter les morceaux de blanc que pour les 20 dernières minutes).","Retirer le poulet et le garder au chaud ; dégraisser la sauce, ajouter les olives et laisser mijoter jusqu''à ce qu''elle épaississe légèrement et que les carottes soient tendres.","Remettre le poulet, incorporer le mélange ail-zeste, la coriandre et le jus de citron, rectifier l''assaisonnement et servir."]},"it":{"title":"Tajine di pollo marocchino con olive e limone","steps":["Mescolare la maggior parte dell''aglio con tutte le spezie in polvere; tritare finemente una scorzetta di limone e mescolarla con l''aglio rimasto.","Asciugare bene il pollo tamponandolo, condirlo e rosolarlo bene nell''olio caldo in una pentola dal fondo spesso, poco per volta; tenere da parte.","Eliminare la maggior parte del grasso, poi far appassire la cipolla con le scorzette rimaste.","Unire la pasta di spezie per circa 30 secondi, poi aggiungere le carote, il brodo e il miele, raschiando il fondo della pentola.","Rimettere il pollo con i suoi succhi, coprire e cuocere a fuoco lento finché non è tenero, circa 1 ora per le cosce (aggiungere i pezzi di petto solo negli ultimi 20 minuti).","Togliere il pollo e tenerlo in caldo; sgrassare il sugo, aggiungere le olive e cuocere a fuoco lento finché non si addensa leggermente e le carote sono morbide.","Rimettere il pollo, unire il mix di aglio e scorza, il coriandolo e il succo di limone, regolare di sale e pepe e servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5bfdb175-f3b8-4a0a-a4ac-d972e6504617')
  returning id
)
