-- Peruvian roast chicken with green sauce
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '89dd9707-0a47-4448-9592-cdae9bfb9fb4'::uuid, null, 'Peruvian roast chicken with green sauce', 'seed', 'https://onceuponachef.com/recipes/peruvian-style-roast-chicken-with-green-sauce.html/comment-page-4', 'Once Upon a Chef', '/recipe-photos/peruvian-roast-chicken-with-green-sauce.webp', 'https://www.onceuponachef.com/images/2013/01/peruvian-chicken-3-1200x873.jpg',
    2, 4, 480, 20, 90, '["Blitz the marinade ingredients (oil, lime juice, garlic, salt, spices, oregano, sugar) until smooth.","Dry the chicken, loosen the skin over breast and legs, push most of the marinade underneath and rub the rest outside.","Refrigerate at least 6 hours or overnight.","Heat the oven to 220°C (425°F) with a rack low-middle; set the chicken on an oiled rack over a foil-lined pan and tie the legs.","Roast 20 minutes until golden, then lower to 190°C (375°F) and roast until the juices run clear (about 70 minutes for a 1.8 kg bird, less for a smaller one); tent with foil if browning too fast.","Blend jalapeños, coriander, garlic, mayonnaise, sour cream, lime juice, salt and pepper, then stream in the oil with the motor running; chill to thicken.","Rest the chicken under foil about 20 minutes, carve and serve with the green sauce."]'::jsonb,
    array['peruvian', 'oven', 'comfort', 'make ahead', 'high protein']::text[], 'peruvian', 1440, 88.3,
    true, 'en', 'medium', '{"pots":1,"oven":true,"special":["blender"]}'::jsonb, false,
    '{"fr":{"title":"Poulet rôti péruvien, sauce verte","steps":["Mixer les ingrédients de la marinade (huile, jus de citron vert, ail, sel, épices, origan, sucre) jusqu''à obtenir un mélange lisse.","Sécher le poulet, décoller la peau des blancs et des cuisses, glisser la majeure partie de la marinade dessous et frotter l''extérieur avec le reste.","Réfrigérer au moins 6 heures ou toute une nuit.","Préchauffer le four à 220 °C (425 °F) avec une grille entre le bas et le milieu ; poser le poulet sur une grille huilée au-dessus d''un plat tapissé de papier aluminium et ficeler les cuisses.","Rôtir 20 minutes jusqu''à ce qu''il soit doré, puis baisser à 190 °C (375 °F) et rôtir jusqu''à ce que le jus soit clair (environ 70 minutes pour une volaille de 1,8 kg, moins pour une plus petite) ; couvrir de papier aluminium s''il dore trop vite.","Mixer les jalapeños, la coriandre, l''ail, la mayonnaise, la crème fraîche, le jus de citron vert, le sel et le poivre, puis verser l''huile en filet sans arrêter le blender ; réfrigérer pour que la sauce épaississe.","Laisser reposer le poulet sous une feuille d''aluminium environ 20 minutes, le découper et servir avec la sauce verte."]},"it":{"title":"Pollo arrosto peruviano con salsa verde","steps":["Frullare gli ingredienti della marinata (olio, succo di lime, aglio, sale, spezie, origano, zucchero) fino a ottenere un composto liscio.","Asciugare il pollo, staccare la pelle su petto e cosce, infilarci sotto la maggior parte della marinata e massaggiare l''esterno con il resto.","Lasciare in frigorifero almeno 6 ore o tutta la notte.","Preriscaldare il forno a 220 °C (425 °F) con una griglia nella parte medio-bassa; sistemare il pollo su una griglia unta sopra una teglia foderata di alluminio e legare le cosce.","Arrostire 20 minuti finché non è dorato, poi abbassare a 190 °C (375 °F) e cuocere finché i succhi non escono limpidi (circa 70 minuti per un pollo da 1,8 kg, meno per uno più piccolo); coprire con alluminio se si colorisce troppo in fretta.","Frullare jalapeños, coriandolo, aglio, maionese, panna acida, succo di lime, sale e pepe, poi versare l''olio a filo con il frullatore in funzione; mettere in frigo per far addensare.","Far riposare il pollo coperto con alluminio per circa 20 minuti, tagliarlo e servire con la salsa verde."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '89dd9707-0a47-4448-9592-cdae9bfb9fb4')
  returning id
)
