-- Seared harissa salmon with cauliflower and chickpeas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f0116db7-383f-4d62-870c-ab0b0417a431'::uuid, null, 'Seared harissa salmon with cauliflower and chickpeas', 'seed', 'https://www.americastestkitchen.com/recipes/16707-one-pan-seared-salmon-with-cauliflower-chickpeas-and-harissa', 'America''s Test Kitchen', '/recipe-photos/seared-harissa-salmon-with-cauliflower-and-chickpeas.webp', 'https://res.cloudinary.com/hksqkdlah/image/upload/c_fill,dpr_2.0,f_auto,fl_lossy.progressive.strip_profile,g_faces:auto,q_auto:low/SFS_One-Pan-Seared-Salmon-with-Cauliflower-Chickpeas-and-Harissa_617_nsowls',
    2, 4, 60, 15, 35, '["Stir the harissa and honey together; set aside.","In a large bowl toss the chickpeas with part of the oil, the lemon juice and the shallot.","Cook the cauliflower with most of the ground coriander, half the salt and more oil in a covered nonstick skillet until starting to soften, then uncover and cook until spotty brown.","Add the cauliflower to the chickpeas with the olives, coriander and mint; keep warm and wipe out the pan.","Season the salmon with the rest of the coriander and salt and sear it, skinned side up, in the remaining oil until deeply browned.","Flip and cook until the centre reaches about 50°C (125°F) for medium-rare.","Off the heat brush the fillets with the harissa-honey, re-toss the vegetables, season and serve together."]'::jsonb,
    array['north african', 'mediterranean', 'one-pot', 'fancy', 'high protein']::text[], 'north african', 821, 43.6,
    true, 'en', 'medium', '{"pots":1,"oven":false,"special":["thermometer"]}'::jsonb, false,
    '{"fr":{"title":"Saumon poêlé à la harissa, chou-fleur et pois chiches","steps":["Mélanger la harissa et le miel ; réserver.","Dans un grand saladier, mélanger les pois chiches avec une partie de l''huile, le jus de citron et l''échalote.","Cuire le chou-fleur avec la majeure partie de la coriandre moulue, la moitié du sel et un peu plus d''huile dans une poêle antiadhésive couverte jusqu''à ce qu''il commence à ramollir, puis découvrir et cuire jusqu''à ce qu''il soit doré par endroits.","Ajouter le chou-fleur aux pois chiches avec les olives, la coriandre et la menthe ; garder au chaud et essuyer la poêle.","Assaisonner le saumon avec le reste de la coriandre moulue et du sel et le saisir, côté peau vers le haut, dans le reste de l''huile jusqu''à ce qu''il soit bien doré.","Retourner et cuire jusqu''à ce que le centre atteigne environ 50 °C (125 °F) pour une cuisson rosée.","Hors du feu, badigeonner les pavés de harissa au miel, remélanger les légumes, assaisonner et servir ensemble."]},"it":{"title":"Salmone scottato all''harissa con cavolfiore e ceci","steps":["Mescolare l''harissa con il miele; tenere da parte.","In una ciotola capiente condire i ceci con una parte dell''olio, il succo di limone e lo scalogno.","Cuocere il cavolfiore con la maggior parte del coriandolo in polvere, metà del sale e altro olio in una padella antiaderente coperta finché non inizia ad ammorbidirsi, poi scoprire e cuocere finché non è dorato qua e là.","Unire il cavolfiore ai ceci con le olive, il coriandolo e la menta; tenere in caldo e pulire la padella.","Condire il salmone con il resto del coriandolo in polvere e del sale e scottarlo, con il lato della pelle rivolto verso l''alto, nell''olio rimasto finché non è ben dorato.","Girarlo e cuocere finché il centro non raggiunge circa 50 °C (125 °F) per una cottura rosata.","A fuoco spento spennellare i filetti con l''harissa al miele, mescolare di nuovo le verdure, regolare di sale e servire insieme."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f0116db7-383f-4d62-870c-ab0b0417a431')
  returning id
)
