-- Sherry-braised chicken with chorizo and chickpeas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a609b57d-8c52-4d05-a917-cc6e7675b365'::uuid, null, 'Sherry-braised chicken with chorizo and chickpeas', 'seed', 'https://sainsburysmagazine.co.uk/recipes/mains/sherry-braised-chicken-with-chorizo-and-chickpeas', 'Sainsbury''s Magazine', '/recipe-photos/sherry-braised-chicken-with-chorizo-and-chickpeas.webp', 'https://www.sainsburysmagazine.co.uk/media/14642/download/Sherry-chicken.jpg?v=1',
    2, 4, 45, 25, 20, '["Trim any fat off the chicken thighs and cut each into 2-3 pieces.","Season the chicken and brown it on both sides in half the oil over high heat; lift it out.","Deglaze the hot pan with the sherry, scraping up the browned bits, and pour it into a jug.","Lower the heat a little, add the rest of the oil with the chorizo, onion and garlic, and cook until the onion turns translucent.","Return the sherry and chicken with the stock, chickpeas, peppers and seasoning; bring to a simmer.","Cover and cook gently about 15 minutes until the chicken is cooked through.","Finish with chopped parsley."]'::jsonb,
    array['spanish', 'mediterranean', 'stew', 'one-pot', 'comfort', 'high protein']::text[], 'spanish', 626, 40.1,
    false, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, false,
    '{"fr":{"title":"Poulet braisé au xérès, chorizo et pois chiches","steps":["Retirer l''excès de gras des hauts de cuisse et couper chacun en 2-3 morceaux.","Assaisonner le poulet et le faire dorer des deux côtés dans la moitié de l''huile à feu vif ; le retirer.","Déglacer la poêle chaude avec le xérès en grattant les sucs, et verser le tout dans un pichet.","Baisser un peu le feu, ajouter le reste de l''huile avec le chorizo, l''oignon et l''ail, et cuire jusqu''à ce que l''oignon devienne translucide.","Remettre le xérès et le poulet avec le bouillon, les pois chiches, les poivrons, du sel et du poivre ; porter à frémissement.","Couvrir et cuire doucement environ 15 minutes jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de persil haché."]},"it":{"title":"Pollo brasato allo sherry con chorizo e ceci","steps":["Eliminare il grasso in eccesso dalle sovracosce e tagliarle ciascuna in 2-3 pezzi.","Condire il pollo e rosolarlo su entrambi i lati in metà dell''olio a fuoco vivo; toglierlo dalla padella.","Sfumare la padella calda con lo sherry, raschiando il fondo di cottura, e versare il tutto in una caraffa.","Abbassare un po'' la fiamma, aggiungere il resto dell''olio con il chorizo, la cipolla e l''aglio e cuocere finché la cipolla non diventa trasparente.","Rimettere lo sherry e il pollo con il brodo, i ceci, i peperoni, sale e pepe; portare a sobbollire.","Coprire e cuocere dolcemente per circa 15 minuti finché il pollo non è cotto.","Completare con prezzemolo tritato."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a609b57d-8c52-4d05-a917-cc6e7675b365')
  returning id
)
