-- Canadian Poutine
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b4a417db-84c5-4375-9e34-ed701092ccaa'::uuid, null, 'Canadian Poutine', 'seed', 'https://anaffairfromtheheart.com/wprm_print/canadian-poutine-recipe', 'An Affair from the Heart', '/recipe-photos/canadian-poutine.webp', 'https://anaffairfromtheheart.com/wp-content/uploads/2022/04/Canadian-Poutine-MAIN.jpg',
    2, 4, 10, 2, 8, '["Prepare the gravy according to the packet instructions and keep it hot over low heat.","Deep-fry the fries in oil at 350°F (175°C) until golden and crisp.","Drain the fries on a tray lined with paper towels.","Pile the fries onto plates, scatter the cheese curds on top and ladle over the hot gravy.","Eat straight away while the curds are just starting to melt."]'::jsonb,
    array['canadian', 'comfort', 'quick', 'treat']::text[], 'canadian', 400, 12.9,
    true, 'en', 'hard', '{"pots":2,"oven":false,"special":["thermometer"]}'::jsonb, false,
    '{"fr":{"title":"Poutine canadienne","steps":["Préparer la sauce brune selon les instructions du sachet et la maintenir chaude à feu doux.","Faire frire les frites dans l''huile à 350 °F (175 °C) jusqu''à ce qu''elles soient dorées et croustillantes.","Égoutter les frites sur une plaque tapissée de papier absorbant.","Répartir les frites dans les assiettes, parsemer de fromage en grains et napper de sauce chaude à la louche.","Déguster aussitôt, pendant que le fromage commence tout juste à fondre."]},"it":{"title":"Poutine canadese","steps":["Preparare la salsa gravy secondo le istruzioni della confezione e tenerla calda a fuoco basso.","Friggere le patatine in olio a 350 °F (175 °C) finché sono dorate e croccanti.","Scolare le patatine su un vassoio foderato di carta assorbente.","Disporre le patatine nei piatti, distribuirvi sopra la cagliata di formaggio a pezzetti e versare con un mestolo la salsa calda.","Mangiare subito, mentre la cagliata inizia appena a sciogliersi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b4a417db-84c5-4375-9e34-ed701092ccaa')
  returning id
)
