-- Croque-monsieur maison
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '292f619c-527e-4bce-8623-235114ca29bf'::uuid, null, 'Croque-monsieur maison', 'seed', 'https://www.demotivateur.fr/food/recette/croque-monsieur-maison-2990', 'Demotivateur Food', '/recipe-photos/croque-monsieur-maison.webp', 'https://www.demotivateur.fr/images/cover_recette/1759999281-croque_monsieur_maison.jpg',
    2, 4, 25, 10, 15, '["Fondre le beurre dans une casserole, ajouter la farine, puis verser le lait petit à petit en fouettant pour obtenir une béchamel lisse.","Laisser épaissir, assaisonner de sel, poivre et muscade, puis retirer du feu.","Faire fondre la moitié de l''emmental dans la béchamel chaude.","Beurrer une face de chaque tranche de pain ; sur la face non beurrée de la moitié des tranches, étaler un peu de béchamel, poser le jambon et un peu de fromage, puis refermer.","Dorer les sandwichs à la poêle 3 à 4 min de chaque côté.","Les poser sur une plaque recouverte de papier cuisson, napper du reste de béchamel et parsemer du fromage restant.","Passer sous le gril environ 5 min jusqu''à ce que le dessus soit gratiné, et servir aussitôt avec une salade."]'::jsonb,
    array['french', 'grill', 'comfort', 'quick', 'treat']::text[], 'french', 568, 35.6,
    true, 'fr', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Homemade croque-monsieur","steps":["Melt the butter in a saucepan, add the flour, then gradually pour in the milk while whisking to make a smooth béchamel.","Let it thicken, season with salt, pepper and nutmeg, then take off the heat.","Melt half the Emmental into the hot béchamel.","Butter one side of each slice of bread; on the unbuttered side of half the slices, spread a little béchamel, add the ham and a little cheese, then close the sandwiches.","Brown the sandwiches in a frying pan for 3 to 4 min on each side.","Place them on a baking tray lined with baking paper, coat with the rest of the béchamel and sprinkle with the remaining cheese.","Put under the grill for about 5 min until the top is golden and bubbling, and serve immediately with a salad."]},"it":{"title":"Croque-monsieur fatto in casa","steps":["Sciogliere il burro in un pentolino, aggiungere la farina, poi versare il latte poco alla volta mescolando con la frusta per ottenere una besciamella liscia.","Lasciare addensare, condire con sale, pepe e noce moscata, poi togliere dal fuoco.","Far sciogliere metà dell''emmental nella besciamella calda.","Imburrare un lato di ogni fetta di pane; sul lato non imburrato di metà delle fette spalmare un po'' di besciamella, adagiare il prosciutto cotto e un po'' di formaggio, poi chiudere.","Dorare i toast in padella per 3-4 min per lato.","Disporli su una teglia rivestita di carta forno, nappare con la besciamella rimasta e cospargere con il formaggio restante.","Passare sotto il grill per circa 5 min finché la superficie è gratinata e servire subito con un''insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '292f619c-527e-4bce-8623-235114ca29bf')
  returning id
)
