-- Parmigiana di melanzane in padella
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0d73508c-6359-434b-bd0d-9ba7e7c3440d'::uuid, null, 'Parmigiana di melanzane in padella', 'seed', 'https://www.dissapore.com/ricette/parmigiana-di-melanzane-in-padella-ricetta/', 'Dissapore', '/recipe-photos/parmigiana-di-melanzane-in-padella.webp', 'https://images.dissapore.com/wp-content/uploads/2019/03/Parmigiana-di-melanzane-in-padella-pane.jpg?width=1280&height=720&quality=75',
    2, 4, 105, 10, 35, '["Lavare le melanzane, eliminare il picciolo e tagliarle a fette.","Disporle in uno scolapasta, cospargerle di sale e lasciarle spurgare per circa 1 ora.","Nel frattempo scaldare un cucchiaio d''olio con la passata e un po'' d''acqua, salare e cuocere a fuoco basso 10 minuti; aggiungere il basilico e spegnere.","Sciacquare le melanzane e strizzarle delicatamente.","Grigliarle poche alla volta su una piastra antiaderente appena unta finché sono morbide e segnate.","In una padella antiaderente da 24 cm alternare strati di melanzane, sugo, parmigiano e mozzarella fino a esaurire gli ingredienti.","Coprire e cuocere a fuoco medio-basso per 20-25 minuti finché la mozzarella è fusa."]'::jsonb,
    array['italian', 'mediterranean', 'vegetarian', 'one-pot', 'comfort', 'treat']::text[], 'italian', 294, 24.4,
    true, 'it', 'medium', '{"pots":3,"oven":false,"special":[]}'::jsonb, false,
    '{"en":{"title":"Skillet aubergine parmigiana","steps":["Wash the aubergines, remove the stalk and slice them.","Place them in a colander, sprinkle with salt and leave to drain for about 1 hour.","Meanwhile, heat a tablespoon of oil with the passata and a little water, season with salt and cook over low heat for 10 minutes; add the basil and turn off the heat.","Rinse the aubergines and gently squeeze them.","Grill them a few at a time on a lightly oiled nonstick griddle until soft and marked.","In a 24 cm nonstick frying pan, alternate layers of aubergine, sauce, Parmesan and mozzarella until the ingredients are used up.","Cover and cook over medium-low heat for 20-25 minutes until the mozzarella has melted."]},"fr":{"title":"Parmigiana d''aubergines à la poêle","steps":["Laver les aubergines, retirer le pédoncule et les couper en tranches.","Les disposer dans une passoire, les saupoudrer de sel et les laisser dégorger environ 1 heure.","Pendant ce temps, chauffer une cuillère à soupe d''huile avec le coulis de tomate et un peu d''eau, saler et cuire à feu doux 10 minutes ; ajouter le basilic et éteindre le feu.","Rincer les aubergines et les presser délicatement.","Les griller quelques-unes à la fois sur une poêle-gril antiadhésive légèrement huilée jusqu''à ce qu''elles soient tendres et marquées.","Dans une poêle antiadhésive de 24 cm, alterner des couches d''aubergines, de sauce, de parmesan et de mozzarella jusqu''à épuisement des ingrédients.","Couvrir et cuire à feu moyen-doux 20 à 25 minutes, jusqu''à ce que la mozzarella soit fondue."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0d73508c-6359-434b-bd0d-9ba7e7c3440d')
  returning id
)
