-- Tartiflette traditionnelle
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '72695646-987b-4eed-9407-29049d511fea'::uuid, null, 'Tartiflette traditionnelle', 'seed', 'https://www.demotivateur.fr/food/recette/tartiflette-traditionnelle-2597', 'Demotivateur Food', '/recipe-photos/tartiflette-traditionnelle.webp', 'https://www.demotivateur.fr/images/cover_recette/1734022037-tartiflette_traditionnelle.jpg',
    2, 6, 60, 10, 50, '["Faire revenir l''oignon émincé et l''ail haché dans un filet d''huile jusqu''à ce qu''ils deviennent translucides, puis réserver.","Dorer les lardons dans la même poêle, remettre oignon et ail, puis déglacer au vin blanc.","Laisser le vin s''évaporer complètement, verser dans un bol et incorporer la crème, le sel, le poivre et la muscade.","Mettre les pommes de terre épluchées dans l''eau froide salée et les cuire environ 15 min : elles doivent rester un peu fermes.","Couper les pommes de terre en fines rondelles.","Frotter un plat à gratin beurré avec de l''ail, puis alterner couches de pommes de terre et de mélange aux lardons.","Gratter la croûte du reblochon, le couper en morceaux et le poser croûte vers le haut sur le dessus.","Enfourner à 180 °C pour 30 à 35 min, jusqu''à ce que le fromage soit fondu et doré, et servir bien chaud."]'::jsonb,
    array['french', 'oven', 'comfort', 'treat']::text[], 'french', 772, 27.6,
    true, 'fr', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, false,
    '{"en":{"title":"Traditional tartiflette","steps":["Fry the sliced onion and chopped garlic in a drizzle of oil until translucent, then set aside.","Brown the lardons in the same pan, return the onion and garlic, then deglaze with the white wine.","Let the wine evaporate completely, transfer to a bowl and stir in the crème fraîche, salt, pepper and nutmeg.","Put the peeled potatoes in cold salted water and cook for about 15 min: they should stay slightly firm.","Cut the potatoes into thin slices.","Rub a buttered gratin dish with garlic, then alternate layers of potato and the lardon mixture.","Scrape the rind of the reblochon, cut it into pieces and lay them rind-side up on top.","Bake at 180 °C for 30 to 35 min, until the cheese is melted and golden, and serve piping hot."]},"it":{"title":"Tartiflette tradizionale","steps":["Soffriggere la cipolla affettata e l''aglio tritato in un filo d''olio finché diventano traslucidi, poi tenerli da parte.","Rosolare la pancetta nella stessa padella, rimettere cipolla e aglio, poi sfumare con il vino bianco.","Lasciare evaporare completamente il vino, versare in una ciotola e incorporare la panna, il sale, il pepe e la noce moscata.","Mettere le patate sbucciate in acqua fredda salata e cuocerle circa 15 min: devono rimanere un po'' sode.","Tagliare le patate a rondelle sottili.","Strofinare una pirofila imburrata con l''aglio, poi alternare strati di patate e di composto di pancetta.","Raschiare la crosta del reblochon, tagliarlo a pezzi e adagiarli sopra con la crosta rivolta verso l''alto.","Infornare a 180 °C per 30-35 min, finché il formaggio è fuso e dorato, e servire ben caldo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '72695646-987b-4eed-9407-29049d511fea')
  returning id
)
