-- Pasta e ceci
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6f72d2b5-6a40-4b91-bf03-6c6a3cb4b4fb'::uuid, null, 'Pasta e ceci', 'seed', null, 'Claude', '/recipe-photos/pasta-e-ceci.webp', '/recipe-photos/pasta-e-ceci.webp',
    2, null, 35, 10, 25, '["Gently fry the onion in 2 tbsp olive oil for 5 min. Add garlic, rosemary and chilli for 1 min, then stir in the tomato paste.","Add the chickpeas and stock and simmer 10 min. Remove the rosemary and mash or blend about a third of the chickpeas to thicken.","Add the pasta and cook in the soup, stirring often, until al dente (add a splash of water if it gets too thick).","Season, then serve with Parmesan, black pepper and a drizzle of olive oil."]'::jsonb,
    array['soup', 'vegetarian', 'budget', 'comfort', 'italian']::text[], 'italian', 556, 26.6,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pasta e ceci","steps":["Faire revenir doucement l''oignon dans 2 c. à soupe d''huile d''olive pendant 5 min. Ajouter l''ail, le romarin et le piment pendant 1 min, puis incorporer le concentré de tomate.","Ajouter les pois chiches et le bouillon et laisser mijoter 10 min. Retirer le romarin et écraser ou mixer environ un tiers des pois chiches pour épaissir.","Ajouter les pâtes et les cuire dans la soupe, en remuant souvent, jusqu''à ce qu''elles soient al dente (ajouter un peu d''eau si cela devient trop épais).","Assaisonner, puis servir avec le parmesan, du poivre noir et un filet d''huile d''olive."]},"it":{"title":"Pasta e ceci","steps":["Soffriggere dolcemente la cipolla in 2 cucchiai d''olio d''oliva per 5 min. Aggiungere aglio, rosmarino e peperoncino per 1 min, poi incorporare il concentrato di pomodoro.","Unire i ceci e il brodo e cuocere a fuoco lento 10 min. Togliere il rosmarino e schiacciare o frullare circa un terzo dei ceci per addensare.","Aggiungere la pasta e cuocerla nella minestra, mescolando spesso, finché è al dente (aggiungere un goccio d''acqua se diventa troppo densa).","Regolare di sale, poi servire con il parmigiano, pepe nero e un filo d''olio d''oliva."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6f72d2b5-6a40-4b91-bf03-6c6a3cb4b4fb')
  returning id
)
