-- Chicken shawarma traybake
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7375c699-23ee-487c-9121-73adc3d46728'::uuid, null, 'Chicken shawarma traybake', 'seed', null, 'Claude', '/recipe-photos/chicken-shawarma-traybake.webp', '/recipe-photos/chicken-shawarma-traybake.webp',
    2, null, 45, 15, 30, '["Heat the oven to 220 °C. Mix the spices, 2 garlic cloves, the juice of half the lemon, 2 tbsp oil and salt.","Toss the chicken and onion wedges in the marinade and spread on a tray in one layer.","Roast 25-30 min until the chicken is charred at the edges. Rest 5 min, then slice.","Mix the yogurt with the remaining garlic, a squeeze of lemon and salt.","Toss tomato, cucumber and parsley with lemon juice and oil. Serve the chicken and onions with flatbreads, garlic yogurt and salad."]'::jsonb,
    array['oven', 'high protein', 'generous', 'middle eastern']::text[], 'middle eastern', 840, 63.4,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Shawarma de poulet au four","steps":["Préchauffer le four à 220 °C. Mélanger les épices, 2 gousses d''ail, le jus d''un demi-citron, 2 c. à soupe d''huile et du sel.","Enrober le poulet et les quartiers d''oignon de marinade et les étaler en une seule couche sur une plaque.","Rôtir 25 à 30 min, jusqu''à ce que le poulet soit grillé sur les bords. Laisser reposer 5 min, puis trancher.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et du sel.","Mélanger la tomate, le concombre et le persil avec du jus de citron et de l''huile. Servir le poulet et les oignons avec les pains pita, le yaourt à l''ail et la salade."]},"it":{"title":"Shawarma di pollo in teglia","steps":["Scaldare il forno a 220 °C. Mescolare le spezie, 2 spicchi d''aglio, il succo di mezzo limone, 2 cucchiai d''olio e sale.","Condire il pollo e gli spicchi di cipolla con la marinata e distribuirli su una teglia in un solo strato.","Arrostire 25-30 min finché il pollo è abbrustolito ai bordi. Lasciare riposare 5 min, poi affettare.","Mescolare lo yogurt con l''aglio rimasto, una spruzzata di limone e sale.","Condire pomodoro, cetriolo e prezzemolo con succo di limone e olio. Servire il pollo e le cipolle con il pane pita, lo yogurt all''aglio e l''insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7375c699-23ee-487c-9121-73adc3d46728')
  returning id
)
