-- Turkey taco lettuce wraps
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '7ccb7672-07ff-4746-b7b9-165af1682c26'::uuid, null, 'Turkey taco lettuce wraps', 'seed', null, 'Claude', '/recipe-photos/turkey-taco-lettuce-wraps.webp', '/recipe-photos/turkey-taco-lettuce-wraps.webp',
    2, null, 22, 10, 12, '["Cook the onion in 1 tsp oil for 3 min. Add the turkey and brown, breaking it up, 5-6 min.","Stir in garlic, chipotle, cumin, paprika and tomato paste for 1 min, then add the beans and a splash of water. Simmer 2 min until saucy.","Season with salt and the juice of half the lime.","Spoon the filling into lettuce cups and top with tomato, avocado, yogurt, coriander and lime wedges."]'::jsonb,
    array['low carb', 'high protein', 'diet', 'quick', 'mexican']::text[], 'mexican', 568, 53.9,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tacos de dinde en feuilles de laitue","steps":["Faire revenir l''oignon dans 1 c. à café d''huile pendant 3 min. Ajouter la dinde et la faire dorer en l''émiettant, 5 à 6 min.","Incorporer l''ail, le chipotle, le cumin, le paprika et le concentré de tomate pendant 1 min, puis ajouter les haricots et un peu d''eau. Laisser mijoter 2 min jusqu''à obtenir une texture nappante.","Assaisonner de sel et du jus d''un demi-citron vert.","Répartir la garniture dans les feuilles de laitue et garnir de tomate, d''avocat, de yaourt, de coriandre et de quartiers de citron vert."]},"it":{"title":"Tacos di tacchino in foglie di lattuga","steps":["Soffriggere la cipolla in 1 cucchiaino d''olio per 3 min. Aggiungere il tacchino e rosolarlo sgranandolo, 5-6 min.","Unire aglio, chipotle, cumino, paprika e concentrato di pomodoro per 1 min, poi aggiungere i fagioli e un goccio d''acqua. Cuocere a fuoco lento 2 min finché si forma un sughetto.","Insaporire con sale e il succo di mezzo lime.","Distribuire il ripieno nelle foglie di lattuga e completare con pomodoro, avocado, yogurt, coriandolo e spicchi di lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '7ccb7672-07ff-4746-b7b9-165af1682c26')
  returning id
)
