-- Chana masala
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'd31d3553-44c2-493a-ae47-a5ef771dfc03'::uuid, null, 'Chana masala', 'seed', null, 'Claude', '/recipe-photos/chana-masala.webp', '/recipe-photos/chana-masala.webp',
    2, null, 35, 10, 25, '["Start the rice according to the packet.","Heat 2 tbsp oil and sizzle the cumin seeds for 30 s. Add the onion and cook 8 min until golden.","Add garlic, ginger and chilli for 1 min, then the ground spices for 30 s.","Add the tomatoes and cook 5 min until thick, then the chickpeas and 150 ml water. Simmer 10 min, lightly crushing some chickpeas.","Season with salt and lemon juice, scatter with coriander and serve with the rice."]'::jsonb,
    array['curry', 'vegetarian', 'vegan', 'make ahead', 'indian']::text[], 'indian', 592, 20.1,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Chana masala","steps":["Lancer la cuisson du riz selon les instructions du paquet.","Chauffer 2 c. à soupe d''huile et faire grésiller les graines de cumin 30 s. Ajouter l''oignon et cuire 8 min jusqu''à ce qu''il soit doré.","Ajouter l''ail, le gingembre et le piment pendant 1 min, puis les épices moulues pendant 30 s.","Ajouter les tomates et cuire 5 min jusqu''à ce que la sauce épaississe, puis les pois chiches et 150 ml d''eau. Laisser mijoter 10 min en écrasant légèrement quelques pois chiches.","Assaisonner de sel et de jus de citron, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Chana masala","steps":["Mettere a cuocere il riso secondo le istruzioni della confezione.","Scaldare 2 cucchiai d''olio e far sfrigolare i semi di cumino per 30 s. Aggiungere la cipolla e cuocere 8 min finché è dorata.","Aggiungere aglio, zenzero e peperoncino per 1 min, poi le spezie in polvere per 30 s.","Unire i pomodori e cuocere 5 min finché si addensano, poi i ceci e 150 ml d''acqua. Cuocere a fuoco lento 10 min, schiacciando leggermente una parte dei ceci.","Insaporire con sale e succo di limone, cospargere di coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'd31d3553-44c2-493a-ae47-a5ef771dfc03')
  returning id
)
