-- Chicken teriyaki donburi
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'bfa142e0-6a9e-458a-b320-536bf8aa8e76'::uuid, null, 'Chicken teriyaki donburi', 'seed', null, 'Claude', '/recipe-photos/chicken-teriyaki-donburi.webp', '/recipe-photos/chicken-teriyaki-donburi.webp',
    2, null, 25, 10, 15, '["Cook the rice. Mix soy sauce, mirin, sake and sugar.","Steam or boil the broccoli for 3-4 min.","Cook the chicken skin-side down in a little oil over medium heat for 7 min until crisp, then turn and cook 4 min more.","Wipe out excess fat, pour in the sauce and simmer 1-2 min, turning the chicken until glossy.","Slice the chicken and serve over rice with broccoli, extra sauce, spring onion and sesame."]'::jsonb,
    array['bowl', 'quick', 'asian', 'japanese']::text[], 'japanese', 781, 47,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Donburi de poulet teriyaki","steps":["Cuire le riz. Mélanger la sauce soja, le mirin, le saké et le sucre.","Cuire le brocoli à la vapeur ou à l''eau 3 à 4 min.","Cuire le poulet côté peau dans un peu d''huile à feu moyen 7 min jusqu''à ce qu''il soit croustillant, puis le retourner et poursuivre la cuisson 4 min.","Retirer l''excédent de graisse, verser la sauce et laisser mijoter 1 à 2 min en retournant le poulet jusqu''à ce qu''il soit bien laqué.","Trancher le poulet et le servir sur le riz avec le brocoli, un peu plus de sauce, l''oignon nouveau et le sésame."]},"it":{"title":"Donburi di pollo teriyaki","steps":["Cuocere il riso. Mescolare salsa di soia, mirin, sake e zucchero.","Cuocere i broccoli al vapore o lessarli per 3-4 min.","Cuocere il pollo dal lato della pelle in un filo d''olio a fuoco medio per 7 min finché è croccante, poi girarlo e cuocere altri 4 min.","Eliminare il grasso in eccesso, versare la salsa e cuocere a fuoco lento 1-2 min, girando il pollo finché è lucido.","Affettare il pollo e servirlo sul riso con i broccoli, altra salsa, il cipollotto e il sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'bfa142e0-6a9e-458a-b320-536bf8aa8e76')
  returning id
)
