-- Shakshuka with feta
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'cf55fbb6-d6f4-4ed9-a1f1-b5675ef81fa4'::uuid, null, 'Shakshuka with feta', 'seed', null, 'Claude', '/recipe-photos/shakshuka-with-feta.webp', '/recipe-photos/shakshuka-with-feta.webp',
    2, null, 30, 10, 20, '["Cook the onion and pepper in 2 tbsp olive oil for 8 min until soft.","Add garlic and spices for 1 min, then the tomatoes. Simmer 6-8 min until thick; season.","Make 5 wells in the sauce and crack in the eggs. Cover and cook on low for 5-7 min until the whites are set and yolks still runny.","Scatter with feta and parsley and serve straight from the pan with bread."]'::jsonb,
    array['vegetarian', 'one-pot', 'breakfast', 'quick', 'north african', 'middle eastern']::text[], 'middle eastern', 583, 33.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Shakshuka à la feta","steps":["Faire revenir l''oignon et le poivron dans 2 c. à soupe d''huile d''olive pendant 8 min jusqu''à ce qu''ils soient tendres.","Ajouter l''ail et les épices pendant 1 min, puis les tomates. Laisser mijoter 6 à 8 min jusqu''à épaississement ; assaisonner.","Creuser 5 puits dans la sauce et y casser les œufs. Couvrir et cuire à feu doux 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de feta et de persil et servir directement dans la poêle avec du pain."]},"it":{"title":"Shakshuka con feta","steps":["Cuocere la cipolla e il peperone in 2 cucchiai d''olio d''oliva per 8 min finché sono morbidi.","Aggiungere aglio e spezie per 1 min, poi i pomodori. Cuocere a fuoco lento 6-8 min finché il sugo si addensa; regolare di sale e pepe.","Formare 5 incavi nel sugo e rompervi dentro le uova. Coprire e cuocere a fuoco basso 5-7 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere di feta e prezzemolo e servire direttamente nella padella con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'cf55fbb6-d6f4-4ed9-a1f1-b5675ef81fa4')
  returning id
)
