-- Beef & broccoli stir-fry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '22aa9226-5726-4893-ab82-6cb10720509d'::uuid, null, 'Beef & broccoli stir-fry', 'seed', null, 'Claude', '/recipe-photos/beef-broccoli-stir-fry.webp', '/recipe-photos/beef-broccoli-stir-fry.webp',
    2, null, 25, 15, 10, '["Cook the rice. Toss the beef with 1 tsp cornflour and 1 tbsp soy sauce.","Mix the sauce: 2 tbsp soy, oyster sauce, sugar, sesame oil, 1 tsp cornflour and 80 ml water.","Heat a wok until smoking, add 1 tbsp oil and sear the beef in one layer, 1-2 min, without overcooking. Remove.","Add a little oil, the broccoli and 2 tbsp water; stir-fry 3 min until bright and just tender. Add garlic and ginger for 30 s.","Return the beef, pour in the sauce and toss 1 min until glossy. Serve over rice."]'::jsonb,
    array['stir-fry', 'high protein', 'fakeaway', 'quick', 'asian', 'chinese']::text[], 'chinese', 692, 49.5,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Sauté de bœuf au brocoli","steps":["Cuire le riz. Mélanger le bœuf avec 1 c. à café de fécule de maïs et 1 c. à soupe de sauce soja.","Préparer la sauce : 2 c. à soupe de sauce soja, la sauce d''huître, le sucre, l''huile de sésame, 1 c. à café de fécule de maïs et 80 ml d''eau.","Chauffer un wok jusqu''à ce qu''il fume, ajouter 1 c. à soupe d''huile et saisir le bœuf en une seule couche, 1 à 2 min, sans trop le cuire. Le retirer.","Ajouter un peu d''huile, le brocoli et 2 c. à soupe d''eau ; faire sauter 3 min jusqu''à ce qu''il soit bien vert et juste tendre. Ajouter l''ail et le gingembre pendant 30 s.","Remettre le bœuf, verser la sauce et mélanger 1 min jusqu''à ce que ce soit bien brillant. Servir sur le riz."]},"it":{"title":"Manzo e broccoli saltati al wok","steps":["Cuocere il riso. Condire il manzo con 1 cucchiaino di amido di mais e 1 cucchiaio di salsa di soia.","Preparare la salsa: 2 cucchiai di salsa di soia, salsa d''ostriche, zucchero, olio di sesamo, 1 cucchiaino di amido di mais e 80 ml d''acqua.","Scaldare il wok finché fuma, aggiungere 1 cucchiaio d''olio e scottare il manzo in un solo strato, 1-2 min, senza cuocerlo troppo. Toglierlo.","Aggiungere un filo d''olio, i broccoli e 2 cucchiai d''acqua; saltare 3 min finché sono di un verde brillante e appena teneri. Aggiungere aglio e zenzero per 30 s.","Rimettere il manzo, versare la salsa e saltare 1 min finché è lucido. Servire sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '22aa9226-5726-4893-ab82-6cb10720509d')
  returning id
)
