-- Salade niçoise with tuna and green beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a50426c9-afb6-41ab-ae5c-a0c08d84695c'::uuid, null, 'Salade niçoise with tuna and green beans', 'seed', null, 'Claude', null, null,
    2, null, 30, 15, 15, '["Put the potatoes in a pan of boiling salted water. After 6 min, lower in the eggs; after 4 more min, add the green beans; 5 min later drain everything and cool under cold water (eggs 9 min, potatoes 15 min).","Peel and quarter the eggs, halve the potatoes and cut the beans in two.","Whisk the mustard, vinegar, salt and pepper, then whisk in the oil.","Salt the tomato wedges lightly.","Arrange the lettuce on a large plate with the potatoes, beans, tomatoes and spring onion. Flake over the tuna and top with the eggs, anchovies, olives and capers.","Drizzle with the vinaigrette and scatter with basil just before serving."]'::jsonb,
    array['french', 'salad', 'summer', 'mediterranean']::text[], 'french', 631, 39.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Salade niçoise au thon et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau bouillante salée. Au bout de 6 min, plonger les œufs ; 4 min plus tard, ajouter les haricots verts ; 5 min après, tout égoutter et refroidir sous l''eau froide (œufs 9 min, pommes de terre 15 min).","Écaler les œufs et les couper en quartiers, couper les pommes de terre en deux et les haricots en deux.","Fouetter la moutarde, le vinaigre, le sel et le poivre, puis incorporer l''huile en fouettant.","Saler légèrement les quartiers de tomate.","Disposer la salade sur un grand plat avec les pommes de terre, les haricots, les tomates et l''oignon nouveau. Émietter le thon par-dessus et garnir d''œufs, d''anchois, d''olives et de câpres.","Arroser de vinaigrette et parsemer de basilic juste avant de servir."]},"it":{"title":"Insalata nizzarda con tonno e fagiolini","steps":["Mettere le patate in una pentola di acqua bollente salata. Dopo 6 min immergere le uova; dopo altri 4 min aggiungere i fagiolini; 5 min più tardi scolare tutto e raffreddare sotto l''acqua fredda (uova 9 min, patate 15 min).","Sgusciare le uova e tagliarle in quarti, tagliare a metà le patate e i fagiolini.","Sbattere la senape, l''aceto, il sale e il pepe, poi incorporare l''olio sbattendo.","Salare leggermente gli spicchi di pomodoro.","Disporre l''insalata su un piatto grande con le patate, i fagiolini, i pomodori e il cipollotto. Sbriciolare sopra il tonno e completare con le uova, le acciughe, le olive e i capperi.","Condire con la vinaigrette e cospargere di basilico appena prima di servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a50426c9-afb6-41ab-ae5c-a0c08d84695c')
  returning id
)
