-- Lemon, pea and ricotta pasta
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'cf3604f7-00c4-4439-ae7c-a23dd60cdc25'::uuid, null, 'Lemon, pea and ricotta pasta', 'seed', null, 'Claude', null, null,
    2, null, 22, 10, 12, '["Bring a large pot of salted water to the boil and cook the pasta 1 min short of the packet time.","Meanwhile mash the ricotta in a large bowl with the lemon zest, half the lemon juice, the garlic, the olive oil, half the parmesan, salt and plenty of pepper.","Add the peas to the pasta for the last 3 min of cooking.","Scoop out a mug of the cooking water, then drain the pasta and peas.","Tip them into the bowl and toss with the ricotta, adding cooking water a splash at a time until the sauce is creamy and coats the pasta.","Taste, add the rest of the lemon juice if you like, and serve topped with the remaining parmesan, the parsley and a pinch of chili flakes."]'::jsonb,
    array['italian', 'vegetarian', 'quick', 'spring', 'mediterranean']::text[], 'italian', 806, 35,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pâtes au citron, petits pois et ricotta","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les pâtes 1 min de moins que le temps indiqué.","Pendant ce temps, écraser la ricotta dans un grand saladier avec le zeste de citron, la moitié du jus, l''ail, l''huile d''olive, la moitié du parmesan, du sel et beaucoup de poivre.","Ajouter les petits pois aux pâtes pendant les 3 dernières minutes de cuisson.","Prélever un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois.","Les verser dans le saladier et mélanger avec la ricotta en ajoutant l''eau de cuisson petit à petit jusqu''à obtenir une sauce crémeuse qui enrobe les pâtes.","Goûter, ajouter le reste du jus de citron si on le souhaite et servir avec le reste du parmesan, le persil et une pincée de piment."]},"it":{"title":"Pasta al limone con piselli e ricotta","steps":["Portare a bollore una pentola di acqua salata e cuocere la pasta 1 min in meno del tempo indicato.","Nel frattempo schiacciare la ricotta in una ciotola capiente con la scorza di limone, metà del succo, l''aglio, l''olio, metà del parmigiano, sale e abbondante pepe.","Aggiungere i piselli alla pasta negli ultimi 3 min di cottura.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli.","Versarli nella ciotola e mescolare con la ricotta, aggiungendo acqua di cottura poco alla volta finché la crema è morbida e avvolge la pasta.","Assaggiare, unire il resto del succo di limone a piacere e servire con il parmigiano rimasto, il prezzemolo e un pizzico di peperoncino."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'cf3604f7-00c4-4439-ae7c-a23dd60cdc25')
  returning id
)
