-- Mushroom and spinach frittata with bread
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '91e8fa61-df06-405b-a7c2-209948b7784f'::uuid, null, 'Mushroom and spinach frittata with bread', 'seed', null, 'Claude', null, null,
    2, null, 35, 10, 25, '["Heat the oven to 180°C.","Warm the oil in a 24 cm ovenproof frying pan over medium heat and soften the onion for 5 min.","Add the mushrooms, garlic and thyme and cook for 6–8 min, until the mushrooms are golden and their liquid has gone.","Add the spinach a handful at a time and stir until wilted and the pan is dry, about 2 min; season.","Beat the eggs with the milk, the parmesan, salt and pepper.","Pour the eggs over the vegetables, spread everything evenly and cook on low heat for 3–4 min, until the edges start to set.","Bake for 10–12 min, until the centre is just set and springs back when pressed.","Rest for 2 min, cut into wedges and serve warm with the bread."]'::jsonb,
    array['italian', 'vegetarian', 'oven', 'light']::text[], 'italian', 612, 39.4,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Frittata aux champignons et épinards, pain","steps":["Préchauffer le four à 180 °C.","Chauffer l''huile dans une poêle de 24 cm allant au four, à feu moyen, et faire fondre l''oignon 5 min.","Ajouter les champignons, l''ail et le thym et cuire 6 à 8 min, jusqu''à ce que les champignons soient dorés et leur eau évaporée.","Ajouter les épinards par poignées et remuer jusqu''à ce qu''ils tombent et que la poêle soit sèche, environ 2 min ; assaisonner.","Battre les œufs avec le lait, le parmesan, du sel et du poivre.","Verser les œufs sur les légumes, bien répartir et cuire à feu doux 3 à 4 min, jusqu''à ce que les bords commencent à prendre.","Enfourner 10 à 12 min, jusqu''à ce que le centre soit juste pris et souple au toucher.","Laisser reposer 2 min, couper en parts et servir tiède avec le pain."]},"it":{"title":"Frittata di funghi e spinaci con pane","steps":["Scaldare il forno a 180 °C.","Scaldare l''olio in una padella da 24 cm adatta al forno, a fuoco medio, e appassire la cipolla per 5 min.","Aggiungere i funghi, l''aglio e il timo e cuocere 6-8 min, finché i funghi sono dorati e la loro acqua è evaporata.","Unire gli spinaci a manciate e mescolare finché sono appassiti e la padella è asciutta, circa 2 min; salare e pepare.","Sbattere le uova con il latte, il parmigiano, sale e pepe.","Versare le uova sulle verdure, distribuire bene e cuocere a fuoco basso 3-4 min, finché i bordi iniziano a rapprendersi.","Infornare per 10-12 min, finché il centro è appena rappreso ed elastico al tatto.","Lasciare riposare 2 min, tagliare a spicchi e servire tiepida con il pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '91e8fa61-df06-405b-a7c2-209948b7784f')
  returning id
)
