-- Mushroom, lentil and walnut ragù
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '966cf969-f9be-46cc-8715-4c5085874d48'::uuid, null, 'Mushroom, lentil and walnut ragù', 'seed', null, 'Claude', null, null,
    2, null, 55, 15, 40, '["Soften the onion, carrot and celery in the oil in a wide pan over medium heat for 8 min.","Add the mushrooms and walnuts and cook for 8–10 min, stirring, until the mushrooms have given up their liquid and start to brown.","Stir in the garlic and tomato paste for 1 min, then pour in the wine and let it bubble until reduced by half.","Add the tomatoes, stock, lentils, soy sauce, thyme and bay leaf, bring to a simmer, cover partly and cook for 25–30 min, stirring now and then, until the lentils are soft and the sauce is thick; add a splash of water if it gets dry.","Meanwhile cook the pasta in salted boiling water until al dente, keeping a mug of the cooking water.","Remove the thyme and bay leaf, season the ragù and toss with the pasta, loosening with cooking water; serve with basil."]'::jsonb,
    array['italian', 'vegan', 'vegetarian', 'comfort', 'freezer-friendly']::text[], 'italian', 929, 34.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Ragù de champignons, lentilles et noix","steps":["Faire revenir l''oignon, la carotte et le céleri dans l''huile dans une grande sauteuse à feu moyen 8 min.","Ajouter les champignons et les noix et cuire 8 à 10 min en remuant, jusqu''à ce que les champignons aient rendu leur eau et commencent à dorer.","Incorporer l''ail et le concentré de tomate 1 min, puis verser le vin et laisser réduire de moitié.","Ajouter les tomates, le bouillon, les lentilles, la sauce soja, le thym et le laurier, porter à frémissement, couvrir à moitié et cuire 25 à 30 min en remuant de temps en temps, jusqu''à ce que les lentilles soient fondantes et la sauce épaisse ; ajouter un peu d''eau si besoin.","Pendant ce temps, cuire les pâtes al dente dans de l''eau bouillante salée en gardant un bol d''eau de cuisson.","Retirer le thym et le laurier, assaisonner le ragù et le mélanger aux pâtes en détendant avec l''eau de cuisson ; servir avec le basilic."]},"it":{"title":"Ragù di funghi, lenticchie e noci","steps":["Appassire cipolla, carota e sedano nell''olio in una padella larga a fuoco medio per 8 min.","Aggiungere i funghi e le noci e cuocere 8-10 min mescolando, finché i funghi hanno perso l''acqua e iniziano a dorare.","Unire l''aglio e il concentrato per 1 min, poi sfumare con il vino e lasciarlo ridurre della metà.","Aggiungere i pomodori, il brodo, le lenticchie, la salsa di soia, il timo e l''alloro, portare a bollore leggero, coprire a metà e cuocere 25-30 min mescolando ogni tanto, finché le lenticchie sono morbide e il sugo è denso; aggiungere un goccio d''acqua se si asciuga troppo.","Nel frattempo cuocere la pasta al dente in acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Togliere timo e alloro, regolare di sale e pepe e saltare il ragù con la pasta, allungando con l''acqua di cottura; servire con il basilico."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '966cf969-f9be-46cc-8715-4c5085874d48')
  returning id
)
