-- Prawn, courgette and lemon linguine
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4ac67db3-15f0-4505-a682-a9989c256c89'::uuid, null, 'Prawn, courgette and lemon linguine', 'seed', null, 'Claude', null, null,
    2, null, 22, 10, 12, '["Cook the linguine in a large pot of salted boiling water until al dente, keeping a mug of the cooking water.","Meanwhile heat 2 tbsp oil in a large frying pan over high heat and fry the courgette for 4–5 min, until golden at the edges; season and set aside.","Add the remaining oil, the garlic and a pinch of chili flakes to the pan for 30 s, then add the prawns and cook for 2–3 min, turning once, until pink all over.","Return the courgette and add the lemon zest and half the juice.","Tip in the drained linguine with a splash of cooking water and toss over the heat for 1 min, until glossy.","Add the parsley, more lemon juice to taste, salt and pepper, and serve straight away."]'::jsonb,
    array['italian', 'quick', 'summer', 'mediterranean']::text[], 'italian', 697, 43.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Linguine aux crevettes, courgette et citron","steps":["Cuire les linguine al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, chauffer 2 c. à soupe d''huile dans une grande poêle à feu vif et faire dorer la courgette 4 à 5 min ; assaisonner et réserver.","Ajouter le reste d''huile, l''ail et une pincée de piment dans la poêle 30 s, puis ajouter les crevettes et cuire 2 à 3 min en les retournant une fois, jusqu''à ce qu''elles soient roses.","Remettre la courgette et ajouter le zeste et la moitié du jus de citron.","Ajouter les linguine égouttées avec un peu d''eau de cuisson et mélanger sur le feu 1 min, jusqu''à ce qu''elles soient brillantes.","Ajouter le persil, du jus de citron selon le goût, du sel et du poivre, et servir aussitôt."]},"it":{"title":"Linguine con gamberi, zucchine e limone","steps":["Cuocere le linguine al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo scaldare 2 cucchiai d''olio in una padella grande a fuoco vivo e dorare la zucchina per 4-5 min; salare e mettere da parte.","Aggiungere nella padella l''olio rimasto, l''aglio e un pizzico di peperoncino per 30 s, poi i gamberi e cuocerli 2-3 min girandoli una volta, finché sono rosa.","Rimettere la zucchina e aggiungere la scorza e metà del succo di limone.","Unire le linguine scolate con un po'' di acqua di cottura e saltare sul fuoco 1 min, finché sono lucide.","Aggiungere il prezzemolo, altro succo di limone a piacere, sale e pepe, e servire subito."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4ac67db3-15f0-4505-a682-a9989c256c89')
  returning id
)
