-- Tomato and mozzarella flatbread pizzas
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a5aace29-d33e-4a90-9a9a-5ec39bbd6f9b'::uuid, null, 'Tomato and mozzarella flatbread pizzas', 'seed', null, 'Claude', null, null,
    2, null, 22, 10, 12, '["Heat the oven to 220°C and put a baking tray in to heat.","Pat the sliced tomatoes and the torn mozzarella dry with kitchen paper.","Mix the passata with the garlic, a pinch of oregano and salt, and spread it thinly over the flatbreads, leaving a narrow border.","Scatter over the grated mozzarella, then the tomato slices and torn mozzarella; season and drizzle with the oil.","Slide onto the hot tray and bake for 10–12 min, until the base is crisp and the cheese is bubbling and browned in spots.","Finish with fresh basil and a pinch of chili flakes, and cut into slices."]'::jsonb,
    array['italian', 'pizza', 'treat', 'quick', 'vegetarian', 'summer']::text[], 'italian', 753, 44.5,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pizzas sur pain plat, tomate et mozzarella","steps":["Préchauffer le four à 220 °C avec une plaque à l''intérieur.","Éponger les rondelles de tomate et la mozzarella déchirée avec du papier absorbant.","Mélanger le coulis de tomate avec l''ail, une pincée d''origan et du sel, puis l''étaler finement sur les pains en laissant une petite bordure.","Parsemer de mozzarella râpée, puis des rondelles de tomate et de la mozzarella déchirée ; assaisonner et arroser d''huile.","Glisser sur la plaque chaude et cuire 10 à 12 min, jusqu''à ce que la base soit croustillante et le fromage bouillonnant et doré par endroits.","Garnir de basilic frais et d''une pincée de piment, puis couper en parts."]},"it":{"title":"Pizzette su piadina con pomodoro e mozzarella","steps":["Scaldare il forno a 220 °C con una teglia all''interno.","Tamponare le fette di pomodoro e la mozzarella spezzettata con carta da cucina.","Mescolare la passata con l''aglio, un pizzico di origano e sale e stenderla sottile sulle focacce, lasciando un piccolo bordo.","Distribuire la mozzarella grattugiata, poi le fette di pomodoro e la mozzarella spezzettata; salare, pepare e irrorare con l''olio.","Trasferire sulla teglia calda e cuocere 10-12 min, finché la base è croccante e il formaggio è bollente e dorato qua e là.","Completare con basilico fresco e un pizzico di peperoncino e tagliare a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a5aace29-d33e-4a90-9a9a-5ec39bbd6f9b')
  returning id
)
