-- Pumpkin, sausage and sage risotto
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '05fd4eac-be99-4274-a403-ad8b8821f794'::uuid, null, 'Pumpkin, sausage and sage risotto', 'seed', null, 'Claude', null, null,
    2, null, 55, 15, 40, '["Heat the oven to 200°C. Toss the pumpkin with the oil, half the sage, salt and pepper on a baking tray and roast for 25 min, until soft and caramelised at the edges.","Meanwhile bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, crumble the sausage and fry over medium heat for 5 min, until browned; lift it out, leaving the fat.","Add half the butter, the onion and the rest of the sage to the pan and soften for 5 min.","Add the rice and toast for 2 min, then pour in the wine and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed, for 16–18 min, until the rice is creamy and al dente; stir in the sausage and half the pumpkin, crushed, halfway through.","Off the heat, stir in the remaining butter and the parmesan, cover and rest for 2 min.","Serve topped with the rest of the roasted pumpkin and the crisp sage leaves."]'::jsonb,
    array['italian', 'risotto', 'autumn', 'comfort']::text[], 'italian', 931, 29.5,
    false, 'en', 'medium', '{"pots":3,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Risotto au potiron, saucisse et sauge","steps":["Préchauffer le four à 200 °C. Mélanger le potiron avec l''huile, la moitié de la sauge, du sel et du poivre sur une plaque et rôtir 25 min, jusqu''à ce qu''il soit fondant et caramélisé sur les bords.","Pendant ce temps, porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, émietter la chair à saucisse et la faire dorer à feu moyen 5 min ; la retirer en laissant la graisse.","Ajouter la moitié du beurre, l''oignon et le reste de la sauge et faire fondre 5 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant 16 à 18 min, jusqu''à ce que le riz soit crémeux et al dente ; incorporer la saucisse et la moitié du potiron écrasé à mi-cuisson.","Hors du feu, incorporer le reste du beurre et le parmesan, couvrir et laisser reposer 2 min.","Servir garni du reste du potiron rôti et des feuilles de sauge croustillantes."]},"it":{"title":"Risotto con zucca, salsiccia e salvia","steps":["Scaldare il forno a 200 °C. Condire la zucca con l''olio, metà della salvia, sale e pepe su una teglia e arrostire 25 min, finché è morbida e caramellata ai bordi.","Nel frattempo portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga sbriciolare la salsiccia e rosolarla a fuoco medio per 5 min; toglierla lasciando il grasso.","Aggiungere metà del burro, la cipolla e il resto della salvia e appassire per 5 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per 16-18 min, finché il riso è cremoso e al dente; a metà cottura unire la salsiccia e metà della zucca schiacciata.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano, coprire e lasciare riposare 2 min.","Servire con il resto della zucca arrosto e le foglie di salvia croccanti."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '05fd4eac-be99-4274-a403-ad8b8821f794')
  returning id
)
