-- Tuna, tomato and spinach pasta bake
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4f5355b3-f2fd-4dbd-921a-d50d37544580'::uuid, null, 'Tuna, tomato and spinach pasta bake', 'seed', null, 'Claude', null, null,
    2, null, 40, 10, 30, '["Heat the oven to 180°C.","Cook the pasta in salted boiling water 2 min short of the packet time, then drain.","Meanwhile soften the onion and garlic in the oil in an ovenproof frying pan over medium heat for 4 min.","Add the tomatoes, oregano, salt, pepper and a splash of water and simmer for 5–8 min, until slightly thickened.","Stir the spinach into the sauce until wilted, then take the pan off the heat and stir in the pasta.","Fold in the tuna in large flakes and scatter the mozzarella on top.","Bake for 15–20 min, until the cheese is golden and the sauce is bubbling at the edges; rest for 3 min before serving."]'::jsonb,
    array['italian', 'oven', 'comfort', 'high protein', 'budget']::text[], 'italian', 718, 54.1,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gratin de pâtes au thon, tomate et épinards","steps":["Préchauffer le four à 180 °C.","Cuire les pâtes dans de l''eau bouillante salée 2 min de moins que le temps indiqué, puis les égoutter.","Pendant ce temps, faire revenir l''oignon et l''ail dans l''huile dans une poêle allant au four à feu moyen 4 min.","Ajouter les tomates, l''origan, du sel, du poivre et un peu d''eau et laisser mijoter 5 à 8 min, jusqu''à ce que la sauce épaississe légèrement.","Incorporer les épinards dans la sauce jusqu''à ce qu''ils tombent, puis retirer du feu et ajouter les pâtes.","Incorporer délicatement le thon en gros morceaux et parsemer de mozzarella.","Enfourner 15 à 20 min, jusqu''à ce que le fromage soit doré et la sauce bouillonnante sur les bords ; laisser reposer 3 min avant de servir."]},"it":{"title":"Pasta al forno con tonno, pomodoro e spinaci","steps":["Scaldare il forno a 180 °C.","Cuocere la pasta in acqua bollente salata 2 min in meno del tempo indicato, poi scolarla.","Nel frattempo appassire cipolla e aglio nell''olio in una padella adatta al forno a fuoco medio per 4 min.","Aggiungere i pomodori, l''origano, sale, pepe e un goccio d''acqua e cuocere 5-8 min, finché il sugo si addensa leggermente.","Unire gli spinaci al sugo e farli appassire, poi togliere dal fuoco e mescolare con la pasta.","Incorporare delicatamente il tonno a pezzi grossi e distribuire la mozzarella in superficie.","Infornare per 15-20 min, finché il formaggio è dorato e il sugo bolle ai bordi; lasciare riposare 3 min prima di servire."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4f5355b3-f2fd-4dbd-921a-d50d37544580')
  returning id
)
