-- Sardine, lemon and breadcrumb spaghetti
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '55823f6d-25c8-4972-b71a-6303a4330168'::uuid, null, 'Sardine, lemon and breadcrumb spaghetti', 'seed', null, 'Claude', null, null,
    2, null, 22, 10, 12, '["Cook the spaghetti in a large pot of salted boiling water until al dente, keeping a mug of the cooking water.","Meanwhile toast the breadcrumbs in 1 tbsp oil in a large frying pan over medium heat for 3–4 min, stirring, until golden and crisp; mix in the lemon zest and a pinch of salt and tip into a bowl.","Wipe the pan, add the remaining oil, the garlic, capers and a pinch of chili flakes and cook gently for 1–2 min, without browning the garlic.","Add the sardines and break them into chunks with a spoon; warm through for 1 min.","Add the drained spaghetti with a splash of cooking water, the lemon juice and most of the parsley and toss until glossy.","Serve topped with the crisp breadcrumbs, the rest of the parsley and black pepper."]'::jsonb,
    array['italian', 'quick', 'budget', 'mediterranean', 'high protein']::text[], 'italian', 836, 38.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Spaghetti aux sardines, citron et chapelure","steps":["Cuire les spaghetti al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, faire griller la chapelure dans 1 c. à soupe d''huile dans une grande poêle à feu moyen 3 à 4 min en remuant, jusqu''à ce qu''elle soit dorée et croustillante ; y mélanger le zeste de citron et une pincée de sel, puis la verser dans un bol.","Essuyer la poêle, ajouter le reste d''huile, l''ail, les câpres et une pincée de piment et cuire doucement 1 à 2 min sans colorer l''ail.","Ajouter les sardines et les briser en morceaux à la cuillère ; réchauffer 1 min.","Ajouter les spaghetti égouttés avec un peu d''eau de cuisson, le jus de citron et la majeure partie du persil, et mélanger jusqu''à ce qu''ils soient brillants.","Servir parsemé de chapelure croustillante, du reste de persil et de poivre."]},"it":{"title":"Spaghetti con sarde, limone e pangrattato","steps":["Cuocere gli spaghetti al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo tostare il pangrattato in 1 cucchiaio d''olio in una padella grande a fuoco medio per 3-4 min, mescolando, finché è dorato e croccante; unire la scorza di limone e un pizzico di sale e versarlo in una ciotola.","Pulire la padella, aggiungere l''olio rimasto, l''aglio, i capperi e un pizzico di peperoncino e cuocere dolcemente 1-2 min senza far colorire l''aglio.","Aggiungere le sarde e spezzettarle con un cucchiaio; scaldarle 1 min.","Unire gli spaghetti scolati con un po'' di acqua di cottura, il succo di limone e quasi tutto il prezzemolo e saltare finché sono lucidi.","Servire con il pangrattato croccante, il prezzemolo rimasto e pepe nero."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '55823f6d-25c8-4972-b71a-6303a4330168')
  returning id
)
