-- Pea and asparagus lemon risotto
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4c97e702-12b8-4dc5-a739-715df1150d37'::uuid, null, 'Pea and asparagus lemon risotto', 'seed', null, 'Claude', null, null,
    2, null, 40, 10, 30, '["Cut the asparagus tips off and keep them; slice the stems into 2 cm pieces.","Bring the stock to a simmer in a saucepan and keep it hot.","In a wide pan, soften the shallot in half the butter and the oil over medium heat for 4 min.","Add the rice and toast for 2 min, then pour in the wine with half the lemon juice and let it evaporate.","Add the hot stock a ladle at a time, stirring and letting each be absorbed, for about 10 min; then add the asparagus stems.","After 4 min more, add the tips and the peas and keep adding stock for 4–5 min, until the rice is creamy and al dente and the asparagus is just tender.","Off the heat, stir in the remaining butter, the parmesan, the egg yolk, the lemon zest and the rest of the juice; season, cover and rest for 1 min.","Serve with the mint scattered over."]'::jsonb,
    array['italian', 'risotto', 'spring', 'vegetarian']::text[], 'italian', 777, 29.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Risotto au citron, petits pois et asperges","steps":["Couper les pointes d''asperges et les réserver ; tailler les tiges en tronçons de 2 cm.","Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote dans la moitié du beurre et l''huile à feu moyen 4 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin avec la moitié du jus de citron et laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant environ 10 min ; ajouter alors les tiges d''asperges.","Après 4 min, ajouter les pointes et les petits pois et continuer à mouiller 4 à 5 min, jusqu''à ce que le riz soit crémeux et al dente et les asperges juste tendres.","Hors du feu, incorporer le reste du beurre, le parmesan, le jaune d''œuf, le zeste et le reste du jus de citron ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé de menthe."]},"it":{"title":"Risotto al limone con piselli e asparagi","steps":["Tagliare le punte degli asparagi e tenerle da parte; tagliare i gambi a tocchetti di 2 cm.","Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno in metà del burro e nell''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e metà del succo di limone e lasciare evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per circa 10 min; poi unire i gambi degli asparagi.","Dopo altri 4 min aggiungere le punte e i piselli e continuare a bagnare per 4-5 min, finché il riso è cremoso e al dente e gli asparagi appena teneri.","Fuori dal fuoco mantecare con il burro rimasto, il parmigiano, il tuorlo, la scorza e il resto del succo di limone; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la menta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4c97e702-12b8-4dc5-a739-715df1150d37')
  returning id
)
