-- Sea bass with fennel and orange salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4427b42a-5623-490b-af00-1004887dfb98'::uuid, null, 'Sea bass with fennel and orange salad', 'seed', null, 'Claude', null, null,
    2, null, 35, 15, 20, '["Boil the potatoes in salted water for 15–18 min, until tender; drain and toss with 1 tbsp oil, the parsley and salt.","Meanwhile cut the peel and pith off 1.5 oranges and slice them into rounds; squeeze the remaining half.","Toss the fennel, orange slices, red onion and olives with the orange juice, half the lemon juice, 2 tbsp oil, salt and pepper; leave for 10 min.","Pat the fish dry, score the skin a few times and season both sides.","Heat the remaining oil in a frying pan over medium-high heat and cook the fillets skin side down for 3–4 min, pressing them flat at first, until the skin is crisp.","Turn and cook for 1–2 min more, until the flesh is just opaque; finish with the rest of the lemon juice.","Serve the fish on the salad, scattered with fennel fronds, with the potatoes alongside."]'::jsonb,
    array['italian', 'winter', 'light', 'mediterranean', 'fancy']::text[], 'italian', 729, 30.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Bar, salade de fenouil et d''orange","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres ; les égoutter et les mélanger avec 1 c. à soupe d''huile, le persil et du sel.","Pendant ce temps, peler à vif 1,5 orange et la couper en rondelles ; presser la demi-orange restante.","Mélanger le fenouil, les rondelles d''orange, l''oignon rouge et les olives avec le jus d''orange, la moitié du jus de citron, 2 c. à soupe d''huile, du sel et du poivre ; laisser reposer 10 min.","Sécher le poisson, inciser la peau à quelques endroits et assaisonner des deux côtés.","Chauffer le reste d''huile dans une poêle à feu moyen-vif et cuire les filets côté peau 3 à 4 min, en les pressant au début, jusqu''à ce que la peau soit croustillante.","Retourner et cuire encore 1 à 2 min, jusqu''à ce que la chair soit juste nacrée ; arroser du reste de jus de citron.","Servir le poisson sur la salade, parsemé de pluches de fenouil, avec les pommes de terre à côté."]},"it":{"title":"Branzino con insalata di finocchi e arance","steps":["Lessare le patate in acqua salata per 15-18 min, finché sono tenere; scolarle e condirle con 1 cucchiaio d''olio, il prezzemolo e sale.","Nel frattempo pelare a vivo 1 arancia e mezza e tagliarla a fette; spremere la mezza arancia rimasta.","Condire finocchio, fette d''arancia, cipolla rossa e olive con il succo d''arancia, metà del succo di limone, 2 cucchiai d''olio, sale e pepe; lasciare insaporire 10 min.","Asciugare il pesce, incidere la pelle in qualche punto e salare e pepare da entrambi i lati.","Scaldare l''olio rimasto in una padella a fuoco medio-alto e cuocere i filetti dal lato della pelle per 3-4 min, premendoli all''inizio, finché la pelle è croccante.","Girarli e cuocere ancora 1-2 min, finché la carne è appena opaca; irrorare con il resto del succo di limone.","Servire il pesce sull''insalata, con le barbe del finocchio, e le patate a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4427b42a-5623-490b-af00-1004887dfb98')
  returning id
)
