-- Smoked salmon and pea spaghetti
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '2fd32898-57b1-45e1-83f9-89850157adf0'::uuid, null, 'Smoked salmon and pea spaghetti', 'seed', null, 'Claude', null, null,
    2, null, 22, 10, 12, '["Cook the spaghetti in a large pot of salted boiling water, adding the peas for the last 3 min.","Meanwhile whisk the yogurt, cream, egg yolk, parmesan, lemon zest, salt and plenty of pepper in a bowl.","Keep a mug of the cooking water, then drain the pasta and peas and return them to the pot off the heat with 3 tbsp of the water.","Pour in the sauce and toss over very low heat for 1–2 min, until creamy and coating the pasta; don''t let it boil or the egg will scramble.","Fold in the smoked salmon and most of the chives, add a squeeze of lemon and loosen with more cooking water if needed.","Serve straight away with the rest of the chives and black pepper."]'::jsonb,
    array['italian', 'quick', 'spring', 'high protein']::text[], 'italian', 711, 40,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Spaghetti au saumon fumé et petits pois","steps":["Cuire les spaghetti dans une grande casserole d''eau bouillante salée en ajoutant les petits pois pendant les 3 dernières minutes.","Pendant ce temps, fouetter le yaourt, la crème, le jaune d''œuf, le parmesan, le zeste de citron, du sel et beaucoup de poivre dans un bol.","Garder un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois et les remettre dans la casserole hors du feu avec 3 c. à soupe d''eau.","Verser la sauce et mélanger sur feu très doux 1 à 2 min, jusqu''à ce qu''elle soit crémeuse et enrobe les pâtes ; ne pas laisser bouillir pour que l''œuf ne coagule pas.","Incorporer le saumon fumé et la majeure partie de la ciboulette, ajouter un filet de citron et détendre avec un peu d''eau de cuisson si besoin.","Servir aussitôt avec le reste de la ciboulette et du poivre."]},"it":{"title":"Spaghetti con salmone affumicato e piselli","steps":["Cuocere gli spaghetti in abbondante acqua bollente salata, aggiungendo i piselli negli ultimi 3 min.","Nel frattempo sbattere in una ciotola lo yogurt, la panna, il tuorlo, il parmigiano, la scorza di limone, sale e abbondante pepe.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli e rimetterli nella pentola fuori dal fuoco con 3 cucchiai d''acqua.","Versare la salsa e mescolare a fuoco bassissimo per 1-2 min, finché è cremosa e avvolge la pasta; non farla bollire o l''uovo si rapprende.","Unire il salmone affumicato e quasi tutta l''erba cipollina, aggiungere una spruzzata di limone e allungare con altra acqua di cottura se serve.","Servire subito con l''erba cipollina rimasta e pepe nero."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '2fd32898-57b1-45e1-83f9-89850157adf0')
  returning id
)
