-- Gambas al ajillo with white beans
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0dce17d0-cb2a-43f8-9113-4566cf6ea46b'::uuid, null, 'Gambas al ajillo with white beans', 'seed', null, 'Claude', null, null,
    2, null, 20, 10, 10, '["Toast the bread slices in a dry frying pan for 1-2 min per side, then set aside.","Pat the prawns dry and season with a pinch of salt.","Warm the oil, garlic and chilli in the pan over medium heat for 2-3 min, until the garlic is just turning golden.","Raise the heat, add the prawns and cook 1 min per side until pink.","Pour in the sherry, sprinkle over the paprika and let it bubble for 30 s.","Add the beans and toss for 2-3 min until hot and coated in the garlic oil. Finish with a squeeze of lemon and the parsley and serve with the toast for dipping."]'::jsonb,
    array['spanish', 'quick', 'high protein', 'mediterranean']::text[], 'spanish', 702, 44.1,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Gambas al ajillo aux haricots blancs","steps":["Griller les tranches de pain dans une poêle sèche 1 à 2 min de chaque côté, puis réserver.","Sécher les crevettes et les saler légèrement.","Chauffer l''huile, l''ail et le piment dans la poêle à feu moyen 2 à 3 min, jusqu''à ce que l''ail commence à blondir.","Monter le feu, ajouter les crevettes et cuire 1 min de chaque côté jusqu''à ce qu''elles rosissent.","Verser le xérès, saupoudrer de paprika et laisser bouillonner 30 s.","Ajouter les haricots et mélanger 2 à 3 min jusqu''à ce qu''ils soient chauds et enrobés d''huile à l''ail. Finir avec un filet de citron et le persil et servir avec le pain grillé pour saucer."]},"it":{"title":"Gamberi all''aglio con fagioli bianchi","steps":["Tostare le fette di pane in una padella asciutta 1-2 min per lato, poi tenerle da parte.","Asciugare i gamberi e salarli leggermente.","Scaldare l''olio, l''aglio e il peperoncino nella padella a fuoco medio per 2-3 min, finché l''aglio inizia a dorare.","Alzare la fiamma, aggiungere i gamberi e cuocere 1 min per lato finché diventano rosa.","Versare lo sherry, cospargere di paprika e lasciar sobbollire 30 s.","Aggiungere i fagioli e saltare 2-3 min finché sono caldi e ricoperti d''olio all''aglio. Completare con una spruzzata di limone e il prezzemolo e servire con il pane tostato per fare la scarpetta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0dce17d0-cb2a-43f8-9113-4566cf6ea46b')
  returning id
)
