-- Arroz con pollo y chorizo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'a5894a47-22ee-42d7-9927-2b4caead1eef'::uuid, null, 'Arroz con pollo y chorizo', 'seed', null, 'Claude', null, null,
    2, null, 55, 15, 40, '["Season the chicken and brown it in the oil in a wide, deep pan over medium-high heat for 5-6 min. Set aside.","Add the chorizo and cook 2 min until it releases its red oil.","Add the onion and pepper and cook over medium heat for 8 min until soft.","Stir in the garlic, paprika and grated tomato and cook 4 min until thick.","Add the rice and stir for 1 min to coat it.","Pour in the stock, crumble in the saffron, add the bay leaf and the chicken, season and bring to the boil.","Cover and simmer on low heat for 18 min; scatter the peas over for the last 5 min, until the rice is tender and still a little moist.","Rest 5 min off the heat, then serve with parsley."]'::jsonb,
    array['spanish', 'one-pot', 'comfort', 'generous', 'high protein']::text[], 'spanish', 887, 47.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Riz au poulet et chorizo","steps":["Assaisonner le poulet et le faire dorer dans l''huile dans une sauteuse profonde à feu moyen-vif 5 à 6 min. Réserver.","Ajouter le chorizo et cuire 2 min jusqu''à ce qu''il rende son huile rouge.","Ajouter l''oignon et le poivron et cuire à feu moyen 8 min jusqu''à ce qu''ils soient tendres.","Incorporer l''ail, le paprika et la tomate râpée et cuire 4 min jusqu''à ce que ce soit épais.","Ajouter le riz et remuer 1 min pour bien l''enrober.","Verser le bouillon, émietter le safran, ajouter le laurier et le poulet, assaisonner et porter à ébullition.","Couvrir et laisser mijoter à feu doux 18 min ; parsemer les petits pois les 5 dernières minutes, jusqu''à ce que le riz soit tendre et encore un peu moelleux.","Laisser reposer 5 min hors du feu, puis servir avec le persil."]},"it":{"title":"Riso con pollo e chorizo","steps":["Condire il pollo e rosolarlo nell''olio in una padella larga e profonda a fuoco medio-alto per 5-6 min. Tenerlo da parte.","Aggiungere il chorizo e cuocere 2 min finché rilascia il suo olio rosso.","Aggiungere la cipolla e il peperone e cuocere a fuoco medio 8 min finché sono morbidi.","Unire l''aglio, la paprika e il pomodoro grattugiato e cuocere 4 min finché si addensa.","Aggiungere il riso e mescolare 1 min per insaporirlo.","Versare il brodo, sbriciolare lo zafferano, aggiungere l''alloro e il pollo, regolare di sale e pepe e portare a bollore.","Coprire e cuocere a fuoco basso 18 min; aggiungere i piselli negli ultimi 5 min, finché il riso è tenero e ancora un po'' umido.","Lasciare riposare 5 min fuori dal fuoco, poi servire con il prezzemolo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'a5894a47-22ee-42d7-9927-2b4caead1eef')
  returning id
)
