-- Lamb burgers with feta and tomato salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '69d6a6a6-0d99-43e5-b62f-57968b7e02c9'::uuid, null, 'Lamb burgers with feta and tomato salad', 'seed', null, 'Claude', null, null,
    2, null, 45, 20, 10, '["Squeeze the grated tomato in your hand to drain it, then mix it into the lamb with the garlic, half the oregano, the mint, parsley, salt and pepper. Shape 2 patties 2 cm thick and chill 15 min.","Mash the feta into the yogurt with a little pepper to make a thick sauce.","Toss the tomato wedges, cucumber, red onion and olives with the vinegar, 1 tbsp oil, the rest of the oregano and salt.","Heat a griddle pan over medium-high heat and cook the burgers 4-5 min per side, until well browned and cooked through. Rest 2 min.","Toast the cut sides of the buns in the pan, 1 min.","Spread the buns with feta sauce, add the burgers and serve the tomato salad on the side."]'::jsonb,
    array['greek', 'burger', 'grill', 'summer', 'mediterranean']::text[], 'greek', 725, 44.7,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Burgers d''agneau à la feta, salade de tomates","steps":["Presser la tomate râpée dans la main pour l''égoutter, puis la mélanger à l''agneau avec l''ail, la moitié de l''origan, la menthe, le persil, du sel et du poivre. Former 2 steaks de 2 cm d''épaisseur et réfrigérer 15 min.","Écraser la feta dans le yaourt avec un peu de poivre pour obtenir une sauce épaisse.","Mélanger les quartiers de tomate, le concombre, l''oignon rouge et les olives avec le vinaigre, 1 c. à soupe d''huile, le reste de l''origan et du sel.","Faire chauffer une poêle-gril à feu moyen-vif et cuire les burgers 4 à 5 min par face, jusqu''à ce qu''ils soient bien dorés et cuits à cœur. Laisser reposer 2 min.","Toaster la face coupée des pains dans la poêle, 1 min.","Tartiner les pains de sauce à la feta, ajouter les steaks et servir la salade de tomates à côté."]},"it":{"title":"Burger di agnello con feta e insalata di pomodori","steps":["Strizzare con la mano il pomodoro grattugiato per scolarlo, poi unirlo all''agnello con l''aglio, metà dell''origano, la menta, il prezzemolo, sale e pepe. Formare 2 hamburger spessi 2 cm e metterli in frigo 15 min.","Schiacciare la feta nello yogurt con un po'' di pepe per ottenere una salsa densa.","Condire gli spicchi di pomodoro, il cetriolo, la cipolla rossa e le olive con l''aceto, 1 cucchiaio d''olio, l''origano rimasto e sale.","Scaldare una bistecchiera a fuoco medio-alto e cuocere gli hamburger 4-5 min per lato, finché sono ben rosolati e cotti all''interno. Lasciare riposare 2 min.","Tostare il lato tagliato dei panini nella bistecchiera, 1 min.","Spalmare i panini con la salsa alla feta, aggiungere gli hamburger e servire l''insalata di pomodori a parte."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '69d6a6a6-0d99-43e5-b62f-57968b7e02c9')
  returning id
)
