-- Tajine d'agneau aux pruneaux
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '9a6ee5cf-200e-4579-9433-3f98f473c9de'::uuid, null, 'Tajine d''agneau aux pruneaux', 'seed', null, 'Claude', null, null,
    2, null, 125, 15, 110, '["Soften the onion in 1 tbsp oil in a heavy pot over medium heat, 3-4 min.","Add the lamb, cinnamon stick, turmeric, ginger, plenty of pepper and a little salt; turn to coat, then pour in 300 ml water.","Bring to the boil, cover and simmer very gently for 1 h 15, until the lamb is almost tender; add a splash of water if it gets dry.","Add the prunes and cook 20 min more, covered.","Stir the honey with the ground cinnamon into the sauce and simmer uncovered 15 min, until it turns thick and glossy.","Meanwhile toast the almonds in a dry frying pan over medium heat, 3-4 min, shaking, until golden.","Serve the tagine scattered with almonds and sesame seeds, with bread to mop up the sauce."]'::jsonb,
    array['north african', 'moroccan', 'stew', 'winter', 'comfort', 'high protein']::text[], 'north african', 945, 50.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tajine d''agneau aux pruneaux","steps":["Faire fondre l''oignon dans 1 c. à soupe d''huile dans une cocotte à feu moyen, 3 à 4 min.","Ajouter l''agneau, le bâton de cannelle, le curcuma, le gingembre, beaucoup de poivre et un peu de sel ; bien enrober, puis verser 300 ml d''eau.","Porter à ébullition, couvrir et laisser mijoter très doucement 1 h 15, jusqu''à ce que l''agneau soit presque tendre ; ajouter un peu d''eau si cela attache.","Ajouter les pruneaux et cuire encore 20 min à couvert.","Mélanger le miel et la cannelle moulue à la sauce et laisser mijoter 15 min à découvert, jusqu''à ce qu''elle soit épaisse et brillante.","Pendant ce temps, faire griller les amandes à sec dans une poêle à feu moyen, 3 à 4 min en remuant, jusqu''à ce qu''elles soient dorées.","Servir le tajine parsemé d''amandes et de graines de sésame, avec du pain pour saucer."]},"it":{"title":"Tajine d''agnello alle prugne","steps":["Appassire la cipolla in 1 cucchiaio d''olio in una pentola dal fondo spesso a fuoco medio, 3-4 min.","Aggiungere l''agnello, la stecca di cannella, la curcuma, lo zenzero, abbondante pepe e un po'' di sale; mescolare bene, poi versare 300 ml d''acqua.","Portare a bollore, coprire e cuocere a fuoco dolcissimo 1 h 15, finché l''agnello è quasi tenero; aggiungere un goccio d''acqua se si asciuga.","Aggiungere le prugne e cuocere ancora 20 min, coperto.","Mescolare il miele e la cannella in polvere nel sugo e cuocere scoperto 15 min, finché è denso e lucido.","Nel frattempo tostare le mandorle in una padella asciutta a fuoco medio, 3-4 min scuotendo, finché sono dorate.","Servire il tajine cosparso di mandorle e semi di sesamo, con pane per fare la scarpetta."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '9a6ee5cf-200e-4579-9433-3f98f473c9de')
  returning id
)
