-- Chermoula prawns with couscous
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'ea0abd75-bf32-4718-9c3a-4ccfd8fc9917'::uuid, null, 'Chermoula prawns with couscous', 'seed', null, 'Claude', null, null,
    2, null, 20, 12, 8, '["Mix the coriander, parsley, garlic, cumin, paprika, chilli, the zest and juice of half the lemon, 2 tbsp oil and a pinch of salt into a loose chermoula.","Toss the prawns with half the chermoula and leave 5 min.","Bring the stock to the boil, pour it over the couscous in a bowl with 1 tsp oil, cover and leave 5 min, then fluff with a fork and stir in the grated carrot.","Cook the prawns in a hot frying pan with the remaining oil over medium-high heat, 3-4 min, turning once, until pink and just cooked through.","Spoon the prawns over the couscous, drizzle with the rest of the chermoula and serve with the other lemon half in wedges."]'::jsonb,
    array['north african', 'quick', 'healthy', 'high protein']::text[], 'north african', 650, 42.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Crevettes à la chermoula et semoule","steps":["Mélanger la coriandre, le persil, l''ail, le cumin, le paprika, le piment, le zeste et le jus d''un demi-citron, 2 c. à soupe d''huile et une pincée de sel pour obtenir une chermoula fluide.","Enrober les crevettes de la moitié de la chermoula et laisser reposer 5 min.","Porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min, puis égrener à la fourchette et incorporer la carotte râpée.","Cuire les crevettes dans une poêle bien chaude avec le reste de l''huile à feu moyen-vif, 3 à 4 min en les retournant une fois, jusqu''à ce qu''elles soient roses et juste cuites.","Déposer les crevettes sur la semoule, arroser du reste de chermoula et servir avec l''autre demi-citron en quartiers."]},"it":{"title":"Gamberi alla chermoula con cuscus","steps":["Mescolare coriandolo, prezzemolo, aglio, cumino, paprika, peperoncino, la scorza e il succo di mezzo limone, 2 cucchiai d''olio e un pizzico di sale per ottenere una chermoula fluida.","Condire i gamberi con metà della chermoula e lasciare riposare 5 min.","Portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min, poi sgranare con una forchetta e unire la carota grattugiata.","Cuocere i gamberi in una padella ben calda con l''olio rimasto a fuoco medio-alto, 3-4 min girandoli una volta, finché sono rosa e appena cotti.","Disporre i gamberi sul cuscus, condire con la chermoula rimasta e servire con l''altra metà del limone a spicchi."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'ea0abd75-bf32-4718-9c3a-4ccfd8fc9917')
  returning id
)
