-- Coconut chickpea and pumpkin curry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '6bc1c089-e3e1-4387-b021-e752bd4966a1'::uuid, null, 'Coconut chickpea and pumpkin curry', 'seed', null, 'Claude', null, null,
    2, null, 45, 15, 30, '["Rinse the rice and cook it in 240 ml salted water, covered, over low heat for 12 min; rest 5 min off the heat.","Heat 2 tbsp oil in a wide pan over medium heat, add the mustard seeds and cumin and let them sizzle and pop for 30 s.","Add the onion, garlic and ginger and cook 5 min until soft, then the tomato, ground coriander, turmeric, chilli powder and salt, and cook 3 min until the tomato breaks down.","Add the pumpkin, chickpeas and 250 ml water, cover and simmer 15 min, until the pumpkin is tender.","Stir in the coconut milk, garam masala and spinach and simmer uncovered 3-4 min, until the spinach wilts and the sauce thickens.","Finish with the lime juice and coriander and serve with the rice."]'::jsonb,
    array['indian', 'asian', 'curry', 'vegan', 'autumn', 'budget']::text[], 'indian', 922, 30.6,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Curry de pois chiches et potiron au lait de coco","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Chauffer 2 c. à soupe d''huile dans une grande sauteuse à feu moyen, ajouter les graines de moutarde et le cumin et les laisser grésiller et éclater 30 s.","Ajouter l''oignon, l''ail et le gingembre et cuire 5 min jusqu''à ce qu''ils soient tendres, puis la tomate, la coriandre moulue, le curcuma, le piment et du sel, et cuire 3 min jusqu''à ce que la tomate se défasse.","Ajouter le potiron, les pois chiches et 250 ml d''eau, couvrir et laisser mijoter 15 min, jusqu''à ce que le potiron soit tendre.","Incorporer le lait de coco, le garam masala et les épinards et laisser frémir 3 à 4 min à découvert, jusqu''à ce que les épinards tombent et que la sauce épaississe.","Finir avec le jus de citron vert et la coriandre et servir avec le riz."]},"it":{"title":"Curry di ceci e zucca al cocco","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare 2 cucchiai d''olio in una padella larga a fuoco medio, aggiungere i semi di senape e il cumino e lasciarli sfrigolare e scoppiettare 30 s.","Aggiungere cipolla, aglio e zenzero e cuocere 5 min finché sono morbidi, poi il pomodoro, il coriandolo in polvere, la curcuma, il peperoncino e il sale, e cuocere 3 min finché il pomodoro si disfa.","Aggiungere la zucca, i ceci e 250 ml d''acqua, coprire e cuocere 15 min, finché la zucca è tenera.","Unire il latte di cocco, il garam masala e gli spinaci e cuocere scoperto 3-4 min, finché gli spinaci appassiscono e il sugo si addensa.","Completare con il succo di lime e il coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '6bc1c089-e3e1-4387-b021-e752bd4966a1')
  returning id
)
