-- Keema aloo
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '4c3bafea-b644-4721-b329-1da8f0824459'::uuid, null, 'Keema aloo', 'seed', null, 'Claude', null, null,
    2, null, 50, 10, 40, '["Heat 2 tbsp oil in a heavy lidded pan over medium heat, add the cumin seeds, bay leaf, cinnamon and cloves and fry 1 min, until fragrant.","Add the onion and cook 6-8 min until golden, then the garlic and ginger for 1 min.","Add the beef and cook over medium-high heat 6-8 min, breaking it up, until browned and its liquid has evaporated.","Stir in the ground coriander, ground cumin, turmeric, chilli powder and 1 tsp salt for 2 min, then add the tomatoes and potatoes.","Pour in 200 ml water, cover and simmer on low heat 20 min, stirring now and then, until the potatoes are tender and the oil rises to the top.","Add the peas and garam masala and cook 3 min more, uncovered, until the sauce clings to the meat.","Finish with the lemon juice and coriander and serve with warm flatbread."]'::jsonb,
    array['indian', 'asian', 'curry', 'one-pot', 'comfort', 'budget']::text[], 'indian', 774, 49.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Keema aloo (bœuf haché et pommes de terre)","steps":["Chauffer 2 c. à soupe d''huile dans une sauteuse à fond épais avec couvercle à feu moyen, ajouter les graines de cumin, le laurier, la cannelle et les clous de girofle et faire revenir 1 min, jusqu''à ce qu''ils embaument.","Ajouter l''oignon et cuire 6 à 8 min jusqu''à ce qu''il soit doré, puis l''ail et le gingembre 1 min.","Ajouter le bœuf et cuire à feu moyen-vif 6 à 8 min en l''émiettant, jusqu''à ce qu''il soit doré et que son jus se soit évaporé.","Incorporer la coriandre moulue, le cumin moulu, le curcuma, le piment et 1 c. à café de sel 2 min, puis ajouter les tomates et les pommes de terre.","Verser 200 ml d''eau, couvrir et laisser mijoter à feu doux 20 min en remuant de temps en temps, jusqu''à ce que les pommes de terre soient tendres et que l''huile remonte en surface.","Ajouter les petits pois et le garam masala et cuire encore 3 min à découvert, jusqu''à ce que la sauce nappe la viande.","Finir avec le jus de citron et la coriandre et servir avec du pain plat chaud."]},"it":{"title":"Keema aloo (macinato di manzo e patate)","steps":["Scaldare 2 cucchiai d''olio in una padella dal fondo spesso con coperchio a fuoco medio, aggiungere i semi di cumino, l''alloro, la cannella e i chiodi di garofano e soffriggere 1 min, finché profumano.","Aggiungere la cipolla e cuocere 6-8 min finché è dorata, poi aglio e zenzero per 1 min.","Aggiungere il manzo e cuocere a fuoco medio-alto 6-8 min sgranandolo, finché è rosolato e il liquido è evaporato.","Unire coriandolo in polvere, cumino in polvere, curcuma, peperoncino e 1 cucchiaino di sale per 2 min, poi aggiungere i pomodori e le patate.","Versare 200 ml d''acqua, coprire e cuocere a fuoco basso 20 min mescolando ogni tanto, finché le patate sono tenere e l''olio affiora in superficie.","Aggiungere i piselli e il garam masala e cuocere ancora 3 min scoperto, finché il sugo avvolge la carne.","Completare con il succo di limone e il coriandolo e servire con pane piatto caldo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '4c3bafea-b644-4721-b329-1da8f0824459')
  returning id
)
