-- Matar paneer
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8cf5200c-38b4-4aa5-aa57-44228ae164ec'::uuid, null, 'Matar paneer', 'seed', null, 'Claude', null, null,
    2, null, 25, 8, 17, '["Rinse the rice and cook it covered in 250 ml salted water, 12 min on low heat; rest 5 min.","Brown the paneer in half the butter in a frying pan, 1-2 min per side, until golden. Set aside.","Add the oil and the rest of the butter, the cumin seeds for 30 s, then the onion; cook 5 min until light golden.","Add the garlic and ginger for 1 min, then the turmeric, chili powder and ground coriander for 30 s.","Pour in the passata with a little salt and cook 4 min, stirring, until thick and the oil separates.","Add the peas and 150 ml water and simmer 5 min.","Add the paneer and garam masala and simmer 2 min. Stir in the cream, scatter with coriander and serve with the rice."]'::jsonb,
    array['indian', 'asian', 'curry', 'vegetarian', 'quick']::text[], 'indian', 918, 35.9,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Matar paneer (paneer aux petits pois)","steps":["Rincer le riz et le cuire à couvert dans 250 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Faire dorer le paneer dans la moitié du beurre dans une poêle, 1 à 2 min de chaque côté. Réserver.","Ajouter l''huile et le reste du beurre, le cumin 30 s, puis l''oignon ; cuire 5 min jusqu''à ce qu''il soit légèrement doré.","Ajouter l''ail et le gingembre 1 min, puis le curcuma, le piment en poudre et la coriandre en poudre 30 s.","Verser le coulis de tomate avec un peu de sel et cuire 4 min en remuant, jusqu''à ce qu''il épaississe et que l''huile se sépare.","Ajouter les petits pois et 150 ml d''eau et laisser mijoter 5 min.","Ajouter le paneer et le garam masala et laisser mijoter 2 min. Incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Matar paneer (paneer con piselli)","steps":["Sciacquare il riso e cuocerlo coperto in 250 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Dorare il paneer in metà del burro in una padella, 1-2 min per lato. Tenere da parte.","Aggiungere l''olio e il resto del burro, il cumino per 30 s, poi la cipolla; cuocere 5 min finché è leggermente dorata.","Aggiungere aglio e zenzero per 1 min, poi curcuma, peperoncino in polvere e coriandolo macinato per 30 s.","Versare la passata con un po'' di sale e cuocere 4 min mescolando, finché si addensa e l''olio si separa.","Aggiungere i piselli e 150 ml di acqua e cuocere a fuoco lento 5 min.","Aggiungere il paneer e il garam masala e cuocere 2 min. Unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8cf5200c-38b4-4aa5-aa57-44228ae164ec')
  returning id
)
