-- Ginger beef lettuce cups with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8374c9b3-57b9-4cc7-be98-c4ae66518e2a'::uuid, null, 'Ginger beef lettuce cups with rice', 'seed', null, 'Claude', null, null,
    2, null, 35, 15, 20, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Heat the oil in a large frying pan over high heat and brown the beef, breaking it up, 5-6 min until well caramelised at the edges. Set aside.","In the same pan, cook the onion, pepper, carrot, garlic and ginger 3-4 min until softened.","Return the beef, add the oyster sauce, hoisin, soy sauce and stock and stir-fry 3-4 min until the liquid has gone and the mince is dry and sticky.","Stir in the sesame oil and take off the heat.","Spoon the beef into the lettuce leaves, top with spring onion, peanuts and chili flakes and serve with the rice."]'::jsonb,
    array['chinese', 'asian', 'light', 'high protein']::text[], 'chinese', 797, 45,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Bouchées de laitue au bœuf gingembre et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Chauffer l''huile dans une grande poêle à feu vif et faire dorer le bœuf en l''émiettant, 5 à 6 min, jusqu''à ce qu''il soit bien caramélisé. Réserver.","Dans la même poêle, faire revenir l''oignon, le poivron, la carotte, l''ail et le gingembre 3 à 4 min jusqu''à ce qu''ils soient tendres.","Remettre le bœuf, ajouter la sauce d''huître, la sauce hoisin, la sauce soja et le bouillon et faire sauter 3 à 4 min jusqu''à ce que le liquide soit absorbé et la viande sèche et laquée.","Incorporer l''huile de sésame et retirer du feu.","Garnir les feuilles de laitue de bœuf, parsemer d''oignon nouveau, de cacahuètes et de piment et servir avec le riz."]},"it":{"title":"Coppette di lattuga con manzo allo zenzero e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Scaldare l''olio in una padella grande a fuoco vivo e rosolare il manzo sbriciolandolo, 5-6 min, finché è ben caramellato ai bordi. Tenere da parte.","Nella stessa padella, cuocere cipolla, peperone, carota, aglio e zenzero 3-4 min finché si ammorbidiscono.","Rimettere il manzo, aggiungere salsa di ostriche, salsa hoisin, salsa di soia e brodo e saltare 3-4 min finché il liquido è evaporato e la carne è asciutta e glassata.","Unire l''olio di sesamo e togliere dal fuoco.","Distribuire il manzo nelle foglie di lattuga, completare con cipollotto, arachidi e peperoncino e servire con il riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8374c9b3-57b9-4cc7-be98-c4ae66518e2a')
  returning id
)
