-- Cumin lamb stir-fry
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'beeb1367-a9d8-4d08-aac1-88fd80b58e0a'::uuid, null, 'Cumin lamb stir-fry', 'seed', null, 'Claude', null, null,
    2, null, 25, 10, 15, '["Rinse the rice and cook it covered in 300 ml water, 12 min on low heat; rest 5 min.","Toss the lamb with the soy sauce, sherry, a pinch of salt, the baking soda and cornstarch; leave 10 min.","Mix the cumin, chili flakes and sugar.","Heat 2 tbsp oil in a wok over high heat and cook the lamb in two batches: spread it out, leave 30 s, then toss 1 min until golden. Set aside.","Add the rest of the oil, the ginger and garlic for 10 s, then the onion; stir-fry 2 min until just softening.","Return the lamb, sprinkle over the spice mix and toss 1 min until coated.","Toss in the coriander and sesame seeds and serve straight away over the rice."]'::jsonb,
    array['chinese', 'asian', 'stir-fry', 'quick', 'spicy', 'high protein']::text[], 'chinese', 958, 36.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Agneau sauté au cumin","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger l''agneau avec la sauce soja, le xérès, une pincée de sel, le bicarbonate et la fécule ; laisser reposer 10 min.","Mélanger le cumin, le piment et le sucre.","Chauffer 2 c. à soupe d''huile dans un wok à feu vif et cuire l''agneau en deux fois : l''étaler, laisser 30 s, puis remuer 1 min jusqu''à ce qu''il soit doré. Réserver.","Ajouter le reste de l''huile, le gingembre et l''ail 10 s, puis l''oignon ; faire sauter 2 min jusqu''à ce qu''il commence à s''attendrir.","Remettre l''agneau, saupoudrer du mélange d''épices et remuer 1 min pour bien enrober.","Ajouter la coriandre et les graines de sésame et servir aussitôt sur le riz."]},"it":{"title":"Agnello saltato al cumino","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare l''agnello con salsa di soia, sherry, un pizzico di sale, bicarbonato e amido; lasciare riposare 10 min.","Mescolare cumino, peperoncino e zucchero.","Scaldare 2 cucchiai d''olio in un wok a fuoco vivo e cuocere l''agnello in due volte: stenderlo, lasciarlo 30 s, poi saltarlo 1 min finché è dorato. Tenere da parte.","Aggiungere il resto dell''olio, zenzero e aglio per 10 s, poi la cipolla; saltare 2 min finché inizia ad ammorbidirsi.","Rimettere l''agnello, cospargere con il mix di spezie e saltare 1 min finché è ben condito.","Unire coriandolo e semi di sesamo e servire subito sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'beeb1367-a9d8-4d08-aac1-88fd80b58e0a')
  returning id
)
