-- Teriyaki tofu with broccoli and rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '52915883-18c7-40b1-9500-09f4efc12426'::uuid, null, 'Teriyaki tofu with broccoli and rice', 'seed', null, 'Claude', null, null,
    2, null, 30, 10, 20, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Pat the tofu very dry with a clean cloth and toss the cubes in 1 tbsp cornstarch with a pinch of salt.","Whisk the soy sauce, honey, vinegar, garlic, ginger, 80 ml water and the 2 tsp cornstarch into a smooth teriyaki sauce.","Fry the tofu in 1.5 tbsp oil in a large non-stick pan over medium-high heat, turning, 10-12 min until golden on all sides. Lift it out.","Add the rest of the oil and the broccoli with 2 tbsp water and stir-fry 4-5 min until bright green and crisp-tender.","Lower the heat, pour in the sauce and stir about 30 s until it bubbles and thickens, then return the tofu and toss to glaze.","Serve over the rice, scattered with sesame seeds and spring onion."]'::jsonb,
    array['japanese', 'asian', 'bowl', 'stir-fry', 'vegetarian', 'high protein']::text[], 'japanese', 865, 43.7,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tofu teriyaki, brocoli et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Bien sécher le tofu dans un torchon propre et enrober les cubes de 1 c. à soupe de fécule et d''une pincée de sel.","Fouetter la sauce soja, le miel, le vinaigre, l''ail, le gingembre, 80 ml d''eau et les 2 c. à café de fécule pour obtenir une sauce teriyaki lisse.","Faire dorer le tofu dans 1,5 c. à soupe d''huile dans une grande poêle antiadhésive à feu moyen-vif, en le retournant, 10 à 12 min. Le réserver.","Ajouter le reste de l''huile, le brocoli et 2 c. à soupe d''eau, et faire sauter 4 à 5 min jusqu''à ce qu''il soit vert vif et encore croquant.","Baisser le feu, verser la sauce et remuer environ 30 s jusqu''à ce qu''elle bouillonne et épaississe, puis remettre le tofu et mélanger pour le laquer.","Servir sur le riz, parsemé de sésame et d''oignon nouveau."]},"it":{"title":"Tofu teriyaki con broccoli e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Asciugare bene il tofu con un canovaccio pulito e passare i cubetti in 1 cucchiaio di amido con un pizzico di sale.","Sbattere la salsa di soia, il miele, l''aceto, l''aglio, lo zenzero, 80 ml d''acqua e i 2 cucchiaini di amido fino a ottenere una salsa teriyaki liscia.","Rosolare il tofu in 1,5 cucchiai d''olio in una padella antiaderente a fuoco medio-alto, girandolo, per 10-12 min finché è dorato su tutti i lati. Toglierlo.","Aggiungere l''olio rimasto, i broccoli e 2 cucchiai d''acqua e saltare 4-5 min finché sono verde brillante e ancora croccanti.","Abbassare il fuoco, versare la salsa e mescolare circa 30 s finché bolle e si addensa, poi rimettere il tofu e mescolare per glassarlo.","Servire sul riso, cosparso di sesamo e cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '52915883-18c7-40b1-9500-09f4efc12426')
  returning id
)
