-- Tofu and edamame sushi rice salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '3d4d6f57-5e42-4208-af77-afff5162cee1'::uuid, null, 'Tofu and edamame sushi rice salad', 'seed', null, 'Claude', null, null,
    2, null, 55, 20, 20, '["Rinse the rice until the water runs clear, simmer it covered in 180 ml water for 12 min and rest 10 min off the heat.","Dissolve 2 tbsp vinegar, the sugar and 0.5 tsp salt, fold into the rice, spread it out on a plate and leave to cool 15 min.","Cook the edamame 3 min in a frying pan with a splash of water until hot, then drain and cool them.","Pat the tofu dry and fry it in the oil in the same pan over medium-high heat, 8 min, until golden; add 1 tbsp soy sauce and toss until it is absorbed.","Whisk the remaining soy sauce and vinegar with the sesame oil into a dressing.","Divide the rice between two bowls and top with the tofu, edamame, cucumber, carrot and avocado.","Drizzle with the dressing and finish with pickled ginger, sesame seeds and spring onion."]'::jsonb,
    array['japanese', 'asian', 'salad', 'bowl', 'vegetarian', 'make ahead']::text[], 'japanese', 815, 38.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Salade de riz à sushi, tofu et edamame","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, le cuire à couvert dans 180 ml d''eau à feu doux 12 min et le laisser reposer 10 min hors du feu.","Dissoudre 2 c. à soupe de vinaigre, le sucre et ½ c. à café de sel, les incorporer au riz, l''étaler sur une assiette et laisser refroidir 15 min.","Cuire les edamame 3 min dans une poêle avec un peu d''eau, puis les égoutter et les laisser refroidir.","Sécher le tofu et le faire dorer dans l''huile dans la même poêle à feu moyen-vif, 8 min ; ajouter 1 c. à soupe de sauce soja et mélanger jusqu''à absorption.","Fouetter le reste de sauce soja et de vinaigre avec l''huile de sésame pour la sauce.","Répartir le riz dans deux bols et garnir de tofu, d''edamame, de concombre, de carotte et d''avocat.","Arroser de sauce et finir avec le gingembre mariné, le sésame et l''oignon nouveau."]},"it":{"title":"Insalata di riso da sushi con tofu ed edamame","steps":["Sciacquare il riso finché l''acqua è limpida, cuocerlo coperto in 180 ml d''acqua a fuoco basso per 12 min e lasciarlo riposare 10 min fuori dal fuoco.","Sciogliere 2 cucchiai di aceto, lo zucchero e mezzo cucchiaino di sale, incorporarli al riso, stenderlo su un piatto e lasciarlo raffreddare 15 min.","Cuocere gli edamame 3 min in padella con un goccio d''acqua, poi scolarli e lasciarli raffreddare.","Asciugare il tofu e rosolarlo nell''olio nella stessa padella a fuoco medio-alto, 8 min, finché è dorato; aggiungere 1 cucchiaio di salsa di soia e mescolare finché si assorbe.","Sbattere la salsa di soia e l''aceto rimasti con l''olio di sesamo per il condimento.","Dividere il riso in due ciotole e completare con tofu, edamame, cetriolo, carota e avocado.","Condire con la salsa e finire con zenzero marinato, sesamo e cipollotto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '3d4d6f57-5e42-4208-af77-afff5162cee1')
  returning id
)
