-- Saba shioyaki
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '96bd3c95-432e-4410-b43d-d745112aa97b'::uuid, null, 'Saba shioyaki', 'seed', null, 'Claude', null, null,
    2, null, 23, 5, 18, '["Rinse the rice and simmer it covered in 300 ml water for 12 min; rest 5 min off the heat.","Salt the mackerel generously on both sides and leave it 10 min while the rice cooks; then pat off the moisture that comes out.","Toss the cucumber with a pinch of salt, wait 5 min, squeeze it and dress with the vinegar and sugar.","Line a frying pan with foil, brush it with the oil and heat over medium heat.","Cook the mackerel skin side down 4-5 min until crisp and browned, then turn and cook 3-4 min more until opaque through.","Serve the fish with the rice, the cucumber salad sprinkled with sesame, lemon wedges and grated radish with a drop of soy sauce."]'::jsonb,
    array['japanese', 'asian', 'quick', 'grill', 'healthy', 'high protein']::text[], 'japanese', 672, 36.5,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saba shioyaki (maquereau grillé au sel)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Saler généreusement le maquereau des deux côtés et le laisser 10 min pendant la cuisson du riz ; puis éponger l''humidité qui en sort.","Mélanger le concombre avec une pincée de sel, attendre 5 min, le presser puis l''assaisonner avec le vinaigre et le sucre.","Tapisser une poêle de papier aluminium, le badigeonner d''huile et chauffer à feu moyen.","Cuire le maquereau côté peau 4 à 5 min jusqu''à ce qu''elle soit croustillante et dorée, puis le retourner et cuire encore 3 à 4 min jusqu''à ce qu''il soit opaque à cœur.","Servir le poisson avec le riz, la salade de concombre parsemée de sésame, les quartiers de citron et le radis râpé arrosé d''une goutte de sauce soja."]},"it":{"title":"Saba shioyaki (sgombro alla griglia con sale)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Salare abbondantemente lo sgombro su entrambi i lati e lasciarlo 10 min mentre cuoce il riso; poi tamponare l''umidità che rilascia.","Mescolare il cetriolo con un pizzico di sale, attendere 5 min, strizzarlo e condirlo con l''aceto e lo zucchero.","Foderare una padella con carta stagnola, spennellarla d''olio e scaldarla a fuoco medio.","Cuocere lo sgombro dal lato della pelle 4-5 min finché è croccante e dorata, poi girarlo e cuocere altri 3-4 min finché è opaco all''interno.","Servire il pesce con il riso, l''insalata di cetriolo cosparsa di sesamo, spicchi di limone e il ravanello grattugiato con una goccia di salsa di soia."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '96bd3c95-432e-4410-b43d-d745112aa97b')
  returning id
)
