-- Kimchi fried rice with tuna, mushrooms and egg
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e4fbec5b-2877-472e-b90f-9cce17e906d4'::uuid, null, 'Kimchi fried rice with tuna, mushrooms and egg', 'seed', null, 'Claude', null, null,
    2, null, 35, 10, 25, '["Cook the rice in 200 ml water, covered, on low heat for 15 min. Spread it on a plate to cool and dry a little (day-old rice is even better).","Heat 1 tbsp oil in a large frying pan over medium-high heat and fry the onion and mushrooms 4-5 min until the mushrooms are browned.","Add the kimchi, chili flakes and sugar and stir-fry 3 min until the kimchi softens and smells toasty.","Add the rice, kimchi juice and soy sauce and stir-fry 3-4 min, pressing the rice against the pan so it takes colour.","Fold in the tuna, half the spring onion and the sesame oil and heat through 1 min. Divide between two bowls.","Fry the eggs in the remaining oil 2-3 min until the whites are set but the yolks still runny.","Top each bowl with a fried egg, the rest of the spring onion and the sesame seeds."]'::jsonb,
    array['korean', 'asian', 'stir-fry', 'comfort', 'spicy']::text[], 'korean', 639, 35.8,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Riz sauté au kimchi, thon, champignons et œuf","steps":["Cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux. L''étaler sur une assiette pour qu''il refroidisse et sèche un peu (le riz de la veille est encore mieux).","Chauffer 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon et les champignons 4 à 5 min jusqu''à ce que les champignons soient dorés.","Ajouter le kimchi, le piment et le sucre et faire sauter 3 min jusqu''à ce que le kimchi ramollisse et sente le grillé.","Ajouter le riz, le jus de kimchi et la sauce soja et faire sauter 3 à 4 min en pressant le riz contre la poêle pour qu''il colore.","Incorporer le thon, la moitié de l''oignon nouveau et l''huile de sésame et réchauffer 1 min. Répartir dans deux bols.","Cuire les œufs au plat dans le reste de l''huile 2 à 3 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Garnir chaque bol d''un œuf au plat, du reste d''oignon nouveau et des graines de sésame."]},"it":{"title":"Riso saltato al kimchi con tonno, funghi e uovo","steps":["Cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso. Stenderlo su un piatto perché si raffreddi e si asciughi un po'' (il riso del giorno prima è ancora meglio).","Scaldare 1 cucchiaio d''olio in una padella larga a fuoco medio-alto e rosolare la cipolla e i funghi 4-5 min finché i funghi sono dorati.","Aggiungere il kimchi, il peperoncino e lo zucchero e saltare 3 min finché il kimchi si ammorbidisce e profuma di tostato.","Aggiungere il riso, il succo del kimchi e la salsa di soia e saltare 3-4 min, premendo il riso contro la padella perché prenda colore.","Incorporare il tonno, metà del cipollotto e l''olio di sesamo e scaldare 1 min. Dividere in due ciotole.","Friggere le uova nell''olio rimasto 2-3 min, finché l''albume è rappreso ma il tuorlo ancora morbido.","Completare ogni ciotola con un uovo, il resto del cipollotto e i semi di sesamo."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e4fbec5b-2877-472e-b90f-9cce17e906d4')
  returning id
)
