-- Jeyuk bokkeum
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b5aa2a92-5715-4729-9059-11df4a1ed144'::uuid, null, 'Jeyuk bokkeum', 'seed', null, 'Claude', null, null,
    2, null, 65, 15, 20, '["Stir the gochujang, chili flakes, soy sauce, vinegar, sugar, honey, sesame oil, garlic and ginger together until the sugar dissolves.","Toss the pork, onion and spring onion in the marinade, rubbing it in well. Cover and chill 30 min (up to a few hours).","Meanwhile cook the rice in 200 ml water, covered, on low heat for 15 min, then rest it off the heat.","Heat the oil in a large frying pan or wok over high heat until shimmering.","Stir-fry the pork in two batches, 3-4 min each, until cooked through and caramelised at the edges; don''t crowd the pan or it will steam.","Scatter with sesame seeds and serve with the rice and lettuce leaves for wrapping."]'::jsonb,
    array['korean', 'asian', 'stir-fry', 'spicy', 'high protein']::text[], 'korean', 984, 45.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Jeyuk bokkeum","steps":["Mélanger le gochujang, le piment, la sauce soja, le vinaigre, le sucre, le miel, l''huile de sésame, l''ail et le gingembre jusqu''à ce que le sucre soit dissous.","Mélanger le porc, l''oignon et l''oignon nouveau avec la marinade en massant bien. Couvrir et réserver 30 min au frais (jusqu''à quelques heures).","Pendant ce temps, cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux, puis le laisser reposer hors du feu.","Chauffer l''huile dans une grande poêle ou un wok à feu vif jusqu''à ce qu''elle frémisse.","Faire sauter le porc en deux fois, 3 à 4 min chaque fois, jusqu''à ce qu''il soit cuit et caramélisé sur les bords ; ne pas surcharger la poêle sinon il bout.","Parsemer de sésame et servir avec le riz et des feuilles de laitue pour faire des wraps."]},"it":{"title":"Jeyuk bokkeum","steps":["Mescolare il gochujang, il peperoncino, la salsa di soia, l''aceto, lo zucchero, il miele, l''olio di sesamo, l''aglio e lo zenzero finché lo zucchero si scioglie.","Condire il maiale, la cipolla e il cipollotto con la marinata, massaggiando bene. Coprire e lasciare in frigo 30 min (fino a qualche ora).","Nel frattempo cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Scaldare l''olio in una padella larga o nel wok a fuoco alto finché è ben caldo.","Saltare il maiale in due volte, 3-4 min ciascuna, finché è cotto e caramellato ai bordi; non riempire troppo la padella o il maiale lessa.","Cospargere di sesamo e servire con il riso e foglie di lattuga per avvolgere."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b5aa2a92-5715-4729-9059-11df4a1ed144')
  returning id
)
