-- Smoky prawn tacos with cabbage and avocado
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'e65fe071-853c-4a03-a5e5-5f8a90979328'::uuid, null, 'Smoky prawn tacos with cabbage and avocado', 'seed', null, 'Claude', null, null,
    2, null, 20, 15, 5, '["Toss the prawns with the smoked paprika, cumin, chili powder, oregano, garlic, half the oil and a pinch of salt.","Toss the cabbage with the juice of 1 lime and a pinch of salt just before assembling, so it stays crunchy.","Stir the yogurt with the hot sauce and a squeeze of lime.","Warm the tortillas in a dry frying pan, 20 seconds per side, and keep them wrapped in a tea towel.","Heat the remaining oil in the pan over high heat and cook the prawns 1-2 min per side until pink and lightly charred.","Fill the tortillas with cabbage, prawns and avocado, spoon over the smoky yogurt and finish with coriander and lime wedges."]'::jsonb,
    array['mexican', 'street food', 'quick', 'high protein']::text[], 'mexican', 830, 54.2,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Tacos de crevettes fumés, chou et avocat","steps":["Mélanger les crevettes avec le paprika fumé, le cumin, le piment en poudre, l''origan, l''ail, la moitié de l''huile et une pincée de sel.","Mélanger le chou avec le jus d''un citron vert et une pincée de sel juste avant de garnir, pour qu''il reste croquant.","Mélanger le yaourt avec la sauce piquante et un filet de citron vert.","Réchauffer les tortillas dans une poêle sèche, 20 secondes de chaque côté, et les garder enveloppées dans un torchon.","Chauffer le reste de l''huile dans la poêle à feu vif et cuire les crevettes 1 à 2 min de chaque côté, jusqu''à ce qu''elles soient roses et légèrement grillées.","Garnir les tortillas de chou, de crevettes et d''avocat, napper de yaourt fumé et finir avec la coriandre et des quartiers de citron vert."]},"it":{"title":"Tacos di gamberi affumicati con cavolo e avocado","steps":["Condire i gamberi con la paprika affumicata, il cumino, il peperoncino in polvere, l''origano, l''aglio, metà dell''olio e un pizzico di sale.","Condire il cavolo con il succo di un lime e un pizzico di sale appena prima di farcire, perché resti croccante.","Mescolare lo yogurt con la salsa piccante e un po'' di succo di lime.","Scaldare le tortillas in una padella asciutta, 20 secondi per lato, e tenerle avvolte in un canovaccio.","Scaldare l''olio rimasto nella padella a fuoco alto e cuocere i gamberi 1-2 min per lato finché sono rosa e leggermente abbrustoliti.","Farcire le tortillas con cavolo, gamberi e avocado, condire con lo yogurt affumicato e finire con coriandolo e spicchi di lime."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'e65fe071-853c-4a03-a5e5-5f8a90979328')
  returning id
)
