-- Picadillo with rice
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '8660ca5e-d5ae-4f8c-8013-fc19defba212'::uuid, null, 'Picadillo with rice', 'seed', null, 'Claude', null, null,
    2, null, 30, 10, 20, '["Rinse the rice, put it in a pan with 300 ml water and a pinch of salt, cover and simmer 12 min. Rest 5 min off the heat.","Meanwhile soften the onion and pepper in 1 tbsp oil over medium heat for 5 min. Add the garlic for 1 min.","Add the beef and break it up. Cook 5 min until it loses its pink colour.","Stir in the cumin, oregano and bay leaf, pour in the wine and let it bubble 1 min.","Add the passata and raisins and simmer uncovered for 10 min, stirring now and then, until thick.","Stir in the olives, capers and vinegar, and season with salt and pepper.","Serve the picadillo over the rice."]'::jsonb,
    array['cuban', 'comfort', 'high protein', 'budget']::text[], 'cuban', 847, 49.2,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Picadillo cubain et riz","steps":["Rincer le riz, le mettre dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min. Laisser reposer 5 min hors du feu.","Pendant ce temps, faire revenir l''oignon et le poivron dans 1 c. à soupe d''huile à feu moyen 5 min. Ajouter l''ail 1 min.","Ajouter le bœuf et l''émietter. Cuire 5 min jusqu''à ce qu''il ne soit plus rosé.","Ajouter le cumin, l''origan et le laurier, verser le vin et laisser bouillonner 1 min.","Ajouter le coulis de tomate et les raisins secs et laisser mijoter 10 min à découvert, en remuant de temps en temps, jusqu''à ce que ce soit épais.","Incorporer les olives, les câpres et le vinaigre, puis saler et poivrer.","Servir le picadillo sur le riz."]},"it":{"title":"Picadillo cubano con riso","steps":["Sciacquare il riso, metterlo in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min. Lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo, appassire la cipolla e il peperone in 1 cucchiaio d''olio a fuoco medio per 5 min. Aggiungere l''aglio per 1 min.","Aggiungere la carne e sgranarla. Cuocere 5 min finché non è più rosa.","Unire il cumino, l''origano e l''alloro, versare il vino e lasciarlo sfumare 1 min.","Aggiungere la passata e l''uvetta e cuocere scoperto 10 min, mescolando ogni tanto, finché si addensa.","Unire le olive, i capperi e l''aceto, e regolare di sale e pepe.","Servire il picadillo sul riso."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '8660ca5e-d5ae-4f8c-8013-fc19defba212')
  returning id
)
