-- Salmon fishcakes with peas and lemon yogurt
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'f9ed364b-8350-45b8-ac5b-aca582be6f94'::uuid, null, 'Salmon fishcakes with peas and lemon yogurt', 'seed', null, 'Claude', null, null,
    2, null, 65, 25, 25, '["Boil the potatoes in salted water for 12-15 min until tender. Drain, leave to steam dry 2 min, then mash roughly.","Meanwhile poach the salmon in a frying pan of barely simmering water for 6-8 min until just cooked. Drain and flake.","Mix the mash, salmon, lemon zest, spring onions, half the dill, salt and pepper. Shape into 4 cakes about 3 cm thick and chill 15 min.","Dust the cakes with flour, dip them in the egg, then coat them in breadcrumbs.","Wipe the frying pan, heat the oil over medium heat and fry the fishcakes 4 min per side until golden and hot through.","Cook the peas in boiling water for 3 min, drain and season.","Mix the yogurt with 1 tbsp lemon juice, the rest of the dill and a pinch of salt.","Serve the fishcakes with the peas, the lemon yogurt and lemon wedges."]'::jsonb,
    array['british', 'comfort', 'kid-friendly', 'high protein']::text[], 'british', 876, 51.8,
    false, 'en', 'medium', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Croquettes de saumon, petits pois et yaourt citronné","steps":["Cuire les pommes de terre 12 à 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres. Égoutter, laisser sécher 2 min, puis écraser grossièrement.","Pendant ce temps, pocher le saumon dans une poêle d''eau à peine frémissante 6 à 8 min, juste cuit. Égoutter et effeuiller.","Mélanger la purée, le saumon, le zeste de citron, les oignons nouveaux, la moitié de l''aneth, sel et poivre. Former 4 galettes d''environ 3 cm d''épaisseur et les réfrigérer 15 min.","Fariner les galettes, les tremper dans l''œuf, puis les enrober de chapelure.","Essuyer la poêle, chauffer l''huile à feu moyen et cuire les croquettes 4 min de chaque côté, jusqu''à ce qu''elles soient dorées et chaudes à cœur.","Cuire les petits pois 3 min dans de l''eau bouillante, égoutter et assaisonner.","Mélanger le yaourt avec 1 c. à soupe de jus de citron, le reste de l''aneth et une pincée de sel.","Servir les croquettes avec les petits pois, le yaourt citronné et des quartiers de citron."]},"it":{"title":"Polpette di salmone con piselli e yogurt al limone","steps":["Lessare le patate in acqua salata per 12-15 min finché sono tenere. Scolarle, lasciarle asciugare 2 min e schiacciarle grossolanamente.","Nel frattempo cuocere il salmone in una padella d''acqua appena sobbollente per 6-8 min, finché è appena cotto. Scolarlo e sfaldarlo.","Mescolare le patate, il salmone, la scorza di limone, i cipollotti, metà dell''aneto, sale e pepe. Formare 4 tortini spessi circa 3 cm e farli riposare in frigo 15 min.","Infarinare i tortini, passarli nell''uovo e poi nel pangrattato.","Pulire la padella, scaldare l''olio a fuoco medio e cuocere i tortini 4 min per lato, finché sono dorati e caldi all''interno.","Cuocere i piselli in acqua bollente per 3 min, scolarli e condirli.","Mescolare lo yogurt con 1 cucchiaio di succo di limone, il resto dell''aneto e un pizzico di sale.","Servire i tortini con i piselli, lo yogurt al limone e spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'f9ed364b-8350-45b8-ac5b-aca582be6f94')
  returning id
)
