-- Sausage and root vegetable tray roast
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select 'b76ef299-3036-48ea-94ff-e8d5f575d475'::uuid, null, 'Sausage and root vegetable tray roast', 'seed', null, 'Claude', null, null,
    2, null, 65, 15, 50, '["Heat the oven to 200 °C (180 °C fan).","Toss the parsnips, carrots, potatoes and onion with the oil, thyme, salt and pepper on a large baking tray in one layer.","Roast for 20 min.","Turn the vegetables, nestle the sausages among them and roast 20 min more.","Mix the honey and mustard, toss it over the sausages and parsnips and roast a final 10 min until sticky and the sausages are cooked through."]'::jsonb,
    array['british', 'oven', 'comfort', 'winter', 'one-pot']::text[], 'british', 876, 29.4,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Saucisses et légumes racines rôtis à la plaque","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger les panais, les carottes, les pommes de terre et l''oignon avec l''huile, le thym, le sel et le poivre sur une grande plaque, en une seule couche.","Rôtir 20 min.","Retourner les légumes, glisser les saucisses entre eux et rôtir encore 20 min.","Mélanger le miel et la moutarde, en enrober les saucisses et les panais et rôtir encore 10 min, jusqu''à ce que ce soit caramélisé et que les saucisses soient cuites à cœur."]},"it":{"title":"Salsicce e ortaggi a radice in teglia","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Condire pastinache, carote, patate e cipolla con l''olio, il timo, sale e pepe su una grande teglia, in un solo strato.","Arrostire per 20 min.","Girare le verdure, sistemare le salsicce in mezzo e arrostire altri 20 min.","Mescolare il miele e la senape, versarli sulle salsicce e sulle pastinache e arrostire altri 10 min, finché sono glassate e le salsicce cotte all''interno."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = 'b76ef299-3036-48ea-94ff-e8d5f575d475')
  returning id
)
