-- Pan-fried hake with pea and mint mash
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '0932be9e-079a-4987-8170-c331087fb0a7'::uuid, null, 'Pan-fried hake with pea and mint mash', 'seed', null, 'Claude', null, null,
    2, null, 30, 10, 20, '["Boil the potatoes in salted water for 15 min until tender, adding the peas for the last 3 min.","Drain, then mash with the butter, warm milk, mint, salt and pepper, leaving some texture. Keep warm.","Pat the hake dry, score the skin lightly and season both sides.","Heat the oil in a frying pan over medium-high heat. Fry the hake skin side down for 4 min until crisp, then turn and cook 2-3 min until just opaque in the centre.","Serve the fish on the mash with a squeeze of lemon."]'::jsonb,
    array['british', 'light', 'high protein']::text[], 'british', 553, 39.4,
    false, 'en', 'easy', '{"pots":2,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Merlu poêlé, écrasé de petits pois à la menthe","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser avec le beurre, le lait chaud, la menthe, sel et poivre, en gardant un peu de texture. Garder au chaud.","Éponger le merlu, inciser légèrement la peau et assaisonner des deux côtés.","Chauffer l''huile dans une poêle à feu moyen-vif. Cuire le merlu côté peau 4 min, jusqu''à ce qu''elle soit croustillante, puis le retourner et cuire 2 à 3 min, juste nacré à cœur.","Servir le poisson sur l''écrasé avec un filet de citron."]},"it":{"title":"Nasello in padella con purè di piselli e menta","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare con il burro, il latte caldo, la menta, sale e pepe, lasciando un po'' di consistenza. Tenere in caldo.","Asciugare il nasello, incidere leggermente la pelle e condire da entrambi i lati.","Scaldare l''olio in padella a fuoco medio-alto. Cuocere il nasello dalla parte della pelle per 4 min finché è croccante, poi girarlo e cuocere 2-3 min, finché è appena opaco al centro.","Servire il pesce sul purè con una spruzzata di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '0932be9e-079a-4987-8170-c331087fb0a7')
  returning id
)
