-- Tuna and sweetcorn jacket potatoes
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '052505d0-dfea-4d39-abe9-1eb80426e276'::uuid, null, 'Tuna and sweetcorn jacket potatoes', 'seed', null, 'Claude', null, null,
    2, null, 25, 7, 18, '["Prick the potatoes all over, rub with a little oil and salt and microwave on high for 6 min. Turn and microwave 5-7 min more until soft to a knife.","Meanwhile heat the oven grill to high and mix the tuna, sweetcorn, yogurt, mayonnaise, spring onions, lemon juice and pepper.","Put the potatoes under the grill for 5 min to crisp the skins.","Split them, fluff the insides with a fork and pile in the tuna mix.","Top with cheddar and grill 2 min until melted. Serve with salad leaves."]'::jsonb,
    array['british', 'quick', 'comfort', 'budget', 'high protein']::text[], 'british', 588, 43.8,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Pommes de terre en robe des champs au thon et maïs","steps":["Piquer les pommes de terre de partout, les frotter d''un peu d''huile et de sel et les cuire au micro-ondes à puissance maximale 6 min. Les retourner et cuire encore 5 à 7 min, jusqu''à ce qu''un couteau s''enfonce facilement.","Pendant ce temps, allumer le gril du four à puissance maximale et mélanger le thon, le maïs, le yaourt, la mayonnaise, les oignons nouveaux, le jus de citron et du poivre.","Passer les pommes de terre 5 min sous le gril pour rendre la peau croustillante.","Les fendre, aérer la chair à la fourchette et garnir du mélange au thon.","Parsemer de cheddar et passer 2 min sous le gril pour le faire fondre. Servir avec de la salade."]},"it":{"title":"Patate al cartoccio con tonno e mais","steps":["Bucherellare le patate, strofinarle con un filo d''olio e sale e cuocerle al microonde alla massima potenza per 6 min. Girarle e cuocere altri 5-7 min, finché un coltello entra facilmente.","Nel frattempo accendere il grill del forno al massimo e mescolare il tonno, il mais, lo yogurt, la maionese, i cipollotti, il succo di limone e il pepe.","Mettere le patate sotto il grill per 5 min per rendere la buccia croccante.","Aprirle, smuovere la polpa con una forchetta e farcirle con il composto di tonno.","Cospargere di cheddar e passare 2 min sotto il grill finché fonde. Servire con insalata."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '052505d0-dfea-4d39-abe9-1eb80426e276')
  returning id
)
