-- Smoked mackerel, beetroot and potato salad
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '18c1a899-e68c-4b75-8eb3-38adbd2e2aae'::uuid, null, 'Smoked mackerel, beetroot and potato salad', 'seed', null, 'Claude', null, null,
    2, null, 30, 15, 15, '["Boil the potatoes in salted water for 15 min until tender, adding the eggs for the last 8 min. Cool the eggs in cold water, then peel and halve them.","Mix the crème fraîche, horseradish, mustard, lemon juice, half the dill, salt and pepper.","Toss the sliced onion with the vinegar and a pinch of salt and leave 10 min.","Toss the warm potatoes with the onion, its vinegar and half the dressing.","Arrange the potatoes, beetroot, mackerel and rocket on plates, top with the eggs and the rest of the dressing, and scatter with the remaining dill."]'::jsonb,
    array['danish', 'salad', 'light', 'high protein']::text[], 'danish', 717, 34.5,
    false, 'en', 'easy', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Salade de maquereau fumé, betterave et pommes de terre","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les œufs les 8 dernières minutes. Refroidir les œufs dans de l''eau froide, puis les écaler et les couper en deux.","Mélanger la crème fraîche, le raifort, la moutarde, le jus de citron, la moitié de l''aneth, sel et poivre.","Mélanger l''oignon émincé avec le vinaigre et une pincée de sel et laisser 10 min.","Mélanger les pommes de terre tièdes avec l''oignon, son vinaigre et la moitié de la sauce.","Répartir les pommes de terre, la betterave, le maquereau et la roquette dans les assiettes, ajouter les œufs et le reste de la sauce, et parsemer du reste d''aneth."]},"it":{"title":"Insalata di sgombro affumicato, barbabietola e patate","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo le uova negli ultimi 8 min. Raffreddare le uova in acqua fredda, poi sgusciarle e tagliarle a metà.","Mescolare la crème fraîche, il rafano, la senape, il succo di limone, metà dell''aneto, sale e pepe.","Condire la cipolla affettata con l''aceto e un pizzico di sale e lasciarla 10 min.","Condire le patate tiepide con la cipolla, il suo aceto e metà della salsa.","Disporre nei piatti le patate, la barbabietola, lo sgombro e la rucola, aggiungere le uova e il resto della salsa e completare con l''aneto rimasto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '18c1a899-e68c-4b75-8eb3-38adbd2e2aae')
  returning id
)
