-- Baked trout with dill potatoes and pressgurka
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '54c25855-82be-4d48-9e67-689d4b21866c'::uuid, null, 'Baked trout with dill potatoes and pressgurka', 'seed', null, 'Claude', null, null,
    2, null, 40, 15, 25, '["Heat the oven to 200°C. Put the potatoes in a pot of cold salted water with the dill stalks, bring to the boil and simmer 15-20 min until tender.","For the pressgurka, stir the vinegar, sugar, 2 tbsp water and a pinch of salt until dissolved, add the cucumber and a little dill, and leave to steep while you cook.","Lay the trout skin side down in an oiled baking dish, season, dot with half the butter and add a few lemon slices.","Bake 10-12 min until the flesh is opaque and flakes easily.","Mix the crème fraîche with the mustard, a squeeze of lemon, half the remaining dill, salt and pepper.","Drain the potatoes and toss them with the rest of the butter and dill.","Serve the trout with the dill potatoes, the drained cucumber and the dill sauce."]'::jsonb,
    array['swedish', 'oven', 'light', 'healthy', 'summer']::text[], 'swedish', 680, 39.2,
    false, 'en', 'easy', '{"pots":2,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Truite au four, pommes de terre à l''aneth et concombre","steps":["Préchauffer le four à 200 °C. Mettre les pommes de terre dans une casserole d''eau froide salée avec les tiges d''aneth, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Pour le pressgurka, mélanger le vinaigre, le sucre, 2 c. à soupe d''eau et une pincée de sel jusqu''à dissolution, ajouter le concombre et un peu d''aneth et laisser mariner pendant la cuisson.","Poser la truite côté peau dans un plat huilé, saler, poivrer, parsemer de la moitié du beurre et ajouter quelques rondelles de citron.","Enfourner 10 à 12 min, jusqu''à ce que la chair soit opaque et se détache facilement.","Mélanger la crème fraîche avec la moutarde, un filet de citron, la moitié de l''aneth restant, du sel et du poivre.","Égoutter les pommes de terre et les enrober du reste du beurre et de l''aneth.","Servir la truite avec les pommes de terre à l''aneth, le concombre égoutté et la sauce à l''aneth."]},"it":{"title":"Trota al forno con patate all''aneto e cetrioli","steps":["Scaldare il forno a 200 °C. Mettere le patate in una pentola di acqua fredda salata con i gambi di aneto, portare a bollore e cuocere 15-20 min finché sono tenere.","Per il pressgurka, mescolare l''aceto, lo zucchero, 2 cucchiai d''acqua e un pizzico di sale finché si sciolgono, aggiungere il cetriolo e un po'' di aneto e lasciare marinare durante la cottura.","Disporre la trota con la pelle verso il basso in una pirofila unta, salare, pepare, distribuire metà del burro e qualche fetta di limone.","Infornare 10-12 min, finché la polpa è opaca e si sfalda facilmente.","Mescolare la crème fraîche con la senape, una spruzzata di limone, metà dell''aneto rimasto, sale e pepe.","Scolare le patate e condirle con il resto del burro e dell''aneto.","Servire la trota con le patate all''aneto, il cetriolo scolato e la salsa all''aneto."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '54c25855-82be-4d48-9e67-689d4b21866c')
  returning id
)
