-- Gulyás
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '5e6779a0-957a-4af7-9775-d03c9b70b678'::uuid, null, 'Gulyás', 'seed', null, 'Claude', null, null,
    2, null, 125, 20, 105, '["Melt the butter in a heavy pot over medium heat and cook the onions 8-10 min until golden.","Add the beef and brown it on all sides for 8 min.","Add the bell pepper, tomato and garlic and cook 5 min.","Take the pot off the heat and stir in the paprika and caraway so the paprika does not scorch.","Pour in the stock, add the bay leaf and salt, bring to the boil, then cover and simmer gently for 1 h.","Add the carrots and potatoes and simmer, covered, another 30-40 min until the beef is very tender and the potatoes are cooked.","Remove the bay leaf, season and serve in deep bowls with a spoonful of crème fraîche and bread."]'::jsonb,
    array['hungarian', 'soup', 'comfort', 'winter', 'one-pot']::text[], 'hungarian', 886, 55.7,
    false, 'en', 'medium', '{"pots":1,"oven":false,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Goulash hongrois (gulyás)","steps":["Faire fondre le beurre dans une cocotte à fond épais à feu moyen et cuire les oignons 8 à 10 min jusqu''à ce qu''ils soient dorés.","Ajouter le bœuf et le faire dorer sur toutes les faces 8 min.","Ajouter le poivron, la tomate et l''ail et cuire 5 min.","Retirer la cocotte du feu et incorporer le paprika et le carvi pour que le paprika ne brûle pas.","Verser le bouillon, ajouter le laurier et du sel, porter à ébullition, puis couvrir et laisser mijoter doucement 1 h.","Ajouter les carottes et les pommes de terre et laisser mijoter à couvert encore 30 à 40 min, jusqu''à ce que le bœuf soit très tendre et les pommes de terre cuites.","Retirer le laurier, rectifier l''assaisonnement et servir dans des assiettes creuses avec une cuillerée de crème fraîche et du pain."]},"it":{"title":"Gulasch ungherese (gulyás)","steps":["Sciogliere il burro in una pentola dal fondo spesso a fuoco medio e cuocere le cipolle 8-10 min finché sono dorate.","Aggiungere il manzo e rosolarlo su tutti i lati per 8 min.","Aggiungere il peperone, il pomodoro e l''aglio e cuocere 5 min.","Togliere la pentola dal fuoco e incorporare la paprika e il cumino dei prati, così la paprika non brucia.","Versare il brodo, aggiungere l''alloro e il sale, portare a bollore, poi coprire e cuocere a fuoco dolce per 1 h.","Aggiungere le carote e le patate e cuocere coperto altri 30-40 min, finché il manzo è molto tenero e le patate sono cotte.","Togliere l''alloro, regolare di sale e servire in piatti fondi con una cucchiaiata di crème fraîche e pane."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '5e6779a0-957a-4af7-9775-d03c9b70b678')
  returning id
)
