-- Lemon salmon, potato and green bean traybake
with r as (
  insert into public.recipes (id, household_id, title, source_type, source_url, source_name, image_path, image_source_url,
    servings, original_servings, total_min, prep_min, cook_min, steps, tags, cuisine, kcal_per_serving, protein_g_per_serving,
    macros_estimated, language, difficulty, equipment, ai_generated_recipe, translations)
  select '86344908-27c8-4c77-90f7-299d2972fb69'::uuid, null, 'Lemon salmon, potato and green bean traybake', 'seed', null, 'Claude', null, null,
    2, null, 45, 10, 35, '["Heat the oven to 200°C. Toss the potatoes with 1 tbsp oil, salt and pepper on a large baking tray and roast 20 min.","Mix the rest of the oil with the garlic, the zest of the lemon and half its juice, half the dill, salt and pepper.","Push the potatoes to the sides, add the green beans tossed in a little of the lemon oil, and set the salmon in the middle, skin side down.","Spoon the rest of the lemon oil over the salmon and add a few lemon slices.","Roast 12-15 min until the salmon flakes easily and the beans are tender but still bright.","Scatter with the rest of the dill and serve with lemon wedges."]'::jsonb,
    array['british', 'oven', 'healthy', 'light', 'high protein']::text[], 'british', 652, 35.3,
    false, 'en', 'easy', '{"pots":1,"oven":true,"special":[]}'::jsonb, true,
    '{"fr":{"title":"Plaque de saumon au citron, pommes de terre et haricots verts","steps":["Préchauffer le four à 200 °C. Mélanger les pommes de terre avec 1 c. à soupe d''huile, du sel et du poivre sur une grande plaque et rôtir 20 min.","Mélanger le reste de l''huile avec l''ail, le zeste du citron et la moitié de son jus, la moitié de l''aneth, du sel et du poivre.","Pousser les pommes de terre sur les côtés, ajouter les haricots verts enrobés d''un peu d''huile citronnée et poser le saumon au centre, côté peau dessous.","Napper le saumon du reste de l''huile citronnée et ajouter quelques rondelles de citron.","Rôtir 12 à 15 min, jusqu''à ce que le saumon s''effeuille facilement et que les haricots soient tendres mais encore bien verts.","Parsemer du reste de l''aneth et servir avec des quartiers de citron."]},"it":{"title":"Salmone al limone in teglia con patate e fagiolini","steps":["Scaldare il forno a 200 °C. Condire le patate con 1 cucchiaio d''olio, sale e pepe su una teglia grande e arrostirle 20 min.","Mescolare il resto dell''olio con l''aglio, la scorza del limone e metà del suo succo, metà dell''aneto, sale e pepe.","Spostare le patate ai lati, aggiungere i fagiolini conditi con un po'' dell''olio al limone e mettere il salmone al centro, con la pelle verso il basso.","Versare il resto dell''olio al limone sul salmone e aggiungere qualche fetta di limone.","Arrostire 12-15 min, finché il salmone si sfalda facilmente e i fagiolini sono teneri ma ancora verdi brillanti.","Cospargere con il resto dell''aneto e servire con spicchi di limone."]}}'::jsonb
  where not exists (select 1 from public.recipes x where x.id = '86344908-27c8-4c77-90f7-299d2972fb69')
  returning id
)
