  ('9169be37-a6b2-4696-85c1-953096525ffa'::uuid, '57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, 10, 'chili flakes', 'spices'::public.aisle, true, true),
  ('e8740860-14ae-427c-9db6-d15b85ca9583'::uuid, '57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, 11, 'salt', 'spices'::public.aisle, true, false),
  ('75760c9e-b43e-464f-ad3c-e5a697919f2b'::uuid, '57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, 12, 'black pepper', 'spices'::public.aisle, true, false)
) as v(id, recipe_id, position, name, aisle, is_staple, optional)
where (i.id = v.id or (i.position = v.position and exists (select 1 from public.recipes x where x.id = i.recipe_id and x.copied_from = v.recipe_id))) and i.optional is distinct from v.optional;

-- Translations for seed recipes and copies of them.
update public.recipes x set translations = v.translations
from (values
  ('d8e4ac12-403d-4d06-97cf-022682d08894'::uuid, '{"en":{"title":"Herb roast turkey","steps":["Tie the turkey breast with kitchen string.","Rub it with rosemary, sage, oregano, curry powder, salt and pepper.","Heat the oil in a pan with the carrot, onion, celery and garlic cut into large chunks, and brown the meat on all sides.","Deglaze with the white wine.","Cook covered over low heat for about 45 minutes, or in the oven at 180 °C covered with foil for about an hour.","Let the meat rest before slicing it.","Blend the cooked vegetables with a little of the pan juices, heat the sauce and serve it with the roast."]},"fr":{"title":"Rôti de dinde aux herbes","steps":["Ficeler le blanc de dinde avec de la ficelle de cuisine.","Le masser avec le romarin, la sauge, l''origan, le curry, le sel et le poivre.","Faire chauffer l''huile dans une sauteuse avec la carotte, l''oignon, le céleri et l''ail coupés en gros morceaux, puis faire revenir la viande sur toutes ses faces.","Déglacer au vin blanc.","Cuire à couvert à feu doux pendant environ 45 minutes, ou au four à 180 °C, couvert de papier aluminium, pendant environ une heure.","Laisser reposer la viande avant de la couper en tranches.","Mixer les légumes de cuisson avec un peu de jus de cuisson, réchauffer la sauce et la servir avec le rôti."]}}'::jsonb),
  ('7cb87b97-df20-4ea6-8837-a97aa96c651f'::uuid, '{"en":{"title":"Ligurian rabbit with Taggiasca olives","steps":["Cut the rabbit into pieces, remove the fat, liver and kidneys, rinse it and pat it dry.","Finely chop the onion, and chop the garlic, germ removed, together with the rosemary needles.","Heat the oil with the chopped aromatics and the rabbit, and brown the meat on all sides over low heat without letting the aromatics burn.","Deglaze with the red wine, raising the heat until the alcohol has evaporated.","Add the bay leaf, thyme, olives and a ladle of hot stock, cover and cook gently, adding more stock only if needed.","After about an hour, when the meat comes away from the bone, uncover and reduce any excess sauce."]},"fr":{"title":"Lapin à la ligure aux olives taggiasche","steps":["Découper le lapin en morceaux, retirer le gras, le foie et les rognons, le rincer et le sécher.","Hacher finement l''oignon, et hacher l''ail dégermé avec les aiguilles de romarin.","Faire chauffer l''huile avec le hachis et le lapin, et faire revenir la viande sur toutes ses faces à feu doux sans brûler les aromates.","Déglacer au vin rouge en augmentant le feu jusqu''à ce que l''alcool soit évaporé.","Ajouter le laurier, le thym, les olives et une louche de bouillon chaud, couvrir et laisser mijoter doucement, en ajoutant du bouillon seulement si nécessaire.","Au bout d''environ une heure, lorsque la viande se détache de l''os, découvrir et faire réduire l''excédent de sauce."]}}'::jsonb),
  ('17c37e4b-5dc1-4114-8e36-27664bd290ca'::uuid, '{"en":{"title":"Taranto-style mussels","steps":["Soak the mussels in salted water for at least an hour, then scrub the shells and pull off the beards.","In a frying pan, gently fry one crushed garlic clove in half the oil without letting it brown.","Add the mussels and a sprig of parsley, deglaze with the wine and cover until they open.","Strain the cooking liquid through a fine sieve and set the mussels aside.","In a clean frying pan, heat the remaining oil with the sliced garlic and the crumbled chilli.","Add the peeled tomatoes, crushing them with a fork, add the mussel liquid and reduce over low heat for about 10 minutes.","Return the mussels to the sauce with the chopped parsley, leave to take on flavour for a few minutes and serve with toasted bread."]},"fr":{"title":"Moules à la mode de Tarente","steps":["Laisser tremper les moules dans de l''eau salée pendant au moins une heure, puis brosser les coquilles et retirer le byssus.","Dans une poêle, faire revenir une gousse d''ail écrasée dans la moitié de l''huile, sans la laisser colorer.","Ajouter les moules et un brin de persil, déglacer au vin et couvrir jusqu''à ce qu''elles s''ouvrent.","Filtrer le jus de cuisson à travers une passoire fine et réserver les moules.","Dans une poêle propre, faire chauffer le reste de l''huile avec l''ail émincé et le piment émietté.","Ajouter les tomates pelées en les écrasant à la fourchette, ajouter le jus des moules et laisser réduire à feu doux pendant environ 10 minutes.","Remettre les moules dans la sauce avec le persil haché, laisser s''imprégner quelques minutes et servir avec du pain grillé."]}}'::jsonb),
  ('bacd2ed3-0463-40f3-bb43-f496642a30b8'::uuid, '{"en":{"title":"Baked courgette and ricotta frittata","steps":["Preheat the oven to 180 °C (conventional, no fan).","Wash and dry the courgettes, trim the ends and cut them into thin rounds.","Beat the eggs in a bowl, stir in the ricotta and parmesan, season with salt and pepper and add the courgettes.","Line a small cake tin with baking paper (lightly greased or dampened), pour in the mixture and level it.","Bake for 30 minutes on the conventional setting, then another 5 minutes with the fan until the top is golden.","Remove from the oven, cut into slices and serve warm or cold."]},"fr":{"title":"Frittata courgettes et ricotta au four","steps":["Préchauffer le four à 180 °C en chaleur statique.","Laver et sécher les courgettes, les équeuter et les couper en fines rondelles.","Battre les œufs dans un saladier, incorporer la ricotta et le parmesan, saler, poivrer et ajouter les courgettes.","Chemiser un petit moule à manqué de papier cuisson (légèrement huilé ou humidifié), verser la préparation et la lisser.","Cuire 30 minutes en chaleur statique, puis encore 5 minutes en chaleur tournante jusqu''à ce que le dessus soit doré.","Sortir du four, couper en parts et servir tiède ou froide."]}}'::jsonb),
  ('27b821b2-edb6-4621-9429-c3073510739c'::uuid, '{"en":{"title":"Farro salad with tuna and chickpeas","steps":["Boil the farro in plenty of salted water for the time given on the packet, drain and leave to cool.","Drain and rinse the chickpeas; drain the tuna well.","Add the chickpeas and flaked tuna to the farro, dress with oil and a pinch of salt and stir.","Quarter the cherry tomatoes; wash and dry the rocket.","Add the cherry tomatoes and rocket to the farro, stir, adjust the seasoning and serve straight away or keep in the fridge until needed."]},"fr":{"title":"Salade d''épeautre au thon et aux pois chiches","steps":["Cuire l''épeautre dans un grand volume d''eau salée selon le temps indiqué sur l''emballage, l''égoutter et le laisser refroidir.","Égoutter et rincer les pois chiches ; bien égoutter le thon.","Ajouter à l''épeautre les pois chiches et le thon émietté, assaisonner avec l''huile et une pincée de sel et mélanger.","Couper les tomates cerises en quatre, laver et sécher la roquette.","Ajouter les tomates cerises et la roquette à l''épeautre, mélanger, rectifier l''assaisonnement et servir aussitôt ou conserver au réfrigérateur jusqu''au moment de servir."]}}'::jsonb),
  ('78ed85bf-8d00-444e-b619-63a462d21934'::uuid, '{"en":{"title":"Baked chicken rolls","steps":["Lay the chicken slices out on a chopping board.","Top each one with a thin slice of fontina and a slice of cooked ham.","Roll them up tightly.","Lightly beat the egg with salt and pepper and dip the rolls in it.","Roll them in the breadcrumbs and arrange them in a baking tray lined with baking paper, with a drizzle of oil.","Bake at 180 °C for 25 minutes."]},"fr":{"title":"Roulés de poulet au four","steps":["Étaler les tranches de poulet sur une planche à découper.","Recouvrir chacune d''une fine tranche de fontina et d''une tranche de jambon blanc.","Les rouler bien serré sur elles-mêmes.","Battre légèrement l''œuf avec du sel et du poivre et y passer les roulés.","Les rouler dans la chapelure et les disposer dans un plat recouvert de papier cuisson, avec un filet d''huile.","Cuire au four à 180 °C pendant 25 minutes."]}}'::jsonb),
  ('e895582c-375e-49f7-95de-d738448185c2'::uuid, '{"en":{"title":"Pork tenderloin medallions with mushrooms","steps":["Trim the fat and silverskin from the tenderloin, cut it into medallions at least 3 cm thick and pat them dry with kitchen paper.","Melt the clarified butter with the sage in a non-stick frying pan and sear the medallions over high heat for about 2 minutes per side, seasoning lightly with salt and pepper.","Deglaze with the white wine and let the alcohol evaporate, then set the meat aside and keep it warm.","In the same pan, cook the thinly sliced mushrooms with the cream, covered, over low heat.","Season with salt, thicken the sauce with the cornflour, return the medallions to the pan to heat through and serve."]},"fr":{"title":"Médaillons de filet mignon aux champignons","steps":["Parer le filet mignon en retirant le gras et les membranes, le couper en médaillons d''au moins 3 cm d''épaisseur et les éponger avec du papier absorbant.","Faire fondre le beurre clarifié avec la sauge dans une poêle antiadhésive et saisir les médaillons à feu vif environ 2 minutes de chaque côté, en salant et poivrant légèrement.","Déglacer au vin blanc et laisser évaporer l''alcool, puis réserver la viande au chaud.","Dans la même poêle, cuire les champignons finement émincés avec la crème, à couvert et à feu doux.","Saler, épaissir la sauce avec la fécule de maïs, remettre les médaillons à réchauffer et servir."]}}'::jsonb),
  ('5bdecccd-5a1b-46a8-8887-5bdebc040da6'::uuid, '{"en":{"title":"Livorno-style cod","steps":["Peel the garlic and remove the green germ.","Fry the garlic in the oil until golden without burning it, then remove it from the pan.","Lay the cod fillets in the pan and brown them for about 5 minutes per side.","Pour in the white wine and let it evaporate over high heat.","Add the passata, the rinsed capers and the olives, and cook until the sauce thickens.","Just before turning off the heat, add the finely chopped parsley and a grind of pepper."]},"fr":{"title":"Cabillaud à la livournaise","steps":["Éplucher l''ail et retirer le germe.","Faire dorer l''ail dans l''huile sans le brûler, puis le retirer de la poêle.","Déposer les filets de cabillaud et les faire dorer environ 5 minutes de chaque côté.","Mouiller avec le vin blanc et laisser évaporer à feu vif.","Ajouter le coulis de tomate, les câpres rincées et les olives, et cuire jusqu''à ce que la sauce réduise.","Juste avant d''éteindre le feu, ajouter le persil finement haché et un tour de moulin à poivre."]}}'::jsonb),
  ('686a6848-a856-4bbe-b6f3-f2f4dae462d8'::uuid, '{"en":{"title":"Sea bream baked in foil","steps":["Preheat the oven to 180 °C.","Clean the sea bream by slitting open the belly, gut it, scale it by scraping against the direction of the scales, then wash and dry it.","Slice the garlic, onion, carrots and lemon.","Stuff the belly of the fish with the bay leaf, garlic, rosemary, thyme and a pinch of salt.","Lay the sea bream on a sheet of foil with the carrots, onion and lemon, season with oil, salt and pepper and seal the parcel tightly.","Bake for about 40 minutes.","Open the parcel, discard the herbs and aromatic vegetables and serve with a drizzle of fresh olive oil."]},"fr":{"title":"Dorade en papillote","steps":["Préchauffer le four à 180 °C.","Nettoyer la dorade en incisant le ventre, la vider, l''écailler en grattant à rebrousse-écailles, puis la laver et la sécher.","Émincer l''ail, l''oignon, les carottes et le citron.","Farcir le ventre du poisson avec le laurier, l''ail, le romarin, le thym et une pincée de sel.","Déposer la dorade sur une feuille de papier aluminium avec les carottes, l''oignon et le citron, arroser d''huile, saler, poivrer et bien fermer la papillote.","Cuire au four pendant environ 40 minutes.","Ouvrir la papillote, retirer les herbes et les légumes aromatiques et servir avec un filet d''huile d''olive crue."]}}'::jsonb),
  ('5d1e5db1-40e3-4f53-9d61-d92916584684'::uuid, '{"en":{"title":"Pasta with lentils","steps":["If using dried lentils, soak them for about 2 hours (this shortens the cooking time); if using canned, just rinse them.","Finely chop the celery, carrot and onion.","Heat the oil in a pot and gently fry the vegetables with the rosemary and garlic for a few minutes.","Add the pancetta and lentils, cover with the hot stock and cook over low heat: about 25 minutes if soaked, 50 if dried and unsoaked.","When the lentils are tender, add the pasta with just enough extra stock to cover it and cook for about 10 minutes, stirring.","Season with salt and pepper and serve hot with a drizzle of fresh olive oil."]},"fr":{"title":"Pâtes aux lentilles","steps":["Pour des lentilles sèches, les faire tremper environ 2 heures (cela raccourcit la cuisson) ; pour des lentilles en conserve, simplement les rincer.","Hacher finement le céleri, la carotte et l''oignon.","Faire chauffer l''huile dans une casserole et faire revenir les légumes avec le romarin et l''ail pendant quelques minutes.","Ajouter les lardons et les lentilles, couvrir de bouillon chaud et cuire à feu doux : environ 25 minutes si elles ont trempé, 50 si elles sont sèches sans trempage.","Lorsque les lentilles sont tendres, ajouter les pâtes avec juste assez de bouillon pour les couvrir et cuire environ 10 minutes en remuant.","Saler, poivrer et servir chaud avec un filet d''huile d''olive crue."]}}'::jsonb),
  ('17aad271-1907-4d68-b566-8d66d014c39e'::uuid, '{"en":{"title":"Creamy tuna and chickpea pasta","steps":["Bring a pot of salted water to the boil for the pasta.","In a frying pan, heat the oil from the tuna together with the extra virgin olive oil.","Finely chop the onion and soften it in the oil over medium heat.","Add the drained chickpeas and flaked tuna; for a creamier sauce, blend half the chickpeas with a little water.","Cook the pasta al dente and drain it, reserving a ladle of the cooking water.","Tip the pasta into the frying pan, add the cooking water and toss for a few moments until creamy.","Serve with chopped chives."]},"fr":{"title":"Pâtes crémeuses au thon et aux pois chiches","steps":["Porter à ébullition l''eau salée pour les pâtes.","Dans une poêle, faire chauffer l''huile du thon avec l''huile d''olive vierge extra.","Hacher finement l''oignon et le faire suer dans l''huile à feu moyen.","Ajouter les pois chiches égouttés et le thon émietté ; pour une sauce plus crémeuse, mixer la moitié des pois chiches avec un peu d''eau.","Cuire les pâtes al dente et les égoutter en réservant une louche d''eau de cuisson.","Verser les pâtes dans la poêle, ajouter l''eau de cuisson et remuer quelques instants pour lier la sauce.","Servir avec la ciboulette ciselée."]}}'::jsonb),
  ('99a3f1c7-6d4d-4439-a8b2-a3e06f9c8a07'::uuid, '{"en":{"title":"Sicilian-style swordfish","steps":["Wash and halve the cherry tomatoes; peel the garlic and chop the chilli if using.","In a large frying pan, heat a drizzle of oil with the garlic, chilli, capers and olives for a couple of minutes.","Add the cherry tomatoes with oregano, basil and a pinch of salt; cover and cook for 10 minutes.","Lay the swordfish slices in the pan in a single layer, cover and cook for another 10 minutes.","Uncover, turn the fish and cook for 5 minutes so the sauce reduces a little; serve straight away."]},"fr":{"title":"Espadon à la sicilienne","steps":["Laver les tomates cerises et les couper en deux ; éplucher l''ail et hacher le piment, le cas échéant.","Dans une grande poêle, faire chauffer un filet d''huile avec l''ail, le piment, les câpres et les olives pendant deux minutes environ.","Ajouter les tomates cerises avec l''origan, le basilic et une pincée de sel ; couvrir et cuire 10 minutes.","Déposer les tranches d''espadon au fond de la poêle en une seule couche, couvrir et cuire encore 10 minutes.","Découvrir, retourner le poisson et laisser cuire 5 minutes pour que la sauce réduise un peu ; servir aussitôt."]}}'::jsonb),
  ('61e1e664-8f21-4039-82b4-008367e27c96'::uuid, '{"en":{"title":"Chicken breast cacciatore","steps":["Clean the mushrooms and cut them into pieces.","Cut the chicken breast into fairly large chunks.","Peel the garlic, removing the germ, and slice the shallot.","Heat the oil with the garlic and mushrooms over low heat for about 10 minutes.","Add the shallot and chicken, deglaze with the wine and brown until the meat is evenly coloured.","Add the crushed peeled tomatoes and the olives, and season with salt and pepper.","Cook gently for about 10 minutes and serve with fresh basil."]},"fr":{"title":"Blanc de poulet à la chasseur","steps":["Nettoyer les champignons et les couper en morceaux.","Couper le blanc de poulet en morceaux assez gros.","Éplucher l''ail en retirant le germe et émincer l''échalote.","Faire chauffer l''huile avec l''ail et les champignons à feu doux pendant environ 10 minutes.","Ajouter l''échalote et le poulet, déglacer au vin et faire revenir jusqu''à ce que la viande soit uniformément dorée.","Ajouter les tomates pelées écrasées et les olives, saler et poivrer.","Laisser mijoter doucement environ 10 minutes et servir avec du basilic frais."]}}'::jsonb),
  ('567369ff-11d7-4696-a56a-38bcb709f826'::uuid, '{"en":{"title":"Light chicken pizzaiola","steps":["In a large frying pan, cook the tomato pulp with the crushed garlic, salt, pepper and oregano over low heat for 10-15 minutes.","Adjust the salt, thin with half a glass of water and cook for another couple of minutes.","Lay the chicken slices in the sauce, cover them with sauce and sprinkle with more oregano.","Cook over medium heat with the lid ajar for about 10 minutes, turning the meat halfway through.","Off the heat, add a drizzle of fresh olive oil if you like and serve with the sauce."]},"fr":{"title":"Blanc de poulet à la pizzaiola allégé","steps":["Dans une grande poêle, cuire la pulpe de tomate avec l''ail écrasé, le sel, le poivre et l''origan à feu doux pendant 10-15 minutes.","Rectifier le sel, allonger avec un demi-verre d''eau et cuire encore deux minutes environ.","Déposer les escalopes de poulet dans la sauce, les napper de sauce et saupoudrer d''un peu plus d''origan.","Cuire à feu moyen avec le couvercle entrouvert pendant environ 10 minutes, en retournant la viande à mi-cuisson.","Hors du feu, ajouter si on le souhaite un filet d''huile d''olive crue et servir avec la sauce."]}}'::jsonb),
  ('2523169e-7128-44b0-9c23-174778b41c14'::uuid, '{"en":{"title":"Octopus stew with potatoes","steps":["Clean the octopus by removing the eyes, beak and innards, rinse it well and cut it into small pieces.","Thinly slice the onion and put it in a pot with the oil, passata, garlic and octopus; season with salt and pepper and stir.","Cover and cook over low heat for 40 minutes without adding water: the octopus cooks in its own liquid.","Peel the potatoes, cut them into even pieces, rinse them and add them to the pot.","Continue cooking, covered, for another 20 minutes (up to 30 more if the octopus is large), until a fork pierces it without resistance.","Adjust the salt and pepper, finish with fresh parsley and a pinch of chilli and serve hot with the sauce."]},"fr":{"title":"Poulpe mijoté aux pommes de terre","steps":["Nettoyer le poulpe en retirant les yeux, le bec et les viscères, bien le rincer et le couper en petits morceaux.","Émincer finement l''oignon et le mettre dans une cocotte avec l''huile, le coulis de tomate, l''ail et le poulpe ; saler, poivrer et mélanger.","Couvrir et cuire à feu doux pendant 40 minutes sans ajouter d''eau : le poulpe cuit dans son propre jus.","Éplucher les pommes de terre, les couper en morceaux réguliers, les rincer et les ajouter dans la cocotte.","Poursuivre la cuisson à couvert pendant encore 20 minutes (jusqu''à 30 de plus si le poulpe est gros), jusqu''à ce qu''une fourchette le transperce sans résistance.","Rectifier l''assaisonnement en sel et en poivre, parsemer de persil frais et d''une pincée de piment et servir chaud avec la sauce."]}}'::jsonb),
  ('99e6987f-43cf-4bb6-a6d2-33eca8e6d6c9'::uuid, '{"en":{"title":"Prawn and orange risotto","steps":["Peel the prawns, removing the heads and shells.","Fry them in a frying pan with the oil and garlic until they change colour, then set them aside.","In a saucepan, soften the chopped shallot in the butter, add the rice and toast it for 2-3 minutes.","Deglaze with the white wine and let it evaporate.","Cook the rice through, adding the boiling stock one ladle at a time and stirring often (about 16-18 minutes).","A few minutes before the end, add the prawns and orange zest; season with salt.","Turn off the heat, stir in the cold butter until creamy, leave to rest for a couple of minutes and serve."]},"fr":{"title":"Risotto aux crevettes et à l''orange","steps":["Décortiquer les crevettes en retirant la tête et la carapace.","Les faire revenir à la poêle avec l''huile et l''ail jusqu''à ce qu''elles changent de couleur, puis les réserver.","Dans une casserole, faire suer l''échalote hachée dans le beurre, ajouter le riz et le faire nacrer 2-3 minutes.","Déglacer au vin blanc et laisser évaporer.","Poursuivre la cuisson en ajoutant le bouillon bouillant louche par louche, en remuant souvent (environ 16-18 minutes).","Quelques minutes avant la fin, ajouter les crevettes et le zeste d''orange ; saler.","Éteindre le feu, incorporer le beurre froid pour lier le risotto, laisser reposer deux minutes environ et servir."]}}'::jsonb),
  ('48ebc83a-a38f-414e-9c34-86c41a6e7c2c'::uuid, '{"en":{"title":"Pistachio and almond crusted salmon","steps":["Preheat the oven to 200 °C.","Chop the pistachios and almonds and mix them with the breadcrumbs, a pinch of salt and the oil until you have a firm mixture.","Lightly grease an ovenproof dish and arrange the salmon fillets in it.","Spread the crust over the top of the fillets, pressing down well.","Bake for about 15 minutes, until the crust is golden, and serve."]},"fr":{"title":"Saumon en croûte de pistaches et d''amandes","steps":["Préchauffer le four à 200 °C.","Hacher les pistaches et les amandes et les mélanger avec la chapelure, une pincée de sel et l''huile jusqu''à obtenir une préparation compacte.","Huiler légèrement un plat allant au four et y disposer les pavés de saumon.","Répartir la croûte sur le dessus des pavés en pressant bien.","Cuire au four pendant environ 15 minutes, jusqu''à ce que la croûte soit dorée, et servir."]}}'::jsonb),
  ('620775f7-df12-48a6-acee-5a00dcdfeba6'::uuid, '{"en":{"title":"Saltimbocca alla romana","steps":["Trim the fat and sinew from the veal slices and salt them very lightly, as the prosciutto is already salty.","Coat the slices evenly in flour.","Place a slice of prosciutto and a sage leaf on each one, securing them with a cocktail stick.","Melt the butter in a frying pan and brown the slices.","Pour in the white wine and let it evaporate completely.","Cover and continue cooking for about 2 minutes, then serve immediately, piping hot."]},"fr":{"title":"Saltimbocca alla romana","steps":["Retirer le gras et les nerfs des escalopes de veau et les saler à peine, le jambon cru étant déjà salé.","Fariner les escalopes de manière uniforme.","Déposer sur chacune une tranche de jambon cru et une feuille de sauge, et les fixer avec un cure-dent.","Faire fondre le beurre dans une poêle et faire dorer les escalopes.","Mouiller avec le vin blanc et le laisser s''évaporer complètement.","Couvrir et poursuivre la cuisson environ 2 minutes, puis servir aussitôt bien chaud."]}}'::jsonb),
  ('015f5e6a-260f-4598-bd56-b3e794d5a80f'::uuid, '{"en":{"title":"Lemon chicken escalopes","steps":["Dust the chicken slices with flour on both sides, shaking off the excess.","Heat a drizzle of oil with the pinch of garlic powder in a non-stick frying pan.","Brown the escalopes on both sides until golden, then season with salt.","Pour in the lemon juice and a glass of water and let it reduce until a creamy sauce forms.","Stir in the honey to soften the acidity and turn the slices again in the pan juices.","Finish with grated lemon zest and ground pepper, leave to rest for a moment and serve with parsley and the sauce."]},"fr":{"title":"Escalopes de poulet au citron","steps":["Fariner les escalopes de poulet des deux côtés en secouant l''excédent.","Faire chauffer un filet d''huile avec la pincée d''ail en poudre dans une poêle antiadhésive.","Faire dorer les escalopes des deux côtés, puis les saler.","Verser le jus de citron et un verre d''eau et laisser réduire jusqu''à obtenir une petite sauce onctueuse.","Incorporer le miel pour adoucir l''acidité et retourner de nouveau les escalopes dans le jus.","Terminer avec le zeste de citron râpé et du poivre moulu, laisser reposer un instant et servir avec le persil et la sauce."]}}'::jsonb),
  ('60fe0e85-846c-4255-941b-f36927ddbfb8'::uuid, '{"en":{"title":"Pan-cooked lemon turkey thigh","steps":["Remove any remaining feathers and, if you like, bone the thigh with a knife.","Heat the oil in a frying pan and add the meat with the lemon slices and juice, salt, pepper, rosemary and bay leaves.","Brown over high heat until golden, then turn it and brown the other side.","Deglaze with the white wine and let the alcohol evaporate.","Cover, turn the heat down to the minimum and cook for about an hour, without adding water.","Raise the heat to reduce the liquid and caramelise the meat in its juices, turning it.","Leave to rest, covered, for 5-10 minutes before serving."]},"fr":{"title":"Haut de cuisse de dinde au citron à la poêle","steps":["Retirer les éventuelles plumes restantes et, si on le souhaite, désosser le haut de cuisse au couteau.","Faire chauffer l''huile dans une poêle et y déposer la viande avec les tranches et le jus de citron, le sel, le poivre, le romarin et le laurier.","Faire dorer à feu vif, puis la retourner et faire dorer l''autre face.","Déglacer au vin blanc et laisser évaporer l''alcool.","Couvrir, baisser le feu au minimum et cuire environ une heure, sans ajouter d''eau.","Monter le feu pour faire réduire les liquides et caraméliser la viande dans son jus, en la retournant.","Laisser reposer à couvert 5-10 minutes avant de servir."]}}'::jsonb),
  ('63131dca-fae3-4d10-8d21-eb0d75a2cdc5'::uuid, '{"en":{"title":"Spaghetti alle vongole","steps":["Soak the clams in cold water with the coarse salt for about 2 hours so they release their sand.","In a large frying pan, heat the oil with the garlic clove and the parsley stems for about 1 minute.","Add the drained clams, cover and cook over high heat until they have all opened.","Strain and keep the cooking liquid, shell about two thirds of the clams and discard the garlic and stems.","Boil the spaghetti in salted water and drain them 5 minutes before the stated cooking time, setting aside some of the cooking water.","Return the spaghetti to the pan with the clams, their strained liquid and a little cooking water; toss until the sauce turns thick and creamy.","Finish with finely chopped parsley and a grind of pepper, then serve immediately."]},"fr":{"title":"Spaghetti alle vongole","steps":["Faire tremper les palourdes dans de l''eau froide avec le gros sel pendant environ 2 heures, pour qu''elles rejettent leur sable.","Dans une grande poêle, faire chauffer l''huile avec la gousse d''ail et les tiges de persil pendant environ 1 minute.","Ajouter les palourdes égouttées, couvrir et cuire à feu vif jusqu''à ce qu''elles soient toutes ouvertes.","Filtrer et conserver le jus de cuisson, décortiquer environ les deux tiers des palourdes et retirer l''ail et les tiges.","Cuire les spaghetti dans de l''eau salée et les égoutter 5 minutes avant le temps indiqué, en réservant un peu d''eau de cuisson.","Remettre les spaghetti dans la poêle avec les palourdes, leur jus filtré et un peu d''eau de cuisson ; faire sauter jusqu''à ce que la sauce devienne épaisse et crémeuse.","Terminer avec du persil finement ciselé et un tour de moulin à poivre, puis servir aussitôt."]}}'::jsonb),
  ('10e1f9f4-df57-4d78-9f93-c707704a3740'::uuid, '{"en":{"title":"Veal stew with potatoes","steps":["Peel the carrot and onion, trim the celery and cut everything into rough chunks.","Heat the oil and gently soften the vegetables with the herbs over low heat for 20-25 minutes, without water.","Cut the veal into 3-5 cm cubes, removing fat and gristle.","Add the meat to the softened vegetables and stir until it changes colour on all sides.","Deglaze with the red wine over high heat until it has completely evaporated.","Pour in the hot stock and cook over very low heat for about an hour, covering if the liquid reduces too much.","Peel the potatoes, cut them into pieces of at least 4 cm and add them to the stew.","Cook for about 20 more minutes, until the potatoes are tender and the sauce is thick."]},"fr":{"title":"Sauté de veau aux pommes de terre","steps":["Éplucher la carotte et l''oignon, nettoyer le céleri et couper le tout en gros morceaux.","Faire chauffer l''huile et faire suer les légumes avec les herbes aromatiques à feu doux pendant 20-25 minutes, sans eau.","Couper le veau en cubes de 3-5 cm, en retirant le gras et les cartilages.","Ajouter la viande aux légumes et remuer jusqu''à ce qu''elle change de couleur sur toutes les faces.","Déglacer au vin rouge à feu vif jusqu''à complète évaporation.","Verser le bouillon chaud et cuire à feu très doux pendant environ une heure, en couvrant si le liquide réduit trop.","Éplucher les pommes de terre, les couper en morceaux d''au moins 4 cm et les ajouter au sauté.","Poursuivre la cuisson environ 20 minutes, jusqu''à ce que les pommes de terre soient tendres et la sauce épaisse."]}}'::jsonb),
  ('e602a672-019f-4399-a580-26a8268d9a62'::uuid, '{"en":{"title":"Beef strips with rocket and cherry tomatoes","steps":["Wash and dry the rocket; wash the cherry tomatoes and halve them.","Pound the beef slices to thin them, cut them into strips and quickly dredge them in the sifted flour.","Heat the oil with the garlic in a non-stick frying pan and brown the beef strips over high heat for 2-3 minutes.","Season with salt and pepper, add the cherry tomatoes and toss for about a minute.","Add half the rocket, stir for one more minute and turn off the heat.","Plate on a bed of raw rocket and cherry tomatoes, lay the meat on top and finish with a drizzle of oil and balsamic vinegar."]},"fr":{"title":"Émincé de bœuf à la roquette et aux tomates cerises","steps":["Laver et sécher la roquette ; laver les tomates cerises et les couper en deux.","Aplatir les tranches de bœuf pour les affiner, les tailler en lanières et les passer rapidement dans la farine tamisée.","Faire chauffer l''huile avec l''ail dans une poêle antiadhésive et faire dorer les lanières de bœuf à feu vif pendant 2-3 minutes.","Saler et poivrer, ajouter les tomates cerises et faire sauter environ une minute.","Ajouter la moitié de la roquette, mélanger encore une minute et éteindre le feu.","Dresser sur un lit de roquette et de tomates cerises crues, déposer la viande dessus et terminer par un filet d''huile et de vinaigre balsamique."]}}'::jsonb),
  ('4147d3f8-71f3-493a-987d-035d634235c5'::uuid, '{"en":{"title":"Beef strips with vegetables","steps":["Cut the meat into thin strips and marinate for about 15 minutes with the soy sauce, a drizzle of oil, the ginger, crushed garlic and cornflour.","Cut the carrot and courgettes into sticks and the spring onion into rounds.","Stir-fry the vegetables in a frying pan with a little oil and a pinch of salt over high heat for a few minutes, keeping them crunchy.","In another frying pan with a drizzle of oil, brown the beef strips for a couple of minutes, stirring constantly.","Combine the meat and vegetables, add the sesame seeds and stir-fry over high heat for 1-2 minutes; serve immediately."]},"fr":{"title":"Émincé de bœuf aux légumes","steps":["Tailler la viande en fines lanières et la faire mariner environ 15 minutes avec la sauce soja, un filet d''huile, le gingembre, l''ail écrasé et la fécule de maïs.","Tailler la carotte et les courgettes en bâtonnets et l''oignon nouveau en rondelles.","Faire sauter les légumes à la poêle avec un peu d''huile et une pincée de sel à feu vif pendant quelques minutes, en les gardant croquants.","Dans une autre poêle avec un filet d''huile, faire revenir les lanières de bœuf pendant deux minutes environ, en remuant sans cesse.","Réunir la viande et les légumes, ajouter les graines de sésame et faire sauter à feu vif 1-2 minutes ; servir aussitôt."]}}'::jsonb),
  ('6293ce0d-a630-48c6-b558-37f7a09ff101'::uuid, '{"en":{"title":"Beef tagliata with rocket and Parmesan","steps":["Take the meat out of the fridge an hour beforehand to bring it to room temperature.","Heat the grill pan well and sprinkle it with coarse salt.","Cook the sirloin for 3 minutes per side.","Let it rest for a minute on a chopping board, then slice it about half a centimetre thick and season with pepper.","Wash and dry the rocket, removing the long stems.","Arrange the rocket and beef slices on the plate, finish with Parmesan shavings and a drizzle of oil."]},"fr":{"title":"Tagliata de bœuf, roquette et parmesan","steps":["Sortir la viande du réfrigérateur une heure avant pour la mettre à température ambiante.","Bien faire chauffer le gril et le parsemer de gros sel.","Cuire le faux-filet 3 minutes de chaque côté.","Le laisser reposer une minute sur une planche, puis le trancher à environ un demi-centimètre d''épaisseur et poivrer.","Laver et sécher la roquette en retirant les longues tiges.","Disposer la roquette et les tranches de viande dans l''assiette, terminer avec des copeaux de parmesan et un filet d''huile."]}}'::jsonb),
  ('eed99dab-45c0-4360-afbb-73c4b4ebc594'::uuid, '{"en":{"title":"Basque-style chicken breast","steps":["Slice each chicken breast in half horizontally to make thin escalopes.","Thinly slice the onion and garlic, deseed the pepper and cut it into thin strips.","Blanch the tomato in boiling water for 30 s, peel it and chop it roughly; cut the ham into strips.","Sear the onion, garlic and pepper in the oil over high heat for about 8 min, then set aside.","In the same frying pan, brown the escalopes for a few minutes on each side.","Return the vegetables, add the ham, tomato and Espelette pepper, season with salt and pepper and stir gently.","Pour in the white wine and reduce at a rolling boil for 3 min.","Lower the heat and simmer for about 15 min, stirring often."]},"it":{"title":"Petto di pollo alla basca","steps":["Aprire ogni petto di pollo a metà nello spessore per ottenere delle fettine sottili.","Affettare la cipolla e l''aglio, eliminare i semi dal peperone e tagliarlo a listarelle sottili.","Sbollentare il pomodoro 30 s in acqua bollente, pelarlo e tagliarlo a pezzetti; tagliare il prosciutto a listarelle.","Saltare cipolla, aglio e peperone nell''olio a fuoco vivo per circa 8 min, poi tenerli da parte.","Nella stessa padella, dorare le fettine per qualche minuto per lato.","Rimettere le verdure, aggiungere prosciutto, pomodoro e peperoncino di Espelette, salare, pepare e mescolare delicatamente.","Versare il vino bianco e farlo ridurre a fuoco vivace per 3 min.","Abbassare la fiamma e cuocere a fuoco lento per circa 15 min, mescolando spesso."]}}'::jsonb),
  ('f57e24d7-670a-41d7-89de-13783e359454'::uuid, '{"en":{"title":"Light veal blanquette","steps":["Bring a casserole of water to the boil; meanwhile, peel and slice the onion, shallot and carrots.","Add the meat and vegetables to the boiling water with the thyme, season with salt and pepper, cover and cook for 30 min.","Drain everything, return it to the casserole with the drained mushrooms and sauté briefly.","Stir in the cream and lemon juice, mixing well until the sauce is thick enough to coat.","Serve immediately, for example with green beans."]},"it":{"title":"Blanquette di vitello leggera","steps":["Portare a ebollizione una casseruola d''acqua; nel frattempo, pelare e affettare cipolla, scalogno e carote.","Immergere la carne e le verdure nell''acqua bollente con il timo, salare, pepare, coprire e cuocere per 30 min.","Scolare il tutto, rimetterlo nella casseruola con i funghi sgocciolati e farlo saltare brevemente.","Incorporare la panna e il succo di limone mescolando bene, finché la salsa risulta abbastanza densa da velare.","Servire subito, per esempio con fagiolini."]}}'::jsonb),
  ('449a378d-34ee-45e9-b50d-4fd3ee78ab88'::uuid, '{"en":{"title":"One-pot veal blanquette","steps":["Cut the veal into large pieces, the carrots into rounds and the mushrooms into quarters; chop the onion and garlic, and peel and dice the potato.","In a large casserole, quickly sear the veal in the oil without browning it too much.","Add the onion and garlic, sprinkle with the flour and stir for 1 min.","Add the carrots, mushrooms, potato, thyme and bay leaf, pour in the hot stock, season lightly with salt, add pepper and stir.","Cover and cook over low heat for 1 h 15 to 1 h 30, stirring from time to time, until the meat is meltingly tender.","Off the heat, whisk the cream with the egg yolk and lemon juice, then stir it in gently without letting it boil again.","Sprinkle with parsley and serve."]},"it":{"title":"Blanquette di vitello one pot","steps":["Tagliare il vitello a pezzi grossi, le carote a rondelle e i funghi in quarti; tritare cipolla e aglio, pelare la patata e tagliarla a dadini.","In una casseruola capiente, rosolare velocemente il vitello nell''olio senza farlo colorire troppo.","Aggiungere cipolla e aglio, spolverizzare con la farina e mescolare per 1 min.","Aggiungere carote, funghi, patata, timo e alloro, versare il brodo caldo, salare leggermente, pepare e mescolare.","Coprire e cuocere a fuoco basso da 1 h 15 a 1 h 30, mescolando di tanto in tanto, finché la carne è tenerissima.","Fuori dal fuoco, sbattere la panna con il tuorlo e il succo di limone, poi incorporarla delicatamente senza far riprendere il bollore.","Cospargere di prezzemolo e servire."]}}'::jsonb),
  ('50ecea78-6439-45fa-8702-4656b35e676d'::uuid, '{"en":{"title":"Light salt cod brandade","steps":["The day before, rinse the salt cod and leave it to desalt for 24 h in the fridge in cold water, changing the water 3 to 4 times.","Peel and cut the potatoes, then cook them in boiling water until tender.","Put the cod and crushed garlic in cold water and poach for 8 to 10 minutes at a gentle simmer, without boiling.","Drain the cod, remove the skin and bones, then flake it finely.","Mash the potatoes, adding the warm milk little by little, then stir in the yoghurt or skyr.","Mix the cod into the mash while drizzling in the olive oil, then season with pepper and add a little nutmeg.","Reheat over low heat or for 10 minutes in the oven at 180 °C, then serve sprinkled with parsley."]},"it":{"title":"Brandade di baccalà leggera","steps":["Il giorno prima, sciacquare il baccalà e lasciarlo dissalare 24 h in frigorifero in acqua fredda, cambiando l''acqua 3 o 4 volte.","Pelare e tagliare le patate, poi lessarle in acqua bollente finché sono tenere.","Mettere il baccalà e l''aglio schiacciato in acqua fredda e cuocerlo da 8 a 10 minuti a fuoco dolcissimo, appena sobbollente, senza farlo bollire.","Scolare il baccalà, eliminare pelle e spine, poi sfilacciarlo finemente.","Schiacciare le patate aggiungendo poco alla volta il latte tiepido, poi incorporare lo yogurt o lo skyr.","Mescolare il baccalà al purè versando l''olio d''oliva a filo, poi pepare e aggiungere un po'' di noce moscata.","Scaldare a fuoco basso o per 10 minuti in forno a 180 °C, poi servire cosparso di prezzemolo."]}}'::jsonb),
  ('e1a56986-8c34-4f97-b92c-a9595a04b081'::uuid, '{"en":{"title":"Bœuf bourguignon","steps":["Optional: the day before, marinate the beef cubes in the fridge in the wine with a little carrot, the crushed garlic and the bouquet garni.","Drain the meat, keeping the liquid, pat it dry, season with salt and pepper and dust lightly with flour.","Sear the beef in small batches over high heat in hot oil in a casserole, then set aside.","In the casserole, brown the lardons, then the carrot rounds, for 5 min.","Return the meat, sprinkle with the remaining flour, add the tomato purée, then the wine (or the strained marinade), the stock and the bouquet garni; bring to the boil.","Cover and cook in the oven at 150 °C for 2 h 30 to 3 h, stirring from time to time.","About 45 min before the end, fry the mushrooms in butter; in another frying pan, glaze the pearl onions with a little butter, sugar and water.","Add the mushrooms and onions to the casserole for the last 30 minutes and adjust the seasoning.","Remove the bouquet garni, sprinkle with parsley and serve piping hot."]},"it":{"title":"Bœuf bourguignon","steps":["Facoltativo: il giorno prima, marinare i cubetti di manzo in frigorifero nel vino con un po'' di carota, l''aglio schiacciato e il mazzetto aromatico.","Scolare la carne conservando il liquido, asciugarla, salarla, peparla e infarinarla leggermente.","Rosolare il manzo poco alla volta a fuoco vivo nell''olio caldo in una casseruola, poi tenerlo da parte.","Nella casseruola, rosolare la pancetta a cubetti, poi la carota a rondelle per 5 min.","Rimettere la carne, spolverizzare con la farina rimasta, aggiungere il concentrato di pomodoro, poi il vino (o la marinata filtrata), il brodo e il mazzetto aromatico; portare a ebollizione.","Coprire e cuocere in forno a 150 °C da 2 h 30 a 3 h, mescolando di tanto in tanto.","Circa 45 min prima della fine, saltare i funghi nel burro; in un''altra padella, glassare le cipolline con un po'' di burro, zucchero e acqua.","Aggiungere funghi e cipolline nella casseruola per gli ultimi 30 minuti e regolare di sale e pepe.","Togliere il mazzetto aromatico, cospargere di prezzemolo e servire ben caldo."]}}'::jsonb),
  ('589fb2e8-d8cb-4568-93b3-16cca96d832b'::uuid, '{"en":{"title":"Spiced baked cod with vegetables","steps":["Preheat the oven to 200 °C.","Slice the potatoes and courgettes into rounds, dice the onion and cut the pepper into strips.","Mix these vegetables with the cherry tomatoes, olive oil, lemon juice, peeled garlic cloves and a little salt.","Spread everything out in a large dish and roast for 25 minutes.","Meanwhile, mix the oil, lemon juice, paprika, turmeric and Espelette pepper, then brush it over the cod pieces.","Place the fish on the vegetables and cook for a further 15 minutes.","Serve sprinkled with chopped parsley, with lemon wedges."]},"it":{"title":"Merluzzo speziato al forno con verdure","steps":["Preriscaldare il forno a 200 °C.","Tagliare patate e zucchine a rondelle, la cipolla a dadini e il peperone a listarelle.","Mescolare queste verdure con i pomodorini, l''olio d''oliva, il succo di limone, gli spicchi d''aglio pelati e un po'' di sale.","Distribuire il tutto in una teglia grande e arrostire in forno per 25 minuti.","Nel frattempo, mescolare l''olio, il succo di limone, la paprika, la curcuma e il peperoncino di Espelette, poi spennellarne i pezzi di merluzzo.","Adagiare il pesce sulle verdure e proseguire la cottura per 15 minuti.","Servire cosparso di prezzemolo tritato, con spicchi di limone."]}}'::jsonb),
  ('c4df5fda-28c9-43a2-96e7-7e5561d1ce17'::uuid, '{"en":{"title":"Basque-style cod loin","steps":["Preheat the oven to 210 °C. Plunge the tomatoes into boiling water for 30 seconds so they peel easily.","Deseed the tomatoes and dice them; cut the pepper into cubes, thinly slice the onion and chop the garlic.","Put the vegetables in a sauté pan with a small glass of water, the chilli and the bouquet garni, cover and leave to stew gently over low heat.","Season with salt and pepper, then remove the chilli and the bouquet garni.","Cook the rice for about 20 minutes in boiling salted water, drain it and keep it warm.","Spread the stewed vegetables in a gratin dish, place the cod pieces on top, season with salt and pepper and bake for 10 minutes.","Serve the fish and its Basque-style vegetables with the rice."]},"it":{"title":"Trancio di merluzzo alla basca","steps":["Preriscaldare il forno a 210 °C. Immergere i pomodori per 30 secondi in acqua bollente per pelarli facilmente.","Eliminare i semi dai pomodori e tagliarli a dadini; tagliare il peperone a cubetti, affettare la cipolla e tritare l''aglio.","Mettere le verdure in una padella dai bordi alti con un bicchierino d''acqua, il peperoncino e il mazzetto aromatico, coprire e lasciar stufare a fuoco basso.","Salare, pepare, poi togliere il peperoncino e il mazzetto aromatico.","Cuocere il riso per circa 20 minuti in acqua bollente salata, scolarlo e tenerlo in caldo.","Distribuire le verdure stufate in una pirofila, adagiarvi sopra i tranci di merluzzo, salare, pepare e infornare per 10 minuti.","Servire il pesce e le sue verdure alla basca con il riso."]}}'::jsonb),
  ('484ced08-5bb5-47ec-ac0a-be7990951eef'::uuid, '{"en":{"title":"Pork tenderloin with mustard","steps":["Thinly slice the onion.","Heat the butter and oil in a sauté pan and sear the pork tenderloin on all sides.","Soften the onion in the fat for 5 min, deglaze with the white wine and return the meat.","Cover and cook for 20 min over medium heat, then set the meat aside on a plate.","Pour the cream into the pan, scraping up the browned bits, season with salt and pepper and stir in both mustards.","Cut the tenderloin into thick slices, return them to the sauce, spoon it over and simmer gently for 10 min."]},"it":{"title":"Filetto di maiale alla senape","steps":["Affettare finemente la cipolla.","Scaldare burro e olio in una padella dai bordi alti e rosolare il filetto su tutti i lati.","Far appassire la cipolla nel grasso di cottura per 5 min, sfumare con il vino bianco e rimettere la carne.","Coprire e cuocere 20 min a fuoco medio, poi tenere da parte la carne su un piatto.","Versare la panna nella padella raschiando il fondo, salare, pepare e stemperarvi le due senapi.","Tagliare il filetto a fette spesse, rimetterle nella salsa, ricoprirle di salsa e cuocere a fuoco lento per 10 min."]}}'::jsonb),
  ('77447388-35a3-4563-83f0-2ca7a120c528'::uuid, '{"en":{"title":"Mustard pork tenderloin with potatoes and broccoli","steps":["Whisk the mustard, maple syrup, soy sauce and a little oil, coat the pork tenderloin and leave it to marinate in the fridge for at least 30 min.","Preheat the oven to 190 °C and thinly slice the potatoes.","Spread the potatoes in a dish, season with salt, pepper, thyme and oil, then bake for 15 min.","Cut the broccoli into florets.","Add the tenderloin and broccoli alongside the potatoes, season and roast for 25 to 30 min, until the core temperature reaches 63 °C.","Let the meat rest for a few minutes, slice it and serve with the vegetables."]},"it":{"title":"Filetto di maiale alla senape con patate e broccoli","steps":["Sbattere senape, sciroppo d''acero, salsa di soia e un po'' d''olio, ricoprire il filetto e lasciarlo marinare in frigorifero per almeno 30 min.","Preriscaldare il forno a 190 °C e affettare sottilmente le patate.","Distribuire le patate in una teglia, condire con sale, pepe, timo e olio, poi infornare per 15 min.","Dividere il broccolo in cimette.","Aggiungere il filetto e il broccolo accanto alle patate, condire e arrostire da 25 a 30 min, finché la carne raggiunge 63 °C al cuore.","Lasciar riposare la carne qualche minuto, affettarla e servire con le verdure."]}}'::jsonb),
  ('9b3c2f12-57fa-470a-81df-b5393ed78c87'::uuid, '{"en":{"title":"Moules marinières","steps":["Rinse the mussels thoroughly and discard any that are broken or stay open when tapped.","Cut the celery into small dice, and chop the shallots and parsley.","Melt the butter in a casserole and gently sweat the shallots and celery without letting them colour.","Add the mussels, white wine, a generous amount of pepper, the bouquet garni and the parsley.","Cover and cook over high heat for 3 to 4 minutes, stirring halfway through, until all the mussels have opened.","Stir one last time to coat the mussels in the juices, remove the bouquet garni and serve immediately."]},"it":{"title":"Moules marinières","steps":["Sciacquare accuratamente le cozze ed eliminare quelle rotte o che restano aperte quando si picchiettano.","Tagliare il sedano a dadini, tritare gli scalogni e il prezzemolo.","Far sciogliere il burro in una casseruola e farvi appassire dolcemente scalogni e sedano, senza farli colorire.","Aggiungere le cozze, il vino bianco, una generosa macinata di pepe, il mazzetto aromatico e il prezzemolo.","Coprire e cuocere a fuoco vivo da 3 a 4 minuti mescolando a metà cottura, finché tutte le cozze si sono aperte.","Mescolare un''ultima volta per avvolgere le cozze nel loro sugo, togliere il mazzetto aromatico e servire subito."]}}'::jsonb),
  ('3716d87e-51ea-489d-9fc2-2d1322423904'::uuid, '{"en":{"title":"Light lamb navarin","steps":["Peel and cut the carrot, turnip and potatoes; slice the leek and onion, chop the tomato and top and tail the beans. Trim the fat from the lamb.","Sear the lamb in the hot oil for 5 to 7 min, then set aside.","Sweat the onion and garlic in the casserole and, if desired, sprinkle them with flour.","Return the lamb, add the stock, tomato, carrot, turnip, leek and bouquet garni; cover and simmer gently for 45 min.","Add the potatoes and green beans and cook for another 15 to 20 min until tender.","Adjust the seasoning, remove the bouquet garni and serve in shallow bowls sprinkled with parsley."]},"it":{"title":"Navarin di agnello leggero","steps":["Pelare e tagliare carota, rapa e patate; affettare porro e cipolla, tagliare a pezzetti il pomodoro e spuntare i fagiolini. Sgrassare l''agnello.","Rosolare l''agnello da 5 a 7 min nell''olio caldo, poi tenerlo da parte.","Far appassire la cipolla e l''aglio nella casseruola e, se si desidera, spolverizzarli con la farina.","Rimettere l''agnello, aggiungere brodo, pomodoro, carota, rapa, porro e mazzetto aromatico; coprire e lasciar sobbollire per 45 min.","Aggiungere patate e fagiolini e cuocere ancora da 15 a 20 min, finché sono teneri.","Regolare di sale e pepe, togliere il mazzetto aromatico e servire in piatti fondi cosparsi di prezzemolo."]}}'::jsonb),
  ('a939f34c-48e2-4fd3-bc1a-216d1801b422'::uuid, '{"en":{"title":"Spring lamb navarin","steps":["Season the lamb with salt and pepper, then sear it over high heat in the hot oil in a casserole, about 3 min per side.","Add the chopped carrot, turnip and onion and sauté for 5 min over medium heat.","Pour in the wine, bring to the boil and reduce by a third.","Add the garlic, bay leaf, cloves and thyme, cover with stock, season and simmer gently for 30 min.","Add the potatoes, celery and tomato, cut into pieces, along with the peas.","Cover and continue cooking over low heat for 20 to 30 min, until the potatoes are tender.","Sprinkle with chopped parsley and serve."]},"it":{"title":"Navarin di agnello primaverile","steps":["Salare e pepare l''agnello, poi rosolarlo a fuoco vivo nell''olio caldo in una casseruola, circa 3 min per lato.","Aggiungere carota, rapa e cipolla tagliate e rosolarle per 5 min a fuoco medio.","Versare il vino, portare a ebollizione e far ridurre di un terzo.","Aggiungere aglio, alloro, chiodi di garofano e timo, coprire con il brodo, condire e lasciar sobbollire per 30 min.","Aggiungere le patate, il sedano e il pomodoro a pezzi, insieme ai piselli.","Coprire e proseguire la cottura a fuoco basso da 20 a 30 min, finché le patate sono tenere.","Cospargere di prezzemolo tritato e servire."]}}'::jsonb),
  ('f2fd383a-9f87-4d59-8b6f-1bcb8af6b4ba'::uuid, '{"en":{"title":"Cod en papillote with cheese and peppers","steps":["Preheat the oven to 180 °C.","Wash, deseed and peel the peppers, then cut them into thin strips.","Finely chop the tarragon and cut the cheese into 3 mm slices.","Soften the pepper strips in a hot frying pan with a little olive oil, add the tarragon at the end of cooking, season and set aside.","Remove the skin from the cod and cover each fillet with slices of cheese.","On sheets of baking paper, lay the peppers then a fish fillet, drizzle with oil, season and seal the parcels tightly.","Bake for 10 minutes, then serve the parcels and open them at the table."]},"it":{"title":"Merluzzo al cartoccio con formaggio e peperoni","steps":["Preriscaldare il forno a 180 °C.","Lavare, privare dei semi e pelare i peperoni, poi tagliarli a listarelle sottili.","Tritare finemente il dragoncello e tagliare il formaggio a fette di 3 mm.","Far appassire le listarelle di peperone in una padella calda con un po'' d''olio d''oliva, aggiungere il dragoncello a fine cottura, condire e tenere da parte.","Togliere la pelle al merluzzo e coprire ogni filetto con fette di formaggio.","Su fogli di carta forno, disporre i peperoni e poi un filetto di pesce, irrorare con un filo d''olio, condire e chiudere ermeticamente i cartocci.","Cuocere in forno per 10 minuti, poi servire i cartocci aprendoli a tavola."]}}'::jsonb),
  ('6fd24020-984a-437d-8c7e-66f378f054a4'::uuid, '{"en":{"title":"Cod en papillote with ginger and lime","steps":["Make the marinade: mix the chopped garlic, the lime zest and juice, the grated ginger, honey, olive oil and soy sauce.","Coat the cod fillets in the marinade, cover and refrigerate for 1 hour.","Preheat the oven to 210 °C. Cut the carrots into sticks and slice the courgette and mangetout.","Par-cook the carrots in boiling water for 10 minutes, then the mangetout and courgette for 2 minutes; drain.","Divide the vegetables among large sheets of baking paper, place the cod on top, drizzle with the remaining marinade and sprinkle with chopped coriander.","Seal the parcels and bake for 20 minutes."]},"it":{"title":"Merluzzo al cartoccio con zenzero e lime","steps":["Preparare la marinata: mescolare l''aglio tritato, la scorza e il succo del lime, lo zenzero grattugiato, il miele, l''olio d''oliva e la salsa di soia.","Ricoprire i tranci di merluzzo con la marinata, coprire e lasciar riposare 1 ora in frigorifero.","Preriscaldare il forno a 210 °C. Tagliare le carote a bastoncini e affettare la zucchina e le taccole.","Precuocere le carote per 10 minuti in acqua bollente, poi le taccole e la zucchina per 2 minuti; scolare.","Distribuire le verdure su grandi fogli di carta forno, adagiarvi sopra il merluzzo, irrorare con la marinata rimasta e cospargere di coriandolo tritato.","Chiudere i cartocci e cuocere in forno per 20 minuti."]}}'::jsonb),
  ('7e1759e4-48d3-4b1a-9b65-d3c31e93172d'::uuid, '{"en":{"title":"Salmon fillets on a bed of lentils","steps":["Stud the onion with the cloves, then put it in a saucepan of water with the lentils, bay leaf, 1 tbsp of oil, salt and pepper.","Simmer for about 25 minutes until the lentils are tender, then drain and remove the onion and bay leaf.","In a frying pan, sweat the shallots in the remaining oil.","Pour in the white wine, add the lemon zest and reduce by half.","Add the lentils, heat through for 2 minutes, stir in the basil, adjust the seasoning and keep warm.","Turn on the oven grill. Place the salmon in a dish, brush it with honey and sprinkle with breadcrumbs.","Place under the grill, on the top shelf, for 5 to 7 minutes depending on thickness.","Cut the salmon into portions and serve them on the lentils."]},"it":{"title":"Tranci di salmone su letto di lenticchie","steps":["Steccare la cipolla con i chiodi di garofano, poi metterla in una pentola d''acqua con le lenticchie, l''alloro, 1 cucchiaio d''olio, sale e pepe.","Lasciar sobbollire per circa 25 minuti finché le lenticchie sono tenere, poi scolarle ed eliminare la cipolla e l''alloro.","In una padella, far appassire gli scalogni nell''olio rimasto.","Versare il vino bianco, aggiungere la scorza di limone e far ridurre della metà.","Aggiungere le lenticchie, scaldare per 2 minuti, incorporare il basilico, regolare di sale e pepe e tenere in caldo.","Accendere il grill del forno. Mettere il salmone in una pirofila, spennellarlo di miele e cospargerlo di pangrattato.","Passare sotto il grill, sul ripiano più alto, da 5 a 7 minuti a seconda dello spessore.","Tagliare il salmone a tranci e servirli sulle lenticchie."]}}'::jsonb),
  ('0987bb18-6284-465e-9872-55a3a4917212'::uuid, '{"en":{"title":"Petit salé (salt pork with lentils)","steps":["Rinse the lentils in cold water and drain them.","In a casserole dish, sauté the diced onion in the olive oil.","Add the diced carrots and the garlic, then the lentils, and stir for about 1 minute.","Lay the salt pork and the sausage on top, pour in the stock, then add the bay leaf, thyme and some pepper.","Cover and simmer for 45 minutes to 1 hour, until the lentils are tender and the meat is cooked; add a little hot water if needed.","Remove the bay leaf and thyme, slice the sausage and sprinkle with parsley.","Serve piping hot with the wholegrain mustard."]},"it":{"title":"Petit salé con lenticchie","steps":["Sciacquare le lenticchie in acqua fredda e scolarle.","In una casseruola, soffriggere la cipolla a dadini nell''olio d''oliva.","Aggiungere le carote a dadini e l''aglio, poi le lenticchie, e mescolare per circa 1 minuto.","Adagiare il petit salé e la salsiccia, versare il brodo, poi aggiungere l''alloro, il timo e il pepe.","Coprire e cuocere a fuoco lento da 45 minuti a 1 ora, finché le lenticchie sono tenere e la carne è cotta; aggiungere un po'' d''acqua calda se necessario.","Togliere l''alloro e il timo, affettare la salsiccia e cospargere di prezzemolo.","Servire ben caldo con la senape in grani."]}}'::jsonb),
  ('e28bf347-b869-4708-97e6-b7edec18d66e'::uuid, '{"en":{"title":"White wine and tarragon chicken with carrots","steps":["Preheat the oven to 190 °C (170 °C fan).","Arrange the chicken breasts in a baking dish and season them with salt.","Brown the sliced shallots in the oil, then spread them over the chicken.","Mix most of the stock with the wine and the fromage frais, add the chopped tarragon and season with pepper.","Pour over the chicken, cover and bake for 30 to 35 min until cooked through.","Meanwhile, sauté the carrots in the melted butter, add the rest of the stock and cook for about 15 min.","Add the parsley to the carrots, season and serve with the chicken, garnished with tarragon."]},"it":{"title":"Pollo al vino bianco e dragoncello con carote","steps":["Preriscaldare il forno a 190 °C (170 °C ventilato).","Disporre i petti di pollo in una pirofila e salarli.","Far dorare gli scalogni affettati nell''olio, poi distribuirli sul pollo.","Mescolare la maggior parte del brodo con il vino e il formaggio fresco, aggiungere il dragoncello tritato e pepare.","Versare sul pollo, coprire e infornare per 30-35 min, fino a cottura completa.","Nel frattempo, rosolare le carote nel burro fuso, bagnare con il resto del brodo e cuocere per circa 15 min.","Aggiungere il prezzemolo alle carote, aggiustare di sale e pepe e servire con il pollo, guarnendo con il dragoncello."]}}'::jsonb),
  ('c342d26f-6184-4e3a-898e-bf58347b4ac2'::uuid, '{"en":{"title":"Braised chicken with olives","steps":["Season the chicken pieces with salt and pepper, then brown them for about 10 min in a casserole dish with a drizzle of olive oil.","Remove the chicken and soften the sliced onion and garlic in the casserole dish.","Return the chicken, pour in the white wine and a small glass of water, then add the drained olives.","Season with the herbes de Provence, salt and pepper, cover and simmer for 40 min over low heat.","Taste, adjust the seasoning, cook a few minutes longer if needed and serve."]},"it":{"title":"Pollo in umido alle olive","steps":["Salare e pepare i pezzi di pollo, poi rosolarli per circa 10 min in una casseruola con un filo d''olio d''oliva.","Togliere il pollo e far appassire la cipolla e l''aglio affettati nella casseruola.","Rimettere il pollo, bagnare con il vino bianco e un bicchierino d''acqua, poi aggiungere le olive sgocciolate.","Insaporire con le erbe di Provenza, sale e pepe, coprire e cuocere a fuoco lento per 40 min.","Assaggiare, regolare di sale e pepe, prolungare la cottura di qualche minuto se necessario e servire."]}}'::jsonb),
  ('a317f775-694d-4e3d-80c1-cdd2f0e6368a'::uuid, '{"en":{"title":"Tarragon chicken","steps":["Finely chop the garlic and shallots and cut each chicken leg in half.","Heat the oil in a sauté pan, melt the butter in it and brown the chicken on all sides over medium heat.","Add the garlic, shallots and tarragon, then deglaze with the white wine.","Season with salt and pepper, cover and simmer for about 20 min, stirring from time to time.","Remove the chicken, stir the crème fraîche into the sauce and heat gently until it just starts to simmer.","Return the chicken to the tarragon sauce and serve."]},"it":{"title":"Pollo al dragoncello","steps":["Tritare finemente l''aglio e gli scalogni e tagliare ogni coscia a metà.","Scaldare l''olio in una padella dai bordi alti, farvi sciogliere il burro e rosolare il pollo a fuoco medio su tutti i lati.","Aggiungere aglio, scalogni e dragoncello, poi sfumare con il vino bianco.","Salare, pepare, coprire e cuocere a fuoco lento per circa 20 min, mescolando di tanto in tanto.","Togliere il pollo, incorporare la panna alla salsa e scaldare dolcemente fino al primo bollore.","Rimettere il pollo nella salsa al dragoncello e servire."]}}'::jsonb),
  ('c0a07491-dc99-4dc0-8895-b6358173175c'::uuid, '{"en":{"title":"Pork roast with milk and mustard","steps":["Preheat the oven to 150 °C.","Peel the garlic and remove the green germ, then put it in a saucepan with the milk, bay leaf, mustard and stock; season with salt and pepper and stir.","Bring to the boil, then simmer very gently for about 15 min.","Sear the roast over high heat on all sides in the oil, in an ovenproof casserole dish, then discard the fat.","Pour the infused milk over the meat, cover and bake for 1 hr 30 min.","Slice the roast and serve it with the sauce spooned over."]},"it":{"title":"Arrosto di maiale al latte e senape","steps":["Preriscaldare il forno a 150 °C.","Sbucciare l''aglio ed eliminare l''anima, poi metterlo in una casseruola con il latte, l''alloro, la senape e il brodo; salare, pepare e mescolare.","Portare a ebollizione, poi lasciar sobbollire molto dolcemente per circa 15 min.","Rosolare l''arrosto a fuoco vivace su tutti i lati nell''olio, in una casseruola adatta al forno, poi eliminare il grasso.","Versare il latte aromatizzato sulla carne, coprire e infornare per 1 ora e 30 min.","Affettare l''arrosto e servirlo irrorato con la salsa."]}}'::jsonb),
  ('8e07faeb-77dd-4637-ac75-c74706aeb411'::uuid, '{"en":{"title":"Roast salmon with green lentils","steps":["Peel the carrots and dice them; peel the garlic and onion, then stud the onion with the clove.","Tie the bouquet garni herbs together with string.","Put the rinsed lentils in a saucepan of cold water with the carrots, onion, garlic, the piece of bacon and the bouquet garni.","Bring to the boil, then simmer for 30 minutes half-covered, adding salt halfway through cooking.","About 10 minutes before the end, put the salmon fillets under the oven grill, skin side towards the heat.","Drain the lentils, removing the onion and the bouquet garni; dice the bacon and brown it in half the oil.","Add the lentils to the bacon, mix and keep warm.","Remove the skin from the salmon, season with salt and pepper, drizzle with the remaining oil and serve on the lentils."]},"it":{"title":"Salmone arrosto con lenticchie verdi","steps":["Pelare le carote e tagliarle a dadini; sbucciare l''aglio e la cipolla, poi steccare la cipolla con il chiodo di garofano.","Legare con lo spago le erbe del bouquet garni.","Mettere le lenticchie sciacquate in una casseruola di acqua fredda con le carote, la cipolla, l''aglio, il pezzo di pancetta e il bouquet garni.","Portare a ebollizione, poi lasciar sobbollire per 30 minuti con il coperchio socchiuso, salando a metà cottura.","Circa 10 minuti prima della fine, passare i tranci di salmone sotto il grill del forno, con la pelle rivolta verso il calore.","Scolare le lenticchie eliminando la cipolla e il bouquet garni; tagliare la pancetta a dadini e farla dorare in metà dell''olio.","Aggiungere le lenticchie alla pancetta, mescolare e tenere in caldo.","Togliere la pelle al salmone, salare, pepare, irrorare con l''olio rimasto e servire sulle lenticchie."]}}'::jsonb),
  ('419c8ae2-41ee-4db8-afd8-c6f6ff0e11be'::uuid, '{"en":{"title":"Troisgros brothers'' salmon with sorrel","steps":["Remove the pin bones from the salmon with tweezers, then cut it into thin escalopes of about 140 g.","Lightly flatten the escalopes between two sheets of oiled baking paper to get an even thickness.","Strip the sorrel, removing the stems and ribs, rinse it and tear the large leaves.","In a sauté pan, combine the finely chopped shallot, the fish stock, the wine and the vermouth, then reduce until syrupy.","Add the cream and simmer until the sauce lightly coats a spoon.","Plunge the sorrel in for 10 seconds, swirling the pan without whisking, then season with a few drops of lemon and some salt.","Sear the salted escalopes in a very hot non-stick frying pan, about 10 seconds per side, leaving them barely cooked.","Spoon the sauce onto warm plates, lay the salmon on top and serve immediately."]},"it":{"title":"Salmone all''acetosa dei fratelli Troisgros","steps":["Eliminare le spine del salmone con una pinzetta, poi tagliarlo in sottili scaloppe di circa 140 g.","Appiattire leggermente le scaloppe tra due fogli di carta forno unti d''olio per ottenere uno spessore uniforme.","Sfogliare l''acetosa eliminando gambi e nervature, sciacquarla e spezzettare le foglie grandi.","In una padella dai bordi alti, riunire lo scalogno tritato finemente, il fumetto, il vino e il vermouth, poi far ridurre fino a ottenere un liquido sciropposo.","Aggiungere la panna e lasciar sobbollire finché la salsa vela leggermente il cucchiaio.","Immergere l''acetosa per 10 secondi muovendo la padella senza sbattere, poi condire con qualche goccia di limone e il sale.","Scottare le scaloppe salate in una padella antiaderente molto calda, circa 10 secondi per lato, lasciandole appena cotte.","Velare di salsa dei piatti caldi, adagiarvi sopra il salmone e servire subito."]}}'::jsonb),
  ('df8c039d-295f-4d5a-b25a-7f45780c4209'::uuid, '{"en":{"title":"Turbot with sauce vierge","steps":["Preheat the oven to 175 °C (350 °F).","Season the fish with salt and pepper and place it in a dish or on a baking tray lined with baking paper.","Bake for 10 to 15 minutes depending on the thickness of the fillets.","Meanwhile, mix the diced tomato, olive oil, capers, vinegar and herbs, then season with salt and pepper; add a little sugar if the tomatoes lack flavour.","Take the fish out and serve it straight away topped with the sauce vierge, with rice or mash and a vegetable."]},"it":{"title":"Rombo con salsa vierge","steps":["Preriscaldare il forno a 175 °C (350 °F).","Salare e pepare il pesce e disporlo in una pirofila o su una teglia rivestita di carta forno.","Infornare per 10-15 minuti a seconda dello spessore dei filetti.","Nel frattempo, mescolare i dadini di pomodoro, l''olio d''oliva, i capperi, l''aceto e le erbe, poi salare e pepare; aggiungere un po'' di zucchero se i pomodori sono poco saporiti.","Sfornare il pesce e servirlo subito coperto di salsa vierge, con riso o purè e una verdura."]}}'::jsonb),
  ('caa6c099-644e-4533-b07e-55ea51423d4c'::uuid, '{"en":{"title":"Poached eggs with spinach and lentils","steps":["In a large frying pan, sauté the onion, garlic and ginger in the oil for about 3 minutes.","Add the garam masala and turmeric and stir for 30 seconds.","Add the grated tomato, the lentils and half the spinach, cover and cook for about 5 minutes until the spinach wilts.","Uncover, add the rest of the spinach, let it wilt, then season with salt and pepper.","Make hollows in the mixture and crack the eggs into them.","Cover and simmer for 5 to 6 minutes, until the whites are set.","Sprinkle with feta, add a dash of sriracha and serve."]},"it":{"title":"Uova in camicia con spinaci e lenticchie","steps":["In una padella grande, soffriggere la cipolla, l''aglio e lo zenzero nell''olio per circa 3 minuti.","Aggiungere il garam masala e la curcuma e mescolare per 30 secondi.","Aggiungere il pomodoro grattugiato, le lenticchie e metà degli spinaci, coprire e cuocere per circa 5 minuti, finché gli spinaci appassiscono.","Togliere il coperchio, aggiungere il resto degli spinaci, lasciarli appassire, poi salare e pepare.","Formare delle conche nel composto e rompervi dentro le uova.","Coprire e cuocere a fuoco lento per 5-6 minuti, finché gli albumi sono rappresi.","Cospargere di feta, aggiungere un goccio di sriracha e servire."]}}'::jsonb),
  ('5a5c66cd-2943-431e-8885-d31eebc8d30e'::uuid, '{"fr":{"title":"Bols de riz au bœuf bulgogi","steps":["Émincer le bœuf très finement et le mettre dans un saladier.","Mixer la poire, l''oignon, l''ail de la marinade, le gingembre, la sauce soja, le sucre roux, le poivre et l''huile de sésame jusqu''à obtenir une purée lisse.","Verser la purée sur le bœuf, ajouter la moitié de l''oignon nouveau et la carotte, mélanger et réfrigérer au moins 1 heure (idéalement toute une nuit).","Cuire le riz.","Faire chauffer une poêle en fonte à feu vif et saisir le bœuf en plusieurs fois avec un peu d''huile, 1 à 2 minutes jusqu''à ce qu''il caramélise, en le retournant une fois ; gratter la poêle pour la nettoyer entre chaque fournée.","Répartir le riz dans des bols et garnir de bœuf, de kimchi, d''ail cru émincé, de piments shishito et du reste d''oignon nouveau.","Parsemer de graines de sésame et servir avec le ssamjang à part."]},"it":{"title":"Ciotole di riso con manzo bulgogi","steps":["Affettare il manzo molto sottile e metterlo in una ciotola.","Frullare la pera, la cipolla, l''aglio per la marinata, lo zenzero, la salsa di soia, lo zucchero di canna, il pepe e l''olio di sesamo fino a ottenere una purea liscia.","Versare la purea sul manzo, aggiungere metà del cipollotto e la carota, mescolare e mettere in frigorifero per almeno 1 ora (meglio tutta la notte).","Cuocere il riso.","Scaldare una padella di ghisa a fuoco vivace e scottare il manzo poco alla volta con un filo d''olio, 1–2 minuti finché è caramellato, girandolo una volta; raschiare e pulire la padella tra una porzione e l''altra.","Riempire le ciotole con il riso e completare con il manzo, il kimchi, l''aglio crudo affettato, i peperoni shishito e il cipollotto rimasto.","Finire con i semi di sesamo e servire con il ssamjang a parte."]}}'::jsonb),
  ('39fd3a34-7eb2-497f-8ff1-3d247f845ea0'::uuid, '{"fr":{"title":"Rendang de bœuf","steps":["Mixer au robot les piments, l''oignon, l''ail, la citronnelle émincée, le galanga, le gingembre et l''huile de la pâte jusqu''à obtenir une pâte très fine.","Faire chauffer l''huile de saisie dans une cocotte à fond épais à feu vif et saisir le bœuf en plusieurs fois ; réserver.","Baisser à feu moyen-doux et faire revenir la pâte d''épices 2 à 3 minutes jusqu''à ce qu''elle fonce.","Remettre le bœuf avec tous les autres ingrédients du curry, porter à frémissement puis baisser le feu pour obtenir un très léger bouillonnement.","Couvrir et cuire 1 heure 15 minutes, puis vérifier le bœuf.","Découvrir, monter à feu moyen et cuire 30 à 40 minutes en remuant souvent, jusqu''à ce que l''huile se sépare et que la sauce réduise en une pâte sombre qui enrobe le bœuf (ajouter un peu d''eau et poursuivre si la viande n''est pas encore tendre).","Servir avec du riz vapeur."]},"it":{"title":"Rendang di manzo","steps":["Frullare nel mixer i peperoncini, la cipolla, l''aglio, la citronella affettata, il galanga, lo zenzero e l''olio per la pasta fino a ottenere un composto finissimo.","Scaldare l''olio per rosolare in una pentola dal fondo spesso a fuoco vivace e rosolare il manzo poco alla volta; tenere da parte.","Abbassare a fuoco medio-basso e soffriggere la pasta di spezie per 2–3 minuti, finché si scurisce.","Rimettere il manzo con tutti gli altri ingredienti del curry, portare a leggero bollore e abbassare la fiamma fino a un bollore leggerissimo.","Coprire e cuocere per 1 ora e 15 minuti, poi controllare il manzo.","Scoprire, alzare a fuoco medio e cuocere per 30–40 minuti mescolando spesso, finché l''olio si separa e la salsa si riduce a una pasta scura che avvolge la carne (aggiungere un goccio d''acqua e continuare se la carne non è ancora tenera).","Servire con riso al vapore."]}}'::jsonb),
  ('48233154-365a-485a-b65e-f5d981d9d5f7'::uuid, '{"fr":{"title":"Bibimbap au bœuf coréen","steps":["Mélanger le gochujang, le mirin, le vinaigre de riz, la sauce soja, le sucre, l''ail râpé et l''huile de sésame jusqu''à dissolution du sucre.","Mélanger la pomme râpée, l''ail, le gingembre, la sauce soja, le miel et l''huile de sésame, ajouter le bœuf et laisser mariner 30 minutes (ou jusqu''au lendemain).","Faire tremper les shiitakés séchés 30 minutes dans de l''eau bouillante, puis les essorer et les émincer ; cuire le riz.","Faire sauter successivement les shiitakés, la carotte, la courgette et les épinards dans un peu d''huile, en assaisonnant légèrement chacun de sel, d''ail, de sauce soja et de sucre.","Blanchir les pousses de soja, les égoutter et les laisser refroidir, puis les assaisonner d''huile de sésame, d''un peu d''ail et de la sauce poisson.","Égoutter le bœuf et le saisir 3 à 4 minutes dans une poêle très chaude avec un peu d''huile ; réserver au chaud.","Cuire les œufs au plat selon les goûts.","Répartir le riz chaud dans des bols, disposer les légumes et le bœuf par-dessus, ajouter l''œuf, parsemer de graines de sésame, arroser d''un filet d''huile de sésame et servir avec la sauce à mélanger."]},"it":{"title":"Bibimbap con manzo alla coreana","steps":["Mescolare il gochujang, il mirin, l''aceto di riso, la salsa di soia, lo zucchero, l''aglio grattugiato e l''olio di sesamo finché lo zucchero si scioglie.","Mescolare la mela grattugiata, l''aglio, lo zenzero, la salsa di soia, il miele e l''olio di sesamo, aggiungere il manzo e lasciar marinare per 30 minuti (o fino al giorno dopo).","Mettere in ammollo gli shiitake secchi in acqua bollente per 30 minuti, poi strizzarli e affettarli; cuocere il riso.","Saltare in padella uno dopo l''altro gli shiitake, la carota, la zucchina e gli spinaci con un filo d''olio, condendo ciascuno leggermente con sale, aglio, salsa di soia e zucchero.","Sbollentare i germogli di soia, scolarli e farli raffreddare, poi condirli con olio di sesamo, un po'' d''aglio e la salsa di pesce.","Scolare il manzo e scottarlo in una padella molto calda con un filo d''olio per 3–4 minuti; tenere in caldo.","Cuocere le uova al tegamino a piacere.","Riempire le ciotole con il riso caldo, disporvi sopra le verdure e il manzo, aggiungere l''uovo, cospargere di semi di sesamo e di un filo d''olio di sesamo e servire con la salsa da mescolare."]}}'::jsonb),
  ('df078eb0-325b-4dde-897e-a5fdefb5ec92'::uuid, '{"fr":{"title":"Poisson vapeur cantonais au gingembre et à l''oignon nouveau","steps":["Tailler les oignons nouveaux et le gingembre en julienne et hacher grossièrement la coriandre ; en réserver environ un tiers pour la garniture.","Mélanger la sauce soja, le sel et le sucre dans 2 c. à soupe d''eau chaude jusqu''à dissolution.","Porter à ébullition 2 à 5 cm d''eau dans un cuit-vapeur (un wok avec une grille et un couvercle fait l''affaire).","Déposer le filet rincé sur une assiette résistant à la chaleur, la placer dans le cuit-vapeur, couvrir et cuire à la vapeur à feu moyen 7 à 10 minutes (4 à 5 pour des filets fins), jusqu''à ce qu''un couteau traverse facilement la partie la plus épaisse.","Jeter le liquide de l''assiette et parsemer le poisson des aromates réservés.","Faire chauffer l''huile dans une petite poêle, faire revenir le reste du gingembre environ 1 minute, ajouter le blanc des oignons nouveaux 30 secondes, puis le vert et la coriandre.","Ajouter le mélange à la sauce soja, laisser bouillonner environ 30 secondes jusqu''à ce que les herbes commencent tout juste à flétrir, puis verser sur le poisson et servir avec du riz vapeur."]},"it":{"title":"Pesce al vapore alla cantonese con zenzero e cipollotto","steps":["Tagliare a julienne i cipollotti e lo zenzero e tritare grossolanamente il coriandolo; tenerne da parte circa un terzo per guarnire.","Sciogliere la salsa di soia, il sale e lo zucchero in 2 cucchiai di acqua calda.","Portare a ebollizione 2–5 cm d''acqua in una vaporiera (va bene anche un wok con griglia e coperchio).","Mettere il filetto sciacquato su un piatto resistente al calore, sistemarlo nella vaporiera, coprire e cuocere a vapore a fuoco medio per 7–10 minuti (4–5 per filetti sottili), finché un coltello affonda facilmente nella parte più spessa.","Eliminare il liquido nel piatto e distribuire sul pesce gli aromi tenuti da parte.","Scaldare l''olio in un padellino, friggere lo zenzero rimasto per circa 1 minuto, aggiungere la parte bianca dei cipollotti per 30 secondi, poi la parte verde e il coriandolo.","Aggiungere il composto di soia, lasciar bollire per circa 30 secondi finché le erbe appassiscono appena, poi versarlo sul pesce e servire con riso al vapore."]}}'::jsonb),
  ('a7ed4529-c101-447e-8900-f9b038ec9bf2'::uuid, '{"fr":{"title":"Larb de poulet en feuilles de laitue","steps":["Faire griller le riz cru dans un wok à sec à feu doux environ 10 minutes jusqu''à ce qu''il soit doré et parfumé, puis le moudre en poudre grossière.","Faire chauffer l''huile dans le wok à feu vif et faire frire la moitié des échalotes jusqu''à ce qu''elles soient croustillantes ; les retirer en gardant l''huile dans le wok.","Faire chauffer de nouveau le wok jusqu''à ce qu''il fume, ajouter le poulet haché et le faire sauter jusqu''à ce qu''il soit doré et légèrement croustillant.","Assaisonner avec le sucre, la sauce poisson et le jus de citron vert.","Incorporer la poudre de riz grillé, le piment, le reste des échalotes crues, l''oignon nouveau, la coriandre et la menthe, et faire sauter environ une minute.","Goûter et équilibrer avec du sel, du piment, de la sauce poisson ou du citron vert selon les besoins.","Répartir à la cuillère dans les feuilles de laitue et parsemer d''échalotes croustillantes."]},"it":{"title":"Larb di pollo in coppette di lattuga","steps":["Tostare il riso crudo in un wok asciutto a fuoco basso per circa 10 minuti, finché è dorato e profumato, poi macinarlo in una polvere grossolana.","Scaldare l''olio nel wok a fuoco vivace e friggere metà degli scalogni finché sono croccanti; toglierli e lasciare l''olio nel wok.","Riscaldare il wok finché fuma, aggiungere il pollo macinato e saltarlo finché è rosolato e leggermente croccante.","Condire con lo zucchero, la salsa di pesce e il succo di lime.","Incorporare la polvere di riso tostato, il peperoncino, gli scalogni crudi rimasti, il cipollotto, il coriandolo e la menta e saltare per circa un minuto.","Assaggiare e bilanciare con sale, peperoncino, salsa di pesce o lime secondo necessità.","Distribuire con un cucchiaio nelle foglie di lattuga e cospargere con gli scalogni croccanti."]}}'::jsonb),
  ('79682a8a-d507-4826-91a4-133add95113d'::uuid, '{"fr":{"title":"Bœuf aux brocolis à la chinoise","steps":["Délayer la fécule de maïs dans un peu d''eau jusqu''à ce qu''elle soit lisse, puis incorporer le sucre, les deux sauces soja, le vin de riz, le cinq-épices, l''huile de sésame et le poivre.","Émincer finement le bœuf et le mélanger avec environ 1,5 c. à soupe de sauce.","Faire chauffer l''huile dans une poêle ou un wok à feu vif, étaler le bœuf et le laisser dorer sans y toucher environ 1 minute.","Remuer le bœuf, ajouter l''ail et le gingembre et faire sauter jusqu''à ce que la viande ne soit plus rosée.","Verser le reste de la sauce et environ 170 ml d''eau, et remuer rapidement.","Dès que ça bouillonne, ajouter les brocolis cuits, bien les enrober de sauce et laisser mijoter environ 1 minute jusqu''à ce que la sauce soit brillante et épaisse.","Retirer du feu et servir sur du riz, parsemé de graines de sésame."]},"it":{"title":"Manzo e broccoli alla cinese","steps":["Stemperare l''amido di mais in poca acqua fino a renderlo liscio, poi unire lo zucchero, le due salse di soia, il vino di riso, le cinque spezie, l''olio di sesamo e il pepe.","Affettare sottilmente il manzo e mescolarlo con circa 1,5 cucchiai di salsa.","Scaldare l''olio in una padella o nel wok a fuoco vivace, distribuire il manzo e lasciarlo rosolare senza toccarlo per circa 1 minuto.","Mescolare il manzo, aggiungere l''aglio e lo zenzero e saltare finché la carne non è più rosa.","Versare il resto della salsa e circa 170 ml d''acqua e mescolare rapidamente.","Quando bolle, aggiungere i broccoli cotti, ricoprirli di salsa e cuocere a fuoco lento per circa 1 minuto, finché la salsa è lucida e densa.","Togliere dal fuoco e servire sul riso, cospargendo di semi di sesamo."]}}'::jsonb),
  ('28d94d63-942b-407b-b0b5-b31c5de37faa'::uuid, '{"fr":{"title":"Poulet aux noix de cajou à la chinoise","steps":["Délayer au fouet la fécule de maïs dans la sauce soja jusqu''à ce qu''elle soit lisse, puis ajouter le vin de riz, la sauce d''huître, l''huile de sésame et le poivre blanc.","Mélanger le poulet avec environ 1 c. à soupe de sauce et laisser reposer au moins 10 minutes.","Faire chauffer l''huile dans un wok à feu vif et faire sauter l''ail et l''oignon environ 1 minute.","Ajouter le poulet et cuire environ 2 minutes, puis ajouter le poivron et cuire encore une minute.","Verser le reste de la sauce avec environ 3 c. à soupe d''eau et remuer environ 1 minute jusqu''à ce qu''elle frémisse et épaississe.","Ajouter les noix de cajou, mélanger, retirer du feu et servir aussitôt avec du riz."]},"it":{"title":"Pollo agli anacardi alla cinese","steps":["Sbattere con una frusta l''amido di mais nella salsa di soia fino a renderlo liscio, poi aggiungere il vino di riso, la salsa di ostriche, l''olio di sesamo e il pepe bianco.","Mescolare il pollo con circa 1 cucchiaio di salsa e lasciar riposare almeno 10 minuti.","Scaldare l''olio nel wok a fuoco vivace e saltare l''aglio e la cipolla per circa 1 minuto.","Aggiungere il pollo e cuocere per circa 2 minuti, poi aggiungere il peperone per un altro minuto.","Versare la salsa rimasta con circa 3 cucchiai d''acqua e mescolare per circa 1 minuto, finché sobbolle e si addensa.","Unire gli anacardi, mescolare, togliere dal fuoco e servire subito con il riso."]}}'::jsonb),
  ('00396751-d223-4187-b0ba-b2793c5f3b91'::uuid, '{"fr":{"title":"Saumon au gingembre et oignon nouveau croustillants","steps":["Faire chauffer une poêle à feu moyen-vif avec la moitié de l''huile et y déposer le saumon côté peau.","Le laisser saisir sans y toucher, 4 à 7 minutes par face selon l''épaisseur, jusqu''à ce que le centre ne soit plus cru ; le retirer.","Mélanger la sauce soja, le sucre, l''huile de sésame et le sel avec environ 60 ml d''eau.","Ajouter le reste de l''huile dans la même poêle et faire frire le gingembre jusqu''à ce qu''il soit croustillant, puis ajouter l''oignon nouveau et le laisser flétrir.","Verser le mélange à la sauce soja, porter à ébullition et éteindre le feu.","Servir le saumon sur du riz, le napper de sauce au gingembre et à l''oignon nouveau et parsemer de coriandre."]},"it":{"title":"Salmone con zenzero e cipollotto croccanti","steps":["Scaldare una padella a fuoco medio-alto con metà dell''olio e adagiarvi il salmone dal lato della pelle.","Lasciarlo rosolare senza toccarlo, 4–7 minuti per lato a seconda dello spessore, finché il centro non è più crudo; toglierlo.","Mescolare la salsa di soia, lo zucchero, l''olio di sesamo e il sale con circa 60 ml d''acqua.","Aggiungere l''olio rimasto nella stessa padella e friggere lo zenzero finché è croccante, poi aggiungere il cipollotto e farlo appassire.","Versare il composto di soia, portare a ebollizione e spegnere il fuoco.","Servire il salmone sul riso, irrorandolo con la salsa allo zenzero e cipollotto e cospargendo di coriandolo."]}}'::jsonb),
  ('2d025e3c-c006-4ef1-873b-677587924532'::uuid, '{"fr":{"title":"Cá kho (maquereau braisé au caramel à la vietnamienne)","steps":["Couper le maquereau en tranches épaisses d''environ 4 cm en jetant les têtes ; frotter de sel, rincer et sécher en tamponnant.","Faire fondre le sucre avec un peu d''eau dans une petite casserole et laisser bouillonner, puis baisser le feu et cuire jusqu''à obtenir un caramel foncé.","Retirer le caramel du feu et y incorporer prudemment environ 140 ml d''eau pour obtenir un liquide de braisage ambré foncé.","Tapisser le fond d''une cocotte à fond épais de galanga, d''échalote et de la majeure partie de la tomate, poser le poisson dessus en une seule couche et répartir le reste des aromates, de la tomate et le piment.","Ajouter la sauce poisson, la sauce soja, le caramel et le poivre noir ; compléter avec un peu d''eau pour que le poisson soit tout juste couvert.","Porter à ébullition, ajouter le jus de citron vert, puis couvrir et laisser mijoter doucement environ 1 heure et demie, en arrosant le poisson de temps en temps (ajouter de l''eau chaude si ça accroche).","Découvrir, goûter et poursuivre le braisage couvercle entrouvert jusqu''à ce qu''il ne reste qu''une fine couche de sauce brillante au fond de la cocotte.","Servir avec du riz vapeur."]},"it":{"title":"Cá kho (sgombro brasato al caramello alla vietnamita)","steps":["Tagliare lo sgombro in tranci spessi circa 4 cm, eliminando le teste; strofinarli con il sale, sciacquarli e tamponarli.","Sciogliere lo zucchero con un goccio d''acqua in un pentolino e lasciarlo bollire, poi abbassare la fiamma e cuocere finché diventa un caramello scuro.","Togliere il caramello dal fuoco e incorporare con cautela circa 140 ml d''acqua per ottenere un liquido di cottura ambrato scuro.","Foderare il fondo di una pentola dal fondo spesso con galanga, scalogno e gran parte del pomodoro, adagiarvi sopra il pesce in un solo strato e distribuire il resto degli aromi, del pomodoro e il peperoncino.","Aggiungere la salsa di pesce, la salsa di soia, il caramello e il pepe nero; aggiungere un po'' d''acqua in modo che il pesce sia appena coperto.","Portare a ebollizione, aggiungere il succo di lime, poi coprire e cuocere a fuoco lento per circa 1 ora e mezza, bagnando il pesce di tanto in tanto (aggiungere acqua calda se si asciuga).","Scoprire, assaggiare e continuare la cottura con il coperchio socchiuso finché resta solo un velo di salsa lucida sul fondo della pentola.","Servire con riso al vapore."]}}'::jsonb),
  ('cb707aa6-b026-4732-a344-0eb8ba339d56'::uuid, '{"fr":{"title":"Dak galbi (poulet sauté épicé)","steps":["Si les gâteaux de riz sont achetés emballés, les séparer et les faire tremper 10 minutes dans de l''eau tiède.","Mélanger le gochujang, le vin de riz, le gochugaru, la sauce soja, le sucre, l''ail, le gingembre, le curry en poudre, l''oignon râpé et un peu de poivre.","Enrober le poulet de marinade et laisser reposer au moins 30 minutes (jusqu''au lendemain pour plus de saveur).","Faire chauffer l''huile dans une grande poêle à feu moyen-vif et étaler la patate douce, la carotte, le chou, les feuilles de périlla et les gâteaux de riz, avec le poulet par-dessus.","Cuire 3 à 4 minutes, puis baisser à feu moyen/moyen-doux et poursuivre la cuisson 10 à 15 minutes en remuant souvent, jusqu''à ce que le poulet et la patate douce soient bien cuits (un couvercle accélère la cuisson).","Servir chaud avec du riz."]},"it":{"title":"Dak galbi (pollo saltato piccante)","steps":["Se gli gnocchi di riso sono confezionati, separarli e metterli in ammollo in acqua tiepida per 10 minuti.","Mescolare il gochujang, il vino di riso, il gochugaru, la salsa di soia, lo zucchero, l''aglio, lo zenzero, il curry in polvere, la cipolla grattugiata e un po'' di pepe.","Ricoprire il pollo con la marinata e lasciar riposare almeno 30 minuti (fino al giorno dopo per più sapore).","Scaldare l''olio in una padella grande a fuoco medio-alto e distribuire la patata dolce, la carota, il cavolo, le foglie di perilla e gli gnocchi di riso, con il pollo sopra.","Cuocere per 3–4 minuti, poi abbassare a fuoco medio/medio-basso e continuare la cottura per 10–15 minuti mescolando spesso, finché il pollo e la patata dolce sono ben cotti (con un coperchio si fa prima).","Servire caldo con il riso."]}}'::jsonb),
  ('7604daa9-9518-4943-8ab8-875c445fe5b9'::uuid, '{"fr":{"title":"Adobo de poulet philippin","steps":["Écraser l''ail au mortier, puis le mélanger avec le poulet et la sauce soja et laisser mariner au moins 1 heure.","Retirer le poulet en réservant séparément la marinade et l''ail.","Faire chauffer la majeure partie de l''huile dans une cocotte et saisir le poulet environ 2 minutes par face ; réserver.","Ajouter le reste de l''huile et l''ail mariné et le faire revenir jusqu''à ce qu''il commence tout juste à colorer.","Remettre le poulet avec le reste de la marinade, les grains de poivre, les feuilles de laurier et environ 180 ml d''eau ; porter à ébullition, couvrir et laisser mijoter environ 30 minutes jusqu''à ce qu''il soit tendre.","Verser le vinaigre et laisser bouillir 1 minute sans remuer, puis remuer et laisser mijoter 15 minutes à découvert pour réduire.","Assaisonner avec le sucre et le sel et servir chaud avec du riz."]},"it":{"title":"Adobo di pollo alla filippina","steps":["Schiacciare l''aglio nel mortaio, poi unirlo al pollo e alla salsa di soia e lasciar marinare per almeno 1 ora.","Togliere il pollo, tenendo da parte separatamente la marinata e l''aglio.","Scaldare la maggior parte dell''olio in una pentola e rosolare il pollo per circa 2 minuti per lato; tenere da parte.","Aggiungere il resto dell''olio e l''aglio marinato e soffriggere finché inizia appena a colorirsi.","Rimettere il pollo con la marinata rimasta, i grani di pepe, le foglie di alloro e circa 180 ml d''acqua; portare a ebollizione, coprire e cuocere a fuoco lento per circa 30 minuti, finché è tenero.","Versare l''aceto e lasciar bollire per 1 minuto senza mescolare, poi mescolare e cuocere a fuoco lento senza coperchio per 15 minuti per far ridurre.","Insaporire con zucchero e sale e servire caldo con il riso."]}}'::jsonb),
  ('f6b65e75-59a5-479d-908f-dcb0781077a6'::uuid, '{"fr":{"title":"Curry de poisson façon Goa","steps":["Mixer la majeure partie de la coriandre avec le gingembre, le piment, l''ail, l''oignon nouveau haché, la moitié du jus de citron, le curry en poudre prévu pour la pâte, une pincée de sel et la moitié du lait de coco jusqu''à obtenir une pâte lisse.","Faire cuire la pâte quelques minutes dans une sauteuse profonde jusqu''à ce qu''elle embaume, puis ajouter le reste du lait de coco et laisser mijoter jusqu''à ce que la sauce épaississe légèrement.","Rincer le riz et le faire cuire à frémissement, à couvert, dans de l''eau jusqu''à ce qu''il soit tendre et que le liquide soit absorbé ; garder à couvert.","Couper le poisson en lanières et l''enrober de farine assaisonnée de sel et du reste de curry en poudre.","Faire frire le poisson à la poêle dans l''huile jusqu''à ce qu''il soit doré et tout juste cuit à cœur.","Rectifier l''assaisonnement de la sauce, ajouter le jus de citron selon le goût, y glisser le poisson pour le réchauffer et servir avec le riz, l''oignon nouveau émincé finement et le reste de la coriandre."]},"it":{"title":"Curry di pesce in stile Goa","steps":["Frullare gran parte del coriandolo con lo zenzero, il peperoncino, l''aglio, il cipollotto tritato, metà del succo di limone, il curry in polvere per la pasta, un pizzico di sale e metà del latte di cocco fino a ottenere un composto liscio.","Cuocere la pasta in una padella profonda per qualche minuto finché non sprigiona il suo aroma, poi aggiungere il resto del latte di cocco e cuocere a fuoco lento finché non si addensa leggermente.","Sciacquare il riso e cuocerlo a fuoco lento, coperto, in acqua finché non è tenero e ha assorbito il liquido; tenere coperto.","Tagliare il pesce a listarelle e passarlo nella farina condita con sale e il curry in polvere rimasto.","Friggere il pesce in padella nell''olio finché non è dorato e appena cotto all''interno.","Regolare di sapore la salsa, aggiungere il succo di limone a piacere, unire il pesce per scaldarlo e servire con il riso, il cipollotto a julienne e il coriandolo rimasto."]}}'::jsonb),
  ('25a49043-ae42-4755-8b99-fe6b204a5964'::uuid, '{"fr":{"title":"Gyudon (bol de riz au bœuf et aux oignons)","steps":["Faire cuire le riz.","Faire chauffer la moitié de l''huile dans une poêle à feu moyen-vif et faire cuire les oignons environ 10 minutes en remuant souvent, jusqu''à ce qu''ils soient tendres.","Ajouter le bœuf et le sucre et remuer jusqu''à ce que le bœuf soit légèrement doré.","Verser le mirin, la sauce soja et le dashi et laisser mijoter 10–15 minutes jusqu''à obtenir une sauce légère ; goûter et rectifier.","Pendant ce temps, faire cuire les œufs au plat dans une autre poêle avec le reste de l''huile, en gardant les jaunes coulants.","Répartir le riz dans des bols, y disposer le bœuf et les oignons avec un peu de sauce, déposer un œuf sur chaque bol et parsemer d''oignon nouveau et de graines de sésame."]},"it":{"title":"Gyudon (ciotola di riso con manzo e cipolle)","steps":["Cuocere il riso.","Scaldare metà dell''olio in una padella a fuoco medio-alto e cuocere le cipolle per circa 10 minuti, mescolando spesso, finché non sono morbide.","Aggiungere il manzo e lo zucchero e mescolare finché la carne non è leggermente rosolata.","Versare il mirin, la salsa di soia e il dashi e cuocere a fuoco lento per 10–15 minuti finché non si riduce a una salsa leggera; assaggiare e regolare.","Nel frattempo cuocere le uova all''occhio di bue in un''altra padella con l''olio rimasto, lasciando i tuorli morbidi.","Distribuire il riso nelle ciotole, adagiarvi sopra il manzo e le cipolle con un po'' di salsa, completare ciascuna con un uovo e finire con cipollotto e semi di sesamo."]}}'::jsonb),
  ('63ace58e-5c2b-45c1-9b70-599b42c3908e'::uuid, '{"fr":{"title":"Gà nướng sả (poulet grillé vietnamien à la citronnelle)","steps":["Fouetter ensemble tous les ingrédients de la marinade dans un bol.","Bien enrober le poulet et le laisser au réfrigérateur au moins 3 heures, idéalement toute une nuit.","Faire chauffer le barbecue (ou une poêle-gril) à environ 200 °C.","Faire griller le poulet en le retournant de temps en temps, jusqu''à ce qu''il soit bien grillé des deux côtés et atteigne 74 °C dans la partie la plus épaisse.","Laisser reposer 5 minutes, puis trancher.","Servir chaud avec du riz ou des vermicelles de riz."]},"it":{"title":"Gà nướng sả (pollo vietnamita alla griglia con citronella)","steps":["Sbattere insieme in una ciotola tutti gli ingredienti della marinata.","Ricoprire bene il pollo e metterlo in frigorifero per almeno 3 ore, meglio ancora per tutta la notte.","Scaldare la griglia (o una bistecchiera) a circa 200 °C.","Grigliare il pollo, girandolo di tanto in tanto, finché non è abbrustolito su entrambi i lati e raggiunge 74 °C nella parte più spessa.","Lasciare riposare per 5 minuti, poi affettare.","Servire caldo con riso o vermicelli di riso."]}}'::jsonb),
  ('60542698-8098-4b4a-9ff6-37e012332afc'::uuid, '{"fr":{"title":"Poulet tikka masala léger aux épinards","steps":["Mixer l''oignon, l''ail et le gingembre jusqu''à obtenir une pâte lisse.","Faire revenir la pâte dans la moitié de l''huile à feu moyen pendant environ 15 minutes jusqu''à ce qu''elle soit dorée et sucrée ; la retirer en raclant la poêle, puis essuyer celle-ci.","Faire dorer le poulet dans le reste de l''huile, puis incorporer les épices tikka et le piment de Cayenne.","Remettre la pâte d''oignon avec les tomates et environ 200 ml d''eau et laisser mijoter 15 minutes à découvert.","Incorporer la poudre d''amandes et les épinards et poursuivre la cuisson 10 minutes.","Saler, retirer du feu, incorporer le yaourt et la coriandre et servir avec du riz basmati complet."]},"it":{"title":"Pollo tikka masala leggero con spinaci","steps":["Frullare la cipolla, l''aglio e lo zenzero fino a ottenere una pasta liscia.","Soffriggere la pasta in metà dell''olio a fuoco medio per circa 15 minuti finché non è dorata e dolce; raccoglierla raschiando la padella e pulire la padella.","Rosolare il pollo nell''olio rimasto, poi unire le spezie tikka e il pepe di Caienna.","Rimettere la pasta di cipolla con i pomodori e circa 200 ml d''acqua e cuocere a fuoco lento senza coperchio per 15 minuti.","Unire le mandorle tritate e gli spinaci e cuocere per altri 10 minuti.","Regolare di sale, togliere dal fuoco, incorporare lo yogurt e il coriandolo e servire con riso basmati integrale."]}}'::jsonb),
  ('072df74c-2984-46e1-b4fc-241bd3c22c69'::uuid, '{"fr":{"title":"Poulet kung pao","steps":["Faire griller les cacahuètes dans le peu d''huile prévu à feu moyen, en remuant sans arrêt pendant environ 3 minutes ; retirer du feu, continuer à remuer encore une minute, puis les laisser refroidir pour qu''elles deviennent croustillantes.","Mélanger les dés de poulet avec l''huile, la fécule de maïs, le vin de riz, le sel et le poivre blanc de la marinade et laisser reposer 20 minutes.","Mélanger les deux sauces soja, le vinaigre, le sucre, la fécule de maïs et environ 1,5 c. à soupe d''eau dans un petit bol.","Faire chauffer un wok à feu très vif, ajouter les deux tiers de l''huile de friture et saisir le poulet jusqu''à ce qu''il soit doré et tout juste cuit ; le retirer.","Baisser le feu, ajouter le reste de l''huile et faire revenir l''ail, le gingembre, les piments, le poivre du Sichuan et l''oignon nouveau jusqu''à ce qu''ils embaument.","Remettre le poulet, monter à feu vif et faire sauter 1 minute.","Remuer de nouveau la sauce, la verser et faire sauter environ 1 minute jusqu''à ce qu''elle épaississe et nappe le poulet.","Incorporer les cacahuètes et servir aussitôt avec du riz."]},"it":{"title":"Pollo kung pao","steps":["Tostare le arachidi nel poco olio a fuoco medio, mescolando di continuo per circa 3 minuti; togliere dal fuoco, continuare a mescolare per un altro minuto, poi lasciarle raffreddare in modo che diventino croccanti.","Mescolare i cubetti di pollo con l''olio, l''amido di mais, il vino di riso, il sale e il pepe bianco della marinata e lasciare riposare per 20 minuti.","Mescolare in una ciotolina le due salse di soia, l''aceto, lo zucchero, l''amido di mais e circa 1,5 cucchiai d''acqua.","Scaldare bene il wok, aggiungere due terzi dell''olio per friggere e scottare il pollo finché non è dorato e appena cotto; toglierlo dal wok.","Abbassare la fiamma, aggiungere l''olio rimasto e soffriggere l''aglio, lo zenzero, i peperoncini, il pepe di Sichuan e il cipollotto finché non sprigionano il loro aroma.","Rimettere il pollo, alzare la fiamma al massimo e saltare per 1 minuto.","Mescolare di nuovo la salsa, versarla e saltare per circa 1 minuto finché non si addensa e avvolge il pollo.","Incorporare le arachidi e servire subito con il riso."]}}'::jsonb),
  ('61be8075-e45c-435e-8e16-5746e7dbddf4'::uuid, '{"fr":{"title":"Nasi goreng malaisien au poulet, crevettes et œuf","steps":["Faire sauter la pâte de nasi goreng avec le poulet et l''oignon à feu moyen pendant environ 6 minutes.","Ajouter les crevettes et les haricots verts et poursuivre la cuisson 5 minutes.","Ajouter le riz cuit et mélanger jusqu''à ce que chaque grain soit enrobé et bien chaud.","Répartir dans deux bols.","Faire cuire les œufs au plat et en déposer un sur chaque bol ; servir avec la laitue, le concombre et la tomate à côté."]},"it":{"title":"Nasi goreng malese con pollo, gamberi e uovo","steps":["Saltare la pasta per nasi goreng con il pollo e la cipolla a fuoco medio per circa 6 minuti.","Aggiungere i gamberi e i fagiolini e cuocere per altri 5 minuti.","Versare il riso cotto e mescolare finché ogni chicco non è ben condito e bollente.","Dividere in due ciotole.","Friggere le uova e adagiarne una su ciascuna ciotola; servire con lattuga, cetriolo e pomodoro a parte."]}}'::jsonb),
  ('ef7a2f1d-b2e6-44f8-b3e8-4198959fa625'::uuid, '{"fr":{"title":"Saumon au miso, riz et légumes verts","steps":["Faire cuire le riz dans de l''eau bouillante salée jusqu''à ce qu''il soit tendre, puis l''égoutter.","Fouetter le miso, le vinaigre de riz, le gingembre et l''ail avec 100 ml d''eau.","Assaisonner le saumon et le faire cuire à la poêle côté peau jusqu''à ce qu''il soit croustillant, puis le retourner.","Verser la sauce au miso dans la poêle et passer sous le gril bien chaud jusqu''à ce que la sauce bouillonne et réduise.","Pendant ce temps, faire cuire brièvement le pak choï, les pois gourmands et les mini-épis de maïs dans l''eau bouillante jusqu''à ce qu''ils soient juste tendres, puis les égoutter.","Dresser le riz et les légumes, déposer le saumon dessus, napper de sauce et parsemer d''oignon nouveau."]},"it":{"title":"Salmone al miso con riso e verdure","steps":["Lessare il riso in acqua salata finché non è tenero, poi scolarlo.","Sbattere il miso, l''aceto di riso, lo zenzero e l''aglio con 100 ml d''acqua.","Condire il salmone e cuocerlo in padella dal lato della pelle finché non è croccante, poi girarlo.","Versare la salsa al miso nella padella e passarla sotto il grill ben caldo finché la salsa non sobbolle e si riduce.","Nel frattempo lessare brevemente il pak choi, le taccole e le pannocchiette finché non sono appena tenere, poi scolarli.","Disporre nei piatti il riso e le verdure, adagiarvi sopra il salmone, irrorare con la salsa e completare con il cipollotto."]}}'::jsonb),
  ('52ce91db-4179-47c8-8c68-268c31a607be'::uuid, '{"fr":{"title":"Poulet tandoori au four","steps":["Mélanger le yaourt, la pâte gingembre-ail, les épices moulues, le sel, les feuilles de fenugrec, l''huile et le jus de citron ; goûter et rectifier le sel et le piquant.","Faire 2–3 entailles profondes dans chaque morceau de poulet, bien l''enrober de marinade et réserver au réfrigérateur 6 heures ou toute une nuit.","Sortir le poulet du réfrigérateur 20 minutes avant la cuisson et préchauffer le four à 240 °C.","Mélanger le piment en poudre et l''huile pour l''huile pimentée.","Poser une grille huilée sur une plaque tapissée de papier aluminium, y disposer le poulet en espaçant les morceaux et enfourner 15 minutes ; badigeonner avec le reste de marinade ou d''huile pimentée.","Retourner les morceaux et poursuivre la cuisson 12–15 minutes, puis badigeonner d''huile pimentée.","Placer en haut du four sous le gril pendant 3–4 minutes jusqu''à ce que le poulet soit légèrement grillé ; la partie la plus épaisse doit atteindre 75 °C.","Parsemer de coriandre et servir avec de l''oignon, du concombre et des quartiers de citron."]},"it":{"title":"Pollo tandoori al forno","steps":["Mescolare lo yogurt, la pasta di zenzero e aglio, le spezie macinate, il sale, le foglie di fieno greco, l''olio e il succo di limone; assaggiare e regolare di sale e piccantezza.","Praticare 2–3 tagli profondi in ogni pezzo di pollo, ricoprirlo bene con la marinata e lasciarlo in frigorifero per 6 ore o per tutta la notte.","Togliere il pollo dal frigorifero 20 minuti prima della cottura e preriscaldare il forno a 240 °C.","Mescolare il peperoncino in polvere e l''olio per l''olio piccante.","Sistemare una griglia unta su una teglia rivestita di carta stagnola, disporvi il pollo ben distanziato e cuocere in forno per 15 minuti; spennellare con la marinata avanzata o con l''olio piccante.","Girare i pezzi e cuocere per altri 12–15 minuti, poi spennellare con l''olio piccante.","Spostare sul ripiano più alto sotto il grill per 3–4 minuti finché non è leggermente abbrustolito; la parte più spessa deve raggiungere 75 °C.","Guarnire con il coriandolo e servire con cipolla, cetriolo e spicchi di limone."]}}'::jsonb),
  ('d5fbc6b0-5548-4b44-a525-d4671dd07f89'::uuid, '{"fr":{"title":"Oyakodon (bol de riz au poulet et à l''œuf)","steps":["Faire cuire le riz.","Couper le poulet en biais en morceaux d''environ 2,5 cm.","Porter le mirin et le saké à ébullition dans une grande poêle à feu moyen-vif, puis ajouter le dashi, la sauce soja et le sucre et porter de nouveau à ébullition.","Répartir l''oignon en une seule couche dans la poêle, disposer le poulet par-dessus, couvrir et porter de nouveau à ébullition.","Écumer la mousse et la graisse, puis laisser mijoter à feu moyen environ 10 minutes jusqu''à ce que le poulet soit cuit.","Verser lentement les œufs battus en filet sur l''ensemble, couvrir et cuire juste jusqu''à ce que l''œuf soit pris mais encore moelleux, en secouant la poêle de temps en temps.","Parsemer d''oignon nouveau, puis faire glisser le poulet, l''œuf et un peu de sauce sur les bols de riz."]},"it":{"title":"Oyakodon (ciotola di riso con pollo e uovo)","steps":["Cuocere il riso.","Tagliare il pollo in diagonale a pezzi di circa 2,5 cm.","Portare a bollore il mirin e il sakè in una padella grande a fuoco medio-alto, poi aggiungere il dashi, la salsa di soia e lo zucchero e riportare a bollore.","Distribuire la cipolla nella padella in un solo strato, adagiarvi sopra il pollo, coprire e riportare a bollore.","Eliminare la schiuma e il grasso, poi far sobbollire a fuoco medio per circa 10 minuti finché il pollo non è cotto.","Versare lentamente le uova sbattute a filo su tutto, coprire e cuocere solo finché l''uovo non si è rappreso ma è ancora morbido, scuotendo la padella di tanto in tanto.","Cospargere con il cipollotto, poi far scivolare il pollo, l''uovo e un po'' di salsa sulle ciotole di riso."]}}'::jsonb),
  ('b47b1a25-61a8-4ea7-8e06-77330e0d02d0'::uuid, '{"fr":{"title":"Pad krapow gai (poulet thaï au basilic et œuf frit)","steps":["Faire frire les œufs au wok dans l''huile de friture, en arrosant le dessus d''huile chaude au lieu de les retourner, jusqu''à ce que les bords soient croustillants ; égoutter et réserver.","Couper le poulet en bouchées ; piler grossièrement l''ail et les piments au mortier (ou les hacher) et effeuiller le basilic.","Faire chauffer le wok à feu vif avec l''huile de cuisson et faire sauter l''ail et le piment environ 20 secondes jusqu''à ce qu''ils embaument, sans les laisser brûler.","Ajouter le poulet et le faire sauter jusqu''à ce qu''il soit presque cuit, en ajoutant une goutte d''eau si le wok devient trop sec.","Assaisonner avec la sauce d''huître, les sauces soja claire et foncée et le sucre, et continuer à faire sauter environ 30 secondes.","Ajouter le basilic sacré, l''incorporer et retirer le wok du feu dès qu''il flétrit.","Servir sur du riz jasmin cuit à la vapeur, avec l''œuf frit par-dessus."]},"it":{"title":"Pad krapow gai (pollo thai al basilico con uovo fritto)","steps":["Friggere le uova nel wok con l''olio per friggere, irrorando la superficie con l''olio caldo invece di girarle, finché i bordi non sono croccanti; scolarle e tenerle da parte.","Tagliare il pollo a bocconcini; pestare grossolanamente l''aglio e i peperoncini nel mortaio (o tritarli) e staccare le foglie di basilico.","Scaldare il wok a fuoco vivo con l''olio per saltare e far saltare l''aglio e il peperoncino per circa 20 secondi finché non sprigionano il loro aroma, senza farli bruciare.","Aggiungere il pollo e saltarlo finché non è quasi cotto, aggiungendo un goccio d''acqua se il wok si asciuga troppo.","Condire con la salsa di ostriche, la salsa di soia chiara e quella scura e lo zucchero, e continuare a saltare per circa 30 secondi.","Unire il basilico sacro, mescolarlo e togliere il wok dal fuoco appena appassisce.","Servire su riso jasmine cotto al vapore con l''uovo fritto sopra."]}}'::jsonb),
  ('7b6d0406-a5ed-4bfa-839a-a993a3868f64'::uuid, '{"fr":{"title":"Pilons de poulet satay, sauce cacahuète","steps":["Pratiquer trois entailles peu profondes (environ 5 mm) sur le côté charnu de chaque pilon.","Mélanger les ingrédients de la marinade, en enrober les pilons et faire pénétrer le mélange dans les entailles ; laisser mariner 3 heures ou toute une nuit au réfrigérateur (facultatif, mais c''est meilleur).","Préchauffer le four à 200 °C (180 °C chaleur tournante) et poser une grille sur une plaque tapissée de papier aluminium.","Disposer les pilons sur la grille et répartir le reste de marinade sur le dessus en tapotant.","Enfourner 35 minutes, puis passer en position gril, puissance maximale, pendant 3–5 minutes pour faire griller la peau.","Pendant ce temps, fouetter tous les ingrédients de la sauce dans une petite casserole et laisser mijoter à feu moyen-doux environ 5 minutes en remuant, jusqu''à ce qu''elle soit fluide mais nappe la cuillère ; garder au chaud.","Servir les pilons avec du riz jasmin et la sauce cacahuète pour les tremper."]},"it":{"title":"Fusi di pollo satay con salsa di arachidi","steps":["Praticare tre tagli poco profondi (circa 5 mm) sul lato più carnoso di ogni fuso.","Mescolare gli ingredienti della marinata, ricoprire i fusi e far penetrare il composto nei tagli; marinare per 3 ore o per tutta la notte in frigorifero (facoltativo ma consigliato).","Preriscaldare il forno a 200 °C (180 °C ventilato) e sistemare una griglia su una teglia rivestita di carta stagnola.","Disporre i fusi sulla griglia e distribuire sopra la marinata rimasta.","Cuocere in forno per 35 minuti, poi passare alla funzione grill al massimo per 3–5 minuti per abbrustolire la pelle.","Nel frattempo sbattere tutti gli ingredienti della salsa in un pentolino e cuocere a fuoco medio-basso per circa 5 minuti, mescolando, finché non è fluida ma vela il cucchiaio; tenere in caldo.","Servire i fusi con riso jasmine e la salsa di arachidi per intingerli."]}}'::jsonb),
  ('57abb0a5-0fc5-4e5e-b5e7-7130b2e204ed'::uuid, '{"fr":{"title":"Poulet trois tasses taïwanais","steps":["Mélanger les sauces soja claire et foncée, le sucre et le vin de riz dans un petit bol.","Faire chauffer l''huile dans une poêle antiadhésive à feu moyen-doux et faire grésiller le gingembre et le piment environ 30 secondes.","Monter à feu vif, ajouter le poulet et le faire cuire jusqu''à ce que l''extérieur blanchisse tout en restant cru à l''intérieur ; ajouter l''ail et remuer 30 secondes.","Verser la sauce, porter à frémissement, puis baisser à feu moyen/moyen-vif pour un frémissement régulier.","Laisser mijoter environ 5 minutes en remuant, jusqu''à ce que le poulet soit coloré et que la sauce ait réduit en un sirop léger (ajouter un peu d''eau si elle réduit trop vite).","Incorporer l''huile de sésame et le basilic jusqu''à ce que les feuilles flétrissent, puis servir sur du riz avec tout le sirop de la poêle."]},"it":{"title":"Pollo tre tazze taiwanese","steps":["Mescolare in una ciotolina la salsa di soia chiara e quella scura, lo zucchero e il vino di riso.","Scaldare l''olio in una padella antiaderente a fuoco medio-basso e far sfrigolare lo zenzero e il peperoncino per circa 30 secondi.","Alzare la fiamma al massimo, aggiungere il pollo e cuocerlo finché l''esterno non diventa bianco pur restando crudo all''interno; aggiungere l''aglio e mescolare per 30 secondi.","Versare la salsa, portare a bollore, poi abbassare a fuoco medio/medio-alto per mantenere un sobbollire costante.","Cuocere a fuoco lento per circa 5 minuti, mescolando, finché il pollo non ha preso colore e la salsa non si è ridotta a uno sciroppo leggero (aggiungere un goccio d''acqua se si riduce troppo in fretta).","Unire l''olio di sesamo e il basilico finché le foglie non appassiscono, poi servire sul riso con tutto lo sciroppo della padella."]}}'::jsonb),
  ('6001b71f-a4b5-458e-b945-13665dd61028'::uuid, '{"fr":{"title":"Poulet teriyaki et riz","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Fouetter ensemble la sauce soja, le sucre, le vinaigre, la moitié de l''huile, l''ail et le gingembre.","Mélanger le poulet avec la moitié de cette sauce dans un plat à four et enfourner 20–25 minutes jusqu''à ce qu''il soit bien cuit et laqué.","Pendant ce temps, faire cuire le riz selon les indications du paquet.","Faire revenir doucement l''oignon dans le reste de l''huile à feu moyen pendant 5–8 minutes jusqu''à ce qu''il soit légèrement doré ; réserver.","Incorporer la fécule de maïs au reste de la sauce et la faire bouillonner dans la poêle jusqu''à ce qu''elle épaississe, puis remettre l''oignon et ajouter le poulet rôti.","Servir sur le riz avec le jus du plat de cuisson et l''oignon nouveau par-dessus."]},"it":{"title":"Pollo teriyaki con riso","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Sbattere insieme la salsa di soia, lo zucchero, l''aceto, metà dell''olio, l''aglio e lo zenzero.","Mescolare il pollo con metà di questa salsa in una pirofila e cuocere in forno per 20–25 minuti finché non è ben cotto e glassato.","Nel frattempo cuocere il riso seguendo le istruzioni sulla confezione.","Far appassire la cipolla nell''olio rimasto a fuoco medio per 5–8 minuti finché non è leggermente dorata; tenere da parte.","Incorporare l''amido di mais alla salsa rimasta e farla sobbollire nella padella finché non si addensa, poi rimettere la cipolla e aggiungere il pollo cotto in forno.","Servire sul riso con il fondo di cottura della pirofila e il cipollotto sopra."]}}'::jsonb),
  ('133f9e39-76f2-420d-954d-e311510897f2'::uuid, '{"fr":{"title":"Curry vert thaï au poulet","steps":["Faire chauffer l''huile dans une casserole à fond épais à feu moyen-vif.","Faire revenir la pâte de curry vert avec l''ail, le gingembre et la citronnelle pendant 2–3 minutes jusqu''à ce que la majeure partie de l''humidité se soit évaporée (garder le visage à l''écart des vapeurs).","Verser le bouillon et le lait de coco et remuer jusqu''à ce que la pâte soit dissoute.","Assaisonner avec la sauce poisson et le sucre, ajouter les feuilles de citron kaffir et porter à frémissement.","Ajouter le poulet, baisser le feu pour obtenir un léger frémissement et cuire 7 minutes.","Ajouter l''aubergine et laisser mijoter environ 5 minutes jusqu''à ce qu''elle soit tendre ; goûter et rectifier le sel et le sucre.","Ajouter les pois gourmands pendant 2 minutes, puis incorporer le basilic et le jus de citron vert et retirer aussitôt du feu.","Servir sur du riz jasmin."]},"it":{"title":"Curry verde thai con pollo","steps":["Scaldare l''olio in una pentola dal fondo spesso a fuoco medio-alto.","Soffriggere la pasta di curry verde con l''aglio, lo zenzero e la citronella per 2–3 minuti finché gran parte dell''umidità non è evaporata (tenere il viso lontano dai vapori).","Versare il brodo e il latte di cocco e mescolare finché la pasta non si scioglie.","Condire con la salsa di pesce e lo zucchero, aggiungere le foglie di lime kaffir e portare a bollore leggero.","Aggiungere il pollo, abbassare la fiamma per un sobbollire delicato e cuocere per 7 minuti.","Aggiungere la melanzana e cuocere a fuoco lento per circa 5 minuti finché non è morbida; assaggiare e regolare di sale e dolcezza.","Aggiungere le taccole per 2 minuti, poi unire il basilico e il succo di lime e togliere subito dal fuoco.","Servire su riso jasmine."]}}'::jsonb),
  ('66ead8f3-045d-4124-a93c-2ee801a03fef'::uuid, '{"fr":{"title":"Ragoût de poisson brésilien (moqueca)","steps":["Éponger le poisson, le couper en gros morceaux et le frotter avec le sel, le zeste et le jus de citron vert ; réserver.","Dans une sauteuse large, faire revenir l''oignon dans l''huile avec une pincée de sel jusqu''à ce qu''il soit tendre.","Ajouter la carotte, le poivron rouge, l''ail et le jalapeño et poursuivre la cuisson quelques minutes.","Incorporer le concentré de tomate, le paprika, le cumin et le fumet, porter à frémissement, ajouter les tomates, couvrir et cuire jusqu''à ce que les carottes soient tendres.","Verser le lait de coco et rectifier le sel.","Enfoncer le poisson dans la sauce et laisser mijoter doucement en l''arrosant de bouillon, jusqu''à ce qu''il soit tout juste cuit (les morceaux épais peuvent finir de cuire au four à 175 °C).","Ajouter un filet de citron vert, parsemer d''herbes et servir sur du riz."]},"it":{"title":"Stufato di pesce brasiliano (moqueca)","steps":["Asciugare il pesce tamponandolo, tagliarlo a pezzi grandi e strofinarlo con il sale, la scorza e il succo di lime; tenere da parte.","In una padella larga, far appassire la cipolla nell''olio con un pizzico di sale finché non è morbida.","Aggiungere la carota, il peperone rosso, l''aglio e il jalapeño e cuocere ancora per qualche minuto.","Unire il concentrato di pomodoro, la paprika, il cumino e il brodo, portare a bollore leggero, aggiungere i pomodori, coprire e cuocere finché le carote non sono tenere.","Versare il latte di cocco e regolare di sale.","Adagiare il pesce nella salsa e cuocere delicatamente a fuoco lento, irrorandolo con il brodo, finché non è appena cotto (i pezzi spessi possono finire la cottura in forno a 175 °C).","Aggiungere una spruzzata di lime, cospargere di erbe aromatiche e servire sul riso."]}}'::jsonb),
  ('259ada42-4c9b-4936-88ec-79c0ba6bb82b'::uuid, '{"fr":{"title":"Chaudrée de saumon cajun et patate douce","steps":["Faire chauffer l''huile dans une casserole à feu moyen-vif, ajouter la carotte, l''oignon et le céleri, couvrir et cuire environ 5 minutes jusqu''à ce qu''ils soient tendres.","Ajouter le poivron et l''assaisonnement cajun et poursuivre la cuisson 2 minutes.","Ajouter la patate douce, le bouillon et environ 120 ml d''eau, porter à ébullition, puis couvrir et laisser mijoter environ 10 minutes jusqu''à ce que la patate douce soit tendre.","Ajouter le saumon et le maïs et laisser mijoter environ 3 minutes jusqu''à ce que le poisson soit tout juste opaque à cœur.","Baisser à feu doux, incorporer le mélange lait-crème, le basilic et le sel et réchauffer 1 minute.","Retirer du feu, incorporer le jus de citron et servir."]},"it":{"title":"Zuppa cremosa di salmone cajun e patate dolci","steps":["Scaldare l''olio in una casseruola a fuoco medio-alto, aggiungere la carota, la cipolla e il sedano, coprire e cuocere per circa 5 minuti finché non si ammorbidiscono.","Aggiungere il peperone e il condimento cajun e cuocere per altri 2 minuti.","Aggiungere la patata dolce, il brodo e circa 120 ml d''acqua, portare a bollore, poi coprire e cuocere a fuoco lento per circa 10 minuti finché la patata non è tenera.","Aggiungere il salmone e il mais e cuocere a fuoco lento per circa 3 minuti finché il pesce non è appena opaco al centro.","Abbassare la fiamma al minimo, unire la miscela di latte e panna, il basilico e il sale e scaldare per 1 minuto.","Togliere dal fuoco, unire il succo di limone e servire."]}}'::jsonb),
  ('d939ecdf-9a41-49f5-87f1-33289d9daeea'::uuid, '{"fr":{"title":"Saumon cajun et quartiers de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger les quartiers sur une plaque antiadhésive avec la moitié de l''huile, le romarin et un peu de sel et enfourner 25-30 minutes jusqu''à ce qu''ils soient croustillants à l''extérieur et fondants à l''intérieur.","Frotter le saumon avec un peu d''huile et l''enrober d''assaisonnement cajun.","Pendant les 10 dernières minutes de cuisson des quartiers, faire rôtir le saumon à côté sur une petite plaque.","Assaisonner la roquette avec le reste de l''huile et le vinaigre et servir avec le saumon et les quartiers."]},"it":{"title":"Salmone cajun con spicchi di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Mescolare gli spicchi su una teglia antiaderente con metà dell''olio, il rosmarino e un po'' di sale e cuocere in forno per 25-30 minuti finché non sono croccanti fuori e morbidi dentro.","Strofinare il salmone con un filo d''olio e ricoprirlo con il condimento cajun.","Negli ultimi 10 minuti di cottura degli spicchi, cuocere in forno il salmone accanto, su una teglia piccola.","Condire la rucola con l''olio rimasto e l''aceto e servire con il salmone e gli spicchi."]}}'::jsonb),
  ('376e8ca0-3d31-4b62-852c-ac2fdc9e9648'::uuid, '{"fr":{"title":"Bols de carne asada, crème au chipotle","steps":["Mélanger l''huile, la sauce soja, le jus de citron vert, le cumin, le chipotle en poudre, la coriandre et l''ail dans un sac de congélation zippé.","Ajouter le steak et laisser mariner au réfrigérateur au moins 30 minutes (jusqu''à 8 heures).","Faire chauffer un barbecue à feu vif, sortir le steak de la marinade, le saler des deux côtés et le faire griller environ 5 minutes de chaque côté.","Laisser reposer le steak 5-10 minutes, couvert sans serrer, puis le trancher perpendiculairement aux fibres et le couper en dés.","Mélanger le riz cuit avec la coriandre et le jus de citron vert.","Mixer la crème, le chipotle, l''ail, le citron vert et le sel jusqu''à obtenir une crème lisse.","Garnir les bols de riz, de steak, de pico de gallo, d''avocat, de jalapeño, de radis et de fromage, puis arroser de crème au chipotle."]},"it":{"title":"Ciotole di carne asada con crema al chipotle","steps":["Mescolare in un sacchetto con chiusura zip l''olio, la salsa di soia, il succo di lime, il cumino, il chipotle in polvere, il coriandolo e l''aglio.","Aggiungere la bistecca e lasciarla marinare in frigorifero per almeno 30 minuti (fino a 8 ore).","Scaldare la griglia al massimo, togliere la bistecca dalla marinata, salarla su entrambi i lati e grigliarla per circa 5 minuti per lato.","Lasciare riposare la bistecca coperta senza stringere per 5-10 minuti, poi tagliarla contro fibra e ridurla a cubetti.","Mescolare il riso cotto con il coriandolo e il succo di lime.","Frullare la crema, il chipotle, l''aglio, il lime e il sale fino a ottenere un composto liscio.","Riempire le ciotole con riso, bistecca, pico de gallo, avocado, jalapeño, ravanelli e formaggio, poi condire con un filo di crema al chipotle."]}}'::jsonb),
  ('7dfb17b4-788e-4166-8e3f-0327f79e3794'::uuid, '{"fr":{"title":"Poulet et patate douce rôtis au four","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger la patate douce, l''oignon et l''ail avec le thym, le romarin, la majeure partie de l''huile, du sel et du poivre, et enfourner 15 minutes.","Remuer, caler le poulet entre les légumes, l''arroser du reste de l''huile, ajouter le jus de citron et le paprika fumé et poursuivre la cuisson 15 minutes.","Ajouter le brocoli et la majeure partie du bouillon et enfourner encore 15-20 minutes, en ajoutant du bouillon si la plaque se dessèche, jusqu''à ce que le poulet soit bien cuit.","Presser l''ail fondant hors de sa peau au-dessus de la plaque et servir avec les quartiers de citron."]},"it":{"title":"Pollo e patate dolci in teglia","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Mescolare la patata dolce, la cipolla e l''aglio con il timo, il rosmarino, gran parte dell''olio, sale e pepe, e cuocere in forno per 15 minuti.","Mescolare, sistemare il pollo tra le verdure, irrorarlo con l''olio rimasto, aggiungere il succo di limone e la paprika affumicata e cuocere in forno per altri 15 minuti.","Aggiungere i broccoli e gran parte del brodo e cuocere in forno per altri 15-20 minuti, aggiungendo altro brodo se la teglia si asciuga, finché il pollo non è ben cotto.","Spremere l''aglio morbido dalla buccia direttamente sulla teglia e servire con gli spicchi di limone."]}}'::jsonb),
  ('27e46b96-2742-476c-bc1f-e5c23aa41f11'::uuid, '{"fr":{"title":"Souvlaki de poulet au tzatziki","steps":["Fouetter l''huile, le jus de citron, l''ail, l''origan, le sel et le poivre pour obtenir une marinade.","Y enrober les cubes de poulet et laisser au réfrigérateur 3-4 heures.","Faire tremper des brochettes en bois dans l''eau, puis y enfiler le poulet et le badigeonner du reste de marinade.","Faire griller 10-15 minutes en retournant de temps en temps, jusqu''à ce que le poulet soit bien cuit.","Réchauffer les pitas sur le gril.","Servir les brochettes sur les pitas avec des rondelles de tomate et du tzatziki."]},"it":{"title":"Souvlaki di pollo con tzatziki","steps":["Sbattere l''olio, il succo di limone, l''aglio, l''origano, il sale e il pepe per preparare una marinata.","Ricoprire i cubetti di pollo con la marinata e lasciarli in frigorifero per 3-4 ore.","Mettere a bagno in acqua gli spiedini di legno, poi infilzarvi il pollo e spennellarlo con la marinata avanzata.","Grigliare per 10-15 minuti, girando di tanto in tanto, finché non è ben cotto.","Scaldare le pita sulla griglia.","Servire gli spiedini sulle pita con fette di pomodoro e tzatziki."]}}'::jsonb),
  ('7fa7da2a-36aa-4a38-95f7-b0269eae6257'::uuid, '{"fr":{"title":"Tinga de poulet","steps":["Faire chauffer l''huile à feu moyen et faire revenir l''oignon émincé environ 3 minutes.","Ajouter l''ail et cuire encore 2 minutes, jusqu''à ce qu''il soit parfumé.","Incorporer les tomates et le persil, baisser le feu et cuire 6-7 minutes jusqu''à ce que les tomates se défassent (ajouter un trait d''eau si c''est trop sec).","Ajouter le poulet effiloché et le chipotle haché et laisser mijoter environ 8 minutes pour que les saveurs se mêlent.","Saler, poivrer, parsemer de persil et servir avec du riz et de la salade ou sur des tostadas."]},"it":{"title":"Tinga di pollo","steps":["Scaldare l''olio a fuoco medio e soffriggere la cipolla affettata per circa 3 minuti.","Aggiungere l''aglio e cuocere ancora 2 minuti, finché non diventa profumato.","Unire i pomodori e il prezzemolo, abbassare la fiamma e cuocere 6-7 minuti finché i pomodori non si disfano (aggiungere un goccio d''acqua se si asciuga troppo).","Aggiungere il pollo sfilacciato e il chipotle tritato e cuocere a fuoco lento per circa 8 minuti, così che i sapori si amalgamino.","Regolare di sale e pepe, guarnire con prezzemolo e servire con riso e insalata oppure sulle tostadas."]}}'::jsonb),
  ('c48e4b57-7ea0-42c9-b482-1f84126f5951'::uuid, '{"fr":{"title":"Doro wat","steps":["Frotter le poulet avec le jus de citron, bien le rincer, saler et laisser reposer 30 minutes.","Cuire les oignons à sec dans une casserole à feu moyen-doux, en remuant de temps en temps, pendant au moins une heure, jusqu''à ce qu''ils soient bien caramélisés.","Ajouter l''huile et poursuivre la cuisson des oignons 15-20 minutes, jusqu''à ce qu''ils foncent.","Incorporer le berbéré, l''ail, le gingembre, la cardamome et le ghee.","Ajouter le poulet, couvrir et cuire 10 minutes, puis ajouter environ 250 ml d''eau, couvrir de nouveau et cuire encore 30 minutes.","Pendant ce temps, faire cuire les œufs environ 10 minutes dans l''eau bouillante, les plonger dans de l''eau glacée, les écaler et les couper en morceaux.","Ajouter les œufs au ragoût, assaisonner de mekelesha et de sel, et servir avec du riz ou de l''injera."]},"it":{"title":"Doro wat","steps":["Strofinare il pollo con il succo di limone, sciacquarlo bene, salarlo e lasciarlo riposare 30 minuti.","Cuocere le cipolle in una casseruola senza grassi a fuoco medio-basso, mescolando di tanto in tanto, per almeno un''ora, finché non sono ben caramellate.","Aggiungere l''olio e continuare a cuocere le cipolle per 15-20 minuti, finché non diventano più scure.","Unire il berbere, l''aglio, lo zenzero, il cardamomo e il ghee.","Aggiungere il pollo, coprire e cuocere 10 minuti, poi aggiungere circa 250 ml d''acqua, coprire di nuovo e cuocere ancora 30 minuti.","Nel frattempo lessare le uova per circa 10 minuti, raffreddarle in acqua e ghiaccio, sgusciarle e tagliarle a pezzi.","Aggiungere le uova allo spezzatino, insaporire con il mekelesha e il sale e servire con riso o injera."]}}'::jsonb),
  ('eab5838e-660b-4b5f-9444-00603cb201fa'::uuid, '{"fr":{"title":"Poisson au four à la grecque (psari plaki)","steps":["Préchauffer le four à 200 °C (400 °F), avec une grille au milieu.","Dans une poêle allant au four, faire revenir l''oignon dans l''huile d''olive avec une pincée de sel jusqu''à ce qu''il soit tendre et légèrement doré.","Incorporer l''ail, puis les tomates, l''origan et le poivre ; écraser les tomates, porter à ébullition et laisser mijoter 10-15 minutes.","Sécher le poisson et l''assaisonner des deux côtés de sel, d''origan, de paprika et de cumin ; presser la moitié du citron par-dessus.","Déposer le poisson dans la sauce et le napper d''un peu de sauce.","Enfourner 15-25 minutes, jusqu''à ce que le poisson soit opaque et s''effeuille facilement ; surveiller pour qu''il ne soit pas trop cuit.","Parsemer de persil et servir avec le reste du citron en quartiers, ainsi que du pain ou du riz."]},"it":{"title":"Pesce al forno alla greca (psari plaki)","steps":["Preriscaldare il forno a 200 °C (400 °F) con una griglia al centro.","In una padella adatta al forno, far appassire la cipolla nell''olio d''oliva con un pizzico di sale finché non è morbida e leggermente dorata.","Unire l''aglio, poi i pomodori, l''origano e il pepe; schiacciare i pomodori, portare a bollore e cuocere a fuoco lento per 10-15 minuti.","Asciugare il pesce e condirlo su entrambi i lati con sale, origano, paprika e cumino; spremerci sopra metà del limone.","Adagiare il pesce nel sugo e coprirlo con un po'' di sugo.","Cuocere in forno 15-25 minuti, finché il pesce non è opaco e si sfalda facilmente; controllare che non cuocia troppo.","Cospargere di prezzemolo e servire con il limone rimasto a spicchi, accompagnando con pane o riso."]}}'::jsonb),
  ('88cbc523-853f-41c7-b63a-f0f761e56e3b'::uuid, '{"fr":{"title":"Saumon rôti à la harissa et céréales aux herbes","steps":["Faire cuire les céréales à petit bouillon dans de l''eau salée 20-25 minutes, jusqu''à ce qu''elles soient juste tendres.","Préchauffer le four à 180 °C (160 °C chaleur tournante) ; mélanger la harissa, l''huile, le miel et le jus d''un demi-citron.","Enrober le saumon et les tomates du mélange à la harissa dans un plat à four et rôtir 15 minutes.","Dans un grand saladier, mélanger les oignons nouveaux, la majeure partie des herbes, le reste du jus de citron et un filet d''huile.","Ajouter les petits pois aux céréales pendant la dernière minute, puis bien égoutter.","Mélanger le reste des herbes au yaourt avec du sel et un trait d''eau pour le détendre.","Mélanger les céréales et les petits pois avec les oignons nouveaux, dresser dans les assiettes, garnir de saumon et de tomates et ajouter la sauce au yaourt."]},"it":{"title":"Salmone al forno all''harissa con cereali alle erbe","steps":["Cuocere i cereali in acqua salata a fuoco lento per 20-25 minuti, finché non sono appena teneri.","Preriscaldare il forno a 180 °C (160 °C ventilato); mescolare harissa, olio, miele e il succo di mezzo limone.","In una pirofila, condire il salmone e i pomodorini con il mix all''harissa e cuocere in forno 15 minuti.","In una ciotola capiente unire i cipollotti, la maggior parte delle erbe, il resto del succo di limone e un filo d''olio.","Aggiungere i piselli ai cereali nell''ultimo minuto di cottura, poi scolare bene.","Mescolare le erbe rimaste allo yogurt con sale e un goccio d''acqua per renderlo più fluido.","Condire cereali e piselli con il mix di cipollotti, impiattare, aggiungere sopra salmone e pomodorini e completare con la salsa allo yogurt."]}}'::jsonb),
  ('21e7d4dc-7424-4a23-b4c8-b3410109c188'::uuid, '{"fr":{"title":"Cottage pie allégé","steps":["Vaporiser une cocotte d''huile et faire suer l''oignon à feu moyen.","Ajouter l''ail, la carotte, le céleri, le sel, les herbes, le sucre et la feuille de laurier et cuire environ 8 minutes.","Ajouter le bœuf haché en l''émiettant et cuire jusqu''à ce qu''il soit bien doré.","Incorporer le concentré de tomates, puis le vinaigre balsamique, la sauce soja et la sauce Worcestershire.","Ajouter la courge butternut et le bouillon, couvrir partiellement et laisser mijoter 30 minutes ; épaissir avec la fécule de maïs délayée dans un peu d''eau froide et retirer la feuille de laurier.","Pendant ce temps, cuire les pommes de terre dans l''eau salée environ 15 minutes jusqu''à ce qu''elles soient tendres, les égoutter (en gardant un peu d''eau de cuisson) et les écraser avec le yaourt ou le fromage blanc.","Préchauffer le four à 220 °C, étaler la garniture dans un plat à four, recouvrir de purée et strier la surface à la fourchette.","Parsemer de parmesan et enfourner 30-35 minutes jusqu''à ce que le dessus soit doré ; laisser reposer 10 minutes avant de servir avec des légumes verts."]},"it":{"title":"Cottage pie light","steps":["Spruzzare una casseruola con l''olio e far appassire la cipolla a fuoco medio.","Aggiungere l''aglio, la carota, il sedano, il sale, le erbe, lo zucchero e l''alloro e cuocere per circa 8 minuti.","Aggiungere il macinato, sgranandolo, e cuocere finché non è ben rosolato.","Unire il concentrato di pomodoro, poi l''aceto balsamico, la salsa di soia e la salsa Worcestershire.","Aggiungere la zucca e il brodo, coprire parzialmente e cuocere a fuoco lento per 30 minuti; addensare con l''amido di mais stemperato in poca acqua fredda ed eliminare la foglia di alloro.","Nel frattempo lessare le patate in acqua salata per circa 15 minuti finché non sono tenere, scolarle (tenendo da parte un goccio dell''acqua di cottura) e schiacciarle con lo yogurt o il formaggio fresco magro.","Preriscaldare il forno a 220 °C, distribuire il ripieno in una pirofila, coprire con il purè e rigare la superficie con una forchetta.","Cospargere di parmigiano e cuocere in forno 30-35 minuti finché non è dorato; lasciar riposare 10 minuti prima di servire con verdure verdi."]}}'::jsonb),
  ('b0816cc0-d7b8-4649-88e0-b13c37a64404'::uuid, '{"fr":{"title":"Chili de dinde allégé","steps":["Faire chauffer l''huile dans une grande marmite à feu moyen-vif et faire revenir l''oignon, l''ail et le poivron 5-7 minutes en remuant souvent.","Ajouter la dinde et l''émietter à la cuillère jusqu''à ce qu''elle ne soit plus rose.","Incorporer le piment en poudre, le cumin, l''origan, le piment de Cayenne et le sel et faire griller environ 20 secondes.","Ajouter les tomates, le bouillon, les haricots rouges et le maïs et porter à ébullition.","Baisser le feu et laisser mijoter 30-45 minutes jusqu''à ce que ce soit épais, puis rectifier l''assaisonnement.","Servir garni d''un peu de fromage, d''avocat ou de coriandre, selon les envies."]},"it":{"title":"Chili di tacchino light","steps":["Scaldare l''olio in una pentola capiente a fuoco medio-alto e soffriggere cipolla, aglio e peperone per 5-7 minuti, mescolando spesso.","Aggiungere il tacchino e sgranarlo con un cucchiaio finché non è più rosa.","Unire il chili in polvere, il cumino, l''origano, il pepe di Cayenna e il sale e tostare per circa 20 secondi.","Aggiungere i pomodori, il brodo, i fagioli rossi e il mais e portare a bollore.","Abbassare la fiamma e cuocere a fuoco lento per 30-45 minuti finché non si addensa, poi aggiustare di sapore.","Servire con un po'' di formaggio, avocado o coriandolo, a piacere."]}}'::jsonb),
  ('72202527-c9b6-4d93-a159-0f71b4d22001'::uuid, '{"fr":{"title":"Ragoût d''agneau irlandais","steps":["Mélanger l''agneau avec la moitié de l''ail, le romarin et le vin blanc et laisser mariner 1 heure ; égoutter et jeter le liquide.","Faire chauffer l''huile dans une cocotte en fonte et faire dorer l''agneau sur toutes les faces, par petites quantités ; réserver.","Faire suer l''oignon dans la même cocotte environ 4 minutes, puis ajouter le reste de l''ail pendant 1 minute.","Remettre l''agneau avec les flocons de piment, les poivrons grillés, la tomate, la feuille de laurier et le vin rouge ; porter à ébullition et laisser mijoter 15 minutes.","Verser le bouillon et cuire doucement à feu doux 1,5-2 heures, jusqu''à ce que l''agneau soit très tendre.","Saler, poivrer et servir avec du riz ou du pain croustillant."]},"it":{"title":"Spezzatino d''agnello irlandese","steps":["Mescolare l''agnello con metà dell''aglio, il rosmarino e il vino bianco e lasciar marinare per 1 ora; scolare ed eliminare il liquido.","Scaldare l''olio in una pentola dal fondo spesso e rosolare l''agnello su tutti i lati, poco per volta; tenere da parte.","Far appassire la cipolla nella stessa pentola per circa 4 minuti, poi aggiungere l''aglio rimasto per 1 minuto.","Rimettere l''agnello con il peperoncino in fiocchi, i peperoni arrostiti, il pomodoro, l''alloro e il vino rosso; portare a bollore e cuocere a fuoco lento per 15 minuti.","Versare il brodo e cuocere dolcemente a fuoco basso per 1,5-2 ore, finché l''agnello non è molto tenero.","Regolare di sale e pepe e servire con riso o pane croccante."]}}'::jsonb),
  ('8415659c-0fbe-4c0f-879f-6902ec41c28b'::uuid, '{"fr":{"title":"Curry de poulet jerk aux haricots","steps":["Frotter les pilons avec un peu d''assaisonnement jerk, du sel et du poivre.","Les faire dorer dans la moitié de l''huile, puis les réserver sur une assiette.","Ajouter le reste de l''huile et faire suer l''oignon et les tiges de coriandre environ 5 minutes, en incorporant le reste de l''assaisonnement jerk pendant la dernière minute.","Remettre le poulet, ajouter les tomates, porter à frémissement, couvrir et cuire 20 minutes ; lancer la cuisson du riz pendant ce temps.","Découvrir, ajouter les haricots et laisser mijoter encore 10 minutes, jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de feuilles de coriandre et servir avec le riz."]},"it":{"title":"Curry di pollo jerk con fagioli","steps":["Massaggiare i fusi di pollo con un po'' di condimento jerk, sale e pepe.","Rosolarli in metà dell''olio, poi toglierli e metterli su un piatto.","Aggiungere il resto dell''olio e far appassire la cipolla e i gambi di coriandolo per circa 5 minuti, unendo il condimento jerk rimasto nell''ultimo minuto.","Rimettere il pollo, aggiungere i pomodori, portare a sobbollire, coprire e cuocere 20 minuti; nel frattempo mettere a cuocere il riso.","Scoprire, aggiungere i fagioli e cuocere a fuoco lento per altri 10 minuti, finché il pollo non è cotto.","Cospargere di foglie di coriandolo e servire con il riso."]}}'::jsonb),
  ('ff2f10ad-8161-4b4b-aba7-4d79a27d86cb'::uuid, '{"fr":{"title":"Poulet jerk et frites de patate douce","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante) et chemiser deux plaques de cuisson.","Couper les patates douces en frites de l''épaisseur d''un doigt, les mélanger avec la majeure partie de l''huile et une pincée de sel et les étaler sur une plaque.","Frotter le poulet avec l''assaisonnement jerk et le disposer sur la seconde plaque.","Rôtir 20 minutes, le poulet sur la grille du haut et les frites en dessous, puis intervertir les plaques et rôtir encore 15-20 minutes, jusqu''à ce que les frites soient tendres et grillées et que le poulet soit cuit.","Pendant ce temps, mélanger les tomates, l''oignon et le piment avec le zeste du citron vert, la moitié de son jus, un filet d''huile et une pincée de sel.","Servir le poulet et les frites avec la salade de tomates, la mâche et le reste du citron vert en quartiers."]},"it":{"title":"Pollo jerk con patatine di patate dolci","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato) e foderare due teglie.","Tagliare le patate dolci a bastoncini spessi un dito, condirle con la maggior parte dell''olio e un pizzico di sale e distribuirle su una teglia.","Massaggiare il pollo con il condimento jerk e disporlo sulla seconda teglia.","Cuocere in forno 20 minuti con il pollo sul ripiano alto e le patate sotto, poi invertire le teglie e cuocere altri 15-20 minuti, finché le patate non sono tenere e abbrustolite e il pollo è cotto.","Nel frattempo mescolare i pomodorini, la cipolla e il peperoncino con la scorza del lime, metà del succo, un filo d''olio e un pizzico di sale.","Servire il pollo e le patate con l''insalata di pomodorini, la valeriana e il lime rimasto a spicchi."]}}'::jsonb),
  ('7ff5c0bd-3b85-48ab-8595-8379faa87fc3'::uuid, '{"fr":{"title":"Kofta d''agneau, yaourt aux herbes","steps":["Mélanger l''agneau avec l''ail, l''oignon râpé, les épices, les herbes, le sel et le poivre.","Diviser en 4 portions, presser chacune autour d''une brochette pour former une kofta allongée et réfrigérer 10-15 minutes si le temps le permet.","Mélanger le yaourt avec l''ail, le jus de citron, les herbes, du sel et du poivre ; garder au frais.","Faire chauffer un gril ou un barbecue à feu moyen-vif et badigeonner les koftas d''huile.","Griller 12-15 minutes en retournant souvent, jusqu''à ce qu''elles soient dorées et cuites à cœur (70 °C à l''intérieur).","Servir avec des pains plats chauds, la sauce au yaourt, la laitue, le concombre et l''oignon rouge."]},"it":{"title":"Kofta d''agnello con yogurt alle erbe","steps":["Mescolare l''agnello con l''aglio, la cipolla grattugiata, le spezie, le erbe, il sale e il pepe.","Dividere in 4 porzioni, modellare ciascuna attorno a uno spiedino formando una kofta allungata e far riposare in frigo 10-15 minuti se c''è tempo.","Mescolare lo yogurt con l''aglio, il succo di limone, le erbe, sale e pepe; tenere in fresco.","Scaldare una griglia o un barbecue a fuoco medio-alto e spennellare le kofta con l''olio.","Grigliare 12-15 minuti, girando spesso, finché non sono dorate e cotte all''interno (70 °C al cuore).","Servire con pane arabo caldo, la salsa allo yogurt, la lattuga, il cetriolo e la cipolla rossa."]}}'::jsonb),
  ('1e932845-59bf-429a-9ef5-73ddfd24e7ee'::uuid, '{"fr":{"title":"Wraps shawarma au poulet à la libanaise","steps":["Mélanger l''ail, le jus de citron, le yaourt, le sel, les épices et l''huile d''olive pour préparer une marinade.","Y enrober le poulet et réfrigérer 3 heures ou toute une nuit (au moins 1 heure si on est pressé).","Faire chauffer l''huile de cuisson dans une grande poêle jusqu''à ce qu''elle soit très chaude.","Cuire le poulet en une seule couche sans surcharger la poêle, environ 2 minutes de chaque côté pour de fines tranches de blanc, jusqu''à ce qu''il soit doré et cuit à cœur.","Couper le poulet cuit en lanières.","Étaler de la toum au centre de chaque pita, ajouter le poulet, les cornichons et les frites si on en utilise.","Rouler bien serré et couper en deux pour servir."]},"it":{"title":"Wrap di shawarma di pollo alla libanese","steps":["Mescolare aglio, succo di limone, yogurt, sale, spezie e olio d''oliva per preparare la marinata.","Ricoprire il pollo con la marinata e lasciarlo in frigo 3 ore o tutta la notte (almeno 1 ora se si ha fretta).","Scaldare l''olio per friggere in una padella ampia finché non è molto caldo.","Cuocere il pollo in un solo strato senza affollare la padella, circa 2 minuti per lato per fettine sottili di petto, finché non è dorato e cotto.","Tagliare il pollo cotto a striscioline.","Spalmare la toum al centro di ogni pita, aggiungere il pollo, i cetriolini sottaceto e, se si usano, le patatine.","Arrotolare stretto e tagliare a metà per servire."]}}'::jsonb),
  ('e31d848c-77d0-4a82-852f-d6885f91706a'::uuid, '{"fr":{"title":"Boulettes suédoises allégées","steps":["Faire suer l''oignon et l''ail dans l''huile, ajouter le céleri et le persil pendant quelques minutes, puis laisser refroidir le mélange.","Mélanger la dinde, le bœuf, l''œuf, les légumes refroidis, la chapelure, le sel, le poivre et le piment de la Jamaïque ; façonner 8 boulettes.","Porter le bouillon à ébullition dans une sauteuse, baisser à frémissement et ajouter les boulettes.","Couvrir et pocher environ 20 minutes jusqu''à ce qu''elles soient cuites à cœur, puis retirer les boulettes.","Filtrer le bouillon et le mixer avec le fromage frais jusqu''à obtenir une sauce lisse.","Remettre la sauce et les boulettes dans la sauteuse et laisser mijoter quelques minutes jusqu''à ce que la sauce épaississe légèrement ; parsemer de persil."]},"it":{"title":"Polpette svedesi light","steps":["Far appassire la cipolla e l''aglio nell''olio, aggiungere il sedano e il prezzemolo per un paio di minuti, poi lasciar raffreddare il composto.","Unire il tacchino, il manzo, l''uovo, le verdure raffreddate, il pangrattato, il sale, il pepe e il pimento; formare 8 polpette.","Portare a bollore il brodo in una padella, abbassare la fiamma a sobbollire e aggiungere le polpette.","Coprire e cuocere dolcemente nel brodo per circa 20 minuti finché non sono cotte, poi togliere le polpette dalla padella.","Filtrare il brodo e frullarlo con il formaggio spalmabile fino a ottenere una salsa liscia.","Rimettere la salsa e le polpette nella padella e cuocere a fuoco lento qualche minuto finché la salsa non si addensa leggermente; guarnire con prezzemolo."]}}'::jsonb),
  ('fc33d4ff-b75f-430a-b4e4-bff6fcb450a4'::uuid, '{"fr":{"title":"Poulet paprikash allégé","steps":["Mettre à bouillir une casserole d''eau salée et y cuire les nouilles aux œufs pendant la préparation de la sauce.","Faire chauffer l''huile dans une grande sauteuse à feu moyen-vif et cuire le poulet jusqu''à ce qu''il ne soit plus rose ; le retirer.","Faire suer l''oignon dans la même sauteuse, puis ajouter l''ail environ une minute.","Remettre le poulet avec les deux paprikas, le bouillon, les tomates, le sel et le poivre ; porter à ébullition et cuire environ 2 minutes jusqu''à ce que la sauce épaississe un peu.","Retirer la sauteuse du feu et incorporer le yaourt (hors du feu pour qu''il ne tranche pas) ; rectifier l''assaisonnement.","Napper les nouilles de la préparation et parsemer de persil."]},"it":{"title":"Pollo paprikash light","steps":["Mettere sul fuoco una pentola di acqua salata e cuocere le tagliatelle all''uovo mentre si prepara il sugo.","Scaldare l''olio in una padella capiente a fuoco medio-alto e cuocere il pollo finché non è più rosa; toglierlo dalla padella.","Far appassire la cipolla nella stessa padella, poi aggiungere l''aglio per circa un minuto.","Rimettere il pollo con entrambe le paprike, il brodo, i pomodori, sale e pepe; portare a bollore e cuocere circa 2 minuti finché il sugo non si addensa un po''.","Togliere la padella dal fuoco e incorporare lo yogurt (a fuoco spento, così non impazzisce); regolare di sale e pepe.","Versare sulle tagliatelle e completare con il prezzemolo."]}}'::jsonb),
  ('5bfdb175-f3b8-4a0a-a4ac-d972e6504617'::uuid, '{"fr":{"title":"Tajine de poulet aux olives et au citron","steps":["Mélanger la majeure partie de l''ail avec toutes les épices moulues ; hacher finement un ruban de zeste et le mélanger avec le reste de l''ail.","Sécher le poulet en le tamponnant, l''assaisonner et le faire bien dorer dans l''huile chaude dans une cocotte en fonte, en plusieurs fois ; réserver.","Retirer la majeure partie de la graisse, puis faire suer l''oignon avec les rubans de zeste restants.","Incorporer la pâte d''épices environ 30 secondes, puis ajouter les carottes, le bouillon et le miel en grattant le fond de la cocotte.","Remettre le poulet et son jus, couvrir et laisser mijoter doucement jusqu''à ce qu''il soit tendre, environ 1 heure pour des cuisses (n''ajouter les morceaux de blanc que pour les 20 dernières minutes).","Retirer le poulet et le garder au chaud ; dégraisser la sauce, ajouter les olives et laisser mijoter jusqu''à ce qu''elle épaississe légèrement et que les carottes soient tendres.","Remettre le poulet, incorporer le mélange ail-zeste, la coriandre et le jus de citron, rectifier l''assaisonnement et servir."]},"it":{"title":"Tajine di pollo marocchino con olive e limone","steps":["Mescolare la maggior parte dell''aglio con tutte le spezie in polvere; tritare finemente una scorzetta di limone e mescolarla con l''aglio rimasto.","Asciugare bene il pollo tamponandolo, condirlo e rosolarlo bene nell''olio caldo in una pentola dal fondo spesso, poco per volta; tenere da parte.","Eliminare la maggior parte del grasso, poi far appassire la cipolla con le scorzette rimaste.","Unire la pasta di spezie per circa 30 secondi, poi aggiungere le carote, il brodo e il miele, raschiando il fondo della pentola.","Rimettere il pollo con i suoi succhi, coprire e cuocere a fuoco lento finché non è tenero, circa 1 ora per le cosce (aggiungere i pezzi di petto solo negli ultimi 20 minuti).","Togliere il pollo e tenerlo in caldo; sgrassare il sugo, aggiungere le olive e cuocere a fuoco lento finché non si addensa leggermente e le carote sono morbide.","Rimettere il pollo, unire il mix di aglio e scorza, il coriandolo e il succo di limone, regolare di sale e pepe e servire."]}}'::jsonb),
  ('89dd9707-0a47-4448-9592-cdae9bfb9fb4'::uuid, '{"fr":{"title":"Poulet rôti péruvien, sauce verte","steps":["Mixer les ingrédients de la marinade (huile, jus de citron vert, ail, sel, épices, origan, sucre) jusqu''à obtenir un mélange lisse.","Sécher le poulet, décoller la peau des blancs et des cuisses, glisser la majeure partie de la marinade dessous et frotter l''extérieur avec le reste.","Réfrigérer au moins 6 heures ou toute une nuit.","Préchauffer le four à 220 °C (425 °F) avec une grille entre le bas et le milieu ; poser le poulet sur une grille huilée au-dessus d''un plat tapissé de papier aluminium et ficeler les cuisses.","Rôtir 20 minutes jusqu''à ce qu''il soit doré, puis baisser à 190 °C (375 °F) et rôtir jusqu''à ce que le jus soit clair (environ 70 minutes pour une volaille de 1,8 kg, moins pour une plus petite) ; couvrir de papier aluminium s''il dore trop vite.","Mixer les jalapeños, la coriandre, l''ail, la mayonnaise, la crème fraîche, le jus de citron vert, le sel et le poivre, puis verser l''huile en filet sans arrêter le blender ; réfrigérer pour que la sauce épaississe.","Laisser reposer le poulet sous une feuille d''aluminium environ 20 minutes, le découper et servir avec la sauce verte."]},"it":{"title":"Pollo arrosto peruviano con salsa verde","steps":["Frullare gli ingredienti della marinata (olio, succo di lime, aglio, sale, spezie, origano, zucchero) fino a ottenere un composto liscio.","Asciugare il pollo, staccare la pelle su petto e cosce, infilarci sotto la maggior parte della marinata e massaggiare l''esterno con il resto.","Lasciare in frigorifero almeno 6 ore o tutta la notte.","Preriscaldare il forno a 220 °C (425 °F) con una griglia nella parte medio-bassa; sistemare il pollo su una griglia unta sopra una teglia foderata di alluminio e legare le cosce.","Arrostire 20 minuti finché non è dorato, poi abbassare a 190 °C (375 °F) e cuocere finché i succhi non escono limpidi (circa 70 minuti per un pollo da 1,8 kg, meno per uno più piccolo); coprire con alluminio se si colorisce troppo in fretta.","Frullare jalapeños, coriandolo, aglio, maionese, panna acida, succo di lime, sale e pepe, poi versare l''olio a filo con il frullatore in funzione; mettere in frigo per far addensare.","Far riposare il pollo coperto con alluminio per circa 20 minuti, tagliarlo e servire con la salsa verde."]}}'::jsonb),
  ('f0116db7-383f-4d62-870c-ab0b0417a431'::uuid, '{"fr":{"title":"Saumon poêlé à la harissa, chou-fleur et pois chiches","steps":["Mélanger la harissa et le miel ; réserver.","Dans un grand saladier, mélanger les pois chiches avec une partie de l''huile, le jus de citron et l''échalote.","Cuire le chou-fleur avec la majeure partie de la coriandre moulue, la moitié du sel et un peu plus d''huile dans une poêle antiadhésive couverte jusqu''à ce qu''il commence à ramollir, puis découvrir et cuire jusqu''à ce qu''il soit doré par endroits.","Ajouter le chou-fleur aux pois chiches avec les olives, la coriandre et la menthe ; garder au chaud et essuyer la poêle.","Assaisonner le saumon avec le reste de la coriandre moulue et du sel et le saisir, côté peau vers le haut, dans le reste de l''huile jusqu''à ce qu''il soit bien doré.","Retourner et cuire jusqu''à ce que le centre atteigne environ 50 °C (125 °F) pour une cuisson rosée.","Hors du feu, badigeonner les pavés de harissa au miel, remélanger les légumes, assaisonner et servir ensemble."]},"it":{"title":"Salmone scottato all''harissa con cavolfiore e ceci","steps":["Mescolare l''harissa con il miele; tenere da parte.","In una ciotola capiente condire i ceci con una parte dell''olio, il succo di limone e lo scalogno.","Cuocere il cavolfiore con la maggior parte del coriandolo in polvere, metà del sale e altro olio in una padella antiaderente coperta finché non inizia ad ammorbidirsi, poi scoprire e cuocere finché non è dorato qua e là.","Unire il cavolfiore ai ceci con le olive, il coriandolo e la menta; tenere in caldo e pulire la padella.","Condire il salmone con il resto del coriandolo in polvere e del sale e scottarlo, con il lato della pelle rivolto verso l''alto, nell''olio rimasto finché non è ben dorato.","Girarlo e cuocere finché il centro non raggiunge circa 50 °C (125 °F) per una cottura rosata.","A fuoco spento spennellare i filetti con l''harissa al miele, mescolare di nuovo le verdure, regolare di sale e servire insieme."]}}'::jsonb),
  ('a609b57d-8c52-4d05-a917-cc6e7675b365'::uuid, '{"fr":{"title":"Poulet braisé au xérès, chorizo et pois chiches","steps":["Retirer l''excès de gras des hauts de cuisse et couper chacun en 2-3 morceaux.","Assaisonner le poulet et le faire dorer des deux côtés dans la moitié de l''huile à feu vif ; le retirer.","Déglacer la poêle chaude avec le xérès en grattant les sucs, et verser le tout dans un pichet.","Baisser un peu le feu, ajouter le reste de l''huile avec le chorizo, l''oignon et l''ail, et cuire jusqu''à ce que l''oignon devienne translucide.","Remettre le xérès et le poulet avec le bouillon, les pois chiches, les poivrons, du sel et du poivre ; porter à frémissement.","Couvrir et cuire doucement environ 15 minutes jusqu''à ce que le poulet soit cuit à cœur.","Parsemer de persil haché."]},"it":{"title":"Pollo brasato allo sherry con chorizo e ceci","steps":["Eliminare il grasso in eccesso dalle sovracosce e tagliarle ciascuna in 2-3 pezzi.","Condire il pollo e rosolarlo su entrambi i lati in metà dell''olio a fuoco vivo; toglierlo dalla padella.","Sfumare la padella calda con lo sherry, raschiando il fondo di cottura, e versare il tutto in una caraffa.","Abbassare un po'' la fiamma, aggiungere il resto dell''olio con il chorizo, la cipolla e l''aglio e cuocere finché la cipolla non diventa trasparente.","Rimettere lo sherry e il pollo con il brodo, i ceci, i peperoni, sale e pepe; portare a sobbollire.","Coprire e cuocere dolcemente per circa 15 minuti finché il pollo non è cotto.","Completare con prezzemolo tritato."]}}'::jsonb),
  ('9a677bea-e590-4684-94e4-663476eb8ad3'::uuid, '{"fr":{"title":"Mafé de poulet","steps":["Faire suer l''oignon dans la moitié de l''huile environ 5 minutes, puis ajouter la patate douce et le poivron et cuire encore 10 minutes ; réserver.","Délayer au fouet le beurre de cacahuète dans le bouillon chaud jusqu''à obtenir un mélange lisse.","Cuire le riz selon les indications du paquet.","Faire chauffer le reste de l''huile et faire revenir le poulet avec l''ail, le gingembre, la coriandre moulue, le cumin et le piment environ 5 minutes, jusqu''à ce qu''il soit doré.","Remettre les légumes, verser le bouillon aux cacahuètes et laisser mijoter environ 20 minutes, jusqu''à ce que la sauce épaississe et que le poulet soit cuit à cœur.","Servir sur le riz, parsemé de feuilles de coriandre et de cacahuètes concassées."]},"it":{"title":"Stufato di pollo e arachidi dell''Africa occidentale","steps":["Far appassire la cipolla in metà dell''olio per circa 5 minuti, poi aggiungere la patata dolce e il peperone e cuocere altri 10 minuti; tenere da parte.","Stemperare il burro di arachidi nel brodo caldo con una frusta fino a ottenere un composto liscio.","Cuocere il riso seguendo le indicazioni della confezione.","Scaldare l''olio rimasto e rosolare il pollo con l''aglio, lo zenzero, il coriandolo in polvere, il cumino e il peperoncino per circa 5 minuti, finché non è dorato.","Rimettere le verdure, versare il brodo alle arachidi e cuocere a fuoco lento per circa 20 minuti, finché non si addensa e il pollo è cotto.","Servire sul riso, cosparso di foglie di coriandolo e arachidi tritate."]}}'::jsonb),
  ('a726112c-2fbf-49c6-b3bc-784875bbf69e'::uuid, '{"fr":{"title":"Çılbır (œufs à la turque au yaourt à l''ail)","steps":["Laisser le yaourt revenir à température ambiante (le sortir environ 30 minutes à l''avance).","Écraser l''ail avec une pincée de sel pour obtenir une pâte, l''incorporer au yaourt et étaler celui-ci dans deux assiettes.","Porter à ébullition une petite casserole d''eau salée additionnée du vinaigre.","Faire tourbillonner l''eau, y glisser un œuf et le pocher 2-3 minutes jusqu''à ce que le blanc soit pris mais que le jaune reste coulant ; recommencer avec le second.","Pendant ce temps, faire chauffer l''huile d''olive à feu doux à moyen, ajouter le pul biber, laisser infuser environ 30 secondes et retirer du feu.","Égoutter les œufs sur du papier absorbant, les déposer sur le yaourt, les arroser d''huile pimentée, saler et parsemer d''herbes.","Servir aussitôt avec du pain."]},"it":{"title":"Çılbır (uova alla turca con yogurt all''aglio)","steps":["Lasciare che lo yogurt arrivi a temperatura ambiente (tirarlo fuori dal frigo circa 30 minuti prima).","Schiacciare l''aglio con un pizzico di sale fino a ridurlo in pasta, mescolarlo allo yogurt e distribuirlo su due piatti.","Portare a bollore un pentolino di acqua salata con l''aceto.","Creare un vortice nell''acqua, farvi scivolare un uovo e cuocerlo in camicia per 2-3 minuti finché l''albume non si rapprende ma il tuorlo resta morbido; ripetere con il secondo.","Nel frattempo scaldare l''olio d''oliva a fuoco medio-basso, aggiungere il pul biber, lasciarlo in infusione per circa 30 secondi e togliere dal fuoco.","Scolare le uova su carta da cucina, adagiarle sullo yogurt, irrorarle con l''olio al peperoncino, salare e cospargere di erbe.","Servire subito con il pane."]}}'::jsonb),
  ('352bee18-6d6b-43cb-a91e-e71ac786c563'::uuid, '{"fr":{"title":"Adjaruli Khachapuri","steps":["Placer une pierre à pizza au milieu du four et préchauffer à 260 °C (500 °F) ; huiler un grand saladier.","Mélanger la levure, le sucre, l''huile, environ 80 ml d''eau tiède, la farine et le sel au crochet pétrisseur : 2-3 minutes à vitesse lente, puis 3-4 minutes à vitesse moyenne-lente, jusqu''à obtenir une pâte lisse et légèrement humide.","Mettre la pâte dans le saladier huilé, couvrir et laisser dans un endroit tiède 50-60 minutes, jusqu''à ce qu''elle ait presque doublé de volume.","Mélanger la mozzarella et la feta ; casser l''œuf dans une petite tasse en gardant le jaune entier.","Façonner la pâte en boule, couvrir sans serrer et laisser reposer 15 minutes.","Sur du papier cuisson fariné, étaler la pâte en un disque de 25 cm d''environ 3 mm d''épaisseur, répartir la moitié du fromage en laissant une petite bordure, rouler deux côtés opposés vers l''intérieur puis pincer et torsader les extrémités pour former une barque ; garnir le centre avec le reste du fromage.","Laisser reposer à découvert 15 minutes pour qu''elle gonfle légèrement, badigeonner les bords d''huile et la faire glisser sur la pierre chaude.","Cuire 14-16 minutes jusqu''à ce qu''elle soit légèrement dorée et le fromage fondu, verser l''œuf au centre et cuire encore 3-4 minutes jusqu''à ce que le blanc soit tout juste pris.","Parsemer de noisettes de beurre et servir chaud, en mélangeant l''œuf et le beurre au fromage à table."]},"it":{"title":"Adjaruli Khachapuri","steps":["Mettere una pietra refrattaria al centro del forno e preriscaldare a 260 °C (500 °F); ungere d''olio una ciotola capiente.","Impastare lievito, zucchero, olio, circa 80 ml di acqua tiepida, farina e sale con il gancio: 2-3 minuti a velocità bassa, poi 3-4 minuti a velocità medio-bassa, finché l''impasto non è liscio e leggermente umido.","Mettere l''impasto nella ciotola unta, coprire e lasciar lievitare in un luogo tiepido per 50-60 minuti, finché non è quasi raddoppiato.","Mescolare la mozzarella e la feta; rompere l''uovo in una tazzina, mantenendo il tuorlo intero.","Formare una palla con l''impasto, coprirla senza stringere e lasciar riposare 15 minuti.","Su carta da forno infarinata, stendere l''impasto in un disco di 25 cm spesso circa 3 mm, distribuire metà del formaggio lasciando un piccolo bordo, arrotolare verso l''interno due lati opposti e pizzicare e attorcigliare le estremità formando una barchetta; riempire il centro con il formaggio rimasto.","Lasciare scoperto per 15 minuti perché si gonfi leggermente, spennellare i bordi con l''olio e farlo scivolare sulla pietra calda.","Cuocere 14-16 minuti finché non è leggermente dorato e il formaggio è fuso, versare l''uovo al centro e cuocere altri 3-4 minuti finché l''albume non si è appena rappreso.","Distribuire il burro a pezzetti e servire caldo, mescolando a tavola l''uovo e il burro al formaggio."]}}'::jsonb),
  ('b4a417db-84c5-4375-9e34-ed701092ccaa'::uuid, '{"fr":{"title":"Poutine canadienne","steps":["Préparer la sauce brune selon les instructions du sachet et la maintenir chaude à feu doux.","Faire frire les frites dans l''huile à 350 °F (175 °C) jusqu''à ce qu''elles soient dorées et croustillantes.","Égoutter les frites sur une plaque tapissée de papier absorbant.","Répartir les frites dans les assiettes, parsemer de fromage en grains et napper de sauce chaude à la louche.","Déguster aussitôt, pendant que le fromage commence tout juste à fondre."]},"it":{"title":"Poutine canadese","steps":["Preparare la salsa gravy secondo le istruzioni della confezione e tenerla calda a fuoco basso.","Friggere le patatine in olio a 350 °F (175 °C) finché sono dorate e croccanti.","Scolare le patatine su un vassoio foderato di carta assorbente.","Disporre le patatine nei piatti, distribuirvi sopra la cagliata di formaggio a pezzetti e versare con un mestolo la salsa calda.","Mangiare subito, mentre la cagliata inizia appena a sciogliersi."]}}'::jsonb),
  ('292f619c-527e-4bce-8623-235114ca29bf'::uuid, '{"en":{"title":"Homemade croque-monsieur","steps":["Melt the butter in a saucepan, add the flour, then gradually pour in the milk while whisking to make a smooth béchamel.","Let it thicken, season with salt, pepper and nutmeg, then take off the heat.","Melt half the Emmental into the hot béchamel.","Butter one side of each slice of bread; on the unbuttered side of half the slices, spread a little béchamel, add the ham and a little cheese, then close the sandwiches.","Brown the sandwiches in a frying pan for 3 to 4 min on each side.","Place them on a baking tray lined with baking paper, coat with the rest of the béchamel and sprinkle with the remaining cheese.","Put under the grill for about 5 min until the top is golden and bubbling, and serve immediately with a salad."]},"it":{"title":"Croque-monsieur fatto in casa","steps":["Sciogliere il burro in un pentolino, aggiungere la farina, poi versare il latte poco alla volta mescolando con la frusta per ottenere una besciamella liscia.","Lasciare addensare, condire con sale, pepe e noce moscata, poi togliere dal fuoco.","Far sciogliere metà dell''emmental nella besciamella calda.","Imburrare un lato di ogni fetta di pane; sul lato non imburrato di metà delle fette spalmare un po'' di besciamella, adagiare il prosciutto cotto e un po'' di formaggio, poi chiudere.","Dorare i toast in padella per 3-4 min per lato.","Disporli su una teglia rivestita di carta forno, nappare con la besciamella rimasta e cospargere con il formaggio restante.","Passare sotto il grill per circa 5 min finché la superficie è gratinata e servire subito con un''insalata."]}}'::jsonb),
  ('6ca01774-0338-4521-8c4e-9940cb329731'::uuid, '{"fr":{"title":"Fish and chips","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Couper les pommes de terre, avec la peau, en grosses frites.","Blanchir les frites 2 à 3 minutes, bien les égoutter et les laisser sécher en laissant s''échapper la vapeur.","Les mélanger avec l''huile végétale dans un plat à rôtir et les cuire au four 25 à 30 minutes, en les retournant une fois, jusqu''à ce qu''elles soient dorées.","Environ 15 minutes avant la fin de cuisson des frites, chauffer l''huile d''olive dans une grande poêle à fond épais et fariner le cabillaud.","Faire cuire le cabillaud côté peau 4 à 5 minutes, le retourner et poursuivre la cuisson 5 à 6 minutes, jusqu''à ce qu''il commence tout juste à s''effeuiller (terminer les morceaux très épais 5 minutes au four) ; le disposer sur des assiettes chaudes.","Dans la même poêle, faire grésiller les cornichons et les câpres 1 minute, ajouter le jus de citron et laisser bouillonner 30 secondes à feu vif, puis retirer du feu et incorporer les herbes.","Garnir chaque filet d''une cuillerée de mayonnaise et du mélange aux câpres, et servir avec les frites."]},"it":{"title":"Fish and chips","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Tagliare le patate, con la buccia, a bastoncini spessi.","Sbollentare le patate 2-3 minuti, scolarle bene e lasciarle asciugare al vapore.","Condirle con l''olio di semi in una teglia e arrostirle 25-30 minuti, girandole una volta, finché sono dorate.","Circa 15 minuti prima che le patate siano pronte, scaldare l''olio d''oliva in una padella grande dal fondo spesso e infarinare il merluzzo.","Cuocere il merluzzo dal lato della pelle per 4-5 minuti, girarlo e cuocere altri 5-6 minuti finché inizia appena a sfaldarsi (terminare i pezzi molto spessi in forno per 5 minuti); trasferirlo su piatti caldi.","Nella stessa padella far sfrigolare i cetriolini e i capperi per 1 minuto, aggiungere il succo di limone e far bollire 30 secondi a fuoco vivo, poi togliere dal fuoco e unire le erbe.","Completare ogni filetto con un cucchiaio di maionese e il composto di capperi e servire con le patate."]}}'::jsonb),
  ('8bd9287e-0b96-4c35-8e0b-c23f0212da32'::uuid, '{"fr":{"title":"Poulet frit coréen (Yangnyeom-tongdak)","steps":["Chauffer environ 5 cm d''huile dans une cocotte à fond épais sur feu moyen-vif pendant 10 à 12 minutes, jusqu''à 165-175 °C ; un morceau de poulet test doit grésiller immédiatement.","Dans un grand saladier, mélanger les ailes à la main avec le sel, le poivre, la fécule, la farine, le bicarbonate et les œufs jusqu''à ce qu''elles soient uniformément enrobées.","Plonger le poulet dans l''huile morceau par morceau (en plusieurs fois si nécessaire) et frire environ 12 minutes, en retournant, jusqu''à ce qu''il soit doré et croustillant.","Déposer les ailes dans une passoire grillagée posée sur un saladier pour les égoutter.","Pour la sauce, chauffer l''huile dans une grande poêle, faire revenir l''ail environ 30 secondes jusqu''à ce qu''il soit légèrement doré, incorporer le ketchup, le sirop de riz, le gochujang et le vinaigre, puis laisser mijoter à feu doux jusqu''à ce que la sauce bouillonne et retirer du feu.","Laisser l''huile de friture remonter en température (environ 2 minutes) et frire les ailes une seconde fois environ 12 minutes, jusqu''à ce qu''elles soient bien croustillantes.","Refaire bouillonner la sauce sur feu moyen-vif, ajouter les ailes chaudes et mélanger jusqu''à ce qu''elles soient bien laquées.","Parsemer de graines de sésame et servir, idéalement avec du radis mariné."]},"it":{"title":"Pollo fritto coreano (Yangnyeom-tongdak)","steps":["Scaldare circa 5 cm di olio in una pentola dal fondo spesso a fuoco medio-alto per 10-12 minuti, fino a 165-175 °C; un pezzetto di pollo di prova deve sfrigolare subito.","In una ciotola capiente mescolare con le mani le ali con sale, pepe, fecola, farina, bicarbonato e uova finché sono ricoperte in modo uniforme.","Immergere il pollo nell''olio un pezzo alla volta (a più riprese se necessario) e friggere circa 12 minuti, girando, finché è dorato e croccante.","Trasferire le ali in un colino a rete appoggiato su una ciotola per farle sgocciolare.","Per la salsa, scaldare l''olio in una padella grande, soffriggere l''aglio circa 30 secondi finché è leggermente dorato, unire ketchup, sciroppo di riso, gochujang e aceto, poi cuocere a fuoco basso finché sobbolle e togliere dal fuoco.","Riportare l''olio di frittura in temperatura (circa 2 minuti) e friggere le ali una seconda volta per circa 12 minuti finché sono croccantissime.","Riportare la salsa a bollore a fuoco medio-alto, aggiungere le ali calde e saltarle finché sono lucide.","Cospargere di semi di sesamo e servire, possibilmente con ravanello in salamoia."]}}'::jsonb),
  ('42b2a8e9-670f-4c85-8abe-400bc2463633'::uuid, '{"en":{"title":"Green lasagne Bolognese","steps":["Heat the oil and butter in a saucepan and brown the mince over low heat for about 10 minutes.","Turn up the heat, pour in the white wine and let it evaporate completely.","Add the sieved peeled tomatoes and the basil, then cook for about 1 and a half hours with the lid ajar.","Meanwhile, cook the spinach in a covered pan for 5 minutes without seasoning, drain, let cool and squeeze well in a tea towel.","Blend the spinach, add the two flours, the egg, the yolk and a pinch of salt and knead into a dough; wrap in cling film and let rest for 30 minutes.","For the béchamel, melt the butter, toast the flour into a golden roux, then pour in the hot milk a little at a time, stirring; season with salt and nutmeg.","Roll the pasta out very thin (about half a millimetre) and cut into rectangles.","Blanch the sheets for 30 seconds in salted water with a drizzle of oil, cool them in cold water and dry them on a tea towel.","In a buttered baking dish, alternate pasta sheets, béchamel, ragù and Parmesan for 5 layers, finishing with béchamel and Parmesan.","Bake in a preheated oven at 170 °C for 40 minutes."]},"fr":{"title":"Lasagnes vertes à la bolognaise","steps":["Chauffer l''huile et le beurre dans une casserole et faire revenir la viande hachée à feu doux pendant environ 10 minutes.","Augmenter le feu, déglacer au vin blanc et le laisser s''évaporer complètement.","Ajouter les tomates pelées passées et le basilic, puis cuire environ 1 heure et demie avec le couvercle posé en biais.","Pendant ce temps, cuire les épinards dans une casserole couverte 5 minutes sans assaisonnement, les égoutter, les laisser refroidir et bien les essorer dans un torchon.","Mixer les épinards, ajouter les deux farines, l''œuf, le jaune et une pincée de sel et pétrir ; envelopper de film alimentaire et laisser reposer 30 minutes.","Pour la béchamel, faire fondre le beurre, faire blondir la farine jusqu''à obtenir un roux doré, puis verser le lait chaud en plusieurs fois en remuant ; saler et parfumer à la muscade.","Abaisser la pâte très finement (environ un demi-millimètre) et la découper en rectangles.","Blanchir les feuilles 30 secondes dans de l''eau salée avec un filet d''huile, les rafraîchir dans l''eau froide et les sécher sur un torchon.","Dans un plat beurré, alterner pâte, béchamel, sauce bolognaise et parmesan sur 5 couches, en terminant par béchamel et parmesan.","Enfourner dans le four préchauffé à 170 °C pendant 40 minutes."]}}'::jsonb),
  ('0d73508c-6359-434b-bd0d-9ba7e7c3440d'::uuid, '{"en":{"title":"Skillet aubergine parmigiana","steps":["Wash the aubergines, remove the stalk and slice them.","Place them in a colander, sprinkle with salt and leave to drain for about 1 hour.","Meanwhile, heat a tablespoon of oil with the passata and a little water, season with salt and cook over low heat for 10 minutes; add the basil and turn off the heat.","Rinse the aubergines and gently squeeze them.","Grill them a few at a time on a lightly oiled nonstick griddle until soft and marked.","In a 24 cm nonstick frying pan, alternate layers of aubergine, sauce, Parmesan and mozzarella until the ingredients are used up.","Cover and cook over medium-low heat for 20-25 minutes until the mozzarella has melted."]},"fr":{"title":"Parmigiana d''aubergines à la poêle","steps":["Laver les aubergines, retirer le pédoncule et les couper en tranches.","Les disposer dans une passoire, les saupoudrer de sel et les laisser dégorger environ 1 heure.","Pendant ce temps, chauffer une cuillère à soupe d''huile avec le coulis de tomate et un peu d''eau, saler et cuire à feu doux 10 minutes ; ajouter le basilic et éteindre le feu.","Rincer les aubergines et les presser délicatement.","Les griller quelques-unes à la fois sur une poêle-gril antiadhésive légèrement huilée jusqu''à ce qu''elles soient tendres et marquées.","Dans une poêle antiadhésive de 24 cm, alterner des couches d''aubergines, de sauce, de parmesan et de mozzarella jusqu''à épuisement des ingrédients.","Couvrir et cuire à feu moyen-doux 20 à 25 minutes, jusqu''à ce que la mozzarella soit fondue."]}}'::jsonb),
  ('ebf5318c-01b3-4cdd-98d9-9e16ab0442f6'::uuid, '{"fr":{"title":"Okonomiyaki aux crevettes","steps":["Fouetter ensemble le ketchup, la sauce Worcestershire, la sauce d''huître et le sucre pour obtenir la sauce okonomiyaki.","Mélanger la farine, la levure chimique et le sel dans un grand saladier, incorporer le bouillon et les œufs en battant, puis ajouter délicatement le chou et la plus grande partie des oignons nouveaux.","Chauffer la moitié de l''huile dans une poêle antiadhésive munie d''un couvercle sur feu moyen et y verser à la cuillère la moitié de la pâte en un disque épais d''environ 15 cm de diamètre ; ne pas l''aplatir.","Enfoncer la moitié des crevettes sur le dessus, couvrir et cuire 3 à 5 minutes, jusqu''à ce que la galette soit prise et dorée en dessous.","Retourner, couvrir à nouveau et cuire encore 3 à 5 minutes, jusqu''à ce qu''elle soit dorée et cuite à cœur ; prolonger d''une minute de chaque côté si nécessaire.","Faire glisser sur une assiette, arroser de mayonnaise et de sauce, parsemer d''oignons nouveaux et servir avec le gingembre mariné.","Recommencer avec le reste d''huile, de pâte et de crevettes pour la deuxième galette."]},"it":{"title":"Okonomiyaki di gamberi","steps":["Mescolare con una frusta ketchup, salsa Worcestershire, salsa d''ostriche e zucchero per ottenere la salsa okonomiyaki.","Riunire farina, lievito e sale in una ciotola capiente, incorporare sbattendo il brodo e le uova, poi unire delicatamente il cavolo e gran parte dei cipollotti.","Scaldare metà dell''olio in una padella antiaderente con coperchio a fuoco medio e versarvi a cucchiaiate metà della pastella formando un disco spesso di circa 15 cm di diametro; non schiacciarlo.","Affondare metà dei gamberi sulla superficie, coprire e cuocere 3-5 minuti finché è rappreso e dorato sotto.","Girare, coprire di nuovo e cuocere altri 3-5 minuti finché è dorato e cotto all''interno; se necessario, prolungare di un minuto per lato.","Farlo scivolare su un piatto, condire con un filo di maionese e di salsa, cospargere di cipollotti e servire con lo zenzero marinato.","Ripetere con l''olio, la pastella e i gamberi rimasti per la seconda frittella."]}}'::jsonb),
  ('badc30ce-6a6a-450a-9bcf-5e4afcf32573'::uuid, '{"fr":{"title":"Rösti aux œufs au plat","steps":["Râper grossièrement les pommes de terre, crues ou cuites et refroidies.","Couper finement en dés la moitié de l''oignon et l''incorporer aux pommes de terre, en assaisonnant si on le souhaite.","Faire fondre du beurre dans une grande poêle à feu vif, ajouter le mélange de pommes de terre et remuer quelques minutes jusqu''à ce qu''il soit bien chaud.","Baisser à feu moyen-vif et presser le mélange en une galette ronde et plate d''environ 1 à 1,5 cm d''épaisseur.","Glisser un peu de beurre supplémentaire sur le pourtour et cuire 5 à 10 minutes, jusqu''à ce qu''une croûte se forme en dessous.","Pendant ce temps, couper en dés le reste de l''oignon et la carotte et les cuire à la vapeur avec les petits pois (ou les épinards) dans un peu d''eau, à couvert.","Retourner le rösti sur une assiette, le faire glisser de nouveau dans la poêle et le cuire à feu moyen-doux jusqu''à ce que la deuxième face soit croustillante.","Retirer le rösti, faire cuire les œufs au plat dans la même poêle et les servir dessus, avec les légumes à côté."]},"it":{"title":"Rösti con uova al tegamino","steps":["Grattugiare grossolanamente le patate, crude oppure lessate e raffreddate.","Tritare finemente metà della cipolla e unirla alle patate, condendo a piacere.","Sciogliere il burro in una padella grande a fuoco vivo, aggiungere il composto di patate e mescolare per qualche minuto finché è ben caldo.","Abbassare a fuoco medio-alto e pressare il composto in un disco piatto spesso circa 1-1,5 cm.","Far scivolare ancora un po'' di burro lungo il bordo e cuocere 5-10 minuti finché sotto si forma una crosticina.","Nel frattempo tagliare a dadini la cipolla rimasta e la carota e cuocerle al vapore con i piselli (o gli spinaci) in poca acqua con il coperchio.","Rovesciare il rösti su un piatto, farlo scivolare di nuovo nella padella e cuocere a fuoco medio-basso finché anche il secondo lato è croccante.","Togliere il rösti, cuocere le uova al tegamino nella stessa padella e servirle sopra, con le verdure a parte."]}}'::jsonb),
  ('72695646-987b-4eed-9407-29049d511fea'::uuid, '{"en":{"title":"Traditional tartiflette","steps":["Fry the sliced onion and chopped garlic in a drizzle of oil until translucent, then set aside.","Brown the lardons in the same pan, return the onion and garlic, then deglaze with the white wine.","Let the wine evaporate completely, transfer to a bowl and stir in the crème fraîche, salt, pepper and nutmeg.","Put the peeled potatoes in cold salted water and cook for about 15 min: they should stay slightly firm.","Cut the potatoes into thin slices.","Rub a buttered gratin dish with garlic, then alternate layers of potato and the lardon mixture.","Scrape the rind of the reblochon, cut it into pieces and lay them rind-side up on top.","Bake at 180 °C for 30 to 35 min, until the cheese is melted and golden, and serve piping hot."]},"it":{"title":"Tartiflette tradizionale","steps":["Soffriggere la cipolla affettata e l''aglio tritato in un filo d''olio finché diventano traslucidi, poi tenerli da parte.","Rosolare la pancetta nella stessa padella, rimettere cipolla e aglio, poi sfumare con il vino bianco.","Lasciare evaporare completamente il vino, versare in una ciotola e incorporare la panna, il sale, il pepe e la noce moscata.","Mettere le patate sbucciate in acqua fredda salata e cuocerle circa 15 min: devono rimanere un po'' sode.","Tagliare le patate a rondelle sottili.","Strofinare una pirofila imburrata con l''aglio, poi alternare strati di patate e di composto di pancetta.","Raschiare la crosta del reblochon, tagliarlo a pezzi e adagiarli sopra con la crosta rivolta verso l''alto.","Infornare a 180 °C per 30-35 min, finché il formaggio è fuso e dorato, e servire ben caldo."]}}'::jsonb),
  ('44f8d889-4d68-471f-a12e-050437c6f2d4'::uuid, '{"fr":{"title":"Poulet street food new-yorkais sur riz","steps":["Mélanger le poulet avec le cumin, la coriandre moulue, l''origan, la moitié du curcuma, 1 gousse d''ail, le jus d''un demi-citron, 1 c. à soupe d''huile, du sel et du poivre. Laisser reposer 10 min.","Rincer le riz. Le faire revenir 1 min dans un peu d''huile avec le reste du curcuma, ajouter le bouillon, couvrir et laisser mijoter 12 min ; laisser reposer 5 min hors du feu.","Pendant ce temps, cuire le poulet dans une poêle chaude avec un peu d''huile, 5 à 6 min de chaque côté, jusqu''à ce qu''il soit grillé et cuit à cœur. Laisser reposer, puis le couper en bouchées.","Mélanger le yaourt, la mayonnaise, le vinaigre, le reste de l''ail, un filet de citron, du sel et du poivre pour préparer la sauce blanche.","Servir le riz garni de poulet, de laitue et de tomate, arrosé de sauce blanche et de sauce piquante."]},"it":{"title":"Pollo street food newyorkese con riso","steps":["Condire il pollo con cumino, coriandolo in polvere, origano, metà della curcuma, 1 spicchio d''aglio, il succo di mezzo limone, 1 cucchiaio d''olio, sale e pepe. Lasciare riposare 10 min.","Sciacquare il riso. Tostarlo 1 min in un filo d''olio con la curcuma rimasta, aggiungere il brodo, coprire e cuocere a fuoco lento 12 min; lasciare riposare 5 min fuori dal fuoco.","Nel frattempo cuocere il pollo in una padella ben calda con un filo d''olio, 5-6 min per lato, finché è abbrustolito e cotto all''interno. Lasciarlo riposare, poi tagliarlo a bocconcini.","Mescolare lo yogurt, la maionese, l''aceto, l''aglio rimasto, una spruzzata di limone, sale e pepe per preparare la salsa bianca.","Servire il riso con sopra il pollo, la lattuga e il pomodoro, condito con la salsa bianca e la salsa piccante."]}}'::jsonb),
  ('83f42f74-df4c-4c45-be95-fa38674d1b1c'::uuid, '{"fr":{"title":"Bol de riz au saumon gochujang","steps":["Cuire le riz selon les instructions du paquet.","Mélanger le concombre avec le vinaigre de riz, une pincée de sel et une pincée de sucre ; réserver pour le faire mariner rapidement.","Mélanger le gochujang, la sauce soja, le miel et l''huile de sésame. Enrober le saumon avec la moitié du mélange.","Cuire les edamames 3 min dans l''eau bouillante, puis les égoutter.","Saisir le saumon dans une poêle chaude avec un peu d''huile 3 à 4 min en le retournant, puis ajouter le reste du glaçage et mélanger 30 s jusqu''à ce qu''il soit bien laqué.","Garnir les bols de riz, de saumon, de concombre, d''edamames et de carotte. Parsemer d''oignon nouveau et de graines de sésame."]},"it":{"title":"Ciotola di riso con salmone al gochujang","steps":["Cuocere il riso secondo le istruzioni della confezione.","Condire il cetriolo con l''aceto di riso, un pizzico di sale e un pizzico di zucchero; tenere da parte per una marinatura veloce.","Mescolare gochujang, salsa di soia, miele e olio di sesamo. Condire il salmone con metà della salsa.","Cuocere gli edamame in acqua bollente per 3 min, poi scolarli.","Scottare il salmone in una padella ben calda con un filo d''olio per 3-4 min, girandolo, poi aggiungere la glassa rimasta e saltare 30 s finché è ben laccato.","Riempire le ciotole con riso, salmone, cetriolo, edamame e carota. Completare con cipollotto e semi di sesamo."]}}'::jsonb),
  ('6f72d2b5-6a40-4b91-bf03-6c6a3cb4b4fb'::uuid, '{"fr":{"title":"Pasta e ceci","steps":["Faire revenir doucement l''oignon dans 2 c. à soupe d''huile d''olive pendant 5 min. Ajouter l''ail, le romarin et le piment pendant 1 min, puis incorporer le concentré de tomate.","Ajouter les pois chiches et le bouillon et laisser mijoter 10 min. Retirer le romarin et écraser ou mixer environ un tiers des pois chiches pour épaissir.","Ajouter les pâtes et les cuire dans la soupe, en remuant souvent, jusqu''à ce qu''elles soient al dente (ajouter un peu d''eau si cela devient trop épais).","Assaisonner, puis servir avec le parmesan, du poivre noir et un filet d''huile d''olive."]},"it":{"title":"Pasta e ceci","steps":["Soffriggere dolcemente la cipolla in 2 cucchiai d''olio d''oliva per 5 min. Aggiungere aglio, rosmarino e peperoncino per 1 min, poi incorporare il concentrato di pomodoro.","Unire i ceci e il brodo e cuocere a fuoco lento 10 min. Togliere il rosmarino e schiacciare o frullare circa un terzo dei ceci per addensare.","Aggiungere la pasta e cuocerla nella minestra, mescolando spesso, finché è al dente (aggiungere un goccio d''acqua se diventa troppo densa).","Regolare di sale, poi servire con il parmigiano, pepe nero e un filo d''olio d''oliva."]}}'::jsonb),
  ('921fc083-e3e0-43a0-a015-814ba0a3fa48'::uuid, '{"fr":{"title":"Poulet basquaise","steps":["Assaisonner le poulet et le faire dorer côté peau dans un peu d''huile dans une cocotte, 6 à 7 min, puis le retourner 2 min. Réserver.","Dans la même cocotte, faire revenir l''oignon, les poivrons et le jambon 8 min jusqu''à ce qu''ils soient tendres. Ajouter l''ail et le piment d''Espelette pendant 1 min.","Déglacer au vin, puis ajouter les tomates, le laurier et le thym. Remettre le poulet, peau vers le haut.","Couvrir et laisser mijoter doucement 25 min, puis découvrir pendant les 5 dernières minutes pour faire épaissir la sauce.","Pendant ce temps, cuire le riz. Servir le poulet et les poivrons sur le riz."]},"it":{"title":"Pollo alla basca","steps":["Salare e pepare il pollo e rosolarlo dal lato della pelle in un filo d''olio in una casseruola, 6-7 min, poi girarlo per 2 min. Tenere da parte.","Nella stessa casseruola cuocere la cipolla, i peperoni e il prosciutto per 8 min finché sono morbidi. Aggiungere l''aglio e il peperoncino di Espelette per 1 min.","Sfumare con il vino, poi aggiungere i pomodori, l''alloro e il timo. Rimettere il pollo con la pelle verso l''alto.","Coprire e cuocere a fuoco lento 25 min, poi scoprire negli ultimi 5 min per far addensare il sugo.","Nel frattempo cuocere il riso. Servire il pollo e i peperoni sul riso."]}}'::jsonb),
  ('7375c699-23ee-487c-9121-73adc3d46728'::uuid, '{"fr":{"title":"Shawarma de poulet au four","steps":["Préchauffer le four à 220 °C. Mélanger les épices, 2 gousses d''ail, le jus d''un demi-citron, 2 c. à soupe d''huile et du sel.","Enrober le poulet et les quartiers d''oignon de marinade et les étaler en une seule couche sur une plaque.","Rôtir 25 à 30 min, jusqu''à ce que le poulet soit grillé sur les bords. Laisser reposer 5 min, puis trancher.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et du sel.","Mélanger la tomate, le concombre et le persil avec du jus de citron et de l''huile. Servir le poulet et les oignons avec les pains pita, le yaourt à l''ail et la salade."]},"it":{"title":"Shawarma di pollo in teglia","steps":["Scaldare il forno a 220 °C. Mescolare le spezie, 2 spicchi d''aglio, il succo di mezzo limone, 2 cucchiai d''olio e sale.","Condire il pollo e gli spicchi di cipolla con la marinata e distribuirli su una teglia in un solo strato.","Arrostire 25-30 min finché il pollo è abbrustolito ai bordi. Lasciare riposare 5 min, poi affettare.","Mescolare lo yogurt con l''aglio rimasto, una spruzzata di limone e sale.","Condire pomodoro, cetriolo e prezzemolo con succo di limone e olio. Servire il pollo e le cipolle con il pane pita, lo yogurt all''aglio e l''insalata."]}}'::jsonb),
  ('7ccb7672-07ff-4746-b7b9-165af1682c26'::uuid, '{"fr":{"title":"Tacos de dinde en feuilles de laitue","steps":["Faire revenir l''oignon dans 1 c. à café d''huile pendant 3 min. Ajouter la dinde et la faire dorer en l''émiettant, 5 à 6 min.","Incorporer l''ail, le chipotle, le cumin, le paprika et le concentré de tomate pendant 1 min, puis ajouter les haricots et un peu d''eau. Laisser mijoter 2 min jusqu''à obtenir une texture nappante.","Assaisonner de sel et du jus d''un demi-citron vert.","Répartir la garniture dans les feuilles de laitue et garnir de tomate, d''avocat, de yaourt, de coriandre et de quartiers de citron vert."]},"it":{"title":"Tacos di tacchino in foglie di lattuga","steps":["Soffriggere la cipolla in 1 cucchiaino d''olio per 3 min. Aggiungere il tacchino e rosolarlo sgranandolo, 5-6 min.","Unire aglio, chipotle, cumino, paprika e concentrato di pomodoro per 1 min, poi aggiungere i fagioli e un goccio d''acqua. Cuocere a fuoco lento 2 min finché si forma un sughetto.","Insaporire con sale e il succo di mezzo lime.","Distribuire il ripieno nelle foglie di lattuga e completare con pomodoro, avocado, yogurt, coriandolo e spicchi di lime."]}}'::jsonb),
  ('d31d3553-44c2-493a-ae47-a5ef771dfc03'::uuid, '{"fr":{"title":"Chana masala","steps":["Lancer la cuisson du riz selon les instructions du paquet.","Chauffer 2 c. à soupe d''huile et faire grésiller les graines de cumin 30 s. Ajouter l''oignon et cuire 8 min jusqu''à ce qu''il soit doré.","Ajouter l''ail, le gingembre et le piment pendant 1 min, puis les épices moulues pendant 30 s.","Ajouter les tomates et cuire 5 min jusqu''à ce que la sauce épaississe, puis les pois chiches et 150 ml d''eau. Laisser mijoter 10 min en écrasant légèrement quelques pois chiches.","Assaisonner de sel et de jus de citron, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Chana masala","steps":["Mettere a cuocere il riso secondo le istruzioni della confezione.","Scaldare 2 cucchiai d''olio e far sfrigolare i semi di cumino per 30 s. Aggiungere la cipolla e cuocere 8 min finché è dorata.","Aggiungere aglio, zenzero e peperoncino per 1 min, poi le spezie in polvere per 30 s.","Unire i pomodori e cuocere 5 min finché si addensano, poi i ceci e 150 ml d''acqua. Cuocere a fuoco lento 10 min, schiacciando leggermente una parte dei ceci.","Insaporire con sale e succo di limone, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('bfa142e0-6a9e-458a-b320-536bf8aa8e76'::uuid, '{"fr":{"title":"Donburi de poulet teriyaki","steps":["Cuire le riz. Mélanger la sauce soja, le mirin, le saké et le sucre.","Cuire le brocoli à la vapeur ou à l''eau 3 à 4 min.","Cuire le poulet côté peau dans un peu d''huile à feu moyen 7 min jusqu''à ce qu''il soit croustillant, puis le retourner et poursuivre la cuisson 4 min.","Retirer l''excédent de graisse, verser la sauce et laisser mijoter 1 à 2 min en retournant le poulet jusqu''à ce qu''il soit bien laqué.","Trancher le poulet et le servir sur le riz avec le brocoli, un peu plus de sauce, l''oignon nouveau et le sésame."]},"it":{"title":"Donburi di pollo teriyaki","steps":["Cuocere il riso. Mescolare salsa di soia, mirin, sake e zucchero.","Cuocere i broccoli al vapore o lessarli per 3-4 min.","Cuocere il pollo dal lato della pelle in un filo d''olio a fuoco medio per 7 min finché è croccante, poi girarlo e cuocere altri 4 min.","Eliminare il grasso in eccesso, versare la salsa e cuocere a fuoco lento 1-2 min, girando il pollo finché è lucido.","Affettare il pollo e servirlo sul riso con i broccoli, altra salsa, il cipollotto e il sesamo."]}}'::jsonb),
  ('cf55fbb6-d6f4-4ed9-a1f1-b5675ef81fa4'::uuid, '{"fr":{"title":"Shakshuka à la feta","steps":["Faire revenir l''oignon et le poivron dans 2 c. à soupe d''huile d''olive pendant 8 min jusqu''à ce qu''ils soient tendres.","Ajouter l''ail et les épices pendant 1 min, puis les tomates. Laisser mijoter 6 à 8 min jusqu''à épaississement ; assaisonner.","Creuser 5 puits dans la sauce et y casser les œufs. Couvrir et cuire à feu doux 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de feta et de persil et servir directement dans la poêle avec du pain."]},"it":{"title":"Shakshuka con feta","steps":["Cuocere la cipolla e il peperone in 2 cucchiai d''olio d''oliva per 8 min finché sono morbidi.","Aggiungere aglio e spezie per 1 min, poi i pomodori. Cuocere a fuoco lento 6-8 min finché il sugo si addensa; regolare di sale e pepe.","Formare 5 incavi nel sugo e rompervi dentro le uova. Coprire e cuocere a fuoco basso 5-7 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere di feta e prezzemolo e servire direttamente nella padella con il pane."]}}'::jsonb),
  ('22aa9226-5726-4893-ab82-6cb10720509d'::uuid, '{"fr":{"title":"Sauté de bœuf au brocoli","steps":["Cuire le riz. Mélanger le bœuf avec 1 c. à café de fécule de maïs et 1 c. à soupe de sauce soja.","Préparer la sauce : 2 c. à soupe de sauce soja, la sauce d''huître, le sucre, l''huile de sésame, 1 c. à café de fécule de maïs et 80 ml d''eau.","Chauffer un wok jusqu''à ce qu''il fume, ajouter 1 c. à soupe d''huile et saisir le bœuf en une seule couche, 1 à 2 min, sans trop le cuire. Le retirer.","Ajouter un peu d''huile, le brocoli et 2 c. à soupe d''eau ; faire sauter 3 min jusqu''à ce qu''il soit bien vert et juste tendre. Ajouter l''ail et le gingembre pendant 30 s.","Remettre le bœuf, verser la sauce et mélanger 1 min jusqu''à ce que ce soit bien brillant. Servir sur le riz."]},"it":{"title":"Manzo e broccoli saltati al wok","steps":["Cuocere il riso. Condire il manzo con 1 cucchiaino di amido di mais e 1 cucchiaio di salsa di soia.","Preparare la salsa: 2 cucchiai di salsa di soia, salsa d''ostriche, zucchero, olio di sesamo, 1 cucchiaino di amido di mais e 80 ml d''acqua.","Scaldare il wok finché fuma, aggiungere 1 cucchiaio d''olio e scottare il manzo in un solo strato, 1-2 min, senza cuocerlo troppo. Toglierlo.","Aggiungere un filo d''olio, i broccoli e 2 cucchiai d''acqua; saltare 3 min finché sono di un verde brillante e appena teneri. Aggiungere aglio e zenzero per 30 s.","Rimettere il manzo, versare la salsa e saltare 1 min finché è lucido. Servire sul riso."]}}'::jsonb),
  ('438ce1d6-39d6-46b8-b1b4-8358a3a7e801'::uuid, '{"fr":{"title":"Médaillons de porc à la normande, purée","steps":["Couper les pommes de terre en morceaux, les couvrir d''eau froide salée, porter à ébullition et cuire 20 min, jusqu''à ce que la pointe d''un couteau s''y enfonce facilement.","Pendant ce temps, saler et poivrer le porc. Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif et saisir les médaillons 3 min de chaque côté jusqu''à ce qu''ils soient dorés ; réserver sur une assiette.","Évider les pommes et couper chacune en 8 quartiers. Les cuire dans la même poêle avec 10 g de beurre 4 à 5 min en les retournant, jusqu''à ce que les bords dorent ; les ajouter au porc.","Faire fondre l''échalote 2 min dans la poêle, puis verser le cidre et décoller les sucs. Faire bouillir 3 min, jusqu''à réduction de moitié.","Incorporer la crème fraîche, la moutarde et les feuilles de thym et laisser frémir 1 min. Remettre le porc, les pommes et leur jus et mijoter doucement 3 à 4 min en retournant, jusqu''à ce que le porc soit juste cuit (à peine rosé à cœur).","Égoutter les pommes de terre et les écraser avec le reste du beurre et le lait chaud ; saler et poivrer.","Servir les médaillons et les pommes sur la purée, nappés de sauce au cidre."]},"it":{"title":"Medaglioni di maiale alla normanna con purè","steps":["Tagliare le patate a pezzi, coprirle con acqua fredda salata, portare a bollore e cuocere 20 min, finché la punta di un coltello entra facilmente.","Nel frattempo salare e pepare il maiale. Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto e rosolare i medaglioni 3 min per lato finché sono dorati; tenerli da parte su un piatto.","Togliere il torsolo alle mele e tagliare ciascuna in 8 spicchi. Cuocerli nella stessa padella con 10 g di burro per 4-5 min, girandoli, finché i bordi sono dorati; unirli al maiale.","Far appassire lo scalogno nella padella per 2 min, poi versare il sidro e staccare il fondo di cottura. Far bollire 3 min, finché si riduce della metà.","Incorporare la crème fraîche, la senape e le foglie di timo e sobbollire 1 min. Rimettere il maiale, le mele e il loro sugo e cuocere dolcemente 3-4 min, girando, finché il maiale è appena cotto (leggermente rosato al centro).","Scolare le patate e schiacciarle con il burro rimasto e il latte caldo; salare e pepare.","Servire i medaglioni e le mele sul purè, irrorati con la salsa al sidro."]}}'::jsonb),
  ('733a1520-f3d1-47af-9be0-d422b48b2c69'::uuid, '{"fr":{"title":"Salade tiède de lentilles, betterave et chèvre","steps":["Torréfier les noix à sec dans la casserole à feu moyen 2 à 3 min, jusqu''à ce qu''elles embaument ; les réserver.","Rincer les lentilles, les mettre dans la même casserole avec le laurier et le thym, couvrir de trois fois leur volume d''eau froide et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres mais encore entières. Saler en fin de cuisson.","Pendant ce temps, fouetter la moutarde, le vinaigre, le sel et le poivre, puis incorporer l''huile en fouettant et ajouter l''échalote.","Égoutter les lentilles, retirer les herbes et les mélanger encore tièdes avec les deux tiers de la vinaigrette. Laisser reposer 5 min pour qu''elles s''imprègnent.","Mélanger la betterave avec le reste de vinaigrette dans un autre bol pour qu''elle ne colore pas les lentilles.","Disposer la roquette dans les assiettes, ajouter les lentilles tièdes et la betterave, puis émietter le chèvre par-dessus et parsemer de noix et de persil. Servir tiède."]},"it":{"title":"Insalata tiepida di lenticchie, barbabietola e caprino","steps":["Tostare le noci a secco nel pentolino a fuoco medio per 2-3 min, finché sono profumate; metterle da parte.","Sciacquare le lenticchie, metterle nello stesso pentolino con l''alloro e il timo, coprirle con tre volte il loro volume di acqua fredda e cuocere a fuoco lento 20-25 min, finché sono tenere ma ancora intere. Salare a fine cottura.","Nel frattempo sbattere la senape, l''aceto, il sale e il pepe, poi incorporare l''olio sbattendo e aggiungere lo scalogno.","Scolare le lenticchie, togliere le erbe e condirle ancora tiepide con due terzi della vinaigrette. Lasciarle riposare 5 min perché si insaporiscano.","Condire la barbabietola con il resto della vinaigrette in un''altra ciotola, così non colora le lenticchie.","Disporre la rucola nei piatti, aggiungere le lenticchie tiepide e la barbabietola, poi sbriciolare sopra il caprino e cospargere di noci e prezzemolo. Servire tiepido."]}}'::jsonb),
  ('01e7604e-bc71-4e31-9a4f-180475fe8ddb'::uuid, '{"fr":{"title":"Truite poêlée, lentilles à la moutarde","steps":["Rincer les lentilles et les mettre dans une casserole avec la carotte, la moitié de l''échalote et le laurier. Couvrir de 3 cm d''eau froide et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres. Égoutter en gardant 3 c. à soupe d''eau de cuisson.","Remettre les lentilles dans la casserole à feu doux avec le reste de l''échalote, les deux moutardes, le vinaigre, la crème fraîche et l''eau réservée. Ajouter les épinards et remuer jusqu''à ce qu''ils tombent, environ 1 min ; assaisonner et garder au chaud.","Sécher la truite, inciser légèrement la peau et assaisonner des deux côtés.","Chauffer l''huile dans une poêle à feu moyen-vif. Poser les filets côté peau, les presser 10 s et cuire 3 à 4 min, jusqu''à ce que la peau soit croustillante et la chair opaque aux deux tiers.","Retourner les filets, ajouter le beurre et cuire encore 1 min en arrosant.","Répartir les lentilles dans les assiettes, poser la truite dessus et servir avec des quartiers de citron et de l''aneth."]},"it":{"title":"Trota in padella con lenticchie alla senape","steps":["Sciacquare le lenticchie e metterle in un pentolino con la carota, metà dello scalogno e l''alloro. Coprire con 3 cm di acqua fredda e cuocere a fuoco lento 20-25 min, finché sono tenere. Scolare tenendo da parte 3 cucchiai di acqua di cottura.","Rimettere le lenticchie nel pentolino a fuoco basso con il resto dello scalogno, le due senapi, l''aceto, la crème fraîche e l''acqua tenuta da parte. Aggiungere gli spinaci e mescolare finché appassiscono, circa 1 min; regolare di sale e pepe e tenere in caldo.","Asciugare la trota, incidere leggermente la pelle e condire da entrambi i lati.","Scaldare l''olio in una padella a fuoco medio-alto. Adagiare i filetti dal lato della pelle, premerli per 10 s e cuocere 3-4 min, finché la pelle è croccante e la carne è opaca per due terzi.","Girare i filetti, aggiungere il burro e cuocere ancora 1 min, irrorandoli.","Distribuire le lenticchie nei piatti, adagiarvi la trota e servire con spicchi di limone e aneto."]}}'::jsonb),
  ('a28a8bc9-457a-4379-b12a-e0367cc7a7cc'::uuid, '{"fr":{"title":"Poulet aux poireaux et champignons","steps":["Cuire le riz dans une casserole d''eau bouillante salée 12 min (ou selon le paquet), puis l''égoutter.","Saler et poivrer le poulet. Le faire dorer dans l''huile dans une grande sauteuse à feu moyen-vif 5 à 6 min, jusqu''à ce qu''il soit doré de tous côtés ; réserver.","Mettre le beurre et les champignons dans la sauteuse et cuire 4 à 5 min à feu vif, jusqu''à ce que leur eau soit évaporée et qu''ils colorent.","Ajouter les poireaux, l''ail, le thym et une pincée de sel et cuire à feu moyen 6 à 8 min, jusqu''à ce qu''ils soient fondants sans colorer.","Verser le vin et faire bouillir 1 min, puis ajouter le bouillon et le poulet. Couvrir et laisser mijoter 10 min, jusqu''à ce que le poulet soit cuit à cœur.","Incorporer la crème fraîche et la moutarde et laisser frémir 2 min à découvert, jusqu''à ce que la sauce nappe la cuillère. Rectifier l''assaisonnement.","Servir avec le riz, parsemé de persil."]},"it":{"title":"Pollo con porri e funghi","steps":["Cuocere il riso in una pentola di acqua bollente salata per 12 min (o secondo la confezione), poi scolarlo.","Salare e pepare il pollo. Rosolarlo nell''olio in una padella larga e alta a fuoco medio-alto per 5-6 min, finché è dorato su tutti i lati; tenerlo da parte.","Mettere nella padella il burro e i funghi e cuocere 4-5 min a fuoco vivo, finché la loro acqua è evaporata e prendono colore.","Aggiungere i porri, l''aglio, il timo e un pizzico di sale e cuocere a fuoco medio 6-8 min, finché sono morbidi ma non coloriti.","Versare il vino e far bollire 1 min, poi aggiungere il brodo e il pollo. Coprire e cuocere a fuoco lento 10 min, finché il pollo è cotto all''interno.","Incorporare la crème fraîche e la senape e sobbollire senza coperchio per 2 min, finché la salsa vela il cucchiaio. Regolare di sale e pepe.","Servire con il riso, cosparso di prezzemolo."]}}'::jsonb),
  ('37a05a33-7df2-470d-aa32-2ffa85f7c61c'::uuid, '{"fr":{"title":"Tarte feuilletée à la ratatouille, salade verte","steps":["Chauffer 2 c. à soupe d''huile dans une grande poêle et faire fondre l''oignon 5 min à feu moyen ; ajouter l''ail 1 min.","Ajouter l''aubergine et le poivron et cuire 8 min à feu moyen-vif en remuant souvent.","Ajouter la courgette, les tomates, les herbes de Provence et le sel et cuire à découvert 10 à 12 min, jusqu''à ce que tout soit tendre et que le jus se soit évaporé ; une ratatouille bien sèche garde la pâte croustillante. Laisser tiédir.","Préchauffer le four à 200 °C. Foncer un moule à tarte de 20 à 22 cm avec la pâte, piquer le fond à la fourchette et le badigeonner de moutarde.","Battre les œufs avec le lait, la moitié de l''emmental, du sel et du poivre.","Étaler la ratatouille sur le fond de tarte, verser l''appareil aux œufs et parsemer du reste de fromage.","Enfourner 30 à 35 min, jusqu''à ce que la pâte soit bien dorée et la garniture juste prise au centre. Laisser reposer 5 min.","Assaisonner la salade avec le vinaigre, le reste d''huile et une pincée de sel, et la servir avec la tarte parsemée de basilic déchiré."]},"it":{"title":"Torta di sfoglia alla ratatouille con insalata verde","steps":["Scaldare 2 cucchiai di olio in una padella larga e far appassire la cipolla per 5 min a fuoco medio; aggiungere l''aglio per 1 min.","Aggiungere la melanzana e il peperone e cuocere 8 min a fuoco medio-alto, mescolando spesso.","Aggiungere la zucchina, i pomodori, le erbe di Provenza e il sale e cuocere senza coperchio 10-12 min, finché tutto è tenero e il liquido è evaporato; una ratatouille asciutta mantiene croccante la sfoglia. Lasciare intiepidire.","Scaldare il forno a 200 °C. Foderare uno stampo da crostata di 20-22 cm con la sfoglia, bucherellare il fondo con una forchetta e spalmarlo di senape.","Sbattere le uova con il latte, metà dell''emmental, sale e pepe.","Distribuire la ratatouille nel guscio di pasta, versare il composto di uova e cospargere con il formaggio rimasto.","Cuocere in forno 30-35 min, finché la sfoglia è ben dorata e il ripieno è appena rappreso al centro. Lasciare riposare 5 min.","Condire l''insalata con l''aceto, l''olio rimasto e un pizzico di sale e servirla con la torta, completata con basilico spezzettato."]}}'::jsonb),
  ('912fa9d1-a5c7-4e51-9ba9-94e7b79e82ca'::uuid, '{"fr":{"title":"Truite aux amandes, haricots verts et pommes de terre","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau bouillante salée, en ajoutant les haricots verts pour les 6 dernières minutes. Égoutter, couper les pommes de terre en deux et garder le tout au chaud dans la casserole.","Saler et poivrer la truite et fariner les filets en tapotant pour ôter l''excédent.","Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif. Cuire les filets côté peau 3 min, jusqu''à ce qu''elle soit croustillante, puis les retourner et cuire encore 1 à 2 min. Les déposer dans des assiettes chaudes.","Essuyer la poêle, ajouter le reste du beurre à feu moyen et, quand il mousse, ajouter les amandes. Remuer 1 à 2 min, jusqu''à ce qu''elles soient blondes ; surveiller, elles brûlent vite.","Retirer la poêle du feu et ajouter le jus d''un demi-citron et le persil.","Napper la truite de beurre aux amandes et servir avec les pommes de terre, les haricots verts et le reste du citron en quartiers."]},"it":{"title":"Trota alle mandorle con fagiolini e patate","steps":["Lessare le patate in acqua salata per 15-18 min, aggiungendo i fagiolini negli ultimi 6 min. Scolare, tagliare a metà le patate e tenere tutto in caldo nella pentola.","Salare e pepare la trota e infarinare i filetti, scuotendo via l''eccesso.","Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto. Cuocere i filetti dal lato della pelle per 3 min, finché è croccante, poi girarli e cuocere ancora 1-2 min. Trasferirli su piatti caldi.","Pulire la padella, aggiungere il burro rimasto a fuoco medio e, quando fa la schiuma, unire le mandorle. Mescolare 1-2 min, finché sono appena dorate; controllare, bruciano in fretta.","Togliere la padella dal fuoco e aggiungere il succo di mezzo limone e il prezzemolo.","Versare il burro alle mandorle sulla trota e servire con le patate, i fagiolini e il resto del limone a spicchi."]}}'::jsonb),
  ('526726ea-ddcf-42ae-b3bc-d66740174c06'::uuid, '{"fr":{"title":"Courgettes farcies à la dinde","steps":["Préchauffer le four à 200 °C. Couper les courgettes en deux dans la longueur et les évider à la cuillère en laissant 1 cm de chair ; hacher la chair retirée.","Faire fondre l''oignon dans l''huile dans une poêle 4 min, puis ajouter l''ail et la chair de courgette hachée et cuire 5 min, jusqu''à ce que l''eau soit évaporée.","Ajouter la dinde en l''émiettant et cuire 5 min jusqu''à ce qu''elle ne soit plus rose. Ajouter les tomates, le concentré et les herbes et cuire encore 3 min.","Hors du feu, laisser tiédir quelques minutes, puis incorporer le persil, l''œuf, la moitié de la chapelure, du sel et du poivre.","Disposer les barquettes de courgette dans un plat huilé, les assaisonner et les garnir généreusement de farce.","Mélanger le reste de chapelure avec le parmesan, en parsemer le dessus et arroser d''un filet d''huile.","Enfourner 30 à 35 min, jusqu''à ce que les courgettes soient tendres sous la pointe d''un couteau et le dessus doré. Servir avec du pain."]},"it":{"title":"Zucchine ripiene di tacchino","steps":["Scaldare il forno a 200 °C. Tagliare le zucchine a metà nel senso della lunghezza e svuotarle con un cucchiaio lasciando 1 cm di polpa; tritare la polpa tolta.","Far appassire la cipolla nell''olio in una padella per 4 min, poi aggiungere l''aglio e la polpa di zucchina tritata e cuocere 5 min, finché l''acqua è evaporata.","Aggiungere il tacchino sbriciolandolo e cuocere 5 min finché non è più rosa. Aggiungere i pomodori, il concentrato e le erbe e cuocere ancora 3 min.","Fuori dal fuoco lasciare intiepidire qualche minuto, poi incorporare il prezzemolo, l''uovo, metà del pangrattato, sale e pepe.","Sistemare le barchette di zucchina in una pirofila unta, condirle e riempirle abbondantemente con il ripieno.","Mescolare il pangrattato rimasto con il parmigiano, cospargerlo sopra e irrorare con un filo d''olio.","Cuocere in forno 30-35 min, finché le zucchine sono tenere alla punta di un coltello e la superficie è dorata. Servire con pane."]}}'::jsonb),
  ('6fce5d8d-5b15-48e1-bbbc-a4f27311e708'::uuid, '{"fr":{"title":"Quiche au saumon fumé et aux poireaux","steps":["Préchauffer le four à 190 °C. Foncer un moule à tarte de 20 à 22 cm avec la pâte, piquer le fond et le réserver au frais pendant la préparation de la garniture.","Laver les poireaux et les faire suer dans le beurre avec une pincée de sel, à couvert, 10 min, jusqu''à ce qu''ils soient fondants ; découvrir les 2 dernières minutes pour les sécher. Laisser tiédir.","Battre les œufs avec la crème fraîche, le lait, la muscade et le poivre ; saler à peine, le saumon étant salé.","Étaler les poireaux sur la pâte, répartir le saumon, l''aneth et l''emmental, puis verser l''appareil.","Enfourner 30 à 35 min, jusqu''à ce que la quiche soit gonflée et dorée et que le centre tremble à peine.","Laisser reposer 10 min avant de découper, et servir avec une salade verte."]},"it":{"title":"Quiche al salmone affumicato e porri","steps":["Scaldare il forno a 190 °C. Foderare uno stampo da crostata di 20-22 cm con la sfoglia, bucherellare il fondo e tenerlo in frigorifero mentre si prepara il ripieno.","Lavare i porri e stufarli nel burro con un pizzico di sale, coperti, per 10 min, finché sono morbidi; scoprire negli ultimi 2 min per asciugarli. Lasciarli intiepidire.","Sbattere le uova con la crème fraîche, il latte, la noce moscata e il pepe; salare appena, perché il salmone è già salato.","Distribuire i porri sulla sfoglia, cospargere con il salmone, l''aneto e l''emmental, poi versare il composto di uova.","Cuocere in forno 30-35 min, finché la quiche è gonfia e dorata e il centro trema appena.","Lasciare riposare 10 min prima di tagliare e servire con un''insalata verde."]}}'::jsonb),
  ('3c54ff1d-21f9-40f7-ac17-447d4677f6e0'::uuid, '{"fr":{"title":"Galette complète","steps":["Fouetter la farine avec 1/2 c. à café de sel, puis incorporer peu à peu 220 ml d''eau froide en fouettant pour obtenir une pâte lisse, de la consistance d''une crème liquide. Couvrir et réserver au frais au moins 1 h (2 h, c''est mieux).","Fouetter à nouveau la pâte. Chauffer une grande poêle antiadhésive ou une crêpière (environ 28 cm) à feu moyen-vif et la graisser d''un peu de beurre.","Verser une petite louche de pâte (environ 70 ml) et l''étaler finement en inclinant la poêle. Cuire 1 min 30 à 2 min, jusqu''à ce que les bords se décollent et croustillent, puis retourner et cuire 30 s. Empiler et recommencer pour obtenir 4 galettes.","Remettre une galette dans la poêle beurrée à feu moyen. Parsemer un quart de l''emmental au centre, casser un œuf dessus et étaler doucement le blanc à la spatule sans crever le jaune.","Disposer une tranche de jambon autour du jaune et cuire 3 à 4 min, en couvrant 1 min, jusqu''à ce que le blanc soit pris et le dessous croustillant.","Replier les quatre bords pour former un carré en laissant le jaune apparent. Glisser sur une assiette, poivrer, parsemer de ciboulette et recommencer avec le reste."]},"it":{"title":"Galette complète bretone","steps":["Sbattere la farina con 1/2 cucchiaino di sale, poi incorporare poco a poco 220 ml di acqua fredda sbattendo, fino a ottenere una pastella liscia, della consistenza della panna liquida. Coprire e tenere in frigorifero almeno 1 ora (meglio 2).","Sbattere di nuovo la pastella. Scaldare una padella antiaderente larga o una crêpiera (circa 28 cm) a fuoco medio-alto e ungerla con poco burro.","Versare un piccolo mestolo di pastella (circa 70 ml) e stenderla sottile ruotando la padella. Cuocere 1,5-2 min, finché i bordi si staccano e diventano croccanti, poi girare e cuocere 30 s. Impilare e ripetere fino a ottenere 4 galette.","Rimettere una galette nella padella imburrata a fuoco medio. Distribuire un quarto dell''emmental al centro, rompervi sopra un uovo e allargare delicatamente l''albume con una spatola senza rompere il tuorlo.","Disporre una fetta di prosciutto intorno al tuorlo e cuocere 3-4 min, coprendo per 1 min, finché l''albume è rappreso e il fondo è croccante.","Ripiegare i quattro bordi formando un quadrato e lasciando visibile il tuorlo. Far scivolare su un piatto, pepare, cospargere di erba cipollina e ripetere con il resto."]}}'::jsonb),
  ('dc443c39-5da5-4243-8dd2-eb0da76ad765'::uuid, '{"fr":{"title":"Hauts de cuisse de poulet rôtis, carottes et pommes de terre","steps":["Préchauffer le four à 200 °C.","Mélanger les pommes de terre, les carottes, l''oignon et l''ail dans un plat à rôtir avec 1,5 c. à soupe d''huile, le thym, du sel et du poivre, et les étaler en une seule couche.","Sécher les hauts de cuisse, les frotter avec le reste d''huile, bien les assaisonner et les poser côté peau vers le haut sur les légumes.","Verser le bouillon dans le plat autour des légumes, sans mouiller la peau du poulet.","Enfourner 45 min en arrosant les légumes une fois à mi-cuisson, jusqu''à ce que la peau soit croustillante, que le jus soit clair (75 °C près de l''os) et que les légumes soient tendres. Pour une peau encore plus croustillante, finir 3 min sous le gril.","Laisser reposer 5 min, presser l''ail fondant dans le jus de cuisson et servir parsemé de persil."]},"it":{"title":"Sovracosce di pollo arrosto con carote e patate","steps":["Scaldare il forno a 200 °C.","Mescolare le patate, le carote, la cipolla e l''aglio in una teglia con 1,5 cucchiai di olio, il timo, sale e pepe, e distribuirli in un solo strato.","Asciugare le sovracosce, massaggiarle con l''olio rimasto, condirle bene e adagiarle con la pelle verso l''alto sulle verdure.","Versare il brodo nella teglia intorno alle verdure, senza bagnare la pelle del pollo.","Arrostire 45 min, irrorando le verdure una volta a metà cottura, finché la pelle è croccante, il sugo esce chiaro (75 °C vicino all''osso) e le verdure sono tenere. Per una pelle ancora più croccante, finire 3 min sotto il grill.","Lasciare riposare 5 min, spremere l''aglio morbido nel fondo di cottura e servire cosparso di prezzemolo."]}}'::jsonb),
  ('32702abe-4094-459f-80a5-53f01914b4d3'::uuid, '{"fr":{"title":"Côtes de porc, haricots blancs à la moutarde","steps":["Sécher les côtes, inciser le gras du bord à deux ou trois endroits pour qu''elles restent à plat, et assaisonner.","Chauffer l''huile dans une grande poêle à feu moyen-vif. Cuire les côtes 4 à 5 min de chaque côté, jusqu''à ce qu''elles soient dorées et à 63 °C à cœur (encore légèrement rosées), en les tenant 1 min sur la tranche pour faire fondre le gras. Laisser reposer sous une feuille d''aluminium.","Baisser le feu, ajouter le beurre et faire fondre l''échalote 2 min, puis ajouter l''ail et le thym 30 s.","Verser le vin en décollant les sucs et réduire 1 min. Ajouter le bouillon et les haricots et laisser mijoter 4 min en écrasant quelques haricots pour épaissir la sauce.","Incorporer les deux moutardes et la crème fraîche, puis les épinards jusqu''à ce qu''ils tombent, environ 1 min. Ajouter le jus de repos des côtes et assaisonner.","Servir les côtes sur les haricots, parsemées de persil."]},"it":{"title":"Braciole di maiale con fagioli bianchi alla senape","steps":["Asciugare le braciole, incidere il grasso del bordo in due o tre punti perché restino piatte, e condirle.","Scaldare l''olio in una padella larga a fuoco medio-alto. Cuocere le braciole 4-5 min per lato, finché sono dorate e a 63 °C al centro (ancora leggermente rosate), tenendole 1 min sul bordo grasso per farlo sciogliere. Lasciarle riposare coperte con un foglio di alluminio.","Abbassare il fuoco, aggiungere il burro e far appassire lo scalogno per 2 min, poi aggiungere l''aglio e il timo per 30 s.","Versare il vino staccando il fondo di cottura e ridurre 1 min. Aggiungere il brodo e i fagioli e sobbollire 4 min, schiacciando qualche fagiolo per addensare la salsa.","Incorporare le due senapi e la crème fraîche, poi gli spinaci finché appassiscono, circa 1 min. Aggiungere il sugo rilasciato dalle braciole e regolare di sale e pepe.","Servire le braciole sui fagioli, cosparse di prezzemolo."]}}'::jsonb),
  ('a1f1bf80-ba8c-445f-919f-eb1dfa24d82f'::uuid, '{"fr":{"title":"Steaks de céleri-rave rôtis, lentilles vertes","steps":["Préchauffer le four à 200 °C. Badigeonner les tranches de céleri de 1,5 c. à soupe d''huile, assaisonner, ajouter le thym et rôtir sur une plaque chemisée 40 à 45 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et tendres sous la pointe d''un couteau. Parsemer de beurre les 5 dernières minutes.","Pendant ce temps, faire revenir l''oignon, la carotte et le céleri branche dans 0,5 c. à soupe d''huile dans une casserole 5 min.","Ajouter les lentilles, le laurier, l''ail et 500 ml d''eau et cuire à frémissement 20 à 25 min, jusqu''à ce qu''elles soient tendres, en ajoutant un peu d''eau si besoin. Saler en fin de cuisson.","Mélanger le fromage blanc avec 1 c. à café de moutarde, la moitié du persil, du sel et du poivre.","Égoutter les lentilles si nécessaire, retirer le laurier et incorporer le vinaigre, le reste de moutarde et d''huile et le reste du persil. Assaisonner.","Servir les lentilles surmontées des steaks de céleri, d''une cuillerée de fromage blanc à la moutarde et des noix."]},"it":{"title":"Bistecche di sedano rapa arrosto con lenticchie","steps":["Scaldare il forno a 200 °C. Spennellare le fette di sedano rapa con 1,5 cucchiai di olio, condirle, aggiungere il timo e arrostirle su una teglia foderata 40-45 min, girandole a metà, finché sono ben dorate e tenere alla punta di un coltello. Distribuire il burro a fiocchetti negli ultimi 5 min.","Nel frattempo far soffriggere la cipolla, la carota e il sedano in 0,5 cucchiai di olio in un pentolino per 5 min.","Aggiungere le lenticchie, l''alloro, l''aglio e 500 ml di acqua e cuocere a fuoco lento 20-25 min, finché sono tenere, aggiungendo un po'' d''acqua se serve. Salare a fine cottura.","Mescolare il fromage blanc con 1 cucchiaino di senape, metà del prezzemolo, sale e pepe.","Scolare le lenticchie se necessario, togliere l''alloro e incorporare l''aceto, la senape e l''olio rimasti e il resto del prezzemolo. Regolare di sale e pepe.","Servire le lenticchie con sopra le bistecche di sedano rapa, una cucchiaiata di fromage blanc alla senape e le noci."]}}'::jsonb),
  ('5486ba0e-eda7-4b34-9db4-c6ded42efe68'::uuid, '{"fr":{"title":"Bar poêlé, écrasé de pommes de terre, tomates et olives","steps":["Cuire les pommes de terre 15 à 20 min dans de l''eau bouillante salée, jusqu''à ce qu''elles soient tendres. Égoutter et laisser sécher 2 min à la vapeur.","Les écraser grossièrement à la fourchette dans la casserole avec 2 c. à soupe d''huile, le zeste du citron, du sel et du poivre ; garder des morceaux, sans faire de purée. Couvrir pour garder au chaud.","Chauffer 1 c. à soupe d''huile dans une poêle, ajouter l''ail 30 s, puis les tomates 3 à 4 min jusqu''à ce qu''elles commencent à éclater. Ajouter les olives, les câpres et un trait d''eau, assaisonner et verser dans un bol. Essuyer la poêle.","Sécher le poisson, inciser la peau et assaisonner. Chauffer le reste d''huile à feu moyen-vif et poser les filets côté peau en les pressant 10 s. Cuire 3 à 4 min, jusqu''à ce que la peau soit croustillante, puis retourner et cuire 1 min.","Servir le poisson sur l''écrasé avec les tomates et les olives, du basilic déchiré et un filet de jus de citron."]},"it":{"title":"Branzino con patate schiacciate, pomodorini e olive","steps":["Lessare le patate in acqua salata per 15-20 min, finché sono tenere. Scolarle e lasciarle asciugare al vapore per 2 min.","Schiacciarle grossolanamente con una forchetta nella pentola con 2 cucchiai di olio, la scorza del limone, sale e pepe; lasciarle a pezzetti, non a purè. Coprire per tenerle in caldo.","Scaldare 1 cucchiaio di olio in una padella, aggiungere l''aglio per 30 s, poi i pomodorini per 3-4 min finché iniziano ad aprirsi. Aggiungere le olive, i capperi e un goccio d''acqua, regolare di sale e pepe e versare in una ciotola. Pulire la padella.","Asciugare il pesce, incidere la pelle e condirlo. Scaldare l''olio rimasto a fuoco medio-alto e adagiare i filetti dal lato della pelle, premendoli per 10 s. Cuocere 3-4 min, finché la pelle è croccante, poi girarli e cuocere 1 min.","Servire il pesce sulle patate schiacciate con i pomodorini e le olive, basilico spezzettato e una spruzzata di limone."]}}'::jsonb),
  ('10bc39c8-9e08-45f4-8b8d-083d4485392e'::uuid, '{"fr":{"title":"Sole meunière, pommes vapeur et haricots verts","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau bouillante salée, en ajoutant les haricots verts pour les 6 dernières minutes. Égoutter et garder au chaud.","Sécher la sole, l''assaisonner des deux côtés et la passer dans la farine en tapotant pour ôter l''excédent.","Chauffer l''huile et 10 g de beurre dans une grande poêle à feu moyen-vif jusqu''à ce qu''ils moussent. Cuire les filets 2 min, les retourner délicatement et cuire encore 1 à 2 min, jusqu''à ce qu''ils soient dorés et opaques ; procéder en deux fois si besoin. Garder au chaud dans les assiettes.","Essuyer la poêle, ajouter le reste du beurre à feu moyen et le laisser mousser jusqu''à ce qu''il devienne noisette et sente la noisette, 2 à 3 min.","Retirer la poêle du feu et ajouter le jus d''un demi-citron (il va grésiller) et le persil.","Verser le beurre noisette sur le poisson et les pommes de terre et servir avec les haricots verts et des quartiers de citron."]},"it":{"title":"Sogliola alla mugnaia con patate e fagiolini","steps":["Lessare le patate in acqua salata per 15-18 min, aggiungendo i fagiolini negli ultimi 6 min. Scolare e tenere in caldo.","Asciugare la sogliola, condirla da entrambi i lati e passarla nella farina, scuotendo via l''eccesso.","Scaldare l''olio e 10 g di burro in una padella larga a fuoco medio-alto finché fanno la schiuma. Cuocere i filetti 2 min, girarli con delicatezza e cuocere ancora 1-2 min, finché sono dorati e opachi; procedere in due volte se serve. Tenerli in caldo nei piatti.","Pulire la padella, aggiungere il burro rimasto a fuoco medio e lasciarlo spumeggiare finché diventa color nocciola e profuma di nocciola, 2-3 min.","Togliere la padella dal fuoco e aggiungere il succo di mezzo limone (sfrigolerà) e il prezzemolo.","Versare il burro nocciola sul pesce e sulle patate e servire con i fagiolini e spicchi di limone."]}}'::jsonb),
  ('a50426c9-afb6-41ab-ae5c-a0c08d84695c'::uuid, '{"fr":{"title":"Salade niçoise au thon et haricots verts","steps":["Mettre les pommes de terre dans une casserole d''eau bouillante salée. Au bout de 6 min, plonger les œufs ; 4 min plus tard, ajouter les haricots verts ; 5 min après, tout égoutter et refroidir sous l''eau froide (œufs 9 min, pommes de terre 15 min).","Écaler les œufs et les couper en quartiers, couper les pommes de terre en deux et les haricots en deux.","Fouetter la moutarde, le vinaigre, le sel et le poivre, puis incorporer l''huile en fouettant.","Saler légèrement les quartiers de tomate.","Disposer la salade sur un grand plat avec les pommes de terre, les haricots, les tomates et l''oignon nouveau. Émietter le thon par-dessus et garnir d''œufs, d''anchois, d''olives et de câpres.","Arroser de vinaigrette et parsemer de basilic juste avant de servir."]},"it":{"title":"Insalata nizzarda con tonno e fagiolini","steps":["Mettere le patate in una pentola di acqua bollente salata. Dopo 6 min immergere le uova; dopo altri 4 min aggiungere i fagiolini; 5 min più tardi scolare tutto e raffreddare sotto l''acqua fredda (uova 9 min, patate 15 min).","Sgusciare le uova e tagliarle in quarti, tagliare a metà le patate e i fagiolini.","Sbattere la senape, l''aceto, il sale e il pepe, poi incorporare l''olio sbattendo.","Salare leggermente gli spicchi di pomodoro.","Disporre l''insalata su un piatto grande con le patate, i fagiolini, i pomodori e il cipollotto. Sbriciolare sopra il tonno e completare con le uova, le acciughe, le olive e i capperi.","Condire con la vinaigrette e cospargere di basilico appena prima di servire."]}}'::jsonb),
  ('0a467eb7-d057-498a-8acc-597b35c741b4'::uuid, '{"fr":{"title":"Lapin à la moutarde","steps":["Saler et poivrer le lapin. Chauffer l''huile et le beurre dans une cocotte à feu moyen-vif et bien dorer les cuisses sur toutes les faces, environ 8 min ; réserver.","Baisser le feu et faire revenir les lardons, l''oignon et l''échalote 5 min, jusqu''à ce qu''ils soient fondants et légèrement dorés.","Remettre le lapin et l''enrober entièrement des deux moutardes. Verser le vin et faire bouillir 2 min, puis ajouter le bouillon et le bouquet garni.","Couvrir et laisser mijoter doucement 50 min en retournant les cuisses à mi-cuisson, jusqu''à ce que la viande se détache facilement de l''os.","En fin de cuisson, cuire les tagliatelles dans de l''eau bouillante salée selon le paquet et les égoutter.","Retirer le lapin et le bouquet garni. Incorporer la crème fraîche à la sauce et faire bouillir 3 à 4 min, jusqu''à ce qu''elle nappe la cuillère. Assaisonner et remettre le lapin pour le réchauffer.","Servir le lapin et sa sauce avec les tagliatelles, parsemés de persil."]},"it":{"title":"Coniglio alla senape","steps":["Salare e pepare il coniglio. Scaldare l''olio e il burro in una casseruola a fuoco medio-alto e rosolare bene le cosce su tutti i lati, circa 8 min; metterle da parte.","Abbassare il fuoco e far rosolare la pancetta, la cipolla e lo scalogno per 5 min, finché sono morbidi e leggermente dorati.","Rimettere il coniglio e ricoprirlo completamente con le due senapi. Versare il vino e far bollire 2 min, poi aggiungere il brodo e il mazzetto odoroso.","Coprire e cuocere a fuoco dolce per 50 min, girando le cosce a metà cottura, finché la carne si stacca facilmente dall''osso.","Verso la fine cuocere le tagliatelle in acqua bollente salata secondo la confezione e scolarle.","Togliere il coniglio e il mazzetto odoroso. Incorporare la crème fraîche nella salsa e far bollire 3-4 min, finché vela il cucchiaio. Regolare di sale e pepe e rimettere il coniglio a scaldare.","Servire il coniglio con la salsa e le tagliatelle, cosparso di prezzemolo."]}}'::jsonb),
  ('72030c48-cb4d-4400-8a24-e49c0be5316c'::uuid, '{"fr":{"title":"Hachis parmentier","steps":["Couvrir les pommes de terre d''eau froide salée, porter à ébullition et cuire 20 min, jusqu''à ce qu''elles soient très tendres.","Pendant ce temps, faire revenir l''oignon et la carotte dans l''huile dans une poêle 6 à 7 min, puis ajouter l''ail 1 min.","Monter le feu, ajouter le bœuf et le faire dorer 5 à 6 min en l''émiettant. Incorporer le concentré de tomate, les feuilles de thym et le bouillon et laisser mijoter 10 min, jusqu''à ce que le liquide soit presque absorbé mais la viande encore moelleuse. Ajouter le persil et assaisonner.","Préchauffer le four à 200 °C. Égoutter les pommes de terre et les écraser avec le beurre, le lait chaud, la muscade et du sel jusqu''à obtenir une purée lisse et souple.","Étaler la viande dans un plat à gratin beurré (environ 20 × 15 cm), recouvrir de purée, lisser et tracer des stries à la fourchette. Parsemer d''emmental.","Enfourner 20 à 25 min, jusqu''à ce que le dessus soit doré et que les bords bouillonnent. Laisser reposer 5 min avant de servir."]},"it":{"title":"Hachis parmentier (pasticcio di carne e purè)","steps":["Coprire le patate con acqua fredda salata, portare a bollore e cuocere 20 min, finché sono molto tenere.","Nel frattempo far soffriggere la cipolla e la carota nell''olio in una padella per 6-7 min, poi aggiungere l''aglio per 1 min.","Alzare il fuoco, aggiungere il manzo e rosolarlo 5-6 min sbriciolandolo. Incorporare il concentrato di pomodoro, le foglie di timo e il brodo e cuocere a fuoco lento 10 min, finché il liquido è quasi assorbito ma la carne è ancora morbida. Aggiungere il prezzemolo e regolare di sale e pepe.","Scaldare il forno a 200 °C. Scolare le patate e schiacciarle con il burro, il latte caldo, la noce moscata e il sale fino a ottenere un purè liscio e morbido.","Stendere la carne in una pirofila imburrata (circa 20 × 15 cm), ricoprire con il purè, livellare e tracciare delle righe con una forchetta. Cospargere di emmental.","Cuocere in forno 20-25 min, finché la superficie è dorata e i bordi sobbollono. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('d1469ff0-250b-44af-9740-b897725d64a9'::uuid, '{"fr":{"title":"Calamars à la provençale","steps":["Cuire le riz 12 min dans de l''eau bouillante salée, puis l''égoutter.","Pendant ce temps, bien sécher les calamars avec du papier absorbant et les assaisonner.","Faire fondre l''oignon dans 1,5 c. à soupe d''huile dans une grande poêle 5 min, puis ajouter les deux tiers de l''ail 1 min.","Ajouter les tomates, les herbes de Provence, le laurier et le vin et laisser réduire à bon frémissement 8 min, jusqu''à ce que la sauce épaississe. Assaisonner et verser la sauce dans un bol ; essuyer la poêle.","Chauffer le reste d''huile dans la poêle à feu vif jusqu''à ce qu''elle soit très chaude et saisir les calamars en une seule couche 1 min 30 à 2 min, juste jusqu''à ce qu''ils soient opaques ; au-delà, ils deviennent caoutchouteux.","Remettre la sauce dans la poêle et mélanger 1 min. Hors du feu, ajouter le persil mélangé au reste d''ail et le piment.","Servir aussitôt avec le riz."]},"it":{"title":"Calamari alla provenzale","steps":["Cuocere il riso in acqua bollente salata per 12 min, poi scolarlo.","Nel frattempo asciugare molto bene i calamari con carta da cucina e condirli.","Far appassire la cipolla in 1,5 cucchiai di olio in una padella larga per 5 min, poi aggiungere due terzi dell''aglio per 1 min.","Aggiungere i pomodori, le erbe di Provenza, l''alloro e il vino e cuocere a fuoco vivace per 8 min, finché la salsa si addensa. Regolare di sale e pepe e versare la salsa in una ciotola; pulire la padella.","Scaldare l''olio rimasto nella padella a fuoco vivo finché è molto caldo e saltare i calamari in un solo strato per 1,5-2 min, solo finché diventano opachi; oltre diventano gommosi.","Rimettere la salsa nella padella e mescolare per 1 min. Fuori dal fuoco aggiungere il prezzemolo mescolato con l''aglio rimasto e il peperoncino.","Servire subito con il riso."]}}'::jsonb),
  ('fc1f7890-aff1-46d1-a531-9eeb03b6ba6f'::uuid, '{"fr":{"title":"Bavette à l''échalote, haricots verts","steps":["Cuire les haricots verts 6 à 7 min dans de l''eau bouillante salée, jusqu''à ce qu''ils soient juste tendres. Égoutter et mélanger avec 5 g de beurre.","Pendant ce temps, sécher la viande et la saler. Chauffer l''huile dans une poêle épaisse à feu vif jusqu''à ce qu''elle fume et saisir la bavette 2 à 3 min de chaque côté pour une cuisson saignante à rosée ; au-delà d''à point, la bavette durcit.","Laisser reposer la viande 5 min sur une assiette chaude sous une feuille d''aluminium.","Baisser à feu moyen, mettre 15 g de beurre et les échalotes dans la poêle et cuire 4 à 5 min en remuant, jusqu''à ce qu''elles soient fondantes et dorées.","Ajouter le vinaigre et le vin, décoller les sucs et faire bouillir 1 à 2 min, jusqu''à consistance sirupeuse. Hors du feu, incorporer le reste du beurre, le persil, le jus de repos de la viande et du poivre en abondance.","Trancher finement la bavette dans le sens contraire des fibres, napper d''échalotes et servir avec les haricots verts et du pain."]},"it":{"title":"Bavette di manzo allo scalogno con fagiolini","steps":["Cuocere i fagiolini in acqua bollente salata per 6-7 min, finché sono appena teneri. Scolarli e condirli con 5 g di burro.","Nel frattempo asciugare la carne e salarla. Scaldare l''olio in una padella dal fondo spesso a fuoco vivo finché fuma e scottare la bavette 2-3 min per lato per una cottura al sangue o media-al sangue; oltre la cottura media diventa dura.","Lasciare riposare la carne 5 min su un piatto caldo coperta con un foglio di alluminio.","Abbassare a fuoco medio, mettere nella padella 15 g di burro e gli scalogni e cuocere 4-5 min mescolando, finché sono morbidi e dorati.","Aggiungere l''aceto e il vino, staccare il fondo di cottura e far bollire 1-2 min, finché diventa sciropposo. Fuori dal fuoco incorporare il burro rimasto, il prezzemolo, il sugo rilasciato dalla carne e abbondante pepe.","Tagliare la carne a fettine sottili contro fibra, coprirla con gli scalogni e servire con i fagiolini e il pane."]}}'::jsonb),
  ('e6a9b053-18c1-4083-bff9-6dd9c29a9b25'::uuid, '{"fr":{"title":"Soupe au pistou aux haricots blancs","steps":["Chauffer 1 c. à soupe d''huile dans un grand faitout et faire fondre l''oignon et le poireau 5 min.","Ajouter la carotte, la pomme de terre, la tomate, le thym, 1,1 l d''eau et du sel. Porter à ébullition et laisser frémir 15 min.","Ajouter les haricots verts, la courgette et les haricots blancs et cuire 10 min.","Ajouter les pâtes et cuire 8 à 10 min, jusqu''à ce qu''elles soient tendres ; la soupe doit être épaisse, n''ajouter un peu d''eau que si nécessaire.","Pendant ce temps, préparer le pistou : écraser l''ail avec une pincée de gros sel jusqu''à obtenir une pâte (au mortier ou avec le plat d''un couteau), ajouter le basilic et piler ou hacher finement, puis incorporer le parmesan et les 3 c. à soupe d''huile.","Retirer le faitout du feu, ôter le thym et incorporer la moitié du pistou. Servir le reste à table."]},"it":{"title":"Zuppa al pistou con fagioli bianchi","steps":["Scaldare 1 cucchiaio di olio in una pentola capiente e far appassire la cipolla e il porro per 5 min.","Aggiungere la carota, la patata, il pomodoro, il timo, 1,1 l di acqua e il sale. Portare a bollore e cuocere a fuoco lento 15 min.","Aggiungere i fagiolini, la zucchina e i fagioli bianchi e cuocere 10 min.","Aggiungere la pasta e cuocere 8-10 min, finché è tenera; la zuppa deve restare densa, quindi aggiungere un po'' d''acqua solo se serve.","Nel frattempo preparare il pistou: schiacciare l''aglio con un pizzico di sale grosso fino a ridurlo in crema (nel mortaio o con la lama piatta di un coltello), aggiungere il basilico e pestare o tritare finemente, poi incorporare il parmigiano e i 3 cucchiai di olio.","Togliere la pentola dal fuoco, eliminare il timo e incorporare metà del pistou. Servire il resto a tavola."]}}'::jsonb),
  ('cf3604f7-00c4-4439-ae7c-a23dd60cdc25'::uuid, '{"fr":{"title":"Pâtes au citron, petits pois et ricotta","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les pâtes 1 min de moins que le temps indiqué.","Pendant ce temps, écraser la ricotta dans un grand saladier avec le zeste de citron, la moitié du jus, l''ail, l''huile d''olive, la moitié du parmesan, du sel et beaucoup de poivre.","Ajouter les petits pois aux pâtes pendant les 3 dernières minutes de cuisson.","Prélever un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois.","Les verser dans le saladier et mélanger avec la ricotta en ajoutant l''eau de cuisson petit à petit jusqu''à obtenir une sauce crémeuse qui enrobe les pâtes.","Goûter, ajouter le reste du jus de citron si on le souhaite et servir avec le reste du parmesan, le persil et une pincée de piment."]},"it":{"title":"Pasta al limone con piselli e ricotta","steps":["Portare a bollore una pentola di acqua salata e cuocere la pasta 1 min in meno del tempo indicato.","Nel frattempo schiacciare la ricotta in una ciotola capiente con la scorza di limone, metà del succo, l''aglio, l''olio, metà del parmigiano, sale e abbondante pepe.","Aggiungere i piselli alla pasta negli ultimi 3 min di cottura.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli.","Versarli nella ciotola e mescolare con la ricotta, aggiungendo acqua di cottura poco alla volta finché la crema è morbida e avvolge la pasta.","Assaggiare, unire il resto del succo di limone a piacere e servire con il parmigiano rimasto, il prezzemolo e un pizzico di peperoncino."]}}'::jsonb),
  ('91e8fa61-df06-405b-a7c2-209948b7784f'::uuid, '{"fr":{"title":"Frittata aux champignons et épinards, pain","steps":["Préchauffer le four à 180 °C.","Chauffer l''huile dans une poêle de 24 cm allant au four, à feu moyen, et faire fondre l''oignon 5 min.","Ajouter les champignons, l''ail et le thym et cuire 6 à 8 min, jusqu''à ce que les champignons soient dorés et leur eau évaporée.","Ajouter les épinards par poignées et remuer jusqu''à ce qu''ils tombent et que la poêle soit sèche, environ 2 min ; assaisonner.","Battre les œufs avec le lait, le parmesan, du sel et du poivre.","Verser les œufs sur les légumes, bien répartir et cuire à feu doux 3 à 4 min, jusqu''à ce que les bords commencent à prendre.","Enfourner 10 à 12 min, jusqu''à ce que le centre soit juste pris et souple au toucher.","Laisser reposer 2 min, couper en parts et servir tiède avec le pain."]},"it":{"title":"Frittata di funghi e spinaci con pane","steps":["Scaldare il forno a 180 °C.","Scaldare l''olio in una padella da 24 cm adatta al forno, a fuoco medio, e appassire la cipolla per 5 min.","Aggiungere i funghi, l''aglio e il timo e cuocere 6-8 min, finché i funghi sono dorati e la loro acqua è evaporata.","Unire gli spinaci a manciate e mescolare finché sono appassiti e la padella è asciutta, circa 2 min; salare e pepare.","Sbattere le uova con il latte, il parmigiano, sale e pepe.","Versare le uova sulle verdure, distribuire bene e cuocere a fuoco basso 3-4 min, finché i bordi iniziano a rapprendersi.","Infornare per 10-12 min, finché il centro è appena rappreso ed elastico al tatto.","Lasciare riposare 2 min, tagliare a spicchi e servire tiepida con il pane."]}}'::jsonb),
  ('a22633f5-d714-4ccc-bc98-4d7d2c560bd9'::uuid, '{"fr":{"title":"Boulettes de dinde à la sauce tomate et polenta","steps":["Mélanger à la main la dinde, l''œuf, la chapelure, la moitié du parmesan, l''ail râpé, le persil, du sel et du poivre, sans trop travailler la farce.","Former 12 boulettes de la taille d''une noix.","Faire dorer les boulettes dans 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif 5 min en les retournant, puis les retirer.","Dans la même poêle, faire revenir l''oignon et l''ail émincé dans le reste d''huile 4 min, puis ajouter le coulis de tomate, du sel et un peu d''eau.","Remettre les boulettes, couvrir et laisser mijoter doucement 15 min, jusqu''à ce qu''elles soient cuites à cœur et la sauce épaissie ; ajouter le basilic déchiré.","Pendant ce temps, porter à ébullition 450 ml d''eau salée et le lait, verser la polenta en pluie en fouettant et cuire 5 à 8 min (voir le paquet) en remuant, jusqu''à ce qu''elle soit épaisse et lisse.","Incorporer le reste du parmesan à la polenta et la servir dans des bols, garnie des boulettes et de la sauce."]},"it":{"title":"Polpette di tacchino al sugo con polenta","steps":["Impastare con le mani il tacchino, l''uovo, il pangrattato, metà del parmigiano, l''aglio grattugiato, il prezzemolo, sale e pepe, senza lavorare troppo.","Formare 12 polpette grandi come una noce.","Rosolare le polpette in 1 cucchiaio d''olio in una padella larga a fuoco medio-alto per 5 min, girandole, poi toglierle.","Nella stessa padella appassire la cipolla e l''aglio a fettine nell''olio rimasto per 4 min, poi aggiungere la passata, sale e un goccio d''acqua.","Rimettere le polpette, coprire e cuocere a fuoco dolce 15 min, finché sono cotte all''interno e il sugo si è addensato; aggiungere il basilico spezzettato.","Nel frattempo portare a bollore 450 ml di acqua salata con il latte, versare la polenta a pioggia mescolando con la frusta e cuocere 5-8 min (vedi confezione), mescolando, finché è densa e liscia.","Mantecare la polenta con il parmigiano rimasto e servirla nei piatti fondi con le polpette e il sugo."]}}'::jsonb),
  ('966cf969-f9be-46cc-8715-4c5085874d48'::uuid, '{"fr":{"title":"Ragù de champignons, lentilles et noix","steps":["Faire revenir l''oignon, la carotte et le céleri dans l''huile dans une grande sauteuse à feu moyen 8 min.","Ajouter les champignons et les noix et cuire 8 à 10 min en remuant, jusqu''à ce que les champignons aient rendu leur eau et commencent à dorer.","Incorporer l''ail et le concentré de tomate 1 min, puis verser le vin et laisser réduire de moitié.","Ajouter les tomates, le bouillon, les lentilles, la sauce soja, le thym et le laurier, porter à frémissement, couvrir à moitié et cuire 25 à 30 min en remuant de temps en temps, jusqu''à ce que les lentilles soient fondantes et la sauce épaisse ; ajouter un peu d''eau si besoin.","Pendant ce temps, cuire les pâtes al dente dans de l''eau bouillante salée en gardant un bol d''eau de cuisson.","Retirer le thym et le laurier, assaisonner le ragù et le mélanger aux pâtes en détendant avec l''eau de cuisson ; servir avec le basilic."]},"it":{"title":"Ragù di funghi, lenticchie e noci","steps":["Appassire cipolla, carota e sedano nell''olio in una padella larga a fuoco medio per 8 min.","Aggiungere i funghi e le noci e cuocere 8-10 min mescolando, finché i funghi hanno perso l''acqua e iniziano a dorare.","Unire l''aglio e il concentrato per 1 min, poi sfumare con il vino e lasciarlo ridurre della metà.","Aggiungere i pomodori, il brodo, le lenticchie, la salsa di soia, il timo e l''alloro, portare a bollore leggero, coprire a metà e cuocere 25-30 min mescolando ogni tanto, finché le lenticchie sono morbide e il sugo è denso; aggiungere un goccio d''acqua se si asciuga troppo.","Nel frattempo cuocere la pasta al dente in acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Togliere timo e alloro, regolare di sale e pepe e saltare il ragù con la pasta, allungando con l''acqua di cottura; servire con il basilico."]}}'::jsonb),
  ('ef9af9e4-429a-41fc-a675-41c9b617379a'::uuid, '{"fr":{"title":"Ribollita","steps":["Chauffer 2 c. à soupe d''huile dans une grande cocotte à feu doux et faire suer l''oignon, la carotte, le céleri, l''ail et le thym 10 min, sans coloration.","Ajouter la pomme de terre, le chou noir et le chou frisé, saler, poivrer et remuer 3 à 4 min jusqu''à ce que les feuilles tombent.","Ajouter les tomates, le concentré et le bouillon, porter à frémissement et cuire à couvert partiel 40 min.","Écraser la moitié des haricots en purée grossière à la fourchette ou au presse-purée avec une louche de soupe.","Incorporer la purée et les haricots entiers dans la cocotte et laisser mijoter encore 15 min.","Enfoncer le pain dans la soupe et cuire 10 min en remuant, jusqu''à ce qu''il se défasse et que la soupe soit épaisse ; ajouter un peu d''eau si besoin.","Rectifier l''assaisonnement et servir avec un filet d''huile d''olive crue, du poivre et du parmesan. Elle est encore meilleure réchauffée le lendemain."]},"it":{"title":"Ribollita","steps":["Scaldare 2 cucchiai d''olio in una pentola capiente a fuoco basso e stufare cipolla, carota, sedano, aglio e timo per 10 min, senza farli colorire.","Aggiungere la patata, il cavolo nero e la verza, salare, pepare e mescolare 3-4 min finché le foglie appassiscono.","Unire i pomodori, il concentrato e il brodo, portare a bollore leggero e cuocere semicoperto per 40 min.","Schiacciare metà dei fagioli con una forchetta o uno schiacciapatate insieme a un mestolo di zuppa, fino a una purea grossolana.","Unire la purea e i fagioli interi nella pentola e cuocere ancora 15 min.","Immergere il pane nella zuppa e cuocere 10 min mescolando, finché si sfalda e la zuppa è densa; aggiungere un po'' d''acqua se serve.","Regolare di sale e servire con un filo d''olio a crudo, pepe e parmigiano. Il giorno dopo, ribollita, è ancora più buona."]}}'::jsonb),
  ('8ffa559e-9ee1-4db0-b46c-a4956b1290be'::uuid, '{"fr":{"title":"Gnocchis aux poivrons rôtis et mozzarella","steps":["Préchauffer le four à 200 °C.","Mélanger les poivrons, l''oignon, les tomates cerises, l''ail et le thym avec 2 c. à soupe d''huile, du sel et du poivre dans un grand plat à rôtir.","Rôtir 25 min, jusqu''à ce que les poivrons soient fondants et cloqués et les tomates éclatées.","Écraser l''ail et les tomates à la fourchette pour obtenir une sauce rustique et retirer les tiges de thym.","Ajouter les gnocchis directement du paquet avec le reste d''huile et un peu d''eau, bien mélanger et rôtir 12 min, jusqu''à ce que les gnocchis soient tendres.","Parsemer de mozzarella et de parmesan et enfourner encore 8 à 10 min, jusqu''à ce que le fromage soit fondu et doré par endroits.","Servir parsemé de basilic."]},"it":{"title":"Gnocchi al forno con peperoni arrosto e mozzarella","steps":["Scaldare il forno a 200 °C.","Condire peperoni, cipolla, pomodorini, aglio e timo con 2 cucchiai d''olio, sale e pepe in una teglia grande.","Arrostire per 25 min, finché i peperoni sono morbidi e abbrustoliti e i pomodorini scoppiati.","Schiacciare l''aglio e i pomodorini con una forchetta per ottenere un sugo rustico ed eliminare i rametti di timo.","Aggiungere gli gnocchi direttamente dalla confezione con l''olio rimasto e un goccio d''acqua, mescolare bene e arrostire 12 min, finché gli gnocchi sono morbidi.","Distribuire la mozzarella e il parmigiano e infornare ancora 8-10 min, finché il formaggio è fuso e dorato qua e là.","Servire con il basilico."]}}'::jsonb),
  ('44542c57-7489-4eeb-ba0c-2a8923c197a8'::uuid, '{"fr":{"title":"Orzotto aux champignons","steps":["Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire sauter les champignons dans l''huile avec l''ail et le romarin à feu vif 6 à 8 min, jusqu''à ce qu''ils soient dorés ; assaisonner, réserver un tiers pour le dessus et retirer l''ail et le romarin.","Ajouter la moitié du beurre et l''échalote dans la sauteuse et faire fondre à feu moyen 3 min.","Ajouter l''orge et la nacrer 2 min en remuant, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant souvent et en attendant qu''il soit presque absorbé, pendant 30 à 35 min, jusqu''à ce que l''orge soit tendre mais encore légèrement ferme.","Hors du feu, incorporer le reste du beurre et le parmesan et laisser reposer 1 min ; l''orzotto doit être crémeux et souple.","Servir garni des champignons réservés, de persil et de poivre."]},"it":{"title":"Orzotto ai funghi","steps":["Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga saltare i funghi nell''olio con l''aglio e il rosmarino a fuoco vivo per 6-8 min, finché sono dorati; salare, tenerne da parte un terzo per guarnire ed eliminare aglio e rosmarino.","Aggiungere metà del burro e lo scalogno nella padella e appassire a fuoco medio per 3 min.","Unire l''orzo e tostarlo 2 min mescolando, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando spesso e aspettando che sia quasi assorbito, per 30-35 min, finché l''orzo è tenero ma ancora leggermente al dente.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano e lasciare riposare 1 min; deve risultare cremoso e morbido.","Servire con i funghi tenuti da parte, il prezzemolo e pepe nero."]}}'::jsonb),
  ('4ac67db3-15f0-4505-a682-a9989c256c89'::uuid, '{"fr":{"title":"Linguine aux crevettes, courgette et citron","steps":["Cuire les linguine al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, chauffer 2 c. à soupe d''huile dans une grande poêle à feu vif et faire dorer la courgette 4 à 5 min ; assaisonner et réserver.","Ajouter le reste d''huile, l''ail et une pincée de piment dans la poêle 30 s, puis ajouter les crevettes et cuire 2 à 3 min en les retournant une fois, jusqu''à ce qu''elles soient roses.","Remettre la courgette et ajouter le zeste et la moitié du jus de citron.","Ajouter les linguine égouttées avec un peu d''eau de cuisson et mélanger sur le feu 1 min, jusqu''à ce qu''elles soient brillantes.","Ajouter le persil, du jus de citron selon le goût, du sel et du poivre, et servir aussitôt."]},"it":{"title":"Linguine con gamberi, zucchine e limone","steps":["Cuocere le linguine al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo scaldare 2 cucchiai d''olio in una padella grande a fuoco vivo e dorare la zucchina per 4-5 min; salare e mettere da parte.","Aggiungere nella padella l''olio rimasto, l''aglio e un pizzico di peperoncino per 30 s, poi i gamberi e cuocerli 2-3 min girandoli una volta, finché sono rosa.","Rimettere la zucchina e aggiungere la scorza e metà del succo di limone.","Unire le linguine scolate con un po'' di acqua di cottura e saltare sul fuoco 1 min, finché sono lucide.","Aggiungere il prezzemolo, altro succo di limone a piacere, sale e pepe, e servire subito."]}}'::jsonb),
  ('4172c8f0-f681-446f-be3b-0a1848a9606c'::uuid, '{"fr":{"title":"Lasagnes aux épinards et champignons","steps":["Préchauffer le four à 200 °C.","Préparer la béchamel : faire fondre le beurre dans une casserole, ajouter la farine et remuer 1 min, puis verser le lait petit à petit en fouettant et laisser épaissir 5 min en remuant. Saler, poivrer, muscader et incorporer les deux tiers du parmesan.","Faire sauter les champignons avec l''ail dans l''huile dans une grande poêle à feu vif 8 min, jusqu''à ce qu''ils soient dorés ; ajouter le vin, le laisser s''évaporer, puis assaisonner.","Ajouter les épinards dans la poêle et remuer jusqu''à ce qu''ils tombent ; jeter le liquide éventuel.","Étaler une fine couche de béchamel dans un plat de 20 × 20 cm, puis alterner feuilles de lasagne, un tiers des champignons et épinards et un quart de la béchamel ; répéter deux fois.","Terminer par une couche de feuilles recouverte du reste de béchamel et de parmesan.","Enfourner 30 à 35 min, jusqu''à ce que le dessus soit doré et bouillonnant et qu''un couteau traverse facilement les pâtes.","Laisser reposer 10 min avant de découper."]},"it":{"title":"Lasagne con spinaci e funghi","steps":["Scaldare il forno a 200 °C.","Preparare la besciamella: sciogliere il burro in un pentolino, unire la farina e mescolare 1 min, poi aggiungere il latte poco alla volta con la frusta e cuocere 5 min mescolando, finché si addensa. Regolare di sale, pepe e noce moscata e incorporare due terzi del parmigiano.","Saltare i funghi con l''aglio nell''olio in una padella grande a fuoco vivo per 8 min, finché sono dorati; sfumare con il vino, lasciarlo evaporare e salare.","Aggiungere gli spinaci nella padella e mescolare finché sono appena appassiti; eliminare l''eventuale liquido.","Stendere un velo di besciamella in una pirofila da 20 × 20 cm, poi alternare sfoglie di lasagna, un terzo di funghi e spinaci e un quarto della besciamella; ripetere altre due volte.","Chiudere con un ultimo strato di sfoglie coperto con la besciamella e il parmigiano rimasti.","Infornare per 30-35 min, finché la superficie è dorata e bollente e un coltello affonda facilmente nella pasta.","Lasciare riposare 10 min prima di tagliare."]}}'::jsonb),
  ('a5aace29-d33e-4a90-9a9a-5ec39bbd6f9b'::uuid, '{"fr":{"title":"Pizzas sur pain plat, tomate et mozzarella","steps":["Préchauffer le four à 220 °C avec une plaque à l''intérieur.","Éponger les rondelles de tomate et la mozzarella déchirée avec du papier absorbant.","Mélanger le coulis de tomate avec l''ail, une pincée d''origan et du sel, puis l''étaler finement sur les pains en laissant une petite bordure.","Parsemer de mozzarella râpée, puis des rondelles de tomate et de la mozzarella déchirée ; assaisonner et arroser d''huile.","Glisser sur la plaque chaude et cuire 10 à 12 min, jusqu''à ce que la base soit croustillante et le fromage bouillonnant et doré par endroits.","Garnir de basilic frais et d''une pincée de piment, puis couper en parts."]},"it":{"title":"Pizzette su piadina con pomodoro e mozzarella","steps":["Scaldare il forno a 220 °C con una teglia all''interno.","Tamponare le fette di pomodoro e la mozzarella spezzettata con carta da cucina.","Mescolare la passata con l''aglio, un pizzico di origano e sale e stenderla sottile sulle focacce, lasciando un piccolo bordo.","Distribuire la mozzarella grattugiata, poi le fette di pomodoro e la mozzarella spezzettata; salare, pepare e irrorare con l''olio.","Trasferire sulla teglia calda e cuocere 10-12 min, finché la base è croccante e il formaggio è bollente e dorato qua e là.","Completare con basilico fresco e un pizzico di peperoncino e tagliare a spicchi."]}}'::jsonb),
  ('05fd4eac-be99-4274-a403-ad8b8821f794'::uuid, '{"fr":{"title":"Risotto au potiron, saucisse et sauge","steps":["Préchauffer le four à 200 °C. Mélanger le potiron avec l''huile, la moitié de la sauge, du sel et du poivre sur une plaque et rôtir 25 min, jusqu''à ce qu''il soit fondant et caramélisé sur les bords.","Pendant ce temps, porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, émietter la chair à saucisse et la faire dorer à feu moyen 5 min ; la retirer en laissant la graisse.","Ajouter la moitié du beurre, l''oignon et le reste de la sauge et faire fondre 5 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin et le laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant 16 à 18 min, jusqu''à ce que le riz soit crémeux et al dente ; incorporer la saucisse et la moitié du potiron écrasé à mi-cuisson.","Hors du feu, incorporer le reste du beurre et le parmesan, couvrir et laisser reposer 2 min.","Servir garni du reste du potiron rôti et des feuilles de sauge croustillantes."]},"it":{"title":"Risotto con zucca, salsiccia e salvia","steps":["Scaldare il forno a 200 °C. Condire la zucca con l''olio, metà della salvia, sale e pepe su una teglia e arrostire 25 min, finché è morbida e caramellata ai bordi.","Nel frattempo portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga sbriciolare la salsiccia e rosolarla a fuoco medio per 5 min; toglierla lasciando il grasso.","Aggiungere metà del burro, la cipolla e il resto della salvia e appassire per 5 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per 16-18 min, finché il riso è cremoso e al dente; a metà cottura unire la salsiccia e metà della zucca schiacciata.","Fuori dal fuoco mantecare con il burro rimasto e il parmigiano, coprire e lasciare riposare 2 min.","Servire con il resto della zucca arrosto e le foglie di salvia croccanti."]}}'::jsonb),
  ('4f5355b3-f2fd-4dbd-921a-d50d37544580'::uuid, '{"fr":{"title":"Gratin de pâtes au thon, tomate et épinards","steps":["Préchauffer le four à 180 °C.","Cuire les pâtes dans de l''eau bouillante salée 2 min de moins que le temps indiqué, puis les égoutter.","Pendant ce temps, faire revenir l''oignon et l''ail dans l''huile dans une poêle allant au four à feu moyen 4 min.","Ajouter les tomates, l''origan, du sel, du poivre et un peu d''eau et laisser mijoter 5 à 8 min, jusqu''à ce que la sauce épaississe légèrement.","Incorporer les épinards dans la sauce jusqu''à ce qu''ils tombent, puis retirer du feu et ajouter les pâtes.","Incorporer délicatement le thon en gros morceaux et parsemer de mozzarella.","Enfourner 15 à 20 min, jusqu''à ce que le fromage soit doré et la sauce bouillonnante sur les bords ; laisser reposer 3 min avant de servir."]},"it":{"title":"Pasta al forno con tonno, pomodoro e spinaci","steps":["Scaldare il forno a 180 °C.","Cuocere la pasta in acqua bollente salata 2 min in meno del tempo indicato, poi scolarla.","Nel frattempo appassire cipolla e aglio nell''olio in una padella adatta al forno a fuoco medio per 4 min.","Aggiungere i pomodori, l''origano, sale, pepe e un goccio d''acqua e cuocere 5-8 min, finché il sugo si addensa leggermente.","Unire gli spinaci al sugo e farli appassire, poi togliere dal fuoco e mescolare con la pasta.","Incorporare delicatamente il tonno a pezzi grossi e distribuire la mozzarella in superficie.","Infornare per 15-20 min, finché il formaggio è dorato e il sugo bolle ai bordi; lasciare riposare 3 min prima di servire."]}}'::jsonb),
  ('24abeaf1-16d2-4545-92bb-0c275f122522'::uuid, '{"fr":{"title":"Conchiglioni farcis aux épinards et à la ricotta","steps":["Préchauffer le four à 200 °C.","Faire tomber les épinards dans une grande casserole avec un peu d''eau 2 à 3 min, les égoutter, les laisser refroidir, les presser et les hacher finement.","Mélanger les épinards avec la ricotta, l''œuf, les deux tiers du parmesan, un peu de muscade, du sel et du poivre.","Remplir à nouveau la casserole d''eau salée et cuire les conchiglioni la moitié du temps indiqué (environ 6 min) ; les égoutter, les passer sous l''eau froide et les huiler légèrement.","Mélanger le coulis de tomate avec l''ail, le reste de l''huile, du sel et le basilic et l''étaler au fond d''un plat à gratin.","Garnir chaque coquille d''une bonne cuillerée de farce et les disposer côte à côte dans la sauce.","Parsemer du reste de parmesan, couvrir d''aluminium et enfourner 15 min, puis découvrir et cuire encore 10 min, jusqu''à ce que le dessus soit doré et la sauce bouillonnante."]},"it":{"title":"Conchiglioni ripieni di ricotta e spinaci","steps":["Scaldare il forno a 200 °C.","Far appassire gli spinaci in una pentola capiente con un goccio d''acqua per 2-3 min, scolarli, lasciarli raffreddare, strizzarli e tritarli finemente.","Mescolare gli spinaci con la ricotta, l''uovo, due terzi del parmigiano, una grattata di noce moscata, sale e pepe.","Riempire di nuovo la pentola con acqua salata e cuocere i conchiglioni per metà del tempo indicato (circa 6 min); scolarli, passarli sotto l''acqua fredda e ungerli con un filo d''olio.","Mescolare la passata con l''aglio, l''olio rimasto, sale e il basilico e stenderla sul fondo di una pirofila.","Farcire ogni conchiglione con una cucchiaiata abbondante di ripieno e sistemarli vicini nel sugo.","Cospargere con il parmigiano rimasto, coprire con l''alluminio e infornare 15 min, poi scoprire e cuocere altri 10 min, finché la superficie è dorata e il sugo bolle."]}}'::jsonb),
  ('55823f6d-25c8-4972-b71a-6303a4330168'::uuid, '{"fr":{"title":"Spaghetti aux sardines, citron et chapelure","steps":["Cuire les spaghetti al dente dans une grande casserole d''eau bouillante salée en gardant un bol d''eau de cuisson.","Pendant ce temps, faire griller la chapelure dans 1 c. à soupe d''huile dans une grande poêle à feu moyen 3 à 4 min en remuant, jusqu''à ce qu''elle soit dorée et croustillante ; y mélanger le zeste de citron et une pincée de sel, puis la verser dans un bol.","Essuyer la poêle, ajouter le reste d''huile, l''ail, les câpres et une pincée de piment et cuire doucement 1 à 2 min sans colorer l''ail.","Ajouter les sardines et les briser en morceaux à la cuillère ; réchauffer 1 min.","Ajouter les spaghetti égouttés avec un peu d''eau de cuisson, le jus de citron et la majeure partie du persil, et mélanger jusqu''à ce qu''ils soient brillants.","Servir parsemé de chapelure croustillante, du reste de persil et de poivre."]},"it":{"title":"Spaghetti con sarde, limone e pangrattato","steps":["Cuocere gli spaghetti al dente in abbondante acqua bollente salata, tenendo da parte una tazza di acqua di cottura.","Nel frattempo tostare il pangrattato in 1 cucchiaio d''olio in una padella grande a fuoco medio per 3-4 min, mescolando, finché è dorato e croccante; unire la scorza di limone e un pizzico di sale e versarlo in una ciotola.","Pulire la padella, aggiungere l''olio rimasto, l''aglio, i capperi e un pizzico di peperoncino e cuocere dolcemente 1-2 min senza far colorire l''aglio.","Aggiungere le sarde e spezzettarle con un cucchiaio; scaldarle 1 min.","Unire gli spaghetti scolati con un po'' di acqua di cottura, il succo di limone e quasi tutto il prezzemolo e saltare finché sono lucidi.","Servire con il pangrattato croccante, il prezzemolo rimasto e pepe nero."]}}'::jsonb),
  ('d05206b1-877d-46fa-bc31-639b46637ae4'::uuid, '{"fr":{"title":"Tagliatelle à la bolognaise de dinde","steps":["Faire revenir la carotte, l''oignon et le céleri dans l''huile dans une sauteuse à fond épais à feu moyen 8 min.","Ajouter la dinde et l''ail, monter le feu et cuire 6 à 8 min en l''émiettant, jusqu''à ce qu''elle ne soit plus rose et commence à dorer.","Incorporer le concentré de tomate 1 min, puis verser le vin et le laisser réduire presque entièrement.","Ajouter les tomates, le lait, le laurier, un peu de muscade, du sel et du poivre, porter à frémissement et cuire doucement à couvert partiel 25 à 30 min, jusqu''à ce que la sauce soit épaisse ; ajouter un peu d''eau si elle attache.","Pendant ce temps, cuire les tagliatelle al dente dans de l''eau bouillante salée en gardant un peu d''eau de cuisson.","Retirer le laurier, mélanger les pâtes avec la sauce et un peu d''eau de cuisson, et servir avec du parmesan."]},"it":{"title":"Tagliatelle al ragù di tacchino","steps":["Appassire carota, cipolla e sedano nell''olio in un tegame dal fondo spesso a fuoco medio per 8 min.","Aggiungere il tacchino e l''aglio, alzare la fiamma e cuocere 6-8 min sgranandolo, finché non è più rosa e inizia a rosolare.","Unire il concentrato per 1 min, poi sfumare con il vino e lasciarlo evaporare quasi del tutto.","Aggiungere i pomodori, il latte, l''alloro, una grattata di noce moscata, sale e pepe, portare a bollore leggero e cuocere dolcemente semicoperto per 25-30 min, finché il ragù è denso; aggiungere un goccio d''acqua se attacca.","Nel frattempo cuocere le tagliatelle al dente in acqua bollente salata, tenendo da parte un po'' di acqua di cottura.","Togliere l''alloro, condire la pasta con il ragù e un goccio di acqua di cottura e servire con il parmigiano."]}}'::jsonb),
  ('b52abd15-1267-4830-a431-c33e87f52e3d'::uuid, '{"fr":{"title":"Risotto aux crevettes, petits pois et citron","steps":["Porter le fumet à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote et l''ail dans le beurre et 1 c. à soupe d''huile à feu moyen 4 min.","Ajouter le riz et remuer 2 min, jusqu''à ce que les grains deviennent translucides sur les bords, puis verser le vin et le laisser s''évaporer.","Ajouter le fumet chaud louche par louche en remuant et en le laissant absorber avant la suivante, pendant environ 12 min.","Incorporer les petits pois et les crevettes et continuer à ajouter du fumet 5 à 6 min, jusqu''à ce que les crevettes soient roses et le riz crémeux et al dente.","Hors du feu, incorporer le jus de citron, le reste d''huile, la majeure partie du persil et une pincée de piment ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé du zeste de citron et du reste de persil."]},"it":{"title":"Risotto con gamberi, piselli e limone","steps":["Portare il fumetto a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno e l''aglio nel burro e in 1 cucchiaio d''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, finché i chicchi diventano traslucidi ai bordi, poi sfumare con il vino e lasciarlo evaporare.","Aggiungere il fumetto caldo un mestolo alla volta, mescolando e lasciandolo assorbire prima del successivo, per circa 12 min.","Unire i piselli e i gamberi e continuare ad aggiungere fumetto per altri 5-6 min, finché i gamberi sono rosa e il riso è cremoso e al dente.","Fuori dal fuoco mantecare con il succo di limone, l''olio rimasto, quasi tutto il prezzemolo e un pizzico di peperoncino; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la scorza di limone e il prezzemolo rimasto."]}}'::jsonb),
  ('4c97e702-12b8-4dc5-a739-715df1150d37'::uuid, '{"fr":{"title":"Risotto au citron, petits pois et asperges","steps":["Couper les pointes d''asperges et les réserver ; tailler les tiges en tronçons de 2 cm.","Porter le bouillon à frémissement dans une casserole et le garder chaud.","Dans une grande sauteuse, faire fondre l''échalote dans la moitié du beurre et l''huile à feu moyen 4 min.","Ajouter le riz et le nacrer 2 min, puis verser le vin avec la moitié du jus de citron et laisser s''évaporer.","Ajouter le bouillon chaud louche par louche en remuant et en le laissant absorber, pendant environ 10 min ; ajouter alors les tiges d''asperges.","Après 4 min, ajouter les pointes et les petits pois et continuer à mouiller 4 à 5 min, jusqu''à ce que le riz soit crémeux et al dente et les asperges juste tendres.","Hors du feu, incorporer le reste du beurre, le parmesan, le jaune d''œuf, le zeste et le reste du jus de citron ; assaisonner, couvrir et laisser reposer 1 min.","Servir parsemé de menthe."]},"it":{"title":"Risotto al limone con piselli e asparagi","steps":["Tagliare le punte degli asparagi e tenerle da parte; tagliare i gambi a tocchetti di 2 cm.","Portare il brodo a bollore leggero in un pentolino e tenerlo caldo.","In una padella larga appassire lo scalogno in metà del burro e nell''olio a fuoco medio per 4 min.","Unire il riso e tostarlo 2 min, poi sfumare con il vino e metà del succo di limone e lasciare evaporare.","Aggiungere il brodo caldo un mestolo alla volta, mescolando e lasciandolo assorbire, per circa 10 min; poi unire i gambi degli asparagi.","Dopo altri 4 min aggiungere le punte e i piselli e continuare a bagnare per 4-5 min, finché il riso è cremoso e al dente e gli asparagi appena teneri.","Fuori dal fuoco mantecare con il burro rimasto, il parmigiano, il tuorlo, la scorza e il resto del succo di limone; regolare di sale, coprire e lasciare riposare 1 min.","Servire con la menta."]}}'::jsonb),
  ('4427b42a-5623-490b-af00-1004887dfb98'::uuid, '{"fr":{"title":"Bar, salade de fenouil et d''orange","steps":["Cuire les pommes de terre 15 à 18 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres ; les égoutter et les mélanger avec 1 c. à soupe d''huile, le persil et du sel.","Pendant ce temps, peler à vif 1,5 orange et la couper en rondelles ; presser la demi-orange restante.","Mélanger le fenouil, les rondelles d''orange, l''oignon rouge et les olives avec le jus d''orange, la moitié du jus de citron, 2 c. à soupe d''huile, du sel et du poivre ; laisser reposer 10 min.","Sécher le poisson, inciser la peau à quelques endroits et assaisonner des deux côtés.","Chauffer le reste d''huile dans une poêle à feu moyen-vif et cuire les filets côté peau 3 à 4 min, en les pressant au début, jusqu''à ce que la peau soit croustillante.","Retourner et cuire encore 1 à 2 min, jusqu''à ce que la chair soit juste nacrée ; arroser du reste de jus de citron.","Servir le poisson sur la salade, parsemé de pluches de fenouil, avec les pommes de terre à côté."]},"it":{"title":"Branzino con insalata di finocchi e arance","steps":["Lessare le patate in acqua salata per 15-18 min, finché sono tenere; scolarle e condirle con 1 cucchiaio d''olio, il prezzemolo e sale.","Nel frattempo pelare a vivo 1 arancia e mezza e tagliarla a fette; spremere la mezza arancia rimasta.","Condire finocchio, fette d''arancia, cipolla rossa e olive con il succo d''arancia, metà del succo di limone, 2 cucchiai d''olio, sale e pepe; lasciare insaporire 10 min.","Asciugare il pesce, incidere la pelle in qualche punto e salare e pepare da entrambi i lati.","Scaldare l''olio rimasto in una padella a fuoco medio-alto e cuocere i filetti dal lato della pelle per 3-4 min, premendoli all''inizio, finché la pelle è croccante.","Girarli e cuocere ancora 1-2 min, finché la carne è appena opaca; irrorare con il resto del succo di limone.","Servire il pesce sull''insalata, con le barbe del finocchio, e le patate a parte."]}}'::jsonb),
  ('7f8f28eb-fb9c-48ec-9d27-6298066de40a'::uuid, '{"fr":{"title":"Gnocchis gratinés au potiron et gorgonzola","steps":["Préchauffer le four à 200 °C.","Mélanger le potiron avec l''huile, la sauge, du sel et du poivre dans un plat à gratin et rôtir 20 min, jusqu''à ce qu''il soit tendre ; en écraser environ la moitié à la fourchette.","Pendant ce temps, faire fondre le beurre dans une casserole, ajouter la farine et remuer 1 min, puis verser le lait en fouettant et laisser épaissir légèrement 3 min.","Ajouter le gorgonzola et remuer à feu doux jusqu''à ce qu''il soit fondu et la sauce lisse ; poivrer et muscader légèrement.","Cuire les gnocchis dans de l''eau bouillante salée jusqu''à ce qu''ils remontent à la surface, 2 à 3 min, puis les égoutter.","Ajouter les gnocchis et la sauce au potiron dans le plat et mélanger délicatement.","Parsemer de parmesan et de noix et enfourner 15 min, jusqu''à ce que le gratin bouillonne et soit doré ; laisser reposer 3 min avant de servir."]},"it":{"title":"Gnocchi gratinati con zucca e gorgonzola","steps":["Scaldare il forno a 200 °C.","Condire la zucca con l''olio, la salvia, sale e pepe in una pirofila e arrostirla per 20 min, finché è morbida; schiacciarne circa metà con una forchetta.","Nel frattempo sciogliere il burro in un pentolino, unire la farina e mescolare 1 min, poi aggiungere il latte con la frusta e cuocere 3 min finché si addensa leggermente.","Aggiungere il gorgonzola e mescolare a fuoco basso finché è fuso e la crema è liscia; pepare e profumare con poca noce moscata.","Lessare gli gnocchi in acqua bollente salata finché salgono a galla, 2-3 min, e scolarli.","Unire gli gnocchi e la crema alla zucca nella pirofila e mescolare delicatamente.","Cospargere con il parmigiano e le noci e infornare per 15 min, finché bolle e si forma una crosticina dorata; lasciare riposare 3 min prima di servire."]}}'::jsonb),
  ('2fd32898-57b1-45e1-83f9-89850157adf0'::uuid, '{"fr":{"title":"Spaghetti au saumon fumé et petits pois","steps":["Cuire les spaghetti dans une grande casserole d''eau bouillante salée en ajoutant les petits pois pendant les 3 dernières minutes.","Pendant ce temps, fouetter le yaourt, la crème, le jaune d''œuf, le parmesan, le zeste de citron, du sel et beaucoup de poivre dans un bol.","Garder un bol d''eau de cuisson, puis égoutter les pâtes et les petits pois et les remettre dans la casserole hors du feu avec 3 c. à soupe d''eau.","Verser la sauce et mélanger sur feu très doux 1 à 2 min, jusqu''à ce qu''elle soit crémeuse et enrobe les pâtes ; ne pas laisser bouillir pour que l''œuf ne coagule pas.","Incorporer le saumon fumé et la majeure partie de la ciboulette, ajouter un filet de citron et détendre avec un peu d''eau de cuisson si besoin.","Servir aussitôt avec le reste de la ciboulette et du poivre."]},"it":{"title":"Spaghetti con salmone affumicato e piselli","steps":["Cuocere gli spaghetti in abbondante acqua bollente salata, aggiungendo i piselli negli ultimi 3 min.","Nel frattempo sbattere in una ciotola lo yogurt, la panna, il tuorlo, il parmigiano, la scorza di limone, sale e abbondante pepe.","Tenere da parte una tazza di acqua di cottura, poi scolare pasta e piselli e rimetterli nella pentola fuori dal fuoco con 3 cucchiai d''acqua.","Versare la salsa e mescolare a fuoco bassissimo per 1-2 min, finché è cremosa e avvolge la pasta; non farla bollire o l''uovo si rapprende.","Unire il salmone affumicato e quasi tutta l''erba cipollina, aggiungere una spruzzata di limone e allungare con altra acqua di cottura se serve.","Servire subito con l''erba cipollina rimasta e pepe nero."]}}'::jsonb),
  ('6c246a38-571f-4eb9-b95c-baad65375613'::uuid, '{"fr":{"title":"Plaque de poulet au pesto et tomates cerises","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante). Mélanger les pommes de terre coupées en deux avec l''huile, du sel et du poivre sur une grande plaque et rôtir 20 min.","Pendant ce temps, enrober les hauts de cuisse de poulet de 2 c. à soupe de pesto, d''un peu de sel et de poivre.","Pousser les pommes de terre sur le côté, ajouter le poulet et les quartiers d''oignon sur la plaque et rôtir 15 min.","Ajouter les tomates cerises et rôtir encore 10 min, jusqu''à ce que les tomates éclatent et que le poulet soit cuit à cœur, avec un jus clair.","Détendre le reste du pesto avec le jus de citron et le verser sur le poulet. Parsemer de basilic et servir sur la plaque."]},"it":{"title":"Teglia di pollo al pesto e pomodorini","steps":["Scaldare il forno a 200 °C (180 °C ventilato). Condire le patate tagliate a metà con l''olio, sale e pepe su una grande teglia e arrostire 20 min.","Nel frattempo, ricoprire le sovracosce di pollo con 2 cucchiai di pesto, un po'' di sale e pepe.","Spostare le patate di lato, aggiungere il pollo e gli spicchi di cipolla nella teglia e arrostire 15 min.","Aggiungere i pomodorini e arrostire altri 10 min, finché i pomodorini si spaccano e il pollo è cotto all''interno, con succhi chiari.","Allungare il pesto rimasto con il succo di limone e versarlo sul pollo. Completare con il basilico e servire nella teglia."]}}'::jsonb),
  ('67056eba-a09c-484e-98ec-cf1f2b086b9e'::uuid, '{"fr":{"title":"Calzones aux champignons et mozzarella","steps":["Mélanger la farine, la levure et le sel, ajouter 160 ml d''eau tiède et 1 c. à soupe d''huile, et pétrir 8 à 10 min jusqu''à obtenir une pâte lisse et élastique. Couvrir et laisser lever environ 1 h, jusqu''à ce qu''elle double de volume.","Faire sauter les champignons dans le reste d''huile à feu vif 5 à 6 min, jusqu''à ce qu''ils soient dorés et secs ; ajouter l''ail et le thym la dernière minute.","Ajouter les épinards et remuer 1 à 2 min jusqu''à ce qu''ils tombent et que la poêle soit sèche. Saler, poivrer et laisser refroidir.","Préchauffer le four à 230 °C avec une plaque à l''intérieur. Mélanger la ricotta avec le parmesan et un peu de poivre.","Diviser la pâte en deux et étirer ou abaisser chaque pâton en un disque de 25 cm sur un plan fariné.","Étaler le coulis de tomate sur une moitié de chaque disque en laissant un bord de 2 cm, puis ajouter la ricotta, les champignons et la mozzarella.","Replier la pâte, presser et pincer fermement les bords, faire une petite cheminée et badigeonner le dessus d''un peu d''huile.","Glisser les calzones sur la plaque chaude et cuire 15 à 18 min, jusqu''à ce qu''ils soient gonflés et bien dorés. Laisser reposer 5 min avant de couper."]},"it":{"title":"Calzoni ai funghi e mozzarella","steps":["Mescolare la farina, il lievito e il sale, aggiungere 160 ml di acqua tiepida e 1 cucchiaio d''olio e impastare 8-10 min fino a ottenere un impasto liscio ed elastico. Coprire e lasciare lievitare circa 1 ora, finché raddoppia.","Saltare i funghi nell''olio rimasto a fuoco vivo per 5-6 min, finché sono dorati e asciutti; aggiungere l''aglio e il timo nell''ultimo minuto.","Aggiungere gli spinaci e mescolare 1-2 min finché appassiscono e la padella è asciutta. Salare, pepare e lasciare raffreddare.","Scaldare il forno a 230 °C con una teglia all''interno. Mescolare la ricotta con il parmigiano e un po'' di pepe.","Dividere l''impasto in due e stendere ogni pezzo in un disco di 25 cm su un piano infarinato.","Spalmare la passata su metà di ogni disco lasciando un bordo di 2 cm, poi aggiungere la ricotta, i funghi e la mozzarella.","Ripiegare l''impasto, premere e pizzicare bene i bordi, praticare un piccolo foro per il vapore e spennellare la superficie con un filo d''olio.","Far scivolare i calzoni sulla teglia calda e cuocere 15-18 min, finché sono gonfi e ben dorati. Lasciare riposare 5 min prima di tagliarli."]}}'::jsonb),
  ('f8703f9d-af88-479d-bf23-0d5a062540bc'::uuid, '{"fr":{"title":"Raviolis ricotta-citron aux petits pois","steps":["Disposer la farine en fontaine, casser les œufs au centre et mélanger à la fourchette, puis pétrir 8 à 10 min jusqu''à obtenir une pâte lisse et élastique. Filmer et laisser reposer 30 min.","Mélanger la ricotta, le parmesan, le zeste de citron, la muscade, du sel et beaucoup de poivre pour obtenir une farce ferme.","Abaisser la pâte très finement (environ 1 mm, presque transparente) au rouleau ou au laminoir, et la couper en deux longues bandes.","Déposer des cuillerées à café de farce espacées de 4 cm sur une bande, humidifier autour à l''eau, couvrir avec la seconde bande et chasser l''air autour de chaque tas de farce.","Découper les raviolis, bien presser les bords pour les souder et les poser sur un plateau fariné.","Cuire les raviolis dans une grande casserole d''eau salée à petite ébullition 3 à 4 min, en ajoutant les petits pois les 2 dernières minutes.","Pendant ce temps, faire fondre le beurre à feu doux dans une grande poêle avec un filet de jus de citron.","Transférer les raviolis et les petits pois dans la poêle à l''écumoire, ajouter une petite louche d''eau de cuisson et mélanger délicatement 1 min jusqu''à ce que ce soit brillant. Servir avec la menthe, du poivre et du parmesan."]},"it":{"title":"Ravioli ricotta e limone con piselli","steps":["Disporre la farina a fontana, rompere le uova al centro e sbattere con una forchetta, poi impastare 8-10 min fino a ottenere un impasto liscio ed elastico. Avvolgere nella pellicola e lasciare riposare 30 min.","Mescolare la ricotta, il parmigiano, la scorza di limone, la noce moscata, sale e abbondante pepe per ottenere un ripieno sodo.","Stendere la pasta molto sottile (circa 1 mm, quasi trasparente) con il mattarello o la macchina per la pasta e tagliarla in due lunghe sfoglie.","Disporre cucchiaini di ripieno a 4 cm di distanza su una sfoglia, spennellare intorno con acqua, coprire con la seconda sfoglia e premere per far uscire l''aria intorno a ogni mucchietto.","Ritagliare i ravioli, premere bene i bordi per sigillarli e disporli su un vassoio infarinato.","Cuocere i ravioli in una pentola grande di acqua salata a leggero bollore per 3-4 min, aggiungendo i piselli negli ultimi 2 min.","Nel frattempo, sciogliere il burro a fuoco basso in una padella grande con una spruzzata di succo di limone.","Trasferire ravioli e piselli nella padella con una schiumarola, aggiungere un mestolino di acqua di cottura e saltare delicatamente 1 min finché è lucido. Servire con la menta, pepe e altro parmigiano."]}}'::jsonb),
  ('3ee4b676-aad6-4e46-8795-8605729489d0'::uuid, '{"fr":{"title":"Orecchiette au brocoli et à la saucisse","steps":["Porter à ébullition une grande casserole d''eau salée et y cuire les fleurettes de brocoli à couvert 6 à 7 min, jusqu''à ce qu''elles soient tendres. Les retirer à l''écumoire et garder l''eau.","Pendant ce temps, chauffer l''huile dans une grande poêle avec l''ail, puis ajouter la chair à saucisse émiettée, le romarin, le thym et le piment et cuire à feu moyen-vif 6 à 7 min jusqu''à ce qu''elle soit dorée.","Verser le vin et laisser bouillonner 1 min jusqu''à ce qu''il ait presque disparu.","Ajouter le brocoli et cuire 3 à 4 min en écrasant une partie des fleurettes à la cuillère. Retirer l''ail et poivrer.","Remettre l''eau du brocoli à ébullition et y cuire les orecchiette juste al dente.","Transférer les pâtes dans la poêle à l''écumoire, ajouter une louche d''eau de cuisson et mélanger sur le feu 2 min jusqu''à ce que ce soit crémeux. Servir avec le parmesan."]},"it":{"title":"Orecchiette con broccoli e salsiccia","steps":["Portare a bollore una pentola grande di acqua salata e cuocere le cimette di broccoli, coperte, per 6-7 min finché sono tenere. Scolarle con una schiumarola e tenere l''acqua.","Nel frattempo, scaldare l''olio in una padella grande con l''aglio, poi aggiungere la salsiccia sbriciolata, il rosmarino, il timo e il peperoncino e rosolare a fuoco medio-alto 6-7 min finché è dorata.","Sfumare con il vino e lasciarlo evaporare per 1 min.","Aggiungere i broccoli e cuocere 3-4 min, schiacciando parte delle cimette con il cucchiaio. Togliere l''aglio e pepare.","Riportare a bollore l''acqua dei broccoli e cuocere le orecchiette al dente.","Trasferire la pasta nella padella con una schiumarola, aggiungere un mestolo di acqua di cottura e saltare sul fuoco per 2 min finché è cremosa. Servire con il parmigiano."]}}'::jsonb),
  ('25acb8ff-311c-4665-944e-84f483b0e912'::uuid, '{"fr":{"title":"Épinards aux pois chiches à la sévillane","steps":["Plonger les œufs dans l''eau bouillante et les cuire 9 min, puis les refroidir dans l''eau froide et les écaler.","Faire tomber les épinards dans une grande poêle avec un peu d''eau à feu moyen 2 à 3 min, puis les égoutter, les presser et les hacher finement.","Essuyer la poêle, chauffer l''huile et y faire dorer les gousses d''ail entières et le pain à feu moyen 2 à 3 min. Les retirer en gardant l''huile dans la poêle.","Piler l''ail et le pain au mortier avec le cumin, le paprika, le piment et une pincée de sel, puis incorporer le vinaigre, le coulis de tomate et 3 c. à soupe d''eau pour obtenir une pâte lisse.","Réchauffer l''huile, ajouter les épinards et remuer 2 min, puis incorporer la pâte et cuire encore 2 min.","Ajouter les pois chiches et environ 100 ml d''eau et laisser mijoter 5 min en remuant, jusqu''à obtenir une sauce épaisse. Rectifier l''assaisonnement.","Servir dans des assiettes creuses, garni des œufs coupés en deux et d''un peu de poivre."]},"it":{"title":"Spinaci con ceci alla sivigliana","steps":["Immergere le uova in acqua bollente e cuocerle 9 min, poi raffreddarle in acqua fredda e sgusciarle.","Far appassire gli spinaci in una padella grande con un goccio d''acqua a fuoco medio per 2-3 min, poi scolarli, strizzarli e tritarli finemente.","Asciugare la padella, scaldare l''olio e dorare gli spicchi d''aglio interi e il pane a fuoco medio per 2-3 min. Toglierli, lasciando l''olio nella padella.","Pestare l''aglio e il pane nel mortaio con il cumino, la paprika, il peperoncino e un pizzico di sale, poi incorporare l''aceto, la passata e 3 cucchiai d''acqua fino a ottenere una pasta liscia.","Riscaldare l''olio, aggiungere gli spinaci e mescolare 2 min, poi unire la pasta e cuocere altri 2 min.","Aggiungere i ceci e circa 100 ml d''acqua e cuocere a fuoco lento 5 min, mescolando, finché è denso e cremoso. Regolare di sale.","Servire in piatti fondi con le uova tagliate a metà e un po'' di pepe."]}}'::jsonb),
  ('6307f25f-d0c5-41b7-9da7-b1c9edcf87e7'::uuid, '{"fr":{"title":"Cabillaud poché à la tomate et aux haricots blancs","steps":["Faire revenir l''oignon et le poivron dans l''huile dans une sauteuse à feu moyen 8 min.","Ajouter l''ail et le paprika et remuer 30 s, puis verser le vin et laisser bouillonner 1 min.","Ajouter les tomates et le laurier, saler, poivrer et laisser mijoter 10 min jusqu''à ce que la sauce épaississe.","Incorporer les haricots et laisser mijoter 3 min.","Assaisonner le cabillaud, le déposer dans la sauce, couvrir et pocher à feu doux 7 à 8 min, jusqu''à ce que le poisson soit nacré et s''effeuille facilement.","Parsemer de persil et servir directement dans la sauteuse."]},"it":{"title":"Merluzzo in umido al pomodoro con fagioli bianchi","steps":["Far appassire la cipolla e il peperone nell''olio in una padella larga a fuoco medio per 8 min.","Aggiungere l''aglio e la paprika e mescolare 30 s, poi versare il vino e lasciarlo sobbollire 1 min.","Aggiungere i pomodori e l''alloro, regolare di sale e pepe e cuocere a fuoco lento 10 min finché il sugo si addensa.","Unire i fagioli e cuocere 3 min.","Condire il merluzzo, adagiarlo nel sugo, coprire e cuocere a fuoco basso 7-8 min, finché il pesce è opaco e si sfalda facilmente.","Completare con il prezzemolo e servire direttamente nella padella."]}}'::jsonb),
  ('3c4bc8c3-19f4-40b7-b916-4f9a3660a44f'::uuid, '{"fr":{"title":"Tortilla de patatas et salade de tomates","steps":["Couper les pommes de terre en rondelles de 2 à 3 mm. Couvrir le fond d''une poêle antiadhésive de 20 cm d''1 cm d''huile d''olive et chauffer à feu moyen.","Ajouter les pommes de terre et l''oignon avec une pincée de sel et cuire doucement 15 à 20 min en remuant de temps en temps, jusqu''à ce qu''ils soient tendres mais à peine colorés.","Égoutter les pommes de terre dans une passoire au-dessus d''un bol, en gardant l''huile pour une autre fois.","Battre les œufs avec du sel, y incorporer les pommes de terre tièdes et laisser reposer 5 min.","Chauffer 1 c. à soupe de l''huile dans la poêle à feu moyen-vif, verser le mélange et cuire 3 à 4 min en secouant la poêle, jusqu''à ce que les bords soient pris.","Couvrir la poêle d''une assiette, retourner la tortilla dessus et la faire glisser à nouveau dans la poêle. Cuire encore 2 à 3 min en gardant le centre légèrement baveux.","Trancher les tomates sur une assiette, ajouter l''oignon rouge et le thon émietté, et assaisonner avec 1 c. à soupe d''huile, le vinaigre, du sel et l''origan. Servir avec la tortilla tiède ou à température ambiante."]},"it":{"title":"Tortilla de patatas con insalata di pomodori","steps":["Tagliare le patate a fette di 2-3 mm. Coprire il fondo di una padella antiaderente da 20 cm con 1 cm di olio d''oliva e scaldare a fuoco medio.","Aggiungere le patate e la cipolla con un pizzico di sale e cuocere dolcemente 15-20 min, girando ogni tanto, finché sono morbide ma poco colorite.","Scolare le patate in un colino sopra una ciotola, tenendo l''olio per un altro uso.","Sbattere le uova con il sale, unire le patate tiepide e lasciare riposare 5 min.","Scaldare 1 cucchiaio dell''olio nella padella a fuoco medio-alto, versare il composto e cuocere 3-4 min, scuotendo la padella, finché i bordi si rapprendono.","Coprire la padella con un piatto, capovolgere la tortilla sul piatto e farla scivolare di nuovo nella padella. Cuocere altri 2-3 min, lasciando il centro leggermente morbido.","Affettare i pomodori su un piatto, aggiungere la cipolla rossa e il tonno sbriciolato e condire con 1 cucchiaio d''olio, l''aceto, sale e origano. Servire con la tortilla tiepida o a temperatura ambiente."]}}'::jsonb),
  ('c47e6281-33c2-439b-ae58-28c4ee81253b'::uuid, '{"fr":{"title":"Merlu au paprika, poivrons et pommes de terre","steps":["Préchauffer le four à 200 °C. Mélanger les pommes de terre, les poivrons et l''oignon avec 2 c. à soupe d''huile, du sel et du poivre dans un plat à rôtir.","Rôtir 25 à 30 min en remuant une fois, jusqu''à ce que les pommes de terre soient tendres et commencent à dorer.","Assaisonner le merlu, le poser sur les légumes côté peau dessous et rôtir 10 à 12 min, jusqu''à ce que la chair soit nacrée et s''effeuille tout juste.","Pendant ce temps, faire revenir l''ail dans les 2 c. à soupe d''huile restantes dans une petite poêle à feu moyen-doux 2 à 3 min, jusqu''à ce qu''il soit blond.","Retirer la poêle du feu, incorporer le paprika puis le vinaigre.","Napper le poisson de l''huile chaude au paprika, parsemer de persil et servir."]},"it":{"title":"Nasello alla paprika con peperoni e patate","steps":["Scaldare il forno a 200 °C. Condire le patate, i peperoni e la cipolla con 2 cucchiai d''olio, sale e pepe in una pirofila.","Arrostire 25-30 min, mescolando una volta, finché le patate sono tenere e iniziano a colorire.","Condire il nasello, adagiarlo sulle verdure con la pelle in basso e arrostire 10-12 min, finché la polpa è opaca e si sfalda appena.","Nel frattempo, soffriggere l''aglio nei 2 cucchiai d''olio rimasti in un padellino a fuoco medio-basso per 2-3 min, finché è appena dorato.","Togliere il padellino dal fuoco, unire la paprika e poi l''aceto.","Versare l''olio caldo alla paprika sul pesce, completare con il prezzemolo e servire."]}}'::jsonb),
  ('0dce17d0-cb2a-43f8-9113-4566cf6ea46b'::uuid, '{"fr":{"title":"Gambas al ajillo aux haricots blancs","steps":["Griller les tranches de pain dans une poêle sèche 1 à 2 min de chaque côté, puis réserver.","Sécher les crevettes et les saler légèrement.","Chauffer l''huile, l''ail et le piment dans la poêle à feu moyen 2 à 3 min, jusqu''à ce que l''ail commence à blondir.","Monter le feu, ajouter les crevettes et cuire 1 min de chaque côté jusqu''à ce qu''elles rosissent.","Verser le xérès, saupoudrer de paprika et laisser bouillonner 30 s.","Ajouter les haricots et mélanger 2 à 3 min jusqu''à ce qu''ils soient chauds et enrobés d''huile à l''ail. Finir avec un filet de citron et le persil et servir avec le pain grillé pour saucer."]},"it":{"title":"Gamberi all''aglio con fagioli bianchi","steps":["Tostare le fette di pane in una padella asciutta 1-2 min per lato, poi tenerle da parte.","Asciugare i gamberi e salarli leggermente.","Scaldare l''olio, l''aglio e il peperoncino nella padella a fuoco medio per 2-3 min, finché l''aglio inizia a dorare.","Alzare la fiamma, aggiungere i gamberi e cuocere 1 min per lato finché diventano rosa.","Versare lo sherry, cospargere di paprika e lasciar sobbollire 30 s.","Aggiungere i fagioli e saltare 2-3 min finché sono caldi e ricoperti d''olio all''aglio. Completare con una spruzzata di limone e il prezzemolo e servire con il pane tostato per fare la scarpetta."]}}'::jsonb),
  ('f42e4280-fed9-47cc-9ccd-5bb37ad400ea'::uuid, '{"fr":{"title":"Gaspacho aux œufs et jambon serrano","steps":["Mettre les tomates, le poivron, le concombre, l''ail et le pain dans un blender avec le vinaigre, 100 ml d''eau froide et 1 c. à café de sel et mixer 2 min jusqu''à ce que ce soit parfaitement lisse.","Moteur en marche, verser l''huile jusqu''à ce que la soupe devienne crémeuse. Goûter et rectifier le sel et le vinaigre.","Passer au tamis pour une texture soyeuse si on le souhaite, puis réfrigérer au moins 2 h.","Plonger les œufs dans l''eau bouillante, les cuire 10 min, les refroidir dans l''eau froide, les écaler et les hacher.","Faire croustiller les dés de jambon dans une poêle sèche à feu moyen 3 à 4 min, puis griller les cubes de pain dans la même poêle 2 à 3 min.","Verser le gaspacho froid dans des bols et garnir d''œuf, de jambon et de croûtons."]},"it":{"title":"Gazpacho con uova e jamón","steps":["Mettere i pomodori, il peperone, il cetriolo, l''aglio e il pane nel frullatore con l''aceto, 100 ml di acqua fredda e 1 cucchiaino di sale e frullare 2 min fino a ottenere un composto perfettamente liscio.","Con il frullatore in funzione, versare l''olio finché la zuppa diventa cremosa. Assaggiare e regolare di sale e aceto.","Passare al setaccio per una consistenza vellutata, se si desidera, poi mettere in frigorifero almeno 2 ore.","Immergere le uova in acqua bollente, cuocerle 10 min, raffreddarle in acqua fredda, sgusciarle e tritarle.","Rendere croccante il jamón a dadini in una padella asciutta a fuoco medio per 3-4 min, poi tostare i cubetti di pane nella stessa padella per 2-3 min.","Versare il gazpacho freddo nelle ciotole e completare con l''uovo, il jamón e i crostini."]}}'::jsonb),
  ('5ad1bda9-8aca-4746-92bc-c6ea865e640e'::uuid, '{"fr":{"title":"Cabillaud, pois chiches croustillants et épinards","steps":["Préchauffer le four à 220 °C. Mélanger les pois chiches bien séchés avec 2 c. à soupe d''huile, le paprika, le cumin et du sel sur une plaque recouverte de papier cuisson.","Rôtir les pois chiches 15 min en secouant la plaque une fois, jusqu''à ce qu''ils commencent à croustiller.","Les pousser sur un côté, ajouter le cabillaud assaisonné, l''arroser d''un filet d''huile et rôtir 10 à 12 min, jusqu''à ce que le poisson s''effeuille facilement et que les pois chiches soient croquants.","Pendant ce temps, faire revenir l''ail dans le reste d''huile dans une grande poêle à feu moyen 1 min, ajouter les épinards et remuer 2 à 3 min jusqu''à ce qu''ils tombent. Assaisonner et ajouter un filet de citron.","Servir le cabillaud sur les épinards, parsemer de pois chiches croustillants et accompagner de quartiers de citron."]},"it":{"title":"Merluzzo con ceci croccanti e spinaci","steps":["Scaldare il forno a 220 °C. Condire i ceci ben asciugati con 2 cucchiai d''olio, la paprika, il cumino e il sale su una teglia rivestita di carta forno.","Arrostire i ceci 15 min, scuotendo la teglia una volta, finché iniziano a diventare croccanti.","Spostarli da un lato, aggiungere il merluzzo condito, irrorarlo con un filo d''olio e arrostire 10-12 min, finché il pesce si sfalda facilmente e i ceci sono croccanti.","Nel frattempo, soffriggere l''aglio nell''olio rimasto in una padella grande a fuoco medio per 1 min, aggiungere gli spinaci e mescolare 2-3 min finché appassiscono. Regolare di sale e aggiungere una spruzzata di limone.","Servire il merluzzo sugli spinaci, cospargere con i ceci croccanti e accompagnare con spicchi di limone."]}}'::jsonb),
  ('4c174849-6e53-4371-be0e-fa0e67e4d60f'::uuid, '{"fr":{"title":"Riz aux crevettes à l''espagnole","steps":["Chauffer le fumet avec le safran dans une petite casserole et le garder chaud.","Chauffer l''huile dans une grande poêle ou une poêle à paella à feu vif, saisir les crevettes 1 min et les réserver.","Baisser à feu moyen, cuire l''oignon et l''ail 5 min, puis ajouter le poivron et le laurier et cuire 8 min jusqu''à ce qu''ils soient tendres.","Ajouter la tomate râpée et cuire 6 à 8 min jusqu''à ce qu''elle fonce et que la poêle soit presque sèche.","Incorporer le paprika quelques secondes, puis le riz 1 min pour bien l''enrober du sofrito.","Verser le fumet chaud, saler, répartir le riz uniformément et laisser frémir à feu moyen 10 min sans remuer.","Baisser le feu et cuire encore 7 à 8 min ; déposer les crevettes dessus les 3 dernières minutes, jusqu''à ce que le riz soit tendre et le fumet absorbé.","Retirer du feu, couvrir d''un torchon propre et laisser reposer 5 min. Servir avec le persil et le citron."]},"it":{"title":"Riso con gamberi alla spagnola","steps":["Scaldare il fumetto con lo zafferano in un pentolino e tenerlo caldo.","Scaldare l''olio in una padella larga o una paellera a fuoco vivo, scottare i gamberi 1 min e tenerli da parte.","Abbassare a fuoco medio, cuocere la cipolla e l''aglio 5 min, poi aggiungere il peperone e l''alloro e cuocere 8 min finché sono morbidi.","Aggiungere il pomodoro grattugiato e cuocere 6-8 min finché scurisce e la padella è quasi asciutta.","Unire la paprika per pochi secondi, poi il riso per 1 min per insaporirlo nel soffritto.","Versare il fumetto caldo, salare, distribuire il riso in modo uniforme e cuocere a fuoco medio 10 min senza mescolare.","Abbassare la fiamma e cuocere altri 7-8 min; adagiare i gamberi sopra negli ultimi 3 min, finché il riso è tenero e il fumetto assorbito.","Togliere dal fuoco, coprire con un canovaccio pulito e lasciare riposare 5 min. Servire con prezzemolo e limone."]}}'::jsonb),
  ('a5894a47-22ee-42d7-9927-2b4caead1eef'::uuid, '{"fr":{"title":"Riz au poulet et chorizo","steps":["Assaisonner le poulet et le faire dorer dans l''huile dans une sauteuse profonde à feu moyen-vif 5 à 6 min. Réserver.","Ajouter le chorizo et cuire 2 min jusqu''à ce qu''il rende son huile rouge.","Ajouter l''oignon et le poivron et cuire à feu moyen 8 min jusqu''à ce qu''ils soient tendres.","Incorporer l''ail, le paprika et la tomate râpée et cuire 4 min jusqu''à ce que ce soit épais.","Ajouter le riz et remuer 1 min pour bien l''enrober.","Verser le bouillon, émietter le safran, ajouter le laurier et le poulet, assaisonner et porter à ébullition.","Couvrir et laisser mijoter à feu doux 18 min ; parsemer les petits pois les 5 dernières minutes, jusqu''à ce que le riz soit tendre et encore un peu moelleux.","Laisser reposer 5 min hors du feu, puis servir avec le persil."]},"it":{"title":"Riso con pollo e chorizo","steps":["Condire il pollo e rosolarlo nell''olio in una padella larga e profonda a fuoco medio-alto per 5-6 min. Tenerlo da parte.","Aggiungere il chorizo e cuocere 2 min finché rilascia il suo olio rosso.","Aggiungere la cipolla e il peperone e cuocere a fuoco medio 8 min finché sono morbidi.","Unire l''aglio, la paprika e il pomodoro grattugiato e cuocere 4 min finché si addensa.","Aggiungere il riso e mescolare 1 min per insaporirlo.","Versare il brodo, sbriciolare lo zafferano, aggiungere l''alloro e il pollo, regolare di sale e pepe e portare a bollore.","Coprire e cuocere a fuoco basso 18 min; aggiungere i piselli negli ultimi 5 min, finché il riso è tenero e ancora un po'' umido.","Lasciare riposare 5 min fuori dal fuoco, poi servire con il prezzemolo."]}}'::jsonb),
  ('b44c86ec-e86c-4a74-94e1-d8ec335c05f4'::uuid, '{"fr":{"title":"Poulet à l''ail à l''espagnole","steps":["Préchauffer le four à 220 °C. Mélanger les dés de pomme de terre avec 1 c. à soupe d''huile et du sel sur une plaque et rôtir 30 à 35 min en les retournant une fois, jusqu''à ce qu''ils soient dorés (à la place des frites traditionnelles).","Faire revenir les gousses d''ail dans le reste d''huile dans une grande poêle à feu moyen 3 à 4 min jusqu''à ce que la peau soit grillée. Les retirer.","Assaisonner le poulet, le fariner légèrement et le faire dorer dans l''huile à l''ail à feu vif 8 min en le retournant, jusqu''à ce qu''il soit doré de tous côtés.","Retirer l''excès d''huile, presser le citron dessus et remettre l''ail. Ajouter le xérès et le laurier et laisser bouillonner 2 min.","Ajouter le bouillon et laisser frémir vivement 10 à 12 min en retournant le poulet, jusqu''à ce qu''il soit cuit à cœur et que la sauce ait réduit et le nappe.","Gratter le fond de la poêle, parsemer de persil et servir avec les pommes de terre."]},"it":{"title":"Pollo all''aglio alla spagnola","steps":["Scaldare il forno a 220 °C. Condire i cubetti di patate con 1 cucchiaio d''olio e il sale su una teglia e arrostire 30-35 min, girandoli una volta, finché sono dorati (al posto delle patate fritte tradizionali).","Soffriggere gli spicchi d''aglio nell''olio rimasto in una padella grande a fuoco medio per 3-4 min finché la buccia è tostata. Toglierli.","Condire il pollo, infarinarlo leggermente e rosolarlo nell''olio all''aglio a fuoco vivo per 8 min, girandolo, finché è dorato da tutti i lati.","Eliminare l''olio in eccesso, spremere sopra il limone e rimettere l''aglio. Aggiungere lo sherry e l''alloro e lasciar sobbollire 2 min.","Aggiungere il brodo e cuocere a fuoco vivace 10-12 min, girando il pollo, finché è cotto all''interno e il sugo si è ridotto e lo vela.","Raschiare il fondo della padella, completare con il prezzemolo e servire con le patate."]}}'::jsonb),
  ('a914da25-8a4d-40fd-b3ae-1857d48c52a8'::uuid, '{"fr":{"title":"Lentilles au chorizo à l''espagnole","steps":["Rincer les lentilles.","Faire revenir l''oignon, le poivron et la carotte dans l''huile dans une grande cocotte à feu moyen 8 min.","Ajouter l''ail, le paprika et la tomate râpée et cuire 3 min.","Ajouter les lentilles, la pomme de terre, le laurier, 900 ml d''eau et un peu de sel. Porter à ébullition, puis couvrir et laisser mijoter doucement 40 min en remuant de temps en temps.","Ajouter le chorizo et laisser mijoter à découvert encore 15 min, jusqu''à ce que les lentilles soient tendres et le bouillon épais et rouge. Ajouter un peu d''eau si c''est trop sec.","Rectifier le sel et laisser reposer 5 min avant de servir."]},"it":{"title":"Lenticchie con chorizo alla spagnola","steps":["Sciacquare le lenticchie.","Far appassire la cipolla, il peperone e la carota nell''olio in una pentola grande a fuoco medio per 8 min.","Aggiungere l''aglio, la paprika e il pomodoro grattugiato e cuocere 3 min.","Aggiungere le lenticchie, la patata, l''alloro, 900 ml d''acqua e un po'' di sale. Portare a bollore, poi coprire e cuocere a fuoco dolce 40 min, mescolando ogni tanto.","Aggiungere il chorizo e cuocere scoperto altri 15 min, finché le lenticchie sono tenere e il brodo è denso e rosso. Aggiungere un goccio d''acqua se si asciuga troppo.","Regolare di sale e lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('6fa70574-b4d3-46d1-83db-4e22739a81cf'::uuid, '{"fr":{"title":"Bacalhau à Brás (morue aux œufs et pommes paille)","steps":["Dessaler la morue dans beaucoup d''eau froide au réfrigérateur 24 à 36 h, en changeant l''eau toutes les 6 à 8 h.","Préchauffer le four à 220 °C. Rincer et bien sécher les allumettes de pomme de terre, les mélanger avec 1,5 c. à soupe d''huile et une pincée de sel et les étaler sur une plaque recouverte de papier cuisson.","Cuire 20 à 25 min en les retournant deux fois, jusqu''à ce qu''elles soient dorées et croustillantes (à la place des pommes paille frites traditionnelles).","Pendant ce temps, retirer la peau et les arêtes de la morue et l''effilocher finement à la main.","Faire revenir l''oignon et l''ail dans le reste d''huile dans une grande poêle à feu moyen-doux 10 min jusqu''à ce qu''ils soient tendres et dorés.","Ajouter la morue et cuire 3 à 4 min en remuant, jusqu''à ce qu''elle absorbe l''huile. Incorporer les pommes de terre.","Battre les œufs avec du poivre, les verser à feu doux et remuer 1 à 2 min ; retirer du feu tant que c''est encore crémeux, avant qu''ils ne prennent.","Servir aussitôt, garni de persil et d''olives noires."]},"it":{"title":"Bacalhau à Brás (baccalà con uova e patate)","steps":["Dissalare il baccalà in abbondante acqua fredda in frigorifero per 24-36 ore, cambiando l''acqua ogni 6-8 ore.","Scaldare il forno a 220 °C. Sciacquare e asciugare bene i fiammiferi di patate, condirli con 1,5 cucchiai d''olio e un pizzico di sale e stenderli su una teglia rivestita di carta forno.","Cuocere 20-25 min, girandoli due volte, finché sono dorati e croccanti (al posto delle patate a fiammifero fritte tradizionali).","Nel frattempo, togliere la pelle e le spine dal baccalà e sfilacciarlo finemente con le mani.","Cuocere la cipolla e l''aglio nell''olio rimasto in una padella grande a fuoco medio-basso per 10 min finché sono morbidi e dorati.","Aggiungere il baccalà e cuocere 3-4 min, mescolando, finché assorbe l''olio. Unire le patate.","Sbattere le uova con il pepe, versarle a fuoco basso e mescolare 1-2 min; togliere dal fuoco quando sono ancora cremose, prima che si rapprendano.","Servire subito con prezzemolo e olive nere."]}}'::jsonb),
  ('a6c31957-1d9a-4114-b952-8037f62d3528'::uuid, '{"fr":{"title":"Pisto manchego aux œufs","steps":["Couper les tomates en deux et les râper sur une râpe, en jetant la peau.","Faire revenir l''oignon et l''ail dans 3 c. à soupe d''huile dans une sauteuse à feu doux 12 min jusqu''à ce qu''ils soient tendres.","Ajouter les poivrons et cuire encore 15 min en remuant de temps en temps, jusqu''à ce qu''ils soient très tendres.","Ajouter la courgette et cuire 8 min.","Incorporer la tomate râpée, le sucre, du sel et du poivre et cuire à feu moyen-doux 20 à 25 min à découvert, jusqu''à ce que ce soit épais, confit et sans eau.","Creuser 4 puits dans le pisto, casser un œuf dans chacun, couvrir et cuire à feu doux 5 à 6 min jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer de jambon et servir dans la sauteuse avec du pain."]},"it":{"title":"Pisto manchego con uova","steps":["Tagliare i pomodori a metà e grattugiarli con una grattugia, eliminando la buccia.","Cuocere la cipolla e l''aglio in 3 cucchiai d''olio in una padella larga a fuoco basso per 12 min finché sono morbidi.","Aggiungere i peperoni e cuocere altri 15 min, mescolando ogni tanto, finché sono molto teneri.","Aggiungere la zucchina e cuocere 8 min.","Unire il pomodoro grattugiato, lo zucchero, sale e pepe e cuocere a fuoco medio-basso 20-25 min, scoperto, finché è denso, morbido e senza acqua.","Fare 4 conche nel pisto, rompere un uovo in ciascuna, coprire e cuocere a fuoco basso 5-6 min finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere con il jamón e servire nella padella con il pane."]}}'::jsonb),
  ('65b65923-4205-4160-98a0-f2a6c4e1c9d7'::uuid, '{"fr":{"title":"Moules à la marinera (à l''espagnole)","steps":["Gratter les moules et retirer les barbes ; jeter celles qui sont cassées ou restent ouvertes quand on les tapote.","Les mettre dans une grande cocotte avec les feuilles de laurier et 100 ml d''eau, couvrir et cuire à feu vif 3 à 4 min en secouant la cocotte, jusqu''à ce qu''elles s''ouvrent. Jeter celles qui restent fermées.","Retirer les moules, filtrer le jus de cuisson dans une passoire fine et en garder 200 ml.","Dans la cocotte essuyée, faire revenir l''oignon et l''ail dans l''huile à feu moyen 8 min jusqu''à ce qu''ils soient dorés.","Incorporer la farine 1 min, puis retirer du feu et ajouter le paprika et le piment.","Verser le vin et le jus des moules réservé et laisser mijoter 5 min en remuant, jusqu''à ce que la sauce épaississe légèrement.","Remettre les moules, ajouter presque tout le persil et mélanger 1 à 2 min jusqu''à ce qu''elles soient chaudes et nappées. Servir avec le reste du persil et du pain pour la sauce."]},"it":{"title":"Cozze alla marinera spagnola","steps":["Raschiare le cozze ed eliminare il bisso; scartare quelle rotte o che restano aperte se battute.","Metterle in una pentola grande con le foglie di alloro e 100 ml d''acqua, coprire e cuocere a fuoco vivo 3-4 min, scuotendo la pentola, finché si aprono. Scartare quelle rimaste chiuse.","Togliere le cozze, filtrare il liquido di cottura con un colino fine e tenerne 200 ml.","Nella pentola asciugata, cuocere la cipolla e l''aglio nell''olio a fuoco medio per 8 min finché sono dorati.","Unire la farina e mescolare 1 min, poi togliere dal fuoco e aggiungere la paprika e il peperoncino.","Versare il vino e il liquido delle cozze tenuto da parte e cuocere a fuoco lento 5 min, mescolando, finché si addensa leggermente.","Rimettere le cozze, aggiungere quasi tutto il prezzemolo e saltare 1-2 min finché sono calde e ben condite. Servire con il prezzemolo rimasto e pane per il sugo."]}}'::jsonb),
  ('b3a53206-d2e6-46c6-8914-d174f6f6000d'::uuid, '{"fr":{"title":"Falafels au four en pain pita","steps":["Faire tremper les pois chiches secs une nuit dans beaucoup d''eau froide (pas de pois chiches en boîte, le mélange serait trop humide), puis les égoutter et bien les sécher.","Mixer les pois chiches par à-coups au robot avec l''oignon, 1 gousse d''ail, le persil, le cumin, la coriandre, le paprika, la farine, 1 c. à soupe d''huile et 1 c. à café de sel, jusqu''à ce qu''ils soient finement hachés et se tiennent quand on les presse.","Réfrigérer le mélange au moins 1 h.","Préchauffer le four à 200 °C et huiler une plaque avec 1 c. à soupe d''huile.","Former des galettes de la taille d''une noix, les poser sur la plaque et badigeonner le dessus du reste d''huile.","Cuire 25 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient dorées et croustillantes.","Pendant ce temps, mélanger le yaourt avec le tahini, le jus de citron, le reste de l''ail râpé et une pincée de sel.","Réchauffer les pains pita, les couper en deux, ouvrir les poches et les garnir de salade, de tomate, de concombre, de falafels et de beaucoup de sauce yaourt-tahini."]},"it":{"title":"Falafel al forno nella pita","steps":["Mettere in ammollo i ceci secchi per una notte in abbondante acqua fredda (non usare ceci in scatola, il composto sarebbe troppo umido), poi scolarli e asciugarli bene.","Tritare i ceci a impulsi nel mixer con la cipolla, 1 spicchio d''aglio, il prezzemolo, il cumino, il coriandolo, la paprika, la farina, 1 cucchiaio d''olio e 1 cucchiaino di sale, finché sono tritati finemente e restano compatti se pressati.","Far riposare il composto in frigorifero almeno 1 ora.","Scaldare il forno a 200 °C e ungere una teglia con 1 cucchiaio d''olio.","Formare delle polpettine della grandezza di una noce, disporle sulla teglia e spennellarle sopra con l''olio rimasto.","Cuocere 25 min, girandole a metà cottura, finché sono dorate e croccanti fuori.","Nel frattempo, mescolare lo yogurt con la tahina, il succo di limone, l''aglio rimasto grattugiato e un pizzico di sale.","Scaldare le pite, tagliarle a metà, aprire le tasche e farcirle con lattuga, pomodoro, cetriolo, i falafel e abbondante salsa di yogurt e tahina."]}}'::jsonb),
  ('e7f345b6-ff62-406f-9461-f8f36fd5b1b1'::uuid, '{"fr":{"title":"Assiette de kefta de dinde et pain pita","steps":["Mélanger à la main la dinde, l''oignon, le persil, presque toute la menthe, le paprika, le cumin, la cannelle, le piment de la Jamaïque, la chapelure, 0,5 c. à café de sel et du poivre jusqu''à ce que ce soit homogène.","Former 6 keftas ovales, autour de brochettes si on en a, et les réfrigérer 10 min pendant la préparation du reste.","Mélanger le yaourt avec le zeste et le jus de citron, l''ail, le reste de la menthe et une pincée de sel.","Mélanger les tomates, le concombre et l''oignon rouge avec un peu de sel.","Chauffer une poêle-gril ou une poêle à feu moyen-vif, badigeonner les keftas d''huile et les cuire 10 à 12 min en les retournant toutes les quelques minutes, jusqu''à ce qu''elles soient dorées et cuites à cœur (74 °C au centre).","Réchauffer les pains pita dans la poêle 30 s de chaque côté et les couper en lanières.","Disposer les keftas, le pain pita, la salade et le yaourt à l''ail sur un plat et servir."]},"it":{"title":"Piatto di kofta di tacchino con pita","steps":["Impastare con le mani il tacchino, la cipolla, il prezzemolo, quasi tutta la menta, la paprika, il cumino, la cannella, il pimento, il pangrattato, mezzo cucchiaino di sale e il pepe finché è ben amalgamato.","Formare 6 kofta ovali, attorno a degli spiedini se si hanno, e metterle in frigorifero 10 min mentre si prepara il resto.","Mescolare lo yogurt con la scorza e il succo di limone, l''aglio, la menta rimasta e un pizzico di sale.","Condire i pomodorini, il cetriolo e la cipolla rossa con un po'' di sale.","Scaldare una bistecchiera o una padella a fuoco medio-alto, spennellare le kofta con l''olio e cuocerle 10-12 min, girandole ogni pochi minuti, finché sono dorate e cotte all''interno (74 °C al centro).","Scaldare le pite nella padella 30 s per lato e tagliarle a strisce.","Disporre le kofta, la pita, l''insalata e lo yogurt all''aglio su un piatto da portata e servire."]}}'::jsonb),
  ('b75b8190-ec3f-49c7-86f1-ccd3ae433c1e'::uuid, '{"fr":{"title":"Pitas au souvlaki de porc","steps":["Mélanger le jus d''un demi-citron, l''ail écrasé, le vinaigre, le miel, 1 c. à café d''origan, le paprika, le cumin, 2 c. à soupe d''huile, du sel et du poivre. Y enrober le porc, couvrir et réfrigérer au moins 1 h (jusqu''à une nuit).","Râper la moitié du concombre, bien l''essorer et l''incorporer au yaourt avec la gousse d''ail restante, l''aneth, un filet de citron, du sel et un trait d''huile.","Couper le reste du concombre en dés et le mélanger avec la tomate, l''oignon rouge, le reste de l''origan, un peu d''huile et du sel.","Enfiler le porc sur 4 brochettes. Faire chauffer une poêle-gril à feu vif jusqu''à ce qu''elle fume.","Griller les brochettes 8 à 10 min en les tournant toutes les 2 min, jusqu''à ce qu''elles soient grillées dehors et juste cuites, à peine rosées au centre. Laisser reposer 3 min.","Réchauffer les pitas 30 s de chaque côté dans la poêle chaude.","Garnir chaque pita de tzatziki, de porc, de salade de tomates et d''un filet de citron ; replier et servir."]},"it":{"title":"Pita con souvlaki di maiale","steps":["Mescolare il succo di mezzo limone, l''aglio schiacciato, l''aceto, il miele, 1 cucchiaino di origano, la paprika, il cumino, 2 cucchiai d''olio, sale e pepe. Condire il maiale, coprire e lasciare in frigo almeno 1 h (fino a una notte).","Grattugiare metà del cetriolo, strizzarlo bene e unirlo allo yogurt con lo spicchio d''aglio rimasto, l''aneto, una spruzzata di limone, sale e un filo d''olio.","Tagliare a dadini il resto del cetriolo e condirlo con il pomodoro, la cipolla rossa, l''origano rimasto, un filo d''olio e sale.","Infilzare il maiale su 4 spiedini. Scaldare una bistecchiera a fuoco vivo finché fuma.","Grigliare gli spiedini 8-10 min, girandoli ogni 2 min, finché sono abbrustoliti fuori e appena cotti, solo leggermente rosati al centro. Lasciare riposare 3 min.","Scaldare le pita 30 s per lato nella bistecchiera calda.","Farcire ogni pita con tzatziki, maiale, insalata di pomodori e una spruzzata di limone; richiudere e servire."]}}'::jsonb),
  ('f8d5e8fc-4632-4270-9051-27105174a375'::uuid, '{"fr":{"title":"Gemista à la viande","steps":["Préchauffer le four à 180 °C. Couper le chapeau des poivrons et des tomates et les garder comme couvercles. Épépiner les poivrons ; évider les tomates dans un bol et hacher finement la chair en gardant le jus.","Saler l''intérieur des légumes, ajouter une pincée de sucre et les placer debout dans un plat à four.","Faire suer l''oignon dans 2 c. à soupe d''huile à feu moyen, 5 min. Ajouter le bœuf et le faire dorer 5 min en l''émiettant, puis incorporer l''ail.","Ajouter le riz et remuer 1 min, puis le concentré de tomate, la moitié de la chair de tomate hachée et 100 ml d''eau. Laisser mijoter 5 min jusqu''à ce que le riz soit à moitié cuit ; hors du feu, ajouter le persil, la menthe, du sel et du poivre.","Remplir les légumes aux trois quarts (le riz gonfle), répartir le reste de chair de tomate dessus et remettre les chapeaux.","Glisser les quartiers de pomme de terre entre les légumes, assaisonner, arroser le tout de 2 c. à soupe d''huile et verser 200 ml d''eau dans le plat.","Couvrir de papier aluminium et cuire 50 min, puis découvrir et cuire encore 25 à 30 min en arrosant une fois, jusqu''à ce que le riz soit tendre et le dessus bien coloré. Ajouter un peu d''eau si le plat se dessèche.","Laisser reposer 10 min et servir tiède avec la feta."]},"it":{"title":"Gemista con carne","steps":["Scaldare il forno a 180 °C. Tagliare la calotta di peperoni e pomodori e tenerla come coperchio. Svuotare i peperoni dai semi; scavare la polpa dei pomodori in una ciotola e tritarla finemente, tenendo il succo.","Salare l''interno degli ortaggi, aggiungere un pizzico di zucchero e sistemarli in piedi in una pirofila.","Appassire la cipolla in 2 cucchiai d''olio a fuoco medio, 5 min. Aggiungere il manzo e rosolarlo 5 min sgranandolo, poi unire l''aglio.","Aggiungere il riso e mescolare 1 min, poi il concentrato, metà della polpa di pomodoro e 100 ml d''acqua. Cuocere 5 min finché il riso è a metà cottura; fuori dal fuoco unire prezzemolo, menta, sale e pepe.","Riempire gli ortaggi per tre quarti (il riso si gonfia), distribuire sopra il resto della polpa di pomodoro e rimettere le calotte.","Sistemare gli spicchi di patata tra gli ortaggi, condire, irrorare tutto con 2 cucchiai d''olio e versare 200 ml d''acqua nella pirofila.","Coprire con alluminio e cuocere 50 min, poi scoprire e cuocere altri 25-30 min, bagnando una volta, finché il riso è tenero e la superficie abbrustolita. Aggiungere un goccio d''acqua se si asciuga troppo.","Lasciare riposare 10 min e servire tiepido con la feta."]}}'::jsonb),
  ('b635672f-00b1-4632-b8a6-4c0172b0cc29'::uuid, '{"fr":{"title":"Köfte de bœuf, boulgour à la tomate","steps":["Essorer l''oignon râpé, puis le pétrir avec le bœuf, l''ail, le persil, le cumin, le paprika, le piment, du sel et du poivre pendant 2 min jusqu''à ce que la farce colle.","Diviser en 6 et presser chaque portion autour d''une brochette en boudin de 12 cm. Réfrigérer pendant la préparation du boulgour.","Faire suer l''oignon haché dans le beurre et 1 c. à soupe d''huile à feu moyen, 5 min. Ajouter le concentré de tomate 1 min, puis la tomate râpée 2 min.","Ajouter le boulgour, le bouillon et une pincée de sel. Porter à ébullition, couvrir et cuire à feu très doux 12 min, jusqu''à absorption du liquide.","Retirer du feu, glisser un torchon propre sous le couvercle et laisser gonfler 10 min.","Pendant ce temps, badigeonner les köfte d''huile et les cuire dans une poêle-gril très chaude 8 à 10 min en les tournant toutes les 2 min, jusqu''à ce qu''elles soient dorées et cuites à cœur.","Égrener le boulgour et servir avec les köfte, le yaourt et des quartiers de citron."]},"it":{"title":"Kofta di manzo con bulgur al pomodoro","steps":["Strizzare la cipolla grattugiata, poi impastarla con il manzo, l''aglio, il prezzemolo, il cumino, la paprika, il peperoncino, sale e pepe per 2 min finché l''impasto è compatto.","Dividere in 6 e modellare ogni porzione attorno a uno spiedino in un salsicciotto di 12 cm. Mettere in frigo mentre si prepara il bulgur.","Appassire la cipolla tritata nel burro e 1 cucchiaio d''olio a fuoco medio, 5 min. Unire il concentrato per 1 min, poi il pomodoro grattugiato per 2 min.","Aggiungere il bulgur, il brodo e un pizzico di sale. Portare a bollore, coprire e cuocere a fuoco minimo 12 min, finché il liquido è assorbito.","Togliere dal fuoco, mettere un canovaccio pulito sotto il coperchio e lasciare riposare 10 min.","Nel frattempo spennellare le kofta d''olio e cuocerle in una bistecchiera rovente 8-10 min, girandole ogni 2 min, finché sono dorate e cotte all''interno.","Sgranare il bulgur e servire con le kofta, lo yogurt e spicchi di limone."]}}'::jsonb),
  ('f3ca2b5c-b4ad-4f57-869b-798303f6f839'::uuid, '{"fr":{"title":"Moussaka aux lentilles et aubergines","steps":["Préchauffer le four à 200 °C. Badigeonner les tranches d''aubergine et de pomme de terre de 3 c. à soupe d''huile, assaisonner et rôtir sur une plaque chemisée 25 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient tendres et dorées.","Pendant ce temps, faire suer l''oignon dans 1 c. à soupe d''huile dans une casserole, 6 min. Ajouter l''ail, l''origan et la cannelle 1 min.","Ajouter les lentilles rincées, le coulis, le concentré de tomate et 300 ml d''eau. Laisser mijoter à demi couvert 30 min, jusqu''à ce que les lentilles soient tendres et la sauce épaisse. Assaisonner et répartir dans un petit plat à four (environ 20 x 15 cm) en alternant avec les légumes : sauce, légumes, sauce, légumes.","Rincer la casserole. Faire fondre le beurre, ajouter la farine et remuer 1 min, puis incorporer le lait petit à petit au fouet et laisser épaissir 3 à 4 min en fouettant. Saler, poivrer et ajouter de la muscade.","Hors du feu, incorporer l''œuf et la moitié du parmesan au fouet.","Verser la béchamel sur les légumes, parsemer du reste de parmesan et cuire à 180 °C pendant 35 min, jusqu''à ce que le dessus soit doré et bouillonnant.","Laisser reposer 10 min avant de découper, pour que les couches se tiennent."]},"it":{"title":"Moussaka di lenticchie e melanzane","steps":["Scaldare il forno a 200 °C. Spennellare le fette di melanzana e di patata con 3 cucchiai d''olio, condire e arrostire su una teglia foderata 25 min, girandole a metà, finché sono morbide e dorate.","Nel frattempo appassire la cipolla in 1 cucchiaio d''olio in una casseruola, 6 min. Unire aglio, origano e cannella per 1 min.","Aggiungere le lenticchie sciacquate, la passata, il concentrato e 300 ml d''acqua. Cuocere semicoperto 30 min, finché le lenticchie sono tenere e il sugo denso. Regolare di sale e distribuire in una piccola pirofila (circa 20 x 15 cm) alternando con le verdure: sugo, verdure, sugo, verdure.","Sciacquare la casseruola. Sciogliere il burro, unire la farina e mescolare 1 min, poi aggiungere il latte poco alla volta con la frusta e cuocere 3-4 min mescolando, finché si addensa. Condire con sale, pepe e noce moscata.","Fuori dal fuoco, incorporare l''uovo e metà del parmigiano con la frusta.","Versare la besciamella sulle verdure, cospargere con il resto del parmigiano e cuocere a 180 °C per 35 min, finché è dorata e sobbolle.","Lasciare riposare 10 min prima di tagliare, così gli strati restano compatti."]}}'::jsonb),
  ('a72b6524-b539-48e5-9e9c-77744a5cb4dc'::uuid, '{"fr":{"title":"Gigantes plaki (haricots géants à la tomate)","steps":["Préchauffer le four à 180 °C.","Dans une cocotte allant sur le feu et au four, faire revenir doucement l''oignon, la carotte et le céleri dans 4 c. à soupe d''huile avec une pincée de sel 8 à 10 min, jusqu''à ce qu''ils soient tendres sans colorer.","Ajouter l''ail et le piment 30 s, puis le concentré de tomate 1 min.","Ajouter les tomates concassées, le bouillon, le laurier, le sucre et la moitié de l''aneth. Porter à frémissement, assaisonner, puis incorporer les haricots.","Enfourner à découvert 45 min en remuant une fois, jusqu''à ce que la sauce soit épaisse et confite et que le dessus commence à colorer. Ajouter un peu d''eau si cela sèche trop vite.","Retirer le laurier, ajouter le reste de l''aneth et laisser reposer 10 min (c''est meilleur tiède que brûlant).","Servir avec la feta émiettée, un filet d''huile, le persil et le pain."]},"it":{"title":"Gigantes plaki (fagioloni al pomodoro)","steps":["Scaldare il forno a 180 °C.","In una casseruola adatta anche al forno, cuocere dolcemente cipolla, carota e sedano in 4 cucchiai d''olio con un pizzico di sale per 8-10 min, finché sono morbidi ma non coloriti.","Aggiungere l''aglio e il peperoncino per 30 s, poi il concentrato per 1 min.","Unire i pomodori pelati, il brodo, l''alloro, lo zucchero e metà dell''aneto. Portare a sobbollire, regolare di sale, poi incorporare i fagioli.","Cuocere in forno scoperto 45 min, mescolando una volta, finché il sugo è denso e la superficie comincia a colorirsi. Aggiungere un goccio d''acqua se asciuga troppo in fretta.","Togliere l''alloro, unire il resto dell''aneto e lasciare riposare 10 min (è più buono tiepido che bollente).","Servire con la feta sbriciolata, un filo d''olio, il prezzemolo e il pane."]}}'::jsonb),
  ('d03d756a-f782-4067-8ef2-a6c2887809d7'::uuid, '{"fr":{"title":"Arni me melitzanes (agneau aux aubergines)","steps":["Préchauffer le four à 180 °C. Saler et poivrer l''agneau.","Dans une cocotte allant au four, dorer les tranches d''aubergine dans 2 c. à soupe d''huile à feu moyen-vif, 2 à 3 min par face, en ajoutant un peu d''huile seulement si la cocotte est sèche. Réserver.","Dorer l''agneau dans 1 c. à soupe d''huile dans la même cocotte, 6 à 8 min en le retournant, jusqu''à ce qu''il soit coloré de partout. Verser le vin et laisser bouillonner 1 min.","Pousser l''agneau sur le côté et faire suer l''oignon et le céleri 5 min, puis ajouter l''ail, l''origan, le paprika et le cumin 1 min.","Ajouter les tomates, 100 ml d''eau et le romarin, assaisonner et porter à frémissement. Disposer l''aubergine par-dessus.","Couvrir et cuire au four 1 h 45, jusqu''à ce que l''agneau soit très tendre. Découvrir, mélanger pour que de l''agneau se retrouve sur le dessus et cuire encore 15 min pour colorer.","Pendant ce temps, environ 20 min avant la fin, cuire le riz : le laisser mijoter à couvert dans 200 ml d''eau salée 12 min, puis reposer 5 min.","Servir le ragoût sur le riz avec une cuillerée de yaourt."]},"it":{"title":"Arni me melitzanes (agnello con melanzane)","steps":["Scaldare il forno a 180 °C. Salare e pepare l''agnello.","In una casseruola adatta al forno, rosolare le fette di melanzana in 2 cucchiai d''olio a fuoco medio-alto, 2-3 min per lato, aggiungendo olio solo se la pentola è asciutta. Mettere da parte.","Rosolare l''agnello in 1 cucchiaio d''olio nella stessa casseruola, 6-8 min, girandolo, finché è colorito ovunque. Versare il vino e lasciarlo sfumare 1 min.","Spostare l''agnello di lato e appassire cipolla e sedano 5 min, poi aggiungere aglio, origano, paprika e cumino per 1 min.","Unire i pomodori, 100 ml d''acqua e il rosmarino, regolare di sale e portare a sobbollire. Adagiare sopra le melanzane.","Coprire e cuocere in forno 1 h 45 min, finché l''agnello è molto tenero. Scoprire, mescolare in modo che un po'' di agnello resti in superficie e cuocere altri 15 min per colorire.","Nel frattempo, circa 20 min prima della fine, cuocere il riso: sobbollire coperto in 200 ml d''acqua salata 12 min, poi riposare 5 min.","Servire lo spezzatino sul riso con un cucchiaio di yogurt."]}}'::jsonb),
  ('d79d51a5-0384-4a66-b807-ef9f7af3a3ef'::uuid, '{"fr":{"title":"Mercimek çorbası (soupe turque aux lentilles)","steps":["Faire suer l''oignon dans 2 c. à soupe d''huile avec une pincée de sel à feu moyen-doux, 6 à 8 min.","Ajouter l''ail, le cumin et le concentré de tomate et faire revenir 3 min en remuant, jusqu''à ce que le concentré fonce.","Ajouter les lentilles, la carotte, la pomme de terre et le bouillon. Porter à ébullition, écumer, puis couvrir et laisser mijoter doucement 20 à 25 min, jusqu''à ce que tout soit très tendre.","Mixer au mixeur plongeant jusqu''à obtenir un velouté lisse ; détendre avec un peu d''eau chaude si c''est trop épais, saler et poivrer.","Dans une petite poêle, faire fondre le beurre avec 1 c. à soupe d''huile, ajouter le paprika et le piment et remuer 1 min à feu doux, jusqu''à ce que le gras devienne rouge.","Servir la soupe dans des bols, arroser de beurre rouge, parsemer de persil et servir avec du citron à presser et le pain."]},"it":{"title":"Mercimek çorbası (zuppa turca di lenticchie)","steps":["Appassire la cipolla in 2 cucchiai d''olio con un pizzico di sale a fuoco medio-basso, 6-8 min.","Aggiungere aglio, cumino e concentrato e soffriggere 3 min mescolando, finché il concentrato si scurisce.","Unire le lenticchie, la carota, la patata e il brodo. Portare a bollore, schiumare, poi coprire e cuocere dolcemente 20-25 min, finché tutto è molto morbido.","Frullare con il frullatore a immersione fino a ottenere una crema liscia; allungare con poca acqua calda se è troppo densa e regolare di sale e pepe.","In un pentolino sciogliere il burro con 1 cucchiaio d''olio, aggiungere paprika e peperoncino e mescolare 1 min a fuoco basso finché il grasso diventa rosso.","Versare la zuppa nelle ciotole, irrorare con il burro rosso, cospargere di prezzemolo e servire con limone da spremere e il pane."]}}'::jsonb),
  ('10663b06-3c7d-4f2f-a1f9-e2aded01352b'::uuid, '{"fr":{"title":"Sabich","steps":["Préchauffer le four à 220 °C. Badigeonner généreusement d''huile les deux faces des tranches d''aubergine, assaisonner et rôtir sur une plaque chemisée 25 min en retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et fondantes.","Pendant ce temps, plonger les œufs dans l''eau frémissante et les cuire 9 min, puis les refroidir sous l''eau froide, les écaler et les trancher.","Fouetter le tahini avec 1 gousse d''ail écrasée, le jus d''un demi-citron, une pincée de sel et 3 à 4 c. à soupe d''eau froide jusqu''à ce que la sauce soit lisse et coulante.","Écraser grossièrement les pois chiches à la fourchette avec l''autre gousse d''ail, le cumin, 1 c. à soupe d''huile, un filet de citron et du sel.","Mélanger la tomate, le concombre, l''oignon et la moitié du persil avec un filet de citron, un trait d''huile et du sel.","Réchauffer les pitas 2 min au four, puis les ouvrir en poche.","Tartiner l''intérieur de pois chiches, puis superposer aubergine, œuf et salade en arrosant de tahini entre les couches. Finir avec du tahini, du persil et de la sauce piquante, et manger aussitôt."]},"it":{"title":"Sabich","steps":["Scaldare il forno a 220 °C. Spennellare abbondantemente d''olio le fette di melanzana su entrambi i lati, condire e arrostire su una teglia foderata 25 min, girandole a metà, finché sono ben dorate e cremose.","Nel frattempo calare le uova in acqua che sobbolle e cuocerle 9 min, poi raffreddarle sotto l''acqua fredda, sgusciarle e affettarle.","Sbattere la tahina con 1 spicchio d''aglio schiacciato, il succo di mezzo limone, un pizzico di sale e 3-4 cucchiai d''acqua fredda fino a ottenere una salsa liscia e fluida.","Schiacciare grossolanamente i ceci con una forchetta insieme all''altro spicchio d''aglio, al cumino, a 1 cucchiaio d''olio, a una spruzzata di limone e al sale.","Mescolare pomodoro, cetriolo, cipolla e metà del prezzemolo con una spruzzata di limone, un filo d''olio e sale.","Scaldare le pita in forno 2 min, poi aprirle a tasca.","Spalmare i ceci all''interno, poi alternare melanzana, uovo e insalata, versando la tahina tra gli strati. Finire con tahina, prezzemolo e salsa piccante e mangiare subito."]}}'::jsonb),
  ('7ff53ecb-a890-45d5-b340-46719ce3ae64'::uuid, '{"fr":{"title":"Plateau shawarma de chou-fleur et pois chiches","steps":["Préchauffer le four à 220 °C et chemiser une grande plaque.","Fouetter 3 c. à soupe d''huile avec le jus d''un demi-citron, 2 gousses d''ail, le cumin, la coriandre moulue, le paprika, le curcuma, la cannelle, le piment en poudre et 1 c. à café de sel.","Enrober le chou-fleur, les pois chiches et l''oignon de cette huile épicée et les étaler en une seule couche sur la plaque.","Rôtir 30 min en secouant la plaque à mi-cuisson, jusqu''à ce que le chou-fleur soit tendre et grillé sur les bords et les pois chiches croustillants. Réchauffer les pitas sur la grille du four les 2 dernières minutes.","Pendant ce temps, fouetter le tahini, le yaourt, le miel, le reste de l''ail, le zeste et le jus de l''autre moitié de citron, une pincée de sel et assez d''eau pour obtenir une sauce coulante.","Disposer les légumes sur un plat, arroser de sauce au tahini et parsemer de persil. Servir avec les pitas déchirées et des cornichons."]},"it":{"title":"Piatto shawarma di cavolfiore e ceci","steps":["Scaldare il forno a 220 °C e foderare una teglia grande.","Sbattere 3 cucchiai d''olio con il succo di mezzo limone, 2 spicchi d''aglio, il cumino, il coriandolo in polvere, la paprika, la curcuma, la cannella, il peperoncino in polvere e 1 cucchiaino di sale.","Condire il cavolfiore, i ceci e la cipolla con l''olio speziato e distribuirli in un solo strato sulla teglia.","Arrostire 30 min, scuotendo la teglia a metà, finché il cavolfiore è tenero e abbrustolito ai bordi e i ceci croccanti. Scaldare le pita sulla griglia del forno negli ultimi 2 min.","Nel frattempo sbattere tahina, yogurt, miele, l''aglio rimasto, la scorza e il succo dell''altra metà del limone, un pizzico di sale e acqua quanto basta per una salsa fluida.","Disporre le verdure su un piatto da portata, irrorare con la salsa alla tahina e cospargere di prezzemolo. Servire con le pita spezzettate e i cetriolini."]}}'::jsonb),
  ('92e6216c-d5d6-4d6c-9483-31a0b88ceac4'::uuid, '{"fr":{"title":"Salade de semoule au halloumi et aux pêches","steps":["Mettre la semoule dans un bol avec 1 c. à café d''huile et une pincée de sel, verser le bouillon bouillant, couvrir et laisser gonfler 5 min.","Fouetter 2 c. à soupe d''huile, le jus du citron, le miel, la moutarde, le piment, du sel et du poivre.","Égrener la semoule à la fourchette et la mélanger avec la moitié de la vinaigrette et l''oignon rouge ; laisser tiédir.","Faire chauffer une poêle-gril ou une poêle antiadhésive à feu moyen-vif. Badigeonner les quartiers de pêche d''un peu d''huile et les cuire 1 à 2 min par face, jusqu''à ce qu''ils soient marqués. Réserver.","Sécher le halloumi et le cuire dans la même poêle 2 min par face, jusqu''à ce qu''il soit doré.","Mélanger la semoule avec la roquette et la menthe, garnir des pêches et du halloumi chaud, arroser du reste de vinaigrette et parsemer de pistaches."]},"it":{"title":"Insalata di cous cous con halloumi e pesche","steps":["Mettere il cous cous in una ciotola con 1 cucchiaino d''olio e un pizzico di sale, versare il brodo bollente, coprire e lasciare riposare 5 min.","Sbattere 2 cucchiai d''olio, il succo del limone, il miele, la senape, il peperoncino, sale e pepe.","Sgranare il cous cous con una forchetta e condirlo con metà del condimento e la cipolla rossa; lasciare intiepidire.","Scaldare una bistecchiera o una padella antiaderente a fuoco medio-alto. Spennellare gli spicchi di pesca con poco olio e cuocerli 1-2 min per lato finché sono segnati. Mettere da parte.","Asciugare l''halloumi e cuocerlo nella stessa padella 2 min per lato, finché è dorato.","Mescolare il cous cous con la rucola e la menta, completare con le pesche e l''halloumi caldo, condire con il resto del condimento e cospargere di pistacchi."]}}'::jsonb),
  ('69d6a6a6-0d99-43e5-b62f-57968b7e02c9'::uuid, '{"fr":{"title":"Burgers d''agneau à la feta, salade de tomates","steps":["Presser la tomate râpée dans la main pour l''égoutter, puis la mélanger à l''agneau avec l''ail, la moitié de l''origan, la menthe, le persil, du sel et du poivre. Former 2 steaks de 2 cm d''épaisseur et réfrigérer 15 min.","Écraser la feta dans le yaourt avec un peu de poivre pour obtenir une sauce épaisse.","Mélanger les quartiers de tomate, le concombre, l''oignon rouge et les olives avec le vinaigre, 1 c. à soupe d''huile, le reste de l''origan et du sel.","Faire chauffer une poêle-gril à feu moyen-vif et cuire les burgers 4 à 5 min par face, jusqu''à ce qu''ils soient bien dorés et cuits à cœur. Laisser reposer 2 min.","Toaster la face coupée des pains dans la poêle, 1 min.","Tartiner les pains de sauce à la feta, ajouter les steaks et servir la salade de tomates à côté."]},"it":{"title":"Burger di agnello con feta e insalata di pomodori","steps":["Strizzare con la mano il pomodoro grattugiato per scolarlo, poi unirlo all''agnello con l''aglio, metà dell''origano, la menta, il prezzemolo, sale e pepe. Formare 2 hamburger spessi 2 cm e metterli in frigo 15 min.","Schiacciare la feta nello yogurt con un po'' di pepe per ottenere una salsa densa.","Condire gli spicchi di pomodoro, il cetriolo, la cipolla rossa e le olive con l''aceto, 1 cucchiaio d''olio, l''origano rimasto e sale.","Scaldare una bistecchiera a fuoco medio-alto e cuocere gli hamburger 4-5 min per lato, finché sono ben rosolati e cotti all''interno. Lasciare riposare 2 min.","Tostare il lato tagliato dei panini nella bistecchiera, 1 min.","Spalmare i panini con la salsa alla feta, aggiungere gli hamburger e servire l''insalata di pomodori a parte."]}}'::jsonb),
  ('a8b8e77d-d4d8-4caa-9ef0-913a096603a2'::uuid, '{"fr":{"title":"Kleftiko d''agneau","steps":["Mélanger le jus du citron, le vin, 3 c. à soupe d''huile, 1 gousse d''ail hachée, l''origan, 1 c. à café de sel et du poivre. En frotter l''agneau, couvrir et réfrigérer 2 h (ou une nuit). Le sortir 30 min avant la cuisson.","Préchauffer le four à 160 °C. Poser deux longues feuilles de papier cuisson en croix dans un plat à rôtir.","Entasser au centre les pommes de terre, l''oignon, le poivron et les tomates, assaisonner, puis poser l''agneau dessus avec sa marinade, les gousses d''ail restantes coupées en deux et le romarin.","Rabattre le papier sur le tout et le plier ou le ficeler pour former une papillote bien fermée ; couvrir aussi le plat de papier aluminium.","Cuire 2 h 30, jusqu''à ce que l''agneau s''effiloche à la fourchette. S''il résiste, refermer et cuire encore 20 min.","Réserver l''agneau sur une assiette, couvert. Monter le four à 200 °C, ouvrir la papillote, parsemer les légumes de feta et rôtir 20 min, jusqu''à ce que les pommes de terre dorent sur les bords.","Servir l''agneau avec les pommes de terre, nappé du jus de cuisson."]},"it":{"title":"Kleftiko di agnello","steps":["Mescolare il succo del limone, il vino, 3 cucchiai d''olio, 1 spicchio d''aglio tritato, l''origano, 1 cucchiaino di sale e pepe. Massaggiare l''agnello con il composto, coprire e lasciare in frigo 2 h (o una notte). Toglierlo dal frigo 30 min prima della cottura.","Scaldare il forno a 160 °C. Stendere due lunghi fogli di carta forno incrociati in una teglia.","Ammucchiare al centro patate, cipolla, peperone e pomodorini, condire, poi adagiare sopra l''agnello con la marinata, gli spicchi d''aglio rimasti tagliati a metà e il rosmarino.","Ripiegare la carta su tutto e chiuderla o legarla bene a cartoccio; coprire anche la teglia con alluminio.","Cuocere 2 h 30 min, finché l''agnello si sfilaccia con una forchetta. Se resiste, richiudere e cuocere altri 20 min.","Spostare l''agnello su un piatto e coprirlo. Alzare il forno a 200 °C, aprire il cartoccio, cospargere le verdure di feta e arrostire 20 min, finché le patate si dorano ai bordi.","Servire l''agnello con le patate, irrorato con il fondo di cottura."]}}'::jsonb),
  ('2f2c73a4-dbc5-4175-9822-235754fff440'::uuid, '{"fr":{"title":"Stifado de bœuf","steps":["Préchauffer le four à 170 °C. Assaisonner le bœuf et le dorer en plusieurs fois dans 2 c. à soupe d''huile dans une cocotte allant au four, à feu moyen-vif, 2 à 3 min par face. Réserver.","Baisser à feu moyen et dorer les échalotes dans la même cocotte 5 min en secouant, puis ajouter l''ail et le concentré de tomate 1 min.","Verser le vin et le vinaigre et laisser bouillonner 2 min en grattant les sucs.","Ajouter les tomates, le bouillon, la cannelle, les clous de girofle, le piment de la Jamaïque et le laurier, remettre le bœuf avec son jus et porter à frémissement.","Couvrir et cuire au four 2 h, jusqu''à ce que le bœuf soit fondant et les échalotes tendres mais entières.","Environ 25 min avant la fin, cuire les pommes de terre 20 min à l''eau salée, les égoutter et les écraser grossièrement avec 2 c. à soupe d''huile, du sel et du poivre.","Si la sauce est trop liquide, laisser mijoter le ragoût à découvert sur le feu 10 min. Retirer la cannelle, les clous et le laurier, rectifier l''assaisonnement et servir sur les pommes de terre avec du persil."]},"it":{"title":"Stifado di manzo","steps":["Scaldare il forno a 170 °C. Salare e pepare il manzo e rosolarlo a più riprese in 2 cucchiai d''olio in una casseruola adatta al forno, a fuoco medio-alto, 2-3 min per lato. Mettere da parte.","Abbassare a fuoco medio e rosolare gli scalogni nella stessa pentola 5 min scuotendola, poi aggiungere l''aglio e il concentrato per 1 min.","Versare il vino e l''aceto e far bollire 2 min, staccando il fondo.","Unire i pomodori, il brodo, la cannella, i chiodi di garofano, il pimento e l''alloro, rimettere il manzo con il suo sugo e portare a sobbollire.","Coprire e cuocere in forno 2 h, finché il manzo è tenerissimo e gli scalogni morbidi ma interi.","Circa 25 min prima della fine, lessare le patate in acqua salata 20 min finché sono tenere, scolarle e schiacciarle grossolanamente con 2 cucchiai d''olio, sale e pepe.","Se il sugo è liquido, far sobbollire lo stufato scoperto sul fuoco 10 min. Togliere cannella, chiodi di garofano e alloro, regolare di sale e servire sulle patate con il prezzemolo."]}}'::jsonb),
  ('1f05ce54-f8c8-49bf-a3d4-5cba3cdbdbc8'::uuid, '{"fr":{"title":"Youvetsi (bœuf et orzo au four)","steps":["Assaisonner le bœuf et le dorer dans 2 c. à soupe d''huile dans une cocotte allant au four, à feu moyen-vif, 2 à 3 min par face. Réserver.","Baisser le feu et faire suer l''oignon et la carotte 4 min, puis ajouter l''ail 1 min et le concentré de tomate 1 min.","Verser le vin et laisser bouillonner 1 min, puis ajouter les tomates, la cannelle, le laurier, 350 ml de bouillon et le bœuf avec son jus.","Couvrir et laisser mijoter doucement 1 h 30 en remuant de temps en temps, jusqu''à ce que le bœuf soit très tendre. Préchauffer le four à 180 °C vers la fin.","Porter à ébullition les 400 ml de bouillon restants. Incorporer l''orzo et le bouillon chaud dans la cocotte, assaisonner et reporter à frémissement.","Cuire au four à découvert 25 à 30 min en remuant une fois à mi-cuisson, jusqu''à ce que l''orzo soit tendre et ait absorbé presque toute la sauce.","Laisser reposer 10 min (cela épaissit en reposant), retirer la cannelle et le laurier et servir avec le pecorino."]},"it":{"title":"Giouvetsi (manzo e orzo al forno)","steps":["Salare e pepare il manzo e rosolarlo in 2 cucchiai d''olio in una casseruola adatta al forno, a fuoco medio-alto, 2-3 min per lato. Mettere da parte.","Abbassare il fuoco e appassire cipolla e carota 4 min, poi aggiungere l''aglio per 1 min e il concentrato per 1 min.","Versare il vino e lasciarlo sfumare 1 min, poi unire i pomodori, la cannella, l''alloro, 350 ml di brodo e il manzo con il suo sugo.","Coprire e cuocere dolcemente 1 h 30 min, mescolando ogni tanto, finché il manzo è molto tenero. Verso la fine scaldare il forno a 180 °C.","Portare a bollore i 400 ml di brodo rimasti. Unire l''orzo e il brodo caldo nella casseruola, regolare di sale e riportare a sobbollire.","Cuocere in forno scoperto 25-30 min, mescolando una volta a metà, finché l''orzo è tenero e ha assorbito quasi tutto il sugo.","Lasciare riposare 10 min (si addensa riposando), togliere cannella e alloro e servire con il pecorino."]}}'::jsonb),
  ('91ce129b-6f6d-476b-8e00-f0497a49ac72'::uuid, '{"fr":{"title":"Karnıyarık (aubergines farcies)","steps":["Préchauffer le four à 220 °C. Quadriller profondément la face coupée de chaque demi-aubergine sans percer la peau, saler et laisser 10 min, puis éponger.","Badigeonner les aubergines de 3 c. à soupe d''huile et les rôtir face coupée en dessous dans un plat à four 20 min, jusqu''à ce qu''elles soient tendres et dorées.","Pendant ce temps, faire suer l''oignon et le poivron dans 1 c. à soupe d''huile à feu moyen, 6 min. Ajouter le bœuf et cuire 5 min en l''émiettant, jusqu''à ce que son jus se soit évaporé.","Ajouter l''ail, le concentré de tomate et le piment 1 min, puis la moitié de la tomate en dés. Laisser mijoter 3 min, assaisonner et ajouter presque tout le persil.","Retourner les aubergines face coupée vers le haut et ouvrir la chair à la cuillère pour former une fente profonde. Garnir de viande, couvrir du reste de tomate et verser 150 ml d''eau dans le plat.","Baisser le four à 180 °C, couvrir de papier aluminium et cuire 15 min, puis découvrir et cuire encore 10 min jusqu''à ce que le dessus soit doré.","Pendant la cuisson, rincer le riz et le cuire à couvert dans 240 ml d''eau salée avec un peu d''huile 12 min, puis laisser reposer 5 min.","Servir les aubergines avec leur jus, le riz, le yaourt et le reste du persil."]},"it":{"title":"Karnıyarık (melanzane ripiene)","steps":["Scaldare il forno a 220 °C. Incidere a griglia in profondità il lato tagliato di ogni mezza melanzana senza bucare la buccia, salare e lasciare 10 min, poi asciugare.","Spennellare le melanzane con 3 cucchiai d''olio e arrostirle con il lato tagliato verso il basso in una pirofila 20 min, finché sono morbide e dorate.","Nel frattempo appassire cipolla e peperone in 1 cucchiaio d''olio a fuoco medio, 6 min. Aggiungere il manzo e cuocere 5 min sgranandolo, finché il liquido è evaporato.","Unire aglio, concentrato e peperoncino per 1 min, poi metà del pomodoro a dadini. Cuocere 3 min, regolare di sale e aggiungere quasi tutto il prezzemolo.","Girare le melanzane con il lato tagliato verso l''alto e aprire la polpa con un cucchiaio formando un taglio profondo. Farcire con la carne, coprire con il pomodoro rimasto e versare 150 ml d''acqua nella pirofila.","Abbassare il forno a 180 °C, coprire con alluminio e cuocere 15 min, poi scoprire e cuocere altri 10 min finché la superficie è dorata.","Durante la cottura sciacquare il riso e cuocerlo coperto in 240 ml d''acqua salata con un filo d''olio 12 min, poi lasciarlo riposare 5 min.","Servire le melanzane con il loro sugo, il riso, lo yogurt e il prezzemolo rimasto."]}}'::jsonb),
  ('ba157b8e-c181-409e-b432-61f3f90fc64e'::uuid, '{"fr":{"title":"Menemen","steps":["Faire chauffer le beurre et 1 c. à soupe d''huile dans une grande poêle à feu moyen. Ajouter le poivron (et l''oignon, si on en met) avec une pincée de sel et cuire 5 min jusqu''à ce qu''il soit tendre.","Ajouter les tomates et le piment, couvrir et cuire 5 à 6 min en remuant une fois, jusqu''à ce que les tomates fondent en une sauce épaisse.","Battre légèrement les œufs avec du sel et du poivre.","Baisser le feu, verser les œufs et remuer lentement à la spatule 2 à 3 min en les mêlant à la sauce, jusqu''à ce qu''ils soient juste pris et encore moelleux.","Parsemer de feta et de persil et servir directement dans la poêle avec le pain."]},"it":{"title":"Menemen","steps":["Scaldare il burro e 1 cucchiaio d''olio in una padella larga a fuoco medio. Aggiungere il peperone (e la cipolla, se si usa) con un pizzico di sale e cuocere 5 min finché è morbido.","Unire i pomodori e il peperoncino, coprire e cuocere 5-6 min, mescolando una volta, finché i pomodori si disfano in un sugo denso.","Sbattere leggermente le uova con sale e pepe.","Abbassare il fuoco, versare le uova e mescolare lentamente con una spatola per 2-3 min, amalgamandole al sugo, finché sono appena rapprese e ancora morbide.","Cospargere di feta e prezzemolo e servire direttamente in padella con il pane."]}}'::jsonb),
  ('6b1436ee-7841-465f-b752-b7b18bd352ba'::uuid, '{"fr":{"title":"Fattouche au poulet grillé","steps":["Frotter le poulet avec 1 c. à soupe d''huile, 2 gousses d''ail, 1 c. à café de sumac, le paprika, le jus d''un demi-citron et du sel. Laisser reposer 20 min.","Préchauffer le four à 200 °C. Ouvrir les pitas, les déchirer en morceaux, les mélanger avec 1 c. à soupe d''huile et une pincée de sel et les cuire 8 à 10 min jusqu''à ce qu''ils soient croustillants et dorés.","Fouetter 3 c. à soupe d''huile avec le jus d''un citron, le vinaigre, le reste de l''ail et du sumac, du sel et du poivre.","Faire chauffer une poêle-gril à feu moyen-vif et cuire le poulet 5 à 6 min par face, jusqu''à ce qu''il soit grillé et cuit à cœur (plus rose au centre). Laisser reposer 5 min, puis trancher.","Mélanger la laitue, la tomate, le concombre, les radis, l''oignon nouveau, le persil et la menthe avec la vinaigrette.","Incorporer les chips de pita juste avant de servir, garnir de poulet et presser le dernier demi-citron par-dessus."]},"it":{"title":"Fattoush con pollo alla griglia","steps":["Massaggiare il pollo con 1 cucchiaio d''olio, 2 spicchi d''aglio, 1 cucchiaino di sumac, la paprika, il succo di mezzo limone e sale. Lasciare riposare 20 min.","Scaldare il forno a 200 °C. Aprire le pita, spezzettarle, condirle con 1 cucchiaio d''olio e un pizzico di sale e cuocerle 8-10 min finché sono croccanti e dorate.","Sbattere 3 cucchiai d''olio con il succo di 1 limone, l''aceto, l''aglio e il sumac rimasti, sale e pepe.","Scaldare una bistecchiera a fuoco medio-alto e cuocere il pollo 5-6 min per lato, finché è abbrustolito e cotto all''interno (non più rosa al centro). Lasciare riposare 5 min, poi affettare.","Condire la lattuga, il pomodoro, il cetriolo, i ravanelli, il cipollotto, il prezzemolo e la menta con la salsa.","Unire le chips di pita appena prima di servire, completare con il pollo e spremere sopra l''ultima metà di limone."]}}'::jsonb),
  ('2a07c7e1-2a5b-461d-b203-27a73373f305'::uuid, '{"fr":{"title":"Shish taouk, sauce à l''ail","steps":["Fouetter le yaourt nature, le jus d''un citron, 1 c. à soupe d''huile, le concentré de tomate, la moutarde, 3 gousses d''ail, le paprika, le sumac, la cannelle, 1 c. à café de sel et du poivre. Y enrober le poulet, couvrir et réfrigérer au moins 2 h (jusqu''à une nuit).","Pour la sauce à l''ail, écraser la dernière gousse avec une pincée de sel en purée, puis l''incorporer au fouet au yaourt grec avec 1 c. à soupe d''huile et un filet de citron. Réfrigérer.","Enfiler le poulet sur des brochettes, en alternant avec le poivron et l''oignon si on en met.","Faire chauffer une poêle-gril à feu moyen-vif, la huiler et cuire les brochettes 10 à 12 min en les tournant toutes les 3 min, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur.","Laisser reposer 5 min sous une feuille d''aluminium pendant que les pitas chauffent dans la poêle.","Servir les brochettes avec les pitas, la sauce à l''ail, la tomate, les cornichons et le reste du citron en quartiers."]},"it":{"title":"Shish tawook con salsa all''aglio","steps":["Sbattere lo yogurt bianco, il succo di 1 limone, 1 cucchiaio d''olio, il concentrato, la senape, 3 spicchi d''aglio, paprika, sumac, cannella, 1 cucchiaino di sale e pepe. Condire il pollo, coprire e lasciare in frigo almeno 2 h (fino a una notte).","Per la salsa all''aglio, schiacciare l''ultimo spicchio con un pizzico di sale fino a ridurlo in crema, poi unirlo con la frusta allo yogurt greco con 1 cucchiaio d''olio e una spruzzata di limone. Mettere in frigo.","Infilzare il pollo sugli spiedini, alternandolo con peperone e cipolla se si usano.","Scaldare una bistecchiera a fuoco medio-alto, ungerla e cuocere gli spiedini 10-12 min, girandoli ogni 3 min, finché sono abbrustoliti ai bordi e cotti all''interno.","Lasciare riposare 5 min sotto un foglio di alluminio mentre si scaldano le pita nella bistecchiera.","Servire gli spiedini con le pita, la salsa all''aglio, il pomodoro, i cetriolini e il resto del limone a spicchi."]}}'::jsonb),
  ('0c76e1d2-3d8c-460e-b515-bb545d5fa83f'::uuid, '{"fr":{"title":"Moujadara au halloumi","steps":["Couvrir les lentilles de 600 ml d''eau dans une casserole, porter à ébullition et cuire 15 min, jusqu''à ce qu''elles soient juste tendres mais encore entières. Égoutter en gardant le liquide.","Pendant ce temps, cuire les oignons dans 4 c. à soupe d''huile avec une pincée de sel dans une grande poêle à feu moyen, en remuant souvent, 25 à 30 min, jusqu''à ce qu''ils soient bien bruns ; monter le feu les 3 dernières minutes pour qu''une partie croustille. En réserver un tiers pour le dessus.","Remettre les lentilles dans la casserole avec le riz, le reste des oignons et leur huile, le cumin, le piment de la Jamaïque, 1 c. à café de sel et du poivre. Remuer 1 min.","Ajouter 280 ml du liquide des lentilles (compléter avec de l''eau), porter à ébullition, couvrir et cuire à feu très doux 15 min. Laisser reposer hors du feu, couvert, 10 min.","Essuyer la poêle et cuire le halloumi à feu moyen-vif 2 min par face, jusqu''à ce qu''il soit doré.","Égrener la moujadara, la garnir des oignons croustillants et du halloumi et servir avec du yaourt et une salade de tomate, concombre et persil hachés."]},"it":{"title":"Mujaddara con halloumi","steps":["Coprire le lenticchie con 600 ml d''acqua in una casseruola, portare a bollore e cuocere 15 min, finché sono appena tenere ma intere. Scolarle tenendo il liquido.","Nel frattempo cuocere le cipolle in 4 cucchiai d''olio con un pizzico di sale in una padella larga a fuoco medio, mescolando spesso, 25-30 min, finché sono ben brunite; alzare il fuoco negli ultimi 3 min perché una parte diventi croccante. Tenerne da parte un terzo per guarnire.","Rimettere le lenticchie nella casseruola con il riso, il resto delle cipolle con il loro olio, il cumino, il pimento, 1 cucchiaino di sale e pepe. Mescolare 1 min.","Aggiungere 280 ml del liquido delle lenticchie (completare con acqua), portare a bollore, coprire e cuocere a fuoco minimo 15 min. Lasciare riposare fuori dal fuoco, coperto, 10 min.","Pulire la padella e cuocere l''halloumi a fuoco medio-alto 2 min per lato, finché è dorato.","Sgranare la mujaddara, completare con le cipolle croccanti e l''halloumi e servire con yogurt e un''insalata di pomodoro, cetriolo e prezzemolo tritati."]}}'::jsonb),
  ('6ed4612b-73f6-4d13-bbe9-4b00aaa15141'::uuid, '{"fr":{"title":"Tajine de pois chiches aux abricots et semoule","steps":["Faire revenir l''oignon dans 2 c. à soupe d''huile avec une pincée de sel dans une grande sauteuse à feu moyen, à couvert, 8 min jusqu''à ce qu''il soit tendre et brillant.","Ajouter l''ail, le gingembre, le cumin, la coriandre moulue, le paprika, le curcuma et la cannelle et remuer 1 min jusqu''à ce que les épices embaument.","Ajouter la carotte et la patate douce et bien les enrober, puis les pois chiches, les tomates, le bouillon et les abricots. Porter à ébullition, couvrir et laisser mijoter 20 min, jusqu''à ce que les légumes soient tendres et la sauce épaissie.","Pendant ce temps, mettre la semoule dans un bol avec le zeste râpé du citron, 1 c. à café d''huile et une pincée de sel, verser 130 ml d''eau bouillante, couvrir et laisser gonfler 5 min, puis égrener à la fourchette.","Faire griller les amandes à sec dans une poêle 2 min jusqu''à ce qu''elles soient dorées, en surveillant.","Assaisonner le tajine de sel, de poivre et d''un filet de citron. Servir sur la semoule, garni d''amandes, d''une cuillerée de yaourt et de coriandre."]},"it":{"title":"Tajine di ceci e albicocche con cous cous","steps":["Cuocere la cipolla in 2 cucchiai d''olio con un pizzico di sale in una pentola larga a fuoco medio, coperta, 8 min finché è morbida e lucida.","Aggiungere aglio, zenzero, cumino, coriandolo in polvere, paprika, curcuma e cannella e mescolare 1 min finché profumano.","Unire la carota e la patata dolce mescolando bene, poi i ceci, i pomodori, il brodo e le albicocche. Portare a bollore, coprire e cuocere 20 min, finché le verdure sono tenere e il sugo si è addensato.","Nel frattempo mettere il cous cous in una ciotola con la scorza grattugiata del limone, 1 cucchiaino d''olio e un pizzico di sale, versare 130 ml d''acqua bollente, coprire e lasciare 5 min, poi sgranare con una forchetta.","Tostare le mandorle in una padella asciutta per 2 min finché sono dorate, sorvegliandole.","Regolare il tajine di sale, pepe e una spruzzata di limone. Servire sul cous cous, con le mandorle, un cucchiaio di yogurt e il coriandolo."]}}'::jsonb),
  ('c24af535-ff47-498a-a075-d6f86716f8c9'::uuid, '{"fr":{"title":"Boulettes d''agneau aux pois chiches et tomate","steps":["Mélanger l''agneau avec l''oignon râpé, 1 gousse d''ail, la majeure partie du persil, 1 c. à café de cumin, 1 c. à café de paprika, la cannelle, du sel et du poivre. Former 14 à 16 boulettes de la taille d''une noix.","Faire dorer les boulettes dans 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif, 6 à 8 min en les retournant, puis les réserver sur une assiette.","Faire fondre l''oignon haché dans la même poêle à feu moyen 6 min, puis ajouter le reste de l''ail, du cumin et du paprika ainsi que la harissa et remuer 1 min.","Ajouter les tomates, les pois chiches et 100 ml d''eau, assaisonner et porter à frémissement.","Remettre les boulettes, couvrir et laisser mijoter doucement 15 min, jusqu''à ce qu''elles soient cuites à cœur et la sauce épaissie.","Parsemer du reste de persil et servir avec du pain plat chaud."]},"it":{"title":"Polpette d''agnello con ceci al pomodoro","steps":["Mescolare l''agnello con la cipolla grattugiata, 1 spicchio d''aglio, quasi tutto il prezzemolo, 1 cucchiaino di cumino, 1 cucchiaino di paprika, la cannella, sale e pepe. Formare 14-16 polpette grandi come una noce.","Rosolare le polpette in 1 cucchiaio d''olio in una padella larga a fuoco medio-alto, 6-8 min girandole, poi metterle da parte su un piatto.","Appassire la cipolla tritata nella stessa padella a fuoco medio per 6 min, poi aggiungere l''aglio, il cumino e la paprika rimasti e la harissa e mescolare 1 min.","Aggiungere i pomodori, i ceci e 100 ml d''acqua, salare e portare a sobbollire.","Rimettere le polpette, coprire e cuocere a fuoco dolce 15 min, finché sono cotte all''interno e il sugo si è addensato.","Cospargere con il prezzemolo rimasto e servire con pane piatto caldo."]}}'::jsonb),
  ('3d018581-d136-4665-a2dc-1caf7eef3fbd'::uuid, '{"fr":{"title":"Couscous royal","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans un grand faitout à feu moyen-vif, 5 min. Ajouter l''oignon et cuire 3 min.","Incorporer le concentré de tomate, 1,5 c. à café de ras el hanout, le paprika, le curcuma, du sel et du poivre, verser le bouillon et laisser frémir à couvert à moitié 30 min.","Ajouter les carottes et le navet et laisser frémir 15 min.","Pendant ce temps, faire dorer les hauts de cuisse dans une poêle avec un peu d''huile, 4 min de chaque côté, puis les ajouter au faitout avec les courgettes et les pois chiches ; laisser frémir encore 25 min, jusqu''à ce que l''agneau soit tendre.","Cuire les merguez dans la poêle à feu moyen, 8 à 10 min en les retournant, jusqu''à ce qu''elles soient dorées et cuites.","Mettre la semoule dans un saladier avec le reste du ras el hanout, une pincée de sel et un filet d''huile ; verser 180 ml de bouillon chaud, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette en y incorporant le beurre.","Servir la semoule garnie des viandes et des légumes, avec un bol de bouillon à part, relevé d''un peu de harissa pour ceux qui aiment le piquant."]},"it":{"title":"Cuscus royal","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola capiente a fuoco medio-alto, 5 min. Aggiungere la cipolla e cuocere 3 min.","Unire il concentrato di pomodoro, 1,5 cucchiaini di ras el hanout, la paprika, la curcuma, sale e pepe, versare il brodo e cuocere a fuoco dolce, semicoperto, 30 min.","Aggiungere le carote e la rapa e cuocere 15 min.","Nel frattempo rosolare le sovracosce in una padella con un filo d''olio, 4 min per lato, poi unirle alla pentola con le zucchine e i ceci; cuocere ancora 25 min, finché l''agnello è tenero.","Cuocere le merguez nella padella a fuoco medio, 8-10 min girandole, finché sono dorate e cotte.","Mettere il cuscus in una ciotola con il ras el hanout rimasto, un pizzico di sale e un filo d''olio; versare 180 ml di brodo caldo, coprire e lasciare riposare 5 min.","Sgranare il cuscus con una forchetta incorporando il burro.","Servire il cuscus con sopra le carni e le verdure, con una ciotola di brodo a parte e un po'' di harissa sciolta dentro per chi ama il piccante."]}}'::jsonb),
  ('9a6ee5cf-200e-4579-9433-3f98f473c9de'::uuid, '{"fr":{"title":"Tajine d''agneau aux pruneaux","steps":["Faire fondre l''oignon dans 1 c. à soupe d''huile dans une cocotte à feu moyen, 3 à 4 min.","Ajouter l''agneau, le bâton de cannelle, le curcuma, le gingembre, beaucoup de poivre et un peu de sel ; bien enrober, puis verser 300 ml d''eau.","Porter à ébullition, couvrir et laisser mijoter très doucement 1 h 15, jusqu''à ce que l''agneau soit presque tendre ; ajouter un peu d''eau si cela attache.","Ajouter les pruneaux et cuire encore 20 min à couvert.","Mélanger le miel et la cannelle moulue à la sauce et laisser mijoter 15 min à découvert, jusqu''à ce qu''elle soit épaisse et brillante.","Pendant ce temps, faire griller les amandes à sec dans une poêle à feu moyen, 3 à 4 min en remuant, jusqu''à ce qu''elles soient dorées.","Servir le tajine parsemé d''amandes et de graines de sésame, avec du pain pour saucer."]},"it":{"title":"Tajine d''agnello alle prugne","steps":["Appassire la cipolla in 1 cucchiaio d''olio in una pentola dal fondo spesso a fuoco medio, 3-4 min.","Aggiungere l''agnello, la stecca di cannella, la curcuma, lo zenzero, abbondante pepe e un po'' di sale; mescolare bene, poi versare 300 ml d''acqua.","Portare a bollore, coprire e cuocere a fuoco dolcissimo 1 h 15, finché l''agnello è quasi tenero; aggiungere un goccio d''acqua se si asciuga.","Aggiungere le prugne e cuocere ancora 20 min, coperto.","Mescolare il miele e la cannella in polvere nel sugo e cuocere scoperto 15 min, finché è denso e lucido.","Nel frattempo tostare le mandorle in una padella asciutta a fuoco medio, 3-4 min scuotendo, finché sono dorate.","Servire il tajine cosparso di mandorle e semi di sesamo, con pane per fare la scarpetta."]}}'::jsonb),
  ('5f6175e0-2fa4-486d-a240-ed5a45569174'::uuid, '{"fr":{"title":"Tajine de kefta aux œufs","steps":["Mélanger le bœuf avec l''oignon râpé, la moitié du persil, 1 c. à café de cumin, 1 c. à café de paprika, la cannelle, du sel et du poivre. Former de petites boulettes d''environ 3 cm.","Faire fondre l''oignon haché et l''ail dans 1 c. à soupe d''huile dans une grande sauteuse avec couvercle (ou un tajine) à feu moyen, 5 min.","Ajouter le reste du cumin et du paprika, le curcuma et le piment, puis les tomates et 100 ml d''eau ; assaisonner et laisser mijoter 10 min, jusqu''à ce que la sauce épaississe légèrement.","Déposer les boulettes dans la sauce, couvrir et laisser mijoter doucement 15 min en les retournant une fois.","Creuser 3 puits entre les boulettes et y casser un œuf. Couvrir et cuire 5 à 7 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Parsemer du reste de persil et de coriandre et servir directement dans le plat avec du pain."]},"it":{"title":"Tajine di kefta con uova","steps":["Mescolare il manzo con la cipolla grattugiata, metà del prezzemolo, 1 cucchiaino di cumino, 1 cucchiaino di paprika, la cannella, sale e pepe. Formare piccole polpette di circa 3 cm.","Appassire la cipolla tritata e l''aglio in 1 cucchiaio d''olio in una padella larga con coperchio (o un tajine) a fuoco medio, 5 min.","Aggiungere il cumino e la paprika rimasti, la curcuma e il peperoncino, poi i pomodori e 100 ml d''acqua; salare e cuocere 10 min, finché il sugo si addensa leggermente.","Adagiare le polpette nel sugo, coprire e cuocere a fuoco dolce 15 min, girandole una volta.","Formare 3 incavi tra le polpette e rompervi un uovo ciascuno. Coprire e cuocere 5-7 min, finché gli albumi sono rappresi e i tuorli ancora morbidi.","Cospargere con il prezzemolo rimasto e il coriandolo e servire direttamente dalla padella con il pane."]}}'::jsonb),
  ('8f203224-5bb8-48d2-8fcc-dfa1e8e3c43b'::uuid, '{"fr":{"title":"Harira","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans un grand faitout à feu moyen-vif, 5 min.","Ajouter l''oignon, le céleri et la majeure partie du persil et cuire 5 min, puis incorporer le gingembre, le curcuma, la cannelle, 0,5 c. à café de poivre et le concentré de tomate 1 min.","Ajouter les tomates, les lentilles et le bouillon, porter à ébullition, puis couvrir et laisser mijoter doucement 40 min, jusqu''à ce que l''agneau et les lentilles soient tendres.","Ajouter les pois chiches et les vermicelles et laisser frémir 8 min.","Délayer la farine dans 100 ml d''eau froide, la verser en filet dans la soupe en remuant et laisser frémir 3 à 4 min, jusqu''à ce qu''elle devienne veloutée.","Battre l''œuf, puis le verser en filet dans la soupe frémissante en remuant pour qu''il prenne en fins filaments ; saler.","Servir avec le reste du persil, la coriandre et des quartiers de citron à presser."]},"it":{"title":"Harira","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola capiente a fuoco medio-alto, 5 min.","Aggiungere la cipolla, il sedano e quasi tutto il prezzemolo e cuocere 5 min, poi unire lo zenzero, la curcuma, la cannella, 0,5 cucchiaini di pepe e il concentrato di pomodoro per 1 min.","Aggiungere i pomodori, le lenticchie e il brodo, portare a bollore, poi coprire e cuocere a fuoco dolce 40 min, finché l''agnello e le lenticchie sono teneri.","Aggiungere i ceci e i vermicelli e cuocere 8 min.","Stemperare la farina in 100 ml d''acqua fredda, versarla a filo nella zuppa mescolando e cuocere 3-4 min, finché diventa vellutata.","Sbattere l''uovo, poi versarlo a filo nella zuppa che sobbolle mescolando, perché si rapprenda in fili sottili; salare.","Servire con il prezzemolo rimasto, il coriandolo e spicchi di limone da spremere."]}}'::jsonb),
  ('5d13af89-d872-4a64-91e2-ab41f15ff8a1'::uuid, '{"fr":{"title":"Tajine de poisson au cabillaud","steps":["Préparer la chermoula : mélanger le persil, la coriandre, l''ail, le cumin, le paprika, le piment, le jus d''un demi-citron, 2 c. à soupe d''huile et une bonne pincée de sel.","Enrober le cabillaud de la moitié de la chermoula et le laisser au réfrigérateur pendant la préparation des légumes.","Étaler l''oignon au fond d''une grande sauteuse avec couvercle (ou d''un tajine) avec la dernière c. à soupe d''huile. Disposer la carotte, puis les pommes de terre, et assaisonner de curcuma, de gingembre, de sel et de poivre.","Disposer la tomate et le poivron par-dessus, napper du reste de chermoula et ajouter 120 ml d''eau.","Couvrir et cuire à feu moyen-doux 25 min, jusqu''à ce que les pommes de terre soient presque tendres sous la pointe d''un couteau.","Poser le cabillaud dessus avec les olives et quelques tranches du demi-citron restant, couvrir et cuire 10 à 12 min, jusqu''à ce que le poisson s''effeuille facilement et que le liquide ait réduit en sauce.","Servir directement dans le plat."]},"it":{"title":"Tajine di pesce con merluzzo","steps":["Preparare la chermoula: mescolare prezzemolo, coriandolo, aglio, cumino, paprika, peperoncino, il succo di mezzo limone, 2 cucchiai d''olio e un buon pizzico di sale.","Condire il merluzzo con metà della chermoula e lasciarlo in frigorifero mentre si preparano le verdure.","Distribuire la cipolla sul fondo di una padella larga con coperchio (o di un tajine) con l''ultimo cucchiaio d''olio. Disporre a strati la carota, poi le patate, e condire con curcuma, zenzero, sale e pepe.","Adagiare sopra il pomodoro e il peperone, distribuire la chermoula rimasta e aggiungere 120 ml d''acqua.","Coprire e cuocere a fuoco medio-basso 25 min, finché le patate sono quasi tenere alla prova del coltello.","Adagiare sopra il merluzzo con le olive e qualche fetta del mezzo limone rimasto, coprire e cuocere 10-12 min, finché il pesce si sfalda facilmente e il liquido si è ridotto in salsa.","Servire direttamente dalla padella."]}}'::jsonb),
  ('bbf7ab1c-0133-41c4-be33-4ff4253271c4'::uuid, '{"fr":{"title":"Couscous merguez et légumes rôtis","steps":["Préchauffer le four à 200 °C. Mélanger l''aubergine, la courgette, le poivron et l''oignon sur une grande plaque avec 3 c. à soupe d''huile, le ras el hanout, du sel et du poivre, et les étaler en une seule couche.","Rôtir 15 min, puis remuer, ajouter les pois chiches et poser les merguez dessus.","Rôtir encore 18 à 20 min en retournant les merguez une fois, jusqu''à ce qu''elles soient dorées et les légumes fondants et caramélisés sur les bords.","Pendant ce temps, porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min.","Égrener la semoule à la fourchette et y mélanger les légumes rôtis et les pois chiches avec le jus de cuisson et le jus de citron.","Servir garni des merguez, de menthe et d''un peu de harissa."]},"it":{"title":"Cuscus con merguez e verdure arrosto","steps":["Scaldare il forno a 200 °C. Condire melanzana, zucchina, peperone e cipolla su una teglia grande con 3 cucchiai d''olio, il ras el hanout, sale e pepe, e distribuirli in un solo strato.","Arrostire 15 min, poi mescolare, aggiungere i ceci e adagiare sopra le merguez.","Arrostire ancora 18-20 min girando le merguez una volta, finché sono dorate e le verdure morbide e caramellate ai bordi.","Nel frattempo portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min.","Sgranare il cuscus con una forchetta e unire le verdure arrosto e i ceci con il fondo di cottura e il succo di limone.","Servire con sopra le merguez, la menta e un po'' di harissa."]}}'::jsonb),
  ('ea0abd75-bf32-4718-9c3a-4ccfd8fc9917'::uuid, '{"fr":{"title":"Crevettes à la chermoula et semoule","steps":["Mélanger la coriandre, le persil, l''ail, le cumin, le paprika, le piment, le zeste et le jus d''un demi-citron, 2 c. à soupe d''huile et une pincée de sel pour obtenir une chermoula fluide.","Enrober les crevettes de la moitié de la chermoula et laisser reposer 5 min.","Porter le bouillon à ébullition, le verser sur la semoule dans un saladier avec 1 c. à café d''huile, couvrir et laisser gonfler 5 min, puis égrener à la fourchette et incorporer la carotte râpée.","Cuire les crevettes dans une poêle bien chaude avec le reste de l''huile à feu moyen-vif, 3 à 4 min en les retournant une fois, jusqu''à ce qu''elles soient roses et juste cuites.","Déposer les crevettes sur la semoule, arroser du reste de chermoula et servir avec l''autre demi-citron en quartiers."]},"it":{"title":"Gamberi alla chermoula con cuscus","steps":["Mescolare coriandolo, prezzemolo, aglio, cumino, paprika, peperoncino, la scorza e il succo di mezzo limone, 2 cucchiai d''olio e un pizzico di sale per ottenere una chermoula fluida.","Condire i gamberi con metà della chermoula e lasciare riposare 5 min.","Portare a bollore il brodo, versarlo sul cuscus in una ciotola con 1 cucchiaino d''olio, coprire e lasciare riposare 5 min, poi sgranare con una forchetta e unire la carota grattugiata.","Cuocere i gamberi in una padella ben calda con l''olio rimasto a fuoco medio-alto, 3-4 min girandoli una volta, finché sono rosa e appena cotti.","Disporre i gamberi sul cuscus, condire con la chermoula rimasta e servire con l''altra metà del limone a spicchi."]}}'::jsonb),
  ('c4a8b76a-90e0-4bbd-9679-d04cd71870d9'::uuid, '{"fr":{"title":"Dal de lentilles corail au lait de coco et riz","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; le laisser gonfler 5 min hors du feu.","Pendant ce temps, faire fondre l''oignon dans 1 c. à soupe d''huile dans une casserole à feu moyen, 5 min.","Ajouter l''ail, le gingembre et le piment et cuire 1 min, puis le cumin, la coriandre moulue, le curcuma et la cannelle 30 s.","Ajouter les lentilles, la tomate, le lait de coco et 450 ml d''eau. Porter à ébullition, puis laisser mijoter à couvert à moitié 20 min en remuant souvent, jusqu''à ce que les lentilles se défassent en une purée épaisse ; ajouter de l''eau si besoin.","Assaisonner de sel et de jus de citron.","Chauffer 1 c. à soupe d''huile dans une petite poêle, ajouter les graines de moutarde et les laisser éclater 30 s, puis verser sur le dal. Servir avec le riz et la coriandre."]},"it":{"title":"Dal di lenticchie rosse al cocco con riso","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo appassire la cipolla in 1 cucchiaio d''olio in una casseruola a fuoco medio, 5 min.","Aggiungere aglio, zenzero e peperoncino e cuocere 1 min, poi cumino, coriandolo in polvere, curcuma e cannella per 30 s.","Aggiungere le lenticchie, il pomodoro, il latte di cocco e 450 ml d''acqua. Portare a bollore, poi cuocere semicoperto 20 min mescolando spesso, finché le lenticchie si sfaldano in una purea densa; aggiungere acqua se serve.","Regolare di sale e aggiungere il succo di limone.","Scaldare 1 cucchiaio d''olio in un padellino, aggiungere i semi di senape e lasciarli scoppiettare 30 s, poi versarli sul dal. Servire con il riso e il coriandolo."]}}'::jsonb),
  ('da808dc3-7d41-43cd-9e70-cb82f2e4f7bd'::uuid, '{"fr":{"title":"Curry de poulet du Kerala","steps":["Mélanger le poulet avec la moitié du curcuma, la moitié du garam masala, le poivre, une pincée de piment en poudre et 0,5 c. à café de sel ; laisser reposer pendant la préparation du reste.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Faire revenir l''oignon dans 2 c. à soupe d''huile dans une sauteuse à fond épais à feu moyen, 10 min, jusqu''à ce qu''il soit doré. Ajouter le gingembre et l''ail et cuire 1 min.","Ajouter la tomate et cuire 3 min jusqu''à ce qu''elle soit fondue, puis incorporer la coriandre moulue, le reste du piment, du curcuma et du garam masala avec 3 c. à soupe d''eau et cuire 1 min.","Ajouter le poulet et remuer à feu moyen-vif 3 à 4 min jusqu''à ce qu''il devienne opaque. Verser 100 ml d''eau, couvrir et cuire à feu doux 15 min, jusqu''à ce qu''il soit tendre.","Incorporer le lait de coco et laisser frémir 5 min à découvert, jusqu''à ce que la sauce épaississe légèrement ; rectifier le sel.","Dans une petite poêle, faire dorer l''échalote dans 1 c. à soupe d''huile, ajouter les graines de moutarde et le piment 30 s, puis verser sur le curry. Servir avec le riz."]},"it":{"title":"Curry di pollo del Kerala","steps":["Condire il pollo con metà della curcuma, metà del garam masala, il pepe, un pizzico di peperoncino in polvere e 0,5 cucchiaini di sale; lasciarlo riposare mentre si prepara il resto.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere la cipolla in 2 cucchiai d''olio in una padella dal fondo spesso a fuoco medio, 10 min, finché è dorata. Aggiungere zenzero e aglio e cuocere 1 min.","Aggiungere il pomodoro e cuocere 3 min finché si disfa, poi unire il coriandolo in polvere, il resto del peperoncino, della curcuma e del garam masala con 3 cucchiai d''acqua e cuocere 1 min.","Aggiungere il pollo e mescolare a fuoco medio-alto 3-4 min finché diventa opaco. Versare 100 ml d''acqua, coprire e cuocere a fuoco basso 15 min, finché è tenero.","Unire il latte di cocco e cuocere scoperto 5 min, finché il sugo si addensa leggermente; regolare di sale.","In un padellino dorare lo scalogno in 1 cucchiaio d''olio, aggiungere i semi di senape e il peperoncino per 30 s, poi versare sul curry. Servire con il riso."]}}'::jsonb),
  ('f47d0b89-d4b8-425b-8d63-dc0b9302e262'::uuid, '{"fr":{"title":"Chaat de pommes de terre et pois chiches croustillants","steps":["Préchauffer le four à 220 °C. Mélanger les pommes de terre et les pois chiches sur une grande plaque avec 2 c. à soupe d''huile, 1 c. à café de cumin, le piment en poudre et du sel.","Rôtir 30 min en retournant à mi-cuisson, jusqu''à ce que les pommes de terre soient dorées et les pois chiches croustillants.","Pendant ce temps, hacher finement la menthe, la majeure partie de la coriandre et le piment et les mélanger à 3 c. à soupe de yaourt avec la moitié du jus de citron vert et une pincée de sel pour obtenir un chutney vert.","Fouetter le reste du yaourt avec une pincée de sel et le reste du cumin, grillé 30 s à sec dans une poêle si on le souhaite.","Dresser les pommes de terre et pois chiches chauds dans les assiettes, napper de yaourt et de chutney vert, parsemer d''oignon, de tomate et du reste de coriandre, et presser le reste du citron vert par-dessus."]},"it":{"title":"Chaat di patate e ceci croccanti","steps":["Scaldare il forno a 220 °C. Condire patate e ceci su una teglia grande con 2 cucchiai d''olio, 1 cucchiaino di cumino, il peperoncino in polvere e sale.","Arrostire 30 min girando a metà cottura, finché le patate sono dorate e i ceci croccanti.","Nel frattempo tritare finemente la menta, quasi tutto il coriandolo e il peperoncino e mescolarli a 3 cucchiai di yogurt con metà del succo di lime e un pizzico di sale per ottenere un chutney verde.","Sbattere lo yogurt rimasto con un pizzico di sale e il cumino rimasto, tostato 30 s in una padella asciutta se si vuole.","Disporre patate e ceci caldi nei piatti, condire con lo yogurt e il chutney verde, cospargere di cipolla, pomodoro e coriandolo rimasto e spremere sopra il resto del lime."]}}'::jsonb),
  ('5b716b9c-544f-4b6e-89b1-5787ec0d5d4d'::uuid, '{"fr":{"title":"Biryani de chou-fleur et petits pois","steps":["Rincer le riz jusqu''à ce que l''eau soit claire et le faire tremper 20 min dans de l''eau froide, puis l''égoutter.","Chauffer 2 c. à soupe d''huile dans une cocotte à feu moyen, ajouter le laurier, la cannelle, les clous de girofle et les noix de cajou et faire revenir 1 min, puis ajouter l''oignon et cuire 8 à 10 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis la moitié de la menthe et la tomate, et cuire 3 min jusqu''à ce qu''elle soit fondue.","Ajouter le chou-fleur, les petits pois, la cardamome, le cumin, le curcuma, le piment, le garam masala, la coriandre moulue et 1 c. à café de sel et remuer 2 min pour bien enrober.","Incorporer 50 g de yaourt, puis le riz égoutté et 300 ml d''eau bouillante. Porter à ébullition, couvrir hermétiquement et cuire à feu très doux 15 min.","Laisser reposer 10 min à couvert hors du feu, puis égrener délicatement à la fourchette.","Mélanger le reste du yaourt avec le concombre, le reste de la menthe et une pincée de sel pour faire un raïta et le servir avec le biryani."]},"it":{"title":"Biryani di cavolfiore e piselli","steps":["Sciacquare il riso finché l''acqua è limpida e lasciarlo in ammollo in acqua fredda 20 min, poi scolarlo.","Scaldare 2 cucchiai d''olio in una pentola dal fondo spesso con coperchio a fuoco medio, aggiungere alloro, cannella, chiodi di garofano e anacardi e soffriggere 1 min, poi aggiungere la cipolla e cuocere 8-10 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi metà della menta e il pomodoro, e cuocere 3 min finché si ammorbidisce.","Aggiungere cavolfiore, piselli, cardamomo, cumino, curcuma, peperoncino, garam masala, coriandolo in polvere e 1 cucchiaino di sale e mescolare 2 min per insaporire.","Unire 50 g di yogurt, poi il riso scolato e 300 ml d''acqua bollente. Portare a bollore, coprire bene e cuocere a fuoco minimo 15 min.","Lasciare riposare coperto 10 min fuori dal fuoco, poi sgranare delicatamente con una forchetta.","Mescolare lo yogurt rimasto con il cetriolo, la menta rimasta e un pizzico di sale per preparare la raita e servirla con il biryani."]}}'::jsonb),
  ('6bc1c089-e3e1-4387-b021-e752bd4966a1'::uuid, '{"fr":{"title":"Curry de pois chiches et potiron au lait de coco","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Chauffer 2 c. à soupe d''huile dans une grande sauteuse à feu moyen, ajouter les graines de moutarde et le cumin et les laisser grésiller et éclater 30 s.","Ajouter l''oignon, l''ail et le gingembre et cuire 5 min jusqu''à ce qu''ils soient tendres, puis la tomate, la coriandre moulue, le curcuma, le piment et du sel, et cuire 3 min jusqu''à ce que la tomate se défasse.","Ajouter le potiron, les pois chiches et 250 ml d''eau, couvrir et laisser mijoter 15 min, jusqu''à ce que le potiron soit tendre.","Incorporer le lait de coco, le garam masala et les épinards et laisser frémir 3 à 4 min à découvert, jusqu''à ce que les épinards tombent et que la sauce épaississe.","Finir avec le jus de citron vert et la coriandre et servir avec le riz."]},"it":{"title":"Curry di ceci e zucca al cocco","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare 2 cucchiai d''olio in una padella larga a fuoco medio, aggiungere i semi di senape e il cumino e lasciarli sfrigolare e scoppiettare 30 s.","Aggiungere cipolla, aglio e zenzero e cuocere 5 min finché sono morbidi, poi il pomodoro, il coriandolo in polvere, la curcuma, il peperoncino e il sale, e cuocere 3 min finché il pomodoro si disfa.","Aggiungere la zucca, i ceci e 250 ml d''acqua, coprire e cuocere 15 min, finché la zucca è tenera.","Unire il latte di cocco, il garam masala e gli spinaci e cuocere scoperto 3-4 min, finché gli spinaci appassiscono e il sugo si addensa.","Completare con il succo di lime e il coriandolo e servire con il riso."]}}'::jsonb),
  ('fef780b4-874f-4404-af16-299d19f45262'::uuid, '{"fr":{"title":"Curry de crevettes de Goa au coco et haricots verts","steps":["Mélanger les crevettes avec 0,25 c. à café de curcuma et une pincée de sel.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Cuire l''oignon dans 2 c. à soupe d''huile dans une grande sauteuse à feu moyen, 6 à 7 min, jusqu''à ce qu''il soit tendre et légèrement doré. Ajouter l''ail et le gingembre et cuire 1 min.","Incorporer le paprika, le piment, la coriandre moulue, le cumin et le reste du curcuma avec 3 c. à soupe d''eau et faire revenir 2 min, jusqu''à ce que l''huile commence à se séparer.","Verser le lait de coco et 150 ml d''eau, ajouter les haricots verts et laisser frémir 6 min, jusqu''à ce qu''ils soient juste tendres.","Ajouter les crevettes et laisser frémir 3 à 4 min, jusqu''à ce qu''elles soient roses et cuites.","Assaisonner avec le jus d''un demi-citron vert, le vinaigre, le sucre et du sel à goût ; la sauce doit être acidulée. Servir avec le riz, la coriandre et le reste du citron vert en quartiers."]},"it":{"title":"Curry di gamberi di Goa al cocco con fagiolini","steps":["Condire i gamberi con 0,25 cucchiaini di curcuma e un pizzico di sale.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Cuocere la cipolla in 2 cucchiai d''olio in una padella larga a fuoco medio, 6-7 min, finché è morbida e leggermente dorata. Aggiungere aglio e zenzero e cuocere 1 min.","Unire paprika, peperoncino, coriandolo in polvere, cumino e la curcuma rimasta con 3 cucchiai d''acqua e soffriggere 2 min, finché l''olio comincia a separarsi.","Versare il latte di cocco e 150 ml d''acqua, aggiungere i fagiolini e cuocere 6 min, finché sono appena teneri.","Aggiungere i gamberi e cuocere 3-4 min, finché sono rosa e cotti.","Condire con il succo di mezzo lime, l''aceto, lo zucchero e sale a piacere; deve risultare acidulo. Servire con il riso, il coriandolo e il resto del lime a spicchi."]}}'::jsonb),
  ('a3ae4eef-b13b-417a-ab48-06aa0416f834'::uuid, '{"fr":{"title":"Palak paneer et riz","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Faire tomber les épinards avec le piment et les noix de cajou dans 1 c. à soupe d''huile dans une grande poêle à feu moyen, 3 min, juste le temps qu''ils réduisent. Laisser tiédir, puis mixer avec 4 c. à soupe d''eau en une purée lisse.","Faire fondre le beurre dans la même poêle, ajouter les graines de cumin 30 s, puis l''oignon et faire revenir 8 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates et une pincée de sel et cuire 5 min jusqu''à ce qu''elles soient fondantes.","Incorporer le garam masala et la coriandre moulue 1 min, ajouter 150 ml d''eau, couvrir et cuire 5 min.","Baisser le feu, incorporer la purée d''épinards et porter juste à frémissement, 2 à 3 min ; ne pas faire bouillir fort pour qu''elle reste bien verte.","Ajouter délicatement le paneer et chauffer 2 min, puis incorporer la crème. Servir avec le riz."]},"it":{"title":"Palak paneer con riso","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Far appassire gli spinaci con il peperoncino e gli anacardi in 1 cucchiaio d''olio in una padella grande a fuoco medio, 3 min, solo finché si afflosciano. Far intiepidire, poi frullare con 4 cucchiai d''acqua fino a ottenere una purea liscia.","Sciogliere il burro nella stessa padella, aggiungere i semi di cumino per 30 s, poi la cipolla e soffriggere 8 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori e un pizzico di sale e cuocere 5 min finché sono morbidi e densi.","Unire garam masala e coriandolo in polvere per 1 min, aggiungere 150 ml d''acqua, coprire e cuocere 5 min.","Abbassare il fuoco, unire la purea di spinaci e portare appena a bollore, 2-3 min; non far bollire forte o perderà il colore.","Aggiungere delicatamente il paneer e scaldare 2 min, poi incorporare la panna. Servire con il riso."]}}'::jsonb),
  ('4c3bafea-b644-4721-b329-1da8f0824459'::uuid, '{"fr":{"title":"Keema aloo (bœuf haché et pommes de terre)","steps":["Chauffer 2 c. à soupe d''huile dans une sauteuse à fond épais avec couvercle à feu moyen, ajouter les graines de cumin, le laurier, la cannelle et les clous de girofle et faire revenir 1 min, jusqu''à ce qu''ils embaument.","Ajouter l''oignon et cuire 6 à 8 min jusqu''à ce qu''il soit doré, puis l''ail et le gingembre 1 min.","Ajouter le bœuf et cuire à feu moyen-vif 6 à 8 min en l''émiettant, jusqu''à ce qu''il soit doré et que son jus se soit évaporé.","Incorporer la coriandre moulue, le cumin moulu, le curcuma, le piment et 1 c. à café de sel 2 min, puis ajouter les tomates et les pommes de terre.","Verser 200 ml d''eau, couvrir et laisser mijoter à feu doux 20 min en remuant de temps en temps, jusqu''à ce que les pommes de terre soient tendres et que l''huile remonte en surface.","Ajouter les petits pois et le garam masala et cuire encore 3 min à découvert, jusqu''à ce que la sauce nappe la viande.","Finir avec le jus de citron et la coriandre et servir avec du pain plat chaud."]},"it":{"title":"Keema aloo (macinato di manzo e patate)","steps":["Scaldare 2 cucchiai d''olio in una padella dal fondo spesso con coperchio a fuoco medio, aggiungere i semi di cumino, l''alloro, la cannella e i chiodi di garofano e soffriggere 1 min, finché profumano.","Aggiungere la cipolla e cuocere 6-8 min finché è dorata, poi aglio e zenzero per 1 min.","Aggiungere il manzo e cuocere a fuoco medio-alto 6-8 min sgranandolo, finché è rosolato e il liquido è evaporato.","Unire coriandolo in polvere, cumino in polvere, curcuma, peperoncino e 1 cucchiaino di sale per 2 min, poi aggiungere i pomodori e le patate.","Versare 200 ml d''acqua, coprire e cuocere a fuoco basso 20 min mescolando ogni tanto, finché le patate sono tenere e l''olio affiora in superficie.","Aggiungere i piselli e il garam masala e cuocere ancora 3 min scoperto, finché il sugo avvolge la carne.","Completare con il succo di limone e il coriandolo e servire con pane piatto caldo."]}}'::jsonb),
  ('8213da9d-3b1b-46a3-b4b2-70bfcbbfc392'::uuid, '{"fr":{"title":"Saag gosht (agneau aux épinards) et riz basmati","steps":["Faire dorer l''agneau dans 1 c. à soupe d''huile dans une cocotte à feu moyen-vif, en deux fois, 5 min, puis le réserver.","Mettre le beurre, les graines de cumin et le laurier dans la cocotte 30 s, puis l''oignon, et cuire 8 à 10 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates, le curcuma, la coriandre moulue, le cumin moulu et le piment, et cuire 8 min jusqu''à ce que le mélange épaississe et que la matière grasse se sépare ; ajouter un peu d''eau si cela attache.","Remettre l''agneau avec 300 ml d''eau et 1 c. à café de sel, couvrir et laisser mijoter doucement 50 min.","Fouetter le yaourt et l''incorporer hors ébullition, puis ajouter les épinards par poignées et les laisser tomber. Couvrir et laisser mijoter encore 15 min, jusqu''à ce que l''agneau soit tendre et la sauce épaisse et verte.","Pendant ce temps, rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Incorporer le garam masala au curry, rectifier le sel et servir avec le riz."]},"it":{"title":"Saag gosht (agnello agli spinaci) con riso basmati","steps":["Rosolare l''agnello in 1 cucchiaio d''olio in una pentola dal fondo spesso con coperchio a fuoco medio-alto, in due volte, 5 min, poi metterlo da parte.","Mettere nella pentola il burro, i semi di cumino e l''alloro per 30 s, poi la cipolla, e cuocere 8-10 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori, la curcuma, il coriandolo in polvere, il cumino in polvere e il peperoncino, e cuocere 8 min finché il fondo è denso e il grasso si separa; aggiungere un goccio d''acqua se attacca.","Rimettere l''agnello con 300 ml d''acqua e 1 cucchiaino di sale, coprire e cuocere a fuoco dolce 50 min.","Sbattere lo yogurt e incorporarlo a fuoco spento, poi aggiungere gli spinaci una manciata alla volta e lasciarli appassire. Coprire e cuocere ancora 15 min, finché l''agnello è tenero e il sugo denso e verde.","Nel frattempo sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Unire il garam masala al curry, regolare di sale e servire con il riso."]}}'::jsonb),
  ('3ce76142-b963-43c3-be17-260ca39b916d'::uuid, '{"fr":{"title":"Brochettes de paneer tikka et riz au concombre","steps":["Mélanger le yaourt avec l''ail, le gingembre, le garam masala, le piment, le paprika, le cumin, le curcuma, le jus d''un demi-citron, 1 c. à soupe d''huile et 0,5 c. à café de sel. Y enrober le paneer, le poivron et l''oignon et laisser 30 min au réfrigérateur.","Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu, puis l''étaler pour qu''il tiédisse.","Allumer le gril du four à puissance maximale (ou le four à 230 °C). Enfiler le paneer, le poivron et l''oignon sur des brochettes et les poser sur une plaque huilée.","Griller 12 à 15 min en retournant une fois, jusqu''à ce que le paneer soit grillé sur les bords et les légumes tendres.","Incorporer le concombre, la menthe, un filet de citron et une pincée de sel au riz tiède.","Servir les brochettes sur le riz au concombre avec le reste du citron en quartiers."]},"it":{"title":"Spiedini di paneer tikka con riso al cetriolo","steps":["Mescolare lo yogurt con aglio, zenzero, garam masala, peperoncino, paprika, cumino, curcuma, il succo di mezzo limone, 1 cucchiaio d''olio e 0,5 cucchiaini di sale. Unire paneer, peperone e cipolla e lasciare in frigorifero 30 min.","Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco, poi allargarlo perché intiepidisca.","Accendere il grill del forno al massimo (o il forno a 230 °C). Infilare paneer, peperone e cipolla negli spiedini e disporli su una teglia unta.","Grigliare 12-15 min girando una volta, finché il paneer è abbrustolito ai bordi e le verdure tenere.","Unire al riso tiepido il cetriolo, la menta, una spruzzata di limone e un pizzico di sale.","Servire gli spiedini sul riso al cetriolo con il resto del limone a spicchi."]}}'::jsonb),
  ('0f1721fb-aa3a-4130-b668-700a02491983'::uuid, '{"fr":{"title":"Rajma chawal (curry de haricots rouges et riz)","steps":["Chauffer le beurre avec 1 c. à soupe d''huile dans une casserole à feu moyen, ajouter les graines de cumin et le laurier 30 s, puis l''oignon, et cuire 5 à 6 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates, et cuire 3 à 4 min jusqu''à ce que l''odeur de cru disparaisse.","Incorporer le piment, la coriandre moulue, le cumin moulu, le curcuma, la moitié du garam masala et 1 c. à café de sel et cuire 3 min jusqu''à ce que la base épaississe et brille d''huile.","Ajouter les haricots et 300 ml d''eau chaude et laisser mijoter 20 min, en écrasant quelques haricots contre la paroi pour épaissir la sauce.","Pendant ce temps, rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; laisser reposer 5 min hors du feu.","Incorporer le reste du garam masala et le jus de citron au rajma, parsemer de coriandre et servir sur le riz avec le yaourt à côté."]},"it":{"title":"Rajma chawal (curry di fagioli rossi con riso)","steps":["Scaldare il burro con 1 cucchiaio d''olio in una casseruola a fuoco medio, aggiungere i semi di cumino e l''alloro per 30 s, poi la cipolla, e cuocere 5-6 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori, e cuocere 3-4 min finché sparisce l''odore di crudo.","Unire peperoncino, coriandolo in polvere, cumino in polvere, curcuma, metà del garam masala e 1 cucchiaino di sale e cuocere 3 min finché il fondo si addensa e diventa lucido d''olio.","Aggiungere i fagioli e 300 ml d''acqua calda e cuocere 20 min, schiacciando qualche fagiolo contro la parete per addensare il sugo.","Nel frattempo sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Unire al rajma il garam masala rimasto e il succo di limone, cospargere di coriandolo e servire sul riso con lo yogurt a parte."]}}'::jsonb),
  ('db823cde-4d7a-4643-83ef-da6dc18ff628'::uuid, '{"fr":{"title":"Poulet jalfrezi","steps":["Rincer le riz et le cuire dans 240 ml d''eau salée, à couvert et à feu doux, 12 min ; le laisser reposer hors du feu jusqu''au service.","Mélanger le poulet avec le jus de citron, une pincée de piment en poudre et du sel.","Faire sauter les poivrons, les morceaux d''oignon et le piment dans 1 c. à soupe d''huile dans une grande poêle à feu vif, 3 min, jusqu''à ce qu''ils soient grillés sur les bords mais encore croquants ; les réserver sur une assiette.","Ajouter 1 c. à soupe d''huile et l''oignon haché dans la poêle et faire revenir à feu moyen-vif 4 min, puis ajouter l''ail et le gingembre 1 min.","Ajouter le poulet et le faire sauter 3 min jusqu''à ce qu''il blanchisse, puis le reste du piment en poudre, le garam masala, la coriandre moulue, le cumin et le curcuma 30 s.","Verser les tomates avec 3 c. à soupe d''eau et cuire 5 à 6 min en remuant, jusqu''à ce que le poulet soit cuit et la sauce épaisse et nappante.","Remettre les poivrons et l''oignon, faire sauter 1 min pour les réchauffer, rectifier le sel et servir avec le riz et la coriandre."]},"it":{"title":"Pollo jalfrezi","steps":["Sciacquare il riso e cuocerlo in 240 ml d''acqua salata, coperto, a fuoco basso per 12 min; lasciarlo riposare fuori dal fuoco fino al momento di servire.","Condire il pollo con il succo di limone, un pizzico di peperoncino in polvere e sale.","Saltare i peperoni, i pezzi di cipolla e il peperoncino in 1 cucchiaio d''olio in una padella grande a fuoco vivo, 3 min, finché sono abbrustoliti ai bordi ma ancora croccanti; metterli da parte su un piatto.","Aggiungere 1 cucchiaio d''olio e la cipolla tritata nella padella e soffriggere a fuoco medio-alto 4 min, poi aggiungere aglio e zenzero per 1 min.","Aggiungere il pollo e saltarlo 3 min finché diventa chiaro, poi il resto del peperoncino in polvere, il garam masala, il coriandolo in polvere, il cumino e la curcuma per 30 s.","Versare i pomodori con 3 cucchiai d''acqua e cuocere 5-6 min mescolando, finché il pollo è cotto e il sugo denso e avvolgente.","Rimettere i peperoni e la cipolla, saltare 1 min per scaldarli, regolare di sale e servire con il riso e il coriandolo."]}}'::jsonb),
  ('442ff452-d938-4eab-96a9-6d100a2a00df'::uuid, '{"fr":{"title":"Anda curry (curry d''œufs)","steps":["Cuire les œufs 9 min dans l''eau frémissante, les refroidir dans l''eau froide et les écaler. Piquer chaque œuf 3 ou 4 fois avec une fourchette.","Rincer le riz, le mettre dans la même casserole avec 300 ml d''eau salée, couvrir et cuire 12 min à feu doux ; laisser reposer 5 min hors du feu.","Pendant ce temps, faire dorer les œufs dans le beurre avec une pincée de curcuma dans une sauteuse, 2 à 3 min, en les roulant jusqu''à ce qu''ils soient dorés et cloqués. Réserver.","Chauffer l''huile dans la même sauteuse, ajouter le laurier, la cannelle et la cardamome 30 s, puis les oignons ; cuire 8 à 10 min à feu moyen jusqu''à ce qu''ils soient dorés.","Ajouter l''ail et le gingembre 1 min, puis les tomates ; cuire 5 min jusqu''à obtenir une sauce épaisse.","Incorporer le piment en poudre, la coriandre en poudre, le garam masala, le reste du curcuma et du sel ; cuire 2 min jusqu''à ce que l''huile se sépare.","Verser 250 ml d''eau, couvrir et laisser mijoter 8 min jusqu''à ce que la sauce épaississe.","Ajouter les œufs et laisser mijoter 3 à 4 min pour qu''ils prennent le goût de la sauce ; incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Anda curry (curry di uova)","steps":["Cuocere le uova 9 min in acqua che sobbolle, raffreddarle in acqua fredda e sgusciarle. Bucherellare ogni uovo 3-4 volte con una forchetta.","Sciacquare il riso, metterlo nella stessa pentola con 300 ml di acqua salata, coprire e cuocere 12 min a fuoco basso; lasciare riposare 5 min fuori dal fuoco.","Nel frattempo, rosolare le uova nel burro con un pizzico di curcuma in una padella larga, 2-3 min, girandole finché sono dorate e con qualche bolla. Tenere da parte.","Scaldare l''olio nella stessa padella, aggiungere alloro, cannella e cardamomo per 30 s, poi le cipolle; cuocere 8-10 min a fuoco medio finché sono dorate.","Aggiungere aglio e zenzero per 1 min, poi i pomodori; cuocere 5 min finché il sugo è denso.","Unire il peperoncino in polvere, il coriandolo macinato, il garam masala, il resto della curcuma e il sale; cuocere 2 min finché l''olio si separa.","Versare 250 ml di acqua, coprire e cuocere a fuoco lento 8 min finché il sugo si addensa.","Aggiungere le uova e cuocere 3-4 min perché prendano il sapore del sugo; unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('1ab9739c-acbe-4eba-9ade-d3384a505962'::uuid, '{"fr":{"title":"Rogan josh (agneau braisé du Cachemire)","steps":["Faire dorer l''oignon dans 1 c. à soupe d''huile dans une cocotte à fond épais, à feu moyen, 8 à 10 min. Le retirer sur une assiette.","Ajouter le reste de l''huile, puis le laurier, la cardamome, les clous de girofle et la cannelle ; laisser grésiller 30 s.","Ajouter l''agneau, le saisir 2 min à feu vif, puis le cuire 5 min à feu moyen jusqu''à ce qu''il soit légèrement doré.","Fouetter le yaourt avec le paprika, le piment en poudre, le fenouil moulu, le gingembre et le sel. Retirer la cocotte du feu et incorporer le yaourt cuillerée par cuillerée pour qu''il ne tranche pas.","Remettre à feu moyen, couvrir et cuire 4 min, puis ajouter 250 ml d''eau chaude. Couvrir et laisser mijoter à feu doux 1 h 30 à 1 h 45, en remuant toutes les 15 min et en ajoutant un peu d''eau chaude si nécessaire, jusqu''à ce que l''agneau soit très tendre.","Pendant les 20 dernières minutes, incorporer l''oignon frit et le garam masala.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Quand la sauce est épaisse et qu''une huile rouge apparaît en surface, rectifier le sel et servir avec le riz."]},"it":{"title":"Rogan josh (agnello brasato del Kashmir)","steps":["Rosolare la cipolla in 1 cucchiaio d''olio in una pentola dal fondo spesso a fuoco medio, 8-10 min, finché è ben dorata. Toglierla e metterla su un piatto.","Aggiungere il resto dell''olio, poi alloro, cardamomo, chiodi di garofano e cannella; lasciarli sfrigolare 30 s.","Aggiungere l''agnello, scottarlo 2 min a fuoco vivo, poi cuocerlo 5 min a fuoco medio finché è leggermente dorato.","Sbattere lo yogurt con paprika, peperoncino in polvere, finocchio macinato, zenzero e sale. Togliere la pentola dal fuoco e incorporare lo yogurt un cucchiaio alla volta perché non impazzisca.","Rimettere a fuoco medio, coprire e cuocere 4 min, poi aggiungere 250 ml di acqua calda. Coprire e cuocere a fuoco basso 1 h 30-1 h 45, mescolando ogni 15 min e aggiungendo un goccio di acqua calda se si asciuga, finché l''agnello è molto tenero.","Negli ultimi 20 min, unire la cipolla rosolata e il garam masala.","Nel frattempo, sciacquare il riso e cuocerlo coperto in 300 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Quando il sugo è denso e in superficie compare un olio rosso, regolare di sale e servire con il riso."]}}'::jsonb),
  ('aff85e70-95e3-4537-a252-0b668f27c213'::uuid, '{"fr":{"title":"Biryani au poulet","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, le couvrir d''eau et le laisser tremper 30 min ; égoutter.","Pendant ce temps, faire frire les oignons dans l''huile dans une cocotte à fond épais à feu moyen, 12 à 15 min, jusqu''à ce qu''ils soient bien dorés. En réserver un tiers pour le dessus.","Ajouter le laurier, la cannelle, la cardamome et les clous de girofle 30 s, puis l''ail et le gingembre 1 min.","Ajouter le poulet et le cuire 3 min jusqu''à ce qu''il blanchisse, puis assaisonner de sel, garam masala, piment en poudre et curcuma et faire revenir encore 3 min.","Incorporer le yaourt, couvrir et cuire 15 à 20 min à feu moyen-doux jusqu''à ce que le poulet soit tendre et la sauce épaisse, pas liquide.","Pendant ce temps, porter à ébullition 2 l d''eau salée avec le cumin, ajouter le riz et le cuire 5 à 6 min jusqu''à ce qu''il soit cuit à 90 %, encore ferme au centre ; égoutter. Faire infuser le safran dans le lait tiède.","Parsemer le poulet de menthe et de coriandre, étaler le riz par-dessus, puis ajouter les oignons réservés, le lait au safran et le beurre fondu.","Fermer hermétiquement la cocotte avec du papier aluminium et le couvercle et cuire 15 min sur le feu le plus doux. Laisser reposer 10 min hors du feu avant d''ouvrir, puis mélanger délicatement et servir."]},"it":{"title":"Biryani di pollo","steps":["Sciacquare il riso finché l''acqua è limpida, coprirlo d''acqua e lasciarlo in ammollo 30 min; scolare.","Nel frattempo, friggere le cipolle nell''olio in una pentola dal fondo spesso a fuoco medio, 12-15 min, finché sono ben dorate. Tenerne da parte un terzo per la copertura.","Aggiungere alloro, cannella, cardamomo e chiodi di garofano per 30 s, poi aglio e zenzero per 1 min.","Aggiungere il pollo e cuocerlo 3 min finché diventa chiaro, poi condire con sale, garam masala, peperoncino in polvere e curcuma e rosolare altri 3 min.","Unire lo yogurt, coprire e cuocere 15-20 min a fuoco medio-basso finché il pollo è tenero e il sugo denso, non acquoso.","Nel frattempo, portare a ebollizione 2 l di acqua salata con il cumino, aggiungere il riso e bollirlo 5-6 min finché è cotto al 90%, ancora sodo al centro; scolare. Mettere in infusione lo zafferano nel latte tiepido.","Cospargere il pollo di menta e coriandolo, stendere sopra il riso, poi aggiungere le cipolle tenute da parte, il latte allo zafferano e il burro fuso.","Sigillare la pentola con carta stagnola e coperchio e cuocere 15 min sul fuoco più basso. Lasciare riposare 10 min fuori dal fuoco prima di aprire, poi mescolare delicatamente e servire."]}}'::jsonb),
  ('8cf5200c-38b4-4aa5-aa57-44228ae164ec'::uuid, '{"fr":{"title":"Matar paneer (paneer aux petits pois)","steps":["Rincer le riz et le cuire à couvert dans 250 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Faire dorer le paneer dans la moitié du beurre dans une poêle, 1 à 2 min de chaque côté. Réserver.","Ajouter l''huile et le reste du beurre, le cumin 30 s, puis l''oignon ; cuire 5 min jusqu''à ce qu''il soit légèrement doré.","Ajouter l''ail et le gingembre 1 min, puis le curcuma, le piment en poudre et la coriandre en poudre 30 s.","Verser le coulis de tomate avec un peu de sel et cuire 4 min en remuant, jusqu''à ce qu''il épaississe et que l''huile se sépare.","Ajouter les petits pois et 150 ml d''eau et laisser mijoter 5 min.","Ajouter le paneer et le garam masala et laisser mijoter 2 min. Incorporer la crème, parsemer de coriandre et servir avec le riz."]},"it":{"title":"Matar paneer (paneer con piselli)","steps":["Sciacquare il riso e cuocerlo coperto in 250 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Dorare il paneer in metà del burro in una padella, 1-2 min per lato. Tenere da parte.","Aggiungere l''olio e il resto del burro, il cumino per 30 s, poi la cipolla; cuocere 5 min finché è leggermente dorata.","Aggiungere aglio e zenzero per 1 min, poi curcuma, peperoncino in polvere e coriandolo macinato per 30 s.","Versare la passata con un po'' di sale e cuocere 4 min mescolando, finché si addensa e l''olio si separa.","Aggiungere i piselli e 150 ml di acqua e cuocere a fuoco lento 5 min.","Aggiungere il paneer e il garam masala e cuocere 2 min. Unire la panna, cospargere di coriandolo e servire con il riso."]}}'::jsonb),
  ('aba8ad6d-ca4c-4d94-a688-3adb95587555'::uuid, '{"fr":{"title":"Crevettes masala","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau salée, 12 min à feu doux ; laisser reposer 5 min.","Mélanger les crevettes avec une pincée de curcuma, de piment en poudre et de sel et les laisser reposer pendant que vous commencez la sauce.","Chauffer l''huile dans une sauteuse, ajouter le cumin 30 s, puis l''oignon ; cuire 6 à 7 min jusqu''à ce qu''il soit doré.","Ajouter l''ail et le gingembre 1 min, puis les tomates et un peu de sel ; cuire 6 min jusqu''à ce qu''elles soient fondues et épaisses.","Incorporer le reste du curcuma, le paprika, le piment en poudre, la coriandre en poudre et le garam masala ; cuire 1 à 2 min jusqu''à ce que l''huile se sépare.","Ajouter le lait de coco et 100 ml d''eau et laisser mijoter 4 à 5 min pour obtenir une sauce épaisse mais nappante.","Baisser le feu, ajouter les crevettes et cuire 3 à 4 min, juste jusqu''à ce qu''elles soient roses et recourbées en C. Ajouter un filet de citron et la coriandre et servir avec le riz."]},"it":{"title":"Gamberi masala","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua salata, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare i gamberi con un pizzico di curcuma, peperoncino in polvere e sale e lasciarli riposare mentre si prepara il sugo.","Scaldare l''olio in una padella, aggiungere il cumino per 30 s, poi la cipolla; cuocere 6-7 min finché è dorata.","Aggiungere aglio e zenzero per 1 min, poi i pomodori e un po'' di sale; cuocere 6 min finché sono disfatti e densi.","Unire il resto della curcuma, paprika, peperoncino in polvere, coriandolo macinato e garam masala; cuocere 1-2 min finché l''olio si separa.","Aggiungere il latte di cocco e 100 ml di acqua e cuocere a fuoco lento 4-5 min fino a ottenere un sugo denso ma fluido.","Abbassare il fuoco, aggiungere i gamberi e cuocere 3-4 min, finché diventano rosa e si piegano a C. Aggiungere una spruzzata di limone e il coriandolo e servire con il riso."]}}'::jsonb),
  ('24505ac8-cfec-4400-bede-ce4bae130d8a'::uuid, '{"fr":{"title":"Sauté de porc au chou et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger le porc avec le xérès, 1 c. à soupe de sauce soja et 1 c. à café de fécule ; laisser reposer 10 min.","Mélanger le reste de la sauce soja avec le sucre et le vinaigre. Délayer le reste de la fécule dans 1 c. à soupe d''eau.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif, étaler le porc en une couche, laisser 1 min, puis faire sauter encore 1 min jusqu''à ce qu''il soit juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail et le gingembre et remuer 20 s jusqu''à ce qu''ils embaument.","Ajouter le chou et le faire sauter 3 à 4 min jusqu''à ce qu''il soit à peine tendre mais encore croquant.","Verser la sauce, remettre le porc, ajouter la fécule délayée et remuer 1 min jusqu''à ce que ce soit brillant. Assaisonner de sel et de piment et servir sur le riz."]},"it":{"title":"Maiale saltato con cavolo e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare il maiale con lo sherry, 1 cucchiaio di salsa di soia e 1 cucchiaino di amido; lasciare riposare 10 min.","Mescolare il resto della salsa di soia con zucchero e aceto. Stemperare l''amido rimasto in 1 cucchiaio di acqua.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo, stendere il maiale in un solo strato, lasciarlo 1 min, poi saltarlo ancora 1 min finché è appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio e zenzero e mescolare 20 s finché profumano.","Aggiungere il cavolo e saltarlo 3-4 min finché è appena tenero ma ancora croccante.","Versare la salsa, rimettere il maiale, aggiungere l''amido stemperato e mescolare 1 min finché è lucido. Condire con sale e peperoncino e servire sul riso."]}}'::jsonb),
  ('8374c9b3-57b9-4cc7-be98-c4ae66518e2a'::uuid, '{"fr":{"title":"Bouchées de laitue au bœuf gingembre et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Chauffer l''huile dans une grande poêle à feu vif et faire dorer le bœuf en l''émiettant, 5 à 6 min, jusqu''à ce qu''il soit bien caramélisé. Réserver.","Dans la même poêle, faire revenir l''oignon, le poivron, la carotte, l''ail et le gingembre 3 à 4 min jusqu''à ce qu''ils soient tendres.","Remettre le bœuf, ajouter la sauce d''huître, la sauce hoisin, la sauce soja et le bouillon et faire sauter 3 à 4 min jusqu''à ce que le liquide soit absorbé et la viande sèche et laquée.","Incorporer l''huile de sésame et retirer du feu.","Garnir les feuilles de laitue de bœuf, parsemer d''oignon nouveau, de cacahuètes et de piment et servir avec le riz."]},"it":{"title":"Coppette di lattuga con manzo allo zenzero e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Scaldare l''olio in una padella grande a fuoco vivo e rosolare il manzo sbriciolandolo, 5-6 min, finché è ben caramellato ai bordi. Tenere da parte.","Nella stessa padella, cuocere cipolla, peperone, carota, aglio e zenzero 3-4 min finché si ammorbidiscono.","Rimettere il manzo, aggiungere salsa di ostriche, salsa hoisin, salsa di soia e brodo e saltare 3-4 min finché il liquido è evaporato e la carne è asciutta e glassata.","Unire l''olio di sesamo e togliere dal fuoco.","Distribuire il manzo nelle foglie di lattuga, completare con cipollotto, arachidi e peperoncino e servire con il riso."]}}'::jsonb),
  ('feea91a4-24a0-4ece-adb4-46b6944cafcc'::uuid, '{"fr":{"title":"Riz sauté au poulet et aux légumes","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux. L''étaler sur un plateau et le laisser refroidir complètement, au moins 30 min (ou le cuire la veille et le réfrigérer).","Mélanger le poulet avec 1 c. à café de sauce soja, la fécule et l''huile de sésame. Mélanger le reste de la sauce soja avec le sucre, une pincée de sel, du poivre et 1 c. à soupe d''eau chaude.","Chauffer 1 c. à soupe d''huile dans un wok à feu moyen-vif, brouiller les œufs jusqu''à ce qu''ils soient juste pris et les retirer.","Ajouter 1 c. à soupe d''huile, saisir le poulet en une couche à feu vif et le faire sauter 3 à 4 min jusqu''à ce qu''il soit cuit. Réserver.","Ajouter le reste de l''huile, faire sauter l''oignon et la carotte 3 min, puis les petits pois 1 min.","Ajouter le riz froid en défaisant les grumeaux et faire sauter 4 à 5 min jusqu''à ce qu''il soit chaud et les grains bien séparés.","Verser la sauce et mélanger jusqu''à coloration uniforme, puis ajouter le poulet, les œufs, les germes de soja et l''oignon nouveau et faire sauter 1 min.","Verser le xérès en filet sur les bords chauds du wok, mélanger 20 s et servir."]},"it":{"title":"Riso saltato con pollo e verdure","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso. Stenderlo su un vassoio e lasciarlo raffreddare completamente, almeno 30 min (oppure cuocerlo il giorno prima e metterlo in frigo).","Mescolare il pollo con 1 cucchiaino di salsa di soia, l''amido e l''olio di sesamo. Mescolare il resto della salsa di soia con zucchero, un pizzico di sale, pepe e 1 cucchiaio di acqua calda.","Scaldare 1 cucchiaio d''olio in un wok a fuoco medio-alto, strapazzare le uova finché sono appena rapprese e toglierle.","Aggiungere 1 cucchiaio d''olio, scottare il pollo in un solo strato a fuoco vivo e saltarlo 3-4 min finché è cotto. Tenere da parte.","Aggiungere il resto dell''olio, saltare cipolla e carota 3 min, poi i piselli 1 min.","Aggiungere il riso freddo sgranando i grumi e saltarlo 4-5 min finché è caldo e i chicchi sono separati.","Versare la salsa e mescolare finché il colore è uniforme, poi aggiungere pollo, uova, germogli di soia e cipollotto e saltare 1 min.","Versare lo sherry lungo i bordi caldi del wok, mescolare 20 s e servire."]}}'::jsonb),
  ('aa00c4b7-db7b-4b8a-8ea5-5637a1fb4bdf'::uuid, '{"fr":{"title":"Boulettes de porc, bouillon au gingembre et nouilles","steps":["Porter le bouillon à ébullition avec les bâtonnets de gingembre et l''ail écrasé, puis laisser frémir 10 min.","Pendant ce temps, mélanger le porc avec le blanc des oignons nouveaux, le gingembre râpé, l''ail râpé, 1 c. à soupe de sauce soja, le xérès, l''huile de sésame, la fécule, 2 c. à soupe d''eau et du poivre. Travailler 1 min jusqu''à ce que la farce soit collante.","Avec les mains mouillées, former environ 14 boulettes de la taille d''une noix.","Plonger les boulettes et la carotte dans le bouillon frémissant et les pocher 8 min sans faire bouillir fort.","Pendant ce temps, cuire les nouilles dans l''eau bouillante selon le paquet, les égoutter et les répartir dans deux bols.","Ajouter le pak-choï au bouillon et laisser frémir 3 à 4 min jusqu''à ce qu''il soit tendre et que les boulettes soient cuites à cœur, sans rose à l''intérieur.","Assaisonner le bouillon avec le reste de la sauce soja, le vinaigre et le sucre, le verser sur les nouilles et parsemer du vert des oignons nouveaux et de piment."]},"it":{"title":"Polpette di maiale in brodo allo zenzero con noodles","steps":["Portare a ebollizione il brodo con i bastoncini di zenzero e l''aglio schiacciato, poi far sobbollire 10 min.","Nel frattempo, mescolare il maiale con la parte bianca dei cipollotti, lo zenzero grattugiato, l''aglio grattugiato, 1 cucchiaio di salsa di soia, lo sherry, l''olio di sesamo, l''amido, 2 cucchiai di acqua e pepe. Lavorare 1 min finché l''impasto è appiccicoso.","Con le mani bagnate, formare circa 14 polpette grandi come una noce.","Immergere le polpette e la carota nel brodo che sobbolle e cuocerle 8 min senza far bollire forte.","Nel frattempo, cuocere i noodles in acqua bollente come indicato sulla confezione, scolarli e dividerli in due ciotole.","Aggiungere il pak choi al brodo e cuocere 3-4 min finché è tenero e le polpette sono cotte all''interno, senza parti rosa.","Condire il brodo con il resto della salsa di soia, l''aceto e lo zucchero, versarlo sui noodles e completare con la parte verde dei cipollotti e il peperoncino."]}}'::jsonb),
  ('03b4b489-6e9f-4433-8687-bbb43c7193ee'::uuid, '{"fr":{"title":"Raviolis grillés aux champignons et au chou","steps":["Mélanger la farine et le sel avec 120 ml d''eau tiède, pétrir 5 min jusqu''à obtenir une pâte lisse, couvrir et laisser reposer 30 min.","Mélanger le chou avec 0,5 c. à café de sel, laisser 10 min, puis le presser pour en extraire le plus d''eau possible.","Brouiller doucement les œufs dans 1 c. à café d''huile dans la poêle, puis les hacher finement.","Faire revenir les champignons et la carotte dans 1 c. à soupe d''huile 5 à 6 min jusqu''à ce qu''ils soient secs, ajouter l''ail et le gingembre 1 min et laisser refroidir.","Mélanger le tofu, le chou, les champignons, les œufs, l''oignon nouveau, 1 c. à soupe de sauce soja, l''huile de sésame et la fécule pour obtenir une farce ferme.","Couper la pâte en 24 morceaux, abaisser chacun en un disque fin de 8 cm et le fariner de fécule.","Déposer une bonne cuillerée à soupe de farce au centre de chaque disque, plier en deux et plisser les bords pour souder.","Cuire en trois fois : chauffer 1 c. à soupe d''huile dans une poêle antiadhésive avec couvercle, faire dorer les raviolis 3 à 4 min, ajouter 60 ml d''eau, couvrir et cuire à la vapeur 5 à 6 min jusqu''à évaporation, puis découvrir et laisser croustiller 1 min.","Mélanger le reste de la sauce soja avec le vinaigre et le piment et servir comme sauce."]},"it":{"title":"Ravioli cinesi alla piastra con funghi e cavolo","steps":["Mescolare farina e sale con 120 ml di acqua tiepida, impastare 5 min fino a ottenere un impasto liscio, coprire e lasciare riposare 30 min.","Mescolare il cavolo con mezzo cucchiaino di sale, lasciare 10 min, poi strizzarlo per eliminare più acqua possibile.","Strapazzare dolcemente le uova in 1 cucchiaino d''olio nella padella, poi tritarle finemente.","Rosolare funghi e carota in 1 cucchiaio d''olio 5-6 min finché sono asciutti, aggiungere aglio e zenzero per 1 min e lasciare raffreddare.","Mescolare tofu, cavolo, funghi, uova, cipollotto, 1 cucchiaio di salsa di soia, olio di sesamo e amido fino a ottenere un ripieno compatto.","Dividere l''impasto in 24 pezzi, stendere ciascuno in un disco sottile di 8 cm e spolverarlo di amido.","Mettere un cucchiaio abbondante di ripieno al centro di ogni disco, piegarlo a metà e pieghettare i bordi per sigillarlo.","Cuocere in tre volte: scaldare 1 cucchiaio d''olio in una padella antiaderente con coperchio, rosolare i ravioli 3-4 min finché la base è dorata, aggiungere 60 ml di acqua, coprire e cuocere al vapore 5-6 min finché l''acqua è evaporata, poi scoprire e far croccare 1 min.","Mescolare il resto della salsa di soia con l''aceto e il peperoncino e servire come salsa per intingere."]}}'::jsonb),
  ('97b513b6-d70b-4491-a7ad-f9277ee94a14'::uuid, '{"fr":{"title":"Soupe de nouilles au poulet et aux champignons","steps":["Faire dorer les champignons dans l''huile dans une grande casserole à feu vif, 5 à 6 min. Les retirer.","Verser le bouillon dans la casserole avec le gingembre, l''ail, la sauce soja et le xérès et porter à ébullition.","Ajouter le poulet, baisser le feu et le pocher à petits frémissements 15 à 18 min jusqu''à ce qu''il soit cuit à cœur, sans rose dans la partie la plus épaisse.","Retirer le poulet, le laisser reposer 5 min et l''effilocher avec deux fourchettes.","Pendant ce temps, cuire les nouilles dans le bouillon le temps indiqué sur le paquet, en ajoutant le pak-choï pour les 3 dernières minutes.","Répartir les nouilles, le pak-choï et le bouillon dans les bols, garnir de poulet et de champignons et finir avec l''huile de sésame, l''oignon nouveau et le piment."]},"it":{"title":"Zuppa di noodles con pollo e funghi","steps":["Rosolare i funghi nell''olio in una pentola grande a fuoco vivo, 5-6 min finché sono dorati. Toglierli.","Versare il brodo nella pentola con zenzero, aglio, salsa di soia e sherry e portare a ebollizione.","Aggiungere il pollo, abbassare il fuoco e cuocerlo a leggero sobbollore 15-18 min finché è cotto all''interno, senza parti rosa nel punto più spesso.","Togliere il pollo, lasciarlo riposare 5 min e sfilacciarlo con due forchette.","Nel frattempo, cuocere i noodles nel brodo per il tempo indicato sulla confezione, aggiungendo il pak choi negli ultimi 3 min.","Dividere noodles, pak choi e brodo nelle ciotole, completare con pollo e funghi e finire con olio di sesamo, cipollotto e peperoncino."]}}'::jsonb),
  ('d7790ac8-391f-4ae9-92b6-2274a94cb910'::uuid, '{"fr":{"title":"Nouilles sautées au porc hoisin et brocoli","steps":["Mélanger le porc avec 1 c. à soupe de sauce soja et la fécule ; laisser reposer 10 min.","Mélanger la sauce hoisin avec le reste de la sauce soja, le miel, le vinaigre, l''huile de sésame et le piment.","Cuire les nouilles dans l''eau bouillante selon le paquet, en ajoutant le brocoli pour les 2 dernières minutes. Garder 60 ml d''eau de cuisson, puis égoutter.","Chauffer 1 c. à soupe d''huile dans un wok à feu vif et saisir le porc en une couche 2 à 3 min, en le retournant une fois, jusqu''à ce qu''il soit doré et juste cuit. Réserver.","Ajouter le reste de l''huile, l''ail, le gingembre et la carotte et faire sauter 1 min.","Ajouter les nouilles, le brocoli, le porc, la sauce et un peu d''eau de cuisson et mélanger 1 à 2 min jusqu''à ce que ce soit brillant et chaud.","Servir parsemé de cacahuètes et d''oignon nouveau."]},"it":{"title":"Noodles saltati con maiale hoisin e broccoli","steps":["Mescolare il maiale con 1 cucchiaio di salsa di soia e l''amido; lasciare riposare 10 min.","Mescolare la salsa hoisin con il resto della salsa di soia, il miele, l''aceto, l''olio di sesamo e il peperoncino.","Cuocere i noodles in acqua bollente come indicato sulla confezione, aggiungendo i broccoli negli ultimi 2 min. Tenere da parte 60 ml di acqua di cottura, poi scolare.","Scaldare 1 cucchiaio d''olio in un wok a fuoco vivo e scottare il maiale in un solo strato 2-3 min, girandolo una volta, finché è dorato e appena cotto. Tenere da parte.","Aggiungere il resto dell''olio, aglio, zenzero e carota e saltare 1 min.","Aggiungere noodles, broccoli, maiale, salsa e un goccio di acqua di cottura e saltare 1-2 min finché è tutto lucido e caldo.","Servire con arachidi e cipollotto."]}}'::jsonb),
  ('261d4acf-50fc-4e1b-be3f-9558751ad743'::uuid, '{"fr":{"title":"Saumon au gingembre, pak-choï et nouilles","steps":["Mélanger la sauce soja, le gingembre, l''ail, le miel, l''huile de sésame et la sriracha. En verser les deux tiers sur le saumon et laisser 30 min au réfrigérateur.","Préchauffer le four à 220 °C (200 °C chaleur tournante).","Cuire le saumon sur une plaque recouverte de papier cuisson 12 à 14 min, jusqu''à ce qu''il s''effeuille facilement.","Pendant ce temps, cuire les nouilles selon le paquet et les égoutter.","Faire sauter le pak-choï et l''oignon nouveau dans l''huile au wok 3 min jusqu''à ce qu''ils soient juste tendres, puis ajouter les nouilles et mélanger.","Pousser les nouilles sur le côté, verser le reste de la marinade et le vinaigre dans le wok et laisser bouillonner 1 min.","Servir le saumon sur les nouilles, napper de sauce et parsemer de graines de sésame."]},"it":{"title":"Salmone allo zenzero con pak choi e noodles","steps":["Mescolare salsa di soia, zenzero, aglio, miele, olio di sesamo e sriracha. Versarne due terzi sul salmone e lasciarlo 30 min in frigo.","Preriscaldare il forno a 220 °C (200 °C ventilato).","Cuocere il salmone su una teglia foderata 12-14 min, finché si sfalda facilmente.","Nel frattempo, cuocere i noodles come indicato sulla confezione e scolarli.","Saltare il pak choi e il cipollotto nell''olio nel wok 3 min finché sono appena appassiti, poi unire i noodles e mescolare.","Spostare i noodles di lato, versare nel wok il resto della marinata e l''aceto e far bollire 1 min.","Servire il salmone sui noodles, irrorare con la salsa e cospargere di semi di sesamo."]}}'::jsonb),
  ('a0cb6512-daf4-4ea6-b97d-8730541d8c4f'::uuid, '{"fr":{"title":"Tofu croustillant sauce orange-gingembre et riz","steps":["Envelopper le tofu dans un torchon propre, poser une casserole lourde dessus et presser 20 min.","Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Couper le tofu en cubes de 2,5 cm, le mélanger avec 1 c. à soupe de sauce soja, puis avec 2 c. à soupe de fécule pour bien l''enrober.","Faire dorer le tofu dans l''huile à feu moyen-vif 8 à 10 min, en le retournant, jusqu''à ce qu''il soit croustillant sur toutes les faces. Réserver sur une grille.","Fouetter le jus et le zeste d''orange, le reste de la sauce soja, le vinaigre, le sucre, le piment et 3 c. à café de fécule.","Dans la même poêle, faire revenir le gingembre et l''ail 30 s, verser la sauce et laisser frémir 2 à 3 min en remuant, jusqu''à ce qu''elle soit épaisse et brillante.","Hors du feu, enrober le tofu de sauce et servir sur le riz avec l''oignon nouveau et les graines de sésame."]},"it":{"title":"Tofu croccante con salsa all''arancia e zenzero e riso","steps":["Avvolgere il tofu in un canovaccio pulito, appoggiarci sopra una pentola pesante e pressarlo 20 min.","Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Tagliare il tofu a cubetti di 2,5 cm, mescolarlo con 1 cucchiaio di salsa di soia, poi con 2 cucchiai di amido finché è ben rivestito.","Rosolare il tofu nell''olio a fuoco medio-alto 8-10 min, girandolo, finché è croccante e dorato su tutti i lati. Tenerlo da parte su una griglia.","Sbattere succo e scorza d''arancia, il resto della salsa di soia, aceto, zucchero, peperoncino e 3 cucchiaini di amido.","Nella stessa padella, cuocere zenzero e aglio 30 s, versare la salsa e cuocere 2-3 min mescolando, finché è densa e lucida.","Fuori dal fuoco, ripassare il tofu nella salsa e servirlo sul riso con cipollotto e semi di sesamo."]}}'::jsonb),
  ('cf5613cb-4635-4714-bf7b-da5b7ac6a5d9'::uuid, '{"fr":{"title":"Mapo tofu","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Torréfier le poivre du Sichuan à sec dans le wok 2 min jusqu''à ce qu''il embaume, le moudre finement et réserver.","Porter 600 ml d''eau salée à frémissement dans le wok, y glisser le tofu 3 min, puis le retirer délicatement et vider le wok.","Chauffer 1 c. à soupe d''huile à feu vif et faire revenir le bœuf 4 à 5 min jusqu''à ce qu''il soit doré et un peu croustillant ; ajouter 1 c. à café de sauce soja et réserver.","Baisser le feu, ajouter le reste de l''huile, l''ail et le gingembre 1 min 30, puis le miso 2 min en remuant, et le piment et le paprika 30 s, jusqu''à ce que l''huile devienne rouge.","Verser le bouillon et le reste de la sauce soja, porter à frémissement et y glisser le tofu. Laisser mijoter 8 à 10 min en poussant le tofu avec le dos d''une spatule plutôt que de remuer.","Ajouter le bœuf, le sucre et la moitié du poivre du Sichuan. Verser la fécule délayée dans 3 c. à soupe d''eau en surface et remuer délicatement jusqu''à ce que la sauce soit brillante et épaisse.","Incorporer l''oignon nouveau et l''huile de sésame, saupoudrer du reste de poivre du Sichuan et servir sur le riz."]},"it":{"title":"Mapo tofu","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Tostare il pepe di Sichuan nel wok asciutto 2 min finché profuma, macinarlo finemente e tenerlo da parte.","Portare a sobbollore 600 ml di acqua salata nel wok, immergere il tofu per 3 min, poi toglierlo delicatamente e svuotare il wok.","Scaldare 1 cucchiaio d''olio a fuoco vivo e rosolare il manzo 4-5 min finché è dorato e un po'' croccante; aggiungere 1 cucchiaino di salsa di soia e tenerlo da parte.","Abbassare il fuoco, aggiungere il resto dell''olio, aglio e zenzero per 90 s, poi il miso per 2 min mescolando, e peperoncino e paprika per 30 s, finché l''olio diventa rosso.","Versare il brodo e il resto della salsa di soia, portare a bollore e unire il tofu. Cuocere 8-10 min spingendo il tofu con il dorso di una spatola invece di mescolare.","Aggiungere il manzo, lo zucchero e metà del pepe di Sichuan. Versare sopra l''amido stemperato in 3 cucchiai di acqua e mescolare delicatamente finché la salsa è lucida e densa.","Unire cipollotto e olio di sesamo, cospargere con il resto del pepe di Sichuan e servire sul riso."]}}'::jsonb),
  ('c27f8d79-6a7d-40f6-b374-34634d94bd69'::uuid, '{"fr":{"title":"Hong shao rou (porc braisé rouge)","steps":["Cuire les œufs 8 min dans l''eau bouillante, les refroidir dans l''eau froide et les écaler.","Mettre le porc dans une cocotte à fond épais, couvrir d''eau froide, porter à ébullition et faire bouillir 2 min. Égoutter, rincer et essuyer la cocotte.","Faire fondre le sucre dans l''huile à feu doux 3 à 4 min jusqu''à obtenir un caramel ambré clair.","Ajouter le porc, passer à feu moyen et remuer 3 à 4 min jusqu''à ce qu''il soit enrobé et légèrement doré.","Ajouter le gingembre, l''oignon nouveau et l''anis étoilé, verser le xérès et cuire 1 min, puis ajouter la sauce soja et environ 400 ml d''eau chaude, de quoi presque couvrir.","Couvrir et laisser mijoter doucement 60 à 75 min, en remuant toutes les 10 à 15 min et en ajoutant de l''eau si nécessaire ; ajouter les œufs au bout de 30 min.","Pendant les 20 dernières minutes, rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Quand le porc est tendre à la fourchette, poser le pak-choï dessus, couvrir 4 min et le retirer. Découvrir, monter le feu et faire bouillir 5 à 8 min en remuant, jusqu''à ce que la sauce soit laquée et collante. Servir avec le riz et les légumes."]},"it":{"title":"Hong shao rou (maiale brasato rosso)","steps":["Cuocere le uova 8 min in acqua bollente, raffreddarle in acqua fredda e sgusciarle.","Mettere il maiale in una pentola dal fondo spesso, coprirlo con acqua fredda, portare a ebollizione e bollire 2 min. Scolare, sciacquare e asciugare la pentola.","Sciogliere lo zucchero nell''olio a fuoco basso 3-4 min fino a ottenere un caramello ambrato chiaro.","Aggiungere il maiale, alzare a fuoco medio e mescolare 3-4 min finché è ricoperto e leggermente dorato.","Aggiungere zenzero, cipollotto e anice stellato, versare lo sherry e cuocere 1 min, poi aggiungere la salsa di soia e circa 400 ml di acqua calda, quanto basta per coprire quasi del tutto.","Coprire e cuocere a fuoco dolce 60-75 min, mescolando ogni 10-15 min e aggiungendo acqua se si asciuga; aggiungere le uova dopo 30 min.","Negli ultimi 20 min, sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Quando il maiale è tenero alla forchetta, adagiarvi sopra il pak choi, coprire 4 min e toglierlo. Scoprire, alzare il fuoco e far bollire 5-8 min mescolando, finché la salsa diventa una glassa appiccicosa. Servire con il riso e le verdure."]}}'::jsonb),
  ('2e88837a-8303-4192-b86e-937e56874383'::uuid, '{"fr":{"title":"Œufs brouillés sautés à la tomate","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Battre les œufs avec le xérès, une pincée de sel et du poivre.","Mélanger le concentré de tomate, la fécule et le sucre avec 3 c. à soupe d''eau.","Chauffer 2 c. à soupe d''huile dans un wok à feu moyen-vif et brouiller les œufs 1 à 2 min jusqu''à ce qu''ils soient juste pris mais encore brillants. Les verser dans un bol.","Ajouter le reste de l''huile, les tomates et le blanc des oignons nouveaux avec une pincée de sel et cuire 3 min jusqu''à ce qu''elles soient tendres et juteuses mais encore entières.","Incorporer le mélange au concentré de tomate jusqu''à ce qu''il épaississe, remettre les œufs et mélanger délicatement 30 s.","Éteindre le feu, arroser d''huile de sésame, parsemer du vert des oignons nouveaux et servir sur le riz."]},"it":{"title":"Uova strapazzate saltate al pomodoro","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Sbattere le uova con lo sherry, un pizzico di sale e pepe.","Mescolare concentrato di pomodoro, amido e zucchero con 3 cucchiai di acqua.","Scaldare 2 cucchiai d''olio in un wok a fuoco medio-alto e strapazzare le uova 1-2 min finché sono appena rapprese ma ancora lucide. Versarle in una ciotola.","Aggiungere il resto dell''olio, i pomodori e la parte bianca dei cipollotti con un pizzico di sale e cuocere 3 min finché sono morbidi e succosi ma ancora interi.","Unire il composto al concentrato finché si addensa, rimettere le uova e mescolare delicatamente 30 s.","Spegnere il fuoco, condire con olio di sesamo, cospargere con la parte verde dei cipollotti e servire sul riso."]}}'::jsonb),
  ('b43b0cd3-cfe4-4513-9b78-fc0e2c6d9a22'::uuid, '{"fr":{"title":"Porc char siu et légumes verts","steps":["Mélanger la sauce hoisin, 1 c. à soupe de sauce soja, le miel, le sucre, 0,5 c. à soupe de sauce d''huître, le xérès, le cinq-épices, l''huile de sésame et l''ail haché. En enrober le porc, réserver 2 c. à soupe de marinade et laisser au réfrigérateur au moins 4 h, ou toute une nuit.","Préchauffer le four à 220 °C. Poser le porc sur une grille au-dessus d''une plaque recouverte de papier aluminium.","Rôtir 20 à 25 min en le retournant et en le badigeonnant de marinade réservée toutes les 10 min, jusqu''à 63 °C à cœur.","Passer en position gril les 2 dernières minutes pour caraméliser les bords, puis laisser reposer 10 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Faire sauter l''ail émincé dans l''huile au wok 20 s, ajouter le pak-choï et 2 c. à soupe d''eau et cuire 3 min ; mélanger avec 1 c. à soupe de sauce d''huître et le reste de la sauce soja.","Trancher le porc dans le sens contraire des fibres et servir avec le riz et les légumes, parsemé de graines de sésame et d''oignon nouveau."]},"it":{"title":"Maiale char siu con verdure","steps":["Mescolare salsa hoisin, 1 cucchiaio di salsa di soia, miele, zucchero, mezzo cucchiaio di salsa di ostriche, sherry, cinque spezie, olio di sesamo e aglio tritato. Ricoprire il maiale, tenere da parte 2 cucchiai di marinata e lasciare in frigo almeno 4 h, o tutta la notte.","Preriscaldare il forno a 220 °C. Mettere il maiale su una griglia sopra una teglia foderata di carta stagnola.","Arrostire 20-25 min girandolo e spennellandolo con la marinata tenuta da parte ogni 10 min, finché raggiunge 63 °C al cuore.","Passare al grill negli ultimi 2 min per caramellare i bordi, poi lasciare riposare 10 min.","Nel frattempo, sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Saltare l''aglio a fettine nell''olio nel wok 20 s, aggiungere il pak choi e 2 cucchiai di acqua e cuocere 3 min; condire con 1 cucchiaio di salsa di ostriche e il resto della salsa di soia.","Affettare il maiale contro fibra e servirlo con il riso e le verdure, cosparso di semi di sesamo e cipollotto."]}}'::jsonb),
  ('beeb1367-a9d8-4d08-aac1-88fd80b58e0a'::uuid, '{"fr":{"title":"Agneau sauté au cumin","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau, 12 min à feu doux ; laisser reposer 5 min.","Mélanger l''agneau avec la sauce soja, le xérès, une pincée de sel, le bicarbonate et la fécule ; laisser reposer 10 min.","Mélanger le cumin, le piment et le sucre.","Chauffer 2 c. à soupe d''huile dans un wok à feu vif et cuire l''agneau en deux fois : l''étaler, laisser 30 s, puis remuer 1 min jusqu''à ce qu''il soit doré. Réserver.","Ajouter le reste de l''huile, le gingembre et l''ail 10 s, puis l''oignon ; faire sauter 2 min jusqu''à ce qu''il commence à s''attendrir.","Remettre l''agneau, saupoudrer du mélange d''épices et remuer 1 min pour bien enrober.","Ajouter la coriandre et les graines de sésame et servir aussitôt sur le riz."]},"it":{"title":"Agnello saltato al cumino","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml di acqua, 12 min a fuoco basso; lasciare riposare 5 min.","Mescolare l''agnello con salsa di soia, sherry, un pizzico di sale, bicarbonato e amido; lasciare riposare 10 min.","Mescolare cumino, peperoncino e zucchero.","Scaldare 2 cucchiai d''olio in un wok a fuoco vivo e cuocere l''agnello in due volte: stenderlo, lasciarlo 30 s, poi saltarlo 1 min finché è dorato. Tenere da parte.","Aggiungere il resto dell''olio, zenzero e aglio per 10 s, poi la cipolla; saltare 2 min finché inizia ad ammorbidirsi.","Rimettere l''agnello, cospargere con il mix di spezie e saltare 1 min finché è ben condito.","Unire coriandolo e semi di sesamo e servire subito sul riso."]}}'::jsonb),
  ('1894de61-71cb-45f7-aba5-7cdf36e2e69e'::uuid, '{"fr":{"title":"Nasu dengaku au tofu et nouilles soba","steps":["Préchauffer le gril du four à puissance maximale. Couper les aubergines en deux dans la longueur et quadriller la chair profondément sans percer la peau.","Chauffer 2 c. à soupe d''huile dans une grande poêle et cuire les aubergines côté peau 3 à 4 min jusqu''à ce que la peau dore.","Les retourner, couvrir et cuire 5 à 6 min jusqu''à ce qu''elles soient fondantes à cœur et dorées côté chair. Les déposer côté peau sur une plaque recouverte de papier cuisson.","Éponger le tofu et le faire dorer dans le reste de l''huile 2 à 3 min de chaque côté ; le mettre sur la plaque.","Fouetter le miso, le sucre, le vin blanc et 1 c. à soupe d''eau pour obtenir un glaçage lisse et en napper les aubergines et le tofu.","Passer sous le gril 3 à 4 min jusqu''à ce que le glaçage bouillonne et caramélise par endroits ; surveiller, car il brûle vite.","Pendant ce temps, cuire les soba selon le paquet, les rincer à l''eau froide et les mélanger avec la sauce soja, l''huile de sésame et l''oignon nouveau.","Servir les aubergines et le tofu parsemés de graines de sésame, avec les soba à côté."]},"it":{"title":"Nasu dengaku con tofu e soba","steps":["Accendere il grill del forno al massimo. Tagliare le melanzane a metà per il lungo e incidere la polpa a griglia in profondità, senza tagliare la buccia.","Scaldare 2 cucchiai d''olio in una padella grande e cuocere le melanzane dal lato della buccia 3-4 min finché la buccia si colora.","Girarle, coprire e cuocere 5-6 min finché sono morbide all''interno e dorate dal lato tagliato. Trasferirle, con la buccia in basso, su una teglia foderata.","Asciugare il tofu e dorarlo nel resto dell''olio 2-3 min per lato; metterlo sulla teglia.","Sbattere miso, zucchero, vino bianco e 1 cucchiaio di acqua fino a ottenere una glassa liscia e stenderla su melanzane e tofu.","Passare sotto il grill 3-4 min finché la glassa bolle e si colora qua e là; controllare perché brucia in fretta.","Nel frattempo, cuocere le soba come indicato sulla confezione, sciacquarle in acqua fredda e condirle con salsa di soia, olio di sesamo e cipollotto.","Servire melanzane e tofu cosparsi di semi di sesamo, con le soba a parte."]}}'::jsonb),
  ('52915883-18c7-40b1-9500-09f4efc12426'::uuid, '{"fr":{"title":"Tofu teriyaki, brocoli et riz","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Bien sécher le tofu dans un torchon propre et enrober les cubes de 1 c. à soupe de fécule et d''une pincée de sel.","Fouetter la sauce soja, le miel, le vinaigre, l''ail, le gingembre, 80 ml d''eau et les 2 c. à café de fécule pour obtenir une sauce teriyaki lisse.","Faire dorer le tofu dans 1,5 c. à soupe d''huile dans une grande poêle antiadhésive à feu moyen-vif, en le retournant, 10 à 12 min. Le réserver.","Ajouter le reste de l''huile, le brocoli et 2 c. à soupe d''eau, et faire sauter 4 à 5 min jusqu''à ce qu''il soit vert vif et encore croquant.","Baisser le feu, verser la sauce et remuer environ 30 s jusqu''à ce qu''elle bouillonne et épaississe, puis remettre le tofu et mélanger pour le laquer.","Servir sur le riz, parsemé de sésame et d''oignon nouveau."]},"it":{"title":"Tofu teriyaki con broccoli e riso","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Asciugare bene il tofu con un canovaccio pulito e passare i cubetti in 1 cucchiaio di amido con un pizzico di sale.","Sbattere la salsa di soia, il miele, l''aceto, l''aglio, lo zenzero, 80 ml d''acqua e i 2 cucchiaini di amido fino a ottenere una salsa teriyaki liscia.","Rosolare il tofu in 1,5 cucchiai d''olio in una padella antiaderente a fuoco medio-alto, girandolo, per 10-12 min finché è dorato su tutti i lati. Toglierlo.","Aggiungere l''olio rimasto, i broccoli e 2 cucchiai d''acqua e saltare 4-5 min finché sono verde brillante e ancora croccanti.","Abbassare il fuoco, versare la salsa e mescolare circa 30 s finché bolle e si addensa, poi rimettere il tofu e mescolare per glassarlo.","Servire sul riso, cosparso di sesamo e cipollotto."]}}'::jsonb),
  ('62893e4f-bac6-47e6-9a16-28e32690738a'::uuid, '{"fr":{"title":"Soupe udon au miso, champignons, tofu et œuf","steps":["Plonger les œufs dans l''eau bouillante et les cuire 6 min 30 pour un jaune fondant ; les refroidir à l''eau froide et les écaler. Vider la casserole.","Dans la même casserole, porter le bouillon à frémissement avec le gingembre et l''ail.","Ajouter les champignons et la sauce soja et laisser frémir 5 min jusqu''à ce que les champignons soient tendres.","Ajouter les udon, le tofu et le pak-choï et laisser frémir 2 à 3 min, jusqu''à ce que les nouilles se détachent et que le pak-choï soit tombé.","Retirer du feu. Délayer le miso dans une louche de bouillon et le remettre dans la casserole ; ne plus faire bouillir.","Répartir dans des bols, garnir des œufs coupés en deux et d''oignon nouveau, puis finir avec l''huile de sésame, le sésame et le piment."]},"it":{"title":"Zuppa di udon al miso con funghi, tofu e uovo","steps":["Immergere le uova in acqua bollente e cuocerle 6 min e mezzo per un tuorlo cremoso; raffreddarle in acqua fredda e sgusciarle. Svuotare la pentola.","Nella stessa pentola portare il brodo a sobbollire con lo zenzero e l''aglio.","Aggiungere i funghi e la salsa di soia e cuocere a fuoco lento 5 min finché i funghi sono teneri.","Aggiungere gli udon, il tofu e il pak choi e cuocere 2-3 min, finché i noodles si separano e il pak choi appassisce.","Togliere dal fuoco. Sciogliere il miso in un mestolo di brodo e rimetterlo nella pentola; non farlo più bollire.","Distribuire nelle ciotole, completare con le uova tagliate a metà e il cipollotto, poi finire con olio di sesamo, sesamo e peperoncino."]}}'::jsonb),
  ('9b05494a-6b38-47d3-a478-7965c5cf3c64'::uuid, '{"fr":{"title":"Thon snacké, épinards au sésame et riz","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert dans 180 ml d''eau à feu doux 12 min et le laisser reposer 10 min hors du feu.","Tiédir le vinaigre avec 1 c. à café de sucre et ½ c. à café de sel jusqu''à dissolution et l''incorporer délicatement au riz chaud.","Torréfier 2 c. à soupe de sésame à sec dans une poêle 2 min jusqu''à ce qu''il dore, puis l''écraser grossièrement et le mélanger avec 1 c. à soupe de sauce soja et le reste du sucre.","Faire tomber les épinards dans la même poêle avec un peu d''eau, environ 2 min ; les presser, les hacher et les mélanger à la sauce au sésame. Essuyer la poêle.","Sécher le thon, le badigeonner d''huile de sésame, le saler légèrement et presser le reste du sésame sur les deux faces.","Chauffer l''huile végétale dans la poêle à feu vif et saisir le thon 1 min par face pour un cœur rosé (2 min pour à point). Laisser reposer 2 min.","Trancher le thon contre le fil et servir sur le riz avec les épinards, le gingembre mariné, l''oignon nouveau et le reste de la sauce soja."]},"it":{"title":"Tonno scottato con spinaci al sesamo e riso","steps":["Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto in 180 ml d''acqua a fuoco basso per 12 min e lasciarlo riposare 10 min fuori dal fuoco.","Scaldare l''aceto con 1 cucchiaino di zucchero e mezzo cucchiaino di sale finché si sciolgono e incorporarlo delicatamente al riso caldo.","Tostare 2 cucchiai di sesamo in una padella asciutta per 2 min finché è dorato, poi pestarlo grossolanamente e mescolarlo con 1 cucchiaio di salsa di soia e lo zucchero rimasto.","Far appassire gli spinaci nella stessa padella con un goccio d''acqua, circa 2 min; strizzarli, tritarli e condirli con la salsa al sesamo. Pulire la padella.","Asciugare il tonno, spennellarlo con l''olio di sesamo, salarlo leggermente e premere il sesamo rimasto su entrambi i lati.","Scaldare l''olio di semi nella padella a fuoco vivo e scottare il tonno 1 min per lato per un cuore al sangue (2 min per una cottura media). Lasciarlo riposare 2 min.","Tagliare il tonno contro fibra e servirlo sul riso con gli spinaci, lo zenzero marinato, il cipollotto e il resto della salsa di soia."]}}'::jsonb),
  ('ff1bfc7c-f6d4-4c1e-a75e-45eb3b87e0dc'::uuid, '{"fr":{"title":"Katsu de poulet au four, riz et chou","steps":["Préchauffer le four à 200 °C. Faire dorer la chapelure panko avec 1,5 c. à soupe d''huile dans une poêle à feu moyen, en remuant, 3 à 4 min ; la verser dans une assiette pour qu''elle refroidisse.","Ouvrir chaque filet en portefeuille et l''aplatir à une épaisseur régulière de 1 à 1,5 cm ; saler et poivrer.","Battre l''œuf avec le reste de l''huile. Passer chaque escalope dans la farine, puis dans l''œuf, puis la presser fermement dans le panko doré.","Poser les escalopes sur une grille au-dessus d''une plaque et cuire 20 à 25 min, jusqu''à ce que le jus soit clair (74 °C à cœur).","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Mélanger le ketchup, la sauce Worcestershire, la sauce soja et le sucre pour une sauce tonkatsu express. Plonger le chou 5 min dans de l''eau glacée et bien l''égoutter.","Laisser reposer le katsu 2 min, le couper en lanières et servir avec le riz, le chou, le citron et la sauce en filet."]},"it":{"title":"Katsu di pollo al forno con riso e cavolo","steps":["Scaldare il forno a 200 °C. Tostare il panko con 1,5 cucchiai d''olio in una padella a fuoco medio, mescolando, per 3-4 min finché è dorato; versarlo in un piatto a raffreddare.","Aprire ogni petto a libro e batterlo a uno spessore uniforme di 1-1,5 cm; salare e pepare.","Sbattere l''uovo con l''olio rimasto. Passare ogni cotoletta nella farina, poi nell''uovo, poi premerla bene nel panko tostato.","Disporre le cotolette su una griglia sopra una teglia e cuocere 20-25 min, finché i succhi sono chiari (74 °C al cuore).","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mescolare il ketchup, la salsa Worcestershire, la salsa di soia e lo zucchero per una salsa tonkatsu veloce. Immergere il cavolo 5 min in acqua ghiacciata e scolarlo bene.","Lasciare riposare il katsu 2 min, tagliarlo a strisce e servirlo con il riso, il cavolo, il limone e la salsa a filo."]}}'::jsonb),
  ('3d4d6f57-5e42-4208-af77-afff5162cee1'::uuid, '{"fr":{"title":"Salade de riz à sushi, tofu et edamame","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, le cuire à couvert dans 180 ml d''eau à feu doux 12 min et le laisser reposer 10 min hors du feu.","Dissoudre 2 c. à soupe de vinaigre, le sucre et ½ c. à café de sel, les incorporer au riz, l''étaler sur une assiette et laisser refroidir 15 min.","Cuire les edamame 3 min dans une poêle avec un peu d''eau, puis les égoutter et les laisser refroidir.","Sécher le tofu et le faire dorer dans l''huile dans la même poêle à feu moyen-vif, 8 min ; ajouter 1 c. à soupe de sauce soja et mélanger jusqu''à absorption.","Fouetter le reste de sauce soja et de vinaigre avec l''huile de sésame pour la sauce.","Répartir le riz dans deux bols et garnir de tofu, d''edamame, de concombre, de carotte et d''avocat.","Arroser de sauce et finir avec le gingembre mariné, le sésame et l''oignon nouveau."]},"it":{"title":"Insalata di riso da sushi con tofu ed edamame","steps":["Sciacquare il riso finché l''acqua è limpida, cuocerlo coperto in 180 ml d''acqua a fuoco basso per 12 min e lasciarlo riposare 10 min fuori dal fuoco.","Sciogliere 2 cucchiai di aceto, lo zucchero e mezzo cucchiaino di sale, incorporarli al riso, stenderlo su un piatto e lasciarlo raffreddare 15 min.","Cuocere gli edamame 3 min in padella con un goccio d''acqua, poi scolarli e lasciarli raffreddare.","Asciugare il tofu e rosolarlo nell''olio nella stessa padella a fuoco medio-alto, 8 min, finché è dorato; aggiungere 1 cucchiaio di salsa di soia e mescolare finché si assorbe.","Sbattere la salsa di soia e l''aceto rimasti con l''olio di sesamo per il condimento.","Dividere il riso in due ciotole e completare con tofu, edamame, cetriolo, carota e avocado.","Condire con la salsa e finire con zenzero marinato, sesamo e cipollotto."]}}'::jsonb),
  ('85118fd3-d36c-4fb3-83b3-c39289e6bc96'::uuid, '{"fr":{"title":"Donburi de tsukune","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Pétrir à la main le poulet haché, presque tout l''oignon nouveau, le gingembre, l''œuf, la fécule et une pincée de sel 1 à 2 min, jusqu''à ce que le mélange colle.","Les mains mouillées, former 10 à 12 petites boulettes aplaties.","Cuire le brocoli dans une poêle avec 3 c. à soupe d''eau, à couvert, 3 à 4 min jusqu''à ce qu''il soit juste tendre ; réserver.","Chauffer l''huile dans la poêle à feu moyen et cuire les tsukune 3 à 4 min par face, jusqu''à ce qu''ils soient dorés et cuits à cœur.","Mélanger la sauce soja, le sucre et le vin, verser dans la poêle et laisser bouillonner 1 à 2 min en retournant les boulettes jusqu''à ce qu''elles soient brillantes et laquées.","Servir les tsukune et le brocoli sur le riz avec la sauce de la poêle, un jaune d''œuf cru par-dessus si on le souhaite, le sésame, le piment et le reste de l''oignon nouveau."]},"it":{"title":"Donburi di tsukune","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Impastare a mano il pollo macinato, quasi tutto il cipollotto, lo zenzero, l''uovo, l''amido e un pizzico di sale per 1-2 min finché il composto è appiccicoso.","Con le mani bagnate formare 10-12 piccole polpette appiattite.","Cuocere i broccoli in padella con 3 cucchiai d''acqua, coperti, 3-4 min finché sono appena teneri; tenerli da parte.","Scaldare l''olio nella padella a fuoco medio e cuocere gli tsukune 3-4 min per lato finché sono dorati e cotti all''interno.","Mescolare la salsa di soia, lo zucchero e il vino, versare nella padella e far sobbollire 1-2 min girando le polpette finché sono lucide e glassate.","Servire gli tsukune e i broccoli sul riso con la glassa della padella, un tuorlo crudo sopra a piacere, sesamo, peperoncino e il cipollotto rimasto."]}}'::jsonb),
  ('f2f27077-f5bc-493c-9769-5f62aefa34eb'::uuid, '{"fr":{"title":"Butaniku shōgayaki (porc au gingembre)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Mélanger le gingembre, l''ail, la sauce soja, le vin et le sucre pour la sauce. Saler et poivrer légèrement le porc.","Chauffer l''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon 2 min.","Étaler les tranches de porc dans la poêle et les cuire 1 à 2 min par face jusqu''à ce qu''elles soient dorées.","Verser la sauce et laisser bouillonner 1 à 2 min en retournant le porc, jusqu''à ce qu''elle réduise et nappe la viande.","Servir le porc et sa sauce avec un dôme de chou cru émincé et le riz, parsemé d''oignon nouveau."]},"it":{"title":"Butaniku shōgayaki (maiale allo zenzero)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mescolare zenzero, aglio, salsa di soia, vino e zucchero per la salsa. Salare e pepare leggermente il maiale.","Scaldare l''olio in una padella grande a fuoco medio-alto e soffriggere la cipolla 2 min.","Distendere le fette di maiale nella padella e cuocerle 1-2 min per lato finché sono dorate.","Versare la salsa e farla sobbollire 1-2 min girando il maiale, finché si riduce e avvolge la carne.","Servire il maiale con la sua salsa insieme a un mucchietto di cavolo crudo affettato e al riso, con cipollotto sopra."]}}'::jsonb),
  ('a6face1b-b335-4aae-b9cd-603f4dd6b7c1'::uuid, '{"fr":{"title":"Nikujaga (bœuf et pommes de terre mijotés)","steps":["Éplucher les pommes de terre, les couper en gros morceaux, arrondir les arêtes pour qu''elles se tiennent et les faire tremper 10 min dans l''eau froide.","Chauffer l''huile dans une cocotte à feu moyen et faire revenir l''oignon, la carotte et les pommes de terre égouttées 3 min, jusqu''à ce que les bords des pommes de terre deviennent translucides.","Ajouter le bœuf et remuer jusqu''à ce qu''il ne soit plus rose.","Verser 300 ml d''eau, porter à ébullition et écumer. Ajouter d''abord le vin et le sucre, couvrir d''une feuille de papier cuisson posée à la surface et laisser mijoter 10 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Ajouter la sauce soja au ragoût et laisser mijoter encore 15 min sans remuer, en arrosant avec le bouillon, jusqu''à ce que les pommes de terre soient tendres et le liquide réduit de moitié environ.","Ajouter les haricots verts pour les 3 dernières minutes. Servir en bols avec un peu de bouillon, le riz à côté."]},"it":{"title":"Nikujaga (manzo e patate in umido)","steps":["Sbucciare le patate, tagliarle a pezzi grossi, smussare gli spigoli perché restino intere e lasciarle 10 min in acqua fredda.","Scaldare l''olio in una pentola a fuoco medio e rosolare cipolla, carota e patate scolate per 3 min, finché i bordi delle patate diventano traslucidi.","Aggiungere il manzo e mescolare finché non è più rosa.","Versare 300 ml d''acqua, portare a bollore e schiumare. Aggiungere prima il vino e lo zucchero, coprire con un foglio di carta forno appoggiato sulla superficie e cuocere a fuoco lento 10 min.","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Aggiungere la salsa di soia allo stufato e cuocere ancora 15 min senza mescolare, irrorando con il brodo, finché le patate sono tenere e il liquido si è ridotto di circa metà.","Aggiungere i fagiolini negli ultimi 3 min. Servire in ciotole con un po'' di brodo, con il riso a parte."]}}'::jsonb),
  ('96bd3c95-432e-4410-b43d-d745112aa97b'::uuid, '{"fr":{"title":"Saba shioyaki (maquereau grillé au sel)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Saler généreusement le maquereau des deux côtés et le laisser 10 min pendant la cuisson du riz ; puis éponger l''humidité qui en sort.","Mélanger le concombre avec une pincée de sel, attendre 5 min, le presser puis l''assaisonner avec le vinaigre et le sucre.","Tapisser une poêle de papier aluminium, le badigeonner d''huile et chauffer à feu moyen.","Cuire le maquereau côté peau 4 à 5 min jusqu''à ce qu''elle soit croustillante et dorée, puis le retourner et cuire encore 3 à 4 min jusqu''à ce qu''il soit opaque à cœur.","Servir le poisson avec le riz, la salade de concombre parsemée de sésame, les quartiers de citron et le radis râpé arrosé d''une goutte de sauce soja."]},"it":{"title":"Saba shioyaki (sgombro alla griglia con sale)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Salare abbondantemente lo sgombro su entrambi i lati e lasciarlo 10 min mentre cuoce il riso; poi tamponare l''umidità che rilascia.","Mescolare il cetriolo con un pizzico di sale, attendere 5 min, strizzarlo e condirlo con l''aceto e lo zucchero.","Foderare una padella con carta stagnola, spennellarla d''olio e scaldarla a fuoco medio.","Cuocere lo sgombro dal lato della pelle 4-5 min finché è croccante e dorata, poi girarlo e cuocere altri 3-4 min finché è opaco all''interno.","Servire il pesce con il riso, l''insalata di cetriolo cosparsa di sesamo, spicchi di limone e il ravanello grattugiato con una goccia di salsa di soia."]}}'::jsonb),
  ('179efe64-fe23-4da3-97b2-836e0e98e0cf'::uuid, '{"fr":{"title":"Curry japonais au poulet","steps":["Saler et poivrer le poulet et le faire dorer dans l''huile dans une cocotte à feu moyen-vif, environ 4 min par face. Le réserver.","Baisser le feu, ajouter l''oignon, l''ail et le gingembre et cuire en remuant 15 min jusqu''à ce qu''ils soient fondants et bien dorés.","Ajouter le beurre, puis incorporer la farine et le curry et cuire 2 min jusqu''à ce que le roux sente le grillé.","Verser le bouillon petit à petit en fouettant, puis ajouter le poulet, les carottes, la pomme, la sauce Worcestershire, le ketchup et le laurier. Couvrir et laisser mijoter 15 min.","Pendant ce temps, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Ajouter la pomme de terre et laisser mijoter à couvert encore 15 min en remuant de temps en temps, jusqu''à ce que les légumes soient très tendres et la sauce épaisse.","Ajouter le miel et les petits pois, laisser frémir 2 min, puis rectifier le sel. Servir à côté du riz."]},"it":{"title":"Curry giapponese di pollo","steps":["Salare e pepare il pollo e rosolarlo nell''olio in una pentola dal fondo spesso a fuoco medio-alto, circa 4 min per lato. Toglierlo.","Abbassare il fuoco, aggiungere cipolla, aglio e zenzero e cuocere mescolando per 15 min finché sono morbidi e ben dorati.","Aggiungere il burro, poi incorporare la farina e il curry e cuocere 2 min finché il roux profuma di tostato.","Unire il brodo poco alla volta mescolando con la frusta, poi aggiungere il pollo, le carote, la mela, la salsa Worcestershire, il ketchup e l''alloro. Coprire e cuocere a fuoco lento 15 min.","Nel frattempo sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Aggiungere la patata e cuocere coperto altri 15 min, mescolando ogni tanto, finché le verdure sono molto tenere e la salsa è densa.","Unire il miele e i piselli, cuocere 2 min, poi regolare di sale. Servire accanto al riso."]}}'::jsonb),
  ('090b603f-91ab-4c37-8c40-93b84e835d51'::uuid, '{"fr":{"title":"Soba froides au tofu et edamame","steps":["Porter le bouillon, la sauce soja, le vin et le sucre à ébullition dans une casserole et laisser bouillir 1 min. Verser dans un bol et le mettre au frais (quelques glaçons accélèrent le refroidissement).","Sécher le tofu et le faire dorer dans l''huile dans une poêle à feu moyen-vif, 3 min par face. Le couper en lanières.","Porter une grande casserole d''eau à gros bouillons, ajouter les edamame et les soba, remuer et cuire le temps indiqué sur le paquet de soba (souvent 4 à 5 min).","Égoutter et rincer sous l''eau froide en frottant les nouilles pour enlever l''amidon, puis les plonger un instant dans de l''eau glacée et bien égoutter.","Dresser les soba et les edamame sur des assiettes avec le tofu et le concombre.","Servir la sauce froide dans de petits bols avec l''oignon nouveau et le radis râpé à y ajouter, et le sésame à parsemer."]},"it":{"title":"Soba freddi con tofu ed edamame","steps":["Portare a bollore brodo, salsa di soia, vino e zucchero in una pentola e bollire 1 min. Versare in una ciotola e farla raffreddare (qualche cubetto di ghiaccio aiuta).","Asciugare il tofu e rosolarlo nell''olio in una padella a fuoco medio-alto, 3 min per lato, finché è dorato. Tagliarlo a strisce.","Portare a bollore una pentola grande d''acqua, aggiungere edamame e soba, mescolare e cuocere per il tempo indicato sulla confezione dei soba (di solito 4-5 min).","Scolare e sciacquare sotto l''acqua fredda strofinando i noodles per eliminare l''amido, poi immergerli un attimo in acqua ghiacciata e scolarli bene.","Disporre soba ed edamame nei piatti con il tofu e il cetriolo.","Servire la salsa fredda in ciotoline con il cipollotto e il ravanello grattugiato da aggiungere, e il sesamo da cospargere."]}}'::jsonb),
  ('2f9185f2-8f3c-45a9-809f-8577f36a66dc'::uuid, '{"fr":{"title":"Bánh mì au tofu croustillant","steps":["Mélanger la carotte et le radis avec le vinaigre, 1 c. à soupe de sucre et ½ c. à café de sel ; laisser mariner au moins 20 min en remuant de temps en temps.","Préchauffer le four à 200 °C. Sécher le tofu et passer les tranches dans la fécule en secouant l''excédent.","Faire frire le tofu dans l''huile végétale dans une poêle antiadhésive à feu moyen-vif, 4 à 5 min par face, jusqu''à ce qu''il soit croustillant et doré. Le réserver.","Baisser le feu, faire revenir l''ail dans l''huile de sésame 1 min, puis ajouter la sauce soja, le reste du sucre et 3 c. à soupe d''eau. Remettre le tofu avec le zeste du citron vert et mélanger 1 à 2 min jusqu''à ce qu''il soit laqué.","Réchauffer les morceaux de baguette directement sur la grille du four 5 à 6 min jusqu''à ce qu''ils soient croustillants.","Mélanger la mayonnaise, la sriracha et 1 c. à soupe de jus de citron vert.","Ouvrir le pain, le tartiner de mayonnaise à la sriracha et le garnir de tofu, de pickles égouttés, de concombre, de coriandre et de piment."]},"it":{"title":"Bánh mì con tofu croccante","steps":["Mescolare carota e ravanello con l''aceto, 1 cucchiaio di zucchero e mezzo cucchiaino di sale; lasciar marinare almeno 20 min mescolando ogni tanto.","Scaldare il forno a 200 °C. Asciugare il tofu e passare le fette nell''amido, scuotendo l''eccesso.","Friggere il tofu nell''olio di semi in una padella antiaderente a fuoco medio-alto, 4-5 min per lato, finché è croccante e dorato. Toglierlo.","Abbassare il fuoco, soffriggere l''aglio nell''olio di sesamo 1 min, poi aggiungere la salsa di soia, lo zucchero rimasto e 3 cucchiai d''acqua. Rimettere il tofu con la scorza del lime e mescolare 1-2 min finché è glassato.","Scaldare i pezzi di baguette direttamente sulla griglia del forno per 5-6 min finché sono croccanti.","Mescolare la maionese, la sriracha e 1 cucchiaio di succo di lime.","Aprire il pane, spalmarlo con la maionese alla sriracha e farcirlo con tofu, verdure sottaceto scolate, cetriolo, coriandolo e peperoncino."]}}'::jsonb),
  ('bd6e4d1a-f6e3-4a40-b674-40721b9a6a01'::uuid, '{"fr":{"title":"Nouilles sautées aux crevettes façon pad thaï","steps":["Faire tremper les nouilles 15 à 20 min dans l''eau tiède jusqu''à ce qu''elles soient souples mais encore fermes ; égoutter.","Mélanger le sucre, la sauce de poisson, le jus d''un demi-citron vert, la pâte de curry et 2 c. à soupe d''eau jusqu''à dissolution du sucre (cela remplace le tamarin).","Faire sauter le tofu et les crevettes dans 1 c. à soupe d''huile dans un wok à feu vif, 2 à 3 min jusqu''à ce que les crevettes soient roses. Réserver.","Ajouter le reste de l''huile et faire revenir l''ail et l''échalote 30 s jusqu''à ce qu''ils embaument.","Ajouter les nouilles et la sauce et faire sauter à feu vif 1 à 2 min jusqu''à ce que les nouilles soient tendres et aient absorbé la sauce.","Pousser les nouilles sur le côté, casser les œufs, les laisser prendre 30 s, puis remettre les crevettes et le tofu et mélanger le tout.","Ajouter les germes de soja et l''oignon nouveau, faire sauter 30 s et servir avec les cacahuètes, le reste du citron vert en quartiers et le piment."]},"it":{"title":"Noodles saltati con gamberi stile pad thai","steps":["Ammollare i noodles in acqua tiepida per 15-20 min finché sono flessibili ma ancora sodi; scolarli.","Mescolare lo zucchero, la salsa di pesce, il succo di mezzo lime, la pasta di curry e 2 cucchiai d''acqua finché lo zucchero si scioglie (sostituisce il tamarindo).","Saltare tofu e gamberi in 1 cucchiaio d''olio nel wok a fuoco vivo per 2-3 min finché i gamberi diventano rosa. Tenerli da parte.","Aggiungere l''olio rimasto e soffriggere aglio e scalogno per 30 s finché profumano.","Aggiungere i noodles e la salsa e saltare a fuoco vivo 1-2 min finché i noodles si ammorbidiscono e assorbono la salsa.","Spostare i noodles di lato, rompere le uova, lasciarle rapprendere 30 s, poi rimettere gamberi e tofu e mescolare tutto.","Aggiungere germogli di soia e cipollotto, saltare 30 s e servire con le arachidi, il resto del lime a spicchi e il peperoncino."]}}'::jsonb),
  ('bb6e3cf8-439f-4f5b-93df-b86fb163c981'::uuid, '{"fr":{"title":"Curry vert aubergine et tofu","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Sécher le tofu et le faire dorer dans l''huile dans un wok ou une sauteuse à feu moyen-vif, 6 à 8 min. Le réserver.","Faire revenir la pâte de curry dans la sauteuse avec 3 c. à soupe de la partie la plus épaisse du lait de coco 2 min, jusqu''à ce qu''elle embaume et que l''huile se sépare.","Ajouter le reste du lait de coco et 100 ml d''eau, puis l''aubergine, et laisser mijoter 8 à 10 min jusqu''à ce qu''elle soit fondante.","Ajouter les haricots verts et le tofu et laisser mijoter encore 4 min, jusqu''à ce que les haricots soient juste tendres.","Assaisonner avec la sauce soja, le sucre et le jus de citron vert, goûter, puis ajouter le basilic hors du feu. Servir avec le riz et le piment."]},"it":{"title":"Curry verde di melanzane e tofu","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Asciugare il tofu e rosolarlo nell''olio in un wok o in una padella larga a fuoco medio-alto, 6-8 min, finché è dorato. Toglierlo.","Soffriggere la pasta di curry nella padella con 3 cucchiai della parte più densa del latte di cocco per 2 min, finché profuma e l''olio si separa.","Unire il resto del latte di cocco e 100 ml d''acqua, aggiungere la melanzana e cuocere a fuoco lento 8-10 min finché è morbida.","Aggiungere fagiolini e tofu e cuocere altri 4 min, finché i fagiolini sono appena teneri.","Condire con salsa di soia, zucchero e succo di lime, assaggiare, poi unire il basilico fuori dal fuoco. Servire con il riso e il peperoncino."]}}'::jsonb),
  ('b5647c45-2692-45ca-8ee6-c01a1edcf529'::uuid, '{"fr":{"title":"Rouleaux de printemps crevettes et avocat","steps":["Cuire les vermicelles 3 à 4 min dans l''eau bouillante (ou selon le paquet), les rincer à l''eau froide et bien les égoutter.","Fouetter le beurre de cacahuète, la sauce soja, le miel, le jus d''un demi-citron vert, le piment et 3 à 4 c. à soupe d''eau tiède pour une sauce lisse.","Arroser l''avocat du reste du citron vert pour qu''il ne noircisse pas.","Tremper une feuille de riz 10 à 15 s dans l''eau tiède jusqu''à ce qu''elle soit juste souple et la poser sur un torchon humide.","Disposer une rangée de demi-crevettes, côté coupé vers le haut, au centre, puis la salade, les vermicelles, la carotte, l''avocat et les herbes par-dessus.","Rabattre le bas sur la garniture, replier les côtés et rouler bien serré. Recommencer pour faire 8 rouleaux.","Servir aussitôt avec la sauce aux cacahuètes pour tremper."]},"it":{"title":"Involtini di carta di riso con gamberi e avocado","steps":["Cuocere i vermicelli in acqua bollente per 3-4 min (o secondo la confezione), sciacquarli in acqua fredda e scolarli bene.","Sbattere burro di arachidi, salsa di soia, miele, succo di mezzo lime, peperoncino e 3-4 cucchiai d''acqua tiepida fino a ottenere una salsa liscia.","Irrorare l''avocado con il resto del lime perché non annerisca.","Immergere un foglio di carta di riso in acqua tiepida per 10-15 s finché è appena morbido e stenderlo su un canovaccio umido.","Disporre al centro una fila di mezzi gamberi con il lato tagliato verso l''alto, poi sopra lattuga, vermicelli, carota, avocado ed erbe.","Ripiegare il lembo inferiore sul ripieno, chiudere i lati e arrotolare stretto. Ripetere per ottenere 8 involtini.","Servire subito con la salsa di arachidi per intingere."]}}'::jsonb),
  ('788cd98a-23e9-42b2-94d2-c323fbb2ec0b'::uuid, '{"fr":{"title":"Curry massaman au bœuf","steps":["Préchauffer le four à 160 °C. Faire dorer le bœuf dans l''huile dans une cocotte allant au four à feu vif, 5 min.","Ajouter l''oignon, l''ail et la pâte de curry et remuer 2 min jusqu''à ce qu''ils embaument.","Ajouter la cannelle, la cardamome, le bouillon et la moitié du lait de coco, porter à frémissement, couvrir et cuire au four 1 h 15.","Ajouter les pommes de terre, les cacahuètes, le reste du lait de coco, la sauce de poisson et le sucre, et remettre au four sans couvercle 50 à 60 min, jusqu''à ce que le bœuf soit tendre et les pommes de terre cuites.","Environ 20 min avant la fin, rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Assaisonner le curry avec le jus d''un demi-citron vert, et un peu de sauce de poisson ou de sucre pour équilibrer le sucré, le salé et l''acide.","Servir avec le riz, la coriandre et le reste du citron vert en quartiers."]},"it":{"title":"Curry massaman di manzo","steps":["Scaldare il forno a 160 °C. Rosolare il manzo nell''olio in una casseruola adatta al forno a fuoco vivo, 5 min.","Aggiungere cipolla, aglio e pasta di curry e mescolare 2 min finché profumano.","Aggiungere cannella, cardamomo, brodo e metà del latte di cocco, portare a sobbollire, coprire e brasare in forno per 1 h 15 min.","Unire patate, arachidi, il resto del latte di cocco, la salsa di pesce e lo zucchero e rimettere in forno scoperto per 50-60 min, finché il manzo è tenero e le patate cotte.","Circa 20 min prima della fine sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Condire il curry con il succo di mezzo lime e altra salsa di pesce o zucchero per bilanciare dolce, salato e acido.","Servire con il riso, il coriandolo e il resto del lime a spicchi."]}}'::jsonb),
  ('6ea6bed6-f994-4c4e-b9dc-7e3c29d833b6'::uuid, '{"fr":{"title":"Curry rouge thaï au butternut et poulet","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Faire revenir doucement la pâte de curry dans l''huile dans un wok 1 à 2 min, jusqu''à ce qu''elle grésille et embaume.","Ajouter le lait de coco et 100 ml d''eau, porter à frémissement, ajouter la courge et laisser mijoter 10 min jusqu''à ce qu''elle soit presque tendre.","Ajouter le poulet et laisser mijoter 6 à 8 min jusqu''à ce qu''il soit cuit à cœur.","Ajouter les tomates et cuire 2 min jusqu''à ce qu''elles commencent à éclater.","Assaisonner avec la sauce de poisson petit à petit et le jus d''un demi-citron vert, puis parsemer de basilic. Servir avec le riz et le reste du citron vert."]},"it":{"title":"Curry rosso thai con zucca butternut e pollo","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Soffriggere dolcemente la pasta di curry nell''olio in un wok per 1-2 min finché sfrigola e profuma.","Unire il latte di cocco e 100 ml d''acqua, portare a sobbollire, aggiungere la zucca e cuocere 10 min finché è quasi tenera.","Aggiungere il pollo e cuocere 6-8 min finché è cotto all''interno.","Aggiungere i pomodorini e cuocere 2 min finché iniziano a spaccarsi.","Condire con la salsa di pesce poco alla volta e il succo di mezzo lime, poi cospargere di basilico. Servire con il riso e il resto del lime."]}}'::jsonb),
  ('3f39c7bd-f6c1-4ad1-86e9-0d865aaf83f2'::uuid, '{"fr":{"title":"Gai yang (poulet grillé thaï) et salade de concombre","steps":["Râper très finement la citronnelle et l''ail (ou les mixer au mixeur plongeant) et les mélanger avec les tiges de coriandre hachées, 1,5 c. à soupe de sauce de poisson, la sauce soja, 1,5 c. à soupe de sucre, l''huile et beaucoup de poivre noir.","Enrober le poulet de marinade, couvrir et réfrigérer au moins 3 h (idéalement une nuit).","Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Chauffer une poêle-gril ou une poêle antiadhésive (ou un barbecue), ajouter le poulet et baisser à feu moyen ; cuire 5 à 6 min par face jusqu''à ce qu''il soit caramélisé sur les bords et cuit à cœur. Laisser reposer 3 min.","Pendant ce temps, mélanger le concombre et l''échalote avec le jus du citron vert, le reste de la sauce de poisson et du sucre, et du piment selon le goût.","Trancher le poulet et servir avec le riz et la salade de concombre, parsemé de cacahuètes et de feuilles de coriandre."]},"it":{"title":"Gai yang (pollo alla griglia thai) con insalata di cetrioli","steps":["Grattugiare finissimi citronella e aglio (o frullarli con il minipimer) e mescolarli con i gambi di coriandolo tritati, 1,5 cucchiai di salsa di pesce, la salsa di soia, 1,5 cucchiai di zucchero, l''olio e molto pepe nero.","Ricoprire il pollo con la marinata, coprire e lasciare in frigo almeno 3 h (meglio tutta la notte).","Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Scaldare bene una bistecchiera o una padella antiaderente (o il barbecue), aggiungere il pollo e abbassare a fuoco medio; cuocere 5-6 min per lato finché è abbrustolito ai bordi e cotto all''interno. Lasciarlo riposare 3 min.","Nel frattempo condire cetriolo e scalogno con il succo del lime, la salsa di pesce e lo zucchero rimasti e peperoncino a piacere.","Affettare il pollo e servirlo con il riso e l''insalata di cetrioli, cosparso di arachidi e foglie di coriandolo."]}}'::jsonb),
  ('6b6848a2-12e1-4dde-a6cb-7291243dbc57'::uuid, '{"fr":{"title":"Bún chả (porc grillé et vermicelles de Hanoï)","steps":["Mélanger l''échalote, 3 gousses d''ail, la citronnelle, la sauce d''huître, 1,5 c. à soupe de sauce de poisson, 1,5 c. à soupe de sucre et beaucoup de poivre. En mélanger la moitié au porc haché et l''autre aux tranches de porc ; laisser mariner 30 min.","Mélanger la carotte avec une pincée de sel, 1 c. à café de sucre et le vinaigre pour un pickle express.","Préparer le bouillon à tremper : dissoudre le reste du sucre dans 200 ml d''eau chaude, puis ajouter le reste de la sauce de poisson, le jus d''un citron vert, la dernière gousse d''ail et le piment.","Préchauffer le gril du four au maximum. Les mains huilées, façonner le porc haché en 10 petites galettes et les poser avec les tranches de porc sur une grille huilée au-dessus d''une plaque.","Faire griller 10 à 12 min en retournant une fois, jusqu''à ce que la viande soit caramélisée sur les bords et cuite à cœur.","Pendant ce temps, cuire les vermicelles 3 à 4 min dans l''eau bouillante (ou selon le paquet), les rincer à l''eau froide et les égoutter.","Mettre le porc grillé et la carotte marinée dans des bols de bouillon tiède et servir avec les vermicelles, la salade, les herbes et le demi-citron vert restant ; tremper le tout dans le bouillon en mangeant."]},"it":{"title":"Bún chả (maiale grigliato e vermicelli di Hanoi)","steps":["Mescolare scalogno, 3 spicchi d''aglio, citronella, salsa d''ostrica, 1,5 cucchiai di salsa di pesce, 1,5 cucchiai di zucchero e molto pepe. Unirne metà al maiale macinato e metà alle fette di maiale; marinare 30 min.","Mescolare la carota con un pizzico di sale, 1 cucchiaino di zucchero e l''aceto per un sottaceto veloce.","Preparare il brodo per intingere: sciogliere lo zucchero rimasto in 200 ml d''acqua calda, poi aggiungere la salsa di pesce rimasta, il succo di 1 lime, l''ultimo spicchio d''aglio e il peperoncino.","Scaldare il grill del forno al massimo. Con le mani unte formare con il maiale macinato 10 piccole polpette piatte e disporle con le fette di maiale su una griglia unta sopra una teglia.","Grigliare 10-12 min girando una volta, finché la carne è abbrustolita ai bordi e cotta all''interno.","Nel frattempo cuocere i vermicelli in acqua bollente 3-4 min (o secondo la confezione), sciacquarli in acqua fredda e scolarli.","Mettere il maiale grigliato e la carota sottaceto in ciotole di brodo tiepido e servire con vermicelli, lattuga, erbe e il mezzo lime rimasto; intingere tutto nel brodo mangiando."]}}'::jsonb),
  ('b5fa3fe8-d226-4eda-88a3-7ea404bc6380'::uuid, '{"fr":{"title":"Bò lúc lắc (bœuf sauté vietnamien)","steps":["Rincer le riz et le cuire à couvert dans 300 ml d''eau à feu doux 12 min ; laisser reposer 5 min hors du feu.","Pendant la cuisson du riz, mélanger le bœuf avec l''ail, la sauce d''huître, la sauce soja, la sauce de poisson, le sucre, la fécule et ½ c. à café de poivre noir ; laisser reposer 15 min.","Disposer la salade, les tomates et l''oignon rouge émincé sur deux assiettes. Mélanger le jus du citron vert avec une bonne pincée de sel et de poivre pour la sauce.","Chauffer l''huile dans un wok à feu vif jusqu''à ce qu''elle fume. Ajouter le bœuf en une couche, laisser dorer 1 min, puis secouer et faire sauter 2 à 3 min jusqu''à ce qu''il soit saisi de tous côtés.","Ajouter le beurre, les carrés d''oignon et l''oignon nouveau et faire sauter encore 1 à 2 min, jusqu''à ce que l''oignon soit juste attendri et le bœuf encore rosé à cœur.","Déposer le bœuf sur la salade et servir avec le riz et la sauce citron vert-poivre."]},"it":{"title":"Bò lúc lắc (manzo saltato vietnamita)","steps":["Sciacquare il riso e cuocerlo coperto in 300 ml d''acqua a fuoco basso per 12 min; lasciarlo riposare 5 min fuori dal fuoco.","Mentre cuoce il riso, mescolare il manzo con aglio, salsa d''ostrica, salsa di soia, salsa di pesce, zucchero, amido e mezzo cucchiaino di pepe nero; lasciar riposare 15 min.","Disporre lattuga, pomodorini e cipolla rossa affettata su due piatti. Mescolare il succo del lime con un buon pizzico di sale e di pepe per la salsina.","Scaldare l''olio nel wok a fuoco vivo finché fuma. Aggiungere il manzo in un solo strato, lasciarlo rosolare 1 min, poi scuotere e saltare 2-3 min finché è scottato su tutti i lati.","Aggiungere il burro, i quadrati di cipolla e il cipollotto e saltare ancora 1-2 min, finché la cipolla è appena morbida e il manzo ancora rosa all''interno.","Disporre il manzo sull''insalata e servire con il riso e la salsina di lime e pepe."]}}'::jsonb),
  ('09155c6a-9a2d-49d0-beb9-32ed4b7d3e9e'::uuid, '{"fr":{"title":"Gado-gado aux œufs et au tofu","steps":["Mettre les pommes de terre et les œufs dans une casserole d''eau froide salée, porter à ébullition et cuire 9 min. Sortir les œufs et les plonger dans l''eau froide.","Ajouter les haricots verts aux pommes de terre et cuire encore 4 min, jusqu''à ce que tout soit juste tendre. Les sortir à l''écumoire.","Plonger le chou et les germes de soja 1 min dans la même eau, puis égoutter et presser pour retirer l''excès d''eau.","Chauffer l''huile dans une poêle et faire dorer le tofu 2 à 3 min de chaque côté à feu moyen-vif. L''égoutter sur du papier absorbant.","Essuyer la poêle, puis faire mijoter le beurre de cacahuète, le lait de coco, 80 ml d''eau, l''ail, la pâte de curry, la sauce soja et le sucre 4 à 5 min en remuant, jusqu''à ce que la sauce nappe la cuillère. Ajouter le jus d''un demi-citron vert et le piment, et détendre avec un peu d''eau si besoin.","Écaler les œufs et les couper en deux. Disposer pommes de terre, haricots, chou, germes, concombre, tofu et œufs sur deux assiettes.","Napper de sauce aux cacahuètes tiède, parsemer de cacahuètes et servir avec le reste du citron vert en quartiers."]},"it":{"title":"Gado-gado con uova e tofu","steps":["Mettere le patate e le uova in una pentola di acqua fredda salata, portare a bollore e cuocere 9 min. Trasferire le uova in acqua fredda.","Aggiungere i fagiolini alle patate e cuocere altri 4 min, finché sono appena teneri. Scolarli con una schiumarola.","Tuffare il cavolo e i germogli di soia nella stessa acqua per 1 min, poi scolarli e strizzarli.","Scaldare l''olio in una padella e rosolare il tofu 2-3 min per lato a fuoco medio-alto finché è dorato. Scolarlo su carta assorbente.","Pulire la padella e cuocere a fuoco basso il burro di arachidi, il latte di cocco, 80 ml d''acqua, l''aglio, la pasta di curry, la salsa di soia e lo zucchero per 4-5 min mescolando, finché vela il cucchiaio. Aggiungere il succo di mezzo lime e il peperoncino, e allungare con acqua se serve.","Sgusciare le uova e tagliarle a metà. Disporre patate, fagiolini, cavolo, germogli, cetriolo, tofu e uova su due piatti.","Condire con la salsa di arachidi tiepida, cospargere di arachidi e servire con il resto del lime a spicchi."]}}'::jsonb),
  ('24a6e5dd-6a48-4027-bef7-93b4fbe4694a'::uuid, '{"fr":{"title":"Nouilles de Singapour","steps":["Faire tremper les vermicelles de riz 3 à 4 min dans de l''eau tout juste bouillante (ou selon le paquet), égoutter et rincer à l''eau froide.","Mélanger la sauce soja, le xérès, le curry, le sucre et une bonne pincée de poivre dans un bol.","Chauffer 1 c. à café d''huile dans un wok à feu moyen-vif, verser les œufs et faire une omelette fine. Une fois prise, la rouler, la couper en lanières et réserver.","Ajouter 1 c. à soupe d''huile et faire sauter le porc 2 min jusqu''à ce qu''il ne soit plus rose, puis les crevettes 1 à 2 min jusqu''à ce qu''elles soient juste roses. Réserver avec l''omelette.","Ajouter le reste de l''huile et faire sauter l''oignon, l''ail et le gingembre 1 à 2 min, puis le poivron 1 min.","Ajouter les nouilles et la sauce et mélanger à la pince 1 à 2 min jusqu''à ce qu''elles soient uniformément jaunes.","Remettre le porc, les crevettes et l''omelette avec les germes de soja et l''oignon nouveau, faire sauter 1 min et servir aussitôt."]},"it":{"title":"Noodles di Singapore","steps":["Ammollare i vermicelli di riso 3-4 min in acqua appena bollita (o come indicato sulla confezione), scolarli e sciacquarli sotto l''acqua fredda.","Mescolare la salsa di soia, lo sherry, il curry, lo zucchero e un buon pizzico di pepe in una ciotolina.","Scaldare 1 cucchiaino d''olio nel wok a fuoco medio-alto, versare le uova e farne una frittatina sottile. Quando è rappresa, arrotolarla, tagliarla a striscioline e tenerla da parte.","Aggiungere 1 cucchiaio d''olio e saltare il maiale 2 min finché non è più rosa, poi i gamberi 1-2 min finché diventano appena rosa. Tenere da parte con la frittatina.","Aggiungere l''olio rimasto e saltare cipolla, aglio e zenzero 1-2 min, poi il peperone 1 min.","Aggiungere i noodles e la salsa e mescolare con le pinze 1-2 min finché sono uniformemente gialli.","Rimettere maiale, gamberi e frittatina con i germogli di soia e il cipollotto, saltare 1 min e servire subito."]}}'::jsonb),
  ('903e26bc-8498-48e9-9a80-8ea3175bd84c'::uuid, '{"fr":{"title":"Tofu au gochujang, riz au sésame et concombre","steps":["Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert avec 200 ml d''eau et une pincée de sel 15 min à feu doux ; laisser reposer 10 min hors du feu.","Couper le concombre en deux dans la longueur et l''émincer finement. Le mélanger avec 1 c. à soupe de vinaigre, le sucre et une pincée de sel et laisser mariner.","Fouetter le gochujang, la sauce soja, le miel, la c. à soupe de vinaigre restante, 2 c. à café d''huile de sésame, l''ail, le gingembre et 2 c. à soupe d''eau.","Sécher le tofu et l''enrober de fécule. Le faire dorer dans l''huile végétale à feu moyen-vif 8 à 10 min en le retournant, jusqu''à ce qu''il soit croustillant de tous côtés.","Baisser le feu, verser la sauce et mélanger 1 à 2 min jusqu''à ce qu''elle bouillonne et enrobe le tofu d''un glaçage collant.","Mélanger à la fourchette le reste d''huile de sésame et les graines de sésame dans le riz.","Servir le riz garni de tofu et de concombre égoutté, parsemé d''oignon nouveau."]},"it":{"title":"Tofu al gochujang con riso al sesamo e cetriolo","steps":["Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto con 200 ml d''acqua e un pizzico di sale per 15 min a fuoco basso; lasciarlo riposare 10 min fuori dal fuoco.","Tagliare il cetriolo a metà per il lungo e affettarlo sottile. Condirlo con 1 cucchiaio di aceto, lo zucchero e un pizzico di sale e lasciarlo marinare.","Sbattere il gochujang, la salsa di soia, il miele, il cucchiaio di aceto rimasto, 2 cucchiaini di olio di sesamo, l''aglio, lo zenzero e 2 cucchiai d''acqua.","Asciugare il tofu e passarlo nell''amido. Rosolarlo nell''olio di semi a fuoco medio-alto per 8-10 min, girandolo, finché è croccante e dorato su tutti i lati.","Abbassare il fuoco, versare la salsa e mescolare 1-2 min finché sobbolle e avvolge il tofu in una glassa appiccicosa.","Incorporare con una forchetta l''olio di sesamo rimasto e i semi di sesamo nel riso.","Servire il riso con sopra il tofu e il cetriolo scolato, cosparso di cipollotto."]}}'::jsonb),
  ('e4fbec5b-2877-472e-b90f-9cce17e906d4'::uuid, '{"fr":{"title":"Riz sauté au kimchi, thon, champignons et œuf","steps":["Cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux. L''étaler sur une assiette pour qu''il refroidisse et sèche un peu (le riz de la veille est encore mieux).","Chauffer 1 c. à soupe d''huile dans une grande poêle à feu moyen-vif et faire revenir l''oignon et les champignons 4 à 5 min jusqu''à ce que les champignons soient dorés.","Ajouter le kimchi, le piment et le sucre et faire sauter 3 min jusqu''à ce que le kimchi ramollisse et sente le grillé.","Ajouter le riz, le jus de kimchi et la sauce soja et faire sauter 3 à 4 min en pressant le riz contre la poêle pour qu''il colore.","Incorporer le thon, la moitié de l''oignon nouveau et l''huile de sésame et réchauffer 1 min. Répartir dans deux bols.","Cuire les œufs au plat dans le reste de l''huile 2 à 3 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants.","Garnir chaque bol d''un œuf au plat, du reste d''oignon nouveau et des graines de sésame."]},"it":{"title":"Riso saltato al kimchi con tonno, funghi e uovo","steps":["Cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso. Stenderlo su un piatto perché si raffreddi e si asciughi un po'' (il riso del giorno prima è ancora meglio).","Scaldare 1 cucchiaio d''olio in una padella larga a fuoco medio-alto e rosolare la cipolla e i funghi 4-5 min finché i funghi sono dorati.","Aggiungere il kimchi, il peperoncino e lo zucchero e saltare 3 min finché il kimchi si ammorbidisce e profuma di tostato.","Aggiungere il riso, il succo del kimchi e la salsa di soia e saltare 3-4 min, premendo il riso contro la padella perché prenda colore.","Incorporare il tonno, metà del cipollotto e l''olio di sesamo e scaldare 1 min. Dividere in due ciotole.","Friggere le uova nell''olio rimasto 2-3 min, finché l''albume è rappreso ma il tuorlo ancora morbido.","Completare ogni ciotola con un uovo, il resto del cipollotto e i semi di sesamo."]}}'::jsonb),
  ('18d7da88-e0e2-45d7-9951-6b9728624038'::uuid, '{"fr":{"title":"Japchae","steps":["Mélanger la sauce soja, le sucre, l''huile de sésame, l''ail et beaucoup de poivre. Enrober le bœuf de 1,5 c. à soupe de cette sauce, puis de fécule, et laisser reposer pendant la préparation.","Cuire les nouilles 6 à 7 min dans l''eau bouillante (ou selon le paquet) jusqu''à ce qu''elles soient souples et élastiques. Égoutter, rincer à l''eau froide et les raccourcir aux ciseaux.","Battre les œufs avec une pincée de sel et les cuire en omelette fine dans le wok légèrement huilé à feu moyen, 1 min de chaque côté. La rouler et la couper en fines lanières.","Chauffer 1 c. à café d''huile dans le wok à feu vif et saisir le bœuf en une seule couche, 1 à 2 min de chaque côté, jusqu''à ce qu''il soit doré. Le mettre dans un grand saladier.","Ajouter 1 c. à soupe d''huile et faire revenir les champignons 4 min jusqu''à ce qu''ils soient dorés et secs ; les ajouter au saladier.","Ajouter le reste de l''huile et faire sauter la carotte, l''oignon et l''oignon nouveau avec une pincée de sel 3 min, jusqu''à ce qu''ils soient juste tendres ; les ajouter au saladier.","Faire tomber les épinards 1 min dans le wok chaud, puis les ajouter au saladier avec les nouilles.","Verser le reste de la sauce, ajouter les lanières d''omelette et le sésame et mélanger à la main ou à la pince jusqu''à ce que les nouilles soient brillantes. Servir tiède."]},"it":{"title":"Japchae","steps":["Mescolare la salsa di soia, lo zucchero, l''olio di sesamo, l''aglio e abbondante pepe. Condire il manzo con 1,5 cucchiai di questa salsa, poi con l''amido, e lasciarlo riposare durante la preparazione.","Cuocere i noodles in acqua bollente per 6-7 min (o come indicato sulla confezione) finché sono morbidi ed elastici. Scolarli, sciacquarli in acqua fredda e accorciarli con le forbici.","Sbattere le uova con un pizzico di sale e cuocerle in una frittatina sottile nel wok leggermente unto a fuoco medio, 1 min per lato. Arrotolarla e tagliarla a striscioline.","Scaldare 1 cucchiaino d''olio nel wok a fuoco alto e scottare il manzo in un solo strato, 1-2 min per lato, finché è rosolato. Trasferirlo in una ciotola grande.","Aggiungere 1 cucchiaio d''olio e rosolare i funghi 4 min finché sono dorati e asciutti; unirli alla ciotola.","Aggiungere l''olio rimasto e saltare carota, cipolla e cipollotto con un pizzico di sale per 3 min, finché sono appena teneri; unirli alla ciotola.","Far appassire gli spinaci nel wok caldo per 1 min, poi unirli alla ciotola con i noodles.","Versare la salsa rimasta, aggiungere le striscioline di frittata e il sesamo e mescolare con le mani o le pinze finché i noodles sono lucidi. Servire tiepido."]}}'::jsonb),
  ('a5433dcb-2462-4141-a7c2-64971329e1d1'::uuid, '{"fr":{"title":"Kimchi jjigae","steps":["Cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux, puis le laisser reposer hors du feu.","Mettre la poitrine de porc dans une cocotte à feu moyen et la faire revenir 4 à 5 min en remuant, jusqu''à ce qu''elle rende un peu de gras et dore sur les bords.","Ajouter l''oignon, l''ail, le gingembre et le kimchi et faire sauter 4 min jusqu''à ce que le kimchi soit tendre et parfumé.","Incorporer le piment, le sucre, la sauce soja, le jus de kimchi et 500 ml d''eau. Porter à ébullition, puis laisser mijoter 15 min à couvert partiel.","Poser le tofu dessus, l''arroser d''un peu de bouillon et mijoter encore 5 min, jusqu''à ce que le porc soit tendre et le tofu bien chaud. Goûter et rectifier en sel ou en piment.","Parsemer d''oignon nouveau, arroser d''huile de sésame et servir bouillonnant dans la cocotte, avec le riz."]},"it":{"title":"Kimchi jjigae","steps":["Cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Mettere la pancia di maiale in una pentola dal fondo spesso a fuoco medio e rosolarla 4-5 min mescolando, finché rilascia un po'' di grasso e si colora ai bordi.","Aggiungere cipolla, aglio, zenzero e kimchi e saltare 4 min finché il kimchi è morbido e profumato.","Unire il peperoncino, lo zucchero, la salsa di soia, il succo del kimchi e 500 ml d''acqua. Portare a bollore, poi cuocere a fuoco basso 15 min con il coperchio socchiuso.","Adagiare sopra il tofu, bagnarlo con un po'' di brodo e cuocere altri 5 min, finché il maiale è tenero e il tofu ben caldo. Assaggiare e regolare di sale o peperoncino.","Cospargere di cipollotto, irrorare con l''olio di sesamo e servire fumante nella pentola, con il riso."]}}'::jsonb),
  ('b5aa2a92-5715-4729-9059-11df4a1ed144'::uuid, '{"fr":{"title":"Jeyuk bokkeum","steps":["Mélanger le gochujang, le piment, la sauce soja, le vinaigre, le sucre, le miel, l''huile de sésame, l''ail et le gingembre jusqu''à ce que le sucre soit dissous.","Mélanger le porc, l''oignon et l''oignon nouveau avec la marinade en massant bien. Couvrir et réserver 30 min au frais (jusqu''à quelques heures).","Pendant ce temps, cuire le riz dans 200 ml d''eau, à couvert, 15 min à feu doux, puis le laisser reposer hors du feu.","Chauffer l''huile dans une grande poêle ou un wok à feu vif jusqu''à ce qu''elle frémisse.","Faire sauter le porc en deux fois, 3 à 4 min chaque fois, jusqu''à ce qu''il soit cuit et caramélisé sur les bords ; ne pas surcharger la poêle sinon il bout.","Parsemer de sésame et servir avec le riz et des feuilles de laitue pour faire des wraps."]},"it":{"title":"Jeyuk bokkeum","steps":["Mescolare il gochujang, il peperoncino, la salsa di soia, l''aceto, lo zucchero, il miele, l''olio di sesamo, l''aglio e lo zenzero finché lo zucchero si scioglie.","Condire il maiale, la cipolla e il cipollotto con la marinata, massaggiando bene. Coprire e lasciare in frigo 30 min (fino a qualche ora).","Nel frattempo cuocere il riso in 200 ml d''acqua, coperto, per 15 min a fuoco basso, poi lasciarlo riposare fuori dal fuoco.","Scaldare l''olio in una padella larga o nel wok a fuoco alto finché è ben caldo.","Saltare il maiale in due volte, 3-4 min ciascuna, finché è cotto e caramellato ai bordi; non riempire troppo la padella o il maiale lessa.","Cospargere di sesamo e servire con il riso e foglie di lattuga per avvolgere."]}}'::jsonb),
  ('bb35f3c2-7532-45fa-a110-e430a3f4f1c5'::uuid, '{"fr":{"title":"Andong jjimdak","steps":["Faire tremper les nouilles de patate douce 30 min dans de l''eau tiède pendant la cuisson. Si vous servez du riz, le cuire maintenant (15 min à couvert à feu doux dans 1,3 fois son volume d''eau).","Mélanger la sauce soja, le sucre, la sauce d''huître, l''huile de sésame, l''ail et le gingembre dans un bol.","Chauffer l''huile dans une sauteuse à feu moyen-vif et faire dorer le poulet 5 min en le retournant.","Verser la sauce, 450 ml d''eau et le piment, porter à ébullition et cuire 10 min à bon frémissement.","Ajouter la pomme de terre, la carotte et l''oignon et laisser mijoter 12 à 15 min en remuant de temps en temps, jusqu''à ce que la pomme de terre soit tendre et la sauce réduite d''environ un tiers.","Égoutter les nouilles et les ajouter avec l''oignon nouveau. Cuire 4 à 5 min jusqu''à ce que les nouilles soient brillantes, translucides et aient absorbé un peu de sauce.","Parsemer de sésame et servir aussitôt, avec du riz si on le souhaite."]},"it":{"title":"Andong jjimdak","steps":["Ammollare i noodles di patata dolce in acqua tiepida per 30 min durante la cottura. Se si serve il riso, cuocerlo ora (15 min coperto a fuoco basso in 1,3 volte il suo volume d''acqua).","Mescolare la salsa di soia, lo zucchero, la salsa di ostriche, l''olio di sesamo, l''aglio e lo zenzero in una ciotola.","Scaldare l''olio in una pentola larga a fuoco medio-alto e rosolare il pollo 5 min, girandolo.","Versare la salsa, 450 ml d''acqua e il peperoncino, portare a bollore e cuocere 10 min a sobbollore vivace.","Aggiungere la patata, la carota e la cipolla e cuocere 12-15 min mescolando ogni tanto, finché la patata è tenera e la salsa si è ridotta di circa un terzo.","Scolare i noodles e unirli con il cipollotto. Cuocere 4-5 min finché i noodles sono lucidi, trasparenti e hanno assorbito un po'' di salsa.","Cospargere di sesamo e servire subito, con riso a piacere."]}}'::jsonb),
  ('6bc515fb-1db9-4a26-a278-d6dea10855c3'::uuid, '{"fr":{"title":"Fajitas au poulet et aux poivrons","steps":["Mélanger 1 c. à soupe d''huile avec l''ail, le zeste de citron vert, la moitié du jus, le cumin, l''origan, le piment en poudre, le paprika fumé et 1/2 c. à café de sel. Enrober le poulet et laisser mariner 30 min (ou jusqu''à un jour au frais).","Chauffer le reste de l''huile dans une grande poêle épaisse à feu moyen-vif. Ajouter les poivrons, l''oignon, le sucre et une pincée de sel et cuire 6 à 8 min en remuant, jusqu''à ce qu''ils soient tendres et grillés par endroits.","Verser 3 c. à soupe d''eau pour décoller les sucs, laisser évaporer, puis réserver les légumes sur une assiette.","Cuire le poulet dans la même poêle bien chaude 3 à 4 min de chaque côté, jusqu''à ce qu''il soit bien doré et cuit à cœur. Laisser reposer 3 min, l''émincer et arroser du reste de jus de citron vert.","Réchauffer les tortillas 20 secondes de chaque côté dans une poêle sèche, ou emballées dans du papier aluminium au four doux.","Remettre les poivrons dans la poêle avec le poulet 1 min pour les réchauffer et servir avec les tortillas, le yaourt, l''avocat et la coriandre."]},"it":{"title":"Fajitas di pollo e peperoni","steps":["Mescolare 1 cucchiaio d''olio con l''aglio, la scorza di lime, metà del succo, il cumino, l''origano, il peperoncino in polvere, la paprika affumicata e 1/2 cucchiaino di sale. Condire il pollo e lasciarlo marinare 30 min (o fino a un giorno in frigo).","Scaldare l''olio rimasto in una padella larga dal fondo spesso a fuoco medio-alto. Aggiungere i peperoni, la cipolla, lo zucchero e un pizzico di sale e cuocere 6-8 min mescolando, finché sono morbidi e abbrustoliti qua e là.","Versare 3 cucchiai d''acqua per staccare il fondo, lasciarla evaporare, poi trasferire le verdure su un piatto.","Cuocere il pollo nella stessa padella ben calda 3-4 min per lato finché è ben rosolato e cotto all''interno. Lasciarlo riposare 3 min, tagliarlo a strisce e irrorarlo con il succo di lime rimasto.","Scaldare le tortillas in una padella asciutta 20 secondi per lato, oppure avvolte nell''alluminio in forno basso.","Rimettere i peperoni nella padella con il pollo per 1 min e servire con le tortillas, lo yogurt, l''avocado e il coriandolo."]}}'::jsonb),
  ('2484fa78-780d-4b2b-9a12-2d64bc9f6410'::uuid, '{"fr":{"title":"Chili aux haricots noirs et patate douce","steps":["Chauffer l''huile dans une grande cocotte à feu moyen et faire fondre l''oignon 6 à 7 min.","Ajouter la patate douce, l''ail, le piment en poudre, le cumin, le paprika fumé et l''origan et remuer 2 min jusqu''à ce que les épices sentent le grillé.","Ajouter les haricots noirs, les tomates et le bouillon et porter à ébullition.","Couvrir, baisser le feu et laisser mijoter 25 min en remuant de temps en temps, jusqu''à ce que la patate douce soit tendre. Découvrir les 5 dernières minutes pour un chili plus épais.","Saler et ajouter le jus d''un demi-citron vert ; écraser quelques haricots contre la paroi pour épaissir.","Servir garni de yaourt, d''avocat, de coriandre et du reste du citron vert en quartiers."]},"it":{"title":"Chili di fagioli neri e patate dolci","steps":["Scaldare l''olio in una pentola capiente a fuoco medio e far appassire la cipolla 6-7 min.","Aggiungere la patata dolce, l''aglio, il peperoncino in polvere, il cumino, la paprika affumicata e l''origano e mescolare 2 min finché le spezie profumano di tostato.","Aggiungere i fagioli neri, i pomodori e il brodo e portare a bollore.","Coprire, abbassare il fuoco e cuocere 25 min mescolando ogni tanto, finché la patata dolce è tenera. Scoprire negli ultimi 5 min per un chili più denso.","Salare e aggiungere il succo di mezzo lime; schiacciare qualche fagiolo contro la pentola per addensare.","Servire con lo yogurt, l''avocado, il coriandolo e il resto del lime a spicchi."]}}'::jsonb),
  ('dbb3e9ce-6c2a-4fd6-855e-868e35eb2ecb'::uuid, '{"fr":{"title":"Quesadillas aux haricots noirs et poivron","steps":["Chauffer l''huile dans une grande poêle à feu moyen et cuire le poivron et l''oignon 5 min jusqu''à ce qu''ils soient tendres.","Ajouter les haricots, le maïs, le cumin et le piment et cuire 3 min en écrasant légèrement un tiers des haricots, jusqu''à ce que le liquide soit évaporé. Assaisonner et ajouter l''oignon nouveau. Verser dans un bol et essuyer la poêle.","Mélanger la tomate avec un filet de citron vert, une pincée de sel et la coriandre pour une salsa rapide.","Parsemer un quart du fromage sur une moitié de chaque tortilla, répartir la garniture aux haricots et finir avec le reste du fromage. Replier et presser légèrement.","Cuire les quesadillas deux par deux dans la poêle sèche à feu moyen-doux, 2 à 3 min de chaque côté, jusqu''à ce qu''elles soient dorées et le fromage fondu.","Couper en parts et servir avec la salsa, le yaourt et des quartiers de citron vert."]},"it":{"title":"Quesadillas di fagioli neri e peperoni","steps":["Scaldare l''olio in una padella larga a fuoco medio e cuocere il peperone e la cipolla 5 min finché sono morbidi.","Aggiungere i fagioli, il mais, il cumino e il peperoncino e cuocere 3 min schiacciando leggermente un terzo dei fagioli, finché l''umidità è evaporata. Regolare di sale e unire il cipollotto. Trasferire in una ciotola e pulire la padella.","Mescolare il pomodoro con un po'' di succo di lime, un pizzico di sale e il coriandolo per una salsa veloce.","Distribuire un quarto del formaggio su metà di ogni tortilla, aggiungere il ripieno di fagioli e finire con il formaggio rimasto. Ripiegare e premere leggermente.","Cuocere le quesadillas due alla volta nella padella asciutta a fuoco medio-basso, 2-3 min per lato, finché sono dorate e il formaggio è fuso.","Tagliare a spicchi e servire con la salsa, lo yogurt e spicchi di lime."]}}'::jsonb),
  ('e65fe071-853c-4a03-a5e5-5f8a90979328'::uuid, '{"fr":{"title":"Tacos de crevettes fumés, chou et avocat","steps":["Mélanger les crevettes avec le paprika fumé, le cumin, le piment en poudre, l''origan, l''ail, la moitié de l''huile et une pincée de sel.","Mélanger le chou avec le jus d''un citron vert et une pincée de sel juste avant de garnir, pour qu''il reste croquant.","Mélanger le yaourt avec la sauce piquante et un filet de citron vert.","Réchauffer les tortillas dans une poêle sèche, 20 secondes de chaque côté, et les garder enveloppées dans un torchon.","Chauffer le reste de l''huile dans la poêle à feu vif et cuire les crevettes 1 à 2 min de chaque côté, jusqu''à ce qu''elles soient roses et légèrement grillées.","Garnir les tortillas de chou, de crevettes et d''avocat, napper de yaourt fumé et finir avec la coriandre et des quartiers de citron vert."]},"it":{"title":"Tacos di gamberi affumicati con cavolo e avocado","steps":["Condire i gamberi con la paprika affumicata, il cumino, il peperoncino in polvere, l''origano, l''aglio, metà dell''olio e un pizzico di sale.","Condire il cavolo con il succo di un lime e un pizzico di sale appena prima di farcire, perché resti croccante.","Mescolare lo yogurt con la salsa piccante e un po'' di succo di lime.","Scaldare le tortillas in una padella asciutta, 20 secondi per lato, e tenerle avvolte in un canovaccio.","Scaldare l''olio rimasto nella padella a fuoco alto e cuocere i gamberi 1-2 min per lato finché sono rosa e leggermente abbrustoliti.","Farcire le tortillas con cavolo, gamberi e avocado, condire con lo yogurt affumicato e finire con coriandolo e spicchi di lime."]}}'::jsonb),
  ('d2793b68-f90b-4f5f-9649-da6b652d910a'::uuid, '{"fr":{"title":"Burgers de patate douce et haricots noirs","steps":["Préchauffer le four à 200 °C. Couper la patate douce en deux, la frotter d''un peu d''huile et la rôtir face coupée vers le bas sur une plaque chemisée 30 min, jusqu''à ce qu''elle soit très tendre.","Pendant ce temps, cuire le quinoa dans 100 ml d''eau à couvert 15 min, jusqu''à absorption ; laisser refroidir.","Récupérer la chair de la patate douce dans un saladier et l''écraser. Ajouter les haricots et en écraser la moitié à la fourchette.","Incorporer le quinoa, l''œuf, la chapelure, l''oignon nouveau, le cumin, le paprika fumé, le sel et le poivre. Le mélange doit se tenir ; ajouter un peu de chapelure s''il est trop humide.","Baisser le four à 190 °C. Former 2 grands ou 4 petits steaks d''environ 2 cm d''épaisseur sur la plaque huilée et badigeonner le dessus d''huile.","Cuire 25 min en les retournant délicatement une fois après 15 min, jusqu''à ce qu''ils soient fermes et dorés. Laisser reposer 5 min pour qu''ils se raffermissent.","Mélanger le yaourt avec un filet de citron vert et une pincée de sel.","Garnir les pains grillés de salade, des steaks, de tomate, d''avocat et du yaourt au citron vert."]},"it":{"title":"Burger di patate dolci e fagioli neri","steps":["Scaldare il forno a 200 °C. Tagliare a metà la patata dolce, ungerla con un filo d''olio e arrostirla con il lato tagliato verso il basso su una teglia foderata per 30 min, finché è morbidissima.","Nel frattempo cuocere la quinoa in 100 ml d''acqua, coperta, per 15 min finché l''acqua è assorbita; lasciarla raffreddare.","Raccogliere la polpa della patata dolce in una ciotola e schiacciarla. Aggiungere i fagioli e schiacciarne metà con una forchetta.","Incorporare la quinoa, l''uovo, il pangrattato, il cipollotto, il cumino, la paprika affumicata, sale e pepe. L''impasto deve stare insieme; aggiungere un po'' di pangrattato se è troppo umido.","Abbassare il forno a 190 °C. Formare 2 burger grandi o 4 piccoli spessi circa 2 cm sulla teglia unta e spennellarli d''olio.","Cuocere 25 min girandoli con delicatezza una volta dopo 15 min, finché sono sodi e dorati. Lasciarli riposare 5 min perché si rassodino.","Mescolare lo yogurt con un po'' di succo di lime e un pizzico di sale.","Farcire i panini tostati con lattuga, burger, pomodoro, avocado e yogurt al lime."]}}'::jsonb),
  ('1ce30af4-0557-44c0-90a7-943b7db38432'::uuid, '{"fr":{"title":"Enchiladas au poulet et poivrons rôtis","steps":["Préchauffer le four à 200 °C. Mélanger les poivrons et l''oignon avec la moitié de l''huile et une pincée de sel et les rôtir sur une plaque 20 min, jusqu''à ce qu''ils soient tendres et grillés sur les bords.","Pendant ce temps, mettre le poulet dans une petite casserole avec le bouillon, porter à frémissement et pocher 12 à 15 min jusqu''à cuisson complète. Le sortir, garder 150 ml de bouillon et effilocher le poulet avec deux fourchettes.","Pour la sauce, chauffer le reste de l''huile dans la casserole et faire revenir l''ail, le cumin, le piment et l''origan 1 min. Ajouter les tomates et le bouillon réservé et laisser mijoter 10 min jusqu''à ce que la sauce épaississe un peu ; assaisonner.","Mélanger le poulet et les poivrons rôtis avec 4 c. à soupe de sauce. Baisser le four à 180 °C.","Étaler quelques cuillerées de sauce dans un plat à gratin. Garnir chaque tortilla du mélange au poulet, la rouler serré et la poser jointure en dessous dans le plat.","Verser le reste de la sauce et parsemer de cheddar.","Enfourner 20 min jusqu''à ce que le fromage soit fondu et la sauce bouillonne sur les bords. Servir avec l''oignon nouveau et la crème fraîche."]},"it":{"title":"Enchiladas di pollo e peperoni arrosto","steps":["Scaldare il forno a 200 °C. Condire i peperoni e la cipolla con metà dell''olio e un pizzico di sale e arrostirli su una teglia per 20 min, finché sono morbidi e abbrustoliti ai bordi.","Nel frattempo mettere il pollo in un pentolino con il brodo, portare a leggero sobbollore e cuocerlo 12-15 min finché è cotto. Toglierlo, tenere 150 ml di brodo e sfilacciare il pollo con due forchette.","Per la salsa, scaldare l''olio rimasto nel pentolino e soffriggere l''aglio, il cumino, il peperoncino e l''origano 1 min. Aggiungere i pomodori e il brodo tenuto da parte e cuocere 10 min finché si addensa un po''; regolare di sale.","Mescolare il pollo e i peperoni arrosto con 4 cucchiai di salsa. Abbassare il forno a 180 °C.","Stendere qualche cucchiaio di salsa in una pirofila. Farcire ogni tortilla con il pollo, arrotolarla stretta e disporla in pirofila con la chiusura sotto.","Versare sopra la salsa rimasta e cospargere di cheddar.","Infornare 20 min finché il formaggio è fuso e la salsa sobbolle ai bordi. Servire con cipollotto e crème fraîche."]}}'::jsonb),
  ('458a777c-279e-44f9-b835-9a4c4c9a99a5'::uuid, '{"fr":{"title":"Burritos à la courge rôtie et aux haricots noirs","steps":["Préchauffer le four à 200 °C. Mélanger la courge avec 1 c. à soupe d''huile, la moitié du cumin, le paprika fumé, le piment et du sel et la rôtir 25 à 30 min en la retournant une fois, jusqu''à ce qu''elle soit tendre et caramélisée.","Pendant ce temps, cuire le riz dans 160 ml d''eau salée à couvert 12 min ; laisser reposer 5 min puis l''égrener avec un filet de citron vert et la coriandre.","Chauffer le reste de l''huile dans une poêle et faire fondre l''oignon 4 min. Ajouter l''ail, le reste du cumin et les haricots avec 3 c. à soupe d''eau et cuire 4 min en écrasant légèrement, jusqu''à ce que ce soit épais. Assaisonner et ajouter du jus de citron vert.","Réchauffer les tortillas dans une poêle sèche ou 2 min au four dans du papier aluminium.","Au centre de chaque tortilla, superposer riz, haricots, courge, épinards, feta et une cuillerée de yaourt.","Rabattre les côtés, rouler serré et faire griller jointure en dessous dans la poêle sèche 1 à 2 min de chaque côté. Couper en deux et servir avec le reste du yaourt."]},"it":{"title":"Burritos di zucca arrosto e fagioli neri","steps":["Scaldare il forno a 200 °C. Condire la zucca con 1 cucchiaio d''olio, metà del cumino, la paprika affumicata, il peperoncino e sale e arrostirla 25-30 min girandola una volta, finché è tenera e caramellata.","Nel frattempo cuocere il riso in 160 ml d''acqua salata, coperto, per 12 min; lasciarlo riposare 5 min, poi sgranarlo con un po'' di succo di lime e il coriandolo.","Scaldare l''olio rimasto in una padella e far appassire la cipolla 4 min. Aggiungere l''aglio, il cumino rimasto e i fagioli con 3 cucchiai d''acqua e cuocere 4 min schiacciando leggermente, finché è denso. Regolare di sale e aggiungere succo di lime.","Scaldare le tortillas in una padella asciutta o avvolte nell''alluminio in forno per 2 min.","Al centro di ogni tortilla stendere riso, fagioli, zucca, spinaci, feta e un cucchiaio di yogurt.","Ripiegare i lati, arrotolare stretto e tostare con la chiusura sotto nella padella asciutta 1-2 min per lato. Tagliare a metà e servire con lo yogurt rimasto."]}}'::jsonb),
  ('8af92bc9-e7f4-4b51-b5c5-f3e158947f63'::uuid, '{"fr":{"title":"Bowls burrito au bœuf et aux haricots noirs","steps":["Cuire le riz dans 280 ml d''eau salée à couvert 12 min ; laisser reposer 5 min, puis l''égrener à la fourchette avec le jus d''un citron vert et la moitié de la coriandre.","Pendant ce temps, chauffer l''huile dans une poêle à feu moyen et faire fondre l''oignon 4 min.","Monter le feu, ajouter le bœuf et le faire dorer 5 à 6 min en l''émiettant, jusqu''à ce qu''il ne soit plus rose.","Ajouter l''ail, les épices et le concentré de tomate 1 min, puis 60 ml d''eau et laisser mijoter 2 à 3 min jusqu''à obtenir une viande nappée. Assaisonner.","Mélanger les haricots, le maïs et la tomate avec le jus d''un demi-citron vert et une pincée de sel.","Répartir le riz dans deux bols et garnir de bœuf, de salsa aux haricots, de salade et d''avocat.","Finir avec le cheddar, une cuillerée de yaourt, le reste de la coriandre et des quartiers de citron vert."]},"it":{"title":"Burrito bowl di manzo e fagioli neri","steps":["Cuocere il riso in 280 ml d''acqua salata, coperto, per 12 min; lasciarlo riposare 5 min, poi sgranarlo con il succo di un lime e metà del coriandolo.","Nel frattempo scaldare l''olio in una padella a fuoco medio e far appassire la cipolla 4 min.","Alzare il fuoco, aggiungere il manzo e rosolarlo 5-6 min sgranandolo, finché non è più rosa.","Unire l''aglio, le spezie e il concentrato di pomodoro per 1 min, poi 60 ml d''acqua e cuocere 2-3 min finché è ben condito. Regolare di sale.","Mescolare i fagioli, il mais e il pomodoro con il succo di mezzo lime e un pizzico di sale.","Dividere il riso in due ciotole e completare con il manzo, la salsa di fagioli, la lattuga e l''avocado.","Finire con il cheddar, un cucchiaio di yogurt, il coriandolo rimasto e spicchi di lime."]}}'::jsonb),
  ('1c8911ac-cb21-4de7-afe8-c3501009222f'::uuid, '{"fr":{"title":"Lomo saltado","steps":["Préchauffer le four à 220 °C et cuire les frites sur une plaque 20 min en les retournant une fois, jusqu''à ce qu''elles soient croustillantes.","Pendant ce temps, cuire le riz dans 240 ml d''eau salée à couvert 12 min, puis le laisser reposer hors du feu.","Mélanger le bœuf avec le cumin, la moitié du vinaigre, la moitié de la sauce soja, du poivre et une pincée de sel ; laisser 10 min.","Chauffer 1 c. à soupe d''huile dans un wok à feu très vif. Égoutter le bœuf et le saisir en deux fois, 2 min par fournée, jusqu''à ce qu''il soit doré dehors et rosé dedans. Réserver.","Ajouter le reste de l''huile et faire sauter l''oignon, l''ail et le piment 1 min, en gardant l''oignon croquant.","Ajouter les tomates, le reste du vinaigre et de la sauce soja et le bouillon et faire sauter 30 secondes, juste jusqu''à ce que les tomates commencent à ramollir.","Remettre le bœuf avec son jus, ajouter les frites et mélanger 15 secondes. Parsemer de persil et servir aussitôt avec le riz."]},"it":{"title":"Lomo saltado","steps":["Scaldare il forno a 220 °C e cuocere le patatine su una teglia per 20 min, girandole una volta, finché sono croccanti.","Nel frattempo cuocere il riso in 240 ml d''acqua salata, coperto, per 12 min, poi lasciarlo riposare fuori dal fuoco.","Condire il manzo con il cumino, metà dell''aceto, metà della salsa di soia, pepe e un pizzico di sale; lasciarlo 10 min.","Scaldare 1 cucchiaio d''olio nel wok a fuoco vivissimo. Scolare il manzo dalla marinata e scottarlo in due volte, 2 min per volta, finché è rosolato fuori e rosato dentro. Tenerlo da parte.","Aggiungere l''olio rimasto e saltare cipolla, aglio e peperoncino 1 min, lasciando la cipolla croccante.","Aggiungere i pomodori, il resto dell''aceto e della salsa di soia e il brodo e saltare 30 secondi, finché i pomodori iniziano appena ad ammorbidirsi.","Rimettere il manzo con il suo sugo, aggiungere le patatine e mescolare 15 secondi. Cospargere di prezzemolo e servire subito con il riso."]}}'::jsonb),
  ('40812162-f84f-4848-8ce1-d2dcbc36e3ee'::uuid, '{"fr":{"title":"Ropa vieja","steps":["Saler et poivrer le bœuf.","Chauffer l''huile dans une cocotte à feu moyen et faire fondre l''oignon et les poivrons 4 min. Réserver un tiers des poivrons pour la fin.","Ajouter l''ail, l''origan, le cumin, le paprika et le laurier 1 min, puis verser le vin et laisser bouillonner 1 min.","Ajouter le coulis de tomate et le bouillon, enfoncer le bœuf pour qu''il soit couvert et porter à frémissement.","Couvrir en laissant le couvercle entrouvert et laisser mijoter très doucement 2 heures, en ajoutant un peu d''eau si besoin, jusqu''à ce que le bœuf s''effiloche facilement.","Sortir le bœuf, retirer le laurier et effilocher la viande en fins filaments avec deux fourchettes.","Remettre le bœuf dans la cocotte avec les poivrons réservés, les olives et le vinaigre et laisser mijoter 15 min à découvert jusqu''à ce que la sauce enrobe la viande. Rectifier l''assaisonnement.","Environ 20 min avant la fin, cuire le riz dans 280 ml d''eau salée à couvert 12 min, laisser reposer 5 min et servir avec la ropa vieja."]},"it":{"title":"Ropa vieja","steps":["Salare e pepare il manzo.","Scaldare l''olio in una pentola dal fondo spesso a fuoco medio e far appassire la cipolla e i peperoni 4 min. Tenere da parte un terzo dei peperoni per la fine.","Unire l''aglio, l''origano, il cumino, la paprika e l''alloro per 1 min, poi versare il vino e farlo sobbollire 1 min.","Aggiungere la passata e il brodo, immergere il manzo in modo che sia coperto e portare a sobbollore.","Coprire lasciando il coperchio socchiuso e cuocere a fuoco dolcissimo per 2 ore, aggiungendo un goccio d''acqua se serve, finché il manzo si sfilaccia facilmente.","Togliere il manzo, eliminare l''alloro e sfilacciare la carne a fili sottili con due forchette.","Rimettere il manzo nella pentola con i peperoni tenuti da parte, le olive e l''aceto e cuocere scoperto 15 min finché la salsa avvolge la carne. Regolare di sale e pepe.","Circa 20 min prima della fine, cuocere il riso in 280 ml d''acqua salata, coperto, per 12 min, lasciarlo riposare 5 min e servirlo con la ropa vieja."]}}'::jsonb),
  ('0d15fc3d-576a-46cd-a6a3-ff2552e7beea'::uuid, '{"fr":{"title":"Tacos de carnitas","steps":["Préchauffer le four à 150 °C. Retirer le gras épais du porc en laissant une fine couche.","Mettre le porc dans une cocotte allant au four avec le zeste et le jus d''orange, le jus d''un citron vert, le laurier, le cumin, l''origan, l''ail, les morceaux d''oignon, 1 c. à café de sel, du poivre et 400 ml d''eau.","Porter à frémissement sur le feu, couvrir et braiser au four 2 heures jusqu''à ce que le porc soit très tendre.","Sortir le porc sur une plaque chemisée. Faire bouillir le jus de cuisson à découvert 8 à 10 min jusqu''à ce qu''il soit réduit à quelques cuillerées sirupeuses.","Effilocher le porc en gros morceaux, le mélanger avec le jus réduit et l''étaler sur la plaque.","Passer le four en position gril et griller le porc à 10-15 cm de la résistance 5 à 8 min en le retournant une fois, jusqu''à ce qu''il soit croustillant sur les bords. Surveiller de près.","Réchauffer les tortillas dans une poêle sèche et les garnir de carnitas, d''oignon haché, d''avocat et de coriandre. Servir avec des quartiers de citron vert et de la sauce piquante."]},"it":{"title":"Tacos di carnitas","steps":["Scaldare il forno a 150 °C. Eliminare il grasso spesso dal maiale lasciandone uno strato sottile.","Mettere il maiale in una pentola con coperchio adatta al forno con la scorza e il succo d''arancia, il succo di un lime, l''alloro, il cumino, l''origano, l''aglio, i pezzi di cipolla, 1 cucchiaino di sale, pepe e 400 ml d''acqua.","Portare a sobbollore sul fuoco, coprire e brasare in forno per 2 ore finché il maiale è tenerissimo.","Trasferire il maiale su una teglia foderata. Far bollire vivacemente il liquido di cottura, scoperto, per 8-10 min finché si riduce a pochi cucchiai sciropposi.","Sfilacciare il maiale a pezzi grossi, condirlo con il liquido ridotto e stenderlo sulla teglia.","Passare il forno in modalità grill e grigliare il maiale a 10-15 cm dalla resistenza per 5-8 min, girandolo una volta, finché è croccante ai bordi. Sorvegliarlo da vicino.","Scaldare le tortillas in una padella asciutta e farcirle con le carnitas, la cipolla tritata, l''avocado e il coriandolo. Servire con spicchi di lime e salsa piccante."]}}'::jsonb),
  ('96b56819-e22c-40cb-a356-bfd932ee56c1'::uuid, '{"fr":{"title":"Sopa de tortilla au poulet","steps":["Porter le bouillon à frémissement dans une grande casserole, ajouter le poulet et le pocher doucement 15 min jusqu''à cuisson complète. Le sortir, l''effilocher et garder le bouillon.","Pendant ce temps, préchauffer le four à 200 °C. Mélanger les lanières de tortilla avec un peu d''huile et une pincée de sel et les cuire sur une plaque 8 à 10 min en les remuant une fois, jusqu''à ce qu''elles soient dorées et croustillantes.","Mixer les tomates, l''oignon, l''ail, le piment, le paprika fumé et l''origan avec une louche de bouillon jusqu''à obtenir une purée bien lisse.","Chauffer l''huile dans une seconde casserole à feu moyen-vif, verser la purée (elle éclabousse) et cuire 8 à 10 min en remuant, jusqu''à ce qu''elle soit épaisse et plus foncée.","Verser la base tomatée dans le bouillon, laisser mijoter 10 min et assaisonner avec du sel et un filet de citron vert.","Remettre le poulet dans la soupe pour le réchauffer.","Mettre les lanières de tortilla dans les bols, verser la soupe et garnir d''avocat, de feta, de crème fraîche, de coriandre et de quartiers de citron vert."]},"it":{"title":"Sopa de tortilla con pollo","steps":["Portare il brodo a sobbollore in una pentola capiente, aggiungere il pollo e cuocerlo dolcemente 15 min finché è cotto. Toglierlo, sfilacciarlo e tenere il brodo.","Nel frattempo scaldare il forno a 200 °C. Condire le strisce di tortilla con un filo d''olio e un pizzico di sale e cuocerle su una teglia 8-10 min, scuotendole una volta, finché sono dorate e croccanti.","Frullare i pomodori, la cipolla, l''aglio, il peperoncino, la paprika affumicata e l''origano con un mestolo di brodo fino a ottenere una purea liscia.","Scaldare l''olio in una seconda pentola a fuoco medio-alto, versare la purea (schizza) e cuocerla 8-10 min mescolando, finché è densa e più scura.","Versare la base di pomodoro nel brodo, cuocere 10 min e regolare con sale e un po'' di succo di lime.","Rimettere il pollo nella zuppa per scaldarlo.","Mettere le strisce di tortilla nelle ciotole, versare la zuppa e completare con avocado, feta, crème fraîche, coriandolo e spicchi di lime."]}}'::jsonb),
  ('117b8579-55c5-4e44-8073-d822afcd3fca'::uuid, '{"fr":{"title":"Ceviche à la patate douce","steps":["Cuire les rondelles de patate douce 12 à 15 min dans de l''eau salée, juste tendres. Égoutter et laisser refroidir complètement au frais.","Faire tremper l''oignon émincé 10 min dans de l''eau glacée, puis bien égoutter.","Préparer le leche de tigre : râper l''ail et le gingembre, hacher finement le céleri et les tiges de coriandre, et les mélanger au jus de citron vert avec 1 c. à café de sel et 2 c. à soupe d''eau froide. Laisser 5 min, puis filtrer.","Couper le poisson en cubes de 2 cm et le mettre dans un saladier froid. Saler légèrement et ajouter le piment.","Verser le leche de tigre sur le poisson et mélanger. Laisser 3 à 5 min, jusqu''à ce que l''extérieur des cubes devienne opaque.","Incorporer l''oignon et les feuilles de coriandre. Goûter et rectifier en sel ou en citron vert.","Servir aussitôt avec le jus, la patate douce froide et le maïs à côté."]},"it":{"title":"Ceviche con patata dolce","steps":["Lessare le rondelle di patata dolce in acqua salata per 12-15 min, finché sono appena tenere. Scolarle e farle raffreddare completamente in frigo.","Mettere in ammollo la cipolla affettata in acqua ghiacciata per 10 min, poi scolarla bene.","Preparare la leche de tigre: grattugiare l''aglio e lo zenzero, tritare finemente il sedano e i gambi di coriandolo e mescolarli al succo di lime con 1 cucchiaino di sale e 2 cucchiai di acqua fredda. Lasciare 5 min, poi filtrare.","Tagliare il pesce a cubetti di 2 cm e metterlo in una ciotola fredda. Salare leggermente e aggiungere il peperoncino.","Versare la leche de tigre sul pesce e mescolare. Lasciare 3-5 min, finché l''esterno dei cubetti diventa opaco.","Unire la cipolla e le foglie di coriandolo. Assaggiare e regolare di sale o lime.","Servire subito con il suo succo, la patata dolce fredda e il mais a parte."]}}'::jsonb),
  ('674abcb4-f1db-4f7d-b760-966a0e335502'::uuid, '{"fr":{"title":"Steak au chimichurri et pommes de terre","steps":["Préparer le chimichurri : mélanger le persil haché au couteau, l''ail, l''origan, le piment, 1,5 c. à soupe de vinaigre et 3 c. à soupe d''huile avec sel et poivre. Laisser reposer au moins 20 min.","Sortir le steak du réfrigérateur 30 min avant la cuisson, l''éponger et bien le saler.","Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres. Égoutter et laisser sécher à la vapeur.","Faire dorer les pommes de terre dans une poêle avec 1 c. à soupe d''huile à feu moyen-vif, 8 min, en les retournant. Garder au chaud.","Essuyer la poêle et la chauffer jusqu''à ce qu''elle fume. Saisir le steak 3 à 4 min de chaque côté pour une cuisson saignante (52-55 °C à cœur). Laisser reposer 5 à 10 min.","Trancher les tomates et l''oignon, assaisonner avec du sel, le reste du vinaigre et un filet d''huile.","Trancher le steak contre le fil, napper de chimichurri et servir avec les pommes de terre et la salade de tomates."]},"it":{"title":"Bistecca al chimichurri con patate","steps":["Preparare il chimichurri: mescolare il prezzemolo tritato a coltello, l''aglio, l''origano, il peperoncino, 1,5 cucchiai di aceto e 3 cucchiai d''olio con sale e pepe. Lasciare riposare almeno 20 min.","Togliere la bistecca dal frigo 30 min prima della cottura, asciugarla e salarla bene.","Lessare le patate in acqua salata per 15 min, finché sono tenere. Scolarle e lasciarle asciugare.","Rosolare le patate in padella con 1 cucchiaio d''olio a fuoco medio-alto per 8 min, girandole. Tenerle in caldo.","Pulire la padella e scaldarla finché fuma. Scottare la bistecca 3-4 min per lato per una cottura al sangue (52-55 °C al cuore). Lasciarla riposare 5-10 min.","Affettare i pomodori e la cipolla e condirli con sale, il resto dell''aceto e un filo d''olio.","Tagliare la bistecca contro fibra, condirla con il chimichurri e servirla con le patate e l''insalata di pomodori."]}}'::jsonb),
  ('8660ca5e-d5ae-4f8c-8013-fc19defba212'::uuid, '{"fr":{"title":"Picadillo cubain et riz","steps":["Rincer le riz, le mettre dans une casserole avec 300 ml d''eau et une pincée de sel, couvrir et cuire à feu doux 12 min. Laisser reposer 5 min hors du feu.","Pendant ce temps, faire revenir l''oignon et le poivron dans 1 c. à soupe d''huile à feu moyen 5 min. Ajouter l''ail 1 min.","Ajouter le bœuf et l''émietter. Cuire 5 min jusqu''à ce qu''il ne soit plus rosé.","Ajouter le cumin, l''origan et le laurier, verser le vin et laisser bouillonner 1 min.","Ajouter le coulis de tomate et les raisins secs et laisser mijoter 10 min à découvert, en remuant de temps en temps, jusqu''à ce que ce soit épais.","Incorporer les olives, les câpres et le vinaigre, puis saler et poivrer.","Servir le picadillo sur le riz."]},"it":{"title":"Picadillo cubano con riso","steps":["Sciacquare il riso, metterlo in una pentola con 300 ml d''acqua e un pizzico di sale, coprire e cuocere a fuoco basso 12 min. Lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo, appassire la cipolla e il peperone in 1 cucchiaio d''olio a fuoco medio per 5 min. Aggiungere l''aglio per 1 min.","Aggiungere la carne e sgranarla. Cuocere 5 min finché non è più rosa.","Unire il cumino, l''origano e l''alloro, versare il vino e lasciarlo sfumare 1 min.","Aggiungere la passata e l''uvetta e cuocere scoperto 10 min, mescolando ogni tanto, finché si addensa.","Unire le olive, i capperi e l''aceto, e regolare di sale e pepe.","Servire il picadillo sul riso."]}}'::jsonb),
  ('a3d15426-1a21-4284-8cf5-5d39c27353d5'::uuid, '{"fr":{"title":"Chowder de haddock fumé et maïs","steps":["Faire fondre le beurre dans une casserole et faire suer l''oignon, le céleri et la pomme de terre à feu doux 10 min, sans coloration.","Verser le bouillon et le lait et porter à petits frémissements. Cuire 15 min, jusqu''à ce que la pomme de terre soit tendre, sans faire bouillir fort.","Écraser quelques morceaux de pomme de terre contre la paroi pour épaissir la soupe.","Ajouter le maïs, poser le haddock dessus et le pocher très doucement 5 min, jusqu''à ce qu''il s''effeuille.","Défaire le poisson en gros morceaux et poivrer. Goûter avant de saler, le poisson fumé est déjà salé.","Servir dans des bols, parsemé de persil."]},"it":{"title":"Chowder di eglefino affumicato e mais","steps":["Sciogliere il burro in una pentola e stufare cipolla, sedano e patata a fuoco basso per 10 min senza farli colorire.","Versare il brodo e il latte e portare a un leggero bollore. Cuocere 15 min finché la patata è tenera, senza far bollire forte.","Schiacciare qualche pezzo di patata contro la parete della pentola per addensare la zuppa.","Aggiungere il mais, adagiare sopra l''eglefino e farlo cuocere molto dolcemente per 5 min, finché si sfalda.","Spezzare il pesce in grosse scaglie e pepare. Assaggiare prima di salare, perché il pesce affumicato è già sapido.","Servire nelle ciotole con il prezzemolo."]}}'::jsonb),
  ('f9ed364b-8350-45b8-ac5b-aca582be6f94'::uuid, '{"fr":{"title":"Croquettes de saumon, petits pois et yaourt citronné","steps":["Cuire les pommes de terre 12 à 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres. Égoutter, laisser sécher 2 min, puis écraser grossièrement.","Pendant ce temps, pocher le saumon dans une poêle d''eau à peine frémissante 6 à 8 min, juste cuit. Égoutter et effeuiller.","Mélanger la purée, le saumon, le zeste de citron, les oignons nouveaux, la moitié de l''aneth, sel et poivre. Former 4 galettes d''environ 3 cm d''épaisseur et les réfrigérer 15 min.","Fariner les galettes, les tremper dans l''œuf, puis les enrober de chapelure.","Essuyer la poêle, chauffer l''huile à feu moyen et cuire les croquettes 4 min de chaque côté, jusqu''à ce qu''elles soient dorées et chaudes à cœur.","Cuire les petits pois 3 min dans de l''eau bouillante, égoutter et assaisonner.","Mélanger le yaourt avec 1 c. à soupe de jus de citron, le reste de l''aneth et une pincée de sel.","Servir les croquettes avec les petits pois, le yaourt citronné et des quartiers de citron."]},"it":{"title":"Polpette di salmone con piselli e yogurt al limone","steps":["Lessare le patate in acqua salata per 12-15 min finché sono tenere. Scolarle, lasciarle asciugare 2 min e schiacciarle grossolanamente.","Nel frattempo cuocere il salmone in una padella d''acqua appena sobbollente per 6-8 min, finché è appena cotto. Scolarlo e sfaldarlo.","Mescolare le patate, il salmone, la scorza di limone, i cipollotti, metà dell''aneto, sale e pepe. Formare 4 tortini spessi circa 3 cm e farli riposare in frigo 15 min.","Infarinare i tortini, passarli nell''uovo e poi nel pangrattato.","Pulire la padella, scaldare l''olio a fuoco medio e cuocere i tortini 4 min per lato, finché sono dorati e caldi all''interno.","Cuocere i piselli in acqua bollente per 3 min, scolarli e condirli.","Mescolare lo yogurt con 1 cucchiaio di succo di limone, il resto dell''aneto e un pizzico di sale.","Servire i tortini con i piselli, lo yogurt al limone e spicchi di limone."]}}'::jsonb),
  ('b76ef299-3036-48ea-94ff-e8d5f575d475'::uuid, '{"fr":{"title":"Saucisses et légumes racines rôtis à la plaque","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante).","Mélanger les panais, les carottes, les pommes de terre et l''oignon avec l''huile, le thym, le sel et le poivre sur une grande plaque, en une seule couche.","Rôtir 20 min.","Retourner les légumes, glisser les saucisses entre eux et rôtir encore 20 min.","Mélanger le miel et la moutarde, en enrober les saucisses et les panais et rôtir encore 10 min, jusqu''à ce que ce soit caramélisé et que les saucisses soient cuites à cœur."]},"it":{"title":"Salsicce e ortaggi a radice in teglia","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato).","Condire pastinache, carote, patate e cipolla con l''olio, il timo, sale e pepe su una grande teglia, in un solo strato.","Arrostire per 20 min.","Girare le verdure, sistemare le salsicce in mezzo e arrostire altri 20 min.","Mescolare il miele e la senape, versarli sulle salsicce e sulle pastinache e arrostire altri 10 min, finché sono glassate e le salsicce cotte all''interno."]}}'::jsonb),
  ('080fcab4-3b09-4071-8cc8-d2871c61b0c3'::uuid, '{"fr":{"title":"Fish pie au cabillaud et pommes de terre","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante). Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres.","Pendant ce temps, mettre le cabillaud et le haddock dans une casserole avec 350 ml de lait et le laurier. Porter juste à frémissement et pocher 4 min. Retirer le poisson et verser le lait dans un pichet.","Faire fondre 20 g de beurre dans la même casserole, ajouter la farine 1 min, puis incorporer peu à peu le lait de pochage au fouet. Laisser épaissir 3 à 4 min à feu doux ; ajouter la moutarde, le persil et du poivre.","Effeuiller le poisson en gros morceaux dans un plat à four, répartir les crevettes et napper de sauce.","Égoutter les pommes de terre et les écraser en purée avec le reste du beurre et du lait. Assaisonner.","Étaler la purée sur la garniture, la strier à la fourchette et parsemer de cheddar.","Enfourner 25 à 30 min, jusqu''à ce que ce soit doré et que ça bouillonne sur les bords."]},"it":{"title":"Fish pie di merluzzo e patate","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato). Lessare le patate in acqua salata per 15 min finché sono tenere.","Nel frattempo mettere il merluzzo e l''eglefino in una pentola con 350 ml di latte e l''alloro. Portare appena a bollore e cuocere 4 min. Togliere il pesce e versare il latte in una caraffa.","Sciogliere 20 g di burro nella stessa pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 3-4 min finché si addensa; aggiungere la senape, il prezzemolo e il pepe.","Sfaldare il pesce a grossi pezzi in una pirofila, distribuire i gamberi e versare sopra la salsa.","Scolare le patate e schiacciarle con il burro e il latte rimasti. Regolare di sale.","Stendere il purè sul ripieno, rigarlo con una forchetta e cospargere di cheddar.","Infornare 25-30 min, finché è dorato e bolle ai bordi."]}}'::jsonb),
  ('7e540a97-e2de-41ac-a97e-3781fce9f828'::uuid, '{"fr":{"title":"Tourte feuilletée à la dinde et aux poireaux","steps":["Faire dorer la dinde dans l''huile dans une sauteuse à feu vif 4 min. La réserver sur une assiette.","Faire fondre le beurre dans la même sauteuse et cuire les poireaux à feu moyen-doux 8 min, jusqu''à ce qu''ils soient fondants.","Ajouter la farine 1 min, puis verser le bouillon petit à petit et laisser épaissir 3 min. Incorporer la crème fraîche, la moutarde, le thym et la dinde ; assaisonner. Laisser tiédir 10 min.","Préchauffer le four à 200 °C (180 °C chaleur tournante).","Verser la garniture dans un petit plat à tourte, couvrir de pâte, souder les bords et percer une petite cheminée. Badigeonner d''œuf.","Enfourner 25 min, jusqu''à ce que la pâte soit gonflée et bien dorée. Laisser reposer 5 min avant de servir."]},"it":{"title":"Torta salata di sfoglia con tacchino e porri","steps":["Rosolare il tacchino nell''olio in una padella larga a fuoco alto per 4 min. Toglierlo e tenerlo da parte.","Sciogliere il burro nella stessa padella e cuocere i porri a fuoco medio-basso per 8 min finché sono morbidi.","Unire la farina per 1 min, poi aggiungere il brodo poco alla volta e cuocere 3 min finché si addensa. Unire la crème fraîche, la senape, il timo e il tacchino; regolare di sale e pepe. Lasciare intiepidire 10 min.","Preriscaldare il forno a 200 °C (180 °C ventilato).","Versare il ripieno in una piccola teglia, coprire con la sfoglia, sigillare i bordi e praticare un piccolo foro. Spennellare con l''uovo.","Infornare 25 min, finché la sfoglia è gonfia e ben dorata. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('f2838b36-f8a4-4800-b348-062ecb0ab0b0'::uuid, '{"fr":{"title":"Macaroni aux quatre fromages et brocoli au four","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante). Cuire les macaroni dans de l''eau bouillante salée 2 min de moins que l''indication du paquet, en ajoutant le brocoli les 3 dernières minutes. Égoutter.","Faire fondre le beurre dans une casserole, ajouter la farine 1 min, puis incorporer le lait peu à peu au fouet. Cuire 5 min en remuant, jusqu''à ce que la sauce nappe la cuillère.","Hors du feu, incorporer le cheddar, l''emmental, la moitié du parmesan, la moutarde et la muscade. Assaisonner.","Mélanger les pâtes et le brocoli à la sauce, verser dans un plat à four et parsemer de mozzarella.","Mélanger la chapelure avec le reste du parmesan, en parsemer le plat et enfourner 20 min, jusqu''à ce que ce soit doré et bouillonnant."]},"it":{"title":"Maccheroni ai quattro formaggi e broccoli al forno","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato). Cuocere i maccheroni in acqua bollente salata 2 min meno di quanto indicato sulla confezione, aggiungendo i broccoli negli ultimi 3 min. Scolare.","Sciogliere il burro in una pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 5 min, mescolando, finché vela il cucchiaio.","Fuori dal fuoco, unire il cheddar, l''emmental, metà del parmigiano, la senape e la noce moscata. Regolare di sale e pepe.","Unire la pasta e i broccoli alla salsa, versare in una pirofila e distribuire la mozzarella.","Mescolare il pangrattato con il parmigiano rimasto, cospargerlo sopra e infornare 20 min, finché è dorato e bolle."]}}'::jsonb),
  ('0932be9e-079a-4987-8170-c331087fb0a7'::uuid, '{"fr":{"title":"Merlu poêlé, écrasé de petits pois à la menthe","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser avec le beurre, le lait chaud, la menthe, sel et poivre, en gardant un peu de texture. Garder au chaud.","Éponger le merlu, inciser légèrement la peau et assaisonner des deux côtés.","Chauffer l''huile dans une poêle à feu moyen-vif. Cuire le merlu côté peau 4 min, jusqu''à ce qu''elle soit croustillante, puis le retourner et cuire 2 à 3 min, juste nacré à cœur.","Servir le poisson sur l''écrasé avec un filet de citron."]},"it":{"title":"Nasello in padella con purè di piselli e menta","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare con il burro, il latte caldo, la menta, sale e pepe, lasciando un po'' di consistenza. Tenere in caldo.","Asciugare il nasello, incidere leggermente la pelle e condire da entrambi i lati.","Scaldare l''olio in padella a fuoco medio-alto. Cuocere il nasello dalla parte della pelle per 4 min finché è croccante, poi girarlo e cuocere 2-3 min, finché è appena opaco al centro.","Servire il pesce sul purè con una spruzzata di limone."]}}'::jsonb),
  ('052505d0-dfea-4d39-abe9-1eb80426e276'::uuid, '{"fr":{"title":"Pommes de terre en robe des champs au thon et maïs","steps":["Piquer les pommes de terre de partout, les frotter d''un peu d''huile et de sel et les cuire au micro-ondes à puissance maximale 6 min. Les retourner et cuire encore 5 à 7 min, jusqu''à ce qu''un couteau s''enfonce facilement.","Pendant ce temps, allumer le gril du four à puissance maximale et mélanger le thon, le maïs, le yaourt, la mayonnaise, les oignons nouveaux, le jus de citron et du poivre.","Passer les pommes de terre 5 min sous le gril pour rendre la peau croustillante.","Les fendre, aérer la chair à la fourchette et garnir du mélange au thon.","Parsemer de cheddar et passer 2 min sous le gril pour le faire fondre. Servir avec de la salade."]},"it":{"title":"Patate al cartoccio con tonno e mais","steps":["Bucherellare le patate, strofinarle con un filo d''olio e sale e cuocerle al microonde alla massima potenza per 6 min. Girarle e cuocere altri 5-7 min, finché un coltello entra facilmente.","Nel frattempo accendere il grill del forno al massimo e mescolare il tonno, il mais, lo yogurt, la maionese, i cipollotti, il succo di limone e il pepe.","Mettere le patate sotto il grill per 5 min per rendere la buccia croccante.","Aprirle, smuovere la polpa con una forchetta e farcirle con il composto di tonno.","Cospargere di cheddar e passare 2 min sotto il grill finché fonde. Servire con insalata."]}}'::jsonb),
  ('86ac5a18-9832-4b71-b7a5-72f531f53ddf'::uuid, '{"fr":{"title":"Côtelettes d''agneau, écrasé de petits pois et pommes de terre","steps":["Frotter les côtelettes avec l''ail, le romarin, 1 c. à soupe d''huile et du poivre. Laisser 20 min à température ambiante.","Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les petits pois les 3 dernières minutes.","Égoutter, puis écraser grossièrement pommes de terre et petits pois avec le beurre, 1 c. à soupe d''huile, la menthe, le zeste de citron et du sel. Garder au chaud.","Saler les côtelettes. Chauffer une poêle à feu vif et poser les côtelettes debout sur leur gras 2 min pour le faire fondre.","Les coucher et cuire 3 min de chaque côté pour une viande rosée. Laisser reposer 5 min.","Servir les côtelettes sur l''écrasé avec des quartiers de citron."]},"it":{"title":"Costolette d''agnello con piselli e patate schiacciati","steps":["Massaggiare le costolette con l''aglio, il rosmarino, 1 cucchiaio d''olio e il pepe. Lasciarle 20 min a temperatura ambiente.","Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo i piselli negli ultimi 3 min.","Scolare, poi schiacciare grossolanamente patate e piselli con il burro, 1 cucchiaio d''olio, la menta, la scorza di limone e il sale. Tenere in caldo.","Salare le costolette. Scaldare una padella a fuoco alto e appoggiare le costolette sul lato del grasso per 2 min per farlo sciogliere.","Adagiarle di piatto e cuocere 3 min per lato per una carne rosata. Lasciarle riposare 5 min.","Servire le costolette sui piselli e patate schiacciati con spicchi di limone."]}}'::jsonb),
  ('5d85fa6b-aadc-4188-ac08-ae090e153778'::uuid, '{"fr":{"title":"Tourte aux champignons, châtaignes et lentilles","steps":["Cuire les lentilles dans un grand volume d''eau non salée 20 min, jusqu''à ce qu''elles soient juste tendres. Égoutter.","Pendant ce temps, faire revenir l''oignon et la carotte dans l''huile dans une sauteuse à feu moyen 8 min. Ajouter l''ail et le thym 1 min.","Monter le feu, ajouter les champignons et les faire sauter 6 à 8 min, jusqu''à ce qu''ils soient dorés et que leur eau se soit évaporée.","Ajouter la farine et le concentré de tomate 1 min, verser le vin et laisser bouillonner 2 min.","Ajouter le bouillon, la sauce soja, les lentilles et les châtaignes et laisser mijoter 15 min, jusqu''à ce que ce soit épais et brillant. Assaisonner et laisser tiédir 15 min.","Préchauffer le four à 200 °C (180 °C chaleur tournante). Verser la garniture dans un plat à tourte, couvrir de pâte, souder les bords, percer une cheminée et badigeonner d''œuf.","Enfourner 25 min, jusqu''à ce que la pâte soit gonflée et bien dorée."]},"it":{"title":"Pasticcio di funghi, castagne e lenticchie in sfoglia","steps":["Cuocere le lenticchie in abbondante acqua non salata per 20 min finché sono appena tenere. Scolarle.","Nel frattempo appassire la cipolla e la carota nell''olio in una padella larga a fuoco medio per 8 min. Aggiungere l''aglio e il timo per 1 min.","Alzare la fiamma, aggiungere i funghi e saltarli 6-8 min finché sono dorati e il loro liquido è evaporato.","Unire la farina e il concentrato di pomodoro per 1 min, versare il vino e lasciarlo sfumare 2 min.","Aggiungere il brodo, la salsa di soia, le lenticchie e le castagne e cuocere 15 min finché il sugo è denso e lucido. Regolare di sale e pepe e lasciare intiepidire 15 min.","Preriscaldare il forno a 200 °C (180 °C ventilato). Versare il ripieno in una teglia, coprire con la sfoglia, sigillare i bordi, praticare un foro e spennellare con l''uovo.","Infornare 25 min, finché la sfoglia è gonfia e ben dorata."]}}'::jsonb),
  ('c6232350-6113-4114-8a14-4cdec962f675'::uuid, '{"fr":{"title":"Gratin de chou-fleur au fromage, croûte de pommes de terre","steps":["Préchauffer le four à 200 °C (180 °C chaleur tournante). Cuire le chou-fleur 5 min dans de l''eau bouillante salée, le retirer à l''écumoire, puis cuire les rondelles de pomme de terre 4 min dans la même eau. Bien égoutter.","Faire fondre le beurre dans une casserole, ajouter la farine 1 min, puis incorporer le lait peu à peu au fouet. Cuire 4 min en remuant, jusqu''à ce que la sauce épaississe.","Hors du feu, incorporer les trois quarts du cheddar, la moutarde et la muscade. Assaisonner.","Mettre le chou-fleur dans un plat à four et le napper de sauce.","Disposer les rondelles de pomme de terre en les faisant se chevaucher, les badigeonner d''huile, assaisonner et parsemer du reste du cheddar et du parmesan.","Enfourner 30 à 35 min, jusqu''à ce que les pommes de terre soient croustillantes et dorées sur les bords. Laisser reposer 5 min avant de servir."]},"it":{"title":"Cavolfiore gratinato al formaggio con crosta di patate","steps":["Preriscaldare il forno a 200 °C (180 °C ventilato). Lessare il cavolfiore in acqua salata per 5 min e toglierlo con una schiumarola; lessare le fette di patata nella stessa acqua per 4 min. Scolare bene.","Sciogliere il burro in una pentola, unire la farina per 1 min, poi aggiungere il latte poco alla volta mescolando con la frusta. Cuocere 4 min, mescolando, finché si addensa.","Fuori dal fuoco, unire tre quarti del cheddar, la senape e la noce moscata. Regolare di sale e pepe.","Mettere il cavolfiore in una pirofila e versarvi sopra la salsa.","Disporre sopra le fette di patata sovrapponendole, spennellarle d''olio, condire e cospargere con il cheddar rimasto e il parmigiano.","Infornare 30-35 min, finché le patate sono croccanti e dorate ai bordi. Lasciare riposare 5 min prima di servire."]}}'::jsonb),
  ('f445cd76-b382-4065-8f94-eb2d927749e5'::uuid, '{"fr":{"title":"Sandwichs aux boulettes de bœuf et mozzarella","steps":["Mélanger le bœuf, la chapelure, l''œuf, le parmesan, 1 gousse d''ail, l''origan, sel et poivre. Former 10 boulettes.","Faire dorer les boulettes dans l''huile dans une poêle à feu moyen-vif 5 min, en les retournant.","Ajouter le coulis de tomate, le reste de l''ail et le sucre. Couvrir et laisser mijoter 12 min, jusqu''à ce que les boulettes soient cuites à cœur.","Allumer le gril du four à puissance maximale. Ouvrir les pains et les griller 2 min, face coupée vers le haut.","Garnir les pains de boulettes et d''un peu de sauce, puis couvrir de mozzarella.","Passer 3 à 4 min sous le gril, jusqu''à ce que le fromage fonde et dore. Parsemer de basilic et servir avec le reste de sauce."]},"it":{"title":"Panini con polpette di manzo e mozzarella","steps":["Mescolare la carne, il pangrattato, l''uovo, il parmigiano, 1 spicchio d''aglio, l''origano, sale e pepe. Formare 10 polpette.","Rosolare le polpette nell''olio in padella a fuoco medio-alto per 5 min, girandole.","Aggiungere la passata, l''aglio rimasto e lo zucchero. Coprire e cuocere a fuoco lento 12 min, finché le polpette sono cotte all''interno.","Accendere il grill del forno al massimo. Aprire i panini e tostarli 2 min con il lato tagliato verso l''alto.","Farcire i panini con le polpette e un po'' di sugo e coprire con la mozzarella.","Gratinare 3-4 min finché il formaggio fonde e si dora. Completare con il basilico e servire con il sugo rimasto."]}}'::jsonb),
  ('579eee8b-5bb0-4a2d-a485-40c468fcf68e'::uuid, '{"fr":{"title":"Hachis parmentier d''agneau aux lentilles","steps":["Cuire les lentilles 15 min dans de l''eau frémissante, à mi-cuisson. Égoutter.","Faire dorer l''agneau dans une sauteuse sans matière grasse à feu vif 6 min, puis retirer l''essentiel du gras. Ajouter l''oignon et la carotte et cuire 6 min.","Ajouter l''ail, la farine et le concentré de tomate 1 min. Verser le bouillon, la sauce Worcestershire, le thym, le romarin et les lentilles, couvrir et laisser mijoter 25 min, jusqu''à ce que les lentilles soient tendres et la sauce épaisse. Assaisonner.","Pendant ce temps, cuire les pommes de terre 15 min dans de l''eau salée. Égoutter et les écraser en purée avec le beurre et le lait chaud ; assaisonner.","Préchauffer le four à 200 °C (180 °C chaleur tournante). Verser la garniture dans un plat à four, couvrir de purée et strier le dessus à la fourchette.","Enfourner 25 min, jusqu''à ce que le dessus soit doré et que ça bouillonne sur les bords."]},"it":{"title":"Shepherd''s pie di agnello e lenticchie","steps":["Cuocere le lenticchie in acqua sobbollente per 15 min, a metà cottura. Scolarle.","Rosolare l''agnello in una padella senza grassi a fuoco alto per 6 min, poi eliminare gran parte del grasso. Aggiungere la cipolla e la carota e cuocere 6 min.","Unire l''aglio, la farina e il concentrato di pomodoro per 1 min. Aggiungere il brodo, la salsa Worcestershire, il timo, il rosmarino e le lenticchie, coprire e cuocere a fuoco lento 25 min, finché le lenticchie sono tenere e il sugo denso. Regolare di sale e pepe.","Nel frattempo lessare le patate in acqua salata per 15 min. Scolarle e schiacciarle con il burro e il latte caldo; regolare di sale.","Preriscaldare il forno a 200 °C (180 °C ventilato). Versare il ripieno in una pirofila, coprire con il purè e rigare la superficie con una forchetta.","Infornare 25 min, finché la superficie è dorata e bolle ai bordi."]}}'::jsonb),
  ('547accca-910e-44d6-8b35-b5f9621f0bd1'::uuid, '{"fr":{"title":"Wraps au poulet façon César","steps":["Aplatir le poulet sur 1,5 cm d''épaisseur régulière et l''assaisonner avec l''huile, le zeste de citron, du sel et du poivre.","Le cuire dans une poêle chaude 4 à 5 min de chaque côté, jusqu''à ce qu''il soit cuit à cœur. Laisser reposer 3 min, puis trancher.","Fouetter le yaourt, la mayonnaise, l''ail, la moutarde, la sauce Worcestershire, le jus de citron, la moitié du parmesan et beaucoup de poivre pour la sauce.","Essuyer la poêle et y réchauffer les tortillas 20 s de chaque côté.","Mélanger la salade avec presque toute la sauce. Garnir chaque tortilla de salade, de poulet, du reste de la sauce et du parmesan, rouler serré et couper en deux."]},"it":{"title":"Wrap di pollo stile Caesar","steps":["Appiattire il pollo a uno spessore uniforme di 1,5 cm e condirlo con l''olio, la scorza di limone, sale e pepe.","Cuocerlo in una padella calda per 4-5 min per lato, finché è cotto all''interno. Lasciarlo riposare 3 min, poi affettarlo.","Sbattere lo yogurt, la maionese, l''aglio, la senape, la salsa Worcestershire, il succo di limone, metà del parmigiano e abbondante pepe per la salsa.","Pulire la padella e scaldarvi le tortillas 20 s per lato.","Condire la lattuga con quasi tutta la salsa. Farcire ogni tortilla con lattuga, pollo, la salsa e il parmigiano rimasti, arrotolare stretto e tagliare a metà."]}}'::jsonb),
  ('18c1a899-e68c-4b75-8eb3-38adbd2e2aae'::uuid, '{"fr":{"title":"Salade de maquereau fumé, betterave et pommes de terre","steps":["Cuire les pommes de terre 15 min dans de l''eau salée, jusqu''à ce qu''elles soient tendres, en ajoutant les œufs les 8 dernières minutes. Refroidir les œufs dans de l''eau froide, puis les écaler et les couper en deux.","Mélanger la crème fraîche, le raifort, la moutarde, le jus de citron, la moitié de l''aneth, sel et poivre.","Mélanger l''oignon émincé avec le vinaigre et une pincée de sel et laisser 10 min.","Mélanger les pommes de terre tièdes avec l''oignon, son vinaigre et la moitié de la sauce.","Répartir les pommes de terre, la betterave, le maquereau et la roquette dans les assiettes, ajouter les œufs et le reste de la sauce, et parsemer du reste d''aneth."]},"it":{"title":"Insalata di sgombro affumicato, barbabietola e patate","steps":["Lessare le patate in acqua salata per 15 min finché sono tenere, aggiungendo le uova negli ultimi 8 min. Raffreddare le uova in acqua fredda, poi sgusciarle e tagliarle a metà.","Mescolare la crème fraîche, il rafano, la senape, il succo di limone, metà dell''aneto, sale e pepe.","Condire la cipolla affettata con l''aceto e un pizzico di sale e lasciarla 10 min.","Condire le patate tiepide con la cipolla, il suo aceto e metà della salsa.","Disporre nei piatti le patate, la barbabietola, lo sgombro e la rucola, aggiungere le uova e il resto della salsa e completare con l''aneto rimasto."]}}'::jsonb),
  ('159dedbb-14c3-4d5a-9b03-6d4f1f6f6f3f'::uuid, '{"fr":{"title":"Escalope de poulet panée, coleslaw et potatoes","steps":["Préchauffer le four à 220 °C (200 °C chaleur tournante). Mélanger les quartiers de pommes de terre avec 1 c. à soupe d''huile d''olive, le paprika et du sel sur une plaque et rôtir 35 min, en retournant une fois, jusqu''à ce qu''ils soient croustillants.","Mélanger le chou et la carotte avec le yaourt, la mayonnaise, la moutarde, le vinaigre et du sel. Laisser ramollir.","Couper chaque blanc de poulet en deux dans l''épaisseur, puis aplatir les morceaux entre deux films à 5 mm d''épaisseur. Assaisonner.","Passer chaque morceau dans la farine, puis dans l''œuf battu, puis dans la chapelure, en l''enrobant légèrement sans appuyer.","Chauffer l''huile végétale dans une grande poêle jusqu''à ce qu''une miette grésille aussitôt (environ 170 °C). Cuire les escalopes 2 à 3 min de chaque côté, en faisant doucement tourner la poêle pour que la panure gonfle, jusqu''à ce qu''elles soient bien dorées.","Égoutter sur du papier absorbant, saler légèrement et servir avec des quartiers de citron, le coleslaw et les potatoes."]},"it":{"title":"Cotoletta di pollo con insalata di cavolo e patate a spicchi","steps":["Preriscaldare il forno a 220 °C (200 °C ventilato). Condire gli spicchi di patata con 1 cucchiaio d''olio d''oliva, la paprika e il sale su una teglia e arrostirli 35 min, girandoli una volta, finché sono croccanti.","Mescolare il cavolo e la carota con lo yogurt, la maionese, la senape, l''aceto e il sale. Lasciare ammorbidire.","Tagliare a metà ogni petto di pollo nello spessore, poi battere i pezzi tra due fogli di pellicola fino a 5 mm. Condire.","Passare ogni pezzo nella farina, poi nell''uovo sbattuto, poi nel pangrattato, ricoprendolo leggermente senza premere.","Scaldare l''olio di semi in una padella grande finché una briciola sfrigola subito (circa 170 °C). Friggere le cotolette 2-3 min per lato, muovendo delicatamente la padella perché la panatura si gonfi, finché sono ben dorate.","Scolarle su carta assorbente, salarle leggermente e servirle con spicchi di limone, l''insalata di cavolo e le patate."]}}'::jsonb),
  ('0fed55e8-6259-459c-8b4c-b64a8add53da'::uuid, '{"fr":{"title":"Saucisses au chou braisé et purée","steps":["Faire dorer les saucisses dans l''huile dans une grande cocotte à feu moyen 5 min. Les réserver.","Mettre les lardons dans la cocotte et les faire revenir 3 min, puis ajouter l''oignon et cuire 5 min, jusqu''à ce qu''il soit tendre.","Ajouter le chou, le carvi et le laurier et remuer 3 min, jusqu''à ce que le chou tombe.","Verser le vin, le bouillon et le vinaigre, assaisonner, couvrir et braiser à feu doux 15 min, en remuant de temps en temps.","Enfoncer les saucisses dans le chou, couvrir et braiser encore 15 min, jusqu''à ce que le chou soit tendre et les saucisses cuites à cœur.","Pendant ce temps, cuire les pommes de terre 15 à 20 min dans de l''eau salée. Égoutter et les écraser en purée avec le beurre, le lait chaud et la muscade.","Servir les saucisses et le chou avec la purée et de la moutarde."]},"it":{"title":"Salsicce con cavolo brasato e purè","steps":["Rosolare le salsicce nell''olio in una casseruola grande a fuoco medio per 5 min. Toglierle e tenerle da parte.","Mettere la pancetta nella casseruola e rosolarla 3 min, poi aggiungere la cipolla e cuocere 5 min finché è morbida.","Aggiungere il cavolo, il cumino dei prati e l''alloro e mescolare 3 min finché il cavolo appassisce.","Versare il vino, il brodo e l''aceto, regolare di sale, coprire e brasare a fuoco basso per 15 min, mescolando ogni tanto.","Sistemare le salsicce nel cavolo, coprire e brasare altri 15 min, finché il cavolo è tenero e le salsicce cotte all''interno.","Nel frattempo lessare le patate in acqua salata per 15-20 min. Scolarle e schiacciarle con il burro, il latte caldo e la noce moscata.","Servire le salsicce e il cavolo con il purè e la senape."]}}'::jsonb),
  ('a789c5f2-85b3-4e2d-816d-a159b7989c55'::uuid, '{"fr":{"title":"Ragoût de patate douce aux cacahuètes","steps":["Lancer le riz : le cuire à couvert à petit feu dans 1,5 fois son volume d''eau salée 12 min, puis le laisser reposer 5 min hors du feu.","Pendant ce temps, faire fondre l''oignon dans l''huile dans une cocotte à feu moyen-doux 6 à 8 min.","Ajouter l''ail, le gingembre, le cumin, la coriandre moulue et le piment de Cayenne et remuer 1 min jusqu''à ce que ça embaume.","Ajouter les tomates, le bouillon, la patate douce et les pois chiches avec sel et poivre. Porter à ébullition puis laisser mijoter à découvert 12 à 15 min, jusqu''à ce que la patate douce soit tendre.","Délayer le beurre de cacahuète avec une louche de liquide chaud jusqu''à ce qu''il soit lisse, l''incorporer dans la cocotte et laisser mijoter 2 à 3 min jusqu''à ce que la sauce épaississe.","Ajouter les épinards et remuer jusqu''à ce qu''ils tombent, environ 1 min, puis rectifier le sel.","Servir sur le riz, parsemé de cacahuètes concassées et de coriandre."]},"it":{"title":"Stufato di patate dolci e arachidi","steps":["Avviare il riso: cuocerlo coperto a fuoco basso in 1,5 volte il suo volume di acqua salata per 12 min, poi lasciarlo riposare 5 min fuori dal fuoco.","Nel frattempo, appassire la cipolla nell''olio in una pentola a fuoco medio-basso per 6-8 min.","Aggiungere l''aglio, lo zenzero, il cumino, il coriandolo in polvere e il pepe di Cayenna e mescolare 1 min finché profumano.","Aggiungere i pomodori, il brodo, la patata dolce e i ceci con sale e pepe. Portare a bollore, poi cuocere scoperto a fuoco lento 12-15 min, finché la patata dolce è tenera.","Stemperare il burro di arachidi con un mestolo di liquido caldo finché è liscio, versarlo nella pentola e cuocere 2-3 min finché la salsa si addensa.","Unire gli spinaci e mescolare finché appassiscono, circa 1 min, poi regolare di sale.","Servire sul riso, con arachidi tritate e coriandolo."]}}'::jsonb),
  ('8bb592e0-9ca3-454e-92f6-15e3a6d0d82d'::uuid, '{"fr":{"title":"Bœuf Stroganoff aux tagliatelles","steps":["Mettre à bouillir une casserole d''eau salée pour les tagliatelles.","Faire dorer les champignons dans la moitié de l''huile dans une grande poêle à feu vif 5 à 6 min, saler et les réserver dans un bol.","Ajouter le reste de l''huile et saisir les lanières de bœuf en une seule couche 1 à 2 min de chaque côté, juste dorées mais encore rosées à cœur. Saler, poivrer et les ajouter aux champignons.","Baisser à feu moyen, faire fondre le beurre et cuire l''oignon avec le concentré de tomate et le paprika 5 à 6 min, jusqu''à ce qu''il soit tendre et légèrement doré.","Incorporer la farine 30 s, puis verser le bouillon et le vin en fouettant et en grattant la poêle. Laisser mijoter 2 à 3 min jusqu''à ce que la sauce nappe la cuillère.","Pendant ce temps, cuire les tagliatelles selon le paquet, en général 8 à 10 min, et les égoutter.","Retirer la poêle du feu, incorporer la moutarde et la crème fraîche, puis remettre le bœuf, les champignons et leur jus et réchauffer 1 min sans faire bouillir.","Servir le Stroganoff sur les tagliatelles, parsemé de persil."]},"it":{"title":"Manzo alla Stroganoff con tagliatelle","steps":["Mettere a bollire una pentola d''acqua salata per le tagliatelle.","Rosolare i funghi in metà dell''olio in una padella grande a fuoco vivo per 5-6 min, salarli e metterli da parte in una ciotola.","Aggiungere il resto dell''olio e scottare le strisce di manzo in un solo strato 1-2 min per lato, appena rosolate ma ancora rosate dentro. Salare, pepare e unirle ai funghi.","Abbassare a fuoco medio, sciogliere il burro e cuocere la cipolla con il concentrato di pomodoro e la paprika per 5-6 min, finché è morbida e appena dorata.","Incorporare la farina per 30 s, poi versare il brodo e il vino mescolando con la frusta e raschiando la padella. Cuocere 2-3 min finché la salsa vela il cucchiaio.","Nel frattempo, cuocere le tagliatelle secondo la confezione, di solito 8-10 min, e scolarle.","Togliere la padella dal fuoco, unire la senape e la crème fraîche, poi rimettere il manzo, i funghi e il loro sugo e scaldare 1 min senza far bollire.","Servire lo Stroganoff sulle tagliatelle con il prezzemolo."]}}'::jsonb),
  ('54c25855-82be-4d48-9e67-689d4b21866c'::uuid, '{"fr":{"title":"Truite au four, pommes de terre à l''aneth et concombre","steps":["Préchauffer le four à 200 °C. Mettre les pommes de terre dans une casserole d''eau froide salée avec les tiges d''aneth, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Pour le pressgurka, mélanger le vinaigre, le sucre, 2 c. à soupe d''eau et une pincée de sel jusqu''à dissolution, ajouter le concombre et un peu d''aneth et laisser mariner pendant la cuisson.","Poser la truite côté peau dans un plat huilé, saler, poivrer, parsemer de la moitié du beurre et ajouter quelques rondelles de citron.","Enfourner 10 à 12 min, jusqu''à ce que la chair soit opaque et se détache facilement.","Mélanger la crème fraîche avec la moutarde, un filet de citron, la moitié de l''aneth restant, du sel et du poivre.","Égoutter les pommes de terre et les enrober du reste du beurre et de l''aneth.","Servir la truite avec les pommes de terre à l''aneth, le concombre égoutté et la sauce à l''aneth."]},"it":{"title":"Trota al forno con patate all''aneto e cetrioli","steps":["Scaldare il forno a 200 °C. Mettere le patate in una pentola di acqua fredda salata con i gambi di aneto, portare a bollore e cuocere 15-20 min finché sono tenere.","Per il pressgurka, mescolare l''aceto, lo zucchero, 2 cucchiai d''acqua e un pizzico di sale finché si sciolgono, aggiungere il cetriolo e un po'' di aneto e lasciare marinare durante la cottura.","Disporre la trota con la pelle verso il basso in una pirofila unta, salare, pepare, distribuire metà del burro e qualche fetta di limone.","Infornare 10-12 min, finché la polpa è opaca e si sfalda facilmente.","Mescolare la crème fraîche con la senape, una spruzzata di limone, metà dell''aneto rimasto, sale e pepe.","Scolare le patate e condirle con il resto del burro e dell''aneto.","Servire la trota con le patate all''aneto, il cetriolo scolato e la salsa all''aneto."]}}'::jsonb),
  ('f494248a-e37a-4325-a232-ee05373d514e'::uuid, '{"fr":{"title":"Gołąbki aux champignons, épinards et riz","steps":["Faire tremper les cèpes séchés 20 min dans 200 ml d''eau chaude, puis les égoutter, les hacher et garder l''eau de trempage.","Retirer le trognon du chou et cuire le chou entier 8 à 10 min dans un grand faitout d''eau salée frémissante, en détachant 8 feuilles à mesure qu''elles ramollissent. Amincir la grosse nervure de chaque feuille.","Vider le faitout et y cuire le riz dans l''eau des cèpes filtrée, complétée d''eau jusqu''à 300 ml, 8 à 10 min, jusqu''à ce qu''il soit à moitié cuit et ait absorbé le liquide.","Pendant ce temps, faire dorer l''oignon dans l''huile et le beurre 8 min, ajouter les champignons frais et réhydratés, l''ail et le thym et cuire 6 à 8 min jusqu''à évaporation, puis ajouter les épinards et les laisser tomber.","Préchauffer le four à 180 °C. Mélanger le riz, la poêlée de champignons et les œufs, et bien assaisonner.","Déposer une bonne cuillerée de farce à la base de chaque feuille, rabattre les côtés et rouler. Ranger les rouleaux, fermeture dessous, dans un plat tapissé de quelques feuilles restantes.","Assaisonner le coulis de tomate, le détendre avec 100 ml d''eau et le verser sur les rouleaux. Couvrir d''un couvercle ou de papier aluminium.","Enfourner 50 min, jusqu''à ce que le chou soit bien tendre. Servir avec une cuillerée de crème fraîche et de l''aneth."]},"it":{"title":"Gołąbki con funghi, spinaci e riso","steps":["Mettere in ammollo i porcini secchi in 200 ml di acqua calda per 20 min, poi scolarli, tritarli e tenere l''acqua dell''ammollo.","Eliminare il torsolo del cavolo e sbollentare il cavolo intero in una pentola grande di acqua salata per 8-10 min, staccando 8 foglie man mano che si ammorbidiscono. Assottigliare la costa spessa di ogni foglia.","Svuotare la pentola e cuocervi il riso nell''acqua dei porcini filtrata, allungata con acqua fino a 300 ml, per 8-10 min, finché è a metà cottura e ha assorbito il liquido.","Nel frattempo, dorare la cipolla nell''olio e nel burro per 8 min, aggiungere i funghi freschi e quelli ammollati, l''aglio e il timo e cuocere 6-8 min finché sono asciutti, poi unire gli spinaci e farli appassire.","Scaldare il forno a 180 °C. Mescolare il riso, i funghi e le uova e condire bene.","Mettere una cucchiaiata abbondante di ripieno alla base di ogni foglia, ripiegare i lati e arrotolare. Disporre gli involtini con la chiusura verso il basso in una pirofila foderata con qualche foglia avanzata.","Condire la passata, allungarla con 100 ml d''acqua e versarla sugli involtini. Coprire con un coperchio o con alluminio.","Infornare 50 min, finché il cavolo è molto tenero. Servire con una cucchiaiata di crème fraîche e aneto."]}}'::jsonb),
  ('3386f80c-25ff-468e-bd8a-ec26b70c7749'::uuid, '{"fr":{"title":"Joojeh kabab et riz au safran","steps":["Piler le safran avec une pincée de sucre ou de sel et le faire infuser 10 min dans 3 c. à soupe d''eau chaude.","Mélanger l''oignon râpé, le jus du citron, le yaourt, l''huile, le curcuma, les deux tiers de l''eau safranée, du sel et du poivre. Y enrober le poulet, couvrir et réfrigérer au moins 4 h, idéalement une nuit.","Rincer le riz jusqu''à ce que l''eau soit claire, puis le cuire à couvert à petit feu dans 250 ml d''eau salée avec le beurre 12 min et le laisser reposer 5 min hors du feu.","Mélanger quelques cuillerées de riz avec le reste de l''eau safranée et réserver pour les incorporer au service.","Enfiler le poulet sur des brochettes en égouttant l''excès de marinade. Faire chauffer très fort une poêle-gril ou un barbecue.","Griller les brochettes 10 à 12 min en les retournant toutes les quelques minutes, jusqu''à ce qu''elles soient grillées sur les bords et cuites à cœur. Griller les demi-tomates à côté 5 à 6 min.","Égrener le riz blanc, le garnir du riz safrané et servir avec les brochettes, les tomates grillées et un filet de citron."]},"it":{"title":"Joojeh kabab con riso allo zafferano","steps":["Pestare lo zafferano con un pizzico di zucchero o sale e lasciarlo in infusione 10 min in 3 cucchiai di acqua calda.","Mescolare la cipolla grattugiata, il succo del limone, lo yogurt, l''olio, la curcuma, due terzi dell''acqua allo zafferano, sale e pepe. Ricoprirvi il pollo, coprire e mettere in frigo almeno 4 h, meglio tutta la notte.","Sciacquare il riso finché l''acqua è limpida, poi cuocerlo coperto a fuoco basso in 250 ml di acqua salata con il burro per 12 min e lasciarlo riposare 5 min fuori dal fuoco.","Mescolare qualche cucchiaiata di riso con il resto dell''acqua allo zafferano e tenerla da parte da unire al momento di servire.","Infilare il pollo negli spiedini, scolando la marinata in eccesso. Scaldare bene una bistecchiera o il barbecue.","Grigliare gli spiedini 10-12 min, girandoli ogni pochi minuti, finché sono abbrustoliti ai bordi e cotti all''interno. Grigliare accanto i mezzi pomodori per 5-6 min.","Sgranare il riso bianco, coprirlo con il riso allo zafferano e servire con gli spiedini, i pomodori grigliati e una spruzzata di limone."]}}'::jsonb),
  ('f96f71e7-3799-457e-bcee-84a98bd7bcad'::uuid, '{"fr":{"title":"Kuku sabzi (omelette persane aux herbes)","steps":["Laver les herbes et les oignons nouveaux et les sécher très soigneusement, puis les hacher finement avec l''ail au robot par petites impulsions (ou au couteau).","Battre les œufs avec le curcuma, la levure chimique, du sel et du poivre, puis incorporer les herbes et les noix. Le mélange doit être plus vert que jaune.","Faire chauffer l''huile dans une poêle antiadhésive de 22 à 24 cm à feu moyen-doux, verser le mélange et l''égaliser.","Couvrir et cuire 8 à 10 min, jusqu''à ce que les bords soient pris et le dessous bien doré.","Couper en quatre, retourner chaque quart et cuire encore 4 à 5 min à découvert, jusqu''à ce que le centre soit pris.","Servir chaud ou tiède avec le yaourt et le pain plat chaud."]},"it":{"title":"Kuku sabzi (frittata persiana alle erbe)","steps":["Lavare le erbe e i cipollotti e asciugarli molto bene, poi tritarli finemente con l''aglio nel robot a brevi impulsi (o a coltello).","Sbattere le uova con la curcuma, il lievito, sale e pepe, poi incorporare le erbe e le noci. Il composto deve essere più verde che giallo.","Scaldare l''olio in una padella antiaderente da 22-24 cm a fuoco medio-basso, versare il composto e livellarlo.","Coprire e cuocere 8-10 min, finché i bordi sono rappresi e il fondo è ben dorato.","Tagliare in quattro, girare ogni spicchio e cuocere scoperto altri 4-5 min, finché è rappreso al centro.","Servire calda o tiepida con lo yogurt e il pane piatto caldo."]}}'::jsonb),
  ('27951550-45d9-4434-95ac-acb66e9a2444'::uuid, '{"fr":{"title":"Riz jollof au poulet","steps":["Préchauffer le four à 200 °C. Frotter le poulet avec la moitié du curry, le paprika, la moitié du thym, un peu d''huile, du sel et du poivre. Le rôtir côté peau vers le haut sur une plaque 35 à 40 min, jusqu''à ce qu''il soit doré et cuit à cœur.","Pendant ce temps, mixer la tomate, le poivron, la moitié de l''oignon, l''ail, le gingembre et le piment en purée lisse.","Émincer le reste de l''oignon et le faire revenir dans l''huile dans une cocotte à feu moyen-vif 3 min.","Ajouter la purée et cuire en remuant 8 à 10 min, jusqu''à ce qu''elle épaississe et que l''huile se sépare. Incorporer le concentré de tomate, le reste du curry et du thym et faire revenir 2 min.","Ajouter le bouillon, le laurier, le beurre et du sel, porter à ébullition, puis incorporer le riz.","Couvrir hermétiquement et cuire à feu doux 20 à 25 min sans remuer, jusqu''à ce que le riz soit tendre et ait absorbé le liquide. Ajouter un peu d''eau s''il sèche avant d''être cuit.","Laisser reposer 5 min hors du feu, égrener à la fourchette et servir avec le poulet rôti."]},"it":{"title":"Riso jollof con pollo","steps":["Scaldare il forno a 200 °C. Massaggiare il pollo con metà del curry, la paprika, metà del timo, un filo d''olio, sale e pepe. Arrostirlo con la pelle verso l''alto su una teglia per 35-40 min, finché è dorato e cotto all''interno.","Nel frattempo, frullare il pomodoro, il peperone, metà della cipolla, l''aglio, lo zenzero e il peperoncino fino a ottenere una purea liscia.","Tritare il resto della cipolla e soffriggerla nell''olio in una pentola dal fondo spesso a fuoco medio-alto per 3 min.","Aggiungere la purea e cuocere mescolando 8-10 min, finché si addensa e l''olio comincia a separarsi. Unire il concentrato di pomodoro, il curry e il timo rimasti e soffriggere 2 min.","Aggiungere il brodo, l''alloro, il burro e il sale, portare a bollore, poi unire il riso.","Coprire bene e cuocere a fuoco basso 20-25 min senza mescolare, finché il riso è tenero e ha assorbito il liquido. Aggiungere un goccio d''acqua se si asciuga prima che il riso sia cotto.","Lasciare riposare 5 min fuori dal fuoco, sgranare con una forchetta e servire con il pollo arrosto."]}}'::jsonb),
  ('9859e619-b04e-460a-b38f-d101ff535774'::uuid, '{"fr":{"title":"Poulet yassa","steps":["Mélanger les oignons, le jus des citrons, la moutarde, l''ail, le piment, 1 c. à soupe d''huile, du sel et du poivre. Y retourner le poulet, couvrir et réfrigérer au moins 2 h, ou une nuit.","Sortir le poulet de la marinade et le sécher. Le faire dorer dans le reste de l''huile dans une cocotte à feu moyen-vif 4 à 5 min de chaque côté, puis réserver.","Égoutter les oignons de la marinade en gardant le liquide. Les cuire dans la même cocotte à feu moyen 15 min en remuant souvent, jusqu''à ce qu''ils soient fondants et dorés.","Ajouter le liquide de marinade, le bouillon et le laurier, puis remettre le poulet. Couvrir et laisser mijoter doucement 25 min jusqu''à ce que le poulet soit tendre, en ajoutant les olives les 5 dernières minutes.","Pendant ce temps, cuire le riz à couvert dans 1,5 fois son volume d''eau salée 12 min et le laisser reposer 5 min.","Goûter la sauce : elle doit être acidulée mais ronde ; ajouter un peu de moutarde ou une pincée de sucre si elle est trop vive. Servir sur le riz."]},"it":{"title":"Pollo yassa","steps":["Mescolare le cipolle, il succo dei limoni, la senape, l''aglio, il peperoncino, 1 cucchiaio d''olio, sale e pepe. Girarvi il pollo, coprire e mettere in frigo almeno 2 h, o tutta la notte.","Togliere il pollo dalla marinata e asciugarlo. Rosolarlo nel resto dell''olio in una casseruola a fuoco medio-alto 4-5 min per lato, poi tenerlo da parte.","Scolare le cipolle dalla marinata tenendo il liquido. Cuocerle nella stessa casseruola a fuoco medio per 15 min, mescolando spesso, finché sono morbide e dorate.","Aggiungere il liquido della marinata, il brodo e l''alloro, poi rimettere il pollo. Coprire e cuocere a fuoco dolce 25 min finché il pollo è tenero, unendo le olive negli ultimi 5 min.","Nel frattempo, cuocere il riso coperto in 1,5 volte il suo volume di acqua salata per 12 min e lasciarlo riposare 5 min.","Assaggiare la salsa: deve essere acidula ma rotonda; aggiungere un po'' di senape o un pizzico di zucchero se è troppo aspra. Servire sul riso."]}}'::jsonb),
  ('cc15f857-8ba8-43a4-b185-6b48713f7f16'::uuid, '{"fr":{"title":"Poulet brown stew, riz aux haricots rouges","steps":["Mélanger le poulet avec l''oignon, le poivron, la carotte, l''ail, le gingembre, les oignons nouveaux, le piment de la Jamaïque, le paprika, le piment, le thym, la sauce soja, du sel et du poivre. Couvrir et réfrigérer au moins 2 h, ou une nuit.","Faire chauffer l''huile et le sucre dans une cocotte à fond épais à feu moyen jusqu''à ce que le sucre devienne brun foncé et commence à fumer, 2 à 3 min, en surveillant bien.","Sortir le poulet des légumes et le faire dorer dans le caramel 4 à 5 min de chaque côté, jusqu''à ce qu''il soit bien brun.","Ajouter les légumes marinés et les faire revenir 3 min, puis incorporer le ketchup et le bouillon. Couvrir et laisser mijoter doucement 25 min.","Pendant ce temps, pour le riz, mettre le riz, les haricots, le lait de coco, 150 ml d''eau, une branche de thym et du sel dans une casserole, porter à ébullition, couvrir et cuire à feu doux 15 min, puis laisser reposer 5 min.","Découvrir le poulet et laisser mijoter encore 10 à 15 min, jusqu''à ce que la viande soit tendre et la sauce épaisse et brillante.","Servir le poulet et sa sauce avec le riz aux haricots rouges."]},"it":{"title":"Pollo brown stew con riso e fagioli","steps":["Mescolare il pollo con la cipolla, il peperone, la carota, l''aglio, lo zenzero, i cipollotti, il pimento, la paprika, il peperoncino, il timo, la salsa di soia, sale e pepe. Coprire e mettere in frigo almeno 2 h, o tutta la notte.","Scaldare l''olio e lo zucchero in una pentola dal fondo spesso a fuoco medio finché lo zucchero diventa bruno scuro e comincia a fumare, 2-3 min, controllando bene.","Togliere il pollo dalle verdure e rosolarlo nel caramello 4-5 min per lato, finché è ben scuro.","Aggiungere le verdure marinate e soffriggere 3 min, poi unire il ketchup e il brodo. Coprire e cuocere a fuoco dolce 25 min.","Nel frattempo, per il riso, mettere in una pentola il riso, i fagioli, il latte di cocco, 150 ml d''acqua, un rametto di timo e il sale, portare a bollore, coprire e cuocere a fuoco basso 15 min, poi lasciare riposare 5 min.","Scoprire il pollo e cuocere altri 10-15 min, finché la carne è tenera e il sugo denso e lucido.","Servire il pollo con il sugo e il riso con i fagioli."]}}'::jsonb),
  ('5e6779a0-957a-4af7-9775-d03c9b70b678'::uuid, '{"fr":{"title":"Goulash hongrois (gulyás)","steps":["Faire fondre le beurre dans une cocotte à fond épais à feu moyen et cuire les oignons 8 à 10 min jusqu''à ce qu''ils soient dorés.","Ajouter le bœuf et le faire dorer sur toutes les faces 8 min.","Ajouter le poivron, la tomate et l''ail et cuire 5 min.","Retirer la cocotte du feu et incorporer le paprika et le carvi pour que le paprika ne brûle pas.","Verser le bouillon, ajouter le laurier et du sel, porter à ébullition, puis couvrir et laisser mijoter doucement 1 h.","Ajouter les carottes et les pommes de terre et laisser mijoter à couvert encore 30 à 40 min, jusqu''à ce que le bœuf soit très tendre et les pommes de terre cuites.","Retirer le laurier, rectifier l''assaisonnement et servir dans des assiettes creuses avec une cuillerée de crème fraîche et du pain."]},"it":{"title":"Gulasch ungherese (gulyás)","steps":["Sciogliere il burro in una pentola dal fondo spesso a fuoco medio e cuocere le cipolle 8-10 min finché sono dorate.","Aggiungere il manzo e rosolarlo su tutti i lati per 8 min.","Aggiungere il peperone, il pomodoro e l''aglio e cuocere 5 min.","Togliere la pentola dal fuoco e incorporare la paprika e il cumino dei prati, così la paprika non brucia.","Versare il brodo, aggiungere l''alloro e il sale, portare a bollore, poi coprire e cuocere a fuoco dolce per 1 h.","Aggiungere le carote e le patate e cuocere coperto altri 30-40 min, finché il manzo è molto tenero e le patate sono cotte.","Togliere l''alloro, regolare di sale e servire in piatti fondi con una cucchiaiata di crème fraîche e pane."]}}'::jsonb),
  ('109d6d4a-1ff5-4003-9980-ec0e6c98e33c'::uuid, '{"fr":{"title":"Bigos (choucroute polonaise du chasseur)","steps":["Faire tremper les cèpes séchés 20 min dans 250 ml d''eau chaude, puis les hacher et filtrer le liquide.","Faire revenir les lardons dans l''huile dans un grand faitout à fond épais à feu moyen jusqu''à ce qu''ils rendent leur gras, puis ajouter le porc et le faire dorer sur toutes les faces 8 min. Ajouter la saucisse les 2 dernières minutes.","Ajouter l''oignon et les champignons frais et cuire 6 à 8 min jusqu''à ce qu''ils soient tendres.","Incorporer le concentré de tomate 1 min, puis ajouter la choucroute, le chou, les cèpes et leur eau, les pruneaux, le vin, le laurier, le piment de la Jamaïque, le carvi et du poivre.","Porter à frémissement, couvrir et cuire à très feu doux 2 h, en remuant de temps en temps et en ajoutant un peu d''eau si ça accroche.","Découvrir les 15 dernières minutes pour faire épaissir. Rectifier l''assaisonnement et servir avec du pain de seigle. C''est encore meilleur réchauffé le lendemain."]},"it":{"title":"Bigos (stufato polacco del cacciatore)","steps":["Mettere in ammollo i porcini secchi in 250 ml di acqua calda per 20 min, poi tritarli e filtrare il liquido.","Rosolare la pancetta nell''olio in una pentola grande dal fondo spesso a fuoco medio finché rilascia il grasso, poi aggiungere il maiale e rosolarlo su tutti i lati per 8 min. Unire la salsiccia negli ultimi 2 min.","Aggiungere la cipolla e i funghi freschi e cuocere 6-8 min finché sono morbidi.","Incorporare il concentrato di pomodoro per 1 min, poi aggiungere i crauti, il cavolo, i porcini con il loro liquido, le prugne, il vino, l''alloro, il pimento, il cumino dei prati e il pepe.","Portare a sobbollire, coprire e cuocere a fuoco bassissimo per 2 h, mescolando ogni tanto e aggiungendo un goccio d''acqua se attacca.","Scoprire negli ultimi 15 min per far addensare. Regolare di sale e servire con pane di segale. Riscaldato il giorno dopo è ancora più buono."]}}'::jsonb),
  ('263af3c6-ef74-4605-91cb-056837b47a7c'::uuid, '{"fr":{"title":"Chkmeruli (poulet géorgien à l''ail)","steps":["Saler et poivrer le poulet. Le poser côté peau dans une grande poêle avec l''huile à feu moyen-vif et l''aplatir avec une casserole lourde ou une assiette.","Cuire 8 à 10 min jusqu''à ce que la peau soit bien dorée et croustillante, puis retourner et cuire encore 4 à 5 min jusqu''à cuisson à cœur. Retirer l''essentiel du gras.","Baisser le feu, ajouter la pâte d''ail autour du poulet et la remuer dans le gras 30 à 60 s sans la laisser colorer.","Verser le lait et la crème, ajouter la coriandre moulue et le piment et laisser mijoter 4 à 5 min en arrosant le poulet de sauce, jusqu''à ce qu''elle épaississe légèrement.","Incorporer le persil, parsemer de coriandre et servir directement dans la poêle avec du pain pour saucer."]},"it":{"title":"Chkmeruli (pollo georgiano all''aglio)","steps":["Salare e pepare il pollo. Disporlo con la pelle verso il basso in una padella grande con l''olio a fuoco medio-alto e schiacciarlo con una pentola pesante o un piatto.","Cuocere 8-10 min finché la pelle è ben dorata e croccante, poi girare e cuocere altri 4-5 min finché è cotto all''interno. Eliminare quasi tutto il grasso.","Abbassare il fuoco, aggiungere la pasta d''aglio intorno al pollo e mescolarla nel grasso per 30-60 s senza farla colorire.","Versare il latte e la panna, aggiungere il coriandolo in polvere e il peperoncino e cuocere 4-5 min, irrorando il pollo con la salsa, finché si addensa leggermente.","Unire il prezzemolo, cospargere di coriandolo e servire direttamente nella padella con pane per fare la scarpetta."]}}'::jsonb),
  ('6c4dd985-1d88-4985-a862-18e27c911a1d'::uuid, '{"fr":{"title":"Carbonnade flamande","steps":["Faire fondre la moitié du beurre dans une cocotte à feu moyen-doux et cuire les oignons à couvert 12 à 15 min jusqu''à ce qu''ils soient fondants et dorés. Ajouter les lardons les 3 dernières minutes, puis tout retirer.","Monter le feu, ajouter le reste du beurre et saisir le bœuf en plusieurs fois, 6 à 8 min en tout, jusqu''à ce qu''il soit bien coloré. Saler et poivrer.","Saupoudrer le bœuf de farine et de cassonade et remuer 1 à 2 min jusqu''à ce que le sucre caramélise.","Remettre les oignons et les lardons, verser la bière, ajouter le bouquet garni et gratter le fond de la cocotte.","Tartiner les tranches de pain d''épices de moutarde et les poser sur le dessus, côté moutarde dessous, sans mélanger.","Couvrir et laisser mijoter à très feu doux 2 h 30 à 3 h, jusqu''à ce que le bœuf soit très tendre et que le pain d''épices ait fondu en une sauce épaisse. Découvrir les 15 dernières minutes si la sauce est trop liquide.","Environ 25 min avant la fin, cuire les pommes de terre 20 min dans de l''eau salée jusqu''à ce qu''elles soient tendres et les égoutter.","Retirer le bouquet garni, ajouter le vinaigre, rectifier l''assaisonnement et servir avec les pommes de terre et le persil."]},"it":{"title":"Carbonade fiamminga (manzo alla birra)","steps":["Sciogliere metà del burro in una casseruola a fuoco medio-basso e cuocere le cipolle coperte per 12-15 min, finché sono morbide e dorate. Unire la pancetta negli ultimi 3 min, poi togliere tutto.","Alzare il fuoco, aggiungere il resto del burro e rosolare il manzo un po'' alla volta, 6-8 min in tutto, finché è ben colorito. Salare e pepare.","Cospargere il manzo con la farina e lo zucchero e mescolare 1-2 min finché lo zucchero caramella.","Rimettere le cipolle e la pancetta, versare la birra, aggiungere il mazzetto aromatico e raschiare il fondo della casseruola.","Spalmare le fette di pan di spezie con la senape e adagiarle sopra, con la senape verso il basso, senza mescolare.","Coprire e cuocere a fuoco bassissimo per 2 h 30 - 3 h, finché il manzo è molto tenero e il pan di spezie si è sciolto in una salsa densa. Scoprire negli ultimi 15 min se la salsa è troppo liquida.","Circa 25 min prima della fine, lessare le patate in acqua salata per 20 min finché sono tenere e scolarle.","Togliere il mazzetto aromatico, unire l''aceto, regolare di sale e servire con le patate e il prezzemolo."]}}'::jsonb),
  ('21256741-4c74-4be1-afeb-973446df94e4'::uuid, '{"fr":{"title":"Waterzooi de poulet","steps":["Faire fondre le beurre dans un grand faitout à feu moyen-doux et faire suer le poireau, les carottes, le céleri et l''oignon 6 à 8 min sans coloration.","Ajouter le bouillon et le bouquet garni, porter à frémissement, puis y plonger le poulet et les pommes de terre.","Pocher doucement, à demi couvert, 20 à 25 min jusqu''à ce que le poulet soit cuit à cœur et les pommes de terre tendres.","Sortir le poulet, le couper en bouchées et le remettre dans le faitout. Retirer le bouquet garni.","Fouetter la crème, le jaune d''œuf et la fécule dans un bol, puis y incorporer une louche de bouillon chaud en fouettant.","Hors ébullition, verser la liaison dans le faitout et chauffer doucement 2 à 3 min en remuant, jusqu''à ce que le bouillon épaississe légèrement. Ne pas faire bouillir.","Assaisonner de sel, de poivre et d''un filet de citron, et servir dans des assiettes creuses avec le persil et la ciboulette."]},"it":{"title":"Waterzooi di pollo","steps":["Sciogliere il burro in una pentola grande a fuoco medio-basso e stufare il porro, le carote, il sedano e la cipolla per 6-8 min senza farli colorire.","Aggiungere il brodo e il mazzetto aromatico, portare a sobbollire, poi immergere il pollo e le patate.","Cuocere dolcemente, semicoperto, per 20-25 min, finché il pollo è cotto all''interno e le patate sono tenere.","Togliere il pollo, tagliarlo a bocconcini e rimetterlo nella pentola. Eliminare il mazzetto aromatico.","Sbattere la panna, il tuorlo e l''amido di mais in una ciotola, poi incorporare un mestolo di brodo caldo.","Fuori dal bollore, versare il composto nella pentola e scaldare dolcemente 2-3 min mescolando, finché il brodo si addensa leggermente. Non far bollire.","Condire con sale, pepe e una spruzzata di limone, e servire in piatti fondi con prezzemolo ed erba cipollina."]}}'::jsonb),
  ('5cad9345-d8b4-438f-a6b8-4f4a657d32ac'::uuid, '{"fr":{"title":"Jambalaya","steps":["Assaisonner le poulet avec la moitié des épices créoles. Le faire dorer dans l''huile dans une cocotte à fond épais à feu moyen-vif 5 à 6 min, puis réserver.","Faire dorer la saucisse dans la même cocotte 3 à 4 min et la réserver avec le poulet.","Cuire l''oignon, le céleri et le poivron dans le gras 5 min jusqu''à ce qu''ils soient tendres, ajouter l''ail 30 s, puis incorporer le concentré de tomate 1 min.","Ajouter les tomates, le bouillon, le reste des épices, le thym et le laurier, gratter le fond et remettre le poulet et la saucisse.","Porter à ébullition, incorporer le riz, puis couvrir et cuire à feu doux 20 min sans remuer.","Répartir les crevettes sur le riz, couvrir à nouveau et cuire 5 à 6 min, jusqu''à ce qu''elles soient roses et le riz tendre.","Laisser reposer 5 min hors du feu, égrener, rectifier l''assaisonnement et servir avec les oignons nouveaux."]},"it":{"title":"Jambalaya","steps":["Condire il pollo con metà delle spezie creole. Rosolarlo nell''olio in una pentola dal fondo spesso a fuoco medio-alto per 5-6 min, poi tenerlo da parte.","Rosolare la salsiccia nella stessa pentola per 3-4 min e metterla da parte con il pollo.","Cuocere la cipolla, il sedano e il peperone nel grasso per 5 min finché sono morbidi, aggiungere l''aglio per 30 s, poi unire il concentrato di pomodoro per 1 min.","Aggiungere i pomodori, il brodo, il resto delle spezie, il timo e l''alloro, raschiare il fondo e rimettere il pollo e la salsiccia.","Portare a bollore, unire il riso, poi coprire e cuocere a fuoco basso 20 min senza mescolare.","Distribuire i gamberi sul riso, coprire di nuovo e cuocere 5-6 min, finché diventano rosa e il riso è tenero.","Lasciare riposare 5 min fuori dal fuoco, sgranare, regolare di sale e servire con i cipollotti."]}}'::jsonb),
  ('751145c3-7b69-4ccb-a0f5-a608ed92d0d8'::uuid, '{"fr":{"title":"Frikadeller, pommes de terre et salade de concombre","steps":["Mettre les pommes de terre dans de l''eau froide salée, porter à ébullition et cuire 15 à 20 min jusqu''à ce qu''elles soient tendres.","Mélanger le vinaigre, le sucre, 1 c. à soupe d''eau et une pincée de sel jusqu''à dissolution et y ajouter le concombre ; laisser mariner.","Mélanger le porc, le veau, l''oignon, l''œuf, la farine, le lait, la muscade, 1 c. à café de sel et du poivre jusqu''à obtenir une farce lisse et collante. Faire cuire une cuillerée pour goûter l''assaisonnement.","Façonner 8 boulettes ovales à l''aide d''une cuillère ou des mains mouillées.","Les faire cuire dans le beurre et l''huile dans une poêle à feu moyen 10 à 12 min en les retournant à mi-cuisson, jusqu''à ce qu''elles soient bien dorées et cuites à cœur.","Égoutter les pommes de terre et les enrober d''un peu du beurre de cuisson et de persil. Servir avec les frikadeller et le concombre égoutté parsemé d''aneth."]},"it":{"title":"Frikadeller con patate e insalata di cetrioli","steps":["Mettere le patate in acqua fredda salata, portare a bollore e cuocere 15-20 min finché sono tenere.","Mescolare l''aceto, lo zucchero, 1 cucchiaio d''acqua e un pizzico di sale finché si sciolgono e unire il cetriolo; lasciare marinare.","Impastare il maiale, il vitello, la cipolla, l''uovo, la farina, il latte, la noce moscata, 1 cucchiaino di sale e il pepe finché l''impasto è liscio e appiccicoso. Cuocerne un cucchiaino per assaggiare il sale.","Formare 8 polpette ovali con un cucchiaio o con le mani bagnate.","Cuocerle nel burro e nell''olio in una padella a fuoco medio per 10-12 min, girandole a metà, finché sono ben dorate e cotte all''interno.","Scolare le patate e condirle con un po'' del burro di cottura e il prezzemolo. Servire con le frikadeller e il cetriolo scolato cosparso di aneto."]}}'::jsonb),
  ('86344908-27c8-4c77-90f7-299d2972fb69'::uuid, '{"fr":{"title":"Plaque de saumon au citron, pommes de terre et haricots verts","steps":["Préchauffer le four à 200 °C. Mélanger les pommes de terre avec 1 c. à soupe d''huile, du sel et du poivre sur une grande plaque et rôtir 20 min.","Mélanger le reste de l''huile avec l''ail, le zeste du citron et la moitié de son jus, la moitié de l''aneth, du sel et du poivre.","Pousser les pommes de terre sur les côtés, ajouter les haricots verts enrobés d''un peu d''huile citronnée et poser le saumon au centre, côté peau dessous.","Napper le saumon du reste de l''huile citronnée et ajouter quelques rondelles de citron.","Rôtir 12 à 15 min, jusqu''à ce que le saumon s''effeuille facilement et que les haricots soient tendres mais encore bien verts.","Parsemer du reste de l''aneth et servir avec des quartiers de citron."]},"it":{"title":"Salmone al limone in teglia con patate e fagiolini","steps":["Scaldare il forno a 200 °C. Condire le patate con 1 cucchiaio d''olio, sale e pepe su una teglia grande e arrostirle 20 min.","Mescolare il resto dell''olio con l''aglio, la scorza del limone e metà del suo succo, metà dell''aneto, sale e pepe.","Spostare le patate ai lati, aggiungere i fagiolini conditi con un po'' dell''olio al limone e mettere il salmone al centro, con la pelle verso il basso.","Versare il resto dell''olio al limone sul salmone e aggiungere qualche fetta di limone.","Arrostire 12-15 min, finché il salmone si sfalda facilmente e i fagiolini sono teneri ma ancora verdi brillanti.","Cospargere con il resto dell''aneto e servire con spicchi di limone."]}}'::jsonb),
  ('d473cbb0-83df-4bdb-bd0c-3fac1f8b2c83'::uuid, '{"fr":{"title":"Omelette aux petits pois, menthe et pommes de terre","steps":["Faire chauffer l''huile dans une poêle antiadhésive de 24 cm allant au four, à feu moyen. Ajouter les rondelles de pomme de terre avec une pincée de sel, couvrir et cuire 10 à 12 min en remuant de temps en temps, jusqu''à ce qu''elles soient tendres et dorées par endroits.","Ajouter les oignons nouveaux et les petits pois surgelés et cuire 2 min à découvert jusqu''à ce que les petits pois soient décongelés.","Allumer le gril du four. Battre les œufs avec la plus grande partie de la menthe, du sel et du poivre.","Verser les œufs dans la poêle, parsemer de feta et cuire à feu moyen-doux 4 à 5 min, en ramenant les bords vers le centre une ou deux fois, jusqu''à ce que le dessous soit pris et doré.","Glisser la poêle sous le gril 2 à 3 min, jusqu''à ce que le dessus soit gonflé et juste pris.","Parsemer du reste de menthe, couper en parts et servir."]},"it":{"title":"Frittata di piselli, menta e patate","steps":["Scaldare l''olio in una padella antiaderente da 24 cm adatta al forno, a fuoco medio. Aggiungere le fette di patata con un pizzico di sale, coprire e cuocere 10-12 min, girandole ogni tanto, finché sono tenere e dorate qua e là.","Aggiungere i cipollotti e i piselli surgelati e cuocere scoperto 2 min finché i piselli sono scongelati.","Accendere il grill del forno. Sbattere le uova con gran parte della menta, sale e pepe.","Versare le uova nella padella, cospargere di feta e cuocere a fuoco medio-basso 4-5 min, riportando i bordi verso il centro una o due volte, finché il fondo è rappreso e dorato.","Passare la padella sotto il grill per 2-3 min, finché la superficie è gonfia e appena rappresa.","Cospargere con la menta rimasta, tagliare a spicchi e servire."]}}'::jsonb),
  ('946f92ac-6411-45df-8501-3e4e1c32c64b'::uuid, '{"fr":{"title":"Burgers de dinde, poivrons rôtis et feta","steps":["Préchauffer le four à 220 °C. Mélanger les lanières de poivron avec 1 c. à soupe d''huile et du sel sur une plaque et rôtir 20 à 25 min, jusqu''à ce qu''elles soient tendres et grillées sur les bords.","Mélanger la dinde avec l''origan, la moitié de l''ail, la chapelure, du sel et du poivre, et façonner 2 steaks d''environ 2 cm d''épaisseur.","Mélanger le yaourt avec le reste de l''ail, un filet de citron et une pincée de sel.","Cuire les steaks dans le reste de l''huile dans une poêle à feu moyen 5 à 6 min de chaque côté, jusqu''à cuisson complète (74 °C à cœur, plus de rose).","Garnir les steaks de feta la dernière minute et couvrir la poêle pour qu''elle ramollisse. Toaster les pains côté mie dans la poêle ou au four.","Garnir les pains de salade, des steaks, des poivrons rôtis et d''une cuillerée de sauce au yaourt."]},"it":{"title":"Burger di tacchino con peperoni arrosto e feta","steps":["Scaldare il forno a 220 °C. Condire le strisce di peperone con 1 cucchiaio d''olio e sale su una teglia e arrostirle 20-25 min, finché sono morbide e abbrustolite ai bordi.","Mescolare il tacchino con l''origano, metà dell''aglio, il pangrattato, sale e pepe, e formare 2 hamburger spessi circa 2 cm.","Mescolare lo yogurt con il resto dell''aglio, una spruzzata di limone e un pizzico di sale.","Cuocere gli hamburger nel resto dell''olio in una padella a fuoco medio 5-6 min per lato, finché sono cotti (74 °C al centro, niente rosa).","Coprire gli hamburger con la feta nell''ultimo minuto e mettere il coperchio perché si ammorbidisca. Tostare i panini dal lato tagliato in padella o in forno.","Farcire i panini con lattuga, hamburger, peperoni arrosto e una cucchiaiata di salsa allo yogurt."]}}'::jsonb),
  ('57241a46-da29-4c3f-93d2-72bf15f30c03'::uuid, '{"fr":{"title":"Poêlée de patate douce, feta et œufs","steps":["Faire chauffer l''huile dans une grande poêle avec couvercle à feu moyen-vif. Ajouter la patate douce et l''oignon avec du sel, couvrir et cuire 8 min en remuant deux fois.","Découvrir et cuire encore 4 à 5 min en remuant de temps en temps, jusqu''à ce que la patate douce soit tendre et dorée sur les bords.","Incorporer l''ail, le paprika et le cumin 1 min, puis ajouter les épinards et un filet de citron et remuer jusqu''à ce qu''ils tombent.","Creuser 4 puits dans la poêlée, casser un œuf dans chacun, assaisonner et répartir la feta autour.","Couvrir et cuire à feu moyen-doux 4 à 5 min, jusqu''à ce que les blancs soient pris et les jaunes encore coulants. Servir avec du piment."]},"it":{"title":"Padellata di patate dolci, feta e uova","steps":["Scaldare l''olio in una padella grande con coperchio a fuoco medio-alto. Aggiungere la patata dolce e la cipolla con il sale, coprire e cuocere 8 min, mescolando due volte.","Scoprire e cuocere altri 4-5 min mescolando ogni tanto, finché la patata dolce è tenera e dorata ai bordi.","Unire l''aglio, la paprika e il cumino per 1 min, poi aggiungere gli spinaci e una spruzzata di limone e mescolare finché appassiscono.","Formare 4 incavi nella padellata, rompere un uovo in ognuno, condire e distribuire la feta intorno.","Coprire e cuocere a fuoco medio-basso 4-5 min, finché gli albumi sono rappresi e i tuorli ancora morbidi. Servire con peperoncino."]}}'::jsonb)
) as v(id, translations)
where (x.id = v.id or (x.copied_from = v.id and x.title = (select s.title from public.recipes s where s.id = v.id)))
  and x.translations is distinct from v.translations;

